INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_01', '分析性思考', 'Analytical Thinking', NULL, '衡量邏輯思考、識別模式、系統性分析資訊以及運用結構化推理解決問題的能力', 'Measures the ability to think logically, identify patterns, analyze information systematically, and approach problems with structured reasoning', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_02', '韌性', 'Resilience1', NULL, '衡量從困難中恢復、處理變化並在困難時期保持情緒堅強的能力。反映情緒強度、靈活性以及在壓力下茁壯成長的能力', 'Measures the capacity to bounce back from difficulties, handle change, and stay emotionally strong during tough times. It reflects emotional strength, flexibility, and the ability to thrive under stress', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_03', '認知彈性', 'Cognitive Flexibility', NULL, '衡量根據新資訊或變化的環境調整思考策略和行為的能力，顯示心理靈活性和問題解決的多樣性', 'Measures the capacity to modify thinking strategies and behaviors in response to new information or changing circumstances, indicating mental flexibility and problem-solving versatility', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_04', '適應敏捷', 'Change Agility', NULL, '衡量快速適應、保持靈活性並對變化的環境、優先事項和期望做出積極回應的能力', 'Measures the ability to adapt quickly, remain flexible, and respond positively to changing environments, priorities, and expectations', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_05', '自主領導', 'Self-Leadership', NULL, '衡量一個人透過目標設定、激勵和個人問責來領導自己的能力', 'Measures a person''s ability to lead themselves through goal-setting, motivation, and personal accountability', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_06', '人際影響力', 'Social Influence', NULL, '衡量說服、啟發和影響他人思想、態度或行為的能力。反映堅定自信、魅力、領導風範和溝通效能', 'Measures the ability to persuade, inspire, and impact others'' thoughts, attitudes, or behaviors. It reflects assertiveness, charisma, leadership presence, and communication effectiveness', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_07', '創造性思考', 'Creative Thinking', NULL, '衡量產生原創想法、發散性思考以及以創新方式應對挑戰的能力', 'Measures the ability to generate original ideas, think divergently, and approach challenges with innovation', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_08', '卓越追求動機', 'Achievement Motivation', NULL, '衡量一個人對卓越表現的驅動力、對技能精通的追求以及對卓越的承諾', 'Measures a person''s drive for exceptional performance, pursuit of skill mastery, and commitment to excellence', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_09', '自我覺察', 'Self-Awareness', NULL, '衡量一個人對自己的情緒、行為、動機以及對他人影響的覺察程度', 'Measures a person''s awareness of their own emotions, behaviors, motivations, and impact on others', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_10', 'AI科技素養', 'AI Literacy', NULL, '衡量理解、使用和批判性評估人工智慧技術的能力', 'Measures the ability to understand, use, and critically assess artificial intelligence technologies', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_11', '同理心', 'Empathy', NULL, '衡量設身處地的能力；並以他人的參考架構去理解或感受他人正在經歷甚麼', 'Measures the capacity to place oneself in the position of another; and to understand or feel what another person is experiencing from within their frame of reference.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_12', '積極傾聽', 'Active Listening', NULL, '衡量專心傾聽、處理資訊並在對話中有效回應的能力', 'Measures the ability to listen attentively, process information, and respond effectively in conversations', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_13', '好奇心', 'Curiosity', NULL, '衡量學習、探索和理解新想法、經驗或資訊的渴望', 'Measures the desire to learn, explore, and understand new ideas, experiences, or information', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_14', '終身學習', 'Lifelong Learning', NULL, '衡量持續追求新知識和技能以促進個人和專業發展的動機', 'Measures the ongoing motivation to pursue new knowledge and skills for personal and professional development throughout life', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_15', '系統性思考', 'Systems Thinking', NULL, '衡量理解和管理複雜系統、模式和相互依存關係的能力', 'Measures the capacity to understand and manage complex systems, patterns, and interdependencies', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_16', '可靠性', 'Dependability', NULL, '衡量一個人的可靠性、一致性和可信度', 'Measures a person''s reliability, consistency, and trustworthiness', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_17', '準確嚴謹度', 'Attention to Detail', NULL, '衡量在完成任務時達到徹底性和準確性的能力', 'Measures the ability to achieve thoroughness and accuracy when accomplishing a task', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_18', '協調溝通', 'Interpersonal Communication', NULL, '衡量基本的溝通能力，如清晰表達、理解他人、回應性互動、自信堅定和有效傾聽', 'Measures essential communication competencies such as clear expression, understanding others, responsive interaction, confident assertiveness, and effective listening', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_19', '協商談判', 'Negotiation Skills', NULL, '衡量一個人在談判情境中的方法、效能和心態', 'Measures a person''s approach, effectiveness, and mindset in negotiation contexts', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_20', '批判性思考', 'Critical Thinking', NULL, '衡量邏輯推理、資訊分析、批判評估和決策判斷能力', 'Measures of logical reasoning, information analysis, critical evaluation, and decision-making judgment', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_21', '社交智商', 'Social Intelligence', NULL, '衡量社會覺察、情境理解和關係管理能力', 'Measures of social awareness, situational understanding, and relationship management', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_22', '高效決策', 'Decision-Making', NULL, '衡量在問題解決、信心、風險分析和果斷性方面的決策效能', 'Measures of decision-making effectiveness in problem-solving, confidence, risk analysis, and decisiveness', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('ANI_23', '社會期望反應', 'Social Desirability', NULL, '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。', 'Evaluates whether individuals are responding truthfully or are misrepresenting their beliefs and distorting their answers in order to portray themselves positively, and earn the approval of others.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_01', '盡責', 'Conscientiousness', NULL, '個人的自制力程度以及把工作做到盡善盡美的慾望。包含成就追求、審慎（深思熟慮）、盡職盡責、衝動控制、條理性、完美主義、自我勝任感、自律。', 'Measures the tendency to be orderly, diligent, responsible to others, self-control and rule abiding. Including Achievement Striving, Deliberation, Dutifulness, Impulse Control, Orderliness, Perfectionism, Self Competence, Self Discipline.', '包含：成就動機、審慎、忠於義務、衝動管理、條理性、完美主義、自我勝任感、自律性');
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_02', '成就動機', 'Achievement Striving', NULL, '衡量一個人對待工作認真的程度、提高工作表現的意願，以及努力達成目標的程度。', 'Measures the extent to which an individual will take their work seriously, improve their performance and strive to accomplish their goals.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_03', '審慎', 'Deliberation', NULL, '評估一個人是否會於行動前審慎思考。', 'Measures the tendency to think carefully before acting.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_04', '義務感', 'Dutifulness', NULL, '衡量一個人有多大程度遵循良知和規範而行。', 'Measures the propensity to honor and uphold commitments to social justice and personal obligations.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_05', '衝動管理', 'Impulse Control', NULL, '衡量一個人為達長期目標，管理自身衝動、情緒和行為的能力。', 'Measures the ability to manage one''s impulses, emotions and behaviors to achieve goals.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_06', '條理性', 'Orderliness', NULL, '衡量對例行程序、審議和細節方向的偏好。', 'Measures the preference for routines, deliberation, and detail-orientation.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_07', '完美主義', 'Perfectionism', NULL, '衡量一個人追求完美和無瑕疵的程度。', 'Measures the perfectionistic tendency; a person''s concern with striving for flawlessness and perfection.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_08', '自我勝任感', 'Self Competence', NULL, '衡量一個人覺得自己是否有能力、有效率且可以掌控局面。', 'Measures the overall sense an individual has being capable, effective and in control.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_09', '自律性', 'Self Discipline', NULL, '衡量延遲滿足、抗拒短期誘惑以實現長期目標的能力。', 'Measures the ability to delay gratification, resisting short-term temptations in order to meet long-term goals.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_10', '誠實謙遜', 'Honesty-Humility', NULL, '評量受訪者在誠懇、公正、避免貪婪及謙虛面向的個人差異。例如在預期目標、利益下是否能維持誠實、公平對待他人，不會過度炫耀或重視財富、社會地位，或視特權為應得權益。', 'Measure of individual differences in sincerity, fairness, greed avoidance and modesty. Including Sincerity, Materialism Avoidance, Fairness, Modesty.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_11', '誠懇', 'Sincerity', NULL, '評量為了達成目標而願意去操縱、欺騙他人的意願。', 'Measure of a person''s (un)willingness to be manipulative or dishonest in their dealings with other people in order to achieve a desired outcome.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_12', '低物質傾向', 'Materialism Avoidance', NULL, '對於財富及地位這類事物的重視程度。', 'Measure of the value a person places on wealth, privileges and high social status.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_13', '公正性', 'Fairness', NULL, '評量為了領先他人是否願意欺騙、偷竊、貪污或利用他人的意願。', 'Measure of (un)willingness to cheat or steal in order to get ahead, as well as people''s tendency to use fraud, be corrupt, or take advantage of others.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_14', '謙虛', 'Modesty', NULL, '評量對於他人與自身關係上的看法。', 'Measures a person''s beliefs about him/herself in relation to others — high scorers see themselves as "no better" than anyone else, whereas low scorers feel they deserve special treatment and more respect than others.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_15', '心理資本', 'Psychological Capital', NULL, '唯一重要正向特質，對態度、行為和表現有積極影響，包含以下四種心理特質：希望、效能、韌性和樂觀情緒。', 'Measures an individual''s psychological resources including Hope (being full of determination), Efficacy (self-reliance while dealing with challenges), Resilience (accomplishment in the face of obstacles) and Optimism (positive expectations for future success).', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_16', '希望', 'Hope', NULL, '對於個人將目標與達成該目標的動機付諸概念化與策略化的能力，其看法為何。', 'Measures an individual''s perception of their capacity to conceptualize and strategize their goals, and their motivation to achieve them.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_17', '目標效能感', 'Efficacy', NULL, '個人對於自己付出努力達成目標的能力有信心的程度。', 'Measure a person''s sense of self-confidence in their ability and capacity to make the required effort to achieve a goal.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_18', '韌性', 'Resilience', NULL, '如何面對壓力或逆境以及降低自身的受損性;包含於衝突、失敗、責任變更(甚或加重)後的挽救的能力。', 'Measures a person''s positive way of coping with stress or adversity and reducing their vulnerability to it; includes the ability to recuperate from conflict, failure, change or even an increase in responsibility.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_19', '樂觀', 'Optimism', NULL, '個人對事物的解讀方式或是看待生活中不如意的方式。高度樂觀者會解釋成不如意只是暫時的，而悲觀者則通常認為這些不如意將會是永久的且無所不在。', 'Measures a person''s disposition or tendency to perceive the favorable side of situations with an expectation of a favorable outcome. People with high optimism explain them as temporary whilst a pessimist often views events as permanent and pervasive.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_20', '創新力', 'Innovativeness', NULL, '用創新的方式做事及發現問題與找出解決方式的慾望;不想受限於既有思考方式以及挑戰主流規則。', 'Measures a person''s desire to do things differently, and discover problems and solutions; preference to think outside the box and challenge prevailing rules. Including Approach to Efficiency, Rule Governance, Sufficiency of Originality.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_21', '效率取向', 'Approach to Efficiency', NULL, '想要變得更精確、更可靠、更有效率的欲望。低分者在解決問題時更加遵循規範、精確且有條理。高分者對繁文縟節不太關心，不喜歡總是按照固定的程序和結構行事，且往往以不同尋常的角度來處理任務。', 'This is the concern for being exact, systematic and disciplined. People who score low are more compliant, precise and methodical in their approach to solving problems. High scorers have little concern with bureaucratic details, dislike following routines and structure all the time, and they tend to approach tasks from unusual angles.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_22', '紀律遵循度', 'Rule Governance', NULL, '反映一個人願意在既定架構內工作或用傳統方式做事的程度。低分者喜歡以既有且被接受的方法來解決問題，他們在存在明確規則的情況下表現最佳。高分者則不依賴於被接受的方法來解決問題，他們更喜歡在沒有既定規則的情境中處理問題。', 'The degree to which an individual works within the accepted structures or doing things in accepted ways. Low scorers like to solve problems with tried and accepted means. They perform best in situations where well-established rules exist. High scorers don''t rely on accepted means to solve problems. They prefer to tackle situations where no rules exist.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_23', '獨創性', 'Sufficiency of Originality', NULL, '發揮其創新性、以另類觀點看待事情及用不同以往的方式做事的意願。高分者經常找出創新方法解決問題，而低分者的想法往往在規範或既定程序內，較少原創性想法。', 'This is the preference of producing a few implementable solutions to problems. High scorers regularly reinvent the wheel; the low scorers offer less original ideas and those ideas tend to lie within present practices and procedures.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_24', '真實性', 'Authenticity', NULL, '衡量個體的行為與其價值觀及欲望的一致性，儘管有著外界的社會從眾壓力，依然保持一致。', 'Measures the degree to which a person''s actions are congruent with his or her values and desires, despite external pressures for social conformity.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_25', '集體意識', 'Collective Orientation', NULL, '衡量對個體間凝聚力重視和強調的程度，以及集體優先於個人的程度。', 'Measure the propensity to work in a collective manner in team settings. High scorers place the needs and interests of the group above their own desires or motivations, whereas low scorers place their own interests ahead of team.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_26', '同理心', 'Empathy', NULL, '衡量設身處地的能力；並以他人的參考架構去理解或感受他人正在經歷甚麼。', 'Measures the capacity to place oneself in the position of another; and to understand or feel what another person is experiencing from within their frame of reference.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_27', '權益公平感', 'Equity Perception', NULL, '是指一個人對付出與回報的在意程度，以此來評測出一個人對職場公平/公正的在意程度。', 'Measures an individual''s preference for workplace equity (fairness) by comparing the effort individuals put into a job and the outcomes or rewards they receive in exchange.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_28', '感謝', 'Gratitude', NULL, '評估個人表達感激的傾象差異。', 'Measures the differences in an individual''s proneness to experience gratitude.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_29', '人際適應力', 'Interpersonal Versatility', NULL, '一個人在多大程度上能夠適應不同類型的人，管理所有人際交往中固有的自然緊張關係，並建立起互利互惠的關係。', 'Measures the extent to which a person can adapt to different types of people, manage the natural tension inherent in social interaction, and build mutually productive relationships.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_30', '個人責任感', 'Personal Accountability', NULL, '衡量個人具備責任感和把事情做好的決心的程度。', 'Measures the extent to which individuals take responsibility and are determined to get things done.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_31', '個人成長動機', 'Personal Growth Initiative', NULL, '評估個人對個人成長的主動性以及參與改變和發展自我的渴望。', 'Assesses an individual''s level of initiative for personal growth; and their desire to be involved in changing and developing oneself. Personal Growth Initiative (PGI) is a future-looking perspective in which individuals believe they will be able to improve themselves.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_32', '心理特權', 'Psychological Entitlement', NULL, '評量其認為應得到特權及特殊待遇的程度，一般不太考慮到其實際能力、努力或績效高低。', 'Measure of a stable and pervasive belief that one deserves preferential rewards and treatment, often with little consideration of one''s actual abilities, effort or performance levels.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_33', '社會期望反應', 'Social Desirability', NULL, '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。', 'Evaluates whether individuals are responding truthfully or are misrepresenting their beliefs and distorting their answers in order to portray themselves positively, and earn the approval of others.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_34', '工作熱忱', 'Work Passion', NULL, '對工作的熱忱程度。', 'Measures the level of passion toward work.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_35', '生活熱情', 'Zest', NULL, '衡量個體在日常工作與生活中，是否傾向以積極、充滿熱情與活力的方式行事，並對未來抱持期待與動能。', 'Measures a person''s habitual approach to work and life with enthusiasm, anticipation, excitement and energy.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CIA_36', '情緒易激度', 'Temper', NULL, '衡量一個人在面對煩惱或挫折時，情緒被激起的容易程度。', 'Measure of the ease of arousal when faced with annoyances or frustrations.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_01', '心理資本', 'Psychological Capital', NULL, '對態度、行為和表現有積極影響的個人發展情況；其特點是存在四種心理資源成分：希望、效能感、韌性和樂觀。', 'Measures an individual''s psychological resources including Hope (being full of determination), Efficacy (self-reliance while dealing with challenges), Resilience (accomplishment in the face of obstacles) and Optimism (positive expectations for future success).', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_02', '希望', 'Hope', NULL, '對於個人將目標與達成該目標的動機付諸概念化與策略化的能力。', 'Measures an individual''s perception of their capacity to conceptualize and strategize their goals, and their motivation to achieve them.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_03', '效能感', 'Efficacy', NULL, '個人對於自己付出努力達成目標的能力有信心的程度。', 'Measure a person''s sense of self-confidence in their ability and capacity to make the required effort to achieve a goal.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_04', '韌性', 'Resilience', NULL, '如何面對壓力或逆境以及降低自身的受損性，包含於衝突、失敗、責任變更(或加重)後的恢復能力。', 'Measures a person''s positive way of coping with stress or adversity and reducing their vulnerability to it; includes the ability to recuperate from conflict, failure, change or even an increase in responsibility.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_05', '樂觀', 'Optimism', NULL, '個人對事物的解讀方式或是看待生活中不如意的方式。高度樂觀者會解釋成不如意只是暫時的，而悲觀者則通常認為這些不如意將會是永久的且無所不在。', 'Measures a person''s disposition or tendency to perceive the favorable side of situations with an expectation of a favorable outcome. People with high optimism explain them as temporary whilst a pessimist often views events as permanent and pervasive.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_06', '工作投入性', 'Job Involvement', NULL, '一個人專注於工作和職位，較不關注生活其他方面的程度。', 'Degree to which a person possesses a singular focus on their job and role rather than other areas of their life.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_07', '職業素養', 'Professionalism', NULL, '傾向於堅持既定的標準，並表現出超越基本要求的水準。', 'Tendency to adhere to set standards and perform at a level in excess of basic requirements.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_08', '反饋尋求', 'Feedback Seeking', NULL, '評量個人尋求績效反饋以協助適應、學習和改進的程度。', 'Measure of the degree to which an individual seeks performance feedback to aid adaptation, learning and improvement.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_09', '權益公平感', 'Equity Perception', NULL, '是指一個人對付出與回報的在意程度，以此來評測出一個人對職場公平 / 公正的在意程度。', 'Measures an individual''s preference for workplace equity (fairness) by comparing the effort individuals put into a job and the outcomes or rewards they receive in exchange.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_10', '精力充沛', 'Liveliness', NULL, '評量過著步調快速與繁忙的生活的傾向，行事快速、積極、有拼勁。', 'Measures the outwardly expressive energy and action.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_11', '可塑性', 'Malleability', NULL, '衡量個人的可塑性，即個人被認為能夠改變其特質、智力和創造力的程度，這對動機、參與和績效有重要影響。', 'Measures an individual''s perceived malleability being the extent to which individuals are seen as able to modify their traits, intelligence and creativity with important consequences for motivation, engagement and performance.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_12', '社會期望反應', 'Social Desirability', NULL, '評估個體是否誠實回答，還是為了塑造樂觀形象和取得他人認可，而歪曲自己的信仰和答案。', 'Evaluates whether individuals are responding truthfully or are misrepresenting their beliefs and distorting their answers in order to portray themselves positively, and earn the approval of others.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_13', 'A型性格', 'Type A Personality', NULL, '行為模式中可明顯看到其進取心、競爭力、掌握狀況、易被激發之敵意以及重視時間的觀念。', 'Measure of a personality characterized by ambitiousness, competitiveness, status-consciousness, easily-aroused hostility and a strong sense of urgency.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_14', '競爭欲望', 'Desire to Compete', NULL, '衡量一個人在每項活動中渴求勝利，掌握所有任務並感到優越的程度。', 'The desire to compete and win or be better than others.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_15', '企圖心', 'Hard-Driving', NULL, '發憤圖強和慾望導向高於一切的傾向。', 'The desire to be driven and goal oriented above all else.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_16', '匆忙/多工性', 'Hurry', NULL, '有種急於想要完成所有工作的迫切欲望，常常同時進行多項任務並注重成果。', 'Measure the extent to which individuals feel chronically hurried and short of time.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_17', '時間壓力', 'Pressed for Time', NULL, '一個人做事傾向持續處於緊迫感中，與時間賽跑，對受延誤耽擱的事沒有耐心。', 'Measures the tendency to act with a constant sense of urgency and impatience with delays.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('SPA_18', '情緒反應', 'Temper', NULL, '衡量面對煩惱或挫折感時的易衝動程度。', 'Measure of the ease of arousal when faced with annoyances or frustrations.', NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_01', '成就動機', 'Achievement Striving', NULL, '衡量一個人對待工作認真的程度、提高工作表現的意願，以及努力達成目標的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_02', '親和性', 'Agreeableness', NULL, '評量個人本質上對人的信賴性、助益性及個性良好與否，以及是否具備熱情與互助的傾向。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_03', '利他行為', 'Altruism', NULL, '評量個人展現無私、自我犧牲、寬大、體貼、禮貌及關心的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_04', '厭倦傾向', 'Boredom Proneness', NULL, '因為對活動或事件缺少投入而感受到無聊的傾向。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_05', '挑戰', 'Challenge', NULL, '衡量一個人是否相信生活的標準與正常模式是變化而非穩定。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_06', '承諾', 'Commitment', NULL, '衡量一個人相信自身興趣與價值觀是真實且重要的，從而使自己能充分融入生活及所處環境的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_07', '法規遵從', 'Compliance', NULL, '評量面對紛爭時的一般回應方式，是否傾向以溫和、合作或聽從的方式解決衝突。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_08', '盡責', 'Conscientiousness', NULL, '個人的自制力程度以及把工作做到盡善盡美的慾望。包含成就追求、審慎（深思熟慮）、盡職盡責、衝動控制、條理性、完美主義、自我勝任感、自律。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_09', '自控力', 'Control', NULL, '衡量一個人相信自己可以影響事情發展的信念與行為的傾向。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_10', '審慎', 'Deliberation', NULL, '評估一個人是否會於行動前審慎思考。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_11', '義務感', 'Dutifulness', NULL, '衡量一個人有多大程度遵循良知和規範而行。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_12', '目標效能感', 'Efficacy', NULL, '個人對於自己付出努力達成目標的能力有信心的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_13', '同理關懷', 'Empathic Concern', NULL, '衡量一個人對他人困境與需求產生同情、憐憫、關懷的傾向。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_14', '公正性', 'Fairness', NULL, '評量為了領先他人是否願意欺騙、偷竊、貪污或利用他人的意願。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_15', '遵循指示', 'Following Instructions', NULL, '衡量遵從指示或服從權威的意願，以及遵守工作場所規定和程序的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_16', '寬恕', 'Forgiveness', NULL, '評量面對欺騙或冒犯時，是否願意放下怨恨並恢復對對方的信任與好感。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_17', '溫和有禮', 'Gentleness', NULL, '衡量個人在與人交往時是否傾向溫和寬容、避免對人做出嚴厲評斷的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_18', '堅毅性', 'Hardiness', NULL, '衡量自身忍受困難條件的能力，以及個人可用來緩衝負面壓力事件影響的內在資源。堅毅由承諾、控制和挑戰三種元素組成。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_19', '誠實謙遜', 'Honesty-Humility', NULL, '評量受訪者在誠懇、公正、避免貪婪及謙虛面向的個人差異。例如在預期目標、利益下是否能維持誠實、公平對待他人，不會過度炫耀或重視財富、社會地位，或視特權為應得權益。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_20', '希望', 'Hope', NULL, '對於個人將目標與達成該目標的動機付諸概念化與策略化的能力，其看法為何。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_21', '衝動管理', 'Impulse Control', NULL, '衡量一個人為達長期目標，管理自身衝動、情緒和行為的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_22', '無法忍受不確定性', 'Intolerance of Uncertainty', NULL, '因為對不確定性形成負面信念而產生的性格傾向，包含面對局勢不定的情況與事件時容易有負面反應。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_23', '低物質傾向', 'Material Avoidance', NULL, '對於財富及地位這類事物的重視程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_24', '謙虛', 'Modesty', NULL, '評量對於他人與自身關係上的看法。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_25', '樂觀', 'Optimism', NULL, '個人對事物的解讀方式或是看待生活中不如意的方式。高度樂觀者會解釋成不如意只是暫時的，而悲觀者則通常認為這些不如意將會是永久的且無所不在。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_26', '條理性', 'Orderliness', NULL, '衡量對例行程序、審議和細節方向的偏好。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_27', '完美主義', 'Perfectionism', NULL, '衡量一個人追求完美和無瑕疵的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_28', '個人責任感', 'Personal Accountability', NULL, '衡量個人具備責任感和把事情做好的決心的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_29', '主動精神', 'Personal Initiative', NULL, '衡量一個人在工作中採取主動積極、自發性開始行動的傾向，以及做超出工作範圍要求的程度。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_30', '心理資本', 'Psychological Capital', NULL, '唯一重要正向特質，對態度、行為和表現有積極影響，包含以下四種心理特質：希望、效能、韌性和樂觀情緒。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_31', '韌性', 'Resilience', NULL, '如何面對壓力或逆境以及降低自身的受損性;包含於衝突、失敗、責任變更(甚或加重)後的挽救的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_32', '自我勝任感', 'Self Competence', NULL, '衡量一個人覺得自己是否有能力、有效率且可以掌控局面。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_33', '自律性', 'Self Discipline', NULL, '衡量延遲滿足、抗拒短期誘惑以實現長期目標的能力。', NULL, NULL);
INSERT INTO trait_definitions (trait_id, name_zh, name_en, dimension, definition, definition_en, hidden_anchor) VALUES ('CSR_34', '誠懇', 'Sincerity', NULL, '評量為了達成目標而願意去操縱、欺騙他人的意願。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (334, 'ANI_01', 'A', 76, 100, '結構清晰', '能穩定運用邏輯與結構化方式拆解問題，辨識關鍵資訊與模式，在複雜或不確定情境下仍能維持分析品質。', '適合承擔問題定義、方案評估與多資訊整合任務。', '表現出穩定的分析性思考，能以邏輯與結構化方式拆解問題、辨識關鍵資訊與模式，面對複雜或不確定情境仍可維持分析品質。', '{"do": ["可用於：①解釋其優勢在「結構化拆解、關鍵訊號辨識、方案比較」②給出任務/角色建議（如問題定義、方案評估、多資訊整合）③提醒仍需用資料/事實驗證結論與假設。"], "dont": ["禁止：①將此特質等同智商、學歷或專業能力高低②保證分析結論一定正確③用貼標/貶抑語氣（如「你就是理工腦」）④推論心理疾病或人格問題。"]}', 'ANI', '你很擅長把複雜問題拆開來看、抓到重點與脈絡；即使情況不太明確，也能整理出清楚的分析方向。', '此區間反映分析歷程的穩定性，不代表結論必然正確。', '', NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (335, 'ANI_01', 'B', 52, 75, '情境分析', '在結構明確或熟悉情境中能有效分析，但在高度模糊或快速變動狀態下需要更多脈絡與引導。', '提供清楚問題框架與資料脈絡，有助於發揮分析能力。', '在情境脈絡較清楚或熟悉時能有效分析與判斷；面對高度模糊或快速變動議題時，較需要補充資訊、問題框架或引導以維持分析效率。', '{"do": ["可用於：①建議先澄清目標/範圍/成功標準②提供框架（輸入-處理-輸出、假設清單、比較表）③說明此區間反映「對情境清晰度的依賴」，並給出提升分析品質的支援做法。"], "dont": ["禁止：①把需要框架解讀為「能力不足」或「不適任」②使用絕對化說法（如「壓力下就完全無法思考」）③將其描述成不負責/不主動④推論任何醫療或心理診斷。"]}', 'ANI', '有清楚目標和資料時，你的分析很到位；如果狀況很模糊或變化太快，先把問題框起來、補齊脈絡，會更順更快。', '此區間反映對情境清晰度的依賴程度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (336, 'ANI_01', 'C', 0, 51, '分析支援', '在資訊複雜或模糊時容易出現焦點分散或結構不足，需要討論、範本或工具協助。', '適合搭配資料整理、拆解模板或團隊共識流程。', '在資訊複雜或模糊時，分析焦點可能較分散，較適合在拆解模板、工具或團隊討論的支援下進行梳理與決策，能更快建立可行的分析結構。', '{"do": ["可用於：①提供具體支撐（拆解模板、問題清單、決策樹、範例）②建議用視覺化整理與共識流程（白板、表格、會議紀錄）③強調「需要支援≠不會思考」，把建議聚焦在如何搭建結構。"], "dont": ["禁止：①說「不會思考/不適合策略」等否定性判斷②把低分當成缺陷或道德評價③推論注意力/心理疾病④要求其在缺乏脈絡與支援下獨立完成高不確定分析。"]}', 'ANI', '當資訊很多又不清楚時，你可能需要先把重點拉回來；用清單/模板或和團隊一起討論，會更快整理出可行方向。', '不代表缺乏思考能力，而是分析過程需要支援。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (337, 'ANI_02', 'A', 76, 100, '壓力調適', '面對挫折與壓力能快速復原並維持穩定表現，較能把困難轉化為調整與學習。', '適合高壓、變動或需要長期推進的任務；可作為穩定軍心的角色配置。', '表現較高韌性傾向，面對壓力、挫折或變動情境時，通常能在合理時間內回復到穩定狀態，並從經驗中整理出調整方向與學習重點。', '{"do": ["可用於：①說明其在「壓力復原、長期任務持續度、情緒穩定度」上的相對優勢②提供適合任務建議，如長期專案、高變動環境或需要安定團隊情緒的角色③提醒仍需安排休息與資源，而非將其視為可以無限加壓的對象。"], "dont": ["禁止：①描述為「不會有壓力」「什麼都壓不垮」等誇大說法②鼓勵在缺乏資源或不合理條件下持續硬撐③以韌性高分作為要求其「犧牲健康或私人生活」的理由④推論任何心理診斷或身心狀態。"]}', 'ANI', '遇到壓力或挫折時，你雖然也會受影響，但通常能在不久之後重新站穩腳步，從中找出下一步要怎麼調整。', '不代表不會感到壓力，而是較能管理與恢復。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (338, 'ANI_02', 'B', 51, 75, '恢復中', '遇到壓力時需要時間調整，通常在獲得支持或釐清方向後能回到穩定狀態。', '安排合理節奏、階段性里程碑與支持資源，有助於維持續航。', '在面對壓力或重大變化時，通常需要一段時間消化與調整；當獲得適當支持、釐清方向與步驟後，多數情況能回到較為穩定的表現並持續前進。', '{"do": ["可用於：①說明其在有支援與清晰方向下，仍具備良好續航與恢復力②建議主管或情境安排，如提供階段性里程碑、情境說明與情緒支持③引導個人覺察「什麼樣的壓力、資源或節奏」有助於自己恢復。"], "dont": ["禁止：①把需要時間調整解讀為「脆弱」「不可靠」②用貶抑或責備語氣描述其反應（例如「太玻璃心」）③推論其適不適合留任或升遷④將一時的狀態當成永久標籤。"]}', 'ANI', '遇到壓力或不確定變化時，你可能需要先花點時間消化、弄清楚狀況，在有人討論或給你方向之後，會比較容易回到穩定步調。', '韌性表現受情境與資源影響，非固定特質。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (339, 'ANI_02', 'C', 0, 50, '能量耗損', '長期高強度或高度不確定環境下，較容易出現情緒耗竭或表現波動。', '避免長期高壓獨撐；可搭配同儕支持、分工與恢復機制。', '在長期高壓、持續不確定或資源不足的情境下，較容易出現能量耗損、情緒起伏或表現不穩，需要在負荷、支持與恢復之間有更刻意的管理與設計。', '{"do": ["可用於：①協助釐清壓力來源與能量消耗模式，並給出具體的恢復與資源使用建議②建議組織在工作量、排程與支援上做調整（如分工、彈性安排、心理安全）③強調這反映的是「能量管理需求」而非價值或意志力問題。"], "dont": ["禁止：①將此解讀為「抗壓性差」「不適任關鍵職位」等負面標籤②鼓勵忽略身心狀態或繼續長期過勞③推論任何身心疾病或使用驚悚語言（如崩潰、撐不住）④把短期表現波動放大為個人缺陷。"]}', 'ANI', '當壓力拉得太長、變化太多或資源不夠時，你可能會很快覺得耗損或疲憊；如果能調整工作節奏、清楚界線並安排恢復時間，狀態會比較好。', '不代表抗壓不足，而是能量管理需求較高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (340, 'ANI_03', 'A', 76, 100, '快速轉換', '能在不同觀點、策略與方法間切換，快速吸收新資訊並調整做法。', '適合跨領域協作、探索性任務或轉型期的快速迭代工作。', '表現較為突出的認知彈性，能在不同觀點、策略或方法之間切換，面對新資訊或情境變化時，較容易調整思考路徑並嘗試替代方案。', '{"do": ["可用於：①說明其在觀點切換、策略調整與跨領域理解上的相對優勢②建議適合投入的任務，例如探索性專案、創新構想討論或轉型期的協作角色③提醒在多方案並行時仍需設立決策標準，避免過度變動方向。"], "dont": ["禁止：①將其描述為「三心二意」「沒定性」②鼓勵在缺乏共識或評估下頻繁變更策略③把認知彈性與「必然創意十足」畫上等號④推論任何注意力或衝動控制問題。"]}', 'ANI', '你很擅長換角度看問題，面對新情況時能很快找到不同做法或新的切入點，而不是只卡在原本的想法裡。', '此區間反映心理切換能力，不等同於執行速度或頻繁改變。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (341, 'ANI_03', 'B', 51, 75, '調整中', '願意接受新方式，但需要時間理解與消化，熟悉後表現會明顯提升。', '提供背景、理由與示範，有助於縮短適應時間並降低摩擦。', '在變化情境下具備一定的調整能力，但較需要先理解背景、理由與可能影響，在釐清之後多數情況能接受新做法並逐步調整自己的運作方式。', '{"do": ["可用於：①說明其屬於「理解後可調整」的型態，適合搭配充分溝通與示範②提供主管或團隊在引入改變時的操作建議（說明脈絡、給範例、設試行期）③鼓勵個人運用小步試驗或先在安全情境中嘗試新方法。"], "dont": ["禁止：①把需要理解過程解讀為「固執」或「抗拒」②用急切或壓迫性語言要求立即改變③忽略其對穩定性與可預期性的合理需求④推斷其不適合任何變革相關任務。"]}', 'ANI', '面對新的做法或改變時，你不會完全排斥，但會需要先弄懂為什麼要這樣做、會影響到什麼；一旦理解之後，通常能慢慢跟上。', '此區間反映轉換需要「理解成本」，不是抗拒。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (342, 'ANI_03', 'C', 0, 50, '思維慣性', '面對改變時傾向維持既有做法，對新方法需要更清楚的必要性與步驟。', '適合變動幅度較小或流程穩定的任務；導入改變時需分段推進。', '在思考方式上較容易維持既有路徑與慣用做法，面對改變時，通常需要更明確的必要性說明、具體步驟與足夠時間，才比較容易嘗試與內化新的方式。', '{"do": ["可用於：①協助釐清其對穩定結構與既有流程的依賴，並建議在導入改變時採取分段、漸進的方式②鼓勵以「小幅試驗」「雙軌並行」來降低不安全感③提醒主管在溝通變革時增加說明、觀察期與回饋機制。"], "dont": ["禁止：①直接貼上「守舊」「抗拒學習」等標籤②忽略其在穩定環境中的價值與貢獻③用威脅或恐嚇的方式推動改變④把這個分數當作衡量學習能力或智力的指標。"]}', 'ANI', '你比較習慣用熟悉的方式做事，遇到改變時，如果知道為什麼要改、怎麼做、會帶來什麼好處，就會比較願意配合和調整。', '不代表不願改變，而是偏好穩定與可預期。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (343, 'ANI_04', 'A', 76, 100, '主動因應', '能快速覺察環境變化並調整優先順序，面對新要求通常能積極回應。', '適合高不確定、節奏快或需頻繁調整資源的情境。', '具備適應敏捷度的明確表現，能較早覺察環境或需求的變化，並主動調整優先順序與資源配置，對新的任務要求通常能以積極、開放的態度面對。', '{"do": ["可用於：①說明其在變動情境下的「主動調整、重新排序、快速起跑」的傾向②建議適合投入在轉型專案、變革推動或需要頻繁調整方向的角色③提醒在反應快速的同時，仍需留意與利害關係人對齊，避免超前過多造成落差。"], "dont": ["禁止：①將其描述為「什麼都接、永遠有彈性」而忽略邊界②鼓勵在資訊不足時貿然大幅改變方向③以此分數合理化過度工作負荷或持續加壓④推論其一定適合所有高變動職務。"]}', 'ANI', '當周遭情況或目標改變時，你通常能很快察覺、調整做事順序，主動尋找新的作法，而不是被動等待指示。', '不等同於衝動行事，仍需搭配決策檢核。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (344, 'ANI_04', 'B', 51, 75, '觀察後行動', '通常在理解變化背景與影響後才投入調整，行動較審慎但可持續。', '先給方向與期望，再給可行選項與期限，有助於加速反應。', '在面對變化時傾向先觀察與理解，再進入行動調整階段；通常在掌握變化的背景、影響與期待後，能做出較穩健且可持續的調整。', '{"do": ["可用於：①強調其「理解後穩健行動」的風格，適合需要權衡利弊與長期影響的情境②建議主管在調整時先說明原因、預期與界線，有助於加快其決策與跟進速度③鼓勵個人在觀察與行動之間抓到平衡，不必過度延後調整。"], "dont": ["禁止：①把先觀察的習慣解讀為「反應慢」「沒企圖心」②在尚未說明清楚前，要求立刻承諾或大幅調整③否定其在穩定推進上的價值④將此分數視為對未來發展潛力的限制。"]}', 'ANI', '遇到變化時，你會先觀察、問清楚來龍去脈，再決定怎麼調整；一旦想清楚之後，行動通常是穩穩往前的。', '此區間反映調整節奏偏穩，不代表反應慢。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (345, 'ANI_04', 'C', 0, 50, '穩定導向', '面對頻繁變動時需要較多適應時間，較依賴既有流程與明確指示。', '適合變動較小或規範明確的環境；變更管理需提供緩衝與支援。', '在變化頻繁或方向多次調整的環境中，較容易感到壓力或不安，會更偏好遵循既有流程、清楚指示與穩定節奏，以維持工作品質與心理安全感。', '{"do": ["可用於：①說明其對穩定性與預期性的需求，並建議在調整時提供足夠的說明、緩衝期與支援②協助設計較固定的作業節奏或明確 SOP，讓其在穩定框架中貢獻③提醒組織在大幅變革時，需特別關注這類成員的溝通與陪伴。"], "dont": ["禁止：①以「抗拒改變」「跟不上時代」等字眼貶低其風格②忽略其在穩定運作、流程維護上的價值③用恐嚇或壓力來逼迫迅速調整④將其描述為不適合任何涉及變化的職務。"]}', 'ANI', '你會比較喜歡有清楚流程和固定節奏的環境；如果變化太多、太快，先有明確說明和一步一步的指引，會讓你比較安心、也比較做得好。', '不代表抗拒改變，而是需要更高的可預期性。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (346, 'ANI_05', 'A', 76, 100, '自我驅動', '能自主設定目標、管理進度並調整行動，對成果與承諾有明確自我要求。', '適合高度自主、遠距或需要自我管理的角色與任務。', '展現明確的自主領導狀態，能主動設定目標、規劃步驟並追蹤進度，對承諾與成果有明確的自我要求，較少需要他人頻繁提醒。', '{"do": ["可用於：①說明其在自我管理、時間規劃與任務推進上的主動性與可靠度②建議適合投入高度自主、遠距或需要自我規劃的任務與角色③提醒組織仍須提供方向對齊與資源支持，而非完全放任自行承擔所有壓力。"], "dont": ["禁止：①把高自主等同於「不需要管理、不需支持」②鼓勵長期過度自我要求而忽略休息與健康③以此作為理所當然加重負荷或指派所有「難搞任務」的理由④推論其人格價值或道德優劣。"]}', 'ANI', '你習慣自己訂目標、自己抓進度，對「說出口要做到」這件事會特別在意，不太需要別人一直盯。', '不等同於不需要回饋；仍需對齊方向與資源。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (347, 'ANI_05', 'B', 51, 75, '框架依賴', '在目標與期待清楚時表現穩定，但較依賴外部節奏與檢核。', '提供階段性目標、優先序與回饋節點，有助於維持動能。', '在目標與期待清楚時，能穩定完成任務並維持一定自我管理，但在缺乏結構或優先順序不明時，較仰賴外部框架與檢核來維持節奏。', '{"do": ["可用於：①說明其適合在有明確目標與節奏設計的情境下發揮穩定表現②建議建立里程碑、檢核點與可視化進度板來支撐自我管理②協助個人學習如何拆解任務與設定自己的節奏，而非單純依賴他人提醒。"], "dont": ["禁止：①將對結構的需求解讀成「不負責任」或「被動」②用批判語氣描述其為「需要人盯」的對象③忽略組織在目標清晰度與任務設計上的責任④推論其不適合承擔任何自主性較高的工作。"]}', 'ANI', '當方向、期限和標準都說清楚時，你可以把事情處理得不錯；如果一切都很模糊，會比較需要有人一起排優先順序、幫忙定節奏。', '此區間反映對外部結構的需求，不代表缺乏責任感。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (348, 'ANI_05', 'C', 0, 50, '外部引導', '需要較明確的指示、節奏與回饋，否則容易分散或延宕。', '適合結構清楚的工作安排；管理上需更明確的分工與追蹤。', '在沒有明確指示、步驟與回饋時，較容易出現分心或延宕，傾向需要清楚的任務拆解、角色分工與追蹤機制，才能較穩定地推進工作。', '{"do": ["可用於：①協助界定其在「需要結構與引導」上的特性，並建議具體管理做法（SOP、任務拆解、固定檢核）②強調這反映的是自我調節需求，而非能力或意願缺乏③鼓勵逐步練習小範圍的自我規劃，以累積自主經驗。"], "dont": ["禁止：①將其標記為「懶惰」「沒有責任感」②忽略環境設計與管理方式對表現的巨大影響③以羞辱或威脅方式要求其「自己想辦法」④推論其不適合任何關鍵任務或長期培養。"]}', 'ANI', '如果事情只說一個大方向、沒有細節和步驟，你可能會比較不知道從哪裡開始；有清楚的分工、待辦清單和回饋時，會比較做得下去。', '不代表不願承擔，而是自我調節需求較高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (349, 'ANI_06', 'A', 76, 100, '自然帶動', '能以溝通、信任與說服影響他人，並能在互動中建立支持與共識。', '適合協調資源、跨部門推進與帶動改變的角色。', '展現高人際影響力，能透過溝通、信任與說服自然帶動他人，容易在團隊中形成意見凝聚或推進變革的關鍵角色。', '{"do": ["可用於：①說明其在建立共識、帶動氣氛與推進跨部門協作上的優勢②建議投入在需要對齊多方利害關係人、推動改變或代表團隊發聲的情境③提醒需注意溝通透明與一致性，避免因影響力大而讓他人感到被壓迫或資訊不對稱。"], "dont": ["禁止：①將其影響力等同於權威或否定他人觀點的正當性②鼓勵以操控、情緒勒索或過度包裝來說服他人③忽略組織在權責設計與決策機制上的界線④把高人際影響力當作必然適合所有管理職的唯一判準。"]}', 'ANI', '你很擅長跟人互動、溝通想法，別人也比較容易因為信任你、被你說服，而願意一起往前走。', '影響力不等同於職權，需注意一致性與透明度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (350, 'ANI_06', 'B', 52, 75, '任務影響', '在職責或專業範圍內具影響力，遇到超出角色邊界時影響力較弱。', '給予清楚角色定位與授權範圍，有助於穩定發揮。', '在人際互動中，在自身職責或專業範圍內具有一定影響力，當角色定位與授權邊界清楚時，能有效說明觀點並帶動相關對象；超出範圍時影響力較受限制。', '{"do": ["可用於：①說明其在人際影響上與「角色清晰度、權責範圍」的連動關係②建議透過清楚賦權與角色說明，提高其在組織內適當發聲的空間③鼓勵在符合職責的前提下，主動提出觀點並練習橫向影響，而非只在被動被詢問時表達。"], "dont": ["禁止：①將其描述為「沒有影響力」「存在感低」②忽略組織結構與文化對其影響表現的限制③以此分數推論其不適合與人合作或不善溝通④要求在完全沒有授權或支持下承擔高度政治性的影響任務。"]}', 'ANI', '在你熟悉或負責的範圍內，你說話的份量和影響力會比較大；但如果是權責之外的事情，會比較看重角色邊界，不一定主動去帶風向。', '此區間反映影響力受情境與權責影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (351, 'ANI_06', 'C', 0, 51, '專業輸出', '影響多來自專業產出而非互動帶動，較少主動推動他人改變。', '適合專注型、個人貢獻或以成果說服的角色配置。', '在人際互動中，影響力多來自專業產出或成果本身，而非主動發起說服或帶動他人，較少在互動中主動推動他人改變或搶佔發言位置。', '{"do": ["可用於：①說明其偏向以專業與成果影響他人，適合在重視品質與貢獻的情境中發揮②建議搭配明確的成果呈現管道（簡報、文件、評估報告），讓其影響力被看見③鼓勵在安全情境下，逐步練習表達觀點與說明思路，而非硬性要求改變風格。"], "dont": ["禁止：①將其標籤為「不擅長人際」「不合群」②要求其立即轉變為高度外向、強勢主導的溝通風格③忽略其在專業深度與穩定輸出上的價值④以此分數推論其不適合任何需要合作或溝通的職務。"]}', 'ANI', '你比較習慣用「把事情做好、把成果做出來」來影響別人，而不是用說服、主導氣氛或去爭取舞台。', '不代表人際能力不足，而是影響管道不同。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (352, 'ANI_07', 'A', 76, 100, '多元發想', '能提出不同觀點與新穎解法，善於跳脫既有框架思考問題。', '適合創新、概念發想與解法探索階段。', '具備創造性思考的突出表現，能從多元角度觀看議題，提出新穎觀點與解法，較容易跳脫既有框架，為問題帶來不同的可能性。', '{"do": ["可用於：①說明其在點子發想、概念設計與問題重新定義上的優勢②建議參與創新專案、策略構想或需要打破慣例的工作階段③提醒仍需搭配可行性評估與落地規畫，避免讓團隊感到變動過多或難以執行。"], "dont": ["禁止：①將「創意多」簡化成「一定好用」或「一定適合所有情境」②以此作為忽略流程、風險或資源限制的藉口③把他人較保守的反應解讀為阻礙或保守者的錯④鼓勵在完全沒有評估下頻繁更換方向。"]}', 'ANI', '你很擅長換角度想事情，常常可以想到別人還沒想到的做法或點子，幫問題打開新的可能。', '不代表想法一定可行，需搭配評估與落地機制。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (353, 'ANI_07', 'B', 51, 75, '改良導向', '能在既有方案上進行優化與調整，創意多來自實務經驗與限制條件。', '提供清楚限制與目標，有助於產出可落地的改良方案。', '在既有框架與實務條件下，擅長對現有方案做調整或優化，創意多與實際需求、限制與經驗結合，傾向尋找「更好但可行」的改良路徑。', '{"do": ["可用於：①說明其創造力偏向「改良與優化」而非完全顛覆式創新②建議投入在流程改善、產品優化或營運調整等需要務實創意的任務③鼓勵與偏概念型創意者合作，由其負責把想法轉化為可落地方案。"], "dont": ["禁止：①把這種風格解讀為「缺乏創意」②要求其在完全沒有參考與以往經驗時，獨立提出大膽顛覆方案③忽略實務限制，期待其產出與A區間相同型態的創新輸出④用分數去否定其在改善與精進上的價值。"]}', 'ANI', '你比較擅長在「原本的做法」上動腦，調整流程、細節或組合，讓事情更順、更有效，而不是完全推翻重來。', '此區間反映創意輸出受情境引導。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (354, 'ANI_07', 'C', 0, 50, '規範取向', '偏好既定流程與標準作法，較少主動提出新構想或冒險嘗試。', '適合高一致性、合規或標準化要求高的任務。', '在思考模式上偏好遵循既定流程與標準作法，較少主動提出新構想或冒險嘗試，更傾向在清楚規則下確保品質與一致性。', '{"do": ["可用於：①說明其在標準化、品質管控與合規要求高的情境中具備穩定優勢②建議投入在需要一致輸出、精準執行或風險敏感度高的任務③鼓勵在安全範圍內，以小步調整或微創新方式逐步擴展彈性。"], "dont": ["禁止：①貼上「沒創意」「保守到不行」等負面標籤②忽略其在穩定營運與風險控管上的重要性③以恐嚇方式要求其頻繁冒險或快速接受高度不確定變化④將此分數視為學習能力或發展潛力的否定。"]}', 'ANI', '你會比較喜歡照規則、依照既有做法把事情做好，而不是常常去試新的路線或大幅改變原本的做法。', '不代表缺乏創意能力，而是輸出優先度較低。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (355, 'ANI_08', 'A', 80, 100, '卓越驅動', '對成果品質與表現標準有高度要求，主動追求突破與精進。', '適合高挑戰、高標準或需要拉高團隊門檻的任務。', '表現明顯卓越追求動機，對成果品質與個人表現標準有較高要求，傾向主動設定具挑戰性的目標並持續投入，以追求突破與精進。', '{"do": ["可用於：①說明其在自我驅動、目標拉高與持續精進上的優勢②建議安排可見成效與成長空間的任務，以善用其高動機③提醒需留意過度完美或目標過高可能帶來的壓力，並協助建立健康的成就觀。"], "dont": ["禁止：①將其視為可以無限加壓、不需照顧的對象②鼓勵以過勞或犧牲私人生活換取成就③用分數合理化不平衡的工作分配④把偶爾狀態下滑解讀為「不夠用力」。"]}', 'ANI', '你對自己的要求通常比較高，會主動拉高標準、訂比較有挑戰性的目標，希望把事情做到更好。', '需留意目標設定是否過高，以免造成壓力累積。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (356, 'ANI_08', 'B', 60, 79, '目標導向', '在目標清楚與回饋機制明確時能穩定投入，動能與里程碑連動。', '設定清楚指標與階段成果，有助於維持節奏與投入。', '在有明確目標與回饋機制時能穩定投入，動機與節奏多與里程碑、成果回饋和外在環境連動，對清楚的期望與進度管理反應較佳。', '{"do": ["可用於：①說明其動機表現與「目標清晰度、回饋頻率」之間的關係②建議透過清楚KPI、階段成果與定期回顧來維持投入度③協助個人學習在目標不夠清楚時，主動澄清與設定自己可控的小目標。"], "dont": ["禁止：①將其描述為「需要人盯才會動」②把所有動機起伏歸咎於個人意志力而忽略目標設計問題③用分數判斷其不適合承擔重要專案④以羞辱方式處理動力下降，而不是檢視系統與情境。"]}', 'ANI', '當目標、指標和回饋都清楚時，你會比較有動力，也比較知道該怎麼調整步伐往前走。', '此區間反映動機受目標清晰度影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (357, 'ANI_08', 'C', 0, 59, '需求回應', '能完成基本要求，但較少主動追求更高標準或自我加碼。', '適合職責明確、節奏穩定的工作安排。', '在滿足基本要求與完成指定任務方面能維持一定水準，但較少主動追求更高標準或額外挑戰，動機多與外在要求、制度或環境壓力連動。', '{"do": ["可用於：①說明其傾向以「達成既定要求」為主要目標，適合在職責明確、流程穩定的情境下工作②建議透過清楚說明升遷、獎酬或成長機會，逐步建立內在動機連結③鼓勵探索個人有興趣的領域，從小範圍開始嘗試更高標準的挑戰。"], "dont": ["禁止：①將其標籤為「不上進」「沒企圖心」②忽略組織在激勵設計、職涯路徑與文化上的影響③以比較或羞辱方式逼迫其追求高標準④推論其未來必然缺乏成長或貢獻。"]}', 'ANI', '你可以把交辦的事情做完，但不一定會特別想要「再多做一點」或自動把標準拉得很高，通常會看公司的要求或情況再決定。', '不代表缺乏能力，而是驅動來源較偏外在要求。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (358, 'ANI_09', 'A', 76, 100, '自我覺察', '能清楚覺察自身情緒與行為模式，理解其對他人與結果的影響並能調整。', '適合需要反思、回饋吸收與自我調節的角色。', '有高自我覺察，能較清楚地察覺自身情緒、想法與行為模式，理解其對他人與結果的影響，並較有能力在需要時調整表現與互動方式。', '{"do": ["可用於：①說明其在情緒管理、反思與行為調整上的潛在優勢②建議投入需要回饋吸收、角色榜樣或教練性質較強的工作脈絡③提醒高覺察不代表永遠狀態穩定，也需要適當支持與休息。"], "dont": ["禁止：①將高自我覺察解讀為「不會情緒失衡」或「不需要支持」②要求其在任何情境下都必須完美調整自己③利用其覺察能力作為加重情緒與責任負擔的理由④推論其必然適合所有輔導或教練角色。"]}', 'ANI', '你通常看得出來自己現在在想什麼、感受如何，也大概知道這樣的狀態會怎麼影響別人，必要時會調整自己的說話或做事方式。', '高分代表覺察能力，不等同於情緒永遠穩定。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (359, 'ANI_09', 'B', 51, 75, '情境覺察', '在特定情境或他人提醒下能察覺自身狀態，但不一定隨時保持反思。', '透過回饋節點與引導提問，可提升自我調節表現。', '在特定情境、他人回饋或事件觸發下，能察覺自己的情緒與反應，但不一定隨時保持自動反思模式，較需要外界提示或停頓空間來整理。', '{"do": ["可用於：①說明其覺察多與「情境與他人回饋」連動，可透過定期檢視與對話提升自我調節②建議設計反思節點（如1對1談話、檢討會、個人筆記）來協助整理經驗③鼓勵主動提問與尋求回饋，逐步拉高平時的自我覺察頻率。"], "dont": ["禁止：①將此區間解讀為「不懂反省」②在缺乏具體例證時指責其「沒自覺」③忽略組織提供回饋文化與心理安全的重要性④用片面事件下的反應直接貼上長期標籤。"]}', 'ANI', '當有人提醒你、或事情有點卡住時，你會開始回頭想「是不是自己哪裡有影響？」但平常不一定會一直處在自我檢視狀態。', '此區間反映覺察啟動條件，非能力不足。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (360, 'ANI_09', 'C', 0, 50, '覺察較少', '較少主動覺察自身狀態或對他人的影響，需要更具體的回饋才會調整。', '適合搭配明確行為指引、即時回饋與檢核機制。', '在日常情境中較少主動檢視自身情緒、行為或其對他人的影響，通常需要較具體、明確的回饋或事件，才會啟動覺察與調整的過程。', '{"do": ["可用於：①說明其在覺察啟動上較仰賴外部回饋與具體事件②建議主管或同事提供明確、具體且建設性的回饋，而非抽象評價③協助設計簡單的自我檢核工具或提問，引導其在重要時刻多一點停頓與思考。"], "dont": ["禁止：①將其定義為「完全沒有自覺」「不會成長」②以指責或羞辱方式提供回饋，造成防衛而非學習③忽略組織在回饋品質與文化上的責任④過度解讀單次行為為固定且不可改變的特質。"]}', 'ANI', '你平常不一定會一直想「我剛剛的反應怎麼樣」，但如果有人具體跟你說明、或事情影響比較大，你會開始注意並思考要不要調整。', '不代表不願改進，而是自發覺察頻率較低。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (361, 'ANI_10', 'A', 76, 100, '應用理解', '能理解 AI 概念、應用情境與限制，並能評估實務價值與風險。', '適合參與數位轉型、工具導入與流程再設計。', '具備較成熟AI 科技素養，能理解 AI 的核心概念、常見應用情境與限制，並在實務中評估其帶來的價值與風險，協助組織做出較穩健的導入決策。', '{"do": ["可用於：①說明其在 AI 概念理解、應用評估與風險意識上的相對優勢②建議投入在數位轉型、工具選型或流程再設計等需要判斷 AI 適用性的任務③提醒 AI 能力主要聚焦在「理解與應用判斷」，並非代表具備模型開發或工程實作能力。"], "dont": ["禁止：①將其 AI 素養等同於「可以獨立開發模型或架構系統」②以高分作為安排不合理技術責任或額外隱性工作負擔的理由③用「你最懂 AI，所以錯都是你」這類方式推卸組織決策責任④把 AI 素養與個人整體價值或智力高低直接畫上等號。"]}', 'ANI', '你對 AI 的基本原理、能做什麼／不能做什麼有一定掌握，也大致看得出來哪裡適合用、可能會踩雷的地方。', '不等同於具備模型開發能力。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (362, 'ANI_10', 'B', 51, 75, '使用導向', '能操作 AI 工具並產生產出，但策略性理解與風險判讀仍需引導。', '提供實例、最佳實務與使用邊界，有助於深化理解。', '在 AI 工具使用上已有一定經驗，能操作並產出成果，但對於更深一層的原理、策略性應用與風險判斷，仍較需要具體案例與引導說明。', '{"do": ["可用於：①說明其目前重點在「實際使用」而非完整策略思維，適合透過工作坊、範例與最佳實務來深化②建議提供清楚的使用邊界、隱私與安全指引，幫助其把既有經驗轉成更穩健的判斷③鼓勵在實務中逐步累積「什麼場合適合用／不適合用」的經驗，而不是只看工具方便與否。"], "dont": ["禁止：①把此區間解讀為「只會亂玩工具」②忽視組織在教育訓練與治理框架上的責任，將所有誤用風險全丟給個人③以是否熟悉最新工具作為對其工作價值的單一評斷④用恐嚇式說法（例如「不會用 AI 就會被淘汰」）施壓。"]}', 'ANI', '你會用一些 AI 工具，也知道大概能幫上什麼忙，但在更進一步評估限制、風險或長期影響時，會需要再多一點示範與說明。', '此區間反映經驗累積中，非缺乏能力。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (363, 'ANI_10', 'C', 0, 50, '起步階段', '對 AI 概念與應用仍在熟悉階段，需要具體示範與情境說明。', '適合循序導入；先從低風險工具與任務開始。', '目前仍在熟悉 AI 相關概念與應用的初始階段，對名詞與工具可能感到陌生或零散，需要透過具體示範、情境案例與循序練習，逐步建立基本理解與信心。', '{"do": ["可用於：①說明其處在「基礎建立期」，適合先從低風險、操作簡單的工具與具體情境開始②建議提供循序漸進的教學、練習任務與問答機會，讓其在安全環境中探索③強調這不代表抗拒或跟不上，而是需要時間與合適資源來累積經驗。"], "dont": ["禁止：①把此區間標籤為「不懂科技」「抗拒改變」②在沒有給予足夠資源與示範前，就以成效不彰作為責備依據③用貶抑語氣嘲諷其數位能力或世代差異④推論其未來無法適應數位轉型或缺乏學習能力。"]}', 'ANI', '現在你對 AI 的感覺比較像「還在摸索」，很多名詞或應用聽過但不一定很熟，需要有人示範、一起試著用幾次，會比較知道怎麼上手。', '不代表抗拒，而是基礎理解仍在建立。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (364, 'ANI_11', 'A', 76, 100, '情感理解', '能從他人立場理解情緒與需求，並在互動中做出適切回應。', '適合需要人際敏感度、團隊支持或客戶互動的角色。', '表現出高度同理心，能從他人角度感受情緒與需求，並在互動中給出適當回應，有助於建立信任關係與支持性的合作氛圍。', '{"do": ["可用於：①說明其在人際敏感度、情緒辨識與關係修復上的優勢②建議投入在需要照顧他人感受、維繫團隊氣氛或大量對外互動的角色（例如客服、顧問、管理者）③提醒同理心仍需要搭配界線與判斷，避免過度承擔他人情緒或犧牲自身需求。"], "dont": ["禁止：①把高同理視為「一定要隨時配合他人」②鼓勵為了維持關係而壓抑合理界線或專業判斷③在衝突發生時，要求其單方面扮演「情緒垃圾桶」的角色④將其同理能力當成理所當然的情緒勞務，而缺乏相對應支持。"]}', 'ANI', '你很能站在別人的立場想事情，也感受得到對方的情緒，通常會用對方可以接受的方式回應與支持。', '同理不等於迎合，仍需搭配界線與判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (365, 'ANI_11', 'B', 51, 75, '理性同理', '能理解他人觀點與處境，但情感回應較偏理性與務實。', '在專業導向或任務型合作中表現穩定。', '在理解他人觀點與處境上具備一定能力，能理性掌握對方立場與需求，但情緒回應較偏務實與就事論事，較少表現強烈的情感回應。', '{"do": ["可用於：①點出其同理風格偏向「理解與協助解決」而非強烈情感投入②建議運用在專業導向或任務型合作情境，如專案協作、問題分析等③鼓勵在需要情緒支持的情境中，多用一句確認感受或簡短回應情緒，再進入解決方案。"], "dont": ["禁止：①將此區間解讀為「冷淡」「沒溫度」②在需要實務決策時，反而過度要求情緒性回應而忽略其理性優勢③以單一互動片段判斷其是否「有同理心」④把所有關係維護責任交給其承擔。"]}', 'ANI', '你聽得懂、也大致理解別人在想什麼、遇到什麼狀況，不過你的反應會比較偏向「就事論事」和幫忙想辦法，而不是很多情緒上的陪伴。', '此區間偏向「理解」，不代表冷漠。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (366, 'ANI_11', 'C', 0, 50, '互動距離', '較少主動感受或回應他人情緒，互動多以任務完成為主。', '適合互動需求較低或分工明確的工作型態。', '在人際互動時較少自然而然地連結到他人的情緒狀態，對感受的敏感度較低，互動重心多放在任務完成、資訊交換或角色職責上。', '{"do": ["可用於：①說明其人際風格偏任務導向，適合在角色分工清楚、情緒需求較低的工作情境②建議透過簡單的提問（例如「這樣你覺得還可以嗎？」）來補上基本的情緒確認③提醒組織在需要高情緒勞務的職位上，應評估是否安排足夠訓練或支援，而非單靠個人自行摸索。"], "dont": ["禁止：①直接貼上「沒同理心」「不在乎別人」等標籤②用道德批判的角度要求其改變，而不提供具體練習與範例③忽略其在穩定、務實與結果導向情境中的價值④將此分數視為無法改善的固定人格缺陷。"]}', 'ANI', '你在和人互動時，比較會專注在事情本身、流程或結果上，不一定會第一時間注意到對方的情緒變化。', '不代表缺乏善意，而是情緒敏感度較低。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (367, 'ANI_12', 'A', 76, 100, '專注回應', '能專注理解對方內容與意圖，並透過提問與回饋確認關鍵資訊。', '適合面談、需求釐清、協調與衝突化解情境。', '在積極傾聽上表現成熟，能維持高度專注，不打斷對方發言，透過複述、總結與適當提問確認理解，同時留意語氣與非語言訊息，接住對方情緒並給予有建設性的回應。', '{"do": ["可用於：①說明其具備接近「積極同理心傾聽／諮詢式傾聽」的能力，在面談、輔導、顧問或協調情境中是重要資源②建議運用複述、開放式提問與總結，協助對方釐清情緒與需求③鼓勵在給建議前先確認「對方想被聽見的是什麼」，讓回應更貼近對方關注點。"], "dont": ["禁止：①將其傾聽能力視為理所當然的情緒勞務，過度仰賴其處理他人情緒而忽略自身負荷②要求在所有情境下都以高強度情感投入回應③將其描繪成「一定能解決所有他人問題」或做心理治療式承諾④以此分數推論具備專業諮商／治療資格。"]}', 'ANI', '你會很認真把對方講完，不會急著插話或下結論，會用「所以你的意思是…」這類方式確認自己有聽懂，也會觀察對方的情緒，再決定要怎麼回應。', '高分反映互動品質，不等同於順從或話少。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (368, 'ANI_12', 'B', 51, 75, '任務傾聽', '在目標明確時能有效傾聽，但在多工或高壓下易出現分心或漏聽。', '用會議結構、重點提示與摘要確認可提升表現。', '在傾聽過程中能維持一定專注，對重要內容與關鍵訊息有不錯掌握；在關係較重要或議題較敏感時，會有意識地多問幾句、確認自己有聽懂，但在其他時候，尤其多工或壓力較大時，較容易回到偏「選擇性傾聽」。', '{"do": ["可用於：①說明其具備從「選擇性傾聽」往「積極同理心傾聽」移動的能力，差別多在情境與心力分配②建議在關鍵溝通時刻刻意關閉干擾、放慢節奏，用複述與簡短總結提高理解深度③鼓勵透過練習開放式提問與情緒確認（如「聽起來你有點…？」）來提升同理層次。"], "dont": ["禁止：①把在高壓或分心情境下的表現簡化為「你不願意聽」②忽視工作環境中的多工要求與資訊轟炸，單純用態度來解讀傾聽品質③以單一互動情境貼上「不會傾聽」的長期標籤④要求其在所有場景都維持高強度傾聽而不考量負荷。"]}', 'ANI', '當情境重要、你在意對方時，你會比較專心聽，也會用追問或重複重點來確認理解；但若同時在忙其他事，或資訊很多時，可能就只會先抓住自己覺得重點的那一部分。', '此區間反映傾聽品質受情境影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (369, 'ANI_12', 'C', 0, 50, '資訊遺漏', '容易錯過細節或誤解對方重點，需要更頻繁的確認與書面化。', '適合搭配紀錄、摘要與確認流程降低落差。', '在對話中較容易落在「選擇性傾聽」或表面回應的模式，可能只接收到自己感興趣或立刻有關的部分，較少主動複述、總結或確認對方真正的感受與需求。', '{"do": ["可用於：①指出其目前傾聽多停在「聽到部分內容」的層次，適合透過簡單技巧（如多問一句、多重述一句）逐步往積極傾聽靠近②建議在重要對話中刻意放慢回應，不急著表達立場，先確認「我剛剛聽到的是…對嗎？」③鼓勵觀察語氣與表情等非語言訊號，幫助自己看見內容背後的情緒與需求。"], "dont": ["禁止：①將此區間直接標記為「不在乎別人」「完全不會聽」②用道德批判或羞辱的方式要求改變傾聽方式③忽略組織文化、會議節奏與發言空間設計對傾聽行為的影響④據此推斷其不適合所有與人互動或服務相關職務。"]}', 'ANI', '你在聊天或開會時，容易先注意到自己在意的那一段，對於其他內容或對方背後的感受，不一定會特別停下來確認，有時會讓對方覺得「好像被部分聽到，但不完全」。', '不代表不在意，而是注意力分配需要支援。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (370, 'ANI_13', 'A', 78, 100, '主動探索', '對新知與新情境保持高度興趣，主動發問、嘗試並擴展理解。', '適合創新、學習、研究與實驗性任務。', '在好奇心上表現強烈，對新知、新情境與不同觀點保持高度興趣，會主動發問、查資料與嘗試新作法，傾向持續拓展自己的理解範圍。', '{"do": ["可用於：①說明其在探索、研究與創新情境中的優勢，適合參與新題目或實驗性任務②建議搭配聚焦與優先順序設定，避免能量分散在過多議題③鼓勵將好奇心延伸到「如何落地」與「如何創造實際價值」，讓探索成果更容易被應用。"], "dont": ["禁止：①將高度好奇視為理所當然，卻不提供時間與空間來探索②忽略其探索需要，僅要求執行重複、單調的任務③把「還在探索」詮釋為「不穩定」或「不務實」④期待其對每個主題都同樣投入，忽視個人興趣差異。"]}', 'ANI', '你對很多新東西都會想「這是怎麼回事？」會主動找資訊、問問題或試試看，不太只滿足於現有的做法。', '不等同於立即產出成果，需搭配聚焦與落地。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (371, 'ANI_13', 'B', 56, 77, '回應式探索', '在需求或引導下能展現探索動機，問題越清楚越容易投入。', '提供明確問題與探索方向，有助於啟動好奇。', '在已有需求、清楚問題或外在引導下，能展現一定程度的探索動機，對與工作或生活相關的議題會主動多問一點，但較少對完全無關的主題投入大量精力。', '{"do": ["可用於：①說明其好奇心較偏向「情境觸發型」，在相關性高或問題清楚時較易啟動②建議在任務設計上清楚說明探索的目的與可能收穫，有助於提升參與度③鼓勵個人針對有興趣或與發展相關的領域，設定小型探索目標，而非被動等待外在刺激。"], "dont": ["禁止：①把此區間解讀為「缺乏好奇心」②在任務缺乏意義感時，單純以壓力或命令要求其投入探索③忽略工作設計與回饋對探索動機的影響④用分數作為評論其人格開放度或價值的依據。"]}', 'ANI', '如果有明確的問題、任務或有人邀請你一起討論，你會願意多了解一些；但不一定會對所有新東西都主動鑽研。', '此區間反映動機受情境觸發。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (372, 'ANI_13', 'C', 0, 55, '焦點保守', '偏好既有知識範圍，較少主動延伸探索或嘗試新作法。', '適合穩定、重複性或標準化程度高的任務。', '在學習與工作中傾向聚焦在已知領域與熟悉作法，對額外探索新主題或新工具的優先度較低，較偏好在穩定框架中持續精進既有能力。', '{"do": ["可用於：①說明其在穩定、標準化或重複性較高的任務中，能以既有經驗維持品質②建議透過小幅度、低風險的探索（例如每次多嘗試一個不同做法）來逐步擴展彈性③強調此分數反映的是探索優先順序，而非學習能力或意願的否定。"], "dont": ["禁止：①貼上「沒好奇心」「不求進步」等標籤②忽視其在穩定執行與知識深化上的價值③要求在缺乏支持與說明下，快速接受大量變化或新工具④將此結果解讀為未來無法成長或轉型。"]}', 'ANI', '你比較習慣把心力放在已經熟悉的事情上，會希望先把這些做穩、做好，而不是同時跑去摸太多新的題目。', '不代表排斥學習，而是探索優先度較低。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (373, 'ANI_14', 'A', 81, 100, '持續投入', '主動規劃並投入長期學習與技能更新，能自我驅動累積新能力。', '適合快速演進的職能環境與需要持續升級的角色。', '在終身學習動機上表現積極，會主動規劃學習路徑與資源，持續更新知識與技能，並尋找應用機會，讓學習能回饋到工作與個人發展。', '{"do": ["可用於：①說明其在長期學習與自我成長上的驅動力，適合投入在變化快速、需要持續升級的角色②建議提供清楚的發展路徑與舞台，讓其看得到學習如何轉化為實際機會③提醒高學習動機不一定等於成果立刻可見，仍需在選題與聚焦上給予支持。"], "dont": ["禁止：①把高學習意願視為可以無限加派新任務與責任的理由②忽略其在時間與精力上的限制，期待「什麼都學、什麼都懂」③用學習熱度作為衡量其全部價值的唯一指標④將所有培訓與知識更新的責任完全轉嫁給個人。"]}', 'ANI', '你很在意自己不要停在原地，會主動找課程、資料或練習機會，讓自己一直有在進步與更新。', '反映學習動機，不代表學習成果一定更好。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (374, 'ANI_14', 'B', 61, 80, '需求導向', '在工作或角色需求出現時投入學習，學習節奏與外在需求連動。', '設定明確目標與應用場景，有助於提升成效。', '在有明確需求、角色轉換或環境變化時，會投入學習來補足所需能力，學習節奏多與工作要求或外在機會緊密連動。', '{"do": ["可用於：①說明其學習傾向偏向「需求驅動型」，在看到用途與必要性時較易啟動②建議在制度上清楚連結學習與角色發展、績效或機會，以提升學習誘因③鼓勵在需求出現前，針對關鍵能力預做一些基本鋪陳，以降低未來壓力。"], "dont": ["禁止：①將此區間簡化為「不愛學習」②在沒有說明學習意義與用途的情況下，只要求完成訓練時數③忽略組織在設計學習機會與發展路徑上的責任④以分數評斷其未來發展上限。"]}', 'ANI', '當工作有新要求、或你看到某個能力真的會影響到成果時，你會開始找資料或學習，但平常不一定會主動去多學很多東西。', '此區間反映學習以「需要」為驅動。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (375, 'ANI_14', 'C', 0, 60, '維持現況', '較少主動追求新技能，偏好以既有能力完成任務。', '適合技能穩定、變動較少的角色。', '在現階段較傾向以既有知識與技能應對工作需求，較少主動投入長期或額外的學習計畫，更偏好在熟悉範圍內維持穩定表現。', '{"do": ["可用於：①說明其目前重點在穩定運作與運用既有能力，適合在變動較低、技能要求較固定的情境②建議透過短小、明確且與現有工作高度相關的學習活動，降低進入門檻③強調此分數代表學習投入的優先順序，而不是否定其學習能力或未來發展可能。"], "dont": ["禁止：①貼上「不思長進」「不上進」等價值評斷②忽略組織在提供有吸引力的學習資源與清楚發展誘因上的角色③以比較或羞辱方式強迫參與學習，導致更高抗拒④用這個結果斷言其無法成長或不適合被培養。"]}', 'ANI', '你會比較偏向「用現在會的東西，把工作做好就好」，不一定會主動去規劃很多新的學習或進修。', '不代表無學習能力，而是投入動機較低。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (376, 'ANI_15', 'A', 76, 100, '整體連結', '能理解系統間相互影響，從整體角度看問題並預判連動效果。', '適合流程設計、跨部門協作與複雜議題盤點。', '在系統性思考上表現突出，能從整體結構與關聯角度審視議題，預先意識到一項決策對不同環節可能產生的連動影響。', '{"do": ["可用於：①說明其在跨流程、跨部門或長期議題盤點上的優勢②建議投入於需要整體規劃、政策設計或路徑模擬的任務③提醒仍需搭配細節檢核，避免只停留在概念層次。"], "dont": ["禁止：①將其解讀為一定精通所有專業細節②僅因具整體觀就期待其獨自承擔複雜變革所有決策③以此作為忽略現場實務限制或基層聲音的理由④推論其必然適合所有策略職位。"]}', 'ANI', '你不太只看單一點，而是會一起想：「這樣改會影響到哪些人、哪些流程？」所以在看事情時視野會比較全。', '強調關聯理解，不等同於細節操作能力。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (552, 'SPA_14', 'C', 0, 30, '較少求勝驅動', '對競爭與排名的興奮度較低，更重視穩定表現或關係品質；不一定追求壓倒性勝利。', '適合顧問式銷售、客戶信任建立與長期服務；用客戶成功與品質指標替代單純排名。', '對排名與勝負的興奮度相對低，更重視穩定表現與關係品質；在顧問式、信任建立與長期服務情境中，往往能持續產出，但不一定被「比賽」激起動能。', '{"do": ["用「客戶成功／續約／滿意度」等指標取代純排名；給長線耕耘任務與清楚期程；把成就回饋做得具體可見"], "dont": ["不要用高壓競賽逼動能；不要把不愛競爭解讀成沒企圖；不要用羞辱式比較刺激，容易反效果"]}', 'SPA', '你不太靠「拚第一」來充電，比較在意把客戶照顧好、把事情做穩；用客戶成功或品質指標，你會更有感。', '低分不等於沒企圖，可能是不喜歡零和競爭；需用適配的激勵方式。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (377, 'ANI_15', 'B', 51, 75, '局部整合', '能掌握主要關聯，但遇到高度複雜系統時需要視覺化或說明輔助。', '用流程圖、關聯圖與假設檢核可提升整體掌握。', '在系統性思考上具備一定能力，能掌握主要關聯與脈絡，但面對高度複雜或資訊龐大的議題時，較需要透過視覺化工具或結構化說明輔助整理全貌。', '{"do": ["可用於：①說明其在有框架、有圖像輔助時能有效理解系統運作②建議透過流程圖、關聯圖與假設檢核表來支援思考③鼓勵在面對複雜問題時，先主動要求或自己建立整體圖像再往下分析。"], "dont": ["禁止：①把對工具與說明的需求視為理解力不足②在資訊高度破碎情境下，仍期待其快速做出全面判斷③以單次混亂經驗評斷其不適合處理複雜議題④用貶抑方式形容其為「只懂一點皮毛」。"]}', 'ANI', '在一般情況下，你看得出事情之間的大關聯；如果牽涉單位太多、資訊太雜，只要有人幫忙畫圖、整理架構，你就能比較快釐清。', '此區間反映對透明度與工具的依賴。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (378, 'ANI_15', 'C', 0, 50, '單點聚焦', '思考多集中於單一面向，較少主動考慮系統連動與外溢影響。', '適合職責明確、界線清楚的任務配置。', '目前在系統性思考上較偏向聚焦單一面向或眼前任務，較少自然而然地延伸思考決策對其他環節或長期影響。', '{"do": ["可用於：①指出其適合在職責清楚、分工明確的任務中專注執行②建議在關鍵決策前，安排與其他相關角色的討論或檢查清單，協助看見外溢影響③鼓勵逐步練習從「這一點」往外多問一兩層，而非一次要求全面系統掌握。"], "dont": ["禁止：①將此區間解讀為「眼光短淺」或「只顧自己」②忽略組織在資訊透明度與跨部門協作設計上的責任③以羞辱方式要求其立即具備高階策略視野④把此結果當作否定其參與重要專案的理由。"]}', 'ANI', '你會比較專心處理手上的那一塊，不一定會第一時間去想「這件事會怎麼影響到其他單位或後續流程」，如果有人提醒或一起討論，會比較容易連起來。', '不代表理解不足，而是視角較集中。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (379, 'ANI_16', 'A', 76, 100, '高度可靠', '能穩定兌現承諾，產出與行為高度可預期，團隊信任成本低。', '適合關鍵流程、交付責任與長期任務配置。', '在可靠性上表現穩定，能一貫地兌現承諾、如期完成交付，讓他人對其時間感與責任感有高度信任。', '{"do": ["可用於：①說明其在長期任務、關鍵流程與客戶承諾上的信賴度優勢②建議擔任需要穩定交付與承諾管理的角色③提醒組織避免因可靠而持續加重其負荷，並留意資源與界線。"], "dont": ["禁止：①將其視為可以無限加派任務的對象②在整體流程設計不良時，把所有延誤責任歸於個人③忽略其休息與支持需求，以「你一向很可靠」要求超額付出④推論其可靠性等同於高效率或高產出。"]}', 'ANI', '你說到的事情，多半都能確實做到，時間與品質也相對穩定，別人會覺得把事情交給你是放心的。', '不等同於高效率，重點在一致性與可信度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (380, 'ANI_16', 'B', 51, 75, '條件可靠', '在目標清楚或流程明確時表現可靠，遇到模糊或變動時易波動。', '提供清楚優先序、時程與檢核節點可提升穩定性。', '在目標、流程與期望清楚時，多數情況能維持可靠的交付；但在需求模糊、變動頻繁或優先順序不明時，交付穩定度較容易受到影響。', '{"do": ["可用於：①說明其可靠性與目標明確度、流程清晰度高度相關②建議透過優先順序、檢核節點與書面確認支援其穩定交付③鼓勵在不確定時主動詢問與確認，而非自己猜測。"], "dont": ["禁止：①把在混亂情境下的波動視為「個人不可靠」②忽視管理與流程問題，單純責怪個人③用分數評斷其不適合承擔關鍵任務④忽略其在結構良好環境中的穩定表現。"]}', 'ANI', '只要事情的期限、標準和流程都交代清楚，你通常可以準時、穩定地交付；如果前提常常改、或指示很模糊，就會比較難掌握。', '此區間反映可靠性受管理方式影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (381, 'ANI_16', 'C', 0, 50, '波動較大', '承諾與交付一致性不足，較容易受情境或狀態影響而延誤。', '適合拆解任務、短週期追蹤與更明確的交付標準。', '在交付穩定性上較具波動，承諾與實際完成之間可能會受到狀態、干擾或優先順序變動影響，較需要明確的排程管理與追蹤機制。', '{"do": ["可用於：①指出其需要在任務拆解、時間管理與干擾管理上得到更多支援②建議運用短週期追蹤、明確交付標準與提醒機制來提升一致性③強調這反映的是節奏與管理方式需求，而非價值或意願的否定。"], "dont": ["禁止：①用「不可靠」「講話不算話」等貼標語言定義個人②忽視工作量、角色衝突與環境干擾等結構性因素③單靠責備或施壓期待其自動改善④以此結果否定其在適當支持下的成長可能。"]}', 'ANI', '有時你會想把事情做好，但中間容易被其他突發或變動影響，導致時間或進度跟原本預期有落差；如果有更清楚的排程與追蹤，會比較穩。', '不代表能力不足，而是穩定輸出需要支援。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (382, 'ANI_17', 'A', 66, 100, '精準嚴謹', '能維持高度專注與準確度，主動發現錯誤並確保品質一致。', '適合品質控管、資料處理、合規與高精度交付任務。', '在準確嚴謹度上表現優異，能長時間維持對細節的專注，主動發現錯誤或不一致之處，確保成果的品質與一致性。', '{"do": ["可用於：①說明其在品質控管、審核與精細作業上的優勢②建議投入在資料處理、合規檢查或高精度要求的工作③提醒在追求精準的同時，也需與時程與效率做平衡。"], "dont": ["禁止：①以此期待其在任何情境下都零失誤②忽視工作量與時間壓力對細節品質的影響③將其嚴謹解讀為「挑剔」或人際問題④把注意細節等同於創意或大局思考不足。"]}', 'ANI', '你對細節很敏感，常常可以在別人沒注意到的地方抓出錯字、數字或流程上的小問題，讓成果更穩。', '不等同於速度快，重點在錯誤率與一致性。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (383, 'ANI_17', 'B', 31, 65, '重點把關', '能在重要環節把關細節，但在多工或時間壓力下容易忽略次要細節。', '以清單化、同儕檢核與分段交付可降低漏失。', '在關鍵環節與主要輸出上能注意到重要細節，但在多工、高壓或時間緊迫時，對次要細節的掌握度較容易下降。', '{"do": ["可用於：①說明其能在重點環節發揮把關作用②建議透過清單、雙重檢核或分工，協助在忙碌時維持細節品質③鼓勵事先釐清「哪些地方一定要很精準、哪些可簡化」來分配注意力。"], "dont": ["禁止：①將偶爾的細節疏漏放大成「不嚴謹」的長期標籤②忽略組織在工時、排程與資源配置上的責任③在要求高精度時，卻不給予足夠時間與工具④以個別錯誤否定其整體專業度。"]}', 'ANI', '對你來說，重要的數字、合約或正式文件，你會特別小心；但如果事情很多、時間又很趕，一些較小的細節比較容易被略過。', '此區間反映注意力資源分配受負荷影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (384, 'ANI_17', 'C', 0, 30, '細節落差', '對細節敏感度較低，容易漏掉規格或小錯誤，需要更多檢核機制。', '適合搭配模板、標準作業與品質檢查流程。', '目前在細節覺察與檢核上較不敏銳，若缺乏標準化流程或檢查機制，較容易遺漏小錯誤或規格要求。', '{"do": ["可用於：①指出其適合在標準作業清楚、已有檢核機制的情境下工作②建議導入模板、檢查清單與工具來降低錯誤率③鼓勵在關鍵文件或成果上安排同儕審閱，而非單獨承擔所有細節。"], "dont": ["禁止：①將此結果等同於「不在意品質」②用羞辱或嘲笑方式指出細節錯誤③忽略職務設計中對精確度的不合理期待④據此推斷其在其他能力面向上的價值。"]}', 'ANI', '你在做事時會先顧大方向，對一些較細的格式、標點或規格細節，不一定會第一時間注意到；如果有明確的檢查表或別人一起幫忙看，會比較安心。', '不代表不在意，而是細節覺察與檢核需要外部化。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (385, 'ANI_18', 'A', 76, 100, '清楚協調', '能清楚表達、理解他人並促進共識，溝通能兼顧內容與關係。', '適合跨部門協作、專案溝通與對齊共識的角色。', '在協調溝通上表現良好，能清楚表達想法、理解他人觀點並整理共識，兼顧資訊內容與關係維持，有助於降低誤解與衝突。', '{"do": ["可用於：①說明其在跨部門協作、專案對齊與會議主持上的優勢②建議投入在需要整合不同利害關係人觀點的情境③鼓勵善用書面摘要與會後整理，放大其溝通貢獻。"], "dont": ["禁止：①將其視為理所當然的「溝通窗口」，卻未給予相應角色與資源②要求其在任何衝突中都扮演調解者③忽略組織制度與權力結構對溝通效果的影響④把溝通好等同於必須始終迎合他人。"]}', 'ANI', '你通常能把自己的想法說清楚，也聽得懂別人在意的是什麼，會幫大家把重點整理出來，讓彼此比較好對齊。', '不等同於說服力，重點在理解與對齊。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (386, 'ANI_18', 'B', 51, 75, '任務溝通', '在工作需求明確時能有效溝通，但高壓或多工時需留意資訊遺漏。', '用議程、摘要與回覆確認可提升溝通品質。', '在任務明確、角色清楚的情境下，能有效傳遞資訊與回應需求；但在高壓、多工或議題較模糊時，資訊的完整度與一致性較容易產生落差。', '{"do": ["可用於：①說明其溝通品質與情境條件的關聯②建議透過會議議程、會後紀錄與關鍵訊息重複確認來支援③鼓勵在不確定時多問一句、再複述一次對方的重點，以減少落差。"], "dont": ["禁止：①把情境造成的誤解一概歸因為「你溝通不好」②在資訊本身就不清楚的前提下，責怪個人沒有講清楚③忽略溝通管道過多、訊息碎片化等結構性問題④以一次溝通失誤否定其長期表現。"]}', 'ANI', '當事情的目標、分工都講清楚時，你的溝通其實蠻順；但如果一次要處理很多事、或討論的主題很模糊，就比較容易漏講、或跟別人理解的不太一樣。', '此區間反映溝通品質受情境影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (387, 'ANI_18', 'C', 0, 50, '互動落差', '在複雜或情緒性互動中容易產生理解差異，互動一致性較不穩。', '適合搭配確認機制、書面化與回饋節點降低誤解。', '在複雜、多方或情緒性較高的互動中，較容易出現理解落差或訊息偏差，如缺乏確認機制，可能導致雙方期待不一致。', '{"do": ["可用於：①指出其在人際溝通上需要更多結構化支持，如書面說明、確認問題與明確結論②建議在關鍵對話後寫下重點並請對方確認，以減少誤會③鼓勵在重要場合前先準備要說的重點，提高表達穩定度。"], "dont": ["禁止：①將其標籤為「不會溝通」「溝通有問題的人」②忽略情境、權力關係與文化對溝通行為的影響③以負面評價而非具體建議回應其表現④推論其不適合任何需要對人互動的工作。"]}', 'ANI', '當談話牽涉的人多、情緒又比較重時，你有時會很難完全掌握對方的重點，或沒辦法一次就把自己的想法說清楚，如果沒有再三確認，雙方期待可能會有誤差。', '不代表缺乏表達能力，而是互動一致性需留意。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (388, 'ANI_19', 'A', 76, 100, '策略協商', '能平衡利益、尋求雙贏並調整策略，面對衝突仍能維持合作。', '適合對外合作、關鍵協議與資源交換情境。', '在協商談判上表現成熟，能兼顧自身與對方利益，清楚表達立場與底線，同時維持合作關係，擅長尋找雙贏或折衷方案。', '{"do": ["可用於：①說明其在價格、條件或資源協調上的優勢②建議投入對外合作、合約協調或內部資源分配等需要談判的情境③提醒談判仍需事前準備與資料支持，而非完全依賴臨場反應。"], "dont": ["禁止：①將其視為必須在所有衝突情境中出面處理的人②以此為由，把高度風險或壓力談判全數交給其負責③忽略團隊或組織在談判策略與立場設定上的責任④以短期結果評價其全部談判能力。"]}', 'ANI', '你談事情時，既會顧到自己這邊要守住的重點，也會注意到對方能接受的空間，常常可以談出雙方都可以接受、關係也維持得不錯的結果。', '不等同於強勢立場，重點在策略與關係兼顧。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (389, 'ANI_19', 'B', 51, 75, '情境談判', '在準備充分或熟悉對象時表現佳，臨場變化大時較依賴框架。', '提供談判目標、底線與替代方案，可提升穩定度。', '在熟悉主題、準備充分或談判結構較清楚時，能有效表達訴求並爭取合理條件；但在臨場變動大或壓力較高時，較依賴事前框架與他人支援。', '{"do": ["可用於：①說明其談判表現與準備程度高度相關②建議在重要協商前提供明確目標、底線、替代方案與常見問題回應③鼓勵在談判過程中適度暫停與回到團隊討論，而非勉強單獨承擔。"], "dont": ["禁止：①把在高壓即興情境中的不穩定表現簡化為「不會談」②要求其在完全沒準備的情況下處理關鍵談判③忽視組織在談判策略、資料與支援上的配置④以個別談判結果作為唯一評價依據。"]}', 'ANI', '如果你對議題很熟、也先準備過要談的重點和底線，談判時表現通常不錯；但遇到臨時變卦或壓力很大的場合，就會比較需要事先規畫好的說法和同伴在場。', '此區間反映談判效果受準備程度影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (402, 'ANI_23', 'C', 0, 26, '回應較真實', '較能如實呈現自身想法與狀態，不會為了形象或討好而大幅扭曲答案，回覆可信度較高。', '在評鑑解讀與面談追問時可更直接使用其結果；適合用開放問題深化洞察。', '作答時傾向如實呈現自己，即使某些回答可能不那麼「好看」，也較少刻意修飾以迎合期待。', '{"do": ["可用於：①說明其報告內容可信度相對較高②建議在解讀其他量表分數時，可以較少保留地相信其自陳資訊③鼓勵其持續維持真實表達，同時也學會在敏感情境中保護自己。"], "dont": ["禁止：①把其低社會期望反應當成「不在意別人看法」的負面標籤②忽略情境與關係對其表達方式的影響③在高風險場合鼓勵其完全不設防④把真實等同於不需任何界線。"]}', 'ANI', '你比較不會特別去想「這樣寫會不會比較好看」，而是照自己的真實情況回答。', '不代表沒禮貌，而是較少包裝；仍需注意溝通方式。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (390, 'ANI_19', 'C', 0, 50, '讓步傾向', '衝突情境中較易退讓或避免對抗，可能錯失保護己方利益的機會。', '適合先設定底線與說法，並安排練習與支援。', '在衝突或利益拉鋸的情境中，可能傾向避免對立、選擇讓步以維持關係或降低場面壓力；或是可能以強勢進逼想贏過對方、沒有保留雙贏空間，，因此談判結果對己方在短期或長期可能遭受損失。', '{"do": ["可用於：①說明其偏好低衝突與關係維持的談判風格②建議在進入協商前先設定清楚的底線、可讓步與不可讓步項目，並安排必要時可請他人協助發聲③鼓勵透過角色扮演或模擬練習，逐步提升在安全範圍內堅持立場或思考雙贏的能力。"], "dont": ["禁止：①將其描述為「沒有立場」「不敢發聲」②忽略其維持關係與降低衝突的正面價值③在完全沒有支持的情況下要求其獨自面對高風險談判④用結果指責其個性有問題或推論其不適合承擔責任。"]}', 'ANI', '一進入比較緊張或有衝突感的談判場景，你可能會傾向先讓一步、先求氣氛不要太僵，結果有時會把對自己比較有利的條件讓出去。另一方面，也可能發生只顧己方利益單純想贏，忽略雙贏的長期利益。', '不代表沒有立場，而是偏好關係穩定與低衝突。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (391, 'ANI_20', 'A', 76, 100, '審慎評估', '能檢視資訊可信度、比較不同觀點並避免過度直覺判斷。', '適合參與風險評估、決策審查與品質把關。', '在批判性思考上表現成熟，能檢視資訊來源與證據品質，對不同觀點進行比較，不會只依靠直覺或單一說法做決定。', '{"do": ["可用於：①說明其在資料驗證、風險評估與決策審查上的優勢②建議投入需要檢視假設、看反例、拆解論點的任務，如專案審查、政策討論、風險委員會③鼓勵搭配清晰的評估標準與多元資料來源，讓其批判性思考轉化為具體決策建議。"], "dont": ["禁止：①將其批判能力解讀為「挑剔」「唱反調」②期待其在毫無資料的情況下仍能做出絕對正確判斷③用這個分數合理化過度否定他人或持續拖延決策④把質疑與提問視為不服從或負面態度。"]}', 'ANI', '你會先看資訊靠不可靠、理由是否站得住腳，不會只因為「聽起來合理」或「大家都這樣說」就接受。', '不等同於保守，而是重視證據與前提檢核。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (392, 'ANI_20', 'B', 51, 75, '選擇性檢視', '在關注重點明確時能進行判斷，但時間壓力下可能簡化評估流程。', '保留討論空間與反例檢核，有助避免單一觀點。', '具備一定批判性思考，當議題與重點清楚時，能針對關鍵資訊提出疑問與判斷；但在時間壓力大或資訊量過多時，較容易簡化評估流程。', '{"do": ["可用於：①說明其批判深度會受時間與情境影響，在結構較清楚時表現較佳②建議透過簡化的檢核清單（如幾個固定問題）協助在壓力下維持基本評估品質③鼓勵在重大決策前預留短暫「停頓時間」，專門檢查假設與風險。"], "dont": ["禁止：①因為少數情境下評估不足，就簡化為「沒有批判能力」②在完全沒有時間與資訊支援的情況下要求其做深度風險分析③忽略議題複雜度與資訊品質，把所有判斷結果都歸因於個人能力④用一次錯誤推論其長期判斷力。"]}', 'ANI', '如果主題明確、時間允許，你會挑重點去想「哪裡說得不夠完整」；但在很趕或資訊太雜時，會傾向先抓大方向，細部就不會檢查太多。', '此區間反映評估深度受情境影響。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (393, 'ANI_20', 'C', 0, 50, '判斷依賴', '較容易依賴他人觀點或既有結論，較少主動質疑前提與證據。', '適合搭配審查機制、多元意見與推理框架訓練。', '目前較容易沿用現成結論或多數意見，較少主動檢查前提、證據與潛在風險，需要外部框架或他人帶領來啟動更深入的檢視。', '{"do": ["可用於：①說明其目前較偏向依賴既有結論與權威意見，適合搭配清楚的評估步驟與示範②建議透過簡單的提問框架（例如「如果相反會怎樣？」「有沒有例外？」）逐步練習質疑前提③鼓勵在安全情境下練習提出不同觀點，而不是一次要求全面顛覆思考方式。"], "dont": ["禁止：①將此區間標籤為「沒在思考」「盲從」②忽視組織文化、權力結構與資訊不對稱對其判斷方式的影響③用羞辱或嘲諷方式要求其「要有批判性」④據此推論其不適合參與重要討論或決策。"]}', 'ANI', '你在面對資訊或決策時，會比較傾向先參考「大家怎麼看」「過去怎麼做」，不一定會自己花很多力氣去拆解理由或找反例。', '不代表缺乏思考，而是檢核動機較低。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (394, 'ANI_21', 'A', 76, 100, '情境洞察', '能讀懂社交線索與關係動態，並調整互動策略以促進合作。', '適合跨部門協作、客戶互動與橋樑型角色。', '在社交智商上表現良好，能讀懂場合氛圍與人際動態，敏感察覺權力關係與微妙變化，並調整溝通方式以維持合作與信任。', '{"do": ["可用於：①說明其在關係經營、跨部門協作與客戶互動上的情境判讀優勢②建議擔任橋樑型角色，如專案協調、利害關係人管理或對外窗口③鼓勵在維持關係的同時，也適度表達真實立場，以避免過度迎合。"], "dont": ["禁止：①將其社交敏感度視為理所當然的隱形勞務②要求其在任何情境都優先照顧他人情緒而忽略自身界線③把「看得懂氣氛」等同於必須處理所有人際問題④用此分數推論其一定外向或喜歡高社交強度。"]}', 'ANI', '你對場合氣氛和人跟人之間的關係很敏感，通常看得出誰在意什麼、現場氛圍如何，會調整說話方式，讓互動順得多。', '不等同於外向或社交活躍，重點在情境判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (395, 'ANI_21', 'B', 51, 75, '基本互動', '能在一般情境維持良好互動，但在複雜權力或衝突情境需要時間適應。', '清楚角色與關係結構、有助於提升互動穩定度。', '在一般職場互動中能維持良好關係，理解基本社交線索與角色分際；但在權力結構複雜、衝突較高或情緒張力大的情境中，較需要時間適應與額外資訊來判讀局勢。', '{"do": ["可用於：①說明其社交智商多在「一般情境」表現穩定，在高複雜度場域需要更多脈絡支援②建議在重要會議或政治敏感議題前，提供關係地圖、角色說明與溝通重點③鼓勵在不確定時，採取多聽、多觀察與詢問建議的策略，而非急於表態。"], "dont": ["禁止：①因在少數複雜情境中不夠靈活，就貼上「社交遲鈍」標籤②忽略組織文化與權力關係對社交壓力的影響③期待其在沒有資訊與支持的情況下獨自處理高度政治性的互動④將社交表現與人格價值直接綁定。"]}', 'ANI', '在日常合作、一般會議或熟悉的同事之間，你的互動通常蠻順；但遇到牽涉權責或氣氛比較僵的場合，就會需要多觀察一下，或事先有人幫忙說明背景，才比較知道如何應對。', '此區間反映熟悉度影響社交判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (396, 'ANI_21', 'C', 0, 50, '線索不敏感', '對社交暗示或關係變化較不敏感，互動策略較固定，易產生落差。', '適合互動規則明確的環境；可用明確回饋降低誤解。', '在社交情境的細微線索（例如眼神、語氣、關係張力）上較不敏銳，互動風格偏固定，容易與他人對情境的解讀產生落差，需要更明確的規則、回饋與說明。', '{"do": ["可用於：①指出其在「讀空氣」上需要更多明確線索與回饋，適合在互動規則清晰、期望透明的環境工作②建議同事與主管用直接、具體的方式說明期待，而不是依賴暗示③鼓勵個人透過詢問（例如「現在大家的顧慮是什麼？」）來補足情境理解。"], "dont": ["禁止：①將此結果簡化為「不懂人情世故」「情商低」②用嘲笑或排斥的方式回應其社交錯位③忽略組織在建立清楚規則與開放溝通文化上的責任④據此否定其在專業貢獻或工作成果上的價值。"]}', 'ANI', '你在和人互動時，會比較專注在話裡「字面上」的內容，對氣氛變化或潛台詞不一定會第一時間察覺，有時會跟別人對當下情況的感受不太一致。', '不代表人際能力差，而是社交判讀需求較高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (397, 'ANI_22', 'A', 76, 100, '果斷判斷', '能在資訊有限時做出決策並承擔結果，遇到變化能快速定案調整。', '適合需要快速反應、決策頻繁的角色與任務。', '在高效決策上表現突出，能在資訊不完全的情況下仍做出合理選擇，並在環境變化時快速調整決策方向，願意承擔結果並持續修正。', '{"do": ["可用於：①說明其在需要即時反應、決策頻繁的情境（如營運調度、專案現場）上的優勢②建議搭配簡明的決策準則與事後檢討機制，讓快速決策持續優化③鼓勵在重大高風險議題上，加入他人觀點與檢核，以平衡速度與品質。"], "dont": ["禁止：①以其決策速度為由，鼓勵在關鍵議題上「先做再說」而忽略風險評估②將快速決策等同於衝動或一意孤行③期待其單獨扛起所有決策結果，而忽視團隊與組織的共同責任④把偶爾的錯誤放大為「判斷草率」的固定標籤。"]}', 'ANI', '遇到需要決定的時候，你不會一直卡著等完美資訊，會根據現有資料做出選擇，之後若情況變了，也能很快調整做法。', '需搭配檢核以避免過快決策造成偏誤。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (398, 'ANI_22', 'B', 51, 75, '審慎選擇', '傾向蒐集足夠資訊後再決策，決策品質穩定但速度受資訊完整度影響。', '設定時程與決策門檻，有助兼顧效率與品質。', '在有足夠資訊與時間時，能做出穩健的決策；傾向先蒐集資料、聽取意見再定案，決策品質通常不錯，但速度會受到資訊完整度與不確定程度影響。', '{"do": ["可用於：①說明其傾向審慎決策、重視風險與證據，在穩定環境中特別適合負責重要判斷②建議在時程敏感的情境下，事先設定「資料夠多就要決定」的門檻與期限③鼓勵在資訊難以完全掌握的情況下，運用情境假設與試行方案，而非無限延後決策。"], "dont": ["禁止：①將審慎與遲疑混為一談，簡化為「反應慢」②忽視議題複雜度與風險，要求其在資訊不足時硬性加快決策③以單次決策延宕評價其整體工作效率④用壓力或羞辱方式逼迫其「快點決定」。"]}', 'ANI', '如果時間允許、資料找得到，你會希望先弄清楚來龍去脈再做決定，所以做出的決策通常蠻穩，但在資訊很模糊時就會多想一下才敢定案。', '此區間反映風險與資訊敏感度較高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (399, 'ANI_22', 'C', 0, 50, '猶豫傾向', '面對多選項時較難快速定案，容易延後或反覆比較。', '提供選項排序、決策框架與期限，可協助定案。', '在面對多個選項或高度不確定的情境時，較容易陷入反覆比較或延後決定，擔心選錯帶來風險，因而需要更多結構化協助來推進決策。', '{"do": ["可用於：①指出其目前在決策上偏向降低風險與避免後悔，需要清楚的決策框架（如利弊列表、優先順序）②建議透過設定決策期限、分階段決定（先小後大）來降低壓力③鼓勵在安全情境中練習「做出足夠好而非完美」的決策經驗，累積信心。"], "dont": ["禁止：①將其描述為「沒主見」「優柔寡斷」②忽略情境風險與過去經驗對其猶豫的影響③在沒有提供任何工具或支持的前提下，單純要求其「要果斷一點」④用這個結果否定其在分析、支持性角色或需要謹慎評估職務上的價值。"]}', 'ANI', '當要在幾個選項之間做選擇、而且每個都有好壞時，你可能會一直來回想、很怕選錯，結果決定會拖比較久。', '不代表缺乏判斷力，而是對風險更敏感。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (400, 'ANI_23', 'A', 54, 100, '高度形象管理', '明顯傾向以社會期待方式作答，可能歪曲信念與答案以取得認可，導致評鑑可用性下降。', '更依賴行為證據、工作樣本與多方資料交叉驗證；避免只靠自述決策。', '作答時高度考量「別人會怎麼看」，較可能以理想化的自我形象作為回答依據，而非完全依照日常真實狀態。', '{"do": ["可用於：①指出其他量表分數可能受到形象管理影響，需要搭配他評、行為觀察與面談綜合判斷②建議在回饋過程中，以安全、不評價的方式討論其「想被看見的樣子」③鼓勵其練習在適當場合逐步放下完美形象，讓真實狀態也有被看見的空間。"], "dont": ["禁止：①直接貼上「不誠實」標籤②忽略測驗情境本身帶來的壓力與不安全感③在回饋時用戳破或羞辱的語氣談其防衛④只靠此指標判斷其人格。"]}', 'ANI', '你在回答時可能常會想「這樣寫感覺比較好」，而不是單純寫平常真正的反應。', '不等於說謊成性，可能害怕否定；重點是降低威脅感並改用佐證法。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (401, 'ANI_23', 'B', 27, 53, '形象真實混合', '多數時回應真實，但在敏感題或想留下好印象時可能偏理想化回答，呈現部分防衛。', '用情境題、行為例證追問與無評價訪談氛圍提高資訊準確度。', '作答時會在真實與形象之間拿捏，多數情況仍偏向說真話，但在少部分問題上可能略為修飾。', '{"do": ["可用於：①說明其整體資料仍具參考價值，但需理解少部分題目可能受形象考量影響②建議在回饋時，同步邀請其分享對測驗的感受，增加開放度③鼓勵其把測驗視為自我了解工具，而不是面試考卷。"], "dont": ["禁止：①因為略有形象考量就說「在騙人」②忽略測驗情境（如是否與錄用掛鉤）③只從社會期望指標單點推論其誠實程度④在回饋時用指責口吻談此結果。"]}', 'ANI', '你大部分會照實回答，但有些題目可能會稍微想一下「這樣寫會不會比較好」。', '大多數人常見狀態；避免把表面正向當成全部真相。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (403, 'CIA_01', 'A', 71, 100, '高度自律', '做事有一致的自我要求，能主動掌握進度、顧品質與收尾，較少需要外部催促也能維持可靠輸出。', '可交付需要穩定產出、長期追蹤、責任界線清楚的任務；適合擔任流程 owner、專案控管與交付把關角色。', '整體呈現高度自律與責任感，做事會主動掌握進度、照顧品質與收尾細節，即使沒有外在催促也能維持穩定輸出。', '{"do": ["可用於：①說明其在自我管理、品質控管與長期專案追蹤上的穩定度②建議安排需要穩定產出、責任邊界清楚的任務或流程 owner 角色③鼓勵在維持高標準的同時，也留意工作量與身心負荷，避免過度投入。"], "dont": ["禁止：①把其盡責當成理所當然，不斷加派任務而不調整資源②將偶爾的延宕或失誤放大成「不負責」③以此分數假設其永遠不需要督導或回饋④把對細節的在意誤解為「愛挑別人毛病」。"]}', 'CIA', '你習慣把事情安排好、跟進好、收尾也做好，別人把任務交給你，大多會覺得放心。', '高分反映自律與責任感；若同時完美主義偏高，可能出現過度投入或對他人標準嚴苛。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (404, 'CIA_01', 'B', 41, 70, '任務可靠', '在目標、範圍與時程清楚時表現穩定；遇到優先序頻繁變動或責任邊界不清時，效率與投入度可能波動。', '以明確分工與里程碑提升穩定度；適合在既定流程內承擔主力執行與回報節點。', '面對目標、範圍與時程清楚的任務時，多能穩定完成並維持基本品質；當優先順序頻繁變動或權責模糊時，節奏與細緻度會跟著起伏。', '{"do": ["可用於：①說明其表現高度仰賴任務清晰度與外部結構②建議透過明確分工、里程碑與定期 check-in，協助其穩定輸出③鼓勵其學會主動釐清優先順序與需求，而不是悶著做。"], "dont": ["禁止：①在目標本身就模糊的前提下，將所有落差歸因於個人「不夠負責」②用零星案例貼上「時好時壞」的標籤③忽略管理與流程設計的責任，把結構問題丟給個人扛④期待其在混亂環境中依然維持完全同樣的表現。"]}', 'CIA', '只要知道要做什麼、什麼時候要完成，你通常都能把事情處理好；但如果規則常改、任務一直變，就會比較難穩住步調。', '此區間多反映對外部結構的依賴程度，不代表不負責。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (405, 'CIA_01', 'C', 0, 40, '節奏支援', '較容易受情境或情緒影響而出現拖延、鬆散或收尾不足；不是做不到，而是自我監控與維持節奏較吃力。', '搭配短週期拆解、檢核清單、同儕回報機制；先讓完成穩定，再逐步拉高品質。', '執行節奏容易受情緒、環境或干擾影響，偶爾會出現拖延、鬆散或收尾不足的情況，能力並非不足，而是在自我監控與維持節奏上較吃力。', '{"do": ["可用於：①指出其需要更多外部化工具（如任務拆解、檢核清單、固定回報節點）來穩定輸出②建議先把「準時完成」與「不漏掉」當成第一優先，再逐步拉高品質標準③鼓勵與主管或同事一起設計適合自己的節奏，而不是單靠意志力撐。"], "dont": ["禁止：①直接標籤為「懶散」「不可靠」②忽略工作量、干擾度與專注環境對其表現的影響③用羞辱或比較的方式要求「要自律一點」④將此分數視為否定其能力或潛力的理由。"]}', 'CIA', '你不是做不到，只是很容易被當下狀態、雜事或心情打斷，要自己撐住步調會比較累。', '低分不等於能力弱，常見是時間管理與優先序未形成固定習慣，管理重點在外部化流程。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (406, 'CIA_02', 'A', 76, 100, '卓越進取', '對表現與成果有明顯企圖心，願意多投入以達到更高標準，遇到挑戰傾向主動升級方法與目標。', '適合高挑戰、高成長、需要拉高標準的任務；可作為衝刺型角色。', '對表現與成果抱持強烈企圖，會主動拉高標準、尋找挑戰，願意投入額外心力追求更出色的成績。', '{"do": ["可用於：①說明其在目標導向與追求成就上的動能，可作為衝刺型或關鍵任務的主力②建議搭配清楚的成長與回饋機制，把努力和成果連結清楚③提醒在高成就傾向下，也要留意休息與界線，避免過勞或過度自責。"], "dont": ["禁止：①以其成就動機為由，不斷加壓或延長工時③忽略資源不足、流程問題，只用「你應該更努力」回應落差③將短暫倦怠解讀為「不再上進」④把個人績效完全與人格價值綁在一起。"]}', 'CIA', '你不太滿足於「剛好過關」，比較習慣問自己「能不能再更好一點」，所以常會多做一些。', '高分不必然代表合作佳；若目標壓力過大，可能出現急躁或把成果放在協作之前。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (407, 'CIA_02', 'B', 51, 75, '目標驅動', '在目標清楚、回饋可見時會穩定投入；若缺乏指標或看不到進展，動能容易下降。', '以 KPI/OKR、里程碑與可視化進度維持續航；適合中長期專案的穩定推進者。', '對達成目標有穩定重視，當目標具體且看得到成果時，會願意投入努力；若缺乏指標或看不到成效，動能就比較容易下降。', '{"do": ["可用於：①說明其動機多與「目標清晰度、意義感與回饋」連動②建議在專案初期一起定義具體指標與節奏，並提供可見的進展回饋③鼓勵其主動提出自己在成就與發展上的期待，避免陷入被動。"], "dont": ["禁止：①將此區間簡化為「不上進」或「沒企圖心」②在缺乏方向與資源時，用壓力或比較逼其多做③忽略職務設計與獎酬機制對動機的影響④用單一時期的低動力推論其長期表現。"]}', 'CIA', '如果知道「做到這裡代表有進步」，你會願意出力；但如果目標很空或看不出差別，就會覺得再拼也不一定有用。', '此區間關鍵在回饋設計，同樣能力的人因回饋密度不同而呈現差異。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (408, 'CIA_02', 'C', 0, 50, '穩定達標', '傾向把工作完成在合理範圍，不一定追求更高難度或額外突破；動機更受環境支持與要求牽動。', '適合明確職責、節奏固定的工作；若期待突破，需提供動機意義與可達成的成長路徑。', '整體行事風格偏向穩穩完成要求，對「超標」「突破」的追求較弱，更傾向在合理範圍內把事情做完即可。', '{"do": ["可用於：①說明其適合在穩定執行與支持性角色中貢獻，而不宜期待高度競賽式表現②建議將其放在需要穩定完成、而非持續衝高指標的工作內容③鼓勵透過探索「自己覺得有成就感的事」來建立屬於自己的成就定義。"], "dont": ["禁止：①貼上「不求上進」「躺平」等道德化標籤②忽略職務匹配與成就感來源差異③用高壓業績文化要求其表現出強烈競爭性④將此分數當作否定其職涯發展可能的依據。"]}', 'CIA', '你會希望把分內的工作處理好，但不一定會為了拿第一名或打破紀錄，再多推自己好幾步。', '低分不等於不上進，需區分是價值觀取向或缺乏挑戰誘因。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (409, 'CIA_03', 'A', 76, 100, '先思後行', '行動前會評估風險、假設與後果，較少因一時判斷造成返工；在不確定情境能維持判斷品質。', '適合風險控管、決策審查、流程把關與合規情境；可擔任決策前最後一道檢核。', '做決定前習慣先思考情境、風險與可能結果，面對不確定時也能維持判斷品質，不會輕易被一時情緒帶走。', '{"do": ["可用於：①說明其在風險評估、策略討論與重要決策上的價值②建議投入錯誤成本高、需要深思熟慮的議題（如人事、合約、長期投資）③鼓勵在已充分思考的情況下，為行動設下明確時限，避免過度拉長決策。"], "dont": ["禁止：①將其審慎誤解為優柔寡斷②要求在資訊高度不足又風險極高時，仍「秒回決定」③忽略議題複雜度與資訊量，只用決策速度評論其能力④把多問幾句當成「找麻煩」。"]}', 'CIA', '你比較像是「先想一圈再出手」的類型，會先評估可能的後果，再決定要怎麼做。', '高分可能帶來速度成本；若任務要求快速試錯，需明確可接受的風險邊界。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (410, 'CIA_03', 'B', 51, 75, '情境權衡', '在重要決策會拉高審慎程度，但在時間壓力或熟悉任務可能簡化評估；品質受情境影響較大。', '提供決策模板（選項/風險/影響/備案）穩定發揮；適合在快慢要切換的團隊中。', '重要事情會刻意拉慢節奏、多想一下；對熟悉或看似小事的議題，則傾向簡化評估、快速做決定，實際謹慎程度會依情境調整。', '{"do": ["可用於：①說明其會依照「重要性」調整審慎程度②建議針對關鍵領域（如人員、預算）設定最基本的思考檢核點③鼓勵在「看似日常但影響深遠」的議題上，也保留一些審慎空間。"], "dont": ["禁止：①因為個別錯誤就說「都想不清楚」②忽略時間壓力、資訊不足等外因③用完美主義標準要求其所有決策都零失誤④把一兩次的疏忽視為長期固定問題。"]}', 'CIA', '遇到大事你會謹慎一點，平常的小決定就會比較順手、直覺地做，沒有每件事都想很久。', '避免用單次表現貼標籤；觀察高風險 vs 低風險情境差異更準。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (411, 'CIA_03', 'C', 0, 50, '行動先行', '傾向先做再調整，評估常在行動後補上；在快速節奏下能衝刺，但也較容易忽略隱性風險。', '搭配快速檢核點與同儕 review 降低返工與踩雷；適合需要速度的工作。', '做事風格偏向「先做再說」，經常先行動再在過程中修正，對事前評估風險與前提的時間相對較少，在快速環境能推進，但也較容易忽略隱藏問題。', '{"do": ["可用於：①指出其在需要快速試錯、敏捷調整的情境中具行動優勢②建議在高風險或一次性決策前，設置簡單的「停一下先想」流程③鼓勵與較審慎的同事搭配，在速度與風險之間互相補位。"], "dont": ["禁止：①直接貼上「莽撞」「沒在想」的標籤②忽略制度、時程與壓力對其行動風格的影響③只用事後責備處理錯誤，而不提供前期支援④把此分數當作否定其判斷力的理由。"]}', 'CIA', '你很多時候會先去做、邊做邊調整，不太會在一開始就把所有細節想透。', '低分不等於魯莽，可能偏好迭代式思考；管理重點在補足關鍵停看聽節點。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (412, 'CIA_04', 'A', 73, 100, '規範堅守', '高度重視承諾、規則與責任邊界，遇到灰色地帶也傾向選擇可被交代、可被信任的做法。', '適合合規、資安、機敏資料等高度信任情境；可放在制度與文化的穩定器位置。', '對承諾、規則和職責界線有強烈重視，遇到灰色地帶時，也會傾向選擇站得住腳、講得清楚的做法。', '{"do": ["可用於：①說明其在守信、合規與高度信任情境中的重要性②建議安排需高度可靠與可追溯性的任務（如合約控管、稽核、長期客戶關係）③鼓勵在堅守原則的同時，也學習與組織討論不合理規範。"], "dont": ["禁止：①把其義務感當成免費勞力，不斷追加責任②用「你有責任」掩蓋制度或資源問題③期待其為了組織利益長期犧牲個人健康與生活④在其提出合理界線時，批評為「不夠有責任感」。"]}', 'CIA', '你會很在意「答應過的事要做到」以及「事情要交代得過去」，對規則和責任界線也比較敏感。', '高分者在不合理規範下可能壓力較大；需提供申訴/調整流程避免僵化遵循。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (413, 'CIA_04', 'B', 46, 72, '規則導向', '大多遵守規範，但在資源不足或目標衝突時會尋求折衷；通常需要明確指示什麼不能動。', '把不可妥協底線講清楚，其餘留彈性可提升效率與配合度。', '大多數情況會遵守規範與承諾，但在資源不足、規則矛盾或多重目標拉扯時，會尋找折衷作法，希望在「守規矩」與「把事情做成」之間取得平衡。', '{"do": ["可用於：①說明其在實務現場會同時顧及原則與效率②建議清楚界定「真的不能動的底線」，其他部分保留彈性空間③鼓勵當規範與目標衝突時，用對話尋找更好的做法，而非悶著承擔。"], "dont": ["禁止：①把情境下的權衡解讀為「沒有責任感」②忽略制度設計與資源條件對行為的限制③用單一事件批評其立場不堅定④要求其在沒有任何空間與支援下，仍獨自扛起所有義務。"]}', 'CIA', '你基本上會照規則來，但如果資源不夠、規定有矛盾，或這樣做會讓事情完全卡住，你也會想辦法找折衷。', '常見於務實型人才；管理者要給原則而非每一步細則。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (414, 'CIA_04', 'C', 0, 45, '彈性取捨', '較容易把規範視為可調整的工具，遇到目標壓力可能優先選擇結果導向做法，需要較強的底線提醒。', '以雙人覆核、紀錄透明、權限控管等制度降低風險；適合創新但需控風險。', '面對規範時較常以「工具」而非「原則」來看待，遇到壓力或目標強烈時，容易優先選擇對結果有利的做法，需要更清楚的底線提醒與制度控管。', '{"do": ["可用於：①指出其在需要彈性、突破與實作導向的情境中具優勢，但需設好界線②建議透過權限控管、雙人覆核與紀錄透明來降低風險③鼓勵在追求結果的同時，也思考長期信任與風險成本。"], "dont": ["禁止：①直接標籤為「沒原則」「會亂來」②忽略目標壓力與制度缺陷對其選擇的影響③完全用道德指責代替制度設計④把此分數當作預測其必然違規或不誠信。"]}', 'CIA', '你比較容易把規則當成可以調整的東西，如果壓力很大、目標很硬，就會先想「怎麼做比較有效」，而不是完全照規定。', '低分不等於不誠信；需區分討厭形式或忽略底線，建議以情境驗證。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (415, 'CIA_05', 'A', 76, 100, '自制穩定', '能管理情緒與衝動反應，在壓力下仍維持一致行為與判斷，不易因一時情緒做出高代價決定。', '適合高壓、客訴、談判等需要穩定情緒輸出的角色；可作為團隊情緒穩定器。', '衝動與情緒來時，多半能先踩煞車、評估一下後果，再決定要不要說或要不要做，短期誘惑不容易完全蓋過長期考量。', '{"do": ["可用於：①說明其在情緒管理、風險行為與重要承諾上的穩定度②建議在需要冷靜判斷與高自制的角色中善用此特質③鼓勵在自我壓抑與健康表達之間找到平衡，不必永遠當「情緒黑洞」。"], "dont": ["禁止：①把其穩定當成無限承受情緒與壓力的理由②忽略其內在耗損，只期待「你一定撐得住」③批評偶發情緒失控為「不應該」而不看長期表現④把高自制等同於不需要支持。"]}', 'CIA', '就算一瞬間很想發作或很想立刻答應，你通常還拉得住自己一下，先想一下「這樣做之後會怎樣」。', '高分不等於不表達情緒；重點是能選擇合適方式表達與處理。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (416, 'CIA_05', 'B', 51, 75, '情境波動', '一般狀態自制力良好，但在連續高壓、衝突或睡眠不足時，反應可能變快、語氣變硬或耐心下降。', '建立高壓期節奏（輪班、緩衝、降噪）與復盤機制；在有支持系統下承擔前線任務。', '平時多能控制自己的反應與衝動，但在長期壓力、嚴重疲勞或連續挫折的情況下，情緒與行為有時會一時失衡。', '{"do": ["可用於：①說明其衝動管理與壓力、體力高度連動②建議建立壓力預警機制（例如自覺快爆時先暫停決定）③鼓勵在事後檢討時，把重點放在調整做法，而不是單純自責。"], "dont": ["禁止：①只用單一事件否定其平常的自制力②忽略制度與工作負荷對其情緒穩定的影響③以「你不可以這樣」作為唯一回應，而不討論實際調整策略④把情緒反應視為人格缺陷。"]}', 'CIA', '你大部分時候都還撐得住，但當很多事疊在一起、又很累的時候，也可能會突然說重話或做了之後覺得太快的決定。', '此區間要看觸發條件；找出何時失控、何時穩定，才能設計有效支持。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (417, 'CIA_05', 'C', 0, 50, '衝動風險', '較容易被情緒推著走，出現衝動回應、倉促承諾或行為過頭；事後常需要修補或解釋。', '降低高衝突暴露、提供情緒停損流程（先暫停/先寫後說/第三方介入）；用規範保護本人與團隊。', '當情緒被挑起或短期誘惑出現時，較容易順著當下感覺行動，事後才意識到後果或產生懊惱，需要更多「多一拍思考」的協助與設計。', '{"do": ["可用於：①指出其在衝動管理上需要具體的環境與流程輔助（例如預設等待時間、找人商量）②建議設計簡單的自問機制，如「這樣做之後一週後我會怎麼看？」③鼓勵用負責但不自我否定的方式看待過去失誤，從中練習新的反應模式。"], "dont": ["禁止：①貼上「沒自制力」「不成熟」的標籤②忽略壓力、情緒與環境刺激對行為的影響③單靠責罵或羞辱要求其改變④將此分數與任何臨床診斷畫上等號。"]}', 'CIA', '你有時會先照當下的情緒或直覺做了，過一陣子才覺得「好像有點太快」。', '低分不代表不適任，但需要環境設計與技能訓練並行。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (418, 'CIA_06', 'A', 81, 100, '流程有序', '偏好清楚流程與例行節奏，能把資訊分類、把任務排程並維持一致做法，降低遺漏與混亂。', '適合流程設計、營運管理、專案行政與品質控管；可建立團隊共通作業標準。', '對秩序與結構有明顯偏好，會主動整理流程、資料與環境，讓事情有條有理地進行，以降低遺漏與混亂。', '{"do": ["可用於：①說明其在流程整理、檔案管理與專案規畫上的貢獻②建議擔任需要維持秩序與結構的角色（如 PM、系統整理、SOP 設計）③鼓勵在需要彈性的情況下，也允許自己保留部分「尚待探索」空間。"], "dont": ["禁止：①把其對條理的堅持解讀為「龜毛」「難相處」②忽略組織本身的混亂對其壓力的影響③期待其單獨扛起全部整理和制度化工作④把偏好秩序等同於缺乏創造力。"]}', 'CIA', '你喜歡把「東西放哪裡」「下一步是什麼」都弄清楚，環境太亂或流程太散會讓你不太安心。', '高分者在高度變動或需要即興場景可能不適；要允許部分任務採彈性模式。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (419, 'CIA_06', 'B', 61, 80, '重點整理', '會整理重點與基本秩序，但不一定每件事都系統化；在多工時需要工具或提醒來維持條理。', '提供共用看板、固定回報節點與簡單模板即可顯著提升；適合兼顧彈性與秩序的型態。', '在重要事情上會維持基本的規畫與整理，但不會追求所有事物都高度結構化，會依情境在「順手」與「有系統」之間調整。', '{"do": ["可用於：①說明其在條理與彈性間具有一定平衡感②建議透過簡單工具（行事曆、任務清單）維持必要結構③鼓勵在多人協作或關鍵專案時，稍微提高條理程度以避免資訊遺漏。"], "dont": ["禁止：①因為不「極度整齊」就認定其沒有組織能力②忽略系統與工具本身的限制③用單次檔案找不到的狀況否定其整體工作風格④在未提供任何支援的情況下要求高度紀律整理。"]}', 'CIA', '對你來說，重要的東西會整理好，其他部分只要自己找得到、用起來順就可以，不一定要全部都非常整齊。', '此區間可被系統化加成；工具與流程到位後差距會快速縮小。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (420, 'CIA_06', 'C', 0, 60, '彈性隨性', '較不靠固定流程工作，容易臨場處理；彈性高但也可能出現紀錄不足、交接不清或遺漏細節。', '設定最低限度的紀錄與交付格式（不求完美，求可追溯）；適合探索或外部開發。', '對固定流程、分類與整理沒有太強的內在動機，習慣依當下需求與感覺處理事物，資訊與物品較容易分散，需要「最低限度的秩序設計」來避免影響工作。', '{"do": ["可用於：①指出其在創意發想或需要靈活應變的工作中可保有彈性，但在大量資訊情境需要外加結構②建議從關鍵檔案與重要流程開始，建立最基本的整理規則③鼓勵逐步加入「讓自己少找東西」的小習慣，而不是一次要求全面大改。"], "dont": ["禁止：①直接貼上「邋遢」「沒組織」的標籤②忽略工作環境、工具與流程本身的雜亂③在未給予任何結構支援下，要求與高度條理者一樣的標準④以此分數否定其在專業或創意上的價值。"]}', 'CIA', '你比較不會特別想要把每件事都歸檔好、標好，多半是要用到的時候才去找、才處理。', '低分不等於混亂，可能是討厭被流程綁住；管理重點在必要秩序而非全面流程化。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (421, 'CIA_07', 'A', 76, 100, '品質苛求', '對細節與品質要求高，會反覆檢查與優化以達到無瑕疵；在高標準場景能顯著提升可靠度。', '適合品質把關、重要交付、品牌/法遵/對外文件等；可作為最後審稿者。', '對成果品質與細節有高度在意，容易把標準拉在相對嚴格的位置，會不斷微調、修正，直到接近心中理想狀態。', '{"do": ["可用於：①說明其在品質控管與精緻輸出上的優勢②建議在關鍵輸出（如對外簡報、正式文件）善用其高標準③鼓勵一開始先區分「需要完美」與「夠好就好」的情境，避免耗損過多心力。"], "dont": ["禁止：①把其完美傾向視為無限壓榨的理由②忽略時間與資源限制，只要求結果「零失誤」③用個別小缺點否定整體努力④鼓勵長期熬夜或超時工作來維持完美表現。"]}', 'CIA', '你常會一改再改，只因為覺得「還可以更好一點」，對小瑕疵也比較看得見、放不太下。', '高分常伴隨時間成本與焦慮；需明確定義夠好標準避免過度打磨。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (422, 'CIA_07', 'B', 51, 75, '品質平衡', '在重要任務會提高標準，但能在時間/資源限制下做取捨；品質與效率之間較能取得平衡。', '採分級品質策略（關鍵件高標、一般件可接受）能發揮最大效益；適合專案推進。', '在重要任務上會希望成果好看、站得住腳，但也能在時程或資源有限時接受「足夠好」，不會在所有細節上都追求極致。', '{"do": ["可用於：①說明其在品質與效率之間的彈性拿捏②建議在專案啟動時就與團隊對齊品質標準與優先順序③鼓勵維持這樣的平衡，而不是被環境推向過度完美或過度隨便。"], "dont": ["禁止：①因為不「事事追求極致」就說「不夠用心」②忽略限制條件（時間、人力、資訊）③用他人極端完美標準要求其配合④將小失誤解讀為態度不佳。"]}', 'CIA', '你會看事情的輕重來決定要多講究：重要的東西會盡量做到好、不丟臉，其他就做到合理水準即可。', '此區間管理關鍵在明確指引哪些要完美、哪些要完成。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (423, 'CIA_07', 'C', 0, 50, '完成優先', '更重視推進與交付，細節品質通常做到可用即可；在快速迭代場景有效率，但可能忽略小錯累積。', '適合 MVP、試點、快速產出；需搭配檢核/測試/他人 review 避免品質風險放大。', '對小細節瑕疵的容忍度較高，做事更在意整體完成與可運作，而不會為了打磨到完美而卡住進度，偏向「先有再優化」的風格。', '{"do": ["可用於：①指出其在快速迭代、原型開發或試錯情境中具有優勢②建議搭配對細節敏感的成員，共同平衡整體品質③鼓勵在重大、一次性輸出時，稍微拉高檢查標準以降低風險。"], "dont": ["禁止：①把這種風格直接等同於「隨便」「沒品質概念」②忽略職務本身是否真需要極高完美標準③在未說清楚品質期待前事後責怪④以單一缺失否定其整體貢獻。"]}', 'CIA', '你比較在意事情有完成、能用，而不是所有細節都要無可挑剔，對不影響結果的小地方會放得比較鬆。', '低分不等於粗糙，可能策略性先上線再修；需確認補救機制。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (424, 'CIA_08', 'A', 81, 100, '勝任自信', '對自身能力與掌控感較有信心，遇到挑戰願意承擔並主動找方法；較少因不確定而退縮。', '適合需要自主判斷、獨立推進與對外代表的角色；可賦予較高授權與主責範圍。', '普遍對自己的能力與影響力抱持信心，相信只要有時間與資源，大多數挑戰都能找到解法並處理好。', '{"do": ["可用於：①說明其在承接新任務、面對變動與帶頭嘗試方面的優勢②建議提供具挑戰但可達成的機會，讓其把勝任感轉化為實際成果③提醒在高自信下仍要留意資源與現實限制，避免壓力累積。"], "dont": ["禁止：①把其自信當成不需支援的理由②在結果不理想時，用更高標準回頭指責「你不是很有能力嗎」③期待其一個人扛起所有困難專案④將自信與自負簡化為同一件事。"]}', 'CIA', '你多半會覺得「給我一點時間，我可以搞定」，面對新挑戰比較容易採取「先試試看」的態度。', '高分不等於永遠正確；仍需回饋迴路避免過度自信造成盲點。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (425, 'CIA_08', 'B', 61, 80, '需要確認', '能力多半足夠，但在新領域或高風險任務會希望獲得確認；得到支持後能穩定輸出並逐步建立信心。', '提供可求助窗口、階段性肯定與清楚成功標準能快速拉升；適合導師制或同儕合作下成長。', '面對熟悉或曾經成功過的任務時，普遍有一定把握；遇到全新、複雜或風險較高的挑戰時，會在意資源、支援與方向是否明確。', '{"do": ["可用於：①說明其勝任感與經驗、準備程度及環境支持高度連動②建議在新任務前提供清楚目標、學習資源與可詢問對象③鼓勵回顧自己過去克服困難的經驗，讓信心不只綁在熟悉領域。"], "dont": ["禁止：①把謹慎與確認解讀為「沒信心」②忽略制度、資訊與支援不足對其心理狀態的影響③只用「你要相信自己」簡化問題④用單一挫敗經驗否定其能力。"]}', 'CIA', '對你做過、熟悉的事情會覺得「這個可以」，但遇到完全陌生的挑戰，就會想先搞清楚「有人可以問嗎？資源夠嗎？」。', '此區間常被誤判為不自信；其實偏審慎，需要明確標準與回饋。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (426, 'CIA_08', 'C', 0, 60, '信心不足', '容易懷疑自己是否能做好，遇到不確定任務可能遲疑或依賴他人決定；需要更多安全感才敢推進。', '以小步成功累積並提供明確指引與正向回饋；避免一開始就丟高風險責任。', '面對挑戰時較容易先想到「我可能不行」或「別人比較適合」，對自己能否處理好事情的把握度較低，需要更多具體支持與成功經驗累積。', '{"do": ["可用於：①指出其在勝任感上需要更多具體回饋與小步成就來建立自信②建議主管在分派新任務時拆小步驟、給清楚指引與即時肯定③鼓勵其將「沒做過」與「做不到」分開看，避免預先放棄。"], "dont": ["禁止：①貼上「沒自信」「太弱」的標籤②忽略過往負面回饋或失敗經驗對其信心的影響③用嘲諷或比較逼其「振作」④依此分數斷定其不適合作為培養對象。"]}', 'CIA', '你有時會先懷疑自己「真的可以嗎？」，會覺得別人可能會做得比自己好。', '低分不等於能力差，可能受過往經驗或環境回饋影響；建議搭配行為證據判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (553, 'SPA_15', 'A', 66, 100, '硬派衝刺', '企圖心強、想把成果做到最好，容易自我加碼並追求更高成就，遇到目標會想往上拉。', '適合高成長、高目標團隊；可給關鍵客戶、挑戰案與升級路徑，並提供資源支援。', '目標感強、傾向自我加碼並追求更高成就，能在高目標環境中快速推進；但若缺乏界線與節奏管理，可能出現過度衝刺、耗損或忽略協作。', '{"do": ["給具挑戰但可落地的升級路徑；提供資源/權限讓你真正能達成；建立節奏（週檢核＋補能）並明確協作規則"], "dont": ["不要只加目標不給資源；不要讓你長期超載卻沒有停損；不要默許「只要結果」而忽略合作成本"]}', 'SPA', '你很容易自己把標準拉更高、越做越想做到最好；只要資源到位、路徑清楚，你會跑得非常快。', '高分需注意過度衝刺導致耗損或忽略協作；要搭配節奏與界線。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (427, 'CIA_09', 'A', 76, 100, '延宕誘惑', '能為了長期目標延遲滿足，面對短期誘惑仍可維持節奏與自我約束，較少因一時舒服而偏離計畫。', '適合長期推進、重複投入與自我管理任務；可交付需要持續交付的工作。', '能長期維持自訂節奏，為了重要目標安排時間、抗拒短期干擾，即使沒有人盯，也會自己推進到位。', '{"do": ["可用於：①說明其在長期專案、自我成長與習慣養成上的穩定度②建議安排需要持續投入與高度自主管理的任務③鼓勵在自律與彈性之間保留調整空間，避免把自己綁太死。"], "dont": ["禁止：①把其自律當成無限加工作量的理由②忽略其同樣會感到疲憊與需要休息的事實③將偶爾鬆動解讀為「變懶」④假設其完全不需要外在支持系統。"]}', 'CIA', '就算沒有人催，你也會照著自己的計畫去做，一點一點往長期目標前進。', '高分反映抗誘惑與持續性，不等於天生意志力強，也可能是習慣建立良好。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (428, 'CIA_09', 'B', 51, 75, '情境自控', '在目標清楚或環境支持下能維持自律，但在壓力大、干擾多或缺乏回饋時，容易出現鬆動與拖延。', '用短週期里程碑與外部承諾機制（回報、共學、檢核點）提升持續性。', '在有期限、有人一起推進或會被檢核的任務上，多能穩定完成；對完全自訂、沒人關心的長期目標，則較容易被日常瑣事打斷。', '{"do": ["可用於：①說明其自律表現與外在結構（時程、檢核、他人參與）高度相關②建議透過結伴、定期回顧或公開承諾來支援長期目標③鼓勵將大目標拆小步驟，減少拖延與中斷。"], "dont": ["禁止：①把需要外在結構的特性簡化為「沒意志力」②忽略制度與工作設計對行為的影響③只用指責回應延誤，而不協助重整計畫④用短期狀態推論其長期人格特質。"]}', 'CIA', '如果有交件時間、或有人一起跟進進度，你會比較穩；但是對那種「沒人管、很長期」的計畫，就容易被其他事情插隊。', '此區間常見於需要結構才穩的型態；重點是支持設計而非道德評價。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (429, 'CIA_09', 'C', 0, 50, '短期拉扯', '較容易被短期誘惑牽動，明知道長期目標重要仍可能在當下選擇立即回報；自律維持較吃力。', '拆小任務、降低啟動成本並用環境設計減少誘惑；以明確獎勵建立習慣。', '在維持固定節奏與長期計畫上較有難度，行動常受當下心情、突發事件或環境干擾影響，計畫與實際執行之間容易出現落差。', '{"do": ["可用於：①指出其在需要高度自律的任務中，必須透過工具與環境設計來補強②建議採用「短時段、短目標、多次重新開始」的方式，而不是一次逼自己完美堅持③鼓勵尋找適合自己的支持系統（例如夥伴約定、提醒工具）。"], "dont": ["禁止：①批評為「沒自制」「不長進」②忽略心理狀態、壓力或生活變動對執行力的影響③要求一次性徹底改變而不提供漸進方案④以此分數否定其負責任或成長的可能性。"]}', 'CIA', '你可能常常有計畫，但實際要照著做會覺得很容易被打斷或被別的事情帶走。', '低分常見於目標模糊、能量不足或干擾過強；先改善情境再談自律。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (430, 'CIA_10', 'A', 76, 100, '誠正節制', '在利益與目標可見的情境下仍能維持誠懇與公正，對財富、地位與特權不會過度執著，也較少炫耀或佔便宜。', '適合需要高度信任的工作（資源分配、敏感資訊、合規與治理）；可作為文化示範者。', '整體價值觀傾向重視誠實、公平與謙遜，對貪圖不當利益、濫用特權或炫耀地位較為排斥。', '{"do": ["可用於：①說明其在信任、倫理與風險控管上的重要性②建議安排在需要高度誠信與長期信賴的職務（如金流、合約、關鍵客戶）③鼓勵組織在制度與文化上與其價值相符，減少價值衝突感。"], "dont": ["禁止：①以其高誠實謙遜為由，忽視公平報酬與合理待遇②在制度不公時只要求個人「要有道德」③把其視為可無限承受價值衝突的防火牆④假設其永遠不會做出錯誤判斷。"]}', 'CIA', '你在意事情是不是光明正大，也不喜歡靠關係或特權撈好處，對炫耀財富或地位的行為比較不買單。', '高分不等於不競爭，而是競爭方式較重視正當性與長期信任資本。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (431, 'CIA_10', 'B', 51, 75, '原則彈性', '多數時候能維持公平與誠實，但在強壓績效或利益衝突下，可能在達標與原則間做權衡。', '把不可妥協底線講清楚（利益揭露、流程透明），並提供可行達標路徑。', '整體而言重視誠實與公平，但在壓力大、競爭激烈或灰色地帶情境中，會同時在意現實與原則，試圖在兩者之間找平衡。', '{"do": ["可用於：①說明其價值觀與現實考量之間的拉扯狀態②建議組織釐清倫理底線與可接受做法，減少個人單獨承擔的壓力③鼓勵在困惑情境中透過對話，而不是獨自吞下矛盾。"], "dont": ["禁止：①因其猶豫或折衝，就貼上「不誠實」標籤②忽略文化、獎酬與權力結構對行為的影響③用道德壓力掩蓋制度缺陷④把單一次的妥協視為長期人格問題。"]}', 'CIA', '你基本不喜歡不公不義的事，但在壓力很大或大家都這樣做的情況下，也會掙扎「這樣是不是還能接受」。', '此區間需看遇到誘惑時的選擇，不宜只用日常互動判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (432, 'CIA_10', 'C', 0, 50, '利益傾斜', '較容易重視利益、地位或外在象徵，可能合理化先拿到再說的做法，對公平與謙遜的自我要求較弱。', '在規範清楚、權限可追溯的環境運作；加強監督、審核與利益衝突管理。', '對財富、特權與自身利益的重視度較高，在作決定時容易優先考量「對自己是否划算」，對利用規則邊界或強調自身地位的接受度較高。', '{"do": ["可用於：①指出其在強競爭、高獎酬環境中可能具有推進成果的動力，但需要明確的倫理與合規框架②建議透過制度設計與監督機制，界定可接受與不可跨越的行為界線③鼓勵其思考長期信任與聲譽對自身利益的影響。"], "dont": ["禁止：①直接將其等同於「不誠實」「會做壞事」②忽略組織獎勵結構對價值偏移的影響③以羞辱方式處理價值議題，而不提供具體標準與討論空間④把此分數視為其必然會違法或嚴重失當的預測。"]}', 'CIA', '你會比較在意自己有沒有得到應得甚至更多的好處，對於運用關係、資源或規則邊邊角角，會覺得只要不太過就是合理手段。', '低分不等於一定不誠信，但風險較高；建議搭配情境題與行為證據。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (433, 'CIA_11', 'A', 76, 100, '直率不操弄', '較少為了達成目標去操縱或欺騙他人，溝通偏直接透明，傾向用真實資訊建立合作。', '適合互信與長期合作情境（跨部門、客戶關係、治理）；可降低猜疑與內耗。', '在人際互動上偏好以真誠、直接的方式溝通，不太傾向刻意操弄、隱瞞或欺騙他人來達成目的。', '{"do": ["可用於：①說明其在建立深度信任與長期關係上的優勢②建議讓其參與需要穩定、真誠互動的合作與夥伴關係管理③鼓勵在保持誠懇的同時，也學會適度保護自己，不被過度要求透明。"], "dont": ["禁止：①期待其在任何情境都完全坦白而不顧自身風險②忽略組織政治與權力現實③將必要的策略性表述誤解為不誠懇④把偶爾的保留視為人格反轉。"]}', 'CIA', '你多半是「怎麼想就怎麼說」，不太喜歡用話術或欺騙的方式來達成目標。', '高分不代表不會談判；是更傾向資訊透明而非話術操作。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (434, 'CIA_11', 'B', 51, 75, '策略拿捏', '多數時回應誠懇，但在競爭、壓力或政治情境中，可能用較策略性的表達方式保護自身立場。', '提供清楚溝通規範（哪些可保留、哪些必須公開）與協作準則，維持信任又不失彈性。', '整體不偏好欺騙或操弄，但在敏感、權力不對等或關係脆弱的情境中，會斟酌要說多少、怎麼說，以兼顧真實與關係。', '{"do": ["可用於：①說明其在誠懇與情境顧慮之間維持某種平衡②建議釐清組織對資訊透明與保密的實際期待，降低個人壓力③鼓勵在不安時尋求對話，而不是一味壓抑或過度隱瞞。"], "dont": ["禁止：①把策略性保留一概解讀為「不老實」②忽略法律、商業機密與角色責任對發言空間的限制③用理想化標準要求其在任何情境完全透明④用單一事件否定其整體誠懇度。"]}', 'CIA', '你大多數時候會說實話，但在某些場合也會想「怎麼講比較不會傷人或惹麻煩」，不一定全部攤開講。', '此區間重點在界線與一致性；規則模糊時容易被誤讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (435, 'CIA_11', 'C', 0, 50, '目的導向', '較容易把包裝或操弄視為達成目標的工具，可能選擇性揭露或用話術影響他人判斷。', '需在透明流程與稽核機制下運作；在客戶/治理領域需更嚴格行為規範。', '對於「只說對自己有利的一部分」或美化資訊的接受度較高，溝通常被視為推進目標的工具，而非單純交換真實狀態的管道。', '{"do": ["可用於：①指出其在談判、銷售與需要強勢說服的場域可能具優勢，但須留意長期信任與誠信風險②建議透過明確規範與例外情境說明，界定不能被犧牲的誠信底線③鼓勵其思考「短期成交」與「長期信任」之間的取捨。"], "dont": ["禁止：①直接等同於「騙人」「不可信」②忽略組織本身對短期成效的高度壓力③只用道德批判要求其改變，而不提供具體示例與學習資源④用此分數斷言其一定會嚴重違反誠信。"]}', 'CIA', '你可能會覺得強調優點、淡化缺點是很正常的做法，重點是事情要推得動。', '低分代表風險訊號；不等同人品評價，但管理建議以控風險為先。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (436, 'CIA_12', 'A', 75, 100, '重價值不重物', '相對不把財富與地位視為主要追求，決策更看重意義、成長或關係品質，較不易被物質誘因牽動。', '適合使命導向或長期投入工作；激勵方式偏成就感、自主與成長資源。', '對金錢、頭銜與外在排場的重視度相對較低，更傾向用意義感、關係與內在成就感來衡量一份工作值不值得。', '{"do": ["可用於：①說明其在追求有意義工作與內在報酬上的傾向②建議以成長機會、影響力與價值實現作為重要激勵來源③提醒組織仍須提供公平報酬，避免以「使命」為由忽略基本待遇。"], "dont": ["禁止：①以其低物質傾向為藉口壓低薪資或福利②用「你不是不看重錢嗎」來逼其接受不合理條件③假設其完全不在意物質生活品質④忽略其對基本安全感的正當需求。"]}', 'CIA', '你當然也需要收入，但不會只用「薪水多少、頭銜多大」來決定事情好不好，更在意內容是不是有價值。', '高分不代表不在乎薪酬，而是物質誘因邊際效果較低，需用不同激勵槓桿。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (437, 'CIA_12', 'B', 50, 74, '務實平衡', '能理解物質與地位的重要性，但不會完全被其主導；會在價值、生活需求與回報之間做合理取捨。', '清楚薪酬制度與可見成長路徑最有效；也能接受績效激勵但需要公平透明。', '既重視合理薪酬與生活品質，也會把工作內容、成長空間與環境氛圍納入考量，在物質與非物質報酬之間尋求平衡。', '{"do": ["可用於：①說明其在評估機會時會綜合考慮多面向②建議在職涯溝通時，同時談報酬、發展與意義感③鼓勵其清楚表達對薪資與環境的期待，而不是壓抑需求。"], "dont": ["禁止：①將對合理報酬的要求貼上「現實」「勢利」標籤②忽略市場行情與貢獻價值③只用理想或使命感要求其忽略物質條件④用此分數評價其人格高低。"]}', 'CIA', '你會希望薪水合理、生活過得去，但也知道「只看錢」不一定會快樂，會一起看內容、學習機會跟團隊氛圍。', '此區間通常彈性最高，重點在制度可信度，否則容易轉向比較。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (438, 'CIA_12', 'C', 0, 49, '高度物質導向', '較重視財富、地位或外在象徵，對回報敏感，可能把物質激勵視為投入與忠誠的主要交換條件。', '適合獎酬明確、成果可量化角色；避免模糊承諾，並以公平制度降低比較摩擦。', '對薪酬、福利、頭銜與外在認可的敏感度較高，容易把這些視為「有沒有被重視」的重要訊號，物質與地位在決策中占較大比例。', '{"do": ["可用於：①指出其在獎酬明確、競爭導向的環境中可能動機強勁②建議清楚解釋薪酬架構、升遷條件與獎勵機制，減少不確定感③鼓勵其同時培養對內在成就與專業成長的重視，讓滿足來源更穩定。"], "dont": ["禁止：①直接貼上「拜金」「很勢利」的標籤②忽略其過往可能被低估或不公平對待的經驗③用道德批評否定其對物質條件的要求④把此分數當作預測其一定會為利益犧牲原則的依據。"]}', 'CIA', '你會很在意待遇好不好、頭銜夠不夠看，以及別人怎麼看待你的位置，覺得這些都代表你有沒有被好好對待。', '低低物質傾向不等於貪婪，而是動機偏外在回報；管理關鍵在規則清楚。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (554, 'SPA_15', 'B', 31, 65, '有企圖但看回饋', '想變更好，但投入強度會隨資源、回饋與勝算評估調整；在看見成效時會明顯加速。', '用清楚成長路徑、里程碑與獎勵設計能提高企圖心；適合循序挑戰。', '具備上進心，但投入強度會依資源、回饋與勝算評估調整；若能看到清楚的成長路徑與可驗證成果，通常會明顯加速。', '{"do": ["用里程碑與獎勵設計讓成果可見；提供方法/腳本/案例降低不確定；把成長路徑說清楚並固定回饋節奏"], "dont": ["不要丟一個很大很空的目標；不要只有口頭鼓勵卻沒有衡量方式；不要在成效未現前就貼上「不夠拚」標籤"]}', 'SPA', '你想變更好，但你也很務實：看得到方法、看得到回報，你就會更願意投入、跑更快。', '此區間要避免目標過大又缺資源，容易造成動能下降。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (439, 'CIA_13', 'A', 76, 100, '原則守公平', '即使想領先或達成目標，仍傾向拒絕欺騙、偷竊、貪污或利用他人的手段，重視對等與規則一致。', '適合資源分配、制度設計、採購與治理等角色，提升信任與長期穩定。', '對公平與正義有強烈敏感度，對欺負弱勢、作弊或佔他人便宜的行為常會感到不舒服，傾向維護制度與互動中的公正。', '{"do": ["可用於：①說明其在維護制度正當性與團隊公信上的重要性②建議在流程設計、規則檢討與倫理議題中納入其觀點③提醒在高度不公情境下，其挫折與憤怒感可能更強，需要支持與對話空間。"], "dont": ["禁止：①把其對公平的堅持視為「不識相」或「太理想」②忽略組織結構與決策不透明對其壓力的影響③期待其單獨扛起對抗不公的任務④因其提出質疑就標籤為「麻煩人物」。"]}', 'CIA', '你看到明顯不公平的事情，會特別在意，覺得「這樣不太對」，也比較希望事情可以講求公道。', '高分不等於不競爭，而是競爭方式更在乎正當性與可被檢驗。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (440, 'CIA_13', 'B', 51, 75, '情境權衡', '大多願意遵守公平規則，但在強烈競爭或目標壓力下可能出現擦邊球心態，視環境容忍度調整行為。', '明確規則與後果（紅線、稽核、透明），並提供可行達標方法避免手段化。', '原則上不贊同不公平的作法，但在權力不對等、風險較高或氛圍緊繃的情境中，有時會選擇觀望、沉默或有限度表達。', '{"do": ["可用於：①說明其在價值與安全感之間的拉扯②建議建立安全管道（如匿名回饋、正式申訴流程），降低其發聲成本③鼓勵其在可掌握的範圍內練習表達，逐步累積為公平發聲的經驗。"], "dont": ["禁止：①把沉默直接解讀為「贊同不公」②忽略權力結構與心理安全感不足③用「你怎麼不早說」責怪其沒出聲④將一次沉默視為長期價值觀問題。"]}', 'CIA', '你會覺得公平很重要，但在現實複雜或講了可能對自己不利時，也會猶豫要不要出聲。', '此區間不可只看口頭價值觀，建議觀察利益衝突時的實際選擇。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (441, 'CIA_13', 'C', 0, 50, '手段傾向', '較容易把領先視為第一順位，可能合理化不公平手段或利用他人換取優勢。', '高風險領域需加強權限控管、雙人覆核與稽核；角色配置宜更謹慎。', '對「世界本來就不會完全公平」這件事接受度較高，傾向優先確保自己不吃虧，對制度或利益分配不均的敏感度相對較低。', '{"do": ["可用於：①指出其在高度競爭或差異報酬環境中可能較能適應，但也存在關係與文化風險②建議明確說清楚組織不可違反的公平底線③鼓勵其思考長期合作、信任與團隊士氣對結果的影響。"], "dont": ["禁止：①直接貼上「沒良心」「沒是非」標籤②忽略其可能曾經歷長期不公平而產生的防衛③只用指責要求其「要有正義感」④以此分數推論其一定會做出嚴重不公行為。"]}', 'CIA', '你可能會覺得，只要不要自己吃太大的虧，有些不那麼公平的事也還能接受，重點是顧好自己。', '低分是風險指標，建議搭配制度設計與行為觀察，不宜只靠溝通期待改善。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (442, 'CIA_14', 'A', 75, 100, '低自我中心', '對自身與他人的相對位置看法較平衡，不太需要透過炫耀或壓過他人來證明價值，較能接受他人貢獻。', '適合團隊協作、共同署名與跨部門合作，降低內耗與功勞爭奪。', '較自然地把自己視為團隊的一員，而非特別應該被優待的人，習慣低調表達貢獻，不會刻意凸顯自己。', '{"do": ["可用於：①說明其在團隊合作、學習與接納回饋上的優勢②建議在需要降低階級距離、建立信任氛圍的情境中善用此特質③鼓勵在合適場合也能清楚說出自己的貢獻，避免長期被低估。"], "dont": ["禁止：①因為其謙虛就忽略或壓低其成果與待遇②用「你很謙虛」包裝客觀上的不公平③期待其永遠把他人放在自己前面④用文化期待壓抑其合理的自我主張。"]}', 'CIA', '你不太會主動強調「我有多厲害」，也不太習慣要求特別待遇，比較傾向讓成果自己說話。', '高分不等於缺乏企圖心；可能是自我價值穩定，因此不需外顯證明。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (443, 'CIA_14', 'B', 50, 74, '自信含蓄', '能肯定自己但表達較保留；在需要展現影響力或爭取資源時，可能猶豫如何拿捏分寸。', '給明確發聲場域與表達框架（成果呈現、角色授權），提升影響力而不違背風格。', '整體能保持不誇大、不自我膨脹的態度，但在需要爭取機會或介紹自己的場合，也有能力適度呈現個人成果。', '{"do": ["可用於：①說明其在謙虛與自我行銷間較能拿捏分寸②建議在重要場合協助其更具體呈現亮點，以免低估自己③鼓勵持續維持這種彈性，不因環境壓力走向過度自貶或過度自誇。"], "dont": ["禁止：①因其在某些場合展現自信就批評為「不謙虛」②忽略角色本身對曝光與表現的要求③用單一互動經驗判斷其整體人格④要求其完全抹去自我存在感。"]}', 'CIA', '你平常不會特別炫耀自己，但如果需要投履歷、簡報或爭取機會，也能把自己做過的事講清楚。', '此區間易被誤判不積極；需分辨表達風格或缺乏主張。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (444, 'CIA_14', 'C', 0, 49, '自我凸顯', '較傾向強調自身貢獻與地位，可能把被看見視為重要需求，對他人表現的接受度較敏感。', '以透明功勞分配與評價制度降低衝突；安排在對外代表或競爭型任務可能更合適。', '較常覺得自己的付出與能力應該獲得更多關注與禮遇，習慣主動凸顯自身貢獻與重要性，期待被特別看見。', '{"do": ["可用於：①指出其在爭取資源、機會與可見度時的主動性優勢，但須留意團隊感受②建議透過具體回饋幫助其調整表達方式，讓自我肯定不至於壓過他人③鼓勵其在展現自己之外，也刻意練習看見與肯定周遭成員。"], "dont": ["禁止：①直接標籤為「自大」「目中無人」②忽略其過去可能長期被低估而需要用力爭取③用羞辱方式壓抑其自我肯定④以此分數推論其無法良好合作。"]}', 'CIA', '你可能會覺得「我做了這麼多，應該要被好好看見」，也會比較常主動提到自己的成果。', '低謙虛不必然負面，關鍵在是否影響合作與公平。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (445, 'CIA_15', 'A', 76, 100, '正向資源充沛', '具備較高的希望、效能感、韌性與樂觀傾向，面對挑戰能維持動能與信心，並把挫折視為可處理的問題。', '適合承擔轉型、開創、逆風推進與需要帶動士氣的角色；可作為團隊動能來源。', '整體心理資源相對充足，面對壓力與挑戰時，多半能帶著希望感、自信與韌性前進，把挫折視為可以調整與學習的機會。', '{"do": ["可用於：①說明其在變動環境與高壓任務中的心理支撐作用②建議擔任需要帶動士氣、面對不確定性的角色③提醒在照顧他人、當大家精神支柱的同時，也要有人照顧他。"], "dont": ["禁止：①把其心理資本視為可以無限加壓的本錢②用「你撐得住」忽略其困難或疲憊③期待其永遠保持樂觀不准低潮④視求助或疲倦為「不應該」。"]}', 'CIA', '你通常會覺得「雖然不一定順利，但總有辦法想出路」，對未來大多保有可以努力的感覺。', '高分不代表永遠不受影響，而是恢復力與自我再啟動能力較強；仍需資源與方向對齊。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (446, 'CIA_15', 'B', 51, 75, '可被激發', '一般狀態能保持正向，但在長期壓力或不確定下動能可能下降；獲得支持與看見進展後會回升。', '以清楚目標、可見進度、支持系統與正向回饋拉升狀態；適合穩健推進型任務。', '在一般情況下能保持一定程度的樂觀與復原，但遇到長期壓力、連續挫敗或高度不確定時，心理動能會明顯下降，需要外在支持與時間恢復。', '{"do": ["可用於：①說明其心理狀態與壓力總量與時間長度高度相關②建議安排合理恢復期與支持資源，避免長期處在高壓而不調整③鼓勵建立自己的紓壓與支持系統，在動能下降時有地方補充。"], "dont": ["禁止：①把在高壓之下的疲憊解讀為「不堅強」②忽略工作量、角色衝突與生活事件③只用「想開一點」簡化其困境④將偶爾低潮視為無法信任的理由。"]}', 'CIA', '多數時候你覺得還行，但如果壓力堆太久、事情一直不順，就會開始懷疑自己、覺得很累。', '此區間是環境敏感型；管理重點在打造可恢復節奏，而非要求更樂觀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (447, 'CIA_15', 'C', 0, 50, '資源不足', '較容易感到無力或悲觀，遇到挫折時動能下降較明顯，對未來期待感相對薄弱。', '先從可達成小目標建立成功經驗，搭配支持、教練式管理與壓力源盤點；避免一開始丟高不確定任務。', '對未來與自身影響力較容易抱持保留或悲觀態度，遇到壓力與挫折時，容易覺得「事情不會變好」或「自己也改變不了太多」。', '{"do": ["可用於：①指出其在面對壓力與變動時需要更多支持與成功經驗累積②建議透過小而具體的目標與逐步成就感，慢慢擴大心理資源③鼓勵組織提供安全嘗試與允許失敗的空間，而非只要求「要正向」。"], "dont": ["禁止：①將其標籤為「負面」「難帶」②忽略過往挫折、資源不足或系統問題對其心理狀態的影響③用雞湯或責備要求其立刻樂觀④以此分數判定其不適合承擔重要任務。"]}', 'CIA', '你可能比較常先看到困難或風險，對「事情會好轉」「我辦得到」這類想法沒有那麼自然。', '低分常與環境、壓力與過往經驗相關；不宜貼負面標籤，建議結合近期行為判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (448, 'CIA_16', 'A', 81, 100, '目標路徑清晰', '能把目標具體化，並同時具備推進動機與替代路徑思考；遇到阻礙時能改道而不放棄。', '適合策略化推進、拆解路徑與持續優化的任務；可負責專案規劃與排除障礙。', '對未來有相對清晰的目標感，也能思考多條可行路徑，遇到阻礙時傾向調整做法而不是放棄方向。', '{"do": ["可用於：①說明其在目標設定與路徑規劃上的優勢②建議參與中長期計畫與改善專案的設計與推進③鼓勵在修正路徑時，同步檢視目標是否仍符合自身價值與現實。"], "dont": ["禁止：①期待其永遠保持清晰方向、從不迷惘②用「你不是很有目標嗎」壓過其目前困境③忽略資源與外部環境對達成目標的影響④將短暫失去動力視為不被允許。"]}', 'CIA', '你大概知道自己要往哪裡走，也會想「那如果這條路不通，可以怎麼繞過去」。', '高分不是空泛正向，而是目標感與路徑感並存；可觀察其是否具備備案思維。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (449, 'CIA_16', 'B', 61, 80, '動機可續航', '有目標動機，但路徑規劃有時需要外部引導；當方法不順時可能卡住，重新對齊後能再推進。', '用路徑拆解、選項清單與障礙排除會議提升連續性；適合在有策略框架的團隊成長。', '對未來大致有想像或方向，但在具體步驟與策略上仍在摸索，遇到環境變化或挫折時，較容易感到卡住，需要更多討論與陪伴釐清。', '{"do": ["可用於：①說明其在願景與路徑之間存在過渡期②建議提供職涯諮詢、導師制度或教練式對話，協助把方向拆成可行步驟③鼓勵從短期可實踐的小目標開始，降低不確定感。"], "dont": ["禁止：①將其猶豫解讀為「沒目標」「沒企圖心」②忽略機會結構與資訊不對稱③只用「自己要想清楚」回應其困惑④以此分數否定其長期發展。"]}', 'CIA', '你大概知道想成為什麼樣的人，但「要怎麼走到那裡」有時還不太確定，遇到變化就會更猶豫。', '此區間關鍵在卡住時怎麼辦；提供替代方案模板比單純打氣有效。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (450, 'CIA_16', 'C', 0, 60, '路徑不足', '可能有想達成的目標，但較難把動機與策略化路徑連結；遇到阻礙時容易停滯或轉向。', '先建立短期可達成目標與清晰下一步，搭配教練式提問與資源支持，逐步建立路徑思考能力。', '目前較難具體描述長期想追求的目標，對未來多半停留在模糊或「先顧好眼前再說」的狀態，較少主動規劃遠期方向。', '{"do": ["可用於：①指出其可能正處於「優先處理當下」的階段②建議透過探索活動、不同嘗試與陪談，一點一點幫助其長出較有個人感的目標③鼓勵從短期小目標開始，讓「未來可以被塑造」的感覺慢慢變清楚。"], "dont": ["禁止：①標籤為「沒未來性」「沒理想」②忽略其現實壓力、資源或資訊限制③用批判或嘲諷逼其立即說出長期藍圖④把此分數視為固定且不可改變。"]}', 'CIA', '你現在可能比較多在處理眼前的事，要說很清楚的長期目標，會覺得有點遙遠或抽象。', '低分不等於沒有企圖心，常見缺乏方法感或過往受挫；管理重點在給路徑而非叫他有希望。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (451, 'CIA_17', 'A', 76, 100, '敢承擔會達成', '對努力能換來結果有明確信心，遇到高標目標傾向主動拆解與推進，較不容易因不確定而退縮。', '適合推進型任務與需要自我驅動的角色；可給較高自主權並期待自我解題。', '面對具有挑戰的目標時，多半相信「只要我願意投入，就有機會做到」，傾向主動拆解目標並推進，而不是因不確定而退縮。', '{"do": ["可用於：①說明其在承接挑戰性任務與帶頭推進方面的潛力②建議提供明確標準與資源，讓其效能感轉成具體成果③提醒在失敗時，不要把所有責任全往自己身上扛，以免效能感反向受損。"], "dont": ["禁止：①把其高效能感視為可以忽略支援與環境條件的理由②在結果不佳時，以更重的道德壓力批評「你本來就做得到」③期待其一人填補所有制度缺口④用短暫挫折推論其信心已崩壞。"]}', 'CIA', '你看到高標目標時，比較容易想「可以怎麼做」而不是「這太難」。', '高分不等於判斷一定正確；仍需回饋迴路避免過度自信。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (577, 'CSR_05', 'A', 76, 100, '擁抱變化', '在高度不確定與頻繁變動的環境中也能自然將變化視為常態，持續從中獲取動能，不需額外調適就能保持開放。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (578, 'CSR_05', 'B', 51, 75, '選擇性接受', '在變化有合理脈絡時能將其視為成長機會，若變動頻繁且方向不明，會優先尋求穩定再評估是否投入。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (579, 'CSR_05', 'C', 0, 50, '偏好穩定', '傾向將穩定與可預測視為理想狀態，面對變化或未知時容易產生不適，較少將變動視為成長機會。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (580, 'CSR_06', 'A', 76, 100, '全心投入', '對自身興趣與價值觀的認同不受環境逆境影響，各種條件下都能維持全心融入，歸屬感與投入程度十分穩定。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (452, 'CIA_17', 'B', 51, 75, '需要確認再加速', '能力感多半足夠，但在新領域或高風險情境會希望先確認方向；一旦標準清楚就能穩定輸出。', '以成功標準、階段檢核與教練式回饋拉升信心與速度；適合在導師制團隊中成長。', '對熟悉或曾經成功的類型較有把握，遇到全新領域或高風險任務時，會先關注方向是否正確、支援是否足夠，再決定要投入多少。', '{"do": ["可用於：①說明其效能感與「掌握度」高度相關②建議在新任務上提供導入說明、示範與可詢問對象，縮短不確定期③鼓勵其把過去克服困難的經驗帶到新的情境中，協助建立信心。"], "dont": ["禁止：①將謹慎視為「沒自信」或「不敢扛責」②忽略資源與資訊不足對投入意願的影響③只用「你要勇敢試」而不調整外在條件④以此分數否定其接新角色的可能性。"]}', 'CIA', '對你有經驗的事情會覺得「OK，這可以試」，但對完全沒碰過的，你會先觀察、確認再全力衝。', '容易被誤讀為不自信；其實是對不確定敏感，需要清晰度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (453, 'CIA_17', 'C', 0, 50, '容易自我懷疑', '對能否完成目標缺乏把握，面對挑戰可能遲疑、過度求證或依賴他人決策，影響推進節奏。', '用小步成功累積、降低啟動門檻並提供明確指引與正向回饋；避免一開始就丟高不確定責任。', '對「即使努力也未必成功」的感受較強烈，面對較大的目標時容易預期失敗，因而降低投入意願或傾向選擇風險較低的選項。', '{"do": ["可用於：①指出其效能感可能受過往「努力與結果落差」經驗影響，需要透過小成功經驗重新建立②建議設計可控性較高、步驟清楚的目標，減少徒勞感③鼓勵其記錄具體的進步與做到的事情，而不是只放大失敗。"], "dont": ["禁止：①把其保守選擇簡化為「不努力」②忽略機會不均、資源限制與系統問題③用嘲諷或比較方式施壓「你要有自信」④把此分數視為無法恢復的信心問題。"]}', 'CIA', '你可能常會想「就算我很努力，也不一定有用」，所以會選擇比較安全、不會太冒險的做法。', '低分不等於能力差，常與過往經驗與環境回饋相關；建議結合行為證據。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (454, 'CIA_18', 'A', 71, 100, '逆境復原快', '遇到壓力、衝突或失敗後能快速回到可工作狀態，並把打擊轉成修正與補救行動。', '適合高壓前線、轉型推進、責任變更頻繁角色；可作為續航與穩定支點。', '面對壓力、挫折或變化時，雖然會受影響，但多能在合理時間內調整心態、找到因應方式並回到可運作狀態。', '{"do": ["可用於：①說明其在變動環境與高壓任務中的復原能力②建議在變革或關鍵專案中安排其扮演穩定力量的角色③提醒組織不要因其韌性而忽略資源、人力與休息配置。"], "dont": ["禁止：①把其韌性當成可以無限加壓的理由②用「你撐得住」忽略其耗損③假設其永遠不會出現耗竭或低潮④在其提出需要幫忙時感到「意外」並責怪。"]}', 'CIA', '你遇到打擊時也會難過或累，但通常可以慢慢整理好，再站起來繼續往前。', '高分不代表不會受挫，而是恢復與再啟動速度快；仍需休息節奏。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (455, 'CIA_18', 'B', 41, 70, '恢復需要時間', '受到壓力時會有明顯影響，但在獲得支持、釐清方向後能逐步回穩；表現受情境差異影響。', '以合理節奏、同儕支持與階段里程碑降低負荷；適合穩健推進配置。', '面對壓力與打擊時會明顯受影響，需要時間與支持才能恢復，但在方向釐清、支持到位後，多能逐步回穩。', '{"do": ["可用於：①說明其恢復速度與壓力強度、持續時間及支持程度高度相關②建議在高壓階段預先安排緩衝與支援機制③鼓勵其把需要幫助視為正常反應，而不是弱點。"], "dont": ["禁止：①把在高壓下恢復較慢解讀為「抗壓性差」②忽略工作與生活中長期壓力來源③只用「要想開」而不處理結構問題④把一次的低潮視為不能再被信任。"]}', 'CIA', '壓力大或事情不順時，你會真的累、真的被影響，但如果有人陪你理一理、環境調整一下，慢慢就能再起來。', '重點看觸發點與修復方式，比單看情緒反應更準。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (456, 'CIA_18', 'C', 0, 40, '耗損累積快', '在長期高壓或連續變動下容易出現能量耗竭，補救與恢復較吃力，表現波動可能增大。', '設計緩衝與分工、避免長期獨撐；用復盤與支持資源提升挽救能力。', '長期或高強度壓力較容易累積成耗損感，一旦被壓垮，恢復需要較多時間與資源，情緒與表現波動也相對明顯。', '{"do": ["可用於：①指出其在長期高壓環境中的風險，需要特別留意工作設計與負荷管理②建議建立穩定的支持系統（如信任的人、專業資源、自我照顧習慣）③鼓勵用溫和、不評價自己的態度面對脆弱，從中練習新的調適方式。"], "dont": ["禁止：①把其狀態標籤為「玻璃心」「不抗壓」②忽略組織在壓力管理與資源配置上的責任③用比較與羞辱逼其「硬起來」④以此分數作為不適合培養或信任的理由。"]}', 'CIA', '你在壓力很大或變動很多的時候，會感覺自己很快就被用完電，要花很久才補得回來。', '低分不等於抗壓差，而是對壓力敏感；重點在降低耗損而非硬扛。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (457, 'CIA_19', 'A', 81, 100, '把不順視為暫時', '對挫折的解釋偏向可改善、可轉機，較能維持希望感與行動力，不易被單次失敗打垮。', '適合帶動士氣、在不確定中推進的任務；可作為團隊動能來源。', '看事情時比較容易先看到可能性與希望，面對挫折也傾向解讀為暫時的阻礙，而不是全面否定自己或未來。', '{"do": ["可用於：①說明其在壓力與變動中維持希望感與行動動能的能力②建議在變革、轉型或高不確定專案中，善用其穩定團隊士氣的特質③鼓勵把樂觀轉化為行動計畫，而不是只停留在「應該會好」的想像。"], "dont": ["禁止：①把其樂觀看成「什麼都不怕」而不討論風險②用樂觀掩蓋現實問題或資源不足③在對方感到沮喪時，用「你不是很樂觀嗎」否定其當下感受④暗示只要樂觀就不需要制度與支援。"]}', 'CIA', '你通常會覺得「雖然不順，但應該還有辦法」，比較少因一次挫折就對一切失去信心。', '高分不等於盲目正向；仍需風險評估避免忽視限制。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (458, 'CIA_19', 'B', 61, 80, '現實中保有期待', '多半能保持正向，但在連續不順或高壓時會短暫消沉；看見進展與資源後能恢復。', '以可視化進度、明確下一步與支持系統維持動能；適合穩健節奏。', '面對多數情況時能維持基本正向看法，但在連續挫折或高度不確定時，心情與信心會隨情境明顯波動。', '{"do": ["可用於：①說明其樂觀程度與事件頻率、壓力強度高度連動②建議在關鍵階段提供資訊透明與具體進展，減少不必要的悲觀解讀③鼓勵透過記錄小成功、與他人對話來調整看事情的角度。"], "dont": ["禁止：①把偶爾的低落解讀為「很負面」②忽略環境與事件累積對其心態的影響③只用「想開一點」要求其振作，而不處理問題本身④把樂觀程度簡化為個人意志力強弱。"]}', 'CIA', '一般情況下你還算樂觀，但如果連續遇到不順或變化太多，就會比較容易懷疑「真的會好轉嗎」。', '此區間需要可見的改善路徑，比單純鼓勵更有效。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (459, 'CIA_19', 'C', 0, 60, '容易悲觀解釋', '傾向把不如意視為長期且普遍，可能降低嘗試意願與抗挫力，遇阻礙容易預期失敗。', '從可控小目標建立成功經驗，搭配教練式提問與資源支持；避免長期無回饋任務。', '在面對壓力、變動或不確定時，較容易先想到可能的風險與失敗結果，對「事情會變好」的想像較不自然。', '{"do": ["可用於：①指出其在風險覺察上具敏感度，但也較容易陷入悲觀循環②建議引導其平衡「最壞情境」與「可行對策」，從可控部分著手③鼓勵透過具體行動與小成果，慢慢修正「事情都不會變好」的內在腳本。"], "dont": ["禁止：①直接貼上「負面」「愛抱怨」標籤②忽略其過往挫折或資源不足對世界觀的影響③用雞湯式鼓勵要其立刻變樂觀④把此分數當作不適合承擔重要任務的單一依據。"]}', 'CIA', '你可能常會往壞的方向先想，對「一切會順利」這種說法會抱持懷疑，覺得還是要準備最壞的打算。', '低分常與環境連續挫敗相關；需結合近期事件脈絡判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (460, 'CIA_20', 'A', 76, 100, '主動挑戰框架', '喜歡用新方法做事，會主動發現問題、提出替代解法並挑戰主流規則，不易被既有慣例限制。', '適合探索、轉型、產品/流程革新；放在發想與實驗段落發揮。', '遇到問題時自然會往新方法、新角度思考，不太滿足於「一向都這樣」，喜歡在限制中找到創新的突破口。', '{"do": ["可用於：①說明其在創新專案、流程改善與新服務設計上的潛力②建議安排有空間試驗與迭代的任務，讓其創意能真正落地③鼓勵同時學會評估風險與成本，讓創新不只好玩也具可行性。"], "dont": ["禁止：①把其創新力當成無限「幫忙發想」的資源，而不給實驗空間②把所有守規或穩定作法都貶低為「不創新」③忽略其創意實作所需時間與支援④要求其在高度僵化環境下仍源源不絕產出新點子。"]}', 'CIA', '你很少只照舊做，看到問題會想「有沒有更好的做法」，也樂於試試不同的點子。', '需明確界定可試與不可碰紅線（合規/安全）。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (461, 'CIA_20', 'B', 51, 75, '改良式創新', '願意提出新點子，但多從現有流程中找改良機會；限制明確時更容易產出可落地方案。', '給清楚目標與限制條件並搭配原型驗證，提升落地率；適合改善型任務。', '在熟悉範圍內遇到問題時，偶爾會提出不同作法；但若風險較高或規則限制較多時，會傾向先確認安全做法再談創新。', '{"do": ["可用於：①說明其創新傾向受情境安全感與資源影響②建議提供明確框架（哪些可試、哪些是底線），讓其較敢提出改進想法③鼓勵在小範圍試驗、A/B 測試中練習把點子變成具體行動。"], "dont": ["禁止：①把不主動「顛覆一切」解讀為「沒創意」②忽略文化氣氛與主管態度對其創新意願的影響③只在出問題時要求其「想點新招」④以少數不成功的嘗試否定其創新能力。"]}', 'CIA', '你有靈感時也會想試試新方式，但會看場合、對象與風險，通常不會貿然大改。', '常是最佳落地者；管理關鍵是提供空間與資源。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (462, 'CIA_20', 'C', 0, 50, '慣例優先', '較偏好沿用成熟做法，面對新方法可能先觀望；創新動機較低但穩定性較高。', '適合標準化與高一致性作業；推動創新可先小規模試點降低不確定。', '做事風格較偏向沿用既有作法與慣例，面對「完全沒做過的嘗試」會感到遲疑或擔心風險，對創新本身不一定感到興奮。', '{"do": ["可用於：①指出其在需要穩定執行、流程遵循的工作上可提供穩定度②建議若希望其參與創新，先從「微調現有流程」而非大幅顛覆開始③鼓勵用逐步嘗試與明確風險控管，降低對創新的不安感。"], "dont": ["禁止：①貼上「保守」「沒創意」的單一標籤②在未提供資訊與支援下強迫其快速接受大變革③忽略其對穩定與可預測性的合理需求④用此分數否定其在改善與優化上的貢獻可能。"]}', 'CIA', '你比較習慣照既有方式把事情做好，對那種完全沒試過的新做法，會先想到風險和麻煩。', '低分不代表沒創意，可能風險偏好較低；用安全試錯機制引導。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (463, 'CIA_21', 'A', 76, 100, '跳脫程序求快', '高度在意更快更省更有效，不喜歡被程序綁住，會用不同角度簡化流程以達成結果。', '適合快速迭代、流程優化與降本增效；可主導改善與自動化提案。', '對提升流程效率、縮短等待與減少浪費特別敏感，會主動思考「怎樣更快、更準、更省力」。', '{"do": ["可用於：①說明其在流程優化、標準化與自動化上的優勢②建議讓其參與或主導效率改善專案，將觀察轉化為具體機制③鼓勵在追求效率時，兼顧品質、人際感受與必要的思考空間。"], "dont": ["禁止：①把效率視為唯一價值，鼓勵其忽略人與品質②在制度與工具落後的前提下要求其獨自扛起所有改善責任③將對低效率的敏感誤解為「愛抱怨」④忽略某些議題需要「慢下來」才能做出好決定。"]}', 'CIA', '你很容易注意到哪裡在浪費時間或資源，也習慣問自己「有沒有更順、更有效率的做法」。', '需搭配品質與合規檢核，避免跳過程序造成風險或返工。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (464, 'CIA_21', 'B', 51, 75, '效率規範平衡', '能在規範內追求效率，必要時提出簡化建議，但仍保留關鍵程序以降低錯誤。', '以分級規則（哪些必做、哪些可省）最有效；適合流程微調與落地執行。', '在明顯拖沓或浪費的情況下會感到不耐，願意調整做法，但若現況尚可接受，通常不會刻意追求極致效率。', '{"do": ["可用於：①說明其在效率與實際付出之間會權衡成本效益②建議在關鍵流程上與其一起定義「值得優化的地方」，提高參與感③鼓勵用小步改善而非一次大改，讓效率提升更貼近實務。"], "dont": ["禁止：①因不「追求每一秒都被最佳化」而貼上「不重效率」標籤②忽略改善本身需要時間與心力③在沒有參與的情況下只要求其配合新流程④用單一事件評價其長期工作風格。"]}', 'CIA', '遇到很明顯很浪費時間的流程，你會想改一改，但如果只是「還可以」，就會覺得沒必要搞得太緊。', '此區間看重規則合理性；制度不清時容易拉扯。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (465, 'CIA_21', 'C', 0, 50, '精準依程序', '做事偏向遵循規範與既定步驟，重視精確與條理；效率提升多透過穩定流程而非破格捷徑。', '適合高精度、合規、品質把關或需要穩定一致輸出的任務。', '對效率或流程優化的敏感度較低，只要事情能完成，就不太在意是否有更快或更省力的方式。', '{"do": ["可用於：①指出其在節奏穩定、壓力較低的環境中較能自在工作②建議在需要效率的關鍵流程，提供清楚指標與具體做法，而不是只喊「要快」③鼓勵透過簡單工具（範本、捷徑）讓效率自然提升，而非完全依賴個人自覺。"], "dont": ["禁止：①貼上「拖延」「效率差」的道德化標籤②忽略任務複雜度、資訊混亂度對節奏的影響③期待其在沒有任何工具與教學下，自行達到高效率標準④把此分數視為無法勝任高要求工作的絕對指標。"]}', 'CIA', '你比較不會主動去想「能不能再快一點、省一點」，只要事情做得完、大家能接受就可以。', '不等於慢，而是偏好可控與可追溯；提速宜先優化流程。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (466, 'CIA_22', 'A', 76, 100, '自在於無規則', '不依賴傳統或被接受的方法，面對缺乏規則的情境仍能找到做法並推進。', '適合新創、0→1、策略探索或規則尚未建立的任務；可放在開荒位置。', '在清楚的規則、流程與架構下工作會感到安心，傾向尊重制度、依循既有規範來處理事情。', '{"do": ["可用於：①說明其在合規、風險控管與制度落實上的重要性②建議安排在需要嚴謹遵守標準作業的任務或角色③鼓勵在面對不合時宜規範時，嘗試用建設性方式提出調整建議。"], "dont": ["禁止：①把其對規則的尊重當成可以塞所有行政雜事的理由②忽略制度本身的不合理，只要求其「要照做」③將其質疑視為「不服從」而不討論內容④把高紀律遵循度當作缺乏彈性的同義詞。"]}', 'CIA', '當規則清楚、流程明確時，你會覺得比較放心，也會習慣「照制度走」來處理事情。', '需補上對齊機制避免各自為政；重點在自由但有共識。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (467, 'CIA_22', 'B', 51, 75, '可切換模式', '在有規則時能配合，在無規則時也願意嘗試；但需要明確目標與邊界才能穩定輸出。', '給方向與原則（目的/底線/驗收）讓其在框架內自由發揮；適合跨情境角色。', '基本會遵守重要規範與流程，但在規則與現實衝突時，會評估情境與風險，尋找可行折衷，而非一味僵硬或完全忽略。', '{"do": ["可用於：①說明其在「守規」與「務實」之間具有一定彈性②建議與其一起界定哪些是不能碰的底線，哪些可以討論與調整③鼓勵在遇到衝突情境時，把思考過程說出來，增加透明度與信任。"], "dont": ["禁止：①因為有彈性就說「不守規矩」②忽略制度矛盾、時間壓力對行為選擇的影響③只看結果是否完美符合流程，而不看其評估過程④用單一事件給出「不可靠」的定義。"]}', 'CIA', '你會照規則做，但如果規則和現況真的完全對不上，也會評估狀況，找比較合理的做法。', '表現差異主要來自管理清晰度，不宜用單次行為貼標。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (468, 'CIA_22', 'C', 0, 50, '規則清楚最好', '偏好依循既有且被接受的方法，規則越清楚越能發揮；面對模糊規則容易卡住或降低效率。', '適合制度化、作業明確、合規高的環境；對變更管理需更完整溝通。', '對既有規則與流程的依附度較低，面對限制時較容易想著「有沒有別的方法」，對高度制式、僵化的環境較難長期適應。', '{"do": ["可用於：①指出其在需要突破僵化流程、面對未定義問題時具優勢②建議在高風險領域設立清楚界線，讓其明白哪些地方不能逾越③鼓勵其將挑戰規則的能量用在提出具體改善方案，而不是只是否定。"], "dont": ["禁止：①直接貼上「叛逆」「不聽話」的標籤②忽略規則本身是否合理③完全用個人意願取代制度設計的討論④在沒有說明風險的前提下，單純要求其「不要亂動流程」。"]}', 'CIA', '你比較不喜歡被很多規定綁住，遇到一堆流程時，容易想「真的有必要這樣嗎」。', '不代表缺乏創造力，而是風險偏好較低；明確 SOP 可放大穩定優勢。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (469, 'CIA_23', 'A', 76, 100, '原創解題者', '常能以另類觀點重新定義問題，並提出非既定路徑做法；原創想法輸出頻率高。', '適合概念發想、策略破題與需要差異化的任務；在早期探索階段發揮。', '思考與表達時常能跳脫既有框架，提出與主流不同但具啟發性的觀點或解法。', '{"do": ["可用於：①說明其在策略討論、產品構想與問題定義上的創意資產②建議在早期構想階段讓其多參與發想，再搭配他人評估可行性③鼓勵在維持獨特觀點的同時，也學會用對方聽得懂的語言表達。"], "dont": ["禁止：①把其與眾不同的想法視為「不切實際」而直接否定②只在有問題時才臨時要其「給點創意」③忽略其在落地執行上可能需要支援④把創意等同於必須承擔所有變革責任。"]}', 'CIA', '你常會想到別人沒想到的角度，看事情也不太只照慣性路線走。', '需搭配驗證與資源評估，避免只停留在點子。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (470, 'CIA_23', 'B', 51, 75, '情境催化原創', '在刺激足夠或問題設計得好時能產出新想法；若限制不清或缺乏材料，容易回到常規解法。', '用工作坊、對比案例與明確限制條件提升原創品質；適合被題目引導的創意輸出。', '在適合的題目與氛圍下，能提出一些與眾不同的想法；平常多半還是以實務可行與現有做法為主。', '{"do": ["可用於：①說明其原創性會受主題興趣與心理安全感影響②建議創造低風險、可試錯的場域，邀請其分享不同看法③鼓勵其將偶爾的靈感記錄下來，累積成可被討論與應用的素材。"], "dont": ["禁止：①因為平時較務實就認定其「沒創意」②忽略團隊文化對發言勇氣的影響③只在會議最後壓時間時才請其「提想法」④用一次沉默評價其創造力。"]}', 'CIA', '如果話題讓你感興趣，或氣氛允許，你也會丟出一些不一樣的點子；但平常做事還是以實際為主。', '重點是方法設計把原創性拉出來，而非用想不想評價。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (471, 'CIA_23', 'C', 0, 50, '常規解法偏好', '傾向在規範或既定程序內思考，較少自發產出原創解法；重視可行與穩定。', '適合落地、標準化、維運與品質一致性工作；創新需求可由他人提供再負責執行。', '多半偏好沿用已證實可行的作法，對太跳躍或過於另類的觀點較難產生共鳴，原創性表現相對內斂。', '{"do": ["可用於：①指出其在維持穩定、落實既有最佳實務上具可靠性②建議若希望其參與創意思考，可從「現有做法的微調」入手，而不是要求大幅顛覆③鼓勵其在聽到新點子時，先詢問邏輯與目的，再決定是否採納。"], "dont": ["禁止：①貼上「墨守成規」「沒想像力」標籤②忽略其在風險敏感與實務可行性上的價值③強迫其接受沒有說清楚的劇烈變革④以此分數否定其在優化、標準化工作中的重要性。"]}', 'CIA', '你比較傾向用已經證明可行的方式處理事情，對那種很跳躍、很新奇的想法會比較保留。', '不代表沒有好點子，可能是風險控管取向；可用小試點建立信心。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (472, 'CIA_24', 'A', 81, 100, '價值一致', '行為與自身價值觀、欲望較一致，即使面臨從眾壓力仍能維持立場與一致性表現。', '適合誠信、文化示範與長期信任角色；在價值衝突場景提供穩定判準。', '言行多半能與內在價值與真實感受保持一致，即使環境有壓力，也比較難長期違背自己真正相信的事。', '{"do": ["可用於：①說明其在信任建立與角色正直上的重要性②建議安排在需要高可信度與價值導向的任務（如顧問、關係管理）③鼓勵其在價值衝突情境中尋求對話與支持，而不是一個人硬撐。"], "dont": ["禁止：①把其真實性當成可以要求「完全透明」的理由②忽略文化與權力現實對表達空間的限制③在其提出價值質疑時視為「不配合」④鼓勵其長期犧牲自我以換取組織穩定。"]}', 'CIA', '你不太喜歡「表裡不一」，會盡量讓自己做的事、說的話跟心裡認同的價值接近。', '高分不等於不妥協；妥協時仍能清楚說明原則與底線。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (473, 'CIA_24', 'B', 61, 80, '顧自己也顧關係', '通常能維持自我一致，但在高社會壓力或權威情境會調整表達以保留合作空間。', '提供安全表達空間與明確決策流程，有助兼顧真實與合作；適合協調角色。', '重視真實與一致性，但也會考量場合、角色與關係，在誠實表達與維持和諧之間尋找平衡。', '{"do": ["可用於：①說明其在真實自我與社會期待之間有彈性調整能力②建議釐清哪些情境可以更做自己、哪些需更策略表達③鼓勵其在長期壓抑時，找到安全場域說真話，減少耗損。"], "dont": ["禁止：①將必要的修飾一概視為「不真誠」②忽略角色責任與關係風險對其表達選擇的影響③用理想化標準要求其「永遠說真話不計代價」④以一次不完全坦白否定其整體真實性。"]}', 'CIA', '你在意真誠，但也會看場合調整表達方式，有些話不一定會直接全部說白。', '策略性調整不等於不真實；重點看是否仍守原則。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (474, 'CIA_24', 'C', 0, 60, '易受從眾牽引', '較容易因外界期待而調整言行，內外一致性較弱；可能避免衝突而壓抑真實想法。', '適合規則清楚、壓力較低環境；管理上降低懲罰式文化並鼓勵回饋。', '在強烈外在期待或壓力下，較容易優先配合情境需要，而壓抑或暫時擱置自己的真實想法與感受。', '{"do": ["可用於：①指出其可能長期處在高社會期待或關係壓力之中②建議提供安全、非評價性的對話空間，讓其練習逐步表達真實自己③鼓勵分辨「為了關係調整」與「完全犧牲自我」之間的界線。"], "dont": ["禁止：①直接貼上「假」「雙面」標籤②忽略權力不對等與文化壓力③要求其立刻完全做自己而不顧現實風險④將此分數視為無法信任的絕對指標。"]}', 'CIA', '你有時會先選擇「先配合環境」，把自己的真實感受收起來，覺得硬說出來可能會更麻煩。', '不等於虛偽，可能安全感不足或文化高壓；需看權力結構。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (475, 'CIA_25', 'A', 76, 100, '團隊優先', '重視凝聚力與共同目標，傾向把集體利益放在個人之前，願意為團隊付出與協調。', '適合跨部門協作、共同 KPI 與共享資源團隊；可擔任凝聚與協調角色。', '自然會把「我們」放在「我」之前，重視團隊凝聚與共同目標，願意在合理範圍內為集體利益調整個人安排。', '{"do": ["可用於：①說明其在團隊合作、跨部門協作與文化建構上的關鍵角色②建議在溝通中清楚說明決策如何影響「整體」，能更激發其投入③鼓勵其同時照顧自己的界線，避免長期只顧團隊忽略自我需求。"], "dont": ["禁止：①把其集體導向當成理所當然，不斷要求多做犧牲②忽略其在團隊衝突與不公情境中的壓力③以「團隊為重」否定其個人合理訴求④將不同意見視為「不團隊」。"]}', 'CIA', '你會很在意團隊好不好、大家合不合，遇到取捨時也比較願意先顧整體。', '需注意界線，避免過度承擔或為和諧壓抑必要衝突處理。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (476, 'CIA_25', 'B', 51, 75, '合作務實', '願意合作，但會視任務與回報做取捨；在公平制度下能維持良好協作。', '以清楚分工與共同目標對齊最有效；適合合作＋個人責任並存制度。', '重視團隊合作與關係，但在個人利益或發展受到明顯影響時，也會思考如何取得平衡。', '{"do": ["可用於：①說明其會在團隊與個人之間做現實權衡②建議在任務分配與獎酬上說清楚彼此的得失，避免其長期感到吃虧③鼓勵其以理性表達而非壓抑來處理衝突。"], "dont": ["禁止：①因為提出個人需求就認定其「不顧團隊」②忽略制度設計與分配機制對其感受的影響③用道德壓力要求其無條件付出④把一次保留視為不適合團隊。"]}', 'CIA', '你願意配合團隊，但如果對自己傷害太大，也會開始評估「這樣值不值得」。', '對制度公平敏感；避免模糊功勞分配降低合作意願。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (477, 'CIA_25', 'C', 0, 50, '個人導向', '更重視個人目標與自主性，對集體要求投入度較低；偏好清楚個人責任與回報。', '適合個人貢獻型角色；若需合作，說明互賴關係與利益對齊。', '思考時較常以個人目標與利益為優先，對「為團隊多做一些」的動機較依賴具體回饋或明確交換。', '{"do": ["可用於：①指出其在個人績效導向情境中可能動機較強，但在高度團隊導向文化中需要更多對齊與說明②建議清楚界定合作帶來的具體好處（學習、資源、評價），提升合作意願③鼓勵其在爭取自我利益的同時，也思考長期關係與名聲。"], "dont": ["禁止：①直接貼上「自私」「不合群」標籤②忽略其過往可能被濫用或吃虧的經驗③只用道德批評要求其「要為團隊著想」④把此分數視為無法參與任何團隊工作的證明。"]}', 'CIA', '你會先想「對自己有沒有幫助」，對那種需要多付出但看不太到回報的團隊要求，比較少熱情。', '不等於不合群，而是動機偏個人；可用互惠機制促進合作。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (478, 'CIA_26', 'A', 76, 100, '能進入他人框架', '能以他人的參考架構理解其處境與感受，互動時會調整語氣與回應方式以貼近對方需要。', '適合客戶溝通、帶人管理、衝突調解與需要情緒敏感度的角色。', '容易從他人立場出發理解對方的感受與處境，能聽出話語背後的情緒與需求，並給出相對貼近的回應。', '{"do": ["可用於：①說明其在輔導、溝通協調與客戶關係中的價值②建議在衝突情境中善用其橋樑角色，協助彼此被理解③鼓勵其建立自我界線與自我照顧，避免長期承擔過多情緒負荷。"], "dont": ["禁止：①把其同理心當成情緒垃圾桶，凡事都請他吸收②忽略其自身的情緒需求③在制度不公時只要求其「多體諒」④將其情緒耗竭視為「不專業」。"]}', 'CIA', '你常會不自覺地想到「如果我是他，會怎麼感受」，對別人的情緒變化也蠻敏感。', '高分不等於迎合；仍需界線與判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (479, 'CIA_26', 'B', 51, 75, '理解為主', '能理解他人觀點，但情緒共感表達較偏理性；在任務型對話中表現穩定。', '提供回饋技巧與提問框架可提升同理回應的可見度；適合專業導向協作。', '在關係重要、對象熟悉或情境明顯時，多能感受到他人情緒並做出恰當回應；在距離較遠或訊號較弱時，理解度會下降。', '{"do": ["可用於：①說明其同理表現與關係親近度、訊息清晰度高度相關②建議在跨部門或陌生對象互動時，提供更多背景資訊與情境說明③鼓勵其用提問而非猜測來了解他人。"], "dont": ["禁止：①把在陌生場景下的判斷失誤解讀為「沒同理心」②忽略文化差異與溝通習慣對表達的影響③只要求「要設身處地想」卻不提供資訊④用單一案例否定其關懷能力。"]}', 'CIA', '對你在乎的人，你會很希望對方覺得被理解；但對很不熟、或表情很隱晦的人，就比較難猜到在想什麼。', '不代表冷漠，較可能是表達風格務實。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (581, 'CSR_06', 'B', 51, 75, '契合時投入', '當所處環境與個人興趣契合時能充分融入，若環境條件改變或價值觀受到挑戰，會重新評估投入的程度與方向。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (480, 'CIA_26', 'C', 0, 50, '線索較少', '不容易捕捉他人情緒或隱含需求，互動多以事情推進為主，可能無意中造成距離感。', '適合互動需求較低角色；在服務/帶人場景建議搭配溝通訓練與回饋機制。', '自然注意力較多放在自己當下的任務、感受與想法上，不太會自發地揣摩他人心情，需要比較明確的訊號才容易察覺。', '{"do": ["可用於：①指出其在專注任務上的優勢，同時在人際情境需刻意練習「多看一眼、多問一句」②建議提供清楚的人際線索與反饋，幫助其理解互動影響③鼓勵其把「想問清楚」當作一種尊重，而不是多此一舉。"], "dont": ["禁止：①直接貼上「冷漠」「沒感覺」標籤②忽略其成長背景與文化對表達情感方式的影響③在沒說明期待的情況下責怪其「不懂人情世故」④以此分數判定其不適合任何關係導向工作。"]}', 'CIA', '你比較容易專注在自己眼前要處理的事，不一定會立刻意識到別人其實已經不太舒服或在意。', '不代表沒有善意，而是線索判讀與回應頻率較低；用具體情境引導。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (481, 'CIA_27', 'A', 68, 100, '共益付出', '在合作中更重視整體成果與長期互惠，願意先付出、讓利或承擔額外責任，以促成共同完成目標。', '適合共創與跨部門協作、短期回報不明但長期價值高的任務；可放在需要先扛先推的角色位置。', '對他人與團隊相當願意投入時間與心力，即便不一定有立即回報，也樂於主動幫忙與支援。', '{"do": ["可用於：①說明其在團隊合作、支援同事與承接額外任務上的高度意願②建議在重要專案或關鍵時刻善用其願意多走一里路的特質③鼓勵組織在接受其付出的同時，給予合理感謝與資源，避免長期過勞或被視為理所當然。"], "dont": ["禁止：①把其願意付出當成無限制增加工作量的理由②忽略其也有疲累與界線，只期待「有事找他就對了」③用道德壓力強調「你那麼願意幫忙就再多撐一點」④在制度設計上假設有人會永遠自願補洞，不處理結構問題。"]}', 'CIA', '你常會先問「我能幫上什麼忙」，不一定要有明確回報才願意多付出一些。', '高分不等於不在乎公平，而是把公平放在長期互惠與整體結果；需避免其被過度依賴而超載。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (482, 'CIA_27', 'B', 35, 67, '互惠平衡', '願意付出，但也會留意互惠是否合理；當看到對方回應與制度公平時，投入度與合作意願會提升。', '以透明分工、可見回饋與資源對齊穩定投入；適合制度清楚的團隊協作。', '願意在合理範圍內為他人與團隊付出，但會衡量情境與自身狀態，選擇在合適的時候伸出援手。', '{"do": ["可用於：①說明其付出傾向會隨工作量、公平感與關係重要性而調整②建議與其清楚談期待與分工，讓付出與回報相對平衡③鼓勵其在自己願意幫忙的前提下，也能適時說明目前的負荷狀況，避免內心累積壓力。"], "dont": ["禁止：①因為不「每次都答應」就貼上「不願付出」的標籤②忽略其實在多數情況下仍願意支援他人③只在忙碌時臨時請求幫忙，卻沒有長期在制度上照顧④用比較的方式指責「別人都願意，你怎麼不行」。"]}', 'CIA', '你會幫忙，也願意多做一點，但會看狀況和自己最近的負荷，不會每件事都一肩扛起。', '關鍵在看見互惠而非口頭承諾；制度越透明越穩。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (483, 'CIA_27', 'C', 0, 34, '回報敏感', '對付出與回報對等性較敏感，容易在意自己是否吃虧；互惠不明確時可能降低投入或轉為保守合作。', '適合權責清楚、回報機制透明環境；需明確界定投入範圍與回饋，避免累積不滿。', '對額外付出較為保留，傾向先確認是否與自身責任、回報或目標明確連結，才會考慮投入更多時間與心力。', '{"do": ["可用於：①指出其在付出時較強調界線與資源運用效率，適合在角色與責任清楚的環境中工作②建議若希望其多一些投入，需說明付出與目標、回報或專業成長的連結③鼓勵其在維護自身界線的同時，也思考關係與團隊長期合作的效益。"], "dont": ["禁止：①簡單貼上「自私」「不肯幫忙」的標籤②忽略其過往可能因過度付出而感到被利用的經驗③用道德控訴要求其無條件犧牲④把此分數當成無法合作或不適合團隊工作的直接證據。"]}', 'CIA', '你會先想清楚「這跟我有沒有直接關係」或「值得不值得」，才決定要不要多花力氣幫忙。', '低分不是自私，而是風險感較高；先建立制度與互信再談共益合作。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (484, 'CIA_28', 'A', 81, 100, '經常表達感激', '容易看見他人付出並主動表達感謝，強化互惠與人際正向循環。', '適合文化建立、團隊氛圍與客戶關係經營；可作為正向回饋示範者。', '對他人的幫助與資源供給比較容易感到感激，會主動表達謝意並記得他人的好。', '{"do": ["可用於：①說明其在建立互信與正向互動氛圍上的貢獻②建議讓其在團隊中成為正向回饋與感謝文化的帶動者③鼓勵其在表達感謝時也具體說明「哪裡幫助到自己」，增加互動品質。"], "dont": ["禁止：①把其願意感謝視為理所當然、反而加重負擔②以「你應該更感恩」來壓抑其合理不滿③忽略制度與實質待遇問題，只期待情緒上的感恩④把感恩當成避免改變的不成文要求。"]}', 'CIA', '別人對你好的地方，你通常會放在心上，也不吝於說聲謝謝或回應對方。', '高分不等於討好；關鍵在把感謝轉為具體回饋與合作。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (485, 'CIA_28', 'B', 61, 80, '有感但不常說', '內心知道他人幫助重要但表達較保留，通常在重要事件或被提醒時才明確致謝。', '提供具體表達方式（回饋模板、公開致謝場域）可提升社會連結效果。', '對明顯的幫助或支持會覺得需要表示感謝，但對日常小協助或制度性資源未必都會特別放在心上。', '{"do": ["可用於：①說明其感謝表現與事件顯著程度有關②建議透過團隊活動或反思機制，增加對日常支持的覺察③鼓勵在覺得被幫助時，適時做出簡單肯定，強化合作關係。"], "dont": ["禁止：①把沒立即表達感謝等同於「不懂感恩」②忽略文化差異對感謝表達形式的影響③用道德壓力要求其「凡事都要感謝」④不分情境地將其行為解讀為冷漠。"]}', 'CIA', '遇到明顯的幫忙你會說謝謝，但有些日常小事，可能就覺得是互相幫忙或制度本來就該給的。', '不宜貼不懂感恩標籤，常是表達習慣差異。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (582, 'CSR_06', 'C', 0, 50, '疏離淡漠', '較難感受到自身興趣與價值觀的重要性，面對需要深度參與的情境時傾向保持旁觀，融入感與投入程度偏低。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (583, 'CSR_07', 'A', 76, 100, '溫和順從', '在各類衝突情境中都傾向以順從與合作態度因應，面對高度對立也不例外，對抗性反應極為少見。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (584, 'CSR_07', 'B', 51, 75, '彈性因應', '面對一般紛爭時傾向以溝通協調方式處理，若衝突持續升級且對方態度強硬，會視情況決定退讓或堅持。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (585, 'CSR_07', 'C', 0, 50, '直接對抗', '面對紛爭或衝突時傾向直接表達立場，較容易出現爭辯或對抗性反應，較少選擇退讓或迎合。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (486, 'CIA_28', 'C', 0, 60, '較少注意感謝', '較不容易察覺或表達感謝，互動多聚焦在任務完成；可能忽略他人投入的情感需求。', '可加入回饋儀式與互相肯定機制；適合任務導向角色但需補足情感回饋。', '對他人提供的協助或制度支援較少產生明顯的感激情緒，可能更傾向視為「應該的」或互利交換的一部分。', '{"do": ["可用於：①指出其在強調權責與交換的互動中較感自在，但在關係經營上可能少了些溫度②建議透過具體例子協助其理解感謝對關係的正向影響③鼓勵其在重要時刻試著用簡短話語表達肯定，不需誇張也能拉近距離。"], "dont": ["禁止：①直接貼上「忘恩負義」標籤②忽略其價值觀中對「互惠、權責分明」的重視③用羞辱方式強迫其表達感謝④將此分數視為無法建立良好人際的必然結果。"]}', 'CIA', '你比較少特別去想「要感謝誰」，會覺得很多事本來就是互相、或制度本來就該提供。', '低分不代表沒有感受，可能不習慣表達；用情境引導比道德勸說有效。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (487, 'CIA_29', 'A', 81, 100, '能與各型人合作', '能適應不同性格與風格的人，懂得管理互動張力並建立互利的合作關係。', '適合跨部門、客戶多元與橋接衝突角色（PM、顧問、BD、HR）。', '在人際互動中能快速調整說話方式與互動風格，面對不同性格與背景的人，都有機會建立合作或信任關係。', '{"do": ["可用於：①說明其在跨部門協作、客戶應對與關係經營上的靈活度②建議安排在需要橋接多方利害關係人的角色③鼓勵在調整自己迎合他人時，也要留意不過度消耗自我。"], "dont": ["禁止：①把其適應力誤解為「沒有立場」「到處討好」②忽略其在人際壓力下的疲憊感③期待其一手處理所有人際問題，而不調整制度④將偶發的誤判視為長期失職。"]}', 'CIA', '你蠻會看場合、看對象調整自己的溝通方式，跟各種類型的人相處都比較容易找到頻率。', '高分不等於八面玲瓏；重點是調整策略但仍保有原則。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (488, 'CIA_29', 'B', 61, 80, '熟悉圈內更順', '在熟悉或風格相近的場域表現良好；遇到差異很大的對象需要時間摸索互動節奏。', '提供對象背景、互動目的與界線可縮短磨合期；適合在穩定合作網絡中擴張。', '在熟悉或相對類似的人際環境中互動順暢；面對風格差異較大或權力距離較大的對象時，需要一些時間摸索相處方式。', '{"do": ["可用於：①說明其人際適應與情境熟悉度高度相關②建議在新環境或新對象互動初期給予明確指引與範例③鼓勵透過觀察與適度試探，逐步找到合適的相處節奏。"], "dont": ["禁止：①因在陌生情境中略顯拘謹就說「人際能力不好」②忽略組織氛圍與權力結構對其互動表現的影響③只在出現衝突時才檢討其人際，而不提供教練式支持④將單次不順視為無法代表公司對外。"]}', 'CIA', '跟風格接近或熟悉的人，你相處起來很自然；但對很不一樣或位階差很多的人，就會先觀察一陣子。', '避免把初期不順當成能力不足，常是資訊不足導致策略難以調整。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (489, 'CIA_29', 'C', 0, 60, '互動張力較高', '面對不同類型的人容易緊繃或不知拿捏，互動策略較固定，合作建立成本較高。', '適合互動規則清楚環境；可用情境腳本、角色演練與回饋提升。', '在人際情境中的調整彈性相對有限，面對不同風格與期待的對象時，較容易感到尷尬、不知如何應對或乾脆選擇少互動。', '{"do": ["可用於：①指出其在人際多樣性高的環境中可能需要較多支持與指引②建議提供具體對話範例、情境演練或觀摩機會，讓其建立安全感③鼓勵其從少數關係開始練習，而不是要求自己對每個人都能自在自如。"], "dont": ["禁止：①貼上「不會做人」「EQ 低」標籤②忽略其內向、焦慮或過去人際經驗帶來的影響③在未提供任何訓練或支持下，要求其立刻處理複雜關係④以此分數否定其在專業或技術面上的價值。"]}', 'CIA', '你可能常覺得「要看人說話」很累，遇到跟自己差很多的人，也會比較不確定怎麼相處才好。', '不等於不擅社交，可能缺乏方法；重點在提供工具。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (490, 'CIA_30', 'A', 81, 100, '對結果負全責', '對把事情做好有強烈決心，遇到問題會主動承擔、補救與追根究柢，而非推給情境或他人。', '適合主責角色、交付導向任務；可降低管理追催成本。', '對自己承諾過或該負責的事情會主動扛起來，不容易把錯怪罪在環境或他人身上，而是先思考自己能做什麼調整。', '{"do": ["可用於：①說明其在責任感與自我要求上的成熟度②建議在授權與關鍵任務上信任其承擔能力，同時避免過度堆疊責任③鼓勵其在負責的同時，也適度界定「自己不能控制的範圍」。"], "dont": ["禁止：①把其責任感當成無限制加派任務的理由②忽略制度或資源問題，只期待其「自己想辦法」③鼓勵其為所有問題自責而不尋求支援④將其願意承擔視為可長期濫用的條件。"]}', 'CIA', '事情沒做好時，你比較會先想「我這邊可以怎麼改」，而不是第一時間怪別人或怪環境。', '可能過度扛責，需注意負荷與授權資源是否匹配。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (491, 'CIA_30', 'B', 61, 80, '責任隨界線而定', '在責任範圍清楚時能承擔並完成；若分工模糊或權責不對等，承擔度會受影響。', '先定義權責、交付標準與升級機制；適合制度清楚的專案體系。', '在合理範圍內會承認自己該負的責任；但當情境明顯不合理或自己影響力有限時，也會指出外在因素的影響。', '{"do": ["可用於：①說明其對責任的看法較貼近現實，能區分個人與系統因素②建議在檢討時，同時討論可控部分與制度層面調整③鼓勵其維持這種「不推責也不全扛」的健康平衡。"], "dont": ["禁止：①把其提到環境因素解讀為「在找藉口」②忽略實際權限與資源限制③只要求「要負責任」而不談如何賦權④用單一事件評價其是否具責任感。"]}', 'CIA', '該負的你會認，但如果很多事情明顯超出自己能控制的範圍，你也會說明不是全都在你身上。', '不是不負責，而是對可控範圍敏感；清晰度越高承擔度越高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (492, 'CIA_30', 'C', 0, 60, '責任外移傾向', '遇到失誤或延誤較容易歸因外部，補救動作相對被動，可能降低學習與改進速度。', '以復盤流程、行為導向回饋與明確後果機制；先從可控小任務建立承擔習慣。', '在事情出現問題時，較容易優先想到外在原因或他人角色，對於自己能影響或調整的部分較少主動檢視。', '{"do": ["可用於：①指出其在壓力情境下容易以防衛性方式看待責任議題②建議透過結構化檢討工具（如：我能調整什麼、可控/不可控）協助其建立新習慣③鼓勵在安全、非責備的環境中談錯誤，降低防禦需求。"], "dont": ["禁止：①直接貼上「愛推卸責任」標籤②在高度責備文化下只批評其防衛，而不處理環境③用羞辱方式要求其「坦承錯誤」④把此分數當成無法信任的永久標記。"]}', 'CIA', '一出狀況時，你可能會先想到「是誰沒做好」或「環境太爛」，比較少一開始就檢查自己哪裡能調整。', '避免人身貼標；重點是建立對結果負責的流程與文化。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (493, 'CIA_31', 'A', 81, 100, '主動自我升級', '會主動尋找成長機會，願意參與改變、學新方法並發展自我，不需要外部推動也會持續進步。', '適合高成長路徑、輪調與培訓、創新任務；給探索資源與更大挑戰。', '對自我成長與能力提升有明確主動性，會自己找資源、設定學習目標並安排行動，而不只是等公司安排訓練。', '{"do": ["可用於：①說明其在學習敏捷與自我發展上的優勢②建議提供更具挑戰性的發展機會與清楚的職涯路徑③鼓勵其在追求成長時，也平衡休息與當下生活品質。"], "dont": ["禁止：①把其成長動機視為理所當然，不給資源只給期待②忽略學習需要時間，仍塞滿日常工作③以「你那麼愛學」為由，把所有新任務都丟給他④把發展責任完全推給個人。"]}', 'CIA', '你常會主動找課、找資料，思考「接下來可以學什麼」，不太只等別人來安排。', '高分不等於想換工作；若有成長舞台，留任與貢獻反而更高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (494, 'CIA_31', 'B', 61, 80, '被引導就成長', '對成長開放，但多在看見清楚路徑、有人引導或制度推動下才積極投入。', '以學習地圖、導師制與可衡量成長目標最有效；適合穩健培育策略。', '認同持續成長的重要，也願意在有合適機會時投入學習；但在工作繁忙或看不到實質回報時，動力會明顯下降。', '{"do": ["可用於：①說明其成長動機與資源、時間與回報期待高度連動②建議在安排訓練時，清楚連結到實際工作與發展機會③鼓勵將學習拆成小步驟，降低啟動成本。"], "dont": ["禁止：①將其在忙碌時學得少解讀為「不重視成長」②忽略工作量與心理負荷③只用口號式「要終身學習」施壓④在未說明意義下要求參與大量培訓。"]}', 'CIA', '你知道學習對未來有幫助，也願意投入，但如果工作太忙或看不出學了會有什麼差別，就會很難擠出力氣。', '需提供為何成長與怎麼成長；只丟課程可能降低投入。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (495, 'CIA_31', 'C', 0, 60, '維持現狀取向', '較少主動追求自我改變，傾向用既有能力完成任務；成長渴望不高或動機不明確。', '適合技能穩定、流程固定角色；若期待提升，先連結其關心利益點與小步目標。', '目前對主動追求自我成長的內在驅動較弱，多半以完成當前工作要求為主，對額外學習較缺乏明確動機。', '{"do": ["可用於：①指出其可能處在高壓或疲累階段，較難額外挪出資源給成長②建議從與現職高度相關、負擔較小的學習機會開始，逐步建立成就感③鼓勵透過職涯對談探索「為什麼要學」而不只是「要學什麼」。"], "dont": ["禁止：①貼上「不上進」標籤②忽略其現實壓力與資源限制③用比較與羞辱方式要求其「要有企圖心」④把此分數視為不能培養的定論。"]}', 'CIA', '你現在可能比較偏向「先把眼前工作做好」，對另外再花時間學新東西，會覺得動機沒那麼強。', '不等於沒潛力，可能缺少誘因；需先調整情境再判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (496, 'CIA_32', 'A', 60, 100, '高特權感', '較容易認為自己應得到特殊待遇且不一定以努力或績效為前提；期待落空可能強烈不滿或對抗。', '清楚制度邊界、權限與後果，避免模糊承諾；在治理與文化面需更嚴格管理。', '對自己應享有特別待遇、資源或彈性的期待較高，若感到未被特別對待，容易出現強烈不滿或被低估的感覺。', '{"do": ["可用於：①指出其在自我價值與外在對待之間連結緊密，容易因差距產生情緒②建議透過清楚標準、數據與實際貢獻來對齊期待③鼓勵其將部分精力放在提升影響力與成果，而不只聚焦在待遇比較上。"], "dont": ["禁止：①直接貼上「公主病」「王子病」標籤②只用道德批評壓抑其不滿③在未討論事實與數據前否定其感受④把此分數當成其必然難以合作的定論。"]}', 'CIA', '你可能常會覺得「以我的條件應該要更好待遇」，如果覺得沒有被這樣對待，就會很不甘心。', '是風險訊號，尤其授權與資源分配情境；建議搭配制度與行為觀察。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (497, 'CIA_32', 'B', 30, 59, '情境性期待', '在投入高或自覺貢獻大時會期待相應待遇；回報不足可能不滿，但仍願意用制度途徑溝通。', '建立可追溯評價與回饋機制，避免不滿轉為消極或抱怨。', '基本認同應依貢獻與表現獲得相應對待，但在自認付出較多或能力較強時，也會期待某種程度的額外肯定與資源。', '{"do": ["可用於：①說明其在「合理期待」與「特別待遇」之間可能有灰色地帶②建議清楚說明評估標準與差異對待的理由，降低被忽略或被放大的感受③鼓勵其在溝通時聚焦事實與貢獻，而不是情緒化表達。"], "dont": ["禁止：①把其合理期待誤解為「愛耍特權」②忽略透明制度與雙向溝通的重要③在沒有解釋下用「大家都一樣」一概帶過④用單次爭取否定其整體專業。"]}', 'CIA', '你會覺得「有付出就該有相對應的待遇」，如果覺得自己做得比別人多，也會希望能被多看見一點。', '需區分合理期待與特權要求；關鍵看是否尊重規則。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (498, 'CIA_32', 'C', 0, 29, '低特權感', '較少認為自己應獲特殊待遇，對資源分配與規則較能接受，以實際貢獻而非身份要求回報。', '適合共享資源與合作情境；較能接受公平制度與透明流程。', '對「自己應被特別對待」的期待相對較低，比較能接受與他人在相近標準下被評估與對待。', '{"do": ["可用於：①說明其在團隊中較少因特權議題造成摩擦②建議在獎酬與機會分配上，仍清楚說明其貢獻，以避免被低估③鼓勵其在明顯不合理待遇時勇於表達，而不是全部吞下。"], "dont": ["禁止：①因其不要求特權就忽略或壓低其應得回報②把其低特權期待當成可以任意加工作量的理由③鼓勵其「多委屈一點」以維持表面和諧④將不爭取視為理所當然。"]}', 'CIA', '你不太會覺得自己一定要被特別優待，反而比較能接受跟大家差不多的標準。', '不等於不爭取資源；可正常提出需求但不以理所當然表達。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (499, 'CIA_33', 'A', 60, 100, '高度形象調整', '明顯傾向以社會期待方式作答，可能歪曲信念與答案以取得認可，導致評鑑可用性下降。', '更依賴行為證據、工作樣本與多方資料交叉驗證；避免只靠自述決策。', '作答時高度考量「別人會怎麼看」，較可能以理想化的自我形象作為回答依據，而非完全依照日常真實狀態。', '{"do": ["可用於：①指出其他量表分數可能受到形象管理影響，需要搭配他評、行為觀察與面談綜合判斷②建議在回饋過程中，以安全、不評價的方式討論其「想被看見的樣子」③鼓勵其練習在適當場合逐步放下完美形象，讓真實狀態也有被看見的空間。"], "dont": ["禁止：①直接貼上「不誠實」標籤②忽略測驗情境本身帶來的壓力與不安全感③在回饋時用戳破或羞辱的語氣談其防衛④只靠此指標判斷其人格。"]}', 'CIA', '你在回答時可能常會想「這樣寫感覺比較好」，而不是單純寫平常真正的反應。', '不等於說謊成性，可能害怕否定；重點是降低威脅感並改用佐證法。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (500, 'CIA_33', 'B', 30, 59, '形象真實混合', '多數時回應真實，但在敏感題或想留下好印象時可能偏理想化回答，呈現部分防衛。', '用情境題、行為例證追問與無評價訪談氛圍提高資訊準確度。', '作答時會在真實與形象之間拿捏，多數情況仍偏向說真話，但在少部分問題上可能略為修飾。', '{"do": ["可用於：①說明其整體資料仍具參考價值，但需理解少部分題目可能受形象考量影響②建議在回饋時，同步邀請其分享對測驗的感受，增加開放度③鼓勵其把測驗視為自我了解工具，而不是面試考卷。"], "dont": ["禁止：①因為略有形象考量就說「在騙人」②忽略測驗情境（如是否與錄用掛鉤）③只從社會期望指標單點推論其誠實程度④在回饋時用指責口吻談此結果。"]}', 'CIA', '你大部分會照實回答，但有些題目可能會稍微想一下「這樣寫會不會比較好」。', '大多數人常見狀態；避免把表面正向當成全部真相。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (501, 'CIA_33', 'C', 0, 29, '回應較真實', '較能如實呈現自身想法與狀態，不會為了形象或討好而大幅扭曲答案，回覆可信度較高。', '在評鑑解讀與面談追問時可更直接使用其結果；適合用開放問題深化洞察。', '作答時傾向如實呈現自己，即使某些回答可能不那麼「好看」，也較少刻意修飾以迎合期待。', '{"do": ["可用於：①說明其報告內容可信度相對較高②建議在解讀其他量表分數時，可以較少保留地相信其自陳資訊③鼓勵其持續維持真實表達，同時也學會在敏感情境中保護自己。"], "dont": ["禁止：①把其低社會期望反應當成「不在意別人看法」的負面標籤②忽略情境與關係對其表達方式的影響③在高風險場合鼓勵其完全不設防④把真實等同於不需任何界線。"]}', 'CIA', '你比較不會特別去想「這樣寫會不會比較好看」，而是照自己的真實情況回答。', '不代表沒禮貌，而是較少包裝；仍需注意溝通方式。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (502, 'CIA_34', 'A', 81, 100, '投入感強', '對工作本身有明顯熱情與投入，願意多付出以追求成果與成長，工作能量較充足。', '適合需要自我驅動、主動推進與帶動氛圍職務；給挑戰題與舞台。', '對工作本身具有高度熱情與投入感，常願意花時間精進、思考與主動承擔與工作相關的挑戰。', '{"do": ["可用於：①說明其在工作動機與投入度上的優勢，適合作為關鍵任務推動者②建議提供與其熱情方向一致的專案與成長機會③提醒在高度投入下，亦需留意過勞與界線，避免工作熱忱轉為耗竭。"], "dont": ["禁止：①把其熱情當成無上限加班的理由②忽略其在挫折時同樣需要支持③以「反正你喜歡」合理化不合理工作量④把工作熱忱視為可以犧牲其他生活面向的藉口。"]}', 'CIA', '你對自己的工作多半是有感覺的，會想把它做好、做深，也願意多花一些心力在上面。', '需注意過勞與邊界；管理上要保護續航避免燃燒殆盡。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (503, 'CIA_34', 'B', 61, 80, '熱度受情境影響', '在任務有意義、回饋可見或氛圍好時熱忱提高；反之容易變成只是完成工作。', '以目標意義連結、可見成就與支持系統維持熱度；適合穩健推進配置。', '若工作內容具意義感、挑戰性或與興趣契合時，會願意投入較多心力；若過於例行或看不到價值，熱情就會下滑。', '{"do": ["可用於：①說明其工作熱忱與工作設計、意義感高度連動②建議在可能範圍內調整任務組合，增加與其興趣與強項連結③鼓勵其在低熱情時思考可以創造什麼新價值，而不是只悶著做。"], "dont": ["禁止：①把低熱情全歸因於個人態度②忽略職務內容長期單調或缺乏自主性的影響③只用「要有使命感」要求其打起精神④在未調整結構前批評其投入不足。"]}', 'CIA', '遇到有意思、有挑戰的工作，你會很有動力；但如果內容很制式、看不到意義，就比較容易只把它當成一份工作。', '不宜用口號激勵；要用工作設計（自主、成就、連結）點火。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (504, 'CIA_34', 'C', 0, 60, '工作僅是責任', '對工作熱情較低，多以責任或收入角度看待；投入度較依賴外部要求與制度。', '適合流程明確、成果可衡量任務；提升投入需釐清其關心價值與誘因。', '對工作本身較少產生強烈熱情，多以完成責任、維持穩定為主，較不會把工作視為自我實現的主要場域。', '{"do": ["可用於：①指出其可能更重視工作以外的生活面向，或過往工作經驗較少帶來熱忱感②建議在職務設計上，不必強迫其展現高度激情，而是聚焦於清楚的目標與穩定表現③鼓勵其探索哪一部分工作內容對自己比較有意義，作為提升滿意度的起點。"], "dont": ["禁止：①貼上「沒熱情」「只為薪水」的道德化標籤②忽略組織文化與職務本身缺乏成就感③用激情作為唯一評價標準④把此分數視為不負責或不可靠的證明。"]}', 'CIA', '你比較把工作看成「需要做好的責任」，但不一定會覺得它是人生的熱愛或主要成就來源。', '不等於表現差，可能價值觀或職務不匹配；需結合績效與興趣判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (505, 'CIA_35', 'A', 81, 100, '活力充沛', '在日常工作與生活中多以積極、充滿熱情與活力方式行事，對未來抱持期待與動能。', '適合帶動氛圍、對外互動與高節奏推進任務；可作為正向能量來源。', '日常行事風格多半充滿活力與期待感，願意主動探索新體驗，並將熱情帶入生活與工作中。', '{"do": ["可用於：①說明其在團隊氣氛與活動帶動方面的正向影響②建議讓其在需要活絡氣氛、鼓舞士氣的場合發揮所長③提醒在照亮他人的同時，也要照顧自己的休息與情緒需求。"], "dont": ["禁止：①把其熱情視為理所當然的「氣氛製造機」②忽略其也會有低潮的時候③在其需要安靜或暫時退後時批評「怎麼變了」④只看外顯活力而忽略內在壓力。"]}', 'CIA', '你多半是那種會主動揪活動、安排有趣事情的人，生活節奏比較有動能。', '不代表永遠亢奮；也需要休息與情緒調節維持續航。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (506, 'CIA_35', 'B', 61, 80, '能量隨情境起伏', '平時有一定活力，但在壓力、睡眠不足或連續挫折時動能會下降；恢復後可回穩。', '提供節奏管理、適度休息與可見成果，有助維持動能。', '在心情不錯或有感興趣的事情時，會展現活力與參與感；但在疲累或壓力較大時，會明顯收斂熱情。', '{"do": ["可用於：①說明其生活熱情與身心狀態高度連動②建議透過合理工時與休息安排，維持其能量水位③鼓勵其接受自己熱情有起伏是正常的，不必勉強一直「很 high」。"], "dont": ["禁止：①在其低潮時貼上「變冷淡」標籤②忽略組織節奏與壓力對其能量的消耗③只在需要活絡氣氛時才想到找他④用單次狀態判斷其個性。"]}', 'CIA', '如果最近狀態好，你會很願意參與各種活動；但一累或煩的時候，就會比較安靜、保留。', '重點看恢復速度；可用支持而非催促。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (617, 'CSR_18', 'B', 51, 75, '適度韌性', '面對一般性的困難與壓力時能運用內在資源因應，若逆境強度持續升高或同時面臨多重壓力源，韌性會出現明顯下降。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (618, 'CSR_18', 'C', 0, 50, '脆弱易損', '面對困難或壓力事件時較容易受到負面影響，內在用於緩衝逆境衝擊的資源較為有限。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (507, 'CIA_35', 'C', 0, 60, '動能偏低', '較少以熱情與活力驅動行動，對未來期待感薄弱時容易被動或拖延，需要更多外部刺激才啟動。', '從小步可達成目標建立動能，搭配支持與節奏安排；避免長期高壓無回饋。', '在日常生活中較少展現外顯的熱情或興奮感，行事節奏偏穩、偏內斂，對活動與變化的主動性相對有限。', '{"do": ["可用於：①指出其在穩定、需要長期堅持的任務中可能更為合適②建議不要強迫其扮演外向帶動角色，而是尊重其節奏與風格③鼓勵其在自己覺得安全與舒適的範圍內，嘗試少量新體驗。"], "dont": ["禁止：①貼上「沒活力」「很冷漠」的簡化標籤②忽略其內在可能有屬於自己的熱情只是不外顯③用外向標準扣分其表現④在團隊中排除較安靜成員的重要性。"]}', 'CIA', '你比較習慣過穩穩的節奏，不一定會對很多新活動感到特別興奮，也不太會主動當氣氛帶動者。', '可能反映疲乏或環境耗損；不宜快速貼沒熱情標籤，需看近期負荷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (508, 'CIA_36', 'A', 70, 100, '容易被點燃', '對挫折、否定、壓力或不公平刺激反應門檻低，情緒升溫快，可能出現語氣變衝、衝動回應或當場對抗。', '需設計降刺激工作方式：明確溝通規範、冷卻流程、衝突場景第三方介入；高衝突前線配置需更謹慎。', '情緒對外在刺激相當敏感，遇到不順或被觸怒的情況時，反應容易快速且強烈，需要更多自我調節與環境支持。', '{"do": ["可用於：①說明其情緒反應速度快、強度高，需在壓力管理與情緒調節上給予具體工具與協助②建議在重要溝通或衝突場合，預留冷卻時間與中立第三方，降低當下失控風險③鼓勵其練習暫停、換位思考或離開現場等方法，幫助自己先穩住情緒再做決定。"], "dont": ["禁止：①直接貼上「暴躁」「情緒化」的標籤②忽略長期壓力、工作環境或過往經驗對其情緒狀態的影響③用羞辱或嘲諷的方式要求其「冷靜一點」④只看爆發當下的畫面而完全不檢視前期累積的壓力來源。"]}', 'CIA', '你很容易因為一件事立刻覺得不爽、生氣或緊張，要壓住不表現出來對你來說是需要用力的。', '高分是風險提醒而非人格批判；重點在觸發條件、可控流程與支持資源。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (509, 'CIA_36', 'B', 35, 69, '可控但會被觸發', '平常多可維持穩定，但遇到特定觸發點（被誤解、時間壓力、連續失敗）時反應會上升；事後多能回穩並修正。', '辨識觸發點並建立停損機制（暫停、書面回覆、換人處理），再用復盤降低再發。', '多數情況下能保持基本穩定，但在壓力累積、被反覆踩到地雷或身心狀態不佳時，情緒起伏會明顯放大。', '{"do": ["可用於：①說明其情緒穩定度與壓力總量、睡眠與支持系統高度相關②建議與其一起找出個人的「情緒警訊」與舒壓方式，在快到臨界點前就先調整③鼓勵其在覺得快受不了時，提前提出需求，而不是一路硬撐到爆發。"], "dont": ["禁止：①只在情緒失控時檢討其個人，而不處理制度或人際問題②忽略工作負荷、時間壓力與資源不足的影響③用「你怎麼這麼誇張」否定其累積已久的感受④把一次情緒爆發當成永久標記，忽略其多數時間的穩定表現。"]}', 'CIA', '平常你還撐得住，但如果同樣的事一再發生、又剛好很累或很煩，就會比較容易一次反應比較大。', '差異在是否能辨識自己快要爆；前置訊號與提醒比事後檢討有效。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (510, 'CIA_36', 'C', 0, 34, '情緒穩定', '情緒反應門檻較高，遇到煩惱或衝突多能保持冷靜與理性處理，較少因一時情緒做出高代價決定。', '適合高壓、客訴、談判與需要穩定輸出的工作；可作為衝突情境的穩定支點。', '在面對壓力、衝突或突發狀況時，多半能維持相對平穩的情緒，不容易因單一事件立刻被點燃或失控。', '{"do": ["可用於：①說明其在高壓情境與危機處理場合中具備情緒穩定優勢②建議在團隊容易緊張或慌亂時，讓其協助穩住節奏與理性討論③鼓勵其在維持冷靜的同時，也適度表達自己的不滿與界線，避免長期只扮演「穩定器」。"], "dont": ["禁止：①因其外表冷靜就忽略其實際壓力與情緒累積②把其穩定視為可以承接所有負面情緒的理由③在其偶爾情緒外露時，以「你平常不是很穩嗎」否定其感受④把高穩定度誤解為完全不需要情緒支持。"]}', 'CIA', '遇到惹人不快的事，你雖然會有感覺，但比較少一瞬間就情緒爆掉，通常還能先穩住自己再看怎麼處理。', '低易激不等於沒有情緒；仍需建立正常表達與壓力釋放管道，避免悶燒。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (511, 'SPA_01', 'A', 76, 100, '具備足夠心理資本', '希望、效能感、韌性與樂觀四項心理資本相對充足，遇到挑戰時更能維持信心與行動力，並把壓力轉成可處理的任務。', '適合承擔需要自我驅動與長期推進的工作（開發客群、目標管理、陌生市場）；可給較大自主權與更高挑戰。', '心理資源整體偏充足，希望感、效能感、韌性與樂觀之間能維持良好平衡，壓力來時較能先穩住狀態再推進。可觀察行為包含：面對挑戰仍願意採取行動、把壓力拆成可處理的任務、在挫折後能調整策略續航。需留意的是，高分不等於不會累；若長期高負荷或缺少補能，仍可能出現耗損累積而影響穩定輸出。', '{"do": ["• 配置在需要自我驅動、長期推進與反覆試錯的任務（陌生市場開發、關鍵案推進、談判收尾），讓穩定續航發揮價值", "• 給清楚目標與決策空間，允許自行調整節奏與做法，同時安排定期復盤把學到的打法沉澱成方法", "• 同步設計恢復節奏與支援資源（交付後緩衝、輪值分擔），避免把心理資源視為永遠用不完"], "dont": ["• 不因高分就推論永遠扛得住或不需要支持；長期超載仍會造成耗損與績效波動", "• 不把測評分數當作心理健康或臨床狀態判定；需結合近期事件與可觀察行為再解讀", "• 不以單一分數做『一定會/一定不會』式決策；忽略角色、環境與資源差異會導致錯配"]}', 'SPA', '遇到變動或壓力時，通常能先把自己穩住，不太會一下子被情緒拖走，接著會把問題拆小、找出能做的下一步，慢慢把事情推回可控。你也比較能在不順後調整做法再上路。不過心理底盤再厚也會耗電，長期高壓時還是需要補能與節奏，才不會硬撐到後面掉速。', '高分代表心理資源較完整，不等於永遠不累；仍需留意負荷與補能節奏。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (536, 'SPA_09', 'B', 35, 67, '互惠平衡', '會在意對等，但若能理解背景、看到補償或改善機制，多能接受差異並維持合作。', '用理由說明、補償方案與清楚流程可穩定合作；適合擔任制度溝通橋樑。', '會在意互惠與對等，但若能理解背景、看見補償或改善機制，多能接受差異並維持合作。此區間對資訊透明度高度敏感，透明化可顯著降低摩擦。', '{"do": ["強調「理由說明＋可見補償」；提供清楚流程、評價標準與可申訴管道；把互惠證據具體化（時程、回補、資源）。"], "dont": ["不要用「先做再說」或空泛打氣帶過；不要資訊不對稱、臨時改規則；不要把其合理在意解讀成愛計較或不配合。"]}', 'SPA', '你會在意公平，但只要理由說得清楚、補償或改善看得到，你通常願意一起往前走。最怕的是資訊不透明、只講口頭承諾。', '此區間最怕資訊不對稱；透明化能顯著降低摩擦。關鍵在看見互惠而非口頭承諾；制度越透明越穩。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (512, 'SPA_01', 'B', 51, 75, '心理資本可用但需補給', '具備一定心理資本，平時能維持表現；在連續挫折、目標模糊或支援不足時，動能可能下滑，回穩後仍能再推進。', '用清楚目標、里程碑與回饋機制可穩定輸出；搭配同儕支持與教練式提問能拉高續航。', '心理資源大致可用，日常多能維持表現，但在連續挫折、目標模糊或支援不足時，動能較容易下滑。可觀察行為是：在有明確方向與回饋時能穩定推進；當規則不清或缺少回饋，可能出現停滯、效率下降或信心動搖。管理重點在用目標、里程碑與回饋機制把條件做齊；否則容易被情境拖著走，表現波動放大。', '{"do": ["• 用清楚目標與里程碑建立可預期節奏，搭配短週期回饋（週檢核/1on1）穩定續航與信心", "• 在挫折期提供同儕支持或教練式提問，把卡點外顯並轉成可行下一步，避免陷入模糊與停滯", "• 把任務條件做齊（資源、權限、成功標準），讓表現不被情境拉扯，並用復盤強化可複製打法"], "dont": ["• 不以單次狀態就判定長期潛力；此區間很吃情境與管理清晰度，需看一段時間的行為證據", "• 不在規則模糊或支援不足時加壓催促；會直接消耗心理資源並放大焦慮與拖延", "• 不把分數當作診斷或人格貼標；錯把情境波動當成固定特質會造成不必要的錯配與誤判"]}', 'SPA', '平常心理資源是夠用的，事情正常推進時你能把該做的做完；但如果一直挫折、目標又不清楚，或旁邊支援跟不上，動能就會比較容易掉。你在有方向、有回饋的狀況下會明顯更穩，反之就容易卡住。把目標、里程碑和回饋節奏對齊清楚，通常就能把狀態拉回來並持續往前。', '此區間的表現很吃情境與管理清晰度，不宜用單次狀態判定長期潛力。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (513, 'SPA_01', 'C', 0, 50, '心理資本偏緊', '希望感、效能感或復原力相對不足，遇到壓力時較容易感到無助或停滯，需要更多外部結構與支持才好重新啟動。', '先從可控的小步成功建立信心，提供明確優先順序與資源；避免長期高壓、無回饋的任務配置。', '心理資源相對偏緊，希望感、效能感或復原力較難在壓力下同時維持，遇到高壓時容易出現無助或停滯感。可觀察行為包含：啟動行動門檻變高、遇阻礙容易卡住、需要外部結構與回饋才較能重新前進。若環境長期高壓、缺乏回饋或任務過大過模糊，受限感會更明顯。需強調的是，低分不等於能力差，常反映近期耗損與環境壓力，應結合近況與行為證據解讀。', '{"do": ["• 先用小步成功建立可控感：把任務拆小、提供明確下一步與短迴圈回饋，逐步拉回行動動能", "• 提供清楚優先序與資源支援（陪同、工具、範本），降低啟動門檻，避免長期獨戰高壓前線", "• 觀察近期事件與行為證據，再決定配置與培訓；必要時先調整負荷與節奏，讓狀態回到可發揮"], "dont": ["• 不把低分直接等同能力差或不適任；需先排除近期耗損、環境壓力與制度不清造成的影響", "• 不配置長期高壓、無回饋且目標模糊的任務；會放大停滯與無助感，造成更大耗損", "• 不以測評結果做臨床或心理健康判定；應以工作情境與可觀察行為為主，避免錯誤標籤"]}', 'SPA', '最近心理資源可能比較緊，壓力一來會更容易覺得卡住、沒力，想開始做也比較難啟動。你需要更清楚的優先順序、有人一起把下一步拆小，才比較能重新走起來。如果環境又高壓、又沒回饋，這種無助感會更被放大。這不代表能力不好，很多時候是近期太耗、條件沒做齊；先把環境與節奏調整好，再談表現會更公平。', '低分不等於能力差，常反映近期耗損或環境壓力；建議結合近況與行為證據解讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (514, 'SPA_02', 'A', 81, 100, '目標路徑清楚', '能把目標具體化，並設計可行的路徑與替代方案；遇到阻礙時仍會想辦法找路而非停在挫折裡。', '適合擔任目標拆解與行動計畫主導者（銷售計畫、BD節奏、專案推進）；給挑戰型KPI能拉出成果。', '目標感清楚，能把想達成的結果具體化，並設計可行路徑與替代方案；遇到阻礙時會轉而找路，而非停在挫折裡。可觀察行為包含：把KPI拆成行動清單、主動準備備案、卡關時迅速調整策略或尋找資源。需留意的是，目標與路徑規劃若過度飽和，可能低估資源限制或同時推太多線；因此仍需搭配資源評估與優先序管理，避免計畫過滿。', '{"do": ["• 讓其主導目標拆解與行動計畫（銷售節奏、BD管線、專案推進），並給挑戰型KPI以拉出成果", "• 把路徑規劃搭配資源盤點（時間、人力、工具）與優先序，避免同時推太多導致分散", "• 鼓勵建立備案庫（替代客群、替代話術、替代渠道），並在週期性檢核中快速更新與調整"], "dont": ["• 不把高希望感誤解成盲目樂觀；仍需用數據與資源限制校準，避免計畫過滿造成失速", "• 不在需求頻繁變更時放任目標漂移；目標不穩會讓路徑規劃失效並增加挫折成本", "• 不以單次規劃就判定永遠能達成；需看執行與回饋迴路是否到位，避免『想得好但做不出來』"]}', 'SPA', '你通常能把目標想得很具體，也比較能規劃出怎麼走、卡住時要怎麼繞路。遇到阻礙，你不太會只停在挫折，而是會換個方式找下一條路。所以在需要拆KPI、排節奏、做行動計畫時，你常能扛起主導。不過也要提醒：路徑想得越多越容易排太滿，把資源和優先順序算清楚，成果會更穩。', '高分不等於過度樂觀；仍需搭配資源評估，避免計畫過滿。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (515, 'SPA_02', 'B', 61, 80, '需要方向才更穩', '有目標感與動機，但對路徑規劃較依賴外部資訊或經驗；在框架清楚時能穩定執行。', '先對齊成功標準與行動節點，提供可參考的打法與案例；用週期性檢核提升節奏感。', '具備目標感與動機，但路徑規劃較依賴外部資訊、案例或經驗；在框架清楚時能穩定執行。可觀察行為是：當有人提供打法、模板或成功案例，能迅速跟上節奏並把任務推進；若目標模糊或缺乏參考，容易卡在「怎麼做」而延後啟動。管理上宜先對齊成功標準與行動節點，再用週期性檢核讓路徑逐步成形，避免把企圖誤讀成不足。', '{"do": ["• 先對齊成功標準與行動節點（每週要做什麼、做到什麼算過關），提供可參考的打法與案例", "• 用週期性檢核（週會/看板）把路徑逐步具體化，讓其在清晰框架下穩定推進與累積信心", "• 安排陪同演練或同儕示範，縮短摸索期，讓動機能快速轉為可複製的行動步驟"], "dont": ["• 不把需要框架誤讀成沒企圖或不願意衝；此區間的關鍵是清晰度，而不是意願不足", "• 不在缺乏資源與案例時要求自行想出完整路徑；會放大卡關與延後啟動", "• 不只丟口號式目標而缺少節點與回饋；目標越抽象，越難轉成具體策略與持續行動"]}', 'SPA', '你不是沒有目標，而是更需要把「怎麼做」看清楚：有框架、有案例、有節點時，你通常能穩穩照節奏走；但如果目標很模糊、也沒人給參考打法，你會比較容易卡在起步階段。只要先把成功標準、行動節點和檢核節奏對齊，你就更能把動機轉成可落地的路徑，表現也會變穩。', '此區間不是沒企圖，而是需要把「怎麼做」變清楚。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (516, 'SPA_02', 'C', 0, 60, '目標感較鬆散', '較難把目標轉成具體策略與步驟，遇到卡關時容易停在原地或改走短線選擇。', '用短週期目標、明確下一步與外部督導，逐步建立路徑規劃能力；避免一次丟太大的模糊目標。', '目標感較鬆散，較難把目標轉成具體策略與步驟，卡關時容易停在原地或改走短線選擇。可觀察行為包含：面對長期KPI較難持續規劃、遇到阻礙時缺乏替代路徑、容易因不確定而延後行動。若任務一開始就很大且模糊，會更難啟動。管理上宜用短週期目標、明確下一步與外部督導，逐步建立路徑規劃能力，並檢視是否為方向或資源不足所致。', '{"do": ["• 把大目標拆成短週期可達成任務，明確指定下一步與期限，並用固定檢核提供外部結構與回饋", "• 提供具體方法與範本（行動清單、話術、客群分層），降低規劃門檻，逐步培養路徑設計能力", "• 先確認方向與資源是否到位；若缺乏資源或目標不合理，先調整任務設計再談行動表現"], "dont": ["• 不一次丟很大的模糊KPI並期待自行規劃；會放大延後啟動與短線逃避", "• 不把低希望感直接等同『沒動機』；可能是方向不清或資源不足，需要先把條件做齊", "• 不只用催促或責備要求更積極；缺乏路徑與回饋時，情緒加壓只會讓行動更難開始"]}', 'SPA', '你可能比較容易有「想達成」的心情，但要把它變成清楚的步驟和計畫時，常會覺得卡卡的；一遇到阻礙，就容易停住或乾脆改走比較短線的選擇。這種狀況在目標很大又很模糊時特別明顯。把目標拆成短週期、把下一步講得很清楚，再加上固定督導與回饋，你會更容易把路徑建起來，也更敢持續前進。', '低分可能反映缺乏方向或資源，需看任務設計是否可控。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (517, 'SPA_03', 'A', 76, 100, '自信推進', '對自己能靠努力達成目標有明確信心，敢承擔結果並持續投入，遇到困難也較不容易退縮。', '適合需要主動開發、陌生拜訪、談判與高拒絕率的銷售情境；可給較高自主與成果責任。', '對自己能靠努力達成目標有明確信心，敢承擔結果並持續投入，遇到困難也較不容易退縮。可觀察行為包含：主動開發陌生客戶、在被拒絕後仍願意再嘗試、願意承擔業績與交付責任。需要注意的是，自信若缺乏數據校準，可能在判斷上過度堅持原路；因此仍需透過復盤與指標檢核，讓信心與方法一起迭代，避免盲點累積。', '{"do": ["• 配置需要主動開發、談判與承擔成果責任的任務，並給足決策空間讓其用行動推進結果", "• 建立數據與復盤節奏（漏斗指標、案例檢討），讓信心與方法一起校準，持續提升命中率", "• 用更高階挑戰（更難客群、更複雜案型）搭配資源支援，讓其把自信轉成可複製的成熟打法"], "dont": ["• 不把自信等同永遠正確；缺少數據校準容易走偏，需保留檢核與調整機制", "• 不在缺乏資源或規則不清時只靠其硬扛；會消耗信心並造成不必要的挫折成本", "• 不把短期成功當成唯一證據；仍需看其是否能在挫折後維持行動與修正，而非只看一兩次結果"]}', 'SPA', '你通常相信自己靠努力是做得到的，所以遇到困難不太會馬上縮手，反而比較願意再試、再修正，甚至願意把成果責任扛起來。這在需要陌生開發、談判或高拒絕率的情境很有優勢。不過自信也需要校準：定期用數據和復盤檢查方向，能讓你不只衝得快，也衝得準，避免因太相信原做法而忽略新訊號。', '高分不代表判斷永遠正確；仍需用數據與復盤校準方向。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (518, 'SPA_03', 'B', 51, 75, '確認後加速', '多數情境能相信自己，但在新產品、新市場或高風險時會更想先確認做法；理解後可穩定輸出。', '給明確成功案例、話術框架與陪同演練能迅速拉升；適合在教練制團隊中成長。', '多數情境能相信自己，但在新產品、新市場或高風險任務時，會更想先確認做法與成功機率；理解後可穩定輸出。可觀察行為包含：先詢問話術、流程或案例，再投入執行；在有教練或同儕支援時表現提升明顯。若缺乏清晰方法或早期回饋，可能延後啟動或反覆確認。管理重點在提供成功案例、框架與演練，把風險感轉成更穩的準備，而不是被誤讀為不自信。', '{"do": ["• 提供清楚成功案例、話術框架與流程步驟，搭配陪同演練，縮短確認期並加速啟動", "• 用教練制與同儕支持建立安全試錯環境，讓其把風險感轉成更扎實的準備與復盤", "• 在新市場/新產品採用分段目標與早期回饋，讓每一步都有驗證點，信心會隨證據快速拉升"], "dont": ["• 不把反覆確認簡化成不自信或拖延；多半是風險感較強，需要清晰度與證據支持", "• 不只丟高風險目標而缺乏示範與資源；會讓啟動門檻變高並拉長磨合期", "• 不在早期失利就否定能力；此區間很看訓練與框架，給到方法後常能迅速穩定輸出"]}', 'SPA', '你其實不是沒信心，而是遇到新東西或風險高的任務時，會想先弄清楚：怎麼做比較會成功、哪些坑要避開。當你拿到清楚的做法、看到案例、甚至有人陪你演練一下，你就能很穩地把事情做起來。如果只丟目標卻不給方法，你就會比較容易一直確認、起步變慢。把清晰度補上，你的輸出會很快回到穩定。', '此區間常被誤讀為不自信，其實是風險感較強、需要清晰度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (519, 'SPA_03', 'C', 0, 50, '容易自我懷疑', '對自己能否達成目標較沒把握，容易因挫折而縮手或拖延，行動啟動門檻較高。', '先安排低風險可達成任務累積成功經驗，搭配正向回饋與明確步驟；避免長期獨戰高壓線。', '對自己能否達成目標較沒把握，遇到挫折容易縮手或拖延，行動啟動門檻偏高。可觀察行為包含：在陌生開發或被拒絕後較難快速回到行動、需要更多確認與鼓勵才敢投入。若近期連續挫敗或缺乏正向回饋，這種自我懷疑會被放大。管理上宜先安排低風險可達成任務累積成功經驗，提供明確步驟與陪跑，逐步重建效能感；並強調低分不等於能力低，需結合近三個月表現解讀。', '{"do": ["• 先配置低風險、可達成且回饋快的任務，累積成功經驗，把效能感從『做得到』的證據建立起來", "• 提供明確步驟、話術與陪跑（同行拜訪/角色扮演/逐案復盤），降低啟動門檻並加速學習", "• 解讀時結合近三個月事件與表現；若是近期挫敗造成，先調整節奏與支持，再談長期配置"], "dont": ["• 不把低分等同能力差或不適任；可能只是近期連續挫折或環境支持不足，需先排除情境因素", "• 不長期安排獨戰高壓前線且缺乏回饋；會加深自我懷疑並讓行動更難啟動", "• 不只用責備或比較激勵；需要的是可操作方法與可見成功，而不是情緒壓力"]}', 'SPA', '你可能比較容易懷疑自己做不做得到，遇到不順就會想先縮一下、拖一下，尤其是需要陌生開發或被拒絕很多的工作，啟動會更難。這種狀況常跟近期連續挫敗、回饋太少有關，不一定是能力問題。先從可達成的小任務開始，給你清楚步驟、陪你跑幾輪，看到成果後效能感會回來，你也會更敢主動出手。', '低分不等於能力低，可能是近期連續挫敗；建議結合近三個月表現解讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (520, 'SPA_04', 'A', 71, 100, '抗壓復原快', '遭遇拒絕、衝突或目標落空後能快速回穩，重新調整策略並保持輸出，不容易被一次挫折打亂節奏。', '適合高壓業務、目標波動大或需長期耕耘的客戶線；也可在團隊低潮時提供穩定力量。', '面對拒絕、衝突或目標落空後，回穩速度快，能重新調整策略並保持輸出，不容易被一次挫折打亂節奏。可觀察行為包含：失利後能迅速復盤、改話術再上、把情緒影響控制在短時間內。需要留意的是，高韌性容易被團隊依賴而承擔過多壓力；若長期缺乏休息與補能，仍可能累積耗損而在後段出現突然掉速，因此管理上仍要配置恢復節奏與支援。', '{"do": ["• 配置在高拒絕率、目標波動大或需要長期耕耘的客戶線，並讓其在團隊低潮時扮演穩定推進者", "• 建立固定復盤機制，把挫折轉成策略調整與學習素材，讓韌性不只硬撐而是變成方法升級", "• 同步安排休息與輪替，避免長期超載；在關鍵衝刺與收尾節點使用其韌性優勢最有效"], "dont": ["• 不把高韌性當作『不會累』的證明；長期超載仍會累積耗損，需主動管理負荷與節奏", "• 不忽略情緒與壓力訊號只看結果；即使輸出穩，也要關心其恢復品質與補能狀態", "• 不在挫折後只要求更快回來；需要的是復盤與資源支援，讓回穩建立在可學習的調整上"]}', 'SPA', '就算遇到被拒絕、衝突或案子沒成，你通常也能比較快把自己拉回來：先整理一下、找出可改的點，然後很快又回到行動節奏。這種韌性在高壓業務很珍貴。不過也因為你撐得住，常會被大家更依賴、事情越扛越多。記得把休息和補能排進去，否則長期硬撐也會在後段一次性耗光。', '高分不代表不需要支持；仍要配置休息與補能，避免累積耗損。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (521, 'SPA_04', 'B', 41, 70, '恢復需要時間', '壓力當下會受影響，但在獲得支持、釐清下一步後能逐步回穩；韌性表現受情境與資源影響。', '用節奏管理、同儕支持與明確里程碑降低耗損；適合穩健推進型配置。', '壓力當下會受影響，但在獲得支持、釐清下一步後能逐步回穩；韌性表現受情境與資源影響較大。可觀察行為包含：遇到衝突或失利時需要一些時間消化，若有人協助對齊目標、提供方法或陪同復盤，恢復速度會明顯提升。若長期缺乏支持或節奏混亂，可能出現恢復變慢、效率下滑與情緒拖尾。管理重點在節奏管理、同儕支持與明確里程碑，並觀察恢復速度而非只看情緒反應。', '{"do": ["• 用節奏管理降低耗損：里程碑清楚、任務拆解到可執行，並在關鍵點提供支持與短回饋", "• 建立同儕支持與教練式1on1，幫助其把失利轉成下一步行動，縮短情緒拖尾與停滯時間", "• 評估時聚焦恢復速度與自我調節方法，並提供可學的工具（復盤框架、壓力管理）來提升韌性"], "dont": ["• 不只看當下情緒反應就判定韌性差；此區間關鍵在恢復機制是否到位，而非完全不受影響", "• 不在缺乏支持與節奏混亂時加壓要求立即回穩；會拉長恢復期並增加耗損", "• 不把挫折當成個人問題；需同步檢視資源、角色與任務設計，避免情境造成的波動被誤判"]}', 'SPA', '遇到壓力或失利時，你不是完全不受影響，當下可能會悶一下、卡一下；但只要有人幫你把下一步講清楚、一起復盤一下，你就能慢慢回穩，重新把事情推起來。你的韌性很吃情境：節奏清楚、有支持時就恢復快；節奏亂、一直沒回饋時就會拖比較久。把里程碑和支持系統做起來，你的狀態會穩很多。', '此區間重點看「恢復速度」與「自我調節方法」，不要只看情緒反應。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (522, 'SPA_04', 'C', 0, 40, '耗損累積快', '在連續高壓或長期不確定下容易出現疲乏與挫折感，復原較慢，表現波動可能增大。', '避免長期高密度前線，增加支援資源與分工；建立固定復盤與情緒釋壓機制。', '在連續高壓或長期不確定下，疲乏與挫折感較容易累積，復原速度偏慢，表現波動可能增大。可觀察行為包含：失利後需要較長時間才能回到行動、對新挑戰的耐受度下降、容易出現撤退或情緒耗竭。若工作前線密度高、缺乏分工支援或回饋機制，耗損會更快累積。需強調的是，低分不等於抗壓差，常是目前負荷過重；管理上宜先調整環境與支援，再談能力與配置。', '{"do": ["• 避免長期高密度前線配置，增加分工與支援資源；先穩住負荷，再逐步拉升挑戰強度", "• 建立固定復盤與情緒釋壓機制（結案檢討、支持對話、喘息安排），縮短恢復期並降低耗損累積", "• 觀察近期壓力來源與事件脈絡；若是負荷過重造成，先調整環境與節奏，再安排能力訓練"], "dont": ["• 不把低韌性分數直接等同『抗壓差』；需要先排除超載與長期不確定造成的耗損", "• 不在缺乏回饋與支援時要求持續衝刺；會加速耗竭並放大波動，甚至影響留任", "• 不忽略恢復期就加新任務；在尚未回穩前再加壓，只會讓挫折感堆疊並降低後續可塑性"]}', 'SPA', '如果壓力是一直來、又看不到結束，你可能會比較快累積疲乏：事情不順時要花更久才回得來，甚至會開始不太想再接新的挑戰。這很常是『負荷太重』而不是你不行。先把前線密度降下來、分工支援補上、回饋節奏變穩，你就比較能慢慢恢復，也更有機會把韌性拉回來。環境先修好，才公平談表現。', '低分不等於抗壓差，可能是目前負荷過重；先調整環境再談能力。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (523, 'SPA_05', 'A', 81, 100, '偏正向解讀', '傾向把不順視為暫時且可改善，較能維持希望感與行動力，在不確定下仍願意嘗試與修正。', '適合需要帶動士氣、推進變革或長期開發的銷售情境；可作為團隊動能來源。', '把不順利解讀為「暫時、可修正」的傾向較強，即使結果未定或環境變動，仍能維持希望感與行動動機。常見表現是：遇到拒絕或失敗會先找可控因素、快速調整話術或策略，再回到行動。需要留意的是，若只看正向而忽略風險訊號，可能低估阻力或備案不足，導致後段返工。', '{"do": ["• 把不確定任務拆成短週期試驗（如兩週一個話術/渠道測試），用數據回饋維持動能與校準方向", "• 在衝刺或變革期安排其帶頭推進士氣，但同時加上「風險清單＋備案」的固定檢核，避免只往前衝", "• 把成功案例沉澱成可複用腳本（開場、異議處理、收尾），讓正向解讀能轉成可落地的行動節奏"], "dont": ["• 不把正向解讀當作『永遠不會低潮』的保證；當連續失利時仍要提供資源、陪同復盤與情緒緩衝", "• 不以『你很樂觀所以不需要備案』的方式配置任務；缺乏風險檢核會放大後段返工成本", "• 不把短期的好心情或一句鼓勵當作管理手段；需要的是可見進度、具體回饋與可調整的策略選項"]}', 'SPA', '面對不順時，通常不會直接認定「完了」，而是比較容易把它當成暫時卡關，先找哪裡能改、下一步怎麼做。你常會用修正策略或換打法把事情推回軌道。不過也要記得：保持正向很好，但還是要把風險點列清楚，避免因為太相信會變好而少做備案。', '高分要避免過度樂觀忽略風險；仍需保留檢核與備案。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (524, 'SPA_05', 'B', 61, 80, '現實中保有期待', '多數時能保持正向，但在連續挫折或高壓時會短暫消沉；看見進展與資源後能恢復。', '用可視化進度、明確下一步與支持系統維持動能；適合穩健節奏的KPI設計。', '多數情境能保持正向期待，但在連續挫折、被否定或高壓拉長時，情緒與動能可能短暫下滑，對未來結果的想像也會變保守。常見行為是：需要看到進度、資源或可行路徑後，才更容易回到投入與嘗試。若缺少可見改善線索，可能出現拖延、降低嘗試或把目標下修的傾向。', '{"do": ["• 把進度做成可視化（里程碑、漏斗、週成果），讓改善路徑可被看見，避免只靠口頭鼓勵", "• 用固定節奏的1on1/週檢核，聚焦「下一步最小可行行動」與資源缺口，幫助快速回到可控感", "• 在挫折期安排小勝利任務（可達成、可回饋），用連續正向回饋把動能接回來"], "dont": ["• 不在挫折期用空泛激勵或比較式壓力（例如拿別人績效刺激）；容易讓動能更低、甚至轉防守", "• 不把一次消沉解讀成長期消極；需要結合近期事件與可見進度判讀，而非貼標", "• 不讓目標長期模糊或規則一直變；資訊不清會直接消耗樂觀感並放大拖延與退縮"]}', 'SPA', '平常你其實是能正向看待事情的，只是如果連續幾次不順、又看不到改善方向，心裡會比較容易「先冷掉」。一旦看到進度、拿到資源或有人把下一步對齊清楚，你又能把狀態拉回來。重點不是打氣，而是讓你看得見「事情正在往更好的方向走」。', '此區間最需要「可見的改善路徑」，單純打氣效果有限。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (525, 'SPA_05', 'C', 0, 60, '悲觀預期偏高', '容易把失利解釋成長期且難改變，降低嘗試與冒險意願；遇阻礙可能提前放棄或轉為防守。', '先用小目標建立成功經驗，提供具體資源與教練式回饋；避免長期無回饋的任務配置。', '傾向把失利解釋成「長期、普遍、難改變」，因此在面對不確定或連續受挫時，嘗試與冒險意願較容易下降。常見表現是：遇到阻礙會先保守收縮、降低投入，或提前判定努力無效而退出。若環境回饋稀薄、資源不足或目標過大過模糊，這種防守解讀會更明顯，可能影響持續開發與抗拒絕能力。', '{"do": ["• 先設計「小步成功」：把任務拆成可控且可驗證的短目標，讓回饋密度變高、重建嘗試意願", "• 提供具體資源與方法（話術範本、陪同演練、成功案例），降低『不知道怎麼改』造成的無力感", "• 避免長期高壓與無回饋配置；用固定復盤把卡點外顯，讓改善路徑變清楚而不是靠硬撐"], "dont": ["• 不把保守解讀當成『天生消極』或『不適任』；需先排除近期耗損、制度不清與資源缺口", "• 不一次丟大型、模糊、成敗不明的目標；會放大無助感並讓行動更難啟動", "• 不在低潮期用責備或羞辱式激勵；會強化防守與撤退，反而更難回到可嘗試的狀態"]}', 'SPA', '遇到不順時，你比較容易先想到「是不是一直都會這樣」，所以會自然地想縮回來、先保守一點，免得再受傷。這不代表沒能力，而是需要讓你重新看到：努力能帶來改變。只要把目標拆小、回饋變密、支援到位，你會比較願意再試一次，也更能把步伐走穩。', '低分不等於消極人格，常與近期情境相關；要結合事件脈絡判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (526, 'SPA_06', 'A', 66, 100, '工作即核心', '對工作高度投入，優先把時間與心力放在職責與成果上，容易把工作表現視為自我重要來源。', '適合需要長期耕耘、深度專注與持續追蹤的銷售/客戶經營；可給長線客戶與關鍵案。', '工作在生活中佔比很高，容易把職責與成果視為自我價值的重要來源，因此會主動加碼投入時間與心力。可觀察行為包含：主動追進度、願意長線跟案、對交付品質與結果有責任感。需要留意的是，若長期高負荷或缺乏恢復節奏，可能出現過勞、對他人投入度不耐，或忽略生活面支持而導致耗損累積。', '{"do": ["• 配置長線客戶經營、關鍵專案或需要深度追蹤的任務，讓投入能轉成可累積的成果與關係資產", "• 建立可預期的恢復節奏（週期性喘口氣、交付後緩衝），避免把高投入當成無限資源使用", "• 用明確成果定義與授權範圍，讓投入集中在高價值行動，降低無效加班與不必要的耗能"], "dont": ["• 不因投入高就持續堆任務或默認『一定扛得住』；長期超載會以績效波動或情緒耗竭反噬", "• 不把工作當作唯一評價尺度；忽略生活面支持會降低續航，甚至影響長期留任與健康", "• 不讓目標與優先序模糊；投入型在不清楚時容易越做越多卻不一定更有效，反而加速耗損"]}', 'SPA', '你通常會把工作放在很核心的位置，事情一來會很自然地想把它做完整、做到有結果，所以也更願意花時間追進度、跟細節、把案子收好。這個投入度在業務或專案很有價值，但也要小心：如果一直把油門踩到底，電量會被透支。把休息節奏排進去，反而能讓你更穩。', '高投入也可能帶來過勞或忽略生活平衡；管理上要安排恢復節奏。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (527, 'SPA_06', 'B', 31, 65, '投入隨情境變動', '在目標清楚、回饋可見時投入度高；若任務意義不明或成就感不足，投入可能下降。', '用清楚目標、可見成就與合理授權提升投入；適合以階段成果驅動的管理方式。', '投入度會隨情境而起伏：當目標清楚、意義感強或回饋可見時，能投入並維持表現；若任務意義不明、回饋稀薄或成就感不足，投入可能下降而轉向完成最低要求。常見行為是：在有明確節奏與里程碑的工作上表現穩定，但在模糊、重複或缺乏被看見的任務上較難自發加碼。管理重點在於把『為何重要』與『怎麼算做到』講清楚。', '{"do": ["• 先把成功標準與里程碑說清楚，讓投入有方向；用階段成果回饋取代只看期末結果", "• 把任務意義連到客戶價值或團隊目標，並提供可見成就（排行榜、案例分享、獎勵）提升投入感", "• 採用階段授權：先給可控範圍讓其做出成果，再逐步放大責任與自主權，讓投入自然加碼"], "dont": ["• 不把投入起伏解讀成不敬業；多半是工作設計缺乏清晰度或回饋機制，而非態度問題", "• 不長期安排重複且無回饋的雜務；會快速耗損投入感，並讓表現落到最低線", "• 不只用口號式激勵要求『更投入』；缺少目標、節奏與回饋時，情緒催促只會增加抗拒"]}', 'SPA', '你的投入不是一直固定在同一格。當目標清楚、事情有意義、做了能看到成果時，你會很願意投入，也做得穩；但如果工作一直很模糊、做了看不到回饋，你就比較容易把它當成「完成就好」。只要把成功標準、里程碑和回饋節奏拉清楚，你的投入感通常會跟著回來。', '此區間不代表不敬業，多半是工作設計是否能點燃。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (528, 'SPA_06', 'C', 0, 30, '工作與生活分隔', '較傾向把工作視為一部分責任，投入度受外部要求影響，可能較少自發加碼或長線耕耘。', '適合流程清楚、成果可量化的任務；若要提升投入，需連結其在乎的價值與誘因。', '較傾向把工作視為生活的一部分責任，投入度多受外部要求與制度規範影響，較少自發加碼或長線耕耘。可觀察行為包含：偏好完成明確交付、按規則做事，對於需要自我驅動或長期追蹤的任務可能較不主動。需要留意的是，若角色與誘因設計不匹配，可能被誤解為不努力；但在流程清楚、成果可量化的任務上，反而能穩定交付。', '{"do": ["• 配置流程清楚、交付可量化的任務，並把期待寫清楚（輸出標準、期限、責任邊界）以提高穩定度", "• 若希望提升投入，先連結其在乎的價值與誘因（學習、成就、獎酬、工作彈性），再逐步擴大任務半徑", "• 用固定追蹤節奏與明確回饋，讓投入從『被要求』轉為『看得見好處』，避免靠情緒催促"], "dont": ["• 不以『投入低＝能力差』做結論；可能是角色不匹配、已耗損或制度不清，需先排除情境因素", "• 不把長期、模糊、需要高度自我驅動的前線任務直接丟上去不管；容易造成拖延或低承諾", "• 不忽略績效行為證據，只用主觀印象評價；在適配任務上可能交付很好，需看任務條件"]}', 'SPA', '你比較像是把工作放在『該做就做好』的位置：規則清楚、交付明確時，你能按步驟穩穩完成；但如果要你自己一路加碼、長期追著一個模糊目標跑，你可能不會自動把油門踩到底。這不代表做不好，而是需要更清楚的成果定義、誘因與節奏，才能讓投入往上走。', '低分不等於表現差，可能是角色不匹配或已耗損，需要搭配績效觀察。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (529, 'SPA_07', 'A', 66, 100, '高標準自我要求', '傾向遵守規範並維持專業品質，做事不只達標而是追求更好，對外代表公司時重視形象與一致性。', '適合客戶面高、需要信任與長期合作的角色；可作為服務品質與流程的示範者。', '對既定標準與專業品質的堅持度高，不只想『做完』，更傾向把交付做得一致、可被信任。可觀察行為包含：重視流程與合規、對外溝通有分寸、文件與承諾較少失誤，能代表團隊維持形象。需要注意的是，若把完美當成唯一標準，可能在多工或緊急情境中降低速度，或對他人品質要求過高而產生摩擦。', '{"do": ["• 安排在客戶面、合規敏感或需要信任累積的任務（提案、合約前置、重大客訴處理），放大專業一致性的價值", "• 建立交付標準與檢核表，讓其成為流程示範者，同時把高標準沉澱成團隊可複用的方法", "• 在趕件情境加上優先級與『足夠好』門檻，避免完美主義拖慢進度；必要時提供協作分工支援"], "dont": ["• 不把高標準解讀成『愛挑剔』就壓制；需要的是把標準轉成可執行規則，而不是否定其要求", "• 不讓其獨自承擔所有品質把關；過度集中會造成瓶頸與耗損，應設計分層審核與授權", "• 不忽略速度需求與情境限制；在緊急任務仍需明確交付優先序，避免品質與時程兩頭落空"]}', 'SPA', '你做事通常不是只求交差，而是會在意專業度和一致性：該有的流程、該確認的細節，你會想把它守好，對外也比較能維持形象與可信度。這在客戶經營很加分。不過也要留意：如果每件事都追到最完美，遇到多工或趕時間時可能會卡住。把優先級分清楚，品質和速度才好兼得。', '高分需注意是否過度完美導致速度下降；可搭配優先級管理。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (530, 'SPA_07', 'B', 31, 65, '標準可維持', '通常能維持基本專業與規範，但在高壓或多工情境可能出現品質波動；有清楚標準時更穩。', '用檢核清單、交付標準與回饋迴路提升一致性；適合穩健型客戶經營。', '多數情境能維持基本專業與規範，但在高壓、多工或資訊不完整時，品質一致性可能出現波動。可觀察行為是：有清楚標準、模板或檢核點時交付較穩；若標準模糊或需求頻繁變更，容易出現遺漏、延後確認或品質起伏。管理重點在把『交付標準』與『驗收方式』事先定義，並提供回饋迴路以穩定表現。', '{"do": ["• 提供清楚交付標準（模板、檢核清單、驗收條件），並在關鍵節點做短回饋，降低品質波動", "• 用固定節奏的復盤把失誤點轉成流程改進（例如常見漏項清單），讓專業表現更可預期", "• 在高壓多工期協助排優先序、減少臨時變更，讓其把力氣用在最重要的品質點上"], "dont": ["• 不把品質起伏簡化成態度問題；多數時是標準不清或變更過多造成，需先修系統再談人", "• 不在需求模糊時要求『一次到位』；應先對齊驗收條件，避免返工與責任模糊", "• 不只給抽象評語（如更專業一點）；需要具體例子與可操作的改進點，否則難以穩定提升"]}', 'SPA', '你通常能把基本專業守住，但如果事情一下子變很多、又很趕或需求不清楚，品質就可能忽上忽下。當你手上有明確的標準、範本或檢核清單時，交付會穩很多；反過來，如果規則一直改、驗收也不明確，就容易漏東漏西。把標準講清楚、回饋做固定，你就更能維持一致性。', '此區間看「制度與支持」；越清楚越能發揮。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (531, 'SPA_07', 'C', 0, 30, '標準感較鬆', '對流程與規範的敏感度較低，可能以完成為主而忽略一致性與細節，對外互動時風險較高。', '需要更明確的規範、示範與檢核；先安排可控任務，逐步提升專業一致性。', '對流程、規範與專業細節的敏感度較低，傾向以『完成任務』為主，可能忽略一致性、合規或對外形象風險。可觀察行為包含：交付前較少自我檢核、文件與承諾容易漏細節、對標準差異不太在意。若放在高客戶曝光或合規要求高的情境，失誤代價會放大；但在任務可控、規則清楚且有示範的環境下，透過制度與訓練能逐步拉升一致性。', '{"do": ["• 先提供明確規範與示範案例（什麼叫達標、哪些細節必檢），再用檢核表把標準固化成流程", "• 安排可控任務逐步練習：先低風險交付→回饋→再提高曝光度，避免一次丟到高風險前線", "• 把合規/品牌風險點做成「必查清單」與交付前的最後關卡，降低因疏忽造成的外部代價"], "dont": ["• 不把低敏感度直接等同『不專業人格』；需要用制度、訓練與回饋把標準建立起來，再觀察變化", "• 不在沒有規則與驗收條件下要求高品質；標準不清只會讓錯誤重複發生並難以追責", "• 不把高曝光、合規敏感任務直接交付而缺乏審核；應先設置把關與陪跑，避免品牌/法務風險"]}', 'SPA', '你比較容易把重點放在「事情做完」而不是「做到同一個標準」，所以在流程、規範或細節上，可能不會自動去多想一步。這在要求不高的任務可能沒問題，但如果要對外代表公司、或牽涉合規，漏一個細節就可能變成大成本。把規則寫清楚、示範一次、再用檢核表輔助，你的專業一致性會更容易拉上來。', '低分不等於不專業，但代表需要制度與訓練補強，避免品牌/合規風險。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (532, 'SPA_08', 'A', 56, 100, '主動要回饋', '會主動向主管、同儕或客戶確認表現與改進點，把回饋當成加速成長的工具，調整速度快。', '適合快速迭代的銷售團隊與教練文化；給即時回饋與數據看板能放大效果。', '主動向主管、同儕或客戶確認表現與改進點，把回饋視為加速學習與提升績效的工具。可觀察行為包含：結案後主動復盤、願意要求具體建議、收到回饋後能快速調整話術或流程。需要注意的是，若回饋來源品質不一，可能被單一聲音牽著走或過度迎合；因此更適合搭配數據、行為證據與多來源校驗，讓調整更穩。', '{"do": ["• 建立快速回饋迴路：結案復盤＋即時數據看板，讓其把回饋轉成可追蹤的改進動作", "• 鼓勵多來源回饋（主管/同儕/客戶/數據），並協助整理成優先級，避免被雜訊淹沒或失焦", "• 把學到的改進沉澱成團隊教材（話術迭代、流程優化），放大其學習型特質對團隊的貢獻"], "dont": ["• 不把『很會要回饋』誤解為沒主見；需看其是否能把回饋轉成行動與成果，而非只求認同", "• 不讓其長期暴露在低品質回饋（情緒化、片面批評）；會拉低判斷力並造成迎合式調整", "• 不只給抽象評語或只說好/不好；需要具體例子與可操作建議，才能維持其快速迭代的優勢"]}', 'SPA', '你會主動去要回饋，不太會等到出事才回頭看：做完會想知道哪裡可以更好、客戶在意什麼，然後很快把做法調整起來。這種學習速度很強，但也要小心回饋來源：如果只聽一個人或一種聲音，可能會越調越偏。把回饋和數據、實際結果一起看，會更穩也更有效。', '高分需留意回饋來源品質，避免過度迎合單一聲音而失焦。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (533, 'SPA_08', 'B', 11, 55, '被提醒才回頭看', '願意接受回饋，但多在遇到問題、績效波動或被要求時才會去確認；回饋頻率較情境性。', '建立固定檢核節奏（週會/1on1/復盤）最有效；提供具體例子比抽象評語更能促進改進。', '願意接受回饋，但多在遇到問題、績效波動或被提醒時才會去確認，回饋習慣偏情境性。可觀察行為是：當有人指出明確問題或提供具體例子時能修正，但平常較少主動蒐集外部觀點。若團隊缺乏固定檢核節奏，容易錯過早期修正窗口；若建立週會、1on1或例行復盤，反而能把改進變成習慣並穩定提升。', '{"do": ["• 設計固定檢核節奏（週會/1on1/結案復盤），把回饋變成例行流程而不是等出事才補救", "• 回饋要具體可行：用案例、錄音、對話片段或數據指標，讓其知道「哪裡改、怎麼改」", "• 用短週期目標＋回饋迴路讓改進可被看見，逐步建立『主動回饋』的習慣與安全感"], "dont": ["• 不用抽象批評或模糊指令（例如更積極一點）；缺少例子時很難轉成行動，反而降低回饋意願", "• 不把被動回饋習慣貼成『不想學』；多半是缺少機制與習慣，不是能力或態度問題", "• 不只在出錯時才給回饋；若回饋只和負面事件綁在一起，會讓其更抗拒確認與對話"]}', 'SPA', '你不是排斥回饋的人，只是通常會在遇到卡關、成績起伏或被提醒時，才比較會回頭確認哪裡要改。當回饋很具體、有人跟你一起看例子，你修正其實很快。重點是把回饋變成習慣：固定的1on1、週檢核或復盤一做起來，你就比較不會等到問題變大才回頭看。', '此區間不是不想學，而是缺少回饋習慣與機制。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (534, 'SPA_08', 'C', 0, 10, '回饋距離感', '較少主動尋求回饋，可能擔心被否定或覺得沒必要，容易錯過修正與學習的窗口。', '用低威脅、具體且可行的回饋方式建立安全感；先從小改進與可見成效開始。', '較少主動尋求回饋，可能擔心被否定、覺得麻煩，或過往經驗讓回饋被視為壓力來源，因此容易錯過修正與學習窗口。可觀察行為包含：不太主動問「我可以怎麼更好」、遇到問題先自己撐或迴避討論。若團隊文化偏指責或回饋方式帶威脅感，這種距離感會更強。管理上宜先建立安全氛圍與低威脅回饋，再逐步導入具體改進與可見成果。', '{"do": ["• 用低威脅回饋方式建立安全感：先描述觀察到的行為與影響，再提供可選擇的改善方案與支持資源", "• 先從小改進與短週期成果開始，讓回饋和『可行、有效』連結起來，而不是和否定感綁在一起", "• 建立固定但溫和的回饋流程（例如每週一題：本週最想改進的一件事），逐步拉近回饋距離"], "dont": ["• 不在公開場合或情緒化狀態下給回饋；會放大威脅感，讓其更迴避確認與討論", "• 不把不問回饋解讀成『抗拒學習』；需先檢視文化氛圍、過往經驗與回饋方式是否造成壓力", "• 不只給結論不給方法（例如你做得不好）；缺少可操作下一步只會加深防衛與逃避"]}', 'SPA', '你比較不會主動去要回饋，可能是怕被否定、也可能覺得問了反而壓力更大，所以遇到狀況會先自己撐、或乾脆不太想談。這不代表你不想進步，而是需要一種比較安全、比較具體的回饋方式：先從小改進開始、給你可做的下一步，看到成效後，你會更願意開口確認。', '低分不代表抗拒回饋，常與文化氛圍或過往經驗相關，需要方法而非壓迫。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (535, 'SPA_09', 'A', 68, 100, '共益付出', '較不以付出回報作為主要衡量，對不對等的容忍度較高，可能更看重關係或任務本身。', '適合彈性制度或使命導向情境；但要避免長期吃虧而累積耗損或隱性不滿。', '較不以付出/回報作為主要衡量，對短期不對等的容忍度較高，可能更看重關係、任務本身與長期互惠。此傾向有助於在彈性制度或使命導向情境中維持投入，但需留意長期吃虧造成耗損或隱性不滿。', '{"do": ["以「長期互惠/整體結果」角度解讀；提醒管理端定期關心負荷與資源；遇到不對等情境用「補償機制/回補安排」來保護個體。"], "dont": ["不要把高分解讀成「可以一直多做/不用回報」；不要鼓勵無止境加碼或情緒勒索式的使命感；不要忽略其累積耗損的風險訊號。"]}', 'SPA', '你對公平不是不在乎，而是更看長期互惠、整體結果；短期吃點虧你可能還能扛。但如果一直被壓榨，你也可能默默累積疲憊或不爽。', '高分不等於不在乎公平，而是把公平放在長期互惠與整體結果；需避免其被過度依賴而超載，定期關心負荷與資源。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (550, 'SPA_14', 'A', 66, 100, '強烈求勝', '對勝負與優越感高度在意，傾向把每個任務當成競賽，會想拿第一或主導局面。', '適合競賽型銷售、排行榜、短期衝刺活動；需要明確規則與公平機制避免內耗。', '面對目標時傾向以「勝負／排名」作為主要驅動，衝刺力強、企圖心明顯，適合短期拉升績效與攻堅任務；但若規則不清或回饋不透明，較可能引發內耗。', '{"do": ["設定明確、可量化、公開的競賽規則；把「個人戰」改成「團隊共同戰績」避免互踩；定期做輸贏復盤把情緒導回策略"], "dont": ["不要用模糊口號煽動或臨時改規則；不要放任零和文化導致資訊封鎖；不要把所有任務都設成比賽導致疲乏"]}', 'SPA', '你很吃「想贏」的感覺，衝起來很快很猛；只要把規則、獎勵和公平講清楚，你會更容易一路把成果推上去。', '高分可能帶來壓迫感或合作下降；要搭配團隊共同目標與文化引導。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (537, 'SPA_09', 'C', 0, 34, '回報敏感', '對付出與回報的公平性非常敏感，會注意資源分配、制度一致性與被對待方式，遇到不對等易產生不滿。', '需要透明制度與清楚評價標準；適合在獎酬、分工規則明確的團隊，避免模糊功勞分配。', '對付出與回報的公平性高度敏感，會特別注意資源分配、制度一致性與被對待方式；遇到不對等易產生不滿。適合在獎酬、分工規則與功勞歸屬清楚的環境中發揮。', '{"do": ["用「透明制度/一致標準」作為管理重點；先建立互信與規則再談共益合作；提供可申訴、可追溯的機制與明確功勞歸屬。"], "dont": ["不要貼標籤成自私或難搞；不要用模糊分工、模糊獎酬與功勞不清；不要用「你就先吞一下」方式處理不對等，會快速破壞信任。"]}', 'SPA', '你對公平非常敏感：規則、資源怎麼分、功勞怎麼算，你都會看得很清楚。只要制度透明，你會很穩；但如果模糊或不一致，你很容易覺得不被尊重。', '低分不等於自私愛計較，而是對信任與制度敏感、風險感較高；先建立制度與互信再談共益合作，管理重點在透明與可申訴。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (538, 'SPA_10', 'A', 66, 100, '高能量快節奏', '生活與工作步調偏快，做事積極、反應迅速，喜歡把事情往前推，容易帶動團隊速度。', '適合外勤開發、快節奏銷售與需要主動出擊的任務；可給多線並行但要控管優先序。', '步調快、行事積極、反應迅速，喜歡把事情往前推，並可能帶動團隊速度。適合快節奏開發與主動出擊任務；但需留意節奏過快造成他人壓力或忽略細節，建議搭配檢核機制。', '{"do": ["配置外勤開發/快節奏任務；同步設「優先序＋檢核點」避免返工；提醒在合作情境放慢溝通節奏、補齊細節。"], "dont": ["不要把高能量等同於永遠不累；不要放任多線並行無收斂；不要忽略細節/品質檢核或團隊壓力累積。"]}', 'SPA', '你做事很有衝勁、節奏快，常常會想把事情立刻推進，也容易帶起整個團隊的速度。但有時候太快會讓別人喘不過氣，或細節沒顧到。', '高分需注意節奏過快造成他人壓力或忽略細節；搭配檢核可避免返工。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (539, 'SPA_10', 'B', 31, 65, '有衝勁但會起伏', '多數時有活力，但在連續高壓或缺乏成就感時能量會下降；補充資源與回饋後可回穩。', '用可見進度、短週期成果與合理休息節奏維持動能；適合穩健推進配置。', '多數時有活力，但在連續高壓或缺乏成就感時能量會下降；補充資源與回饋後可回穩。重點在能量管理與節奏設計，而非單純加壓。', '{"do": ["用「短週期成果/可見進度」維持動能；安排合理休息節奏與資源補給；以節奏管理取代純加壓。"], "dont": ["不要用持續催促取代方法；不要忽略成就感與回饋機制；不要把能量起伏誤判成不積極或態度問題。"]}', 'SPA', '你平常是有衝勁的，但如果一直高壓、又看不到成果，能量會掉。相反地，只要進度變得可見、回饋到位，你又能很快回來。', '此區間重點在能量管理，而非單純加壓催促。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (540, 'SPA_10', 'C', 0, 30, '節奏偏穩慢', '做事較不追求快，傾向按部就班；在高節奏環境可能感到耗損或被推著走。', '適合需要耐心、細緻跟進與長線耕耘的任務；若要提速，先優化流程與工具支援。', '做事不追求快，傾向按部就班、節奏較穩；在高節奏環境可能感到耗損或被推著走。適合耐心跟進、細緻執行與長線耕耘型任務；若需提速，宜先優化流程與工具支援。', '{"do": ["配置長線耕耘/細緻跟進任務；若要提速先給工具、流程與緩衝；以清楚期限＋回饋節點協助節奏對齊。"], "dont": ["不要把低分解讀成懶散；不要用純「加速」要求硬推；不要把其放在高多工高催促環境卻不提供資源與方法。"]}', 'SPA', '你屬於穩穩做、一步一步推進的型，未必追求快，但重視可控與穩定。如果環境節奏太急，你可能會很耗；但在需要耐心與細緻的任務，你反而很能扛。', '低分不代表懶散，可能是風格偏穩；要看是否能穩定交付。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (541, 'SPA_11', 'A', 66, 100, '相信可變可學', '更相信特質、能力與表現能透過努力改善，願意嘗試新方法並持續調整，學習動機與參與度較高。', '適合導入新打法、新工具或轉型訓練；給挑戰與成長回饋能快速升級。', '更相信特質、能力與表現可透過努力改善，願意嘗試新方法並持續調整，學習動機與參與度高。適合導入新打法、新工具或轉型訓練；但仍需合理目標與資源，避免過度承諾。', '{"do": ["用挑戰＋成長回饋驅動；安排新工具/新打法導入角色；把目標拆成可達成的里程碑並配資源。"], "dont": ["不要把高分當成「什麼都能改、無限加碼」；不要只給口號不給方法/資源；不要鼓勵過度承諾導致挫折。"]}', 'SPA', '你很相信「可以變得更好」，也願意試新方法、做調整，學習動機通常很強。只要給你方向和資源，你升級速度會很快；但也要避免目標喊太大變成壓力。', '高分不等於什麼都能改，仍需合理目標與資源；避免過度承諾。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (542, 'SPA_11', 'B', 31, 65, '部分可塑', '相信某些能力可以提升，但對改變幅度與速度較務實；看見成效才會更投入。', '用可驗證的小步改進與案例支持，能提升投入；適合循序培訓與教練制。', '相信部分能力可以提升，但對改變幅度與速度較務實；看見成效才會更投入。有效做法是以可驗證的小步改進與案例支持，逐步拉高投入。', '{"do": ["用「小步改進＋可驗證成果」設計培訓；提供案例與同儕示範；採循序教練制提升投入。"], "dont": ["不要用空泛理念硬推；不要一次要求大轉變；不要在沒有成效回饋時長期施壓，會讓投入下降。"]}', 'SPA', '你覺得有些能力是能練的，但你會比較務實：要看到成果、才會更願意加大投入。用小步試驗、快速驗證，對你最有效。', '此區間需要「看得到的成果」，空泛理念說服力有限。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (543, 'SPA_11', 'C', 0, 30, '較固定心態', '較傾向認為能力與特質相對固定，面對改變可能先觀望或覺得徒勞，學習投入度容易受挫折影響。', '先讓其在安全範圍內獲得小成功，逐步建立成長經驗；提供清楚方法與同儕示範。', '較傾向認為能力與特質相對固定，面對改變易先觀望或覺得徒勞，學習投入度可能受挫折影響。建議先在安全範圍創造小成功，提供清楚方法與示範，逐步建立成長經驗與安全感。', '{"do": ["先創造小成功與安全感；提供清楚方法、步驟與同儕示範；用支持式回饋取代批評。"], "dont": ["不要用批評/羞辱式激勵；不要直接貼「抗拒改變/不想學」標籤；不要一口氣丟大改造且缺乏方法與支持。"]}', 'SPA', '你可能比較不相信「人可以很快被改變」，遇到變革時會先觀望，甚至覺得努力也沒用。但只要先讓你在安全範圍內嘗到小成功、看到方法，你其實是能慢慢跟上的。', '低分不等於不學，而是需要更多證據與安全感；避免用批評式激勵。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (544, 'SPA_12', 'A', 60, 100, '高度形象管理', '答題或表達時傾向以社會期待的方式呈現，可能為了看起來更正向而淡化真實狀態，資訊可信度需交叉驗證。', '在面談/管理上多用情境題、行為例證與工作樣本確認；建立低威脅氛圍可提升真實回饋。', '答題或表達時傾向以社會期待的方式呈現，可能為了維持正向形象而淡化真實狀態；因此資訊可信度需交叉驗證。建議在面談/管理上使用情境題、行為例證與工作樣本，並建立低威脅氛圍以提升真實回饋。', '{"do": ["提醒需交叉驗證（情境題/行為證據/工作樣本）；用中性提問與低威脅氛圍提高真實度；避免讓對方覺得被審判。"], "dont": ["不要直接判定「不誠實」或用指責式追問；不要只依賴單次自陳分數做重大決策；不要用高壓盤問逼出更大的包裝。"]}', 'SPA', '你可能比較會「把自己講得更好一些」：不是一定在說謊，而是怕被否定、想留下好印象，所以會偏向說得正向。要更準確理解你，會需要用例子、情境題、或工作樣本來對照。', '高分不一定是刻意說謊，可能是怕被否定；避免用指責方式追問。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (545, 'SPA_12', 'B', 30, 59, '部分包裝', '多數時回應真實，但在敏感議題或想留下好印象時會偏理想化；整體仍可用，但要注意偏差。', '用中性提問、要求舉例與第三方佐證，可提高判讀準確度；固定回饋節奏也有幫助。', '多數回應真實，但在敏感議題或想留下好印象時會偏理想化；整體仍可用，但需留意偏差。適合搭配中性提問、要求舉例與第三方佐證，提高判讀準確度。', '{"do": ["採中性提問＋要求舉例；必要時加第三方佐證；建立固定回饋節奏，降低臨場包裝需求。"], "dont": ["不要把表面正向當成全部真相；不要忽略敏感議題的包裝偏差；不要用二分法（真/假）評斷，改用證據校正。"]}', 'SPA', '你大致是講真的，但遇到敏感題目、或很想留下好印象時，可能會稍微「講得更漂亮」。這很常見，不需要過度解讀；只要搭配舉例和佐證，判讀就會很準。', '此區間非常常見，解讀上不要把表面正向當成全部真相。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (546, 'SPA_12', 'C', 0, 29, '較真實直白', '較少為迎合他人而扭曲答案，回應更貼近真實狀態；優點是資訊品質高，但表達可能較不修飾。', '可用開放問題深入挖掘動機與行為；在客戶情境則可加強溝通包裝與同理表達。', '較少為迎合他人而扭曲答案，回應更貼近真實狀態，資訊品質高；但表達可能較不修飾。管理上可用開放問題深入挖掘；在客戶情境可加強溝通包裝與同理表達。', '{"do": ["肯定其真實資訊價值；用開放問題深入動機/行為；在對外互動提供溝通包裝與同理技巧。"], "dont": ["不要把直白解讀成沒情商；不要要求其為了迎合而扭曲事實；不要忽略其在客戶/協作情境的表達風險（需教方法而非批評）。"]}', 'SPA', '你比較直白、講話偏真實，不太會為了迎合而包裝，所以資訊可信度高。但有時也可能因為太直接，讓人覺得不夠圓滑；如果是面對客戶或協作場景，稍微加一點同理和包裝會更加分。', '低分不等於不懂人情世故，而是較少形象包裝；需看其互動方式是否得體。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (547, 'SPA_13', 'A', 66, 100, '高度競速型', '行為上明顯進取、重視掌控與效率，容易被競爭與時間感驅動；壓力下可能出現急躁或敵意反應。', '適合目標明確、節奏快的銷售環境；需搭配情緒管理與衝突停損機制，避免內耗。', '行為明顯進取、重視掌控與效率，容易受競爭與時間感驅動；壓力下可能出現急躁或敵意反應。適合目標清楚、節奏快的銷售環境，但需搭配情緒管理與衝突停損機制，避免內耗。', '{"do": ["配置目標明確/節奏快任務；同步建立情緒調節、衝突停損與溝通規範；用復盤把衝勁轉成穩定產出。"], "dont": ["不要把高分直接等同高績效；不要放任衝突升級或用「硬碰硬」管理；不要忽略其壓力下的敵意/急躁風險與團隊內耗。"]}', 'SPA', '你屬於典型「衝很快、很拚」的風格：目標感強、效率導向、想掌控節奏。這能帶來速度與推進力，但一旦卡關或壓力大，你也更容易急躁、火氣上來。', '高分並非一定高績效，關鍵在是否能把衝勁轉成穩定產出而非摩擦。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (548, 'SPA_13', 'B', 31, 65, '目標導向但可調節', '有一定競爭與掌控需求，但多數時可維持理性合作；在高壓或受阻時才較明顯急躁。', '用清楚目標與可控節奏可放大優勢；提供復盤與壓力管理工具可降低副作用。', '具一定競爭與掌控需求，多數時可維持理性合作；在高壓或受阻時較易急躁。管理重點在提前對齊期待、釐清節奏與提供壓力管理工具，以降低觸發摩擦。', '{"do": ["找出觸發點（被拖慢/被否定/受阻）；提前對齊期待與節奏；提供復盤與壓力管理工具，維持合作品質。"], "dont": ["不要等爆點才處理；不要用模糊指令、臨時變更拖垮節奏；不要把短暫急躁上綱成「難相處」，而忽略情境觸發。"]}', 'SPA', '你有目標感，也在意效率，但大多時你能合作、能理性溝通。只是當你被拖慢、被否定或壓力很大時，急躁會比較容易被點燃；只要先對齊節奏和期待，就能很穩。', '此區間要留意觸發點（被拖慢、被否定）；提前對齊期待可降摩擦。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (549, 'SPA_13', 'C', 0, 30, '相對平衡型', '較不以競速與掌控作為主要驅動，重視合作與步調穩定；在高競爭環境可能較不亢奮。', '適合需要耐心、關係經營與長線耕耘的銷售模式；可用明確成就回饋提升動能。', '較不以競速與掌控作為主要驅動，重視合作與步調穩定；在高競爭環境可能較不亢奮。適合耐心、關係經營與長線耕耘的銷售模式，並可用明確成就回饋提升動能。', '{"do": ["配置關係經營/長線耕耘任務；用清楚成果回饋與里程碑維持動能；避免用純競賽/高壓方式驅動。"], "dont": ["不要把低分當成沒企圖；不要硬套競速文化造成不適配；不要忽略其穩健持續性與合作價值（用對場景才會發光）。"]}', 'SPA', '你比較像「穩健合作型」：不一定喜歡搶快或掌控一切，反而更重視關係和穩定步調。在需要耐心經營、長線跟進的情境，你會很吃香；只是如果環境太競速，你可能看起來不那麼亢奮。', '低分不等於沒企圖，可能是風格偏穩；需看其持續性與結果。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (551, 'SPA_14', 'B', 31, 65, '有競爭心但務實', '在關鍵任務會想贏，但不會把所有情境都視為競賽；能在合作與競爭間切換。', '用階段性挑戰賽與清楚獎勵能提升動能；同時保留協作機制維持團隊氣氛。', '在關鍵任務上具有競爭動機，但能在合作與競爭之間切換；若提供階段性挑戰與合理獎勵，可有效提升動能並維持團隊氛圍。', '{"do": ["用「階段目標＋小型挑戰」帶動節奏；獎勵與評分透明化；同時設計協作機制（共享名單/共同行動）讓競爭不傷感情"], "dont": ["不要把你放進長期沒有回饋的環境；不要只用排名刺激卻不給資源；不要讓競爭變成互相拆台的默許文化"]}', 'SPA', '你會在該拚的時候很想拚，但也能跟大家一起做事；給你一個清楚的挑戰賽，你通常會自己加速。', '此區間可塑性高，管理重點在設計健康競爭。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (555, 'SPA_15', 'C', 0, 30, '企圖感較保守', '較少把「往上衝」放在第一順位，偏向把事情做好但不一定追求極致突破；可能更重生活平衡。', '適合穩健型業績盤、既有客戶維繫或流程型工作；若要提升企圖心，需連結其在乎的價值與誘因。', '較少以「往上衝」作為第一順位，傾向穩健完成、重視平衡；在既有客戶維繫、流程型或長期可預期的任務中可穩定交付，但不一定會主動加碼。', '{"do": ["設定清楚的最低標準與期待；把誘因連到你在意的價值（生活品質/成就感/穩定）；給可預期的任務盤與固定回饋"], "dont": ["不要用「拼命文化」當唯一激勵；不要把不加碼誤解成不努力；不要讓角色長期模糊，容易更收斂"]}', 'SPA', '你比較偏向把事情做穩、做長久，不太會自己無限加碼；把期待講清楚、誘因對齊，你會更好發揮。', '低分不等於低績效，但可能不會自動加碼；管理上要用明確期待與回饋。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (556, 'SPA_16', 'A', 66, 100, '同時做很多', '做事節奏急、偏好多工並行，容易同時推多件事以追求速度與成果；在切換間可能忽略收尾與細節。', '適合需要快速反應的開發與前線，但要配合優先級與收斂機制（週清單/結案標準）。', '做事節奏快、傾向多線並行以追求速度與成果；能快速推動進度，但若缺乏收斂與結案標準，易出現分心、漏尾或品質波動。', '{"do": ["建立優先序（本週三件最重要）與看板；要求每件事有結案標準；用固定節奏做收斂（週清單/日結）"], "dont": ["不要同時塞過多臨時任務；不要只要求快卻不給整理時間；不要讓你一直切換而沒有收尾機制"]}', 'SPA', '你習慣同時推很多件事，速度很快；只要把優先順序和結案標準訂好，你會更像「推進引擎」而不是「到處救火」。', '高分不是效率保證；若缺乏管理方法，多工可能變成分心。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (557, 'SPA_16', 'B', 31, 65, '多工視情境', '能在必要時多工，但也知道需要收斂；在任務明確與工具支援下可維持品質。', '提供工作拆解、看板與時間區塊管理能提升效率；適合彈性但有節奏的團隊。', '能在必要時多工，也知道需要收斂；若任務拆解清楚且工具到位，多數情況能維持品質與節奏，是「可控的多工」型態。', '{"do": ["提供任務拆解與期限；用時間盒與看板工具；定期回顧哪些多工是必要、哪些要砍掉"], "dont": ["不要用混亂當成常態；不要頻繁插單破壞節奏；不要只看忙不忙而不看完成度"]}', 'SPA', '你不是一定要多工，但需要時做得到；給你清楚的拆解和工具，你通常可以快又不亂。', '此區間重點在方法；有方法就快，沒方法就亂。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (558, 'SPA_16', 'C', 0, 30, '偏好一次一件', '較習慣專注完成一件事再切換，節奏較穩；在高多工環境可能感到壓力或效率下降。', '適合深度跟進、關係經營或需要精準交付的任務；若需多工，先給工具與緩衝。', '較偏好一次專注完成一件事再切換，節奏穩定、品質導向；在高多工環境可能感到壓力或效率下降，但在深度跟進與精準交付任務上具優勢。', '{"do": ["用明確期限＋充足緩衝；安排深度跟進/關係經營/精準交付任務；若需要多工，先給工具與清楚切換規則"], "dont": ["不要硬塞高頻切換工作；不要把穩健解讀成慢；不要臨時改需求又要求同樣交期"]}', 'SPA', '你比較像「一件一件做完做漂亮」的類型；給你更穩的節奏與緩衝，你反而能交付得更可靠。', '低分不等於慢，常代表品質與專注優勢；要避免用錯環境。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (559, 'SPA_17', 'A', 66, 100, '強烈時間緊迫', '常感到時間不夠用，做事像在追趕時程，對延誤特別敏感，容易出現急躁或催促行為。', '需要清楚排程、緩衝與升級機制；適合短週期衝刺，但要避免長期高壓造成耗損與人際摩擦。', '經常處於時間緊迫感，對延誤高度敏感，能推快節奏與短期衝刺；但也容易因催促與急躁提高耗損與人際摩擦，需要更清楚的排程與升級機制。', '{"do": ["提供清楚排程與緩衝；建立卡點升級流程（誰決策/多久回覆）；用短週期衝刺＋固定復盤降低焦慮"], "dont": ["不要讓你長期在不確定與等待中；不要用含糊指令或頻繁變更；不要放任催促文化傷害合作關係"]}', 'SPA', '你很容易感到時間不夠用，會想把事情趕快推完；只要排程清楚、卡點有處理流程，你就能把急迫感用在推進而不是內耗。', '高分可能提升速度，也可能拉高壓力；管理上要同時顧節奏與關係。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (560, 'SPA_17', 'B', 31, 65, '會緊張但可調整', '在重要交付或多任務時會有時間壓力感，但在規劃清楚、資源到位時能回到穩定節奏。', '用里程碑、優先序與時間盒管理能有效；適合有節奏的KPI與追蹤方式。', '在重要交付或多任務時會有壓力感，但在規劃清楚、資源到位時可回到穩定節奏；對「清楚優先序」與「可預期交付」反應最好。', '{"do": ["用里程碑＋時間盒管理；提前對齊交付標準；減少臨時插單並確保資源到位"], "dont": ["不要讓需求反覆變更又不調整時程；不要只丟一句「快點」；不要把壓力全交給個人承擔"]}', 'SPA', '你會緊張，但不是不能穩；把優先順序講清楚、把期限切成里程碑，你就會比較安心也做得更順。', '此區間最怕臨時變更與模糊指令；越清楚越穩。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (561, 'SPA_17', 'C', 0, 30, '時間壓力感較低', '較少被時間追著跑，對延誤的焦慮較低，步調偏穩；在快節奏團隊可能被誤解為不急。', '適合長線耕耘、品質控管與需要耐心的任務；若要提速，需更明確期限與回饋節點。', '較少被時間追著跑，對延誤焦慮低、步調偏穩；在長線耕耘、品質控管與需要耐心的任務更能發揮，但在快節奏團隊可能被誤解為不急。', '{"do": ["設定明確期限與檢核節點；用可視化進度避免被誤解；安排長線或品質導向任務並給足資訊"], "dont": ["不要用恐嚇式催促；不要把「不焦慮」解讀成拖延；不要缺乏期限與回饋，容易失去節奏感"]}', 'SPA', '你不太會被時間逼著跑，節奏比較穩；只要把期限、節點和回饋講清楚，你通常能穩穩交付。', '低分不代表拖延，可能是情緒較穩或偏好品質；需看交付紀律。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (562, 'SPA_18', 'A', 70, 100, '情緒反應快', '面對煩惱或挫折時較容易衝動、情緒升溫快，可能出現急躁、語氣變硬、當場對抗或做出高代價回應。', '需設計降刺激工作方式、建立冷卻機制與溝通規範（先暫停、先書面、先換人），並降低高衝突暴露，衝突場景第三方介入；必要時安排情緒調節訓練。', '面對挫折時情緒升溫快、衝動反應機率高，可能在高衝突場景做出高代價回應；需透過降刺激工作設計、冷卻流程與溝通規範降低風險。', '{"do": ["建立冷卻機制（先暫停/先書面/先換人）；降低高衝突暴露並用第三方介入；教練式訓練情緒調節與回應腳本"], "dont": ["不要當場硬碰硬；不要在情緒高點做重大決策；不要用羞辱/否定式管理加劇爆點"]}', 'SPA', '你在被惹到或壓力很高時，反應會來得很快；如果先把「怎麼停損、怎麼冷卻」設好，你其實可以更好地把力氣用在解決問題。', '高分是風險訊號，不是人格評價；重點在觸發點與可控流程設計。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (563, 'SPA_18', 'B', 35, 69, '會被觸發但可回穩', '一般情況能維持理性，但在被否定、受委屈、被誤解、連續失敗或壓力高時反應會上升；事後多能恢復並修正。', '先辨識觸發情境，建立停損與復盤流程；給提前提醒與支持能顯著降低爆點。', '多數情況能維持理性，但在被否定、受委屈、被誤解或連續失敗時反應會上升；事後通常可回穩並修正，差異在於是否具備自我覺察與停損方法。', '{"do": ["辨識觸發情境並預先約定停損；用復盤把情緒轉成改善點；給提前提醒與支持（1on1/同儕）降低爆點"], "dont": ["不要把情緒反應直接貼成「難搞」；不要在高壓時用硬壓/指責；不要忽略觸發點而只要求忍耐"]}', 'SPA', '你平常是穩的，但踩到特定地雷就會上來；如果先抓到觸發點，再配一套停損流程，你會更快回到可解決的狀態。', '此區間差異在自我覺察與停損能力；管理上要教方法而非指責。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (564, 'SPA_18', 'C', 0, 34, '情緒穩定', '情緒反應門檻較高，遇到煩惱或衝突多能保持冷靜與理性處理，較少因一時情緒影響判斷、做出高代價決定。', '適合客訴、談判與高壓場景；可作為衝突情境的穩定支點。', '情緒反應門檻高，面對衝突多能冷靜理性處理，適合高壓、談判與客訴場景；但也可能較不外顯，需要確保有正常表達與釋壓管道，避免悶燒。', '{"do": ["安排在談判/客訴/高壓協調任務；建立正常回饋與表達機制；提供規律釋壓與復盤節奏"], "dont": ["不要把冷靜誤解成沒有感受；不要長期讓你承接所有高壓；不要缺乏表達管道導致累積到臨界點"]}', 'SPA', '你在壓力下通常很冷靜，很多人會覺得你很可靠；同時也要記得把壓力有地方說、有地方放，不要都自己吞。', '低易激不等於沒有情緒，可能較不外顯；仍需建立正常表達與壓力釋放管道，避免悶燒。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (565, 'CSR_01', 'A', 76, 100, '卓越進取', '對表現與成果有明顯企圖心，願意多投入以達到更高標準，遇到挑戰傾向主動升級方法與目標。', '適合高挑戰、高成長、需要拉高標準的任務；可作為衝刺型角色。', '對表現與成果抱持強烈企圖，會主動拉高標準、尋找挑戰，願意投入額外心力追求更出色的成績。', '{"do": ["可用於：①說明其在目標導向與追求成就上的動能，可作為衝刺型或關鍵任務的主力②建議搭配清楚的成長與回饋機制，把努力和成果連結清楚③提醒在高成就傾向下，也要留意休息與界線，避免過勞或過度自責。"], "dont": ["禁止：①以其成就動機為由，不斷加壓或延長工時③忽略資源不足、流程問題，只用「你應該更努力」回應落差③將短暫倦怠解讀為「不再上進」④把個人績效完全與人格價值綁在一起。"]}', 'CSR', '你不太滿足於「剛好過關」，比較習慣問自己「能不能再更好一點」，所以常會多做一些。', '高分不必然代表合作佳；若目標壓力過大，可能出現急躁或把成果放在協作之前。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (566, 'CSR_01', 'B', 51, 75, '目標驅動', '在目標清楚、回饋可見時會穩定投入；若缺乏指標或看不到進展，動能容易下降。', '以 KPI/OKR、里程碑與可視化進度維持續航；適合中長期專案的穩定推進者。', '對達成目標有穩定重視，當目標具體且看得到成果時，會願意投入努力；若缺乏指標或看不到成效，動能就比較容易下降。', '{"do": ["可用於：①說明其動機多與「目標清晰度、意義感與回饋」連動②建議在專案初期一起定義具體指標與節奏，並提供可見的進展回饋③鼓勵其主動提出自己在成就與發展上的期待，避免陷入被動。"], "dont": ["禁止：①將此區間簡化為「不上進」或「沒企圖心」②在缺乏方向與資源時，用壓力或比較逼其多做③忽略職務設計與獎酬機制對動機的影響④用單一時期的低動力推論其長期表現。"]}', 'CSR', '如果知道「做到這裡代表有進步」，你會願意出力；但如果目標很空或看不出差別，就會覺得再拼也不一定有用。', '此區間關鍵在回饋設計，同樣能力的人因回饋密度不同而呈現差異。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (567, 'CSR_01', 'C', 0, 50, '穩定達標', '傾向把工作完成在合理範圍，不一定追求更高難度或額外突破；動機更受環境支持與要求牽動。', '適合明確職責、節奏固定的工作；若期待突破，需提供動機意義與可達成的成長路徑。', '整體行事風格偏向穩穩完成要求，對「超標」「突破」的追求較弱，更傾向在合理範圍內把事情做完即可。', '{"do": ["可用於：①說明其適合在穩定執行與支持性角色中貢獻，而不宜期待高度競賽式表現②建議將其放在需要穩定完成、而非持續衝高指標的工作內容③鼓勵透過探索「自己覺得有成就感的事」來建立屬於自己的成就定義。"], "dont": ["禁止：①貼上「不求上進」「躺平」等道德化標籤②忽略職務匹配與成就感來源差異③用高壓業績文化要求其表現出強烈競爭性④將此分數當作否定其職涯發展可能的依據。"]}', 'CSR', '你會希望把分內的工作處理好，但不一定會為了拿第一名或打破紀錄，再多推自己好幾步。', '低分不等於不上進，需區分是價值觀取向或缺乏挑戰誘因。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (568, 'CSR_02', 'A', 76, 100, '信任合作', '在各類人際情境中都能自然展現信任與熱情，面對不確定或陌生的互動也不例外，合作與助人成為穩定的反應模式。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (569, 'CSR_02', 'B', 51, 75, '情境調節', '在多數互動中能展現合作與善意，當對方意圖不明確或溝通出現摩擦時，會暫時收回熱情並觀察後再決定投入程度。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (570, 'CSR_02', 'C', 0, 50, '戒備疏離', '在人際互動中傾向保持距離與戒備，較少主動展現信任或熱情，面對合作需求時容易出現猜疑反應。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (571, 'CSR_03', 'A', 76, 100, '無私付出', '面對高度個人犧牲的需求也不動搖付出意願，無私與體貼成為各類互動中的自然反應，較少因自身成本而退縮。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (572, 'CSR_03', 'B', 51, 75, '適度關懷', '在日常互動中展現體貼與關心，當付出涉及較大的個人犧牲時，會根據情境評估投入程度而非無條件奉獻。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (573, 'CSR_03', 'C', 0, 50, '自我優先', '面對他人需求時，傾向以自身利益為優先考量，較少主動展現體貼或犧牲行為。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (574, 'CSR_04', 'A', 76, 100, '易感厭倦', '無論活動形式如何變化，都容易迅速失去投入感，厭倦與無聊的體驗在各類情境中頻繁出現，難以透過外部刺激長時間維持興趣。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (575, 'CSR_04', 'B', 51, 75, '刺激依賴', '面對有挑戰性或新穎的活動時能保持投入，若活動持續單調且缺乏回饋，會逐漸失去興趣並尋求轉換。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (576, 'CSR_04', 'C', 0, 50, '持續投入', '在多數活動中能自然維持投入感，較少因缺乏新鮮刺激而產生無聊或厭倦。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (586, 'CSR_08', 'A', 76, 100, '高度自律', '做事有一致的自我要求，能主動掌握進度、顧品質與收尾，較少需要外部催促也能維持可靠輸出。', '可交付需要穩定產出、長期追蹤、責任界線清楚的任務；適合擔任流程 owner、專案控管與交付把關角色。', '整體呈現高度自律與責任感，做事會主動掌握進度、照顧品質與收尾細節，即使沒有外在催促也能維持穩定輸出。', '{"do": ["可用於：①說明其在自我管理、品質控管與長期專案追蹤上的穩定度②建議安排需要穩定產出、責任邊界清楚的任務或流程 owner 角色③鼓勵在維持高標準的同時，也留意工作量與身心負荷，避免過度投入。"], "dont": ["禁止：①把其盡責當成理所當然，不斷加派任務而不調整資源②將偶爾的延宕或失誤放大成「不負責」③以此分數假設其永遠不需要督導或回饋④把對細節的在意誤解為「愛挑別人毛病」。"]}', 'CSR', '你習慣把事情安排好、跟進好、收尾也做好，別人把任務交給你，大多會覺得放心。', '高分反映自律與責任感；若同時完美主義偏高，可能出現過度投入或對他人標準嚴苛。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (587, 'CSR_08', 'B', 51, 75, '任務可靠', '在目標、範圍與時程清楚時表現穩定；遇到優先序頻繁變動或責任邊界不清時，效率與投入度可能波動。', '以明確分工與里程碑提升穩定度；適合在既定流程內承擔主力執行與回報節點。', '面對目標、範圍與時程清楚的任務時，多能穩定完成並維持基本品質；當優先順序頻繁變動或權責模糊時，節奏與細緻度會跟著起伏。', '{"do": ["可用於：①說明其表現高度仰賴任務清晰度與外部結構②建議透過明確分工、里程碑與定期 check-in，協助其穩定輸出③鼓勵其學會主動釐清優先順序與需求，而不是悶著做。"], "dont": ["禁止：①在目標本身就模糊的前提下，將所有落差歸因於個人「不夠負責」②用零星案例貼上「時好時壞」的標籤③忽略管理與流程設計的責任，把結構問題丟給個人扛④期待其在混亂環境中依然維持完全同樣的表現。"]}', 'CSR', '只要知道要做什麼、什麼時候要完成，你通常都能把事情處理好；但如果規則常改、任務一直變，就會比較難穩住步調。', '此區間多反映對外部結構的依賴程度，不代表不負責。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (588, 'CSR_08', 'C', 0, 50, '節奏支援', '較容易受情境或情緒影響而出現拖延、鬆散或收尾不足；不是做不到，而是自我監控與維持節奏較吃力。', '搭配短週期拆解、檢核清單、同儕回報機制；先讓完成穩定，再逐步拉高品質。', '執行節奏容易受情緒、環境或干擾影響，偶爾會出現拖延、鬆散或收尾不足的情況，能力並非不足，而是在自我監控與維持節奏上較吃力。', '{"do": ["可用於：①指出其需要更多外部化工具（如任務拆解、檢核清單、固定回報節點）來穩定輸出②建議先把「準時完成」與「不漏掉」當成第一優先，再逐步拉高品質標準③鼓勵與主管或同事一起設計適合自己的節奏，而不是單靠意志力撐。"], "dont": ["禁止：①直接標籤為「懶散」「不可靠」②忽略工作量、干擾度與專注環境對其表現的影響③用羞辱或比較的方式要求「要自律一點」④將此分數視為否定其能力或潛力的理由。"]}', 'CSR', '你不是做不到，只是很容易被當下狀態、雜事或心情打斷，要自己撐住步調會比較累。', '低分不等於能力弱，常見是時間管理與優先序未形成固定習慣，管理重點在外部化流程。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (589, 'CSR_09', 'A', 76, 100, '主動掌控', '無論情境可控程度如何，都持續相信自身能影響結果並主動採取行動，掌控感在各類處境中都十分穩定。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (590, 'CSR_09', 'B', 51, 75, '範圍內行動', '在可掌握的範圍內會主動採取行動，若面對超出掌控的因素或回饋不明確時，會重新評估是否繼續投入。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (591, 'CSR_09', 'C', 0, 50, '被動因應', '面對事態變化時較少相信自己能產生影響，傾向被動等待結果而非主動採取行動。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (592, 'CSR_10', 'A', 76, 100, '先思後行', '行動前會評估風險、假設與後果，較少因一時判斷造成返工；在不確定情境能維持判斷品質。', '適合風險控管、決策審查、流程把關與合規情境；可擔任決策前最後一道檢核。', '做決定前習慣先思考情境、風險與可能結果，面對不確定時也能維持判斷品質，不會輕易被一時情緒帶走。', '{"do": ["可用於：①說明其在風險評估、策略討論與重要決策上的價值②建議投入錯誤成本高、需要深思熟慮的議題（如人事、合約、長期投資）③鼓勵在已充分思考的情況下，為行動設下明確時限，避免過度拉長決策。"], "dont": ["禁止：①將其審慎誤解為優柔寡斷②要求在資訊高度不足又風險極高時，仍「秒回決定」③忽略議題複雜度與資訊量，只用決策速度評論其能力④把多問幾句當成「找麻煩」。"]}', 'CSR', '你比較像是「先想一圈再出手」的類型，會先評估可能的後果，再決定要怎麼做。', '高分可能帶來速度成本；若任務要求快速試錯，需明確可接受的風險邊界。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (593, 'CSR_10', 'B', 51, 75, '情境權衡', '在重要決策會拉高審慎程度，但在時間壓力或熟悉任務可能簡化評估；品質受情境影響較大。', '提供決策模板（選項/風險/影響/備案）穩定發揮；適合在快慢要切換的團隊中。', '重要事情會刻意拉慢節奏、多想一下；對熟悉或看似小事的議題，則傾向簡化評估、快速做決定，實際謹慎程度會依情境調整。', '{"do": ["可用於：①說明其會依照「重要性」調整審慎程度②建議針對關鍵領域（如人員、預算）設定最基本的思考檢核點③鼓勵在「看似日常但影響深遠」的議題上，也保留一些審慎空間。"], "dont": ["禁止：①因為個別錯誤就說「都想不清楚」②忽略時間壓力、資訊不足等外因③用完美主義標準要求其所有決策都零失誤④把一兩次的疏忽視為長期固定問題。"]}', 'CSR', '遇到大事你會謹慎一點，平常的小決定就會比較順手、直覺地做，沒有每件事都想很久。', '避免用單次表現貼標籤；觀察高風險 vs 低風險情境差異更準。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (647, 'CSR_28', 'B', 51, 75, '責任隨界線而定', '在責任範圍清楚時能承擔並完成；若分工模糊或權責不對等，承擔度會受影響。', '先定義權責、交付標準與升級機制；適合制度清楚的專案體系。', '在合理範圍內會承認自己該負的責任；但當情境明顯不合理或自己影響力有限時，也會指出外在因素的影響。', '{"do": ["可用於：①說明其對責任的看法較貼近現實，能區分個人與系統因素②建議在檢討時，同時討論可控部分與制度層面調整③鼓勵其維持這種「不推責也不全扛」的健康平衡。"], "dont": ["禁止：①把其提到環境因素解讀為「在找藉口」②忽略實際權限與資源限制③只要求「要負責任」而不談如何賦權④用單一事件評價其是否具責任感。"]}', 'CSR', '該負的你會認，但如果很多事情明顯超出自己能控制的範圍，你也會說明不是全都在你身上。', '不是不負責，而是對可控範圍敏感；清晰度越高承擔度越高。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (594, 'CSR_10', 'C', 0, 50, '行動先行', '傾向先做再調整，評估常在行動後補上；在快速節奏下能衝刺，但也較容易忽略隱性風險。', '搭配快速檢核點與同儕 review 降低返工與踩雷；適合需要速度的工作。', '做事風格偏向「先做再說」，經常先行動再在過程中修正，對事前評估風險與前提的時間相對較少，在快速環境能推進，但也較容易忽略隱藏問題。', '{"do": ["可用於：①指出其在需要快速試錯、敏捷調整的情境中具行動優勢②建議在高風險或一次性決策前，設置簡單的「停一下先想」流程③鼓勵與較審慎的同事搭配，在速度與風險之間互相補位。"], "dont": ["禁止：①直接貼上「莽撞」「沒在想」的標籤②忽略制度、時程與壓力對其行動風格的影響③只用事後責備處理錯誤，而不提供前期支援④把此分數當作否定其判斷力的理由。"]}', 'CSR', '你很多時候會先去做、邊做邊調整，不太會在一開始就把所有細節想透。', '低分不等於魯莽，可能偏好迭代式思考；管理重點在補足關鍵停看聽節點。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (595, 'CSR_11', 'A', 76, 100, '規範堅守', '高度重視承諾、規則與責任邊界，遇到灰色地帶也傾向選擇可被交代、可被信任的做法。', '適合合規、資安、機敏資料等高度信任情境；可放在制度與文化的穩定器位置。', '對承諾、規則和職責界線有強烈重視，遇到灰色地帶時，也會傾向選擇站得住腳、講得清楚的做法。', '{"do": ["可用於：①說明其在守信、合規與高度信任情境中的重要性②建議安排需高度可靠與可追溯性的任務（如合約控管、稽核、長期客戶關係）③鼓勵在堅守原則的同時，也學習與組織討論不合理規範。"], "dont": ["禁止：①把其義務感當成免費勞力，不斷追加責任②用「你有責任」掩蓋制度或資源問題③期待其為了組織利益長期犧牲個人健康與生活④在其提出合理界線時，批評為「不夠有責任感」。"]}', 'CSR', '你會很在意「答應過的事要做到」以及「事情要交代得過去」，對規則和責任界線也比較敏感。', '高分者在不合理規範下可能壓力較大；需提供申訴/調整流程避免僵化遵循。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (596, 'CSR_11', 'B', 51, 75, '規則導向', '大多遵守規範，但在資源不足或目標衝突時會尋求折衷；通常需要明確指示什麼不能動。', '把不可妥協底線講清楚，其餘留彈性可提升效率與配合度。', '大多數情況會遵守規範與承諾，但在資源不足、規則矛盾或多重目標拉扯時，會尋找折衷作法，希望在「守規矩」與「把事情做成」之間取得平衡。', '{"do": ["可用於：①說明其在實務現場會同時顧及原則與效率②建議清楚界定「真的不能動的底線」，其他部分保留彈性空間③鼓勵當規範與目標衝突時，用對話尋找更好的做法，而非悶著承擔。"], "dont": ["禁止：①把情境下的權衡解讀為「沒有責任感」②忽略制度設計與資源條件對行為的限制③用單一事件批評其立場不堅定④要求其在沒有任何空間與支援下，仍獨自扛起所有義務。"]}', 'CSR', '你基本上會照規則來，但如果資源不夠、規定有矛盾，或這樣做會讓事情完全卡住，你也會想辦法找折衷。', '常見於務實型人才；管理者要給原則而非每一步細則。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (597, 'CSR_11', 'C', 0, 50, '彈性取捨', '較容易把規範視為可調整的工具，遇到目標壓力可能優先選擇結果導向做法，需要較強的底線提醒。', '以雙人覆核、紀錄透明、權限控管等制度降低風險；適合創新但需控風險。', '面對規範時較常以「工具」而非「原則」來看待，遇到壓力或目標強烈時，容易優先選擇對結果有利的做法，需要更清楚的底線提醒與制度控管。', '{"do": ["可用於：①指出其在需要彈性、突破與實作導向的情境中具優勢，但需設好界線②建議透過權限控管、雙人覆核與紀錄透明來降低風險③鼓勵在追求結果的同時，也思考長期信任與風險成本。"], "dont": ["禁止：①直接標籤為「沒原則」「會亂來」②忽略目標壓力與制度缺陷對其選擇的影響③完全用道德指責代替制度設計④把此分數當作預測其必然違規或不誠信。"]}', 'CSR', '你比較容易把規則當成可以調整的東西，如果壓力很大、目標很硬，就會先想「怎麼做比較有效」，而不是完全照規定。', '低分不等於不誠信；需區分討厭形式或忽略底線，建議以情境驗證。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (598, 'CSR_12', 'A', 76, 100, '敢承擔會達成', '對努力能換來結果有明確信心，遇到高標目標傾向主動拆解與推進，較不容易因不確定而退縮。', '適合推進型任務與需要自我驅動的角色；可給較高自主權並期待自我解題。', '面對具有挑戰的目標時，多半相信「只要我願意投入，就有機會做到」，傾向主動拆解目標並推進，而不是因不確定而退縮。', '{"do": ["可用於：①說明其在承接挑戰性任務與帶頭推進方面的潛力②建議提供明確標準與資源，讓其效能感轉成具體成果③提醒在失敗時，不要把所有責任全往自己身上扛，以免效能感反向受損。"], "dont": ["禁止：①把其高效能感視為可以忽略支援與環境條件的理由②在結果不佳時，以更重的道德壓力批評「你本來就做得到」③期待其一人填補所有制度缺口④用短暫挫折推論其信心已崩壞。"]}', 'CSR', '你看到高標目標時，比較容易想「可以怎麼做」而不是「這太難」。', '高分不等於判斷一定正確；仍需回饋迴路避免過度自信。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (599, 'CSR_12', 'B', 51, 75, '需要確認再加速', '能力感多半足夠，但在新領域或高風險情境會希望先確認方向；一旦標準清楚就能穩定輸出。', '以成功標準、階段檢核與教練式回饋拉升信心與速度；適合在導師制團隊中成長。', '對熟悉或曾經成功的類型較有把握，遇到全新領域或高風險任務時，會先關注方向是否正確、支援是否足夠，再決定要投入多少。', '{"do": ["可用於：①說明其效能感與「掌握度」高度相關②建議在新任務上提供導入說明、示範與可詢問對象，縮短不確定期③鼓勵其把過去克服困難的經驗帶到新的情境中，協助建立信心。"], "dont": ["禁止：①將謹慎視為「沒自信」或「不敢扛責」②忽略資源與資訊不足對投入意願的影響③只用「你要勇敢試」而不調整外在條件④以此分數否定其接新角色的可能性。"]}', 'CSR', '對你有經驗的事情會覺得「OK，這可以試」，但對完全沒碰過的，你會先觀察、確認再全力衝。', '容易被誤讀為不自信；其實是對不確定敏感，需要清晰度。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (600, 'CSR_12', 'C', 0, 50, '容易自我懷疑', '對能否完成目標缺乏把握，面對挑戰可能遲疑、過度求證或依賴他人決策，影響推進節奏。', '用小步成功累積、降低啟動門檻並提供明確指引與正向回饋；避免一開始就丟高不確定責任。', '對「即使努力也未必成功」的感受較強烈，面對較大的目標時容易預期失敗，因而降低投入意願或傾向選擇風險較低的選項。', '{"do": ["可用於：①指出其效能感可能受過往「努力與結果落差」經驗影響，需要透過小成功經驗重新建立②建議設計可控性較高、步驟清楚的目標，減少徒勞感③鼓勵其記錄具體的進步與做到的事情，而不是只放大失敗。"], "dont": ["禁止：①把其保守選擇簡化為「不努力」②忽略機會不均、資源限制與系統問題③用嘲諷或比較方式施壓「你要有自信」④把此分數視為無法恢復的信心問題。"]}', 'CSR', '你可能常會想「就算我很努力，也不一定有用」，所以會選擇比較安全、不會太冒險的做法。', '低分不等於能力差，常與過往經驗與環境回饋相關；建議結合行為證據。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (601, 'CSR_13', 'A', 76, 100, '深度關懷', '面對大量且持續的困境也不減損同情與關懷的深度，對他人需求的敏感在各類互動中穩定展現，情感投入不因消耗而退縮。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (602, 'CSR_13', 'B', 51, 75, '適度同理', '在日常互動中能敏感察覺他人的需求與困境並展現關心，若同時面對多重壓力或情緒負荷較高時，會調節自身投入的情感程度。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (603, 'CSR_13', 'C', 0, 50, '情感疏離', '面對他人困境時情感反應較為平淡，較少自發產生同情或關懷的衝動，傾向理性看待而非情感投入。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (604, 'CSR_14', 'A', 76, 100, '原則守公平', '即使想領先或達成目標，仍傾向拒絕欺騙、偷竊、貪污或利用他人的手段，重視對等與規則一致。', '適合資源分配、制度設計、採購與治理等角色，提升信任與長期穩定。', '對公平與正義有強烈敏感度，對欺負弱勢、作弊或佔他人便宜的行為常會感到不舒服，傾向維護制度與互動中的公正。', '{"do": ["可用於：①說明其在維護制度正當性與團隊公信上的重要性②建議在流程設計、規則檢討與倫理議題中納入其觀點③提醒在高度不公情境下，其挫折與憤怒感可能更強，需要支持與對話空間。"], "dont": ["禁止：①把其對公平的堅持視為「不識相」或「太理想」②忽略組織結構與決策不透明對其壓力的影響③期待其單獨扛起對抗不公的任務④因其提出質疑就標籤為「麻煩人物」。"]}', 'CSR', '你看到明顯不公平的事情，會特別在意，覺得「這樣不太對」，也比較希望事情可以講求公道。', '高分不等於不競爭，而是競爭方式更在乎正當性與可被檢驗。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (605, 'CSR_14', 'B', 51, 75, '情境權衡', '大多願意遵守公平規則，但在強烈競爭或目標壓力下可能出現擦邊球心態，視環境容忍度調整行為。', '明確規則與後果（紅線、稽核、透明），並提供可行達標方法避免手段化。', '原則上不贊同不公平的作法，但在權力不對等、風險較高或氛圍緊繃的情境中，有時會選擇觀望、沉默或有限度表達。', '{"do": ["可用於：①說明其在價值與安全感之間的拉扯②建議建立安全管道（如匿名回饋、正式申訴流程），降低其發聲成本③鼓勵其在可掌握的範圍內練習表達，逐步累積為公平發聲的經驗。"], "dont": ["禁止：①把沉默直接解讀為「贊同不公」②忽略權力結構與心理安全感不足③用「你怎麼不早說」責怪其沒出聲④將一次沉默視為長期價值觀問題。"]}', 'CSR', '你會覺得公平很重要，但在現實複雜或講了可能對自己不利時，也會猶豫要不要出聲。', '此區間不可只看口頭價值觀，建議觀察利益衝突時的實際選擇。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (606, 'CSR_14', 'C', 0, 50, '手段傾向', '較容易把領先視為第一順位，可能合理化不公平手段或利用他人換取優勢。', '高風險領域需加強權限控管、雙人覆核與稽核；角色配置宜更謹慎。', '對「世界本來就不會完全公平」這件事接受度較高，傾向優先確保自己不吃虧，對制度或利益分配不均的敏感度相對較低。', '{"do": ["可用於：①指出其在高度競爭或差異報酬環境中可能較能適應，但也存在關係與文化風險②建議明確說清楚組織不可違反的公平底線③鼓勵其思考長期合作、信任與團隊士氣對結果的影響。"], "dont": ["禁止：①直接貼上「沒良心」「沒是非」標籤②忽略其可能曾經歷長期不公平而產生的防衛③只用指責要求其「要有正義感」④以此分數推論其一定會做出嚴重不公行為。"]}', 'CSR', '你可能會覺得，只要不要自己吃太大的虧，有些不那麼公平的事也還能接受，重點是顧好自己。', '低分是風險指標，建議搭配制度設計與行為觀察，不宜只靠溝通期待改善。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (607, 'CSR_15', 'A', 76, 100, '服從配合', '不分情境都能穩定配合既有規定與程序，面對與自身判斷不一致的指示也能維持高度遵從，質疑或抗拒的反應極為少見。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (608, 'CSR_15', 'B', 51, 75, '理解後遵從', '在指示清楚且理由充分時會配合執行，若指示模糊或缺乏說明，會先確認意圖再決定遵循程度。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (609, 'CSR_15', 'C', 0, 50, '獨立挑戰', '對既有指示與規定的配合度較低，面對程序要求時傾向質疑或挑戰而非直接遵從。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (610, 'CSR_16', 'A', 76, 100, '放下釋懷', '對放下怨恨與恢復好感的傾向不受冒犯嚴重程度影響，遭遇重大信任違背或反覆傷害後仍能選擇寬恕，寬容態度十分穩定。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (611, 'CSR_16', 'B', 51, 75, '視情寬容', '面對一般性的冒犯或過失時能較快放下不滿，若遭遇嚴重的信任違背或重複性傷害，會需要較長時間才能恢復信任。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (612, 'CSR_16', 'C', 0, 50, '持續記恨', '面對冒犯或過錯時較難釋懷，傾向長時間持有不滿，恢復對對方的信任需要相當漫長的過程。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (613, 'CSR_17', 'A', 76, 100, '溫和寬容', '在各類互動中都能保持溫和有禮的態度，面對高度摩擦或對方反覆犯錯也不例外，嚴厲或批評性的回應極為少見。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (614, 'CSR_17', 'B', 51, 75, '適度溫和', '在多數互動中展現溫和與禮貌，若面對反覆出現的問題或對方態度不佳的情境，會在寬容與直接表達之間調整方式。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (615, 'CSR_17', 'C', 0, 50, '直接嚴厲', '評價他人時傾向直接且嚴厲，較容易做出批評性的判斷，互動中較少展現寬容或緩和的態度。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (616, 'CSR_18', 'A', 76, 100, '韌性充沛', '無論逆境強度或持續時間如何，都能維持充沛的內在資源來緩衝負面影響，堅毅韌性在各類壓力處境中穩定展現。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (619, 'CSR_19', 'A', 76, 100, '誠正節制', '在利益與目標可見的情境下仍能維持誠懇與公正，對財富、地位與特權不會過度執著，也較少炫耀或佔便宜。', '適合需要高度信任的工作（資源分配、敏感資訊、合規與治理）；可作為文化示範者。', '整體價值觀傾向重視誠實、公平與謙遜，對貪圖不當利益、濫用特權或炫耀地位較為排斥。', '{"do": ["可用於：①說明其在信任、倫理與風險控管上的重要性②建議安排在需要高度誠信與長期信賴的職務（如金流、合約、關鍵客戶）③鼓勵組織在制度與文化上與其價值相符，減少價值衝突感。"], "dont": ["禁止：①以其高誠實謙遜為由，忽視公平報酬與合理待遇②在制度不公時只要求個人「要有道德」③把其視為可無限承受價值衝突的防火牆④假設其永遠不會做出錯誤判斷。"]}', 'CSR', '你在意事情是不是光明正大，也不喜歡靠關係或特權撈好處，對炫耀財富或地位的行為比較不買單。', '高分不等於不競爭，而是競爭方式較重視正當性與長期信任資本。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (620, 'CSR_19', 'B', 51, 75, '原則彈性', '多數時候能維持公平與誠實，但在強壓績效或利益衝突下，可能在達標與原則間做權衡。', '把不可妥協底線講清楚（利益揭露、流程透明），並提供可行達標路徑。', '整體而言重視誠實與公平，但在壓力大、競爭激烈或灰色地帶情境中，會同時在意現實與原則，試圖在兩者之間找平衡。', '{"do": ["可用於：①說明其價值觀與現實考量之間的拉扯狀態②建議組織釐清倫理底線與可接受做法，減少個人單獨承擔的壓力③鼓勵在困惑情境中透過對話，而不是獨自吞下矛盾。"], "dont": ["禁止：①因其猶豫或折衝，就貼上「不誠實」標籤②忽略文化、獎酬與權力結構對行為的影響③用道德壓力掩蓋制度缺陷④把單一次的妥協視為長期人格問題。"]}', 'CSR', '你基本不喜歡不公不義的事，但在壓力很大或大家都這樣做的情況下，也會掙扎「這樣是不是還能接受」。', '此區間需看遇到誘惑時的選擇，不宜只用日常互動判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (621, 'CSR_19', 'C', 0, 50, '利益傾斜', '較容易重視利益、地位或外在象徵，可能合理化先拿到再說的做法，對公平與謙遜的自我要求較弱。', '在規範清楚、權限可追溯的環境運作；加強監督、審核與利益衝突管理。', '對財富、特權與自身利益的重視度較高，在作決定時容易優先考量「對自己是否划算」，對利用規則邊界或強調自身地位的接受度較高。', '{"do": ["可用於：①指出其在強競爭、高獎酬環境中可能具有推進成果的動力，但需要明確的倫理與合規框架②建議透過制度設計與監督機制，界定可接受與不可跨越的行為界線③鼓勵其思考長期信任與聲譽對自身利益的影響。"], "dont": ["禁止：①直接將其等同於「不誠實」「會做壞事」②忽略組織獎勵結構對價值偏移的影響③以羞辱方式處理價值議題，而不提供具體標準與討論空間④把此分數視為其必然會違法或嚴重失當的預測。"]}', 'CSR', '你會比較在意自己有沒有得到應得甚至更多的好處，對於運用關係、資源或規則邊邊角角，會覺得只要不太過就是合理手段。', '低分不等於一定不誠信，但風險較高；建議搭配情境題與行為證據。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (622, 'CSR_20', 'A', 76, 100, '目標路徑清晰', '能把目標具體化，並同時具備推進動機與替代路徑思考；遇到阻礙時能改道而不放棄。', '適合策略化推進、拆解路徑與持續優化的任務；可負責專案規劃與排除障礙。', '對未來有相對清晰的目標感，也能思考多條可行路徑，遇到阻礙時傾向調整做法而不是放棄方向。', '{"do": ["可用於：①說明其在目標設定與路徑規劃上的優勢②建議參與中長期計畫與改善專案的設計與推進③鼓勵在修正路徑時，同步檢視目標是否仍符合自身價值與現實。"], "dont": ["禁止：①期待其永遠保持清晰方向、從不迷惘②用「你不是很有目標嗎」壓過其目前困境③忽略資源與外部環境對達成目標的影響④將短暫失去動力視為不被允許。"]}', 'CSR', '你大概知道自己要往哪裡走，也會想「那如果這條路不通，可以怎麼繞過去」。', '高分不是空泛正向，而是目標感與路徑感並存；可觀察其是否具備備案思維。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (623, 'CSR_20', 'B', 51, 75, '動機可續航', '有目標動機，但路徑規劃有時需要外部引導；當方法不順時可能卡住，重新對齊後能再推進。', '用路徑拆解、選項清單與障礙排除會議提升連續性；適合在有策略框架的團隊成長。', '對未來大致有想像或方向，但在具體步驟與策略上仍在摸索，遇到環境變化或挫折時，較容易感到卡住，需要更多討論與陪伴釐清。', '{"do": ["可用於：①說明其在願景與路徑之間存在過渡期②建議提供職涯諮詢、導師制度或教練式對話，協助把方向拆成可行步驟③鼓勵從短期可實踐的小目標開始，降低不確定感。"], "dont": ["禁止：①將其猶豫解讀為「沒目標」「沒企圖心」②忽略機會結構與資訊不對稱③只用「自己要想清楚」回應其困惑④以此分數否定其長期發展。"]}', 'CSR', '你大概知道想成為什麼樣的人，但「要怎麼走到那裡」有時還不太確定，遇到變化就會更猶豫。', '此區間關鍵在卡住時怎麼辦；提供替代方案模板比單純打氣有效。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (624, 'CSR_20', 'C', 0, 50, '路徑不足', '可能有想達成的目標，但較難把動機與策略化路徑連結；遇到阻礙時容易停滯或轉向。', '先建立短期可達成目標與清晰下一步，搭配教練式提問與資源支持，逐步建立路徑思考能力。', '目前較難具體描述長期想追求的目標，對未來多半停留在模糊或「先顧好眼前再說」的狀態，較少主動規劃遠期方向。', '{"do": ["可用於：①指出其可能正處於「優先處理當下」的階段②建議透過探索活動、不同嘗試與陪談，一點一點幫助其長出較有個人感的目標③鼓勵從短期小目標開始，讓「未來可以被塑造」的感覺慢慢變清楚。"], "dont": ["禁止：①標籤為「沒未來性」「沒理想」②忽略其現實壓力、資源或資訊限制③用批判或嘲諷逼其立即說出長期藍圖④把此分數視為固定且不可改變。"]}', 'CSR', '你現在可能比較多在處理眼前的事，要說很清楚的長期目標，會覺得有點遙遠或抽象。', '低分不等於沒有企圖心，常見缺乏方法感或過往受挫；管理重點在給路徑而非叫他有希望。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (625, 'CSR_21', 'A', 76, 100, '自制穩定', '能管理情緒與衝動反應，在壓力下仍維持一致行為與判斷，不易因一時情緒做出高代價決定。', '適合高壓、客訴、談判等需要穩定情緒輸出的角色；可作為團隊情緒穩定器。', '衝動與情緒來時，多半能先踩煞車、評估一下後果，再決定要不要說或要不要做，短期誘惑不容易完全蓋過長期考量。', '{"do": ["可用於：①說明其在情緒管理、風險行為與重要承諾上的穩定度②建議在需要冷靜判斷與高自制的角色中善用此特質③鼓勵在自我壓抑與健康表達之間找到平衡，不必永遠當「情緒黑洞」。"], "dont": ["禁止：①把其穩定當成無限承受情緒與壓力的理由②忽略其內在耗損，只期待「你一定撐得住」③批評偶發情緒失控為「不應該」而不看長期表現④把高自制等同於不需要支持。"]}', 'CSR', '就算一瞬間很想發作或很想立刻答應，你通常還拉得住自己一下，先想一下「這樣做之後會怎樣」。', '高分不等於不表達情緒；重點是能選擇合適方式表達與處理。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (626, 'CSR_21', 'B', 51, 75, '情境波動', '一般狀態自制力良好，但在連續高壓、衝突或睡眠不足時，反應可能變快、語氣變硬或耐心下降。', '建立高壓期節奏（輪班、緩衝、降噪）與復盤機制；在有支持系統下承擔前線任務。', '平時多能控制自己的反應與衝動，但在長期壓力、嚴重疲勞或連續挫折的情況下，情緒與行為有時會一時失衡。', '{"do": ["可用於：①說明其衝動管理與壓力、體力高度連動②建議建立壓力預警機制（例如自覺快爆時先暫停決定）③鼓勵在事後檢討時，把重點放在調整做法，而不是單純自責。"], "dont": ["禁止：①只用單一事件否定其平常的自制力②忽略制度與工作負荷對其情緒穩定的影響③以「你不可以這樣」作為唯一回應，而不討論實際調整策略④把情緒反應視為人格缺陷。"]}', 'CSR', '你大部分時候都還撐得住，但當很多事疊在一起、又很累的時候，也可能會突然說重話或做了之後覺得太快的決定。', '此區間要看觸發條件；找出何時失控、何時穩定，才能設計有效支持。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (627, 'CSR_21', 'C', 0, 50, '衝動風險', '較容易被情緒推著走，出現衝動回應、倉促承諾或行為過頭；事後常需要修補或解釋。', '降低高衝突暴露、提供情緒停損流程（先暫停/先寫後說/第三方介入）；用規範保護本人與團隊。', '當情緒被挑起或短期誘惑出現時，較容易順著當下感覺行動，事後才意識到後果或產生懊惱，需要更多「多一拍思考」的協助與設計。', '{"do": ["可用於：①指出其在衝動管理上需要具體的環境與流程輔助（例如預設等待時間、找人商量）②建議設計簡單的自問機制，如「這樣做之後一週後我會怎麼看？」③鼓勵用負責但不自我否定的方式看待過去失誤，從中練習新的反應模式。"], "dont": ["禁止：①貼上「沒自制力」「不成熟」的標籤②忽略壓力、情緒與環境刺激對行為的影響③單靠責罵或羞辱要求其改變④將此分數與任何臨床診斷畫上等號。"]}', 'CSR', '你有時會先照當下的情緒或直覺做了，過一陣子才覺得「好像有點太快」。', '低分不代表不適任，但需要環境設計與技能訓練並行。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (628, 'CSR_22', 'A', 76, 100, '高度敏感', '無論不確定性的程度輕重，都容易產生強烈的負面反應與持續焦慮，對模糊與未知的忍受度在各類情境中都極低。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (629, 'CSR_22', 'B', 51, 75, '有限容忍', '在不確定性有限且可預見時間框架時能從容因應，若面對長期懸而未決或完全無法預測的情境，負面反應會明顯增加。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (630, 'CSR_22', 'C', 0, 50, '從容接受', '面對不確定情境時能維持穩定，對模糊與未知的容忍度較高，較少因缺乏明確資訊而產生焦慮反應。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (631, 'CSR_23', 'A', 76, 100, '重價值不重物', '相對不把財富與地位視為主要追求，決策更看重意義、成長或關係品質，較不易被物質誘因牽動。', '適合使命導向或長期投入工作；激勵方式偏成就感、自主與成長資源。', '對金錢、頭銜與外在排場的重視度相對較低，更傾向用意義感、關係與內在成就感來衡量一份工作值不值得。', '{"do": ["可用於：①說明其在追求有意義工作與內在報酬上的傾向②建議以成長機會、影響力與價值實現作為重要激勵來源③提醒組織仍須提供公平報酬，避免以「使命」為由忽略基本待遇。"], "dont": ["禁止：①以其低物質傾向為藉口壓低薪資或福利②用「你不是不看重錢嗎」來逼其接受不合理條件③假設其完全不在意物質生活品質④忽略其對基本安全感的正當需求。"]}', 'CSR', '你當然也需要收入，但不會只用「薪水多少、頭銜多大」來決定事情好不好，更在意內容是不是有價值。', '高分不代表不在乎薪酬，而是物質誘因邊際效果較低，需用不同激勵槓桿。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (632, 'CSR_23', 'B', 51, 75, '務實平衡', '能理解物質與地位的重要性，但不會完全被其主導；會在價值、生活需求與回報之間做合理取捨。', '清楚薪酬制度與可見成長路徑最有效；也能接受績效激勵但需要公平透明。', '既重視合理薪酬與生活品質，也會把工作內容、成長空間與環境氛圍納入考量，在物質與非物質報酬之間尋求平衡。', '{"do": ["可用於：①說明其在評估機會時會綜合考慮多面向②建議在職涯溝通時，同時談報酬、發展與意義感③鼓勵其清楚表達對薪資與環境的期待，而不是壓抑需求。"], "dont": ["禁止：①將對合理報酬的要求貼上「現實」「勢利」標籤②忽略市場行情與貢獻價值③只用理想或使命感要求其忽略物質條件④用此分數評價其人格高低。"]}', 'CSR', '你會希望薪水合理、生活過得去，但也知道「只看錢」不一定會快樂，會一起看內容、學習機會跟團隊氛圍。', '此區間通常彈性最高，重點在制度可信度，否則容易轉向比較。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (633, 'CSR_23', 'C', 0, 50, '高度物質導向', '較重視財富、地位或外在象徵，對回報敏感，可能把物質激勵視為投入與忠誠的主要交換條件。', '適合獎酬明確、成果可量化角色；避免模糊承諾，並以公平制度降低比較摩擦。', '對薪酬、福利、頭銜與外在認可的敏感度較高，容易把這些視為「有沒有被重視」的重要訊號，物質與地位在決策中占較大比例。', '{"do": ["可用於：①指出其在獎酬明確、競爭導向的環境中可能動機強勁②建議清楚解釋薪酬架構、升遷條件與獎勵機制，減少不確定感③鼓勵其同時培養對內在成就與專業成長的重視，讓滿足來源更穩定。"], "dont": ["禁止：①直接貼上「拜金」「很勢利」的標籤②忽略其過往可能被低估或不公平對待的經驗③用道德批評否定其對物質條件的要求④把此分數當作預測其一定會為利益犧牲原則的依據。"]}', 'CSR', '你會很在意待遇好不好、頭銜夠不夠看，以及別人怎麼看待你的位置，覺得這些都代表你有沒有被好好對待。', '低低物質傾向不等於貪婪，而是動機偏外在回報；管理關鍵在規則清楚。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (634, 'CSR_24', 'A', 76, 100, '低自我中心', '對自身與他人的相對位置看法較平衡，不太需要透過炫耀或壓過他人來證明價值，較能接受他人貢獻。', '適合團隊協作、共同署名與跨部門合作，降低內耗與功勞爭奪。', '較自然地把自己視為團隊的一員，而非特別應該被優待的人，習慣低調表達貢獻，不會刻意凸顯自己。', '{"do": ["可用於：①說明其在團隊合作、學習與接納回饋上的優勢②建議在需要降低階級距離、建立信任氛圍的情境中善用此特質③鼓勵在合適場合也能清楚說出自己的貢獻，避免長期被低估。"], "dont": ["禁止：①因為其謙虛就忽略或壓低其成果與待遇②用「你很謙虛」包裝客觀上的不公平③期待其永遠把他人放在自己前面④用文化期待壓抑其合理的自我主張。"]}', 'CSR', '你不太會主動強調「我有多厲害」，也不太習慣要求特別待遇，比較傾向讓成果自己說話。', '高分不等於缺乏企圖心；可能是自我價值穩定，因此不需外顯證明。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (635, 'CSR_24', 'B', 51, 75, '自信含蓄', '能肯定自己但表達較保留；在需要展現影響力或爭取資源時，可能猶豫如何拿捏分寸。', '給明確發聲場域與表達框架（成果呈現、角色授權），提升影響力而不違背風格。', '整體能保持不誇大、不自我膨脹的態度，但在需要爭取機會或介紹自己的場合，也有能力適度呈現個人成果。', '{"do": ["可用於：①說明其在謙虛與自我行銷間較能拿捏分寸②建議在重要場合協助其更具體呈現亮點，以免低估自己③鼓勵持續維持這種彈性，不因環境壓力走向過度自貶或過度自誇。"], "dont": ["禁止：①因其在某些場合展現自信就批評為「不謙虛」②忽略角色本身對曝光與表現的要求③用單一互動經驗判斷其整體人格④要求其完全抹去自我存在感。"]}', 'CSR', '你平常不會特別炫耀自己，但如果需要投履歷、簡報或爭取機會，也能把自己做過的事講清楚。', '此區間易被誤判不積極；需分辨表達風格或缺乏主張。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (636, 'CSR_24', 'C', 0, 50, '自我凸顯', '較傾向強調自身貢獻與地位，可能把被看見視為重要需求，對他人表現的接受度較敏感。', '以透明功勞分配與評價制度降低衝突；安排在對外代表或競爭型任務可能更合適。', '較常覺得自己的付出與能力應該獲得更多關注與禮遇，習慣主動凸顯自身貢獻與重要性，期待被特別看見。', '{"do": ["可用於：①指出其在爭取資源、機會與可見度時的主動性優勢，但須留意團隊感受②建議透過具體回饋幫助其調整表達方式，讓自我肯定不至於壓過他人③鼓勵其在展現自己之外，也刻意練習看見與肯定周遭成員。"], "dont": ["禁止：①直接標籤為「自大」「目中無人」②忽略其過去可能長期被低估而需要用力爭取③用羞辱方式壓抑其自我肯定④以此分數推論其無法良好合作。"]}', 'CSR', '你可能會覺得「我做了這麼多，應該要被好好看見」，也會比較常主動提到自己的成果。', '低謙虛不必然負面，關鍵在是否影響合作與公平。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (637, 'CSR_25', 'A', 76, 100, '把不順視為暫時', '對挫折的解釋偏向可改善、可轉機，較能維持希望感與行動力，不易被單次失敗打垮。', '適合帶動士氣、在不確定中推進的任務；可作為團隊動能來源。', '看事情時比較容易先看到可能性與希望，面對挫折也傾向解讀為暫時的阻礙，而不是全面否定自己或未來。', '{"do": ["可用於：①說明其在壓力與變動中維持希望感與行動動能的能力②建議在變革、轉型或高不確定專案中，善用其穩定團隊士氣的特質③鼓勵把樂觀轉化為行動計畫，而不是只停留在「應該會好」的想像。"], "dont": ["禁止：①把其樂觀看成「什麼都不怕」而不討論風險②用樂觀掩蓋現實問題或資源不足③在對方感到沮喪時，用「你不是很樂觀嗎」否定其當下感受④暗示只要樂觀就不需要制度與支援。"]}', 'CSR', '你通常會覺得「雖然不順，但應該還有辦法」，比較少因一次挫折就對一切失去信心。', '高分不等於盲目正向；仍需風險評估避免忽視限制。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (638, 'CSR_25', 'B', 51, 75, '現實中保有期待', '多半能保持正向，但在連續不順或高壓時會短暫消沉；看見進展與資源後能恢復。', '以可視化進度、明確下一步與支持系統維持動能；適合穩健節奏。', '面對多數情況時能維持基本正向看法，但在連續挫折或高度不確定時，心情與信心會隨情境明顯波動。', '{"do": ["可用於：①說明其樂觀程度與事件頻率、壓力強度高度連動②建議在關鍵階段提供資訊透明與具體進展，減少不必要的悲觀解讀③鼓勵透過記錄小成功、與他人對話來調整看事情的角度。"], "dont": ["禁止：①把偶爾的低落解讀為「很負面」②忽略環境與事件累積對其心態的影響③只用「想開一點」要求其振作，而不處理問題本身④把樂觀程度簡化為個人意志力強弱。"]}', 'CSR', '一般情況下你還算樂觀，但如果連續遇到不順或變化太多，就會比較容易懷疑「真的會好轉嗎」。', '此區間需要可見的改善路徑，比單純鼓勵更有效。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (639, 'CSR_25', 'C', 0, 50, '容易悲觀解釋', '傾向把不如意視為長期且普遍，可能降低嘗試意願與抗挫力，遇阻礙容易預期失敗。', '從可控小目標建立成功經驗，搭配教練式提問與資源支持；避免長期無回饋任務。', '在面對壓力、變動或不確定時，較容易先想到可能的風險與失敗結果，對「事情會變好」的想像較不自然。', '{"do": ["可用於：①指出其在風險覺察上具敏感度，但也較容易陷入悲觀循環②建議引導其平衡「最壞情境」與「可行對策」，從可控部分著手③鼓勵透過具體行動與小成果，慢慢修正「事情都不會變好」的內在腳本。"], "dont": ["禁止：①直接貼上「負面」「愛抱怨」標籤②忽略其過往挫折或資源不足對世界觀的影響③用雞湯式鼓勵要其立刻變樂觀④把此分數當作不適合承擔重要任務的單一依據。"]}', 'CSR', '你可能常會往壞的方向先想，對「一切會順利」這種說法會抱持懷疑，覺得還是要準備最壞的打算。', '低分常與環境連續挫敗相關；需結合近期事件脈絡判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (640, 'CSR_26', 'A', 76, 100, '流程有序', '偏好清楚流程與例行節奏，能把資訊分類、把任務排程並維持一致做法，降低遺漏與混亂。', '適合流程設計、營運管理、專案行政與品質控管；可建立團隊共通作業標準。', '對秩序與結構有明顯偏好，會主動整理流程、資料與環境，讓事情有條有理地進行，以降低遺漏與混亂。', '{"do": ["可用於：①說明其在流程整理、檔案管理與專案規畫上的貢獻②建議擔任需要維持秩序與結構的角色（如 PM、系統整理、SOP 設計）③鼓勵在需要彈性的情況下，也允許自己保留部分「尚待探索」空間。"], "dont": ["禁止：①把其對條理的堅持解讀為「龜毛」「難相處」②忽略組織本身的混亂對其壓力的影響③期待其單獨扛起全部整理和制度化工作④把偏好秩序等同於缺乏創造力。"]}', 'CSR', '你喜歡把「東西放哪裡」「下一步是什麼」都弄清楚，環境太亂或流程太散會讓你不太安心。', '高分者在高度變動或需要即興場景可能不適；要允許部分任務採彈性模式。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (641, 'CSR_26', 'B', 51, 75, '重點整理', '會整理重點與基本秩序，但不一定每件事都系統化；在多工時需要工具或提醒來維持條理。', '提供共用看板、固定回報節點與簡單模板即可顯著提升；適合兼顧彈性與秩序的型態。', '在重要事情上會維持基本的規畫與整理，但不會追求所有事物都高度結構化，會依情境在「順手」與「有系統」之間調整。', '{"do": ["可用於：①說明其在條理與彈性間具有一定平衡感②建議透過簡單工具（行事曆、任務清單）維持必要結構③鼓勵在多人協作或關鍵專案時，稍微提高條理程度以避免資訊遺漏。"], "dont": ["禁止：①因為不「極度整齊」就認定其沒有組織能力②忽略系統與工具本身的限制③用單次檔案找不到的狀況否定其整體工作風格④在未提供任何支援的情況下要求高度紀律整理。"]}', 'CSR', '對你來說，重要的東西會整理好，其他部分只要自己找得到、用起來順就可以，不一定要全部都非常整齊。', '此區間可被系統化加成；工具與流程到位後差距會快速縮小。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (642, 'CSR_26', 'C', 0, 50, '彈性隨性', '較不靠固定流程工作，容易臨場處理；彈性高但也可能出現紀錄不足、交接不清或遺漏細節。', '設定最低限度的紀錄與交付格式（不求完美，求可追溯）；適合探索或外部開發。', '對固定流程、分類與整理沒有太強的內在動機，習慣依當下需求與感覺處理事物，資訊與物品較容易分散，需要「最低限度的秩序設計」來避免影響工作。', '{"do": ["可用於：①指出其在創意發想或需要靈活應變的工作中可保有彈性，但在大量資訊情境需要外加結構②建議從關鍵檔案與重要流程開始，建立最基本的整理規則③鼓勵逐步加入「讓自己少找東西」的小習慣，而不是一次要求全面大改。"], "dont": ["禁止：①直接貼上「邋遢」「沒組織」的標籤②忽略工作環境、工具與流程本身的雜亂③在未給予任何結構支援下，要求與高度條理者一樣的標準④以此分數否定其在專業或創意上的價值。"]}', 'CSR', '你比較不會特別想要把每件事都歸檔好、標好，多半是要用到的時候才去找、才處理。', '低分不等於混亂，可能是討厭被流程綁住；管理重點在必要秩序而非全面流程化。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (643, 'CSR_27', 'A', 76, 100, '品質苛求', '對細節與品質要求高，會反覆檢查與優化以達到無瑕疵；在高標準場景能顯著提升可靠度。', '適合品質把關、重要交付、品牌/法遵/對外文件等；可作為最後審稿者。', '對成果品質與細節有高度在意，容易把標準拉在相對嚴格的位置，會不斷微調、修正，直到接近心中理想狀態。', '{"do": ["可用於：①說明其在品質控管與精緻輸出上的優勢②建議在關鍵輸出（如對外簡報、正式文件）善用其高標準③鼓勵一開始先區分「需要完美」與「夠好就好」的情境，避免耗損過多心力。"], "dont": ["禁止：①把其完美傾向視為無限壓榨的理由②忽略時間與資源限制，只要求結果「零失誤」③用個別小缺點否定整體努力④鼓勵長期熬夜或超時工作來維持完美表現。"]}', 'CSR', '你常會一改再改，只因為覺得「還可以更好一點」，對小瑕疵也比較看得見、放不太下。', '高分常伴隨時間成本與焦慮；需明確定義夠好標準避免過度打磨。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (644, 'CSR_27', 'B', 51, 75, '品質平衡', '在重要任務會提高標準，但能在時間/資源限制下做取捨；品質與效率之間較能取得平衡。', '採分級品質策略（關鍵件高標、一般件可接受）能發揮最大效益；適合專案推進。', '在重要任務上會希望成果好看、站得住腳，但也能在時程或資源有限時接受「足夠好」，不會在所有細節上都追求極致。', '{"do": ["可用於：①說明其在品質與效率之間的彈性拿捏②建議在專案啟動時就與團隊對齊品質標準與優先順序③鼓勵維持這樣的平衡，而不是被環境推向過度完美或過度隨便。"], "dont": ["禁止：①因為不「事事追求極致」就說「不夠用心」②忽略限制條件（時間、人力、資訊）③用他人極端完美標準要求其配合④將小失誤解讀為態度不佳。"]}', 'CSR', '你會看事情的輕重來決定要多講究：重要的東西會盡量做到好、不丟臉，其他就做到合理水準即可。', '此區間管理關鍵在明確指引哪些要完美、哪些要完成。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (645, 'CSR_27', 'C', 0, 50, '完成優先', '更重視推進與交付，細節品質通常做到可用即可；在快速迭代場景有效率，但可能忽略小錯累積。', '適合 MVP、試點、快速產出；需搭配檢核/測試/他人 review 避免品質風險放大。', '對小細節瑕疵的容忍度較高，做事更在意整體完成與可運作，而不會為了打磨到完美而卡住進度，偏向「先有再優化」的風格。', '{"do": ["可用於：①指出其在快速迭代、原型開發或試錯情境中具有優勢②建議搭配對細節敏感的成員，共同平衡整體品質③鼓勵在重大、一次性輸出時，稍微拉高檢查標準以降低風險。"], "dont": ["禁止：①把這種風格直接等同於「隨便」「沒品質概念」②忽略職務本身是否真需要極高完美標準③在未說清楚品質期待前事後責怪④以單一缺失否定其整體貢獻。"]}', 'CSR', '你比較在意事情有完成、能用，而不是所有細節都要無可挑剔，對不影響結果的小地方會放得比較鬆。', '低分不等於粗糙，可能策略性先上線再修；需確認補救機制。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (646, 'CSR_28', 'A', 76, 100, '對結果負全責', '對把事情做好有強烈決心，遇到問題會主動承擔、補救與追根究柢，而非推給情境或他人。', '適合主責角色、交付導向任務；可降低管理追催成本。', '對自己承諾過或該負責的事情會主動扛起來，不容易把錯怪罪在環境或他人身上，而是先思考自己能做什麼調整。', '{"do": ["可用於：①說明其在責任感與自我要求上的成熟度②建議在授權與關鍵任務上信任其承擔能力，同時避免過度堆疊責任③鼓勵其在負責的同時，也適度界定「自己不能控制的範圍」。"], "dont": ["禁止：①把其責任感當成無限制加派任務的理由②忽略制度或資源問題，只期待其「自己想辦法」③鼓勵其為所有問題自責而不尋求支援④將其願意承擔視為可長期濫用的條件。"]}', 'CSR', '事情沒做好時，你比較會先想「我這邊可以怎麼改」，而不是第一時間怪別人或怪環境。', '可能過度扛責，需注意負荷與授權資源是否匹配。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (648, 'CSR_28', 'C', 0, 50, '責任外移傾向', '遇到失誤或延誤較容易歸因外部，補救動作相對被動，可能降低學習與改進速度。', '以復盤流程、行為導向回饋與明確後果機制；先從可控小任務建立承擔習慣。', '在事情出現問題時，較容易優先想到外在原因或他人角色，對於自己能影響或調整的部分較少主動檢視。', '{"do": ["可用於：①指出其在壓力情境下容易以防衛性方式看待責任議題②建議透過結構化檢討工具（如：我能調整什麼、可控/不可控）協助其建立新習慣③鼓勵在安全、非責備的環境中談錯誤，降低防禦需求。"], "dont": ["禁止：①直接貼上「愛推卸責任」標籤②在高度責備文化下只批評其防衛，而不處理環境③用羞辱方式要求其「坦承錯誤」④把此分數當成無法信任的永久標記。"]}', 'CSR', '一出狀況時，你可能會先想到「是誰沒做好」或「環境太爛」，比較少一開始就檢查自己哪裡能調整。', '避免人身貼標；重點是建立對結果負責的流程與文化。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (649, 'CSR_29', 'A', 76, 100, '自發超越', '在各類情境中都能自發開啟行動並超越既定要求，缺乏支持或方向模糊也不影響投入，主動精神十分穩定且不依賴外部驅動。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (650, 'CSR_29', 'B', 51, 75, '選擇性主動', '察覺到機會或需求時傾向自發投入，若方向不明確或回饋不足，會先評估投入的實際效益再決定是否超越既有範圍。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (651, 'CSR_29', 'C', 0, 50, '被動回應', '較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。', NULL, NULL, '{"do": [], "dont": []}', 'CSR', NULL, NULL, NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (652, 'CSR_30', 'A', 76, 100, '正向資源充沛', '具備較高的希望、效能感、韌性與樂觀傾向，面對挑戰能維持動能與信心，並把挫折視為可處理的問題。', '適合承擔轉型、開創、逆風推進與需要帶動士氣的角色；可作為團隊動能來源。', '整體心理資源相對充足，面對壓力與挑戰時，多半能帶著希望感、自信與韌性前進，把挫折視為可以調整與學習的機會。', '{"do": ["可用於：①說明其在變動環境與高壓任務中的心理支撐作用②建議擔任需要帶動士氣、面對不確定性的角色③提醒在照顧他人、當大家精神支柱的同時，也要有人照顧他。"], "dont": ["禁止：①把其心理資本視為可以無限加壓的本錢②用「你撐得住」忽略其困難或疲憊③期待其永遠保持樂觀不准低潮④視求助或疲倦為「不應該」。"]}', 'CSR', '你通常會覺得「雖然不一定順利，但總有辦法想出路」，對未來大多保有可以努力的感覺。', '高分不代表永遠不受影響，而是恢復力與自我再啟動能力較強；仍需資源與方向對齊。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (653, 'CSR_30', 'B', 51, 75, '可被激發', '一般狀態能保持正向，但在長期壓力或不確定下動能可能下降；獲得支持與看見進展後會回升。', '以清楚目標、可見進度、支持系統與正向回饋拉升狀態；適合穩健推進型任務。', '在一般情況下能保持一定程度的樂觀與復原，但遇到長期壓力、連續挫敗或高度不確定時，心理動能會明顯下降，需要外在支持與時間恢復。', '{"do": ["可用於：①說明其心理狀態與壓力總量與時間長度高度相關②建議安排合理恢復期與支持資源，避免長期處在高壓而不調整③鼓勵建立自己的紓壓與支持系統，在動能下降時有地方補充。"], "dont": ["禁止：①把在高壓之下的疲憊解讀為「不堅強」②忽略工作量、角色衝突與生活事件③只用「想開一點」簡化其困境④將偶爾低潮視為無法信任的理由。"]}', 'CSR', '多數時候你覺得還行，但如果壓力堆太久、事情一直不順，就會開始懷疑自己、覺得很累。', '此區間是環境敏感型；管理重點在打造可恢復節奏，而非要求更樂觀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (654, 'CSR_30', 'C', 0, 50, '資源不足', '較容易感到無力或悲觀，遇到挫折時動能下降較明顯，對未來期待感相對薄弱。', '先從可達成小目標建立成功經驗，搭配支持、教練式管理與壓力源盤點；避免一開始丟高不確定任務。', '對未來與自身影響力較容易抱持保留或悲觀態度，遇到壓力與挫折時，容易覺得「事情不會變好」或「自己也改變不了太多」。', '{"do": ["可用於：①指出其在面對壓力與變動時需要更多支持與成功經驗累積②建議透過小而具體的目標與逐步成就感，慢慢擴大心理資源③鼓勵組織提供安全嘗試與允許失敗的空間，而非只要求「要正向」。"], "dont": ["禁止：①將其標籤為「負面」「難帶」②忽略過往挫折、資源不足或系統問題對其心理狀態的影響③用雞湯或責備要求其立刻樂觀④以此分數判定其不適合承擔重要任務。"]}', 'CSR', '你可能比較常先看到困難或風險，對「事情會好轉」「我辦得到」這類想法沒有那麼自然。', '低分常與環境、壓力與過往經驗相關；不宜貼負面標籤，建議結合近期行為判讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (655, 'CSR_31', 'A', 76, 100, '逆境復原快', '遇到壓力、衝突或失敗後能快速回到可工作狀態，並把打擊轉成修正與補救行動。', '適合高壓前線、轉型推進、責任變更頻繁角色；可作為續航與穩定支點。', '面對壓力、挫折或變化時，雖然會受影響，但多能在合理時間內調整心態、找到因應方式並回到可運作狀態。', '{"do": ["可用於：①說明其在變動環境與高壓任務中的復原能力②建議在變革或關鍵專案中安排其扮演穩定力量的角色③提醒組織不要因其韌性而忽略資源、人力與休息配置。"], "dont": ["禁止：①把其韌性當成可以無限加壓的理由②用「你撐得住」忽略其耗損③假設其永遠不會出現耗竭或低潮④在其提出需要幫忙時感到「意外」並責怪。"]}', 'CSR', '你遇到打擊時也會難過或累，但通常可以慢慢整理好，再站起來繼續往前。', '高分不代表不會受挫，而是恢復與再啟動速度快；仍需休息節奏。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (656, 'CSR_31', 'B', 51, 75, '恢復需要時間', '受到壓力時會有明顯影響，但在獲得支持、釐清方向後能逐步回穩；表現受情境差異影響。', '以合理節奏、同儕支持與階段里程碑降低負荷；適合穩健推進配置。', '面對壓力與打擊時會明顯受影響，需要時間與支持才能恢復，但在方向釐清、支持到位後，多能逐步回穩。', '{"do": ["可用於：①說明其恢復速度與壓力強度、持續時間及支持程度高度相關②建議在高壓階段預先安排緩衝與支援機制③鼓勵其把需要幫助視為正常反應，而不是弱點。"], "dont": ["禁止：①把在高壓下恢復較慢解讀為「抗壓性差」②忽略工作與生活中長期壓力來源③只用「要想開」而不處理結構問題④把一次的低潮視為不能再被信任。"]}', 'CSR', '壓力大或事情不順時，你會真的累、真的被影響，但如果有人陪你理一理、環境調整一下，慢慢就能再起來。', '重點看觸發點與修復方式，比單看情緒反應更準。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (657, 'CSR_31', 'C', 0, 50, '耗損累積快', '在長期高壓或連續變動下容易出現能量耗竭，補救與恢復較吃力，表現波動可能增大。', '設計緩衝與分工、避免長期獨撐；用復盤與支持資源提升挽救能力。', '長期或高強度壓力較容易累積成耗損感，一旦被壓垮，恢復需要較多時間與資源，情緒與表現波動也相對明顯。', '{"do": ["可用於：①指出其在長期高壓環境中的風險，需要特別留意工作設計與負荷管理②建議建立穩定的支持系統（如信任的人、專業資源、自我照顧習慣）③鼓勵用溫和、不評價自己的態度面對脆弱，從中練習新的調適方式。"], "dont": ["禁止：①把其狀態標籤為「玻璃心」「不抗壓」②忽略組織在壓力管理與資源配置上的責任③用比較與羞辱逼其「硬起來」④以此分數作為不適合培養或信任的理由。"]}', 'CSR', '你在壓力很大或變動很多的時候，會感覺自己很快就被用完電，要花很久才補得回來。', '低分不等於抗壓差，而是對壓力敏感；重點在降低耗損而非硬扛。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (658, 'CSR_32', 'A', 76, 100, '勝任自信', '對自身能力與掌控感較有信心，遇到挑戰願意承擔並主動找方法；較少因不確定而退縮。', '適合需要自主判斷、獨立推進與對外代表的角色；可賦予較高授權與主責範圍。', '普遍對自己的能力與影響力抱持信心，相信只要有時間與資源，大多數挑戰都能找到解法並處理好。', '{"do": ["可用於：①說明其在承接新任務、面對變動與帶頭嘗試方面的優勢②建議提供具挑戰但可達成的機會，讓其把勝任感轉化為實際成果③提醒在高自信下仍要留意資源與現實限制，避免壓力累積。"], "dont": ["禁止：①把其自信當成不需支援的理由②在結果不理想時，用更高標準回頭指責「你不是很有能力嗎」③期待其一個人扛起所有困難專案④將自信與自負簡化為同一件事。"]}', 'CSR', '你多半會覺得「給我一點時間，我可以搞定」，面對新挑戰比較容易採取「先試試看」的態度。', '高分不等於永遠正確；仍需回饋迴路避免過度自信造成盲點。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (659, 'CSR_32', 'B', 51, 75, '需要確認', '能力多半足夠，但在新領域或高風險任務會希望獲得確認；得到支持後能穩定輸出並逐步建立信心。', '提供可求助窗口、階段性肯定與清楚成功標準能快速拉升；適合導師制或同儕合作下成長。', '面對熟悉或曾經成功過的任務時，普遍有一定把握；遇到全新、複雜或風險較高的挑戰時，會在意資源、支援與方向是否明確。', '{"do": ["可用於：①說明其勝任感與經驗、準備程度及環境支持高度連動②建議在新任務前提供清楚目標、學習資源與可詢問對象③鼓勵回顧自己過去克服困難的經驗，讓信心不只綁在熟悉領域。"], "dont": ["禁止：①把謹慎與確認解讀為「沒信心」②忽略制度、資訊與支援不足對其心理狀態的影響③只用「你要相信自己」簡化問題④用單一挫敗經驗否定其能力。"]}', 'CSR', '對你做過、熟悉的事情會覺得「這個可以」，但遇到完全陌生的挑戰，就會想先搞清楚「有人可以問嗎？資源夠嗎？」。', '此區間常被誤判為不自信；其實偏審慎，需要明確標準與回饋。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (660, 'CSR_32', 'C', 0, 50, '信心不足', '容易懷疑自己是否能做好，遇到不確定任務可能遲疑或依賴他人決定；需要更多安全感才敢推進。', '以小步成功累積並提供明確指引與正向回饋；避免一開始就丟高風險責任。', '面對挑戰時較容易先想到「我可能不行」或「別人比較適合」，對自己能否處理好事情的把握度較低，需要更多具體支持與成功經驗累積。', '{"do": ["可用於：①指出其在勝任感上需要更多具體回饋與小步成就來建立自信②建議主管在分派新任務時拆小步驟、給清楚指引與即時肯定③鼓勵其將「沒做過」與「做不到」分開看，避免預先放棄。"], "dont": ["禁止：①貼上「沒自信」「太弱」的標籤②忽略過往負面回饋或失敗經驗對其信心的影響③用嘲諷或比較逼其「振作」④依此分數斷定其不適合作為培養對象。"]}', 'CSR', '你有時會先懷疑自己「真的可以嗎？」，會覺得別人可能會做得比自己好。', '低分不等於能力差，可能受過往經驗或環境回饋影響；建議搭配行為證據判斷。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (661, 'CSR_33', 'A', 76, 100, '延宕誘惑', '能為了長期目標延遲滿足，面對短期誘惑仍可維持節奏與自我約束，較少因一時舒服而偏離計畫。', '適合長期推進、重複投入與自我管理任務；可交付需要持續交付的工作。', '能長期維持自訂節奏，為了重要目標安排時間、抗拒短期干擾，即使沒有人盯，也會自己推進到位。', '{"do": ["可用於：①說明其在長期專案、自我成長與習慣養成上的穩定度②建議安排需要持續投入與高度自主管理的任務③鼓勵在自律與彈性之間保留調整空間，避免把自己綁太死。"], "dont": ["禁止：①把其自律當成無限加工作量的理由②忽略其同樣會感到疲憊與需要休息的事實③將偶爾鬆動解讀為「變懶」④假設其完全不需要外在支持系統。"]}', 'CSR', '就算沒有人催，你也會照著自己的計畫去做，一點一點往長期目標前進。', '高分反映抗誘惑與持續性，不等於天生意志力強，也可能是習慣建立良好。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (662, 'CSR_33', 'B', 51, 75, '情境自控', '在目標清楚或環境支持下能維持自律，但在壓力大、干擾多或缺乏回饋時，容易出現鬆動與拖延。', '用短週期里程碑與外部承諾機制（回報、共學、檢核點）提升持續性。', '在有期限、有人一起推進或會被檢核的任務上，多能穩定完成；對完全自訂、沒人關心的長期目標，則較容易被日常瑣事打斷。', '{"do": ["可用於：①說明其自律表現與外在結構（時程、檢核、他人參與）高度相關②建議透過結伴、定期回顧或公開承諾來支援長期目標③鼓勵將大目標拆小步驟，減少拖延與中斷。"], "dont": ["禁止：①把需要外在結構的特性簡化為「沒意志力」②忽略制度與工作設計對行為的影響③只用指責回應延誤，而不協助重整計畫④用短期狀態推論其長期人格特質。"]}', 'CSR', '如果有交件時間、或有人一起跟進進度，你會比較穩；但是對那種「沒人管、很長期」的計畫，就容易被其他事情插隊。', '此區間常見於需要結構才穩的型態；重點是支持設計而非道德評價。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (663, 'CSR_33', 'C', 0, 50, '短期拉扯', '較容易被短期誘惑牽動，明知道長期目標重要仍可能在當下選擇立即回報；自律維持較吃力。', '拆小任務、降低啟動成本並用環境設計減少誘惑；以明確獎勵建立習慣。', '在維持固定節奏與長期計畫上較有難度，行動常受當下心情、突發事件或環境干擾影響，計畫與實際執行之間容易出現落差。', '{"do": ["可用於：①指出其在需要高度自律的任務中，必須透過工具與環境設計來補強②建議採用「短時段、短目標、多次重新開始」的方式，而不是一次逼自己完美堅持③鼓勵尋找適合自己的支持系統（例如夥伴約定、提醒工具）。"], "dont": ["禁止：①批評為「沒自制」「不長進」②忽略心理狀態、壓力或生活變動對執行力的影響③要求一次性徹底改變而不提供漸進方案④以此分數否定其負責任或成長的可能性。"]}', 'CSR', '你可能常常有計畫，但實際要照著做會覺得很容易被打斷或被別的事情帶走。', '低分常見於目標模糊、能量不足或干擾過強；先改善情境再談自律。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (664, 'CSR_34', 'A', 76, 100, '直率不操弄', '較少為了達成目標去操縱或欺騙他人，溝通偏直接透明，傾向用真實資訊建立合作。', '適合互信與長期合作情境（跨部門、客戶關係、治理）；可降低猜疑與內耗。', '在人際互動上偏好以真誠、直接的方式溝通，不太傾向刻意操弄、隱瞞或欺騙他人來達成目的。', '{"do": ["可用於：①說明其在建立深度信任與長期關係上的優勢②建議讓其參與需要穩定、真誠互動的合作與夥伴關係管理③鼓勵在保持誠懇的同時，也學會適度保護自己，不被過度要求透明。"], "dont": ["禁止：①期待其在任何情境都完全坦白而不顧自身風險②忽略組織政治與權力現實③將必要的策略性表述誤解為不誠懇④把偶爾的保留視為人格反轉。"]}', 'CSR', '你多半是「怎麼想就怎麼說」，不太喜歡用話術或欺騙的方式來達成目標。', '高分不代表不會談判；是更傾向資訊透明而非話術操作。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (665, 'CSR_34', 'B', 51, 75, '策略拿捏', '多數時回應誠懇，但在競爭、壓力或政治情境中，可能用較策略性的表達方式保護自身立場。', '提供清楚溝通規範（哪些可保留、哪些必須公開）與協作準則，維持信任又不失彈性。', '整體不偏好欺騙或操弄，但在敏感、權力不對等或關係脆弱的情境中，會斟酌要說多少、怎麼說，以兼顧真實與關係。', '{"do": ["可用於：①說明其在誠懇與情境顧慮之間維持某種平衡②建議釐清組織對資訊透明與保密的實際期待，降低個人壓力③鼓勵在不安時尋求對話，而不是一味壓抑或過度隱瞞。"], "dont": ["禁止：①把策略性保留一概解讀為「不老實」②忽略法律、商業機密與角色責任對發言空間的限制③用理想化標準要求其在任何情境完全透明④用單一事件否定其整體誠懇度。"]}', 'CSR', '你大多數時候會說實話，但在某些場合也會想「怎麼講比較不會傷人或惹麻煩」，不一定全部攤開講。', '此區間重點在界線與一致性；規則模糊時容易被誤讀。', NULL, NULL);
INSERT INTO trait_bands (id, trait_id, band, min_score, max_score, semantic_label, description, management_focus, report_wording, ai_guidance, trait_project, report_wording_friendly, usage_note, trait_interaction_guide, version) VALUES (666, 'CSR_34', 'C', 0, 50, '目的導向', '較容易把包裝或操弄視為達成目標的工具，可能選擇性揭露或用話術影響他人判斷。', '需在透明流程與稽核機制下運作；在客戶/治理領域需更嚴格行為規範。', '對於「只說對自己有利的一部分」或美化資訊的接受度較高，溝通常被視為推進目標的工具，而非單純交換真實狀態的管道。', '{"do": ["可用於：①指出其在談判、銷售與需要強勢說服的場域可能具優勢，但須留意長期信任與誠信風險②建議透過明確規範與例外情境說明，界定不能被犧牲的誠信底線③鼓勵其思考「短期成交」與「長期信任」之間的取捨。"], "dont": ["禁止：①直接等同於「騙人」「不可信」②忽略組織本身對短期成效的高度壓力③只用道德批判要求其改變，而不提供具體示例與學習資源④用此分數斷言其一定會嚴重違反誠信。"]}', 'CSR', '你可能會覺得強調優點、淡化缺點是很正常的做法，重點是事情要推得動。', '低分代表風險訊號；不等同人品評價，但管理建議以控風險為先。', NULL, NULL);
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2342, 'CIA_01', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：展現極強的紀律與成功慾望，是高產出的明星員工。管理上需注意其可能為了目標忽略身心平衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2343, 'CIA_01', 'A (高)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「魯莽的勤奮者」。雖有極強執行力但行動前缺乏思考，易努力執行錯誤決策，需加強前置覆核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2344, 'CIA_01', 'A (高)', 'CIA_04', 'A', '與 CIA_04 (義務感) 高分聯動：典型的「組織基石」。對規範高度尊重且極度自律，是非常可靠的合規型人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2345, 'CIA_01', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「焦慮補償者」。雖渴望做好但易受情緒干擾，壞事後會花加倍力氣彌補，效率波動較大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2346, 'CIA_01', 'A (高)', 'CIA_06', 'A', '與 CIA_06 (條理性) 高分聯動：卓越的流程管理者。能將複雜工作系統化，產出極其穩定且精確。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2347, 'CIA_01', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：品質的絕對守門員。標準極高，但需警惕因過度鑽研細節導致進度延宕或造成團隊壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2348, 'CIA_01', 'A (高)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「自省型執行者」。雖然表現優異但對自己缺乏信心，易產生職業燃盡，需主管頻繁給予正向回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2349, 'CIA_01', 'A (高)', 'CIA_09', 'A', '與 CIA_09 (自律性) 高分聯動：長期目標的長跑者。具備極強的抗誘惑能力與延遲滿足感，能自主完成長期艱難任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2350, 'CIA_01', 'A (高)', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「權謀執行者」。極度自律但可能具備操縱傾向，需注意其工作產出背後的動機與誠信風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2351, 'CIA_01', 'A (高)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) 低分聯動：表現為「高度功利驅動」。自律是為了換取物質回報或地位，若獎酬制度不明確，其穩定性會下降。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2352, 'CIA_01', 'A (高)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：組織的倫理標竿。做事盡責且絕不作弊，適合擔任稽核、財務或高誠信要求的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2353, 'CIA_01', 'A (高)', 'CIA_14', 'C', '與 CIA_14 (謙虛) 低分聯動：表現為「傲慢的優等生」。因自身高標準而自覺高人一等，易在團隊中製造階級感並忽視他人意見。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2354, 'CIA_01', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) 低分聯動：表現為「脆弱的完美者」。這是關鍵預警項，一旦失敗會因無法忍受瑕疵而崩潰，難以從挫折中恢復。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2355, 'CIA_01', 'A (高)', 'CIA_19', 'C', '與 CIA_19 (樂觀) 低分聯動：表現為「憂患意識者」。凡事滴水不漏但缺乏活力，總在防範最壞情況，雖可信賴但會帶給團隊沉重氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2356, 'CIA_01', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) 高分聯動：表現為「實踐型天才」。能將創新點子轉化為具體的 SOP 與執行計畫，是推動體制內變革的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2357, 'CIA_01', 'A (高)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) 高分聯動：傳統規則的捍衛者。在既定架構內表現極佳，但在無規則或模糊情境下會感到極度焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2358, 'CIA_01', 'A (高)', 'CIA_25', 'C', '與 CIA_25 (集體意識) 低分聯動：表現為「孤傲型強人」。個人產出強但無視團隊節奏，對不認同的團體活動展現消極。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2359, 'CIA_01', 'A (高)', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「冷酷執行者」。只看目標不看人情，適合推行硬性政策，但長期可能造成組織氣氛僵化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2360, 'CIA_01', 'A (高)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) 高分聯動：精確的對等者。對付出與回報的比例極度敏感，若感到不公，其「盡責」程度會迅速下降。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2361, 'CIA_01', 'A (高)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) 高分聯動：卓越的自主管理者。不需要外界監督也能達成高標，管理上應給予充分授權而非微觀管理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2362, 'CIA_01', 'A (高)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) 高分聯動：自我進步型人才。不僅把事做好，還渴望優化自身能力，是組織極具價值的儲備幹部。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2363, 'CIA_01', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「精英心態者」。認為自己的高績效應換取特殊的優先待遇，若未獲特權會產生不平。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2364, 'CIA_01', 'A (高)', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) 低分聯動：表現為「機器人型執行」。雖依循規範完成任務，但內心缺乏熱情，僅視工作為義務，長期發展動力有限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2365, 'CIA_01', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「暴躁的工頭」。對工作要求轉化為對人的怒氣，當他人未達標時會產生強烈情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2366, 'CIA_01', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「有企圖心的條件型執行者」。目標、範圍與時程一旦說清楚，他不只是把事情做完，還會主動想拉高標準、多試一種做法看能不能更好，遇到卡關傾向升級策略而不是繞過去。可是一旦優先序被反覆改動或責任邊界模糊，他的投入感會先鬆動，原本想追求的更高標準也跟著往後放，變成先求把眼前交出去。管理上宜先把目標與範圍鎖定清楚，再放心讓他自己往上加碼，一旦環境變動頻繁,要有人幫忙重新框定範圍，他的企圖心才不會跟著空轉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2367, 'CIA_01', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先衝再補洞的穩定產出者」。在目標與時程清楚的狀況下，他會先動手推進，把評估和檢查留到做出雛形之後再補；這種節奏在熟悉任務上跑得快，交付也算穩。問題出在優先序一變、責任邊界一模糊，他既沒有先想清楚的緩衝，收尾的自我要求又鬆動，容易把補救動作也一起延後，隱性風險就這樣被疊著往後拖。管理上宜替他在快動作之後安排固定的檢查點，並在任務轉換頻繁時多給一次明確的邊界確認，讓他的衝勁不會變成沒人接住的缺口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2368, 'CIA_01', 'B (中)', 'CIA_04', 'A', '與 CIA_04 (義務感) 高分聯動：表現為「守住底線的看情境輸出者」。目標與範圍清楚時他做得穩，即使在效率或投入度上有起伏，遇到承諾、規則或責任歸屬這類灰色地帶，他仍然傾向選可以被交代、經得起檢驗的做法，不會為了趕進度就犧牲原則。當優先序頻繁變動讓他一時抓不準該顧哪一頭，他寧可先確認清楚不能碰的底線在哪，再決定怎麼推進，行動速度因此可能慢下來。管理上宜在任務轉換時明確標出哪些規則與承諾不能讓步，讓他能安心地在守住底線的前提下重新找回節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2430, 'CIA_04', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「傲慢的苦難者」。一邊為了組織義務辛苦付出，一邊覺得自己理應獲得特殊優待，容易在背後抱怨他人偷懶而自己受苦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2431, 'CIA_04', 'A (高)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「模範生人設」。高度社會化，會刻意表現出符合主流價值期待的樣子，需觀察其私下是否能維持一致。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2369, 'CIA_01', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「平時穩定、壓力下容易失守的執行者」。目標清楚、節奏平順時他能維持穩定輸出，可是一旦優先序被打亂或責任邊界說不清，情緒壓力上來，他容易被當下感受推著走，倉促回應、隨口答應下一步，事後常常要花時間解釋或收拾。這種時候最先垮的往往不是能力而是反應的分寸，效率下滑之外還伴隨衝動決定，恢復期會拉得比單純沒做完更長。管理上宜在變動大的時期預先降低外部刺激、給緩衝時間讓他先消化情緒，再談進度要求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2370, 'CIA_01', 'B (中)', 'CIA_06', 'A', '與 CIA_06 (條理性) 高分聯動：表現為「靠流程撐住波動期的執行者」。他習慣把資訊分類、任務排程，這套習慣在目標清楚時讓他跑得又快又穩；當優先序開始頻繁變動、責任邊界說不清楚，投入度容易先受影響，但因為手上仍握著固定的整理方式，遺漏與混亂的風險比單純沒有條理的人少很多。他會靠著重新排列待辦與資料，慢慢把被打亂的節奏找回來，而不是整個停擺。管理上宜在變動期主動提供最新範圍與優先序，讓他既有的流程能力有東西可以掛，就能較快從波動裡穩下來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2371, 'CIA_01', 'B (中)', 'CIA_07', 'C', '與 CIA_07 (完美主義) 低分聯動：表現為「條件式可靠的堪用交付者」。目標、範圍與時程講清楚時，他能穩定往前推進，也交得出東西。品質上他不會多磨，做到堪用、能過關就往下一步走，小瑕疵常常留在成品裡沒被回頭修掉。一旦優先序頻繁被改、或責任邊界變得模糊，他明顯提不起勁，進度也跟著容易卡住或拖延。在範圍不清又要快速交付的場合，他傾向先求有再求好，累積的小錯常要到後段才會浮現。管理上宜把目標、範圍與時程盡量說清楚，並在關鍵節點安排複核，補上他不會主動回頭檢查的細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2372, 'CIA_01', 'B (中)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) 高分聯動：表現為「帶著自信撐過模糊期的執行者」。目標與範圍清楚時他表現穩定，遇到優先序變動或責任邊界不清楚，效率可能暫時下滑，但他對自己有沒有能力處理這種不確定並不特別懷疑，仍然願意主動摸索、先試著找方法而不是等別人給答案。即使進度被打斷，他也比較快重新抓住方向，不太會因為一時混亂就退縮不動。管理上宜在變動期給他多一點自主空間去嘗試調整做法，同時盡快補上明確的範圍資訊，讓他的信心能轉成實際產出而不是空轉的摸索。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2373, 'CIA_02', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高效能明星」。具備極強的成功欲望與自我要求，是組織績效的穩定貢獻者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2374, 'CIA_02', 'A (高)', 'CIA_03', 'C', '與 CIA_03 (審慎) C聯動：表現為「冒進的擴張者」。渴望快速達成目標但行動前缺乏深思，易忽略潛在風險，需加強風險控管提示。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2375, 'CIA_02', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情緒化衝刺者」。雖極想贏但易受當下情緒干擾，表現起伏大，需建立標準作業程序以穩定產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2376, 'CIA_02', 'A (高)', 'CIA_06', 'C', '與 CIA_06 (條理性) C聯動：表現為「混亂的衝鋒者」。專注於大目標但細節混亂，雖有產出但常伴隨行政錯誤，需行政資源輔助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2377, 'CIA_02', 'A (高)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「利益導向者」。成功至上且可能不惜犧牲倫理，需注意其達成目標的手段是否符合合規要求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2378, 'CIA_02', 'A (高)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「高度物質動機」。對金錢與地位有強烈需求。若獎酬機制不具競爭力，此類員工離職風險極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2379, 'CIA_02', 'A (高)', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「炫耀型成功者」。達成目標後傾向於彰顯功勞，易在團隊中造成他人心理壓力，需引導其分享成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2380, 'CIA_02', 'A (高)', 'CIA_17', 'A', '與 CIA_17 (目標效能感) A聯動：表現為「自信的開拓者」。不僅想贏且相信自己能贏，面對挑戰不退縮，是組織攻堅時的首選先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2381, 'CIA_02', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆弱的攀登者」。極度渴望成功但心理緩衝空間小，一旦專案失敗易陷入長期低潮，需主管即時介入輔導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2382, 'CIA_02', 'A (高)', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「焦慮的追求者」。雖然努力達成目標，但內心總預見壞結果，工作動能雖強但情緒緊繃感極重。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2383, 'CIA_02', 'A (高)', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「創新實踐者」。會不斷尋找更聰明的方法來達成業績，不滿足於現狀，是推動流程變革的核心人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2384, 'CIA_02', 'A (高)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較回報的戰士」。對付出與獲得的公平性極度敏感，若獎勵未達其預期，會迅速轉向消極反抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2385, 'CIA_02', 'A (高)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「自我進化者」。將工作成就視為個人成長的一部分，極度看重培訓與發展空間，是優質的儲備幹部。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2386, 'CIA_02', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「權利索求者」。認為自己的努力應換取特殊優待與特權。若管理上無法給予特殊感，其工作配合度會降低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2387, 'CIA_02', 'A (高)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「全心投入者」。工作本身即是快樂來源，具備極強的長期戰鬥力與忠誠度，是組織文化的核心支柱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2388, 'CIA_02', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「有目標才衝刺的可靠執行者」。目標清楚、進展看得見時，他會主動盯進度、把品質顧好、收尾收得乾淨，不太需要人催。一旦指標模糊或看不到成果累積，衝勁會先鬆下來，但顧品質、把事情收好的習慣仍在，交出去的東西不會亂。管理上宜替他把階段性成果標出來，讓他常常看到自己往前走，投入度會跟著回升。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2389, 'CIA_02', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先動手才校準方向的衝刺型」。不管目標交代得清不清楚，他做事都習慣先動手，評估與修正留到做出一輪之後才補上，這是他一貫的方式。目標清楚、看得到回饋時，這股先做再說的動能會拉滿，推進速度快，但也容易在衝的過程中漏看不明顯的風險；一旦指標模糊、看不到進展，投入的力道會弱下來，先做再調整的做法還在，只是做的量跟緊迫感都跟著降低。管理上宜給明確的短期指標，並在他起步後即時補上風險提醒，讓速度與注意力不因動機起伏而一起流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2464, 'CIA_06', 'A (高)', 'CIA_02', 'C', '與 CIA_02 (成就動機) C聯動：表現為「行政管家」。雖然極度細心且愛好程序，但缺乏突破目標的野心。管理建議：適合擔任穩定運營的幕後支援，不宜賦予高競爭性的開拓任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2390, 'CIA_02', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「沉得住氣的目標追蹤者」。目標清楚、回饋可見時他願意持續加碼投入，遇到壓力或挫折也能維持一致的反應與判斷，不會因為一時情緒亂了節奏。真正讓他卡住的不是情緒，是看不到進展——指標消失、回饋斷線時，動能會慢慢降下來，但情緒表現依然穩定，不會因此焦躁或口氣變差。管理上宜定期補上可見的進度回饋，讓他的沉穩有東西可以支撐著往前投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2391, 'CIA_02', 'B (中)', 'CIA_06', 'C', '與 CIA_06 (條理性) 低分聯動：表現為「看得到終點才衝、過程不靠流程」。他做事一路都偏臨場處理，不靠固定流程，習慣用當下判斷把事情兜起來，這點不太隨任務有沒有清楚目標而改變。目標明確、能看到成果時，他願意把力氣往前壓，衝勁十足；一旦指標模糊、看不到進展，投入度會降下來，變成有一搭沒一搭地應付，兜事情的方式仍是臨場、缺乏固定流程，紀錄不足或交接不清的風險也還在。管理上宜把目標拆成看得見的小段落，並搭配簡單的記錄提醒，維持他的投入與該留下的東西兩邊都不掉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2392, 'CIA_02', 'B (中)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) 高分聯動：表現為「拚成果但不越線的追求者」。目標清楚、看得到回饋時他會卯足勁投入，即使成果與利益就在眼前，也不會靠誇大、佔便宜或搶功來換取進度，做法上仍保持誠懇公正。看不到指標或進展停滯時，他的衝勁會先降下來，但不會因此換一套投機的做法去硬拚成果，行事分寸沒有跟著鬆動。管理上宜提供清楚可見的成果回饋，讓他的投入有方向，同時放心把需要拿捏分寸的任務交給他。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2393, 'CIA_02', 'B (中)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) 低分聯動：表現為「看獎勵決定衝不衝的人」。不論目標交代得清不清楚，他心裡都有一把回報的尺，習慣拿看得到的實質回報或外顯肯定——獎金、頭銜、被看見的機會——來衡量一件事值不值得多花力氣。目標清楚、回饋可見時他願意加碼投入，一旦指標模糊、進展看不到，投入度會先降下來；不管哪種情況，他評估要不要繼續投入時，那把回報的尺都還在，物質與外顯肯定始終是他心裡重要的判準。管理上宜把目標與相應的回報一起講清楚，讓他看得到終點也看得到值不值得衝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2394, 'CIA_02', 'B (中)', 'CIA_14', 'A', '與 CIA_14 (謙虛) 高分聯動：表現為「衝成果但不搶光環的人」。目標清楚、看得到回饋時他會積極投入去追成果，功勞出來時不特別需要突顯自己比別人強，也能自然接受別人的貢獻。指標模糊、進展看不見時投入度會降下來，但他看待自己與他人相對位置的平衡感不會跟著改變，不會因為想找回動力就開始搶著證明自己。管理上宜持續提供看得見的目標與進度回饋，維持他的投入節奏即可，不需要額外用突顯個人來刺激他。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2395, 'CIA_03', 'A (高)', 'CIA_01', 'C', '與 CIA_01 (盡責) C聯動：表現為「想得多做得少」。雖能洞察風險但執行力不足，容易陷入「過度分析而無行動」的狀態，需搭配強力的執行窗口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2396, 'CIA_03', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「精確的戰略家」。追求成功的同時具備高度理性，能規劃出具備高可行性的路徑，是高品質決策的核心人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2397, 'CIA_03', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「理性的內耗者」。雖然腦中知道該審慎思考，但行為上易受衝動誘惑而破功，事後常感到後悔，心理壓力較大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2398, 'CIA_03', 'A (高)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「決策癱瘓者」。因過度考慮風險且對自己能力缺乏信心，在需要快速反應時會因焦慮而無法做決定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2399, 'CIA_03', 'A (高)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「深沉的操縱者」。行動極其謹慎且具備隱藏真實動機的傾向，在職場政治中較難被看透，需留意其長期誠信表現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2400, 'CIA_03', 'A (高)', 'CIA_15', 'C', '與 CIA_15 (心理資本) C聯動：表現為「悲觀的風險控管者」。審慎變成了對挫折的防備而非策略規劃，容易因過度看重困難點而失去前進動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2401, 'CIA_03', 'A (高)', 'CIA_19', 'A', '與 CIA_19 (樂觀) A聯動：表現為「務實的開拓者」。對未來抱持正向期待，同時具備風險避開能力。能產出既具企圖心又經得起推敲的提案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2402, 'CIA_03', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「有紀律的創新者」。不會為了不同而不同，而是能在深思熟慮後，挑戰無效規則並提出具邏輯支撐的創新方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2403, 'CIA_03', 'A (高)', 'CIA_21', 'C', '與 CIA_21 (效率取向) C聯動：表現為「緩慢的完美主義」。極度重視邏輯嚴謹但忽視時間效率，在講求快速變動的環境中適應力較低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2404, 'CIA_03', 'A (高)', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「誠信的觀察家」。不僅言行一致，且在表達觀點前會經過精密考量，其給出的建議通常具備高度參考價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2405, 'CIA_03', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「貼心的協調者」。在人際往來中思慮周全，能顧及他人感受且說話不魯莽，適合處理複雜的人事糾紛。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2406, 'CIA_03', 'A (高)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「完美的防禦者」。因高度負責且凡事三思，適合處理合規、法務、審計等絕對不能出錯的高風險任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2407, 'CIA_03', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「精明的索求者」。會精密計算如何透過特殊待遇獲取最大利益，並小心保護自己的特權，需注意其與團隊利益的衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2408, 'CIA_03', 'A (高)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「精確的人設師」。為了獲得認可會非常謹慎地篩選答案或行為，其真實特質可能被良好的社交偽裝覆蓋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2409, 'CIA_03', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「冷靜的引信」。雖易被激怒，但因具備高度審慎，會刻意壓抑或精確計算反擊時機，展現出具攻擊性的嚴謹。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2410, 'CIA_03', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「重大決策收緊、常規推進放手的執行者」。面對重要決策，他會把評估拉滿，反覆確認風險與假設，同時對進度、品質與收尾維持一致的自我要求，不太需要人催就能把後續補齊。到了熟悉或時間緊迫的任務，他評估的動作會簡化甚至跳過，但收尾與品質的自我要求不會跟著鬆，該補的檢查、該顧的細節還是會做完，讓交出去的東西不至於因為省了評估就跟著粗糙。管理上可以放心把重大決策交給他自己拿捏鬆緊，日常任務則不必特別盯著收尾，他自己會顧到。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2465, 'CIA_06', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密規劃者」。在行動前會細節性地推敲每一個步驟，確保流程無死角。警示：應變速度極慢，在混亂或緊急環境下會感到極大壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2411, 'CIA_03', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「重要關頭才認真掂量的合理達標者」。遇到重要決策，他會把評估拉高、多想幾步再動作；但他對工作本身沒有非要突破的企圖心，把事情做完、做到合理範圍就足夠，不會主動找更難的做法或多繞一圈去追求更高標準。時間壓力或熟悉任務一來，他的評估動作跟著簡化，加上動機也不特別想多投入，兩件事同時往下修時容易只求把眼前交出去、不多想。管理上宜替他把重要決策的門檻明確標出來，並用環境支持或明確要求撐住他的投入度，避免簡化評估又缺乏企圖心疊在同一項任務上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2412, 'CIA_03', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「評估收放有度、情緒始終穩得住的決策者」。重要決策上他願意花時間評估風險與後果，時間壓力大或任務熟悉時評估動作會簡化，但這種簡化是他自己選擇的節奏調整，不是被情緒推著走——即使進度緊、外界催促，他仍能維持一致的反應與判斷，不會因為一時心浮氣躁就跳過該想的部分或倉促定案。也因此，就算某次評估做得比較快，事後回頭看多半也不是情緒失控造成的破口。管理上可以放心把時間壓力大的任務交給他，他的簡化評估是節奏取捨，不是失控前兆。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2413, 'CIA_03', 'B (中)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「安全感不足的反覆求證者」。在任務熟悉、資訊足夠時，他能把審慎維持在剛好的程度，確認過關鍵點就會往前推進。換到不熟悉的情境時，他又會開始反覆確認，評估容易變成一種內耗。面對這種情境，他常把同一個決定翻來覆去檢查，也想先問過別人的看法才敢往下走。時間拉得越長，他消耗在猶豫上的心力越多，交付的節奏也跟著被拖慢。管理上宜在他面對陌生任務時提供明確的判斷依據與階段性確認，讓他能較快建立把握、縮短反覆評估的時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2414, 'CIA_03', 'B (中)', 'CIA_11', 'A', '與 CIA_11 (誠懇) 高分聯動：表現為「評估拉滿也不藏話的決策者」。重要決策上他會認真評估風險與假設，過程中不會為了讓結論好看或達成目標而挑話說、操弄資訊，該說的疑慮或還沒想清楚的地方會直接攤開，用真實資訊跟人一起把決策想透。時間壓力大或任務熟悉時，他評估的深度會簡化，但即使簡化，他也不會用模糊或誇大的說法掩蓋自己其實沒想那麼多，寧可老實說「這次評估得比較快」。管理上可以信任他回報的評估深度，他簡化了會直說，不會包裝成已經想清楚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2415, 'CIA_03', 'B (中)', 'CIA_15', 'C', '與 CIA_15 (心理資本) 低分聯動：表現為「評估越拉高、越容易被自己嚇退的決策者」。重要決策上他願意把評估拉高、認真想風險，但評估得越深，看到的變數與可能的挫折也越多，這種時候他容易感到無力，動能明顯往下掉，對後續能不能做好的期待感跟著變薄弱。時間壓力或熟悉任務下他的評估會簡化，反而暫時不會被這種消沉纏住，可是一旦真的踩到挫折，恢復速度較慢，下一次面對重要決策時評估動作可能因此更保守或更遲疑。管理上宜在他做完深度評估後主動給支持與具體的下一步，避免他把「想得多」變成「更容易被自己的評估打垮」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2416, 'CIA_03', 'B (中)', 'CIA_19', 'A', '與 CIA_19 (樂觀) 高分聯動：表現為「把風險看透也把轉機看到的決策者」。重要決策上他會認真評估風險、假設與後果，即使看到不少隱憂，他對這些不順的解讀偏向可以改善、還有轉機，不會因為評估出一堆問題就先自己放棄，反而更願意帶著希望感把方案往下推。時間壓力或熟悉任務下他的評估動作會簡化，但簡化不代表他對結果的期待跟著悲觀，該有的行動力仍然維持得住。即使某次簡化評估後結果不如預期，他也不容易被單一次失敗打垮，很快會把注意力轉回下一步能怎麼修正。管理上可以放心讓他在重要決策後承擔後續調整的角色，他評估得出風險，也扛得住風險兌現後的落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2417, 'CIA_04', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「極致的守法者」。將規範視為個人信仰，執行任務不打折扣。管理警示：容易對不守規矩的同事產生強烈偏見，導致團隊氣氛緊繃。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2418, 'CIA_04', 'A (高)', 'CIA_02', 'C', '與 CIA_02 (成就動機) C聯動：表現為「安分的執行員」。極度負責且聽話，但缺乏向上突破的動力。管理預測：適合擔任穩定崗位，但不宜放在需要「不計代價達成業績」的開拓職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2419, 'CIA_04', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的守護者」。在執行規範前會思考其合理性與影響，能為組織提供具建設性的法律或合規建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2420, 'CIA_04', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「自責的失控者」。內心極度想遵循規範，但行為常受衝動驅使而違規。心理風險：事後會產生巨大的罪惡感與焦慮，長期易導致自尊受損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2421, 'CIA_04', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「教條主義者」。不僅要遵守規則，更要追求流程的完美無瑕。警示：容易在繁文縟節中迷失，造成行政效率低下，甚至阻礙緊急決策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2422, 'CIA_04', 'A (高)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「形式主義的利己者」。外在極力表現出合規的樣子，實則內在缺乏誠信，僅是為了避免受罰而守規，需防範隱蔽性舞弊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2423, 'CIA_04', 'A (高)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「正義使者」。對職場不公平現象極度敏感，會為了維護正義而舉報或反抗，是組織清廉的指標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2424, 'CIA_04', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「易碎的樑柱」。承擔過多責任卻缺乏抗壓彈性，一旦組織規則劇烈變動或面臨衝突，容易出現情緒崩潰或迅速離職。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2425, 'CIA_04', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「建設性變革者」。遵循更高層級的「良知」而非「死板規定」。會為了優化組織而勇敢提出挑戰舊規的創新方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2426, 'CIA_04', 'A (高)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「傳統捍衛者」。絕對服從現有體系，缺乏應變彈性。在轉型期可能成為組織阻力，因為他們認為挑戰規則是不忠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2427, 'CIA_04', 'A (高)', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「言行合一的楷模」。行為高度契合價值觀。管理預測：極具誠信魅力，適合擔任組織文化傳播者或內部導師。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2428, 'CIA_04', 'A (高)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「重視承諾的夥伴」。對「勞資契約」有神聖感。警示：一旦感受到付出回報不對等，會認為組織「不講信義」而徹底心碎並轉身離開。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2429, 'CIA_04', 'A (高)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「自主責責任者」。不僅守規矩，還會主動承擔任務。預測：是最不需要監督的員工，給予明確目標後即可高度放心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2432, 'CIA_04', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「守紅線的自主推進者」。他推進任務時不太需要人盯著，進度、品質與收尾大多靠自己抓緊；遇到規範模糊或資源卡關的地方，他會主動想辦法找一個過得去的折衷方案，而不是停下來等指示。但真正涉及被明確標出『不能動』的界線，他不會拿效率當理由去踩線，還是照著界線走。管理上，把不可退讓的底線一次講清楚，其餘交給他自行拿捏，會是效率與合規都顧到的做法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2433, 'CIA_04', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「待激而動的規則跟隨者」。他做事習慣把任務完成到能交代過去的程度就好，不太會主動加碼挑戰更高難度；規範也大多照著走，但一旦資源卡緊或目標出現衝突，他會先找一個各方都能接受的折衷，而不是硬撐標準。『不能碰』的界線需要有人先明講，他才會確實守住；沒有明講的灰色地帶，他傾向用最省力、能過關的方式處理。管理上要留意，外部若沒有清楚設定要求與底線，他的產出與合規都容易停在最低但足夠的水準，需要主動給刺激與明確指示才會拉高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2434, 'CIA_04', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「先算代價的審慎協商者」。他在動手前會先想清楚風險、可能的假設落空點跟後果，即使情況不確定也能維持判斷品質，不太會因一時判斷就得回頭重做。規範方面他大多會遵守，但遇到資源不足或目標出現矛盾時，他傾向先評估各種做法的代價，再挑一個能兼顧規範與現實的折衷路線，而不是直接硬闖或直接放棄原則。真正被明確畫出『不能碰』的界線，他會把它當成評估時的固定變數，一開始就排除違規選項。管理上，先把不可退讓的底線講清楚，他的判斷力就能在其餘空間裡找出兼顧效率與合規的做法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2435, 'CIA_04', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「情緒未平先鬆手的協商者」。他遇到刺激或壓力大的時刻，情緒容易先衝上來，可能當場答應原本沒打算做的事，或講話、行動超出原本的分寸，事後得花時間解釋或補救。對於規範，他平常大多會照著走，但一旦資源緊繃或目標衝突，他會想找一個折衷做法；問題是這種折衷有時是在情緒還沒平復時就拍板，之後才發現踩到了不該碰的界線。真正被明講『不能動』的紅線，冷靜狀態下他能守住，但在情緒被挑起的當下，這條線也可能被他一併衝過去。管理上除了要把底線講清楚，還需要在他情緒明顯升溫時提供一個暫停或降溫的機制，避免衝動當下把折衷做成了違規。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2436, 'CIA_04', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「品質不打折的折衷協商者」。他對細節與品質的要求很高，交出去前習慣反覆檢查、修到沒有明顯瑕疵，尤其在標準訂得高的場合，成果的可靠度普遍偏高。規範方面他大多會照著走，但資源不足或目標出現衝突時，他會傾向找一個折衷方案，只是這個折衷常常卡在他自己對品質的堅持上，容易反覆調整、遲遲定不了案。真正被明講『不能動』的界線，他會直接排除違規選項，不會拿品質理由去談判底線。管理上，若要他在時限內交出折衷方案，需要有人明確幫他框住這次可以放的品質範圍，否則他可能在追求面面俱到的過程中把時間耗盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2437, 'CIA_04', 'B (中)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) 低分聯動：表現為「灰色地帶偏向自己的協商者」。他平常大多會照規範走，但心裡對利益、地位或外在象徵這類東西其實相當在意，遇到資源不足或目標衝突時，他找的折衷方案常常會不自覺往對自己更有利的方向靠。他不太覺得這樣做有什麼問題，公平或謙遜不是他優先自我要求的項目，只要沒人明講『這樣不行』，他傾向把能拿到的先拿到，事後再視情況解釋。真正被劃出『不能動』的界線，他會遵守，但界線以外的灰色地帶，他的折衷選擇很難自動對齊公平。管理上，光靠他自己的規範意識不足以防堵利己傾斜，需要把公平分配的具體規則講清楚，並持續檢查折衷結果是否偏向他自己。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2438, 'CIA_04', 'B (中)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：表現為「公平不退讓的折衷協商者」。即使很想達成目標或搶得先機，他也不會考慮用欺瞞、偷取、貪污或占他人便宜這類手段，對『對等』與『規則要一致適用』看得很重。規範他大多會遵守，但資源不足或目標出現衝突時，他還是會想找一個折衷方案，不過這個折衷會先卡在會不會對他人不公平上，寧可進度慢一點也不願意用犧牲他人利益的方式換取效率。真正被明講『不能動』的界線，他不用被反覆提醒就會守住；沒被明講的灰色地帶，他也會用自己對公平的堅持去把關，不至於一路退讓。管理上，遇到需要快速折衷的情境，可以放心把公平相關的判斷交給他，但仍要記得先把資源或時程的硬底線講清楚，避免他在拿捏公平時卡太久拖慢進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2439, 'CIA_04', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「效率至上的冷酷者」。雖然做事有紀律能達成目標，但缺乏道德感或對規範的尊重，容易為了達成任務而遊走灰色地帶。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2440, 'CIA_05', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「鋼鐵般的穩定者」。具備極高的自律性與自我控制力，是高難度長線專案的最佳負責人。管理預測：產出極其穩定，極少因個人情緒影響工作進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2441, 'CIA_05', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「冷靜的狩獵者」。能為了最終成就而忍受長期的枯燥與誘惑。管理建議：適合擔任需要高度專注力且具備延遲滿足特性的高階開拓職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2442, 'CIA_05', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「極致的理性派」。行動前深思熟慮且行為受控，絕不輕率表態。警示：在需要「快速試錯」的環境中可能顯得過於保守或反應遲鈍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2443, 'CIA_05', 'A (高)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「高階操縱者」。行為高度受控但動機不純，能冷靜且有計畫地為了目標欺騙或操縱他人，是組織中最高層級的誠信風險，需加強合規監督。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2444, 'CIA_05', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「靜默的受難者」。雖然能管住行為不爆發，但內心缺乏緩衝能力。管理風險：容易將壓力內化導致身心崩潰或突然「無預警離職」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2445, 'CIA_05', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「高度修養的壓力鍋」。極易被激怒但能展現極強的職業素養予以壓制。警示：外表冷靜但內心消耗巨大，需適度給予情緒宣洩空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2466, 'CIA_06', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「細節偏執者」。對排列、程序與成果無瑕疵有極強渴望。管理風險：容易因瑣碎細節而耽誤核心進度，需主管適時定義「何謂完成」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2446, 'CIA_05', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「平時穩健、壓力尖峰易失守的執行者」。他做事一貫主動掌握進度，顧品質、顧收尾，不太需要別人在後面催。日常節奏下情緒也管得住，講話有分寸、決定不倉促。但一旦連續幾天高壓、衝突不斷或睡眠被壓縮，語氣會先變硬、耐心先掉下來，即使手上的任務仍照著計畫在推進，那股穩定的自我要求會被一時的煩躁蓋過去。管理上宜在他進入高壓期時主動關心狀態、必要時分攤緊急事項，讓他的自律有機會撐過情緒的低點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2447, 'CIA_05', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「平穩推進、壓力下最先鬆手的人」。他多半把工作完成在合理範圍就好，不特別追更高難度，動能本來就跟著環境支持走；情緒平常也管得住，很少衝著誰發脾氣。但遇上連續高壓、衝突或睡眠不足的日子，反應會變快、語氣變硬,這種時候他更沒有動力硬撐去多做一點，直接退回到把眼前交差就算了的狀態，甚至懶得解釋自己為什麼慢下來。管理上宜在高壓期主動幫他清出優先序、降低額外要求，避免情緒緊繃疊上動能低落一起拖垮產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2448, 'CIA_05', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「決策前會想清楚、情緒上頭時仍硬撐判斷的人」。他做決定前習慣先評估風險與後果，不確定的情境也能維持一定的判斷品質，這點平時很穩。只是碰到連續高壓、衝突或睡眠不足,反應會變快、語氣變硬、耐心下降,那種時候他仍然想按原本的評估邏輯走,卻得多花力氣壓住想立刻回應的衝動,思考的品質沒垮但過程明顯吃力,偶爾還是會在還沒想透前就先把話說出口。管理上宜在他高壓期給決策留緩衝時間，避免逼他當場拍板，讓審慎的判斷力有空間跟上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2449, 'CIA_05', 'B (中)', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「順風自制、逆風話術的緩衝者」。多數時候他情緒管得住，話說得直來直往，不太需要包裝就能把立場講清楚。遇到連續高壓、衝突或睡眠不足的情境，他的耐心會先鬆動，語氣變快變硬。這種時候他更容易先丟出討巧的說法或只透露部分資訊來壓住場面，等情勢緩和後再回頭解釋或圓場。管理上宜在他明顯疲憊或連續衝突後先介入緩衝，避免讓他在耐心見底時用選擇性資訊撐場面。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2450, 'CIA_05', 'B (中)', 'CIA_18', 'A', '與 CIA_18 (韌性) 高分聯動：表現為「情緒會被激起、但很快能自己拉回來的人」。他平常自制力沒問題，一旦進入連續高壓、衝突或睡眠不足的階段,反應還是會變快、語氣還是會變硬、耐心還是會下降——這一段他躲不掉。差別在於他很快就能把這次的失控轉成修正動作，重新回到能正常運作的狀態，不會卡在情緒裡太久，也願意主動找人補救剛才說重的話。管理上可以放心讓他自己走過情緒尖峰,只需要在他語氣變硬的當下稍微提醒一句,他多半能自己收回來、把場面接住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2451, 'CIA_05', 'B (中)', 'CIA_36', 'C', '與 CIA_36 (情緒易激度) 低分聯動：表現為「多數時候冷靜、特定壓力點才會繃不住的人」。他情緒反應門檻本來就偏高，遇到一般的煩惱或摩擦多半能保持冷靜、不至於做出高代價的衝動決定。但當連續高壓、衝突或睡眠不足疊在一起時，他這道防線也會被推到臨界，那幾天語氣會變硬、耐心會下降、回應速度變快,跟平常那個穩重的樣子明顯不一樣，只是這種失守維持的時間通常不長，情況緩解後很快又能回到原本冷靜的狀態。管理上宜留意他這種瞬間失衡的信號，不必過度解讀成性格轉變，給他一點緩衝空間即可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2452, 'CIA_05', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「細節要求高、心浮氣躁時仍不肯放水的人」。他對品質的要求平常就高，會反覆檢查、優化到自己滿意為止。碰上連續高壓、衝突或睡眠不足的時候，語氣會先變硬、耐心會先下降，跟人對話容易顯得不耐煩,但他對輸出品質的那把尺沒有跟著鬆掉,反而可能因為情緒緊繃又不肯降低標準,對細節更加挑剔、對自己和旁人都更難忍受一點小疏漏。管理上宜在他高壓期分開處理情緒出口與品質要求，別讓兩者一起發作,適時提醒他標準可以階段性放寬,先把情緒穩下來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2453, 'CIA_05', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的追求者」。內心極想做好（盡責）但行為卻常失控違規。行為預測：工作成果起伏巨大，常在「失誤」與「拼命補救」之間循環。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2454, 'CIA_05', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「挫敗的完美主義」。雖對品質有極高要求，但因行為魯莽常在細節出錯。管理建議：容易因自己的失誤而陷入極大的自我責備，需他人協助檢查細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2455, 'CIA_05', 'C (低)', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「投機冒險者」。不僅管不住衝動，且缺乏誠信底線，極易為了短期利益而觸犯規則或法律，需嚴格限制其權限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2456, 'CIA_05', 'C (低)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「失控的發明家」。點子多且行動極快，但常在未經測試前就推翻現有流程。管理警示：適合發想階段，但不宜讓其主導專案落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2457, 'CIA_05', 'C (低)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「情緒敏感的協調者」。雖能感同身受，但易因一時激動而做出過度的情感承諾。預測：容易在職場衝突中因一時同情而壞了規矩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2458, 'CIA_05', 'C (低)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「社交變色龍（負面型）」。雖能適應人際關係，但常因衝動說錯話或表錯態，導致原本建立的關係迅速崩塌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2459, 'CIA_05', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場地雷」。認為自己應得特權且管不住脾氣，一旦環境不如其意便會立刻爆發。管理警示：對團隊士氣殺傷力極大，需建立明確的行為底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2460, 'CIA_05', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「人設崩塌者」。極度渴望獲得認可但卻管不住負面衝動，常在失控後花極大心力進行公關式彌補。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2461, 'CIA_05', 'C (低)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「三分鐘熱度者」。熱情時極其投入，但一旦遇到挫折或新誘惑，興趣會迅速轉移，長期穩定性存疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2462, 'CIA_05', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「典型的火藥桶」。極易生氣且會立刻表現於行為。預測：頻繁引發人際衝突，不適合團隊協作崗位，需獨立作戰空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2463, 'CIA_06', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「系統化的執行者」。不僅想把事做好，還能建立標準作業程序 (SOP) 並嚴格執行。預測：極其穩定且精確的產出，是流程優化的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2467, 'CIA_06', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「實務改良家」。能將天馬行空的創意整理成邏輯通順的實施方案。預測：能讓創新成果落地的關鍵橋樑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2468, 'CIA_06', 'A (高)', 'CIA_21', 'C', '與 CIA_21 (效率取向) C聯動：表現為「繁文縟節的愛好者」。雖然愛好程序，但卻過於精確 methodical 導致喪失效率，適合稽核崗位，但不適合敏捷團隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2469, 'CIA_06', 'A (高)', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「自創系統者」。喜歡有條理，但不喜歡「別人的」條條框框，會傾向於重新建立一套自己覺得更高效的程序。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2470, 'CIA_06', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「程序守門員的怒火」。當環境被弄亂或他人不按 SOP 執行時，會瞬間被激發情緒反應，對混亂有極低的容忍度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2471, 'CIA_06', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「工具輔助型的可靠推進者」。他對自己要求高，任務進度、品質與收尾不太需要別人盯，通常能一路推進到完成。但把資訊分類、排定流程這件事，他做到基本程度就好，不是每次都會系統化建檔或排序。同時處理多件事時，他常靠便條、清單或提醒工具撐住秩序，少了這些輔助，細節容易留在腦中而不是紀錄裡。整體推進不會卡關，只是檔案或交接紀錄常內容都在，卻不一定好找。管理上可以放心把結果責任交給他，同時提供簡單的整理範本或提醒機制，讓產出更容易被接手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2472, 'CIA_06', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「看要求鬆緊調整的達標者」。他做事習慣把任務完成在說得過去的範圍，不特別去挑戰更高難度或多做份外的東西，有沒有動力多半看環境給不給支持、有沒有明確要求。整理這件事他能抓出重點、維持基本秩序，但不會每件事都建立系統化流程；事情一多，需要清單或提醒才撐得住條理。在要求明確、有人跟催的場合，他一邊會把事情確實做完，一邊也比較會把該記錄的內容記下來。遇到要求模糊、沒人特別在意結果時，他一邊容易停在「做完就好」，一邊也少了分類、歸檔這類動作。管理上把期待講清楚、給定期檢核點，能穩住他的產出範圍，也讓紀錄跟著清楚一些。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2473, 'CIA_06', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「單線周全、多線待撐的判斷者」。他做決定前習慣先想過風險、假設和可能後果，不會憑一時感覺衝出去，就算情境不確定，判斷品質也能維持住，返工的狀況比較少見。但把這些想法或資訊落成清楚的紀錄、分類、排程，他做得到基礎程度，不是每次都會建立完整系統；事情一多、要同時盯好幾條線時，得靠清單或提醒才撐得住條理。單一決策場合，他的評估通常完整又扎實；換成需要同時追蹤多個決策、多條資訊線的場合，他仍會把每個判斷想清楚，但支撐判斷的資料容易零散在不同地方、不好回頭查。管理上若在多任務情境提供簡單的追蹤工具或整理模板，能讓他判斷後的依據更容易被保存與回溯。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2474, 'CIA_06', 'B (中)', 'CIA_07', 'C', '與 CIA_07 (完美主義) 低分聯動：表現為「先交付、後補秩序的推進者」。他做事的優先順序很清楚：先把東西生出來、交出去，細節做到堪用就往下一步走，不會為了打磨而拖慢腳步。整理資訊、排定流程這件事，他能做出基本秩序、抓住重點，但不是每個環節都會系統化處理；一旦手上同時有好幾件事在跑，沒有清單或提醒盯著，容易漏掉該記錄卻沒記錄的細節。在步調快、要求快速迭代的場合，他能一路推進不卡關，只是小疏漏、沒歸檔的資訊容易一件一件累積，等到要回頭查或交接時才會被發現。管理上若能搭配簡單的檢核清單或固定的收尾動作，能在不拖慢他推進速度的前提下，把容易漏掉的細節攔下來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2475, 'CIA_06', 'B (中)', 'CIA_20', 'A', '與 CIA_20 (創新力) 高分聯動：表現為「點子常有、歸檔常缺的開創者」。他做事喜歡找新角度，遇到問題常主動提出跟慣例不同的做法，也不太甩既有規則對他的限制，願意打破現成流程去試新的路。但把手上的資訊、想法分類歸檔這件事，他只做到抓重點、維持基本秩序的程度，不是每次都會建立完整系統；同時有多個新點子或多條任務線在跑時，若沒有清單或提醒工具幫忙，好幾個想法容易同時卡在腦中、沒有落成看得到的紀錄。單一個新點子從發想到收尾，他還能自己記得脈絡；一旦點子一多、又跳著做，回頭想找某個判斷的來龍去脈就會變得困難。管理上若給他一個簡單、不綁死流程的記錄方式，能在不擋住他嘗新的前提下，讓這些想法比較容易被找回來、被接手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2476, 'CIA_06', 'B (中)', 'CIA_21', 'C', '與 CIA_21 (效率取向) 低分聯動：表現為「守程序、多線時秩序打折的執行者」。他做事偏好照著明確的步驟走，覺得穩定的流程比抄捷徑更靠得住，遇到能省事的破格做法也不會優先選，寧可照規矩來、把精確度顧好。不過落到實際把資訊分類、把工作排出頭緒這件事，他做得到基本程度，不是每個環節都會系統化整理；事情一多、要同時處理好幾條線時，仍然需要清單或提醒才撐得住秩序。單一條線、按表操課的場合，他既照步驟走、也能把該記的記好；換成多線並行、步驟被打斷或臨時插件的場合，遵循程序的意願還在，但真正落成紀錄、排好順序的動作容易跟不上。管理上把工作拆成清楚的步驟、一次不要塞太多條線給他，比較能讓他的產出維持穩定、紀錄也跟得上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2477, 'CIA_06', 'B (中)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) 高分聯動：表現為「闖路不卡關、多線時秩序待撐的行動者」。遇到沒有前例、沒人告訴他該怎麼做的情境，他不會卡住，通常能自己摸索出一條可行的路，繼續往前推進，不需要現成的規則或方法幫他兜底。但把摸索出來的做法、過程中累積的資訊整理成看得懂的秩序，他做得到抓重點、維持基本結構的程度，不是每次都會建成完整系統；一旦同時要開好幾條沒前例可循的路，光靠腦子記，細節容易漏掉，得靠清單或提醒才撐得住條理。單獨一件沒規則可循的任務，他從摸索到收尾都還算跟得上；多件這種任務同時開展時，找路的能力還在，但把每條路徑走過的紀錄留下來、方便日後回頭查，就比較吃力。管理上若在他同時處理多個無前例任務時，搭配簡單的追蹤紀錄或定期回顧，能讓摸索出來的做法比較容易留存、被複用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2478, 'CIA_06', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「隨興的苦幹者」。雖然非常盡責想把事做好，但做事雜亂無章、缺乏次序。行為預測：努力但效率低，需行政輔助工具協助管理進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2479, 'CIA_06', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「混亂的獵人」。極想達成業績目標，但過程中容易丟三落四、遺漏細節。警示：業績好但售後或行政手尾極多，需配備助理協助控管。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2480, 'CIA_06', 'C (低)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場混亂製造者」。既沒條理又容易衝動行事。管理風險：行為極度隨機且不可控，會造成團隊協作上的巨大困擾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2481, 'CIA_06', 'C (低)', 'CIA_07', 'A', '與 CIA_06 (條理性) C 與 CIA_07 (完美主義) A：表現為「內在衝突的完美者」。渴望完美但缺乏建立次序的能力。預測：會因環境混亂而焦慮，卻又不知如何整理，需他人協助建立架構。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2482, 'CIA_06', 'C (低)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「非典型的快速執行者」。雖然不重視程序與整潔，但對獲取結果的效率有極強渴望。會用跳躍式的路徑達成目的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2483, 'CIA_06', 'C (低)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「負責任的散漫者」。對結果負責，但過程極其跳躍。管理預測：只要給他最終成果的期限，不要管他過程怎麼排列。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2484, 'CIA_07', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高品質保證者」。強大的自制力支撐其對完美的追求。行為預測：產出極其精緻且合規，是處理精密任務或核心資產的關鍵人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2485, 'CIA_07', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密的防禦者」。行動前反覆推敲以確保無誤。管理警示：極度畏懼錯誤，在面對高時效要求的專案時，可能因過度檢查而錯失良機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2486, 'CIA_07', 'A (高)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「冒名頂替症候群 (Imposter Syndrome)」。設定了極高標準卻不相信自己能達成。管理風險：極度焦慮，即使表現優異仍深感挫折，需頻繁情感支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2487, 'CIA_07', 'A (高)', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「挑剔的管理者」。對自己要求完美，且認為自己理應獲得最高尊重，易對下屬或同僚表現出不耐與輕視，造成人際摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2488, 'CIA_07', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性完美主義」。一旦專案出現無法控制的瑕疵，其自我認同會崩解。預測：在逆境下恢復緩慢，甚至可能因一次失敗而選擇徹底逃避。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2489, 'CIA_07', 'A (高)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「卓越的工匠」。不僅追求完美，更渴望用最快、最精確的方式達成。預測：這是效率與品質兼備的極佳組合，是高階專業技術職的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2490, 'CIA_07', 'A (高)', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的工作狂」。對細節的執著凌駕於對他人感受的關注。警示：容易為了成果無瑕疵而過度逼迫團隊，導致團隊流失率增高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2491, 'CIA_07', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易爆的檢查者」。對任何不完美的行為（如垃圾沒丟好、簡報格式跑掉）會產生即時且強烈的情緒反應，容忍度極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2492, 'CIA_07', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「自律型的品質收放者」。他平常推進穩定,很少需要外部催促也能維持可靠輸出;碰到他判定重要的任務,標準會主動拉高,但只要時間或資源吃緊,他仍看得出哪裡該收、哪裡可以放一手。品質與速度的界線不是憑感覺猜,是邊做邊調整出來的。管理上把明確的完成標準先講清楚,讓他能自己拿捏該磨到什麼程度、什麼時候該停手交件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2493, 'CIA_07', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「衝刺中臨時加碼的人」。他常常不等全盤想清楚就先動手,節奏快、也敢衝;但只要碰到自己在意的重要任務,會在動手途中臨時拉高標準、回頭補檢查,即使原本沒打算做到那麼細。這種臨場加碼容易打亂原本的節奏,補檢查花的時間也未必抓得準。管理上宜先框出哪些任務容許快做快改、哪些任務值得他放慢磨,讓他知道臨時加碼的界線在哪裡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2494, 'CIA_07', 'B (中)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) 高分聯動：表現為「敢接高標任務的收斂者」。他對自身能力與掌控感有信心,遇到挑戰願意承擔、也敢自己找方法,不太因為不確定而卻步;但一到真正重要的任務,他仍會把標準往上調,同時清楚時間或資源撐不住時該在哪裡收手。這種自信不會讓他每件事都往滿分衝,他知道什麼時候「夠好」就是夠好。管理上可以放心把有難度、需要獨立判斷取捨的任務交給他,不必額外緊盯。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2495, 'CIA_07', 'B (中)', 'CIA_14', 'C', '與 CIA_14 (謙虛) 低分聯動：表現為「被能見度牽動標準的人」。他在意成果有沒有被注意到,對別人表現得到的關注也比較敏感;碰到自己判定重要的任務,會把品質標準拉高好讓成果站得住,但仍能視時間或資源夠不夠而收斂到「這樣就行」。只是這種收斂有時會被「這件事夠不夠亮眼」的念頭牽著走,而不是單純看任務本身的份量。管理上宜把重要任務的評斷標準講清楚,避免他把心力錯放在追求能見度而非任務真正需要的品質上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2496, 'CIA_07', 'B (中)', 'CIA_18', 'A', '與 CIA_18 (韌性) 高分聯動：表現為「挫折後快速收斂標準的人」。他碰到壓力、衝突或失敗後,回到可工作狀態的速度快,也習慣把打擊直接轉成修正動作;遇到自己在意的重要任務,標準會拉高,但資源或時間吃緊時仍收得住,不會一路死磨到底。這讓他在出錯之後不只是狀態上復原,還能同時判斷這次補救該做到多細、什麼程度算夠。管理上可以放心讓他處理容易出狀況又要求品質的任務,他能自己完成復原與收斂標準這兩件事。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2497, 'CIA_07', 'B (中)', 'CIA_21', 'C', '與 CIA_21 (效率取向) 低分聯動：表現為「按流程分配講究心力的人」。他做事偏好照著穩定流程走,重視精確與條理,效率是靠流程本身穩定產出,不靠臨場抄捷徑;碰到自己認定重要的任務,標準會再拉高一截,但只要時間或資源吃緊,他仍能看出流程裡哪個環節可以簡化、哪個環節不能省。他的照規矩來不等於每個細節都要做到頂,重要與否仍會影響他在流程裡分配心力的方式。管理上把任務的重要程度先標明,能幫他把有限心力放進流程中真正該講究的段落。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2498, 'CIA_07', 'B (中)', 'CIA_26', 'A', '與 CIA_26 (同理心) 高分聯動：表現為「顧品質也顧當下人的人」。他跟人互動時會留意眼前的人處境與感受、調整語氣貼近他人真正需要;碰到自己在意的重要任務,標準會拉高,但也看得出時間或資源撐不住時該從哪裡收。他要求品質的同時,不會因為顧著磨細節而忽略眼前的人此刻真正需要什麼。管理上可以讓他負責同時要顧品質、又要顧及他人感受與節奏的任務,他自己會抓好分寸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2499, 'CIA_07', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「務實的執行者」。雖然自律且盡責，但不糾結細節，以完成任務為首要。管理預測：產出速度快且及格，適合高週轉率、容許微小誤差的工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2500, 'CIA_07', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「擴張型獵人」。極想贏但不在意過程是否無瑕疵。管理警示：容易達成業績但「售後」問題多，需安排「條理性高」的人員協助收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2501, 'CIA_07', 'C (低)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「豁達的進取者」。容許失敗與瑕疵，並對未來保持樂觀。預測：心理彈性極佳，非常適合變動劇烈、不確定性高的創業型環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2502, 'CIA_07', 'C (低)', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「自由散漫者」。既不追求完美，也不想遵循規則。管理風險：除非有強大的熱忱支持，否則其產出品質往往難以維持組織基本水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2503, 'CIA_08', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「高產能開拓者」。不僅渴望成功，且深信自己具備達標的能力。預測：在面對困難專案時具備極強的心理優勢，是帶領團隊突破困境的靈魂人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2504, 'CIA_08', 'A (高)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「穩健的掌控者」。相信自己能應付局面，且行為高度自律。管理預測：在危機時刻能保持冷靜，不因恐慌而失控，是極佳的危機處理人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2505, 'CIA_08', 'A (高)', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「膨脹的權威」。具備能力自信但缺乏謙遜。警示：容易變得剛愎自用，不願聽取他人建議，甚至在團隊中形成獨裁風格，需注意其人際關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2506, 'CIA_08', 'A (高)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「體制內的專家」。在熟悉的規則架構下感覺極度自信且高效。預測：是組織 SOP 的最佳執行者，能完美維護既有系統的運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2507, 'CIA_08', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自負的精英」。深信自己的卓越能力應換取特殊優待。管理風險：對一般行政要求配合度低，認為瑣事應由他人代勞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2508, 'CIA_08', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「求證後全力衝的進取者」。他對表現與成果有明顯企圖心，願意多投入去達到更高標準，但真正踩下油門前，會先想確認自己抓對了方向、能力接得住這個挑戰。熟悉領域裡他敢直接把目標訂高、主動升級做法；換成新領域或風險較大的任務，他仍然想拚更高標準，卻會先找人核對一下框架或邊界，得到確認後動能立刻回滿、投入毫不打折。管理上，給他明確的高標目標之餘，若能在啟動階段快速回應他的確認需求，他的進取心會發揮得更完整、更持久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2509, 'CIA_08', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「情緒一亂就自我懷疑的人」。他較容易被情緒推著走，出現衝動回應、倉促承諾或行為過頭，事後常需要修補或解釋；一旦這種情況發生在他還沒把握的任務上，他會開始懷疑自己是不是真的能掌控局面，需要有人幫忙確認方向才敢繼續推進。在熟悉的場合他能力足夠、輸出穩定，但情緒一衝動就容易連帶動搖他對自己判斷的信心，變得想找人核對而不是自己拍板。管理上宜在他情緒起伏後、進新任務前，先給予明確肯定與方向確認，避免衝動留下的不確定感拖慢他重新建立信心的速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2510, 'CIA_08', 'B (中)', 'CIA_14', 'A', '與 CIA_14 (謙虛) 高分聯動：表現為「確認過才敢說自己做得到的人」。他對自身與他人的相對位置看法平衡，不太需要透過炫耀或壓過別人來證明價值,也能接受他人的貢獻;面對新領域或高風險任務,他不會急著把話說滿,反而希望先確認一下、拿到具體支持後再承接。他不會用姿態去掩蓋不確定,而是傾向老實說「這塊我還需要再確認」,等到方向清楚、有人回應之後,就能安穩地把事情做出來、信心也跟著逐步累積。管理上可以直接給他清楚的資訊與回饋管道,不必擔心他因此顯得退縮,他要的只是踏實的確認,不是被捧。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2511, 'CIA_08', 'B (中)', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) 低分聯動：表現為「規則清楚才敢放手做的人」。他偏好依循既有且被接受的方法,規則越清楚越能發揮,面對模糊規則時容易卡住、效率下降;這種卡頓在新領域或高風險任務上會更明顯——他不只是不知道方法,還會開始懷疑自己是不是有能力把這件事扛起來,需要先確認清楚的規則或標準才敢動手。一旦規則到位、方向確認過,他就能穩定產出,也逐漸累積起自己確實做得到的信心。管理上宜在交付模糊性高的任務前,先幫他把規則邊界講清楚,他的能力才有機會被看見,而不是卡在「不確定能不能做」的階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2512, 'CIA_08', 'B (中)', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「先要確認才要待遇的人」。他較容易認為自己應得到特殊待遇,不一定以努力或績效為前提,期待落空時可能強烈不滿或對抗;但這份「應得」的認定,在新領域或高風險任務上會先讓位給另一個念頭——他得先確認自己真的接得住、真的做得到,才會理直氣壯地要求相應的待遇。等到有人給了明確支持、他把事情穩定做出來,他對自己該得什麼的主張反而會更堅定、更難被說服讓步。管理上除了要留意他對回報的敏感度,也可以善用他求確認的這一面,把確認的過程做扎實,能同時降低他事後不滿的機率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2513, 'CIA_08', 'B (中)', 'CIA_01', 'C', '與 CIA_01 (盡責) 低分聯動：表現為「沒抓穩節奏就更不敢放手的人」。他較容易受情境或情緒影響而出現拖延、鬆散或收尾不足,不是做不到,而是自我監控與維持節奏本身就吃力;這種吃力感一旦碰上新領域或高風險任務,會進一步變成他對自己能不能扛住的懷疑,想找人確認方向、確認自己沒有偏航。一旦有人幫他把進度盯住、給出明確回饋,他的輸出反而會穩下來,信心也一點一點建立起來。管理上宜提供具體的進度檢核點,而不是只給目標放他自己走,檢核點同時能穩住他的節奏、也能滿足他想被確認的需要。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2514, 'CIA_08', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「反覆確認到位才放手交件的人」。他對細節與品質要求高,會反覆檢查與優化以求做到無瑕疵;面對新領域或高風險任務時,這種反覆檢查會帶著一種自我確認的意味——他不只是在挑錯,也是在透過一次次核對,確認自己真的有能力把品質撐住。一旦得到方向上的支持或明確回饋,他的檢查就會從「反覆懷疑」轉成「穩定把關」,輸出品質可靠、也不再需要一直重來。管理上宜在高標準任務前段就給予清楚回饋,讓他的高要求盡早找到穩定的施力點,而不是耗在無止盡的自我確認裡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2515, 'CIA_08', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的耕耘者」。雖然做事盡責努力，但內心始終擔心自己能力不足。行為預測：會花過多時間反覆檢查，雖然產出品質高，但心理內耗極大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2516, 'CIA_08', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「癱瘓的完美主義」。因追求無瑕疵但又不信自己能達成，導致嚴重的拖延症。管理建議：需主管協助拆解小目標，累積成功的「微體驗」以重建信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2517, 'CIA_08', 'C (低)', 'CIA_17', 'C', '與 CIA_17 (目標效能感) C聯動：表現為「習得性無助者」。完全不相信努力能改變結果。警示：在高壓環境下極易放棄，是組織績效的重大隱憂，需關注其身心健康與職務契合度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2553, 'CIA_10', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「極端利己者」。完全以目標為導向且具備操縱傾向。風險預測：高頻率出現職場政治操弄，需嚴格控管其決策權限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2518, 'CIA_08', 'C (低)', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「韌性支撐的求存者」。雖然目前對自己信心不足，但遭遇打擊時能迅速站起並從頭再來。管理建議：屬於大器晚成型，適合長期培養以建立信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2519, 'CIA_08', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「討好型偽裝者」。因對能力沒信心，會過度觀察他人臉色並迎合期望以獲取安全感。其專業觀點可能因恐懼而不誠實。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2520, 'CIA_09', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「卓越的馬拉松跑者」。具備強大的目標導向與執行意志，能為了長遠成功忍受現階段的艱辛。預測：在長期轉型專案中展現極佳的穩定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2521, 'CIA_09', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「冷靜的戰術執行家」。在深思熟慮後，能嚴格控制行為不偏離既定策略，絕不因外部干擾而打亂節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2522, 'CIA_09', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「意志力與情緒的拉鋸」。雖然內在有強烈長期目標（自律），但外在行為易受誘惑干擾（衝動）。管理警示：此組合會造成巨大的心理內耗，需建立環境隔離誘惑以輔助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2523, 'CIA_09', 'A (高)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「高度務實的奮鬥者」。其自律源於對物質回報的強烈渴望，能為了高額獎酬或地位晉升展現出極致的禁慾與努力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2524, 'CIA_09', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「有紀律的發明者」。能克制「只發點子不做事」的傾向，強迫自己將創新概念進入繁瑣的研發與測試階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2525, 'CIA_09', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自負的修煉者」。因具備極強自律能力而認為自己應獲得特殊優待，並容易對不自律的下屬展現出缺乏同理心的批判。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2526, 'CIA_09', 'A (高)', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) C聯動：表現為「專業的苦行僧」。雖然對工作缺乏熱情，但憑藉強大的意志力（自律）依然能高品質完成任務，行為表現極其職業化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2527, 'CIA_09', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「有企圖心但續航看情境的推進者」。他對做出更高水準的成果有明顯企圖心，願意多投入、主動把方法和目標往上升級。目標清楚、節奏穩定時，這股企圖心能撐著他持續延遲享受、把計畫走完；一旦壓力拉高、干擾變多或看不到回饋，原本想衝更高標準的念頭仍在，卻越來越難把自己按在計畫上，容易鬆動或拖到最後才補。管理上宜替他固定檢查點與可見的進度回饋，讓企圖心有著力點，避免高目標和低自控落差變成拖延的來源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2528, 'CIA_09', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先動手、自律靠環境撐住的行動派」。他傾向先做再說，評估常常是事後補上，在快速節奏下能立刻衝出去。這種先行動的慣性,在目標明確、環境有支持的時候還撐得住——他知道終點在哪,衝完會回頭把節奏拉回來;但一旦壓力變大、干擾變多,他容易一邊倉促出手,一邊把原本該守住的長期計畫放到後面,隱性風險跟收尾拖延就跟著冒出來。管理上宜替他在行動前插入輕量檢核點,並在高壓期主動盯進度,減少衝太快又收不回來的狀況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2529, 'CIA_09', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「情緒穩得住、節奏仍會被壓垮的人」。他在壓力下仍能管理情緒與衝動反應,不容易因一時情緒做出高代價的決定,面對挫折或催促也能維持一致的言行。可是這份穩定管得住的是情緒表現,管不住的是長期節奏——目標清楚、環境支持時他能把自律維持得不錯,一旦壓力拉長、干擾增加或回饋斷了,他表面依舊平靜,行動上卻悄悄鬆動、進度慢慢往後拖,不會爆發,但會沉默地落後。管理上宜主動追蹤進度而非只看情緒表現,提早補上回饋與提醒,才能在他還沒察覺自己已經落後前介入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2530, 'CIA_09', 'B (中)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) 低分聯動：表現為「自律隨誘因擺盪、易被眼前回報帶走的人」。他較重視財富、地位或外在象徵,對回報是否到位相當敏感,容易把具體的物質激勵當成自己願不願意投入的主要交換條件。有清楚誘因擺在眼前時,他能撐住節奏把長期任務走完;可一旦看不到明確回報,或誘因換成模糊的未來承諾,他原本就容易鬆動的自我約束會更快垮掉,轉而被眼前更快拿到手的東西吸走注意力。管理上宜把長期目標拆成有具體、可見回報的中繼站,讓他每一段都摸得到誘因,自律才有東西可以撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2531, 'CIA_09', 'B (中)', 'CIA_20', 'A', '與 CIA_20 (創新力) 高分聯動：表現為「點子敢衝、把點子走完要看環境的人」。他喜歡用新方法做事,會主動發現問題、提出替代解法,也不太甘於被既有的慣例框住,遇到瓶頸第一反應是換個角度重來一次。這份敢換路的衝勁,在目標清楚、環境給空間時能延伸成把新解法一路執行到底的耐性;可一旦干擾變多、回饋不明顯,他維持既定路徑的自我約束會先鬆動,常常還沒把一個新點子走完,注意力已經被下一個更有趣的可能性拉走。管理上宜替他的創意設固定的收尾檢查點,並在高壓或多工期主動確認上一個點子有沒有真的執行到底,避免構想不斷冒出卻少有真正落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2532, 'CIA_09', 'B (中)', 'CIA_32', 'C', '與 CIA_32 (心理特權) 低分聯動：表現為「不居功也守不住節奏的人」。他較少認為自己應該獲得特殊待遇,對資源分配與既有規則接受度高,習慣用實際貢獻而不是身份去換回報,不太會為自己爭取例外空間。壓力大或資源被排擠時,他不太開口要求調整,多半選擇默默承受、自己想辦法消化;目標模糊或干擾一多的時候,他維持節奏的自我約束也容易鬆動,常常是進度和品質悄悄往下掉、他卻不主動反映哪裡吃緊。管理上宜主動關心他的負荷而非等他反映,並在資源緊縮時明確告知他的優先序,避免他因為不爭取而被動吸收過多壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2533, 'CIA_09', 'B (中)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) 高分聯動：表現為「熱情帶得動、熱情退了才見真章的人」。他對工作本身懷有明顯熱情,願意多付出去追求成果與成長,能量通常算充足,投入時很少需要人推。任務有意義、節奏順的時候,他能持續延遲享樂、把長期計畫穩穩推進;熱度一旦被壓力、干擾或看不到回饋磨掉,他維持節奏的自我約束也跟著鬆動,行動力明顯打折、拖延開始出現,他自己也未必第一時間意識到落差已經拉開。管理上宜留意他熱情消退的訊號、及早補上意義感或具體回饋,而不是預設他的投入永遠穩定不變。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2534, 'CIA_09', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「受罪惡感驅動者」。內心極想做好（盡責）但行為上卻難以抵抗誘惑（低自律）。預測：常在最後一刻趕工，並在工作過程中伴隨高度焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2535, 'CIA_09', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「眼高手低的焦慮者」。對成果有無瑕疵的要求，卻管不住自己去落實細節。警示：容易產生「想得美、做不到」的落差，需主管介入監督進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2536, 'CIA_09', 'C (低)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「隨性的樂天派」。雖然不夠自律且易分心，但對未來保持積極期待，即便進度延遲也能自我排解壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2537, 'CIA_09', 'C (低)', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「多產但不落地的創意家」。有極多創新的原創想法，但因缺乏自律將其細緻化，成果往往流於草稿階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2538, 'CIA_09', 'C (低)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「救火式執行者」。雖然缺乏日常紀律，但一旦事情迫在眉睫，會基於強烈的責任感爆發性能量完成工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2539, 'CIA_09', 'C (低)', 'CIA_35', 'A', '與 CIA_35 (生活熱情) A聯動：表現為「熱情四射的散漫者」。對生活充滿活力與興趣，但工作上難以專注於單一目標，容易被新奇事物吸引而轉向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2540, 'CIA_10', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「正派的領袖」。追求成功但絕不走捷徑。預測：能建立具備長期信任感的團隊，即便在高度競爭下也能維持組織聲譽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2541, 'CIA_10', 'A (高)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「清廉的高效能者」。在追求效率的過程中極其精確且誠實，適合處理採購、預算控管等涉及龐大利益的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2542, 'CIA_10', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自覺的內耗者」。內心覺得自己應得特權，但道德感強迫自己謙虛。管理警示：容易累積隱性不滿，需注意其情緒平衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2543, 'CIA_10', 'A (高)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的誠信者」。不在乎他人評價或包裝形象，真實地展現正直。預測：是組織內部舉報或倫理風險查核的最佳守門員。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2544, 'CIA_10', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「衝刺型的原則權衡者」。他對成果有明確企圖心，遇到卡關會主動換方法、拉高標準也要拚到底，多數時候仍公平對待身邊的人、如實回報進度。但當衝刺的目標卡在最後一哩、時間所剩不多時，他可能把數字報得更漂亮一點，或把某個灰色地帶往對自己有利的方向解讀。這類落差不容易第一時間被察覺，往往要等結果對不上才追溯得回去。管理上宜在設定高目標時把怎麼做到講清楚，並在衝刺後段多一道檢核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2545, 'CIA_10', 'B (中)', 'CIA_21', 'C', '與 CIA_21 (效率取向) 低分聯動：表現為「照規矩走、關鍵處鬆動原則的人」。他做事偏好按部就班，重視精確與既定步驟，很少為了求快去跳過該有的程序，多數時候也如實、公平地對待每一項評估。但在強壓績效或利益衝突逼近時，他仍會按表操課走完整套流程，只是在某個可自由詮釋的環節，悄悄把判斷收斂到對自己較有利的一端。表面紀錄看起來完整合規，落差往往要等有人回頭比對細節才會浮現。管理上宜在關鍵判斷節點加入交叉複核，而不只是檢查流程是否走完。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2546, 'CIA_10', 'B (中)', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「自覺應得優待、落空即找補的人」。他心裡常帶著這本來就該是我的預期，不太會先問自己投入或績效夠不夠，資源、機會被分配時也習慣先設想自己該拿到較好的一份。多數時候他仍願意照公平的方式對待身邊的人，但一旦那份預期落空、又剛好碰上目標壓力，他的反應可能不只是表面不滿，還會在下一次分配或報告中，把天平悄悄調回對自己有利的位置。這種找補通常包裝成合理調整而不是公開爭取，旁人不容易第一時間看出用意。管理上宜把分配標準說清楚在先，並留意他情緒落差明顯後的下一個決定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2547, 'CIA_10', 'B (中)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) 低分聯動：表現為「自陳坦率、決斷時偏己的人」。被問到自己的狀態、能力或看法時，他傾向照實講，不太會為了留下好印象而把答案修飾得更漂亮，說出口的話普遍站得住。但這份坦率停留在講的層面，落到強壓績效或利益衝突的實際決定上，他仍可能在對自己有利與對他人公平之間做權衡，選擇偏向自己那一邊，卻不必然主動說破。旁人聽慣了他平常說話真誠，比較少去檢視他實際做的決定是否同樣公允。管理上宜把他怎麼說與他怎麼做分開檢視，尤其在利益牽涉到他自己的場合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2548, 'CIA_10', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「自律可靠、緊要關頭護交付的人」。他做事有一貫的自我標準，能自己掌握進度、顧好品質與收尾，不太需要人催，身邊的人也習慣把重要事情放心交給他。在強壓績效或利益衝突逼近、心裡只想著這次一定要交得出來時，他可能優先護住看得見的交付結果，對過程中某個沒做到位的環節，選擇輕描淡寫帶過而不主動攤開來說。他平常的可靠印象很深，這類淡化不容易被立即質疑。管理上宜在高壓收尾階段主動問細節，而非只看結果是否準時到位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2549, 'CIA_10', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先衝了才回頭看有沒有踩線的人」。他做事習慣先動手、邊做邊調整，評估常常是行動之後才補上，在快節奏場合能衝得很快，代價是容易漏看不明顯的風險。遇到強壓績效或利益衝突逼近的時候，他往往先把手上動作做完再說，沒有先停下來檢視這一步公不公平，等事情告一段落回頭看，才發現剛才那個選擇其實偏了。這種落差不是他刻意算計出來的，卻仍會造成實際的不公平結果。管理上宜在他啟動快節奏任務前，先框出幾條不能碰的底線，而不是事後才來釐清。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2550, 'CIA_10', 'B (中)', 'CIA_11', 'A', '與 CIA_11 (誠懇) 高分聯動：表現為「不騙人卻悄悄拿多一點的人」。他跟人溝通一向直接，不太會為了說服誰、推進目標而去操縱或誆騙他人，給出的資訊多半真實，合作也建立在這份真實上。但強壓績效或利益衝突逼近時，他未必說了什麼假話，更常是在資源分配、額度認定這類不需要開口就能動手腳的地方，把判斷悄悄收斂到對自己有利的一端。他說的話向來抓不到破綻，這種偏移往往要很久才被注意到。管理上宜把分配、認定這類環節的標準寫清楚並留紀錄，而不只是信任他口頭上的誠懇。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2551, 'CIA_10', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「精明的權謀家」。利用高度的自律與細心來實現個人私利，行為極難被察覺。警示：若缺乏外部稽核，容易造成系統性損害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2552, 'CIA_10', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深沉的政治家」。行為極其謹慎且不擇手段。管理警示：在職場競爭中擅長佈局且不留痕跡，需注意其對團隊互信的破壞力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2554, 'CIA_10', 'C (低)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「貪婪的追求者」。對財富、地位有極度渴望且不排除用非正式手段獲取。警示：是職場舞弊的高風險群組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2555, 'CIA_10', 'C (低)', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「狂傲的擴張者」。自視甚高且追求財富。管理建議：其強大的自信雖能帶來業績，但極易引發團隊衝突與流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2556, 'CIA_10', 'C (低)', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「虛偽的表演者」。為了利益可以隨時調整價值觀或行為，表裡不一。預測：人際關係起伏大，誠信基礎薄弱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2557, 'CIA_10', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較的利己主義」。對付出回報極其敏感，且會為了爭取更多私利而挑戰公平規則，屬於難以滿足的員工。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2558, 'CIA_10', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「職場變色龍」。表面極度謙虛、誠懇以獲取認可，實則內在逐利。警示：是最難識別的風險對象，需透過第三方反饋來驗證。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2559, 'CIA_11', 'A (高)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「正直的穩定者」。不僅不屑於欺騙，且能冷靜克制誘惑。預測：在金錢或權力誘惑面前具備極強的抵抗力，是組織信任的定海神針。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2560, 'CIA_11', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「透明的關懷者」。對人的關心發自內心，不帶目的性。預測：極易建立深厚的人際信任，適合擔任團隊黏著劑或心理諮詢角色。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2561, 'CIA_11', 'A (高)', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「拙於包裝的正直者」。為人誠懇但不懂圓滑，說話過於直白。管理警示：雖值得信任，但易在不經意間得罪人，需注意其溝通技巧。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2562, 'CIA_11', 'A (高)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的真我」。完全不掩飾缺點，也不刻意塑造形象。管理預測：其測評結果信效度極高，是職場中最透明、最好管理的類型。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2563, 'CIA_11', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「冷靜拿捏的表達者」。多數時候他回應誠懇、願意把真實想法說清楚，但一遇到競爭或政治情境，會刻意換個包裝方式來保護自己的立場。這時他不會因情緒失控而說溜嘴，反而能穩穩控制語氣與用詞，把要收起來的話收得很乾淨，把要釋放的話拿捏在剛好的分寸。他的節制不是因為緊張說不出口，而是清醒地選擇此刻該說多少、該怎麼說。旁人很難從他的情緒起伏看出他正在拿捏，只會覺得他每次開口都恰到好處。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2564, 'CIA_11', 'B (中)', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「各自運作的分寸感」。他多數時候誠懇待人，但在壓力或利益衝突下會採取較策略性的表達，選一個能保護自己立場又不算說謊的說法。問題是他不太容易捕捉聽的人會有什麼感受，互動時較少去揣摩言語落地後的情緒效果，於是他調整用詞時考慮的多半是「這樣講站不站得住腳」，而不是這句話聽起來會不會傷人。結果他自認拿捏得宜的說法，聽起來常顯得生硬或帶著距離感，他自己往往後知後覺才發現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2565, 'CIA_11', 'B (中)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) 高分聯動：表現為「看人下菜的圓融溝通者」。他面對不同性格與風格的人時，會先判斷眼前的人能接受多直接的說法、在意什麼，再調整用詞與揭露程度，並主動化解互動中容易出現的緊張。因此同一件事從他口中說出來，版本可能隨對象而有差異；面對強勢或立場對立的人，他更容易挑比較委婉、保護自己立場的說法。這種調整多半發生在措辭與呈現順序上，不涉及捏造事實或刻意誤導。旁人若同時聽到他對不同人的說法，可能會覺得他前後不太一致；但對他而言，這是在維持關係與守住底線之間找一條可以走的路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2566, 'CIA_11', 'B (中)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) 低分聯動：表現為「策略修飾但底子真實」。他在強壓績效或利益衝突的場合會拿捏措辭、選一個較安全的說法來保護自己的立場,但這份拿捏不等於扭曲事實——他呈現的想法與狀態底子仍偏真實,不會為了讓自己看起來更好、博取好感而大幅美化答案。換句話說,他調整的是表達的包裝層,不是內容本身的真假。當被直接追問細節時,他傾向給出經得起檢驗的版本,而不是一套聽起來漂亮卻站不住腳的說法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2567, 'CIA_11', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「為達標調整表達節奏」。他對成果有明顯企圖心,遇到挑戰會主動加碼投入,但這股衝勁碰上競爭或政治壓力大的場合,他不會不顧一切直說,而是先想清楚哪種說法既能推進目標又不至於樹敵過多。他可能暫時不揭露某個對自己不利的細節,或用比較迂迴的方式提出訴求,為的是讓局面持續朝目標推進。這種拿捏在他身上更像是一種達標策略,而不是單純的自我保護,一旦目標明朗、風險降低,他又會回到直接表達的狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2568, 'CIA_11', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先開口後收斂的臨場表達者」。大多數時候他表達得直接坦誠，但一到競爭激烈或政治敏感的場合，他會傾向調整用詞來保護自己的立場。在這類場合，他常常先把話說出口，才回頭覺得剛才的措辭需要收斂或修正。他在對話當下多半能快速接話、不冷場，但同一時間比較少停下來想某句話可能踩到誰的敏感點。聽的人有時會因此愣一下，或私下開始重新解讀他話裡的用意。管理上宜在他進入敏感或競爭場合前，先幫他預留一次語氣覆核的空檔，讓收斂發生在說出口之前而不是之後。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2569, 'CIA_11', 'B (中)', 'CIA_14', 'A', '與 CIA_14 (謙虛) 高分聯動：表現為「不為凸顯自己而修飾」。他對自身與他人的位置看得平衡,不太需要靠壓過誰或炫耀來證明價值,這讓他在拿捏措辭時,動機很少是為了讓自己顯得更厲害或搶功。他選擇較策略性的表達,通常是為了在競爭壓力下保護一個立場或避開不必要的衝突,而不是為了包裝自己的貢獻。也因此當他收斂某些話時,那份收斂顯得乾淨——不夾帶自我膨脹的成分,旁人事後回想,較少覺得他是在替自己臉上貼金。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2570, 'CIA_11', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目的導向的野心家」。為了業績或晉升，不惜美化事實或誤導他人。警示：短期績效雖好，但長期會嚴重損害團隊的互信基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2571, 'CIA_11', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精密的政治玩家」。操縱行為經過精密計算，且不會輕易留下把柄。風險預測：擅長推卸責任或竊取功勞，是組織內部的潛在負面變數。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2572, 'CIA_11', 'C (低)', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「偽善者」。表面表現得極度謙遜，實則內在充滿操縱動機。警示：最難防範的類型，常利用「弱者姿態」來獲取資源或同情。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2573, 'CIA_11', 'C (低)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「具備欺騙性的創意者」。可能利用創新的點子來包裝個人私利，或將他人的創意占為己有並進行改良。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2574, 'CIA_11', 'C (低)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「派系操作者」。極力維護小團體利益，但過程充滿政治操弄，容易在組織內形成「小圈子」文化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2575, 'CIA_11', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「權利的計較者」。會利用操縱手段來確保自己獲得「超額回報」，並對任何微小的不公平進行政治化的反擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2576, 'CIA_11', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「完美的社交包裝師」。擅長透過塑造樂觀形象來獲得認可，實則行為充滿目的性。其測評結果可能存在高度偽飾，需多方查核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2577, 'CIA_12', 'A (高)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「純粹的修煉者」。比起加薪，更看重學習機會與自我實現。管理建議：應提供具挑戰性的專案或進修機會作為主要獎酬。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2578, 'CIA_12', 'A (高)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「使命感驅動者」。對工作充滿熱愛且不計酬勞多寡。預測：在組織面臨寒冬或薪資凍結時，這類員工的留任意願最高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2579, 'CIA_12', 'A (高)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「無私的貢獻者」。願意為了團隊共榮而放棄個人獎金或特權。預測：是建立高凝聚力文化的核心成員。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2580, 'CIA_12', 'A (高)', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「淡泊名利的隱士」。既不追求財富也不渴求他人尊重，這類人極難被外在名利收買，適合擔任高度保密或敏感職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2581, 'CIA_12', 'B (中)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) 高分聯動：表現為「為意義升級的務實學習者」。他會主動找機會學新方法、推進自己，不太需要別人推一把；挑新工作或新技能時，先問的是這件事能不能讓自己更好，薪水或頭銜是否跟得上放在後面考量。但遇到需要額外投入時間或資源的成長機會，他仍會算一下生活需求撐不撐得住，這筆帳算不過去時，他會放慢腳步或縮小投入範圍。管理上可用有意義的挑戰與學習內容吸引他投入，同時留意基本回報別讓他長期墊底，否則再有企圖心也會在現實壓力下卡住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2582, 'CIA_12', 'B (中)', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) 低分聯動：表現為「把工作當責任收著做的人」。他對工作本身沒有太多熱情，多半用責任或收入的角度看待這份差事，投入度隨外部要求走；但他也不是為了錢拚命衝，達到該有的水準、拿到合理報酬，他就滿足，不會額外去追逐更高的物質回報來彌補動力不足。日子久了，這種狀態容易變成兩頭都平淡：既不特別有勁，也不特別在意能多賺多少。管理上與其用加薪催動能，不如先確認任務本身有沒有給他基本的意義感，物質誘因對他效果有限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2583, 'CIA_12', 'B (中)', 'CIA_25', 'A', '與 CIA_25 (集體意識) 高分聯動：表現為「願意讓利成全團隊的人」。他重視團隊的凝聚力與共同目標，遇到資源分配的場合傾向先想整體能不能運作順利，自己少拿一點、多扛一點責任都能接受。他仍會留意付出與生活需求是否大致平衡，只是碰到團隊需要有人先讓一步時，他多半就是先做出讓步的那個人。長期若團隊持續佔他便宜、回報始終跟不上,他的配合意願仍會慢慢磨損。管理上可放心讓他承擔協調角色，但仍要記得適度回饋,別把他的讓步當成理所當然。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2584, 'CIA_12', 'B (中)', 'CIA_14', 'C', '與 CIA_14 (謙虛) 低分聯動：表現為「在意被看見卻不追物質的人」。他傾向強調自己的貢獻,希望努力被看見,對別人搶了風頭或成果被忽略會比較敏感;但這股在意的核心是地位與認可,不是財富——他不會為了多拿一點錢去爭,卻可能為了頭銜、掛名或誰在報告裡被提到而計較。金錢方面他仍照生活需求與合理回報去衡量,不會被物質誘因牽著走,反而是「有沒有被承認」這件事更容易牽動他的情緒。管理上給予公開肯定與適當曝光,比加碼獎金更能穩住他的投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2585, 'CIA_12', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「為成果拚而非為錢拚的人」。他對表現與成果有明顯企圖心,願意多投入時間心力把事情做到更高標準,遇到困難的挑戰會主動想辦法升級做法、拉高目標,這股拚勁的來源是把事情做好本身帶來的成就感。同時他對物質回報保持務實態度——會期待付出與所得大致相稱,但不會把加薪或獎金當成推自己更拚的主要理由,回報不到位時他頂多略感失落,不至於因此收手。管理上可放心用高難度任務與清楚的成長路徑吸引他,不必依賴頻繁的物質激勵來維持他的投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2586, 'CIA_12', 'B (中)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) 低分聯動：表現為「價值底線鬆動時仍算合理帳的人」。他在利益與地位面前自我要求較弱,遇到能先拿到好處的機會,容易找理由讓自己心安理得地行動,對公平與謙遜的堅持不算穩固;但這不代表他被物質完全主導——他仍會在心裡算一筆帳,拿的是不是符合實際付出與生活需要,而不是來者不拒、多多益善。換句話說,他的鬆動出現在「要不要先拿」的判斷上,而不是「拿多少才夠」的胃口上,後者他仍有一套務實的衡量標準。管理上需要明確的規則與監督來補他判斷上的鬆動,同時他對合理回報的敏感度,也可以是設計誘因結構時的施力點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2587, 'CIA_12', 'B (中)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：表現為「守住公平手段又不逐物質的人」。即使有機會領先或達成目標,他仍傾向拒絕欺騙、佔便宜或犧牲他人利益的手段,重視對等與規則一致,不會為了搶快而破格。這份底線跟他對物質的態度相互印證——他本來就不把財富地位當首要追求,遇到取捨會照生活需求與合理回報做衡量,不容易被誘因牽著走,所以在誠信與利益衝突的場合,他更少感到猶豫,決定也做得比較快、比較穩。管理上可放心把牽涉公平分配或敏感資源的事務交給他,他的判斷通常經得起檢驗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2588, 'CIA_12', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目標明確的掠奪者」。其成就動機源於對財富與地位的渴望。管理警示：只要有更高薪的對手招手，離職風險極高，需建立績效獎金掛鉤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2589, 'CIA_12', 'C (低)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「貪婪的職場投機者」。高度重視利益且可能忽視倫理。警示：是職場舞弊、收受回扣的高風險群組，需建立嚴格的財務審核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2590, 'CIA_12', 'C (低)', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「利益至上的不公者」。為了獲取個人物質優勢，不惜破壞組織公平規則。風險預測：極易為了私利而損害團隊或客戶利益。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2591, 'CIA_12', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「特權索求者」。認為自己應享有最高薪資與專屬待遇。管理警示：若組織無法給予「優越感」，其工作動能會迅速崩潰且產生負面抱怨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2592, 'CIA_12', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「高度現實的勞動者」。對每一分付出的金錢回報都斤斤計較。管理預測：是標準的「金錢驅動型」，管理方式應簡單直接，以獎金說話。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2593, 'CIA_12', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「職場鍍金者」。為了塑造成功形象（高社會地位）而過度包裝自己。警示：其表面展現的價值觀可能與內在逐利心態不符，需長期觀察。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2594, 'CIA_13', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「正道成功者」。對成功有渴望但絕不跨越道德底線。預測：其成就具備極高的透明度與可複製性，是組織內部良性競爭的標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2595, 'CIA_13', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「失控但正直者」。雖然行為魯莽易出錯，但出發點通常是誠實的，不會為了掩蓋錯誤而撒謊。管理建議：應包容其無心之過，引導其修正行為而非懲罰其動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2596, 'CIA_13', 'A (高)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「廉潔守護神」。具備極高的道德標準且不貪婪。預測：極其適合擔任高價值資產管理、法務、稽核或涉及高度信任的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2597, 'CIA_13', 'A (高)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「體制公平的捍衛者」。不僅要求自己公正，也極度在意組織的公平。管理警示：若組織出現不公平競爭，他會是第一個站出來發聲或選擇離職的人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2598, 'CIA_13', 'A (高)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「剛正不阿者」。不在乎社交形象，即使在同儕壓力下也會堅持說出真相，是預防集體作惡的關鍵防線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2599, 'CIA_13', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「求勝但守底線的進取者」。他對表現與成果有明顯企圖心，遇到挑戰會主動升級方法、加大投入來換取更高標準。公平規則多半願意遵守，但當競爭拉到很緊、達標壓力逼近臨界點時，會開始評估某些擦邊球做法能不能換來領先，行為隨環境對此的容忍度而調整。同一個場合換個氛圍，他過不過線的判斷就會跟著變：容忍度高的場合他敢往邊界靠，管得嚴的場合他就收得住。管理上宜在高強度目標任務中明確畫出不可退讓的底線，並讓進度與方法一起被檢視，避免只看結果不看手段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2600, 'CIA_13', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「壓力下界線鬆動的衝動者」。平常他大致遵守公平規則，會顧慮對等與一致性，但容易被情緒推著走，遇到挫折或被逼急時可能先衝動回應、倉促承諾，事後才回頭修補。這兩種狀態疊在同一個時刻最危險：情緒被點燃的當下,原本會權衡的公平判斷來不及介入,一句話說重了、一個承諾開得太快,已經逾越了原本能接受的邊界。事後他多半意識得到、也願意解釋補救，但當場攔不住自己。管理上宜在高壓或衝突情境提前給緩衝與冷靜的空間，避免讓他在情緒最高點做出承諾或決策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2601, 'CIA_13', 'B (中)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) 高分聯動：表現為「有原則但仍會權衡的公平者」。即使目標或利益清楚擺在眼前，他也不會因此去炫耀、爭地位或佔便宜，對財富特權沒有過度執著。公平規則他大多願意守,但在強烈競爭或業績逼近死線時,會出現一種擦邊球的心態,開始盤算哪些做法在當下環境是被容忍的。這種權衡不是為了圖利自己的物質或地位,而更像是「這次能不能通融」的臨場判斷,通融過後他通常還是回到原本的節制與公正基準,不會把偶一為之當成常態。管理上可放心讓他自主判斷灰色地帶,但目標壓力大時,適時提醒規則的邊界仍有幫助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2602, 'CIA_13', 'B (中)', 'CIA_27', 'C', '與 CIA_27 (權益公平感) 低分聯動：表現為「在意吃虧的規則權衡者」。他對公平規則大致願意遵守，但對付出與回報是否對等相當敏感，容易留意自己是不是吃虧。若他感覺遊戲規則本身已經對自己不利，原本願意守的擦邊球界線會鬆動——他可能開始覺得既然對等被打破，自己稍微彈性一點也算合理。競爭壓力大、又覺得不划算的場合最容易鬆手，投入也可能轉趨保守，只做剛好夠交代的部分。管理上宜讓回報機制透明可見、讓他清楚知道付出會被公平計算，能降低他把規則彈性化的動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2603, 'CIA_13', 'B (中)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) 高分聯動：表現為「看場合修飾但底線會鬆動的人」。他明顯傾向用讓人觀感良好的方式回應，遇到敏感問題時容易把自己的想法或答案往理想化調整，以取得認可。公平規則他大多願意遵守，但當競爭壓力升高、又想維持一貫的正面形象時，可能悄悄把自己實際做的擦邊球行為淡化描述，讓外界看到的版本比實際更乾淨。問起細節時他傾向給概括、正向的說法帶過，避免具體描述容易顯得不好看的那一步。管理上宜多看實際行為紀錄而非自陳說法，遇到利益衝突情境時，具體詢問細節會比接受概括性保證更可靠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2604, 'CIA_13', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先衝了才回頭補評估的人」。他做事傾向先做再說，風險與後果的評估常常是行動之後才補上，在快節奏場合能衝得動，但也容易漏看隱性風險。公平規則他大致願意守，可是這種先做後想的習慣,遇到競爭壓力大、時間又緊的場合特別危險——他可能已經用了某個擦邊球做法把事情推進去，是做完之後才意識到那步踩線了。有沒有踩線,常常不是他當下判斷出來的,而是事後回頭看才發現。管理上宜在牽涉利益或規則邊界的任務,設一道行動前的檢查點,逼他在動手前先過一次評估,能有效攔住這種先做後悔的落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2605, 'CIA_13', 'B (中)', 'CIA_11', 'A', '與 CIA_11 (誠懇) 高分聯動：表現為「誠懇待人但仍會權衡手段的人」。他跟人溝通時偏直接透明，不太會為了達成目的去操縱或欺騙別人，傾向用真實資訊建立合作。公平規則他大多願意守，但當競爭拉到很緊、目標壓力逼近臨界點時，仍可能出現一種擦邊球心態，開始評估某些做法在當下環境能不能被接受。這種權衡幾乎只發生在規則與資源分配這類抽象層面，不會延伸成他對人耍手段或說謊——他對人依然坦誠，鬆動的是「守不守某條規定」，不是「騙不騙眼前的人」。管理上可以放心讓他處理需要信任的溝通，同時在資源分配或競爭規則上多一層覆核，能補上他這塊的波動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2606, 'CIA_13', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「不擇手段的擴張者」。為了達成業績或領先同儕，會利用資訊不對稱或規則漏洞。管理風險：高業績可能掩蓋其合規風險，需加強第三方稽核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2607, 'CIA_13', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的投機家」。其不誠實行為通常經過精心佈局，難以察覺。警示：是高階商業犯罪潛在對象，需建立分權制衡機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2608, 'CIA_13', 'C (低)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場慣竊或投機者」。管不住慾望且缺乏公正底線。行為預測：容易出現偷工減料、虛報開支或侵占公物等低階舞弊行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2609, 'CIA_13', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「偽裝的利用家」。透過操縱手段獲取他人信任後再進行剝削。風險預測：在團隊中容易造成信任感瓦解，是組織文化中的「劇毒」成分。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2610, 'CIA_13', 'C (低)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「走捷徑的高效能」。為了快而省去必要的安全或倫理程序。管理警示：雖能快速達標，但可能留下巨大的法律或安全後患。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2611, 'CIA_13', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「貪婪的特權者」。認為自己的「特殊」地位應換取超越規則的利益，且不會對利用他人感到愧疚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2612, 'CIA_13', 'C (低)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「熱情的利己者」。雖熱愛工作，但其動機可能源於工作帶來的灰色利益獲取機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2613, 'CIA_14', 'A (高)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「內斂的高手」。具備極強能力卻不張揚。預測：在團隊中極受尊敬且具備高影響力，是理想的導師（Mentor）型人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2614, 'CIA_14', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「僕人式領導」。真心平視他人並感同身受。預測：能創造極高的心理安全感，非常適合帶領高知識產能或需要創意協作的團隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2615, 'CIA_14', 'A (高)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「低調的協調者」。能身處不同階層而不顯突兀。管理建議：在跨部門溝通中具備極強的潤滑作用，能有效降低組織摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2616, 'CIA_14', 'A (高)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「終身學習者」。因謙虛而自覺不足，能持續吸收新知。管理預測：具備極佳的受教性（Coachability），是組織持續進化的核心力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2617, 'CIA_14', 'B (中)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) 高分聯動：表現為「低調的能手」。他對自己能不能把事情做好心裡有數，遇到挑戰願意接手、也相信自己找得到辦法，但講到自己做了什麼、貢獻多少，話會收得比較短。被直接問起成果時他常先想到還有哪裡可以更好，而不是直接把功勞攬過來講清楚。需要爭取資源或在會議上為自己的方案發聲時，他容易卡在「講太多會不會顯得在邀功」，拿捏分寸的過程比實際內容還花時間。管理上可以主動幫他把具體貢獻攤開來說、替他起頭，讓他不用自己開口也能被看見。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2618, 'CIA_14', 'B (中)', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「安靜但後知後覺的協作者」。他不太主動搶功、也不會刻意壓過別人，日常互動偏向就事論事，比較少去留意旁人這時候是想被稱讚還是需要被安慰。這種安靜有時被誤讀成謙讓，其實只是他沒特別注意到當下的人際訊號。等到有人明講「你這樣讓我不太舒服」，他才會意識到自己講話或分配功勞的方式漏掉了什麼，事後補上調整。爭取資源或發言時他仍會猶豫分寸，但那份猶豫較少是顧慮他人感受，更多是單純不確定自己該說多少。管理上宜給他清楚的回饋而非期待他自己讀出弦外之音，也可提醒他留意場合裡誰需要被肯定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2619, 'CIA_14', 'B (中)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) 高分聯動：表現為「不搶戲的橋樑」。他能跟風格差很大的人都合作得下去，懂得順著不同節奏調整自己的說法、緩和場面裡的張力，但這份彈性用在自己身上卻常變成往後站——有人搶話或攬功時，他傾向先讓一步、維持場面和諧。需要為自己爭取發言權或資源的時候，他能感覺到自己在收著，卻不一定馬上調整過來，得先在心裡衡量一下才敢把話說滿。跨部門或跨風格的場合裡，他常是那個把不同的人湊在一起做成事的人，自己的貢獻卻容易被併進團隊成果裡、沒被單獨看見。管理上可以在合作促成後主動點名他的角色，幫他把這份貢獻具體講出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2620, 'CIA_14', 'B (中)', 'CIA_31', 'C', '與 CIA_31 (個人成長動機) 低分聯動：表現為「夠用就好的低調者」。他不太主動找機會突顯自己，也沒有很強的動力去追加新技能或挑戰更高難度的任務，傾向用現有的能力把事情完成就好。在團隊裡他顯得非常安靜——既不搶著爭取被看見，也不主動升級自己去搏更多機會，久而久之存在感容易被稀釋。有人明確引導、給出成長路徑時他會願意跟進，但若沒人推一把，他就停在原地，連「該為自己爭取一點什麼」的念頭都不太會浮現。管理上需要主動幫他框出下一步、也主動幫他爭取曝光機會，兩件事都得由外部啟動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2621, 'CIA_14', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「把光環讓給結果的衝刺者」。他對把事情做出更高水準有明顯企圖心，遇到挑戰會主動加碼投入、升級做法，追求成果這件事上一點都不含蓄。但把力氣拿去談自己做到了什麼、值得什麼位置或資源時，他明顯縮回去，常常是把整個團隊的成果講在前面，自己的角色一筆帶過。這種落差在被問到「這案子你的貢獻是什麼」時特別明顯——他能滔滔不絕講方法跟過程，講到自己時反而語塞或簡化。管理上可以直接把他在成果裡的具體角色攤開來確認，而不是等他自己主動陳述。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2622, 'CIA_14', 'B (中)', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「話術包裝但不搶功的操作者」。他為了把事情推向想要的結果，願意用比較策略性、甚至帶點包裝的方式說話，選擇性強調對自己有利的資訊。但這份策略性很少用在幫自己爭取名聲或位置上——講到自己的貢獻和該得的認可時，他反而拿不太出那種操作的手腕，話說得保留，該爭取的沒爭取到。也就是說他懂得怎麼包裝一件事去說服別人接受方案，卻不太懂得包裝自己去說服別人肯定他。管理上可以留意這種落差，主動確認資源分配是否合理反映他實際的操作與貢獻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2623, 'CIA_14', 'B (中)', 'CIA_15', 'A', '與 CIA_15 (心理資本) 高分聯動：表現為「帶著底氣卻不張揚的人」。他面對挑戰能維持動能與信心，把挫折當成可以處理的問題，就算連續碰壁也不至於一蹶不振。但這份底氣沒有轉成外顯的自我展示——他心裡清楚自己做得到、也相信自己有價值，講出口時仍然收著，不太會主動把自己的信心說給別人聽。碰到需要為自己爭取機會或發聲的場合，他能穩住不退縮，卻仍拿不準該把話說滿到什麼程度、把功勞講清楚到什麼份上，中間仍有一段要拿捏。管理上可以放心把有挑戰性的任務交給他，同時主動幫他把這份底氣轉譯成讓別人看得到的具體說法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2624, 'CIA_14', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「狂妄的野心家」。成功後傾向於擴張自我，排斥他人功勞。警示：容易造成「一將功成萬骨枯」的情形，需注意優秀部屬的流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2625, 'CIA_14', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「權勢型操縱者」。自視甚高且擅長權術。風險預測：會利用職位或資訊不對稱來打壓異己，對組織文化透明度有強烈破壞性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2626, 'CIA_14', 'C (低)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「過度自負的樂觀」。相信自己無所不能且未來必勝。警示：容易忽略客觀風險警訊，導致組織在重大決策上出現盲目的毀滅性策略。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2627, 'CIA_14', 'C (低)', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「虛飾的名利徒」。為了維持高人一等的形象而不斷包裝或誇大事實。行為預測：在面對錯誤時會全力推諉，以保護其自傲的形象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2628, 'CIA_14', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場獨裁傾向者」。自認優越且理應享有特權。管理警示：會強烈要求特殊化管理，破壞組織的制度統一性，挑戰管理權威。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2629, 'CIA_14', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「偽裝的菁英」。內心傲慢但外在包裝得很得體。警示：這種「隱性傲慢」會在長期合作或高壓下暴露，需注意其對團隊長期信任的損害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2630, 'CIA_14', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「自尊極度敏感者」。因自視甚高，任何輕微的指正或異議都會被其視為嚴重的冒犯，引發劇烈的情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2631, 'CIA_15', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「無敵的開路者」。具備強大成功慾望且擁有充足心理資源支持。預測：面對高難度挑戰時不會輕言放棄，是組織推動艱鉅任務的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2632, 'CIA_15', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「務實的樂觀主義者」。既對未來抱持正向期待，又能冷靜分析潛在風險。預測：能制定出具備激勵性且紮實可行的計畫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2633, 'CIA_15', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「韌性十足的變革者」。創新過程中失敗率極高，高心理資本提供了失敗後的快速復原力。預測：能帶領團隊在反覆試錯中找到新路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2634, 'CIA_15', 'A (高)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「正向能量傳播者」。能以自身的樂觀與韌性感染團隊，在逆境中穩定軍心。管理建議：適合作為組織文化大使或危機應變核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2635, 'CIA_15', 'A (高)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「天生贏家型員工」。對工作充滿熱情且心態極其健康，離職風險與燃盡風險極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2636, 'CIA_15', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「被看見進展就衝的進取者」。他對表現與成果有明顯企圖心，願意多投入去達到更高標準、遇挑戰主動升級方法；但這股企圖心是否能一路撐下去，要看當下有沒有支持與看得見的進展。目標清楚、有人肯定時，他會把難度往上加、主動找更好的做法。一旦卡關卡久、看不到回饋，動能會先鬆下來，但企圖心本身沒消失，重新看見一點進展就會很快把節奏拉回來。管理上宜定期讓他看到具體進展與肯定，避免長時間無回饋空轉，才能穩定接住他的高投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2637, 'CIA_15', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先衝再修的樂觀行動派」。他傾向先做再調整，評估常在動手之後才補齊，快節奏場合能衝得動、也敢往前推進；這份敢衝背後帶著一種相信情況會好轉的底氣，一旦事情走偏，他不容易被打趴，會把出錯當成能修正的插曲繼續往下走。但這份底氣不是隨時都在：連續踩雷或長時間沒人接住時，他也會有一陣子提不起勁去收拾殘局，等看到一點轉機才又重新動起來。管理上宜在他快速行動後補上檢核與提醒風險的機制，同時在連續受挫時給予具體的支持與方向,幫他把動能接回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2638, 'CIA_15', 'B (中)', 'CIA_20', 'A', '與 CIA_20 (創新力) 高分聯動：表現為「看到轉機就敢換路走的挑戰者」。他喜歡用新方法做事，會主動發現問題、提出替代解法,不容易被既有慣例困住；這股嘗試新路的動力平常能撐著他去試不同做法，遇到不確定也敢先動手看看效果。但長期壓力或連續碰壁久了,這股動能會先降下來,嘗試新解法的意願跟著變保守,傾向先守住現況；等到有人給支持或看到一點成果的苗頭,他又會重新願意冒險換個角度做。管理上宜在他嘗試新方法卡關時提供具體支持與階段性回饋,讓突破的動能有機會延續而不斷在原地熄火。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2639, 'CIA_15', 'B (中)', 'CIA_25', 'C', '與 CIA_25 (集體意識) 低分聯動：表現為「順風時個人優先的樂觀行動者」。他更重視個人目標與自主性,對集體要求的投入度不高,遇事習慣先從自己的節奏和利益出發去安排怎麼做；這種以自己為主的行動力,在有支持、能看見成果時能撐出不錯的推進速度與正向態度。長期壓力或連續受挫時,這份積極會先垮下來,他容易變得提不起勁,對事情能不能好轉也失去把握，這時他更不會主動去顧全大局,只想先顧好自己能掌握的部分。管理上宜提供清楚的個人目標與具體回饋,幫他在低潮時重新找到施力點,而不是期待他在無支持狀態下還能兼顧整體。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2640, 'CIA_15', 'B (中)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) 高分聯動：表現為「被氛圍點燃的投入型行動者」。他對工作本身有明顯熱情與投入,願意多付出去追求成果與成長,能量平常算充足;但這股能量能不能一直維持,跟他當下有沒有被支持、有沒有看到事情在往前走很有關係。氛圍對、有進展時,他會把這份熱情用得很足,主動多做一點、多想一步。長期高壓或連續碰壁一陣子後,熱情會先降溫,變得比較像在完成份內的事;一旦重新看到一點轉機或得到肯定,他又會很快把投入感找回來。管理上宜留意他的能量週期,在低潮期主動給予看得見的回饋與支持,避免長時間沒人接住讓熱情持續下滑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2641, 'CIA_15', 'B (中)', 'CIA_01', 'C', '與 CIA_01 (盡責) 低分聯動：表現為「情境撐得住才穩的樂觀執行者」。他較容易受情境或情緒影響而出現拖延、鬆散或收尾不足,不是做不到,而是自我監控與維持節奏本身就比較吃力；當下有支持、事情看得到進展時,他還能保有一份相信情況會變好的底氣,願意撐著把進度往前推一點。一旦長期缺乏回饋或連續卡關,這份底氣會先鬆掉,原本就不太穩的節奏更容易整個掉下來、收尾更難完成。管理上宜提供具體的進度檢核與階段性肯定,幫他在維持節奏本來就吃力的狀態下,還能靠外部支持把動能接住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2746, 'CIA_21', 'A (高)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「快樂的生產者」。對優化流程充滿熱情。預測：具備極強的抗燃盡能力，因為他們總能找到更輕鬆且高效的方式完成工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2642, 'CIA_15', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「有底氣時願意反覆打磨的人」。他對細節與品質要求高,會反覆檢查與優化以追求無瑕疵,這份講究平常能把可靠度撐得不錯;但願不願意持續花這份心力去磨,要看他當下有沒有支持、看不看得到成果在累積。狀態好時,他會願意多花一輪把東西修到更好,相信這些努力值得。長期壓力大或看不到回饋時,這份講究的動能會先降下來,可能開始縮短檢查的輪次、標準跟著鬆動；等重新得到肯定或看到一點成效,他又會把打磨的耐心找回來。管理上宜在高標準任務中適時給予進度回饋與支持,避免他在無回饋狀態下把品質要求連帶一起放掉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2643, 'CIA_15', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的耕耘者」。雖極其努力工作，但內心缺乏支撐資源。警示：一旦遇到無法控制的挫折，極易陷入自我否定，需高度關注其心理健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2644, 'CIA_15', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「崩潰邊緣的完美者」。追求完美但心理資源不足以承載失敗。風險預測：只要成果有一點瑕疵，其崩潰感會比一般人強烈數倍，易出現逃避行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2645, 'CIA_15', 'C (低)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「清高的受害者」。堅持正直但在不公環境中缺乏韌性與樂觀。預測：容易因職場政治感到灰心喪志，轉向消極應對。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2646, 'CIA_15', 'C (低)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「苦命的承擔者」。責任感強迫其接下工作，但內心深感無力與悲觀。警示：是「職場過勞」的高風險群組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2647, 'CIA_15', 'C (低)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「渴望成長但自卑者」。想變好但總擔心自己做不到。管理建議：需提供明確的成長路徑與頻繁的小成功（Small Wins）來補足信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2648, 'CIA_15', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易碎的火藥桶」。對逆境耐受力差且易被激怒。風險預測：在壓力下不僅容易放棄，還會伴隨激烈的情緒宣洩，對團隊穩定性極大傷害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2649, 'CIA_16', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「目標導向的戰略家」。不僅想把事做對（盡責），且腦中總有多套達成目標的路徑。預測：在遇到阻礙時會迅速切換執行策略，而非死守一條死路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2650, 'CIA_16', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「周密的夢想家」。具備宏大的目標動機，但每一步都經過精確計算。管理預測：能提出既具備野心又能避開風險的長遠計畫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2651, 'CIA_16', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「急躁的開拓者」。對達成目標充滿渴望與策略，但執行時易因情緒波動而偏離軌道。管理警示：雖有點子且想贏，但需他人協助維持執行節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2652, 'CIA_16', 'A (高)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「正派的願景家」。其規劃的達成路徑完全符合倫理，不屑於透過損人利己的方式達成目標，是組織誠信文化的好榜樣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2653, 'CIA_16', 'A (高)', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「不屈的導航員」。遭遇重大挫折（韌性）後，能迅速產生新的目標動機與執行方案（希望）。預測：是組織度過經營危機的靈魂人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2654, 'CIA_16', 'A (高)', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「創新的策略師」。善於用非傳統的方法達成目標，能看見別人看不見的替代方案。預測：適合解決結構性難題或處理複雜的商業併購。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2655, 'CIA_16', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「鼓舞人心的領導者」。不僅自己有希望，還能站在他人立場設計出讓團隊成員都有共鳴的達成路徑，大幅提升團隊動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2656, 'CIA_16', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「按表操課的重新定向者」。他對眼前工作的自我要求穩定，進度、品質與收尾多半不用人催促就能顧好。但當通往目標的路徑本身卡關、原本做法走不通時，他仍準時把手上該做的部分交出來，只是心裡對「下一步該往哪走」感到含糊，得先把方向重新對齊過才推得動。方向一旦重新確立，他又能把那份自律投入新路徑、持續往前推進。管理上適合定期檢視目標路徑是否仍可行，趁他還維持穩定輸出時，及早補上策略層的方向引導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2657, 'CIA_16', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先衝再校準的追目標者」。他對目標抱有動機，一旦既定做法卡住，不太會停下來把新路徑想清楚才動，而是先換個方式衝出去、邊做邊看結果再修正。這種先衝的節奏下，他一邊很快脫離原本卡住的狀態、重新有事可做，一邊也容易在還沒把新路想透時就一頭栽進去，撞上原本能避開的風險。真正比較穩妥的走法，往往要等方向被重新指出才會浮現，屆時他又能把那股急著動起來的勁道用在對的地方上。管理上宜在他卡關初期就給明確方向，讓他的行動力用在對的路上，避免摸索期間累積不必要的返工。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2658, 'CIA_16', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「卡關也不亂了陣腳的等待者」。當通往目標的路徑走不通、一時看不出下一步時，他不會因此煩躁到亂丟決定或臨時改變承諾，情緒與行為仍維持一致。他會先把手上還能做的部分穩住，等方向重新釐清後再全力推進，不因等待拉長就做出衝動取捨。這段卡關期在他身上比較安靜，較少出現因情緒堆積而衝動收場的狀況。管理上可以放心讓他在方向未明時先按兵不動，重點是儘快把路徑釐清，不必擔心他會卡住就衝動行事。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2659, 'CIA_16', 'B (中)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) 低分聯動：表現為「卡關先佔位的推進者」。當原本通往目標的做法卡住、一時想不出下一步時，他容易被能盡快拿到成果、被人看見的做法吸引，即使那條路不是最站得住腳的方式，也會先做了再找理由圓過去。比起花時間把公平合理的路徑想清楚，他更傾向選一個能盡快脫離卡關、順便換到一點好處或存在感的方向；等真正有效的路徑被重新指出，這種先搶先贏的傾向才會跟著降溫，動機也回到把目標穩穩推進本身。管理上宜在他卡關時盡快給出明確且站得住腳的路徑，減少他自行找捷徑、事後才圓說法的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2660, 'CIA_16', 'B (中)', 'CIA_18', 'A', '與 CIA_18 (韌性) 高分聯動：表現為「卡關快速翻頁的推進者」。原本規劃的路徑走不通時，他會有一段對下一步含糊的空白，但這段空白通常拉得不長——他很快回到可以做事的狀態，把剛卡住的經驗轉成下一次嘗試的修正材料，不太會停留在懊惱裡。方法卡關後的空窗期在他身上通常不長，只要新方向一被對齊，他幾乎能立刻接上動能繼續走。管理上可以趁他剛從卡關中回穩時盡快提供路徑調整的建議，他通常能很快吸收並轉為行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2661, 'CIA_16', 'B (中)', 'CIA_23', 'C', '與 CIA_23 (獨創性) 低分聯動：表現為「照著路標找路的推進者」。原本的做法卡關時，他不太會自己想出一條前所未有的新路子，而是在腦中翻找有沒有類似情境用過、驗證過的既定做法可以套用，重視走不走得通勝過新不新。他一邊帶著想達成目標的動機，一邊在缺乏現成參照時容易卡住不動，直到有具體且落在熟悉範圍內的路徑被指出來才願意動起來，之後便踏實照著推進。管理上宜在他卡關時直接提供具體可依循的步驟或前例，而不是丟給他一片空白要他自創路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2662, 'CIA_16', 'B (中)', 'CIA_26', 'A', '與 CIA_26 (同理心) 高分聯動：表現為「卡關也讀得懂旁人的推進者」。原本的路徑卡住、他自己還沒想清楚下一步時，他仍能感受到周遭的人在等什麼、擔心什麼，回應語氣會照著旁人的處境調整，不會因為自己卡關就變得生硬或不耐煩。他一邊帶著想推進目標的動機、一邊對下一步感到含糊，卻仍留意著旁人的感受與立場，把「還沒想清楚」講得清楚明白，不至於引發不必要的擔心。方向一旦被重新指出，他也比較容易聽懂建議背後的考量，把它吸收成自己能走的下一步，而不是被動接受或表面應付。管理上可以直接跟他說明卡關的判斷與理由，他通常能理解並據此調整，不需要包裝太多。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2663, 'CIA_16', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「盲目的攀登者」。極想成功（成就動機）但缺乏達成目標的路徑規劃能力（低希望）。管理警示：容易像無頭蒼蠅般瞎忙，需主管協助給予明確的操作指引。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2664, 'CIA_16', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「絕望的苛求者」。對結果要求完美，但對「如何達成」缺乏信心。風險預測：常因看不見完美的達成路徑而陷入極度悲觀，並出現嚴重拖延。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2665, 'CIA_16', 'C (低)', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「習得性無助的典型」。對未來不抱期待，也不相信自己能找到出路。管理警示：動能完全熄火，若持續在高壓職位，極易引發嚴重的心理健康問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2666, 'CIA_16', 'C (低)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「空有願望的成長者」。想變好但找不到具體方法。管理建議：應提供結構化的培訓與導師指導（Mentorship），幫他畫出成長路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2667, 'CIA_17', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「強效執行者」。具備極高的達成信心且配合嚴明的紀律。預測：對承諾的目標有極高的達成率，且過程穩定不需督促。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2668, 'CIA_17', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「深思熟慮的自信者」。其信心建立在充分的準備與分析之上，而非盲目自信。預測：能承擔高風險決策，因為他已看清路徑並相信自己能控場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2669, 'CIA_17', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「過度擴張的冒險家」。相信自己能搞定一切但行為容易失控。警示：容易承諾超過自身負荷的任務，需主管協助控管承諾邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2670, 'CIA_17', 'A (高)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「信念堅定的專家」。對能力（08）與努力達成目標（17）都有極高信心。預測：展現出強大的氣場與說服力，適合帶領變革或開拓性任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2671, 'CIA_17', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性自信者」。在順境中信心爆棚，但一旦努力後仍失敗，自信會迅速崩塌。管理建議：需在失敗初期即時介入，防止其陷入自我懷疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2672, 'CIA_17', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「敢於突破的發明者」。相信非傳統的方法可行且自己能推動它。預測：能打破僵化的 SOP，透過創新的手段達成他人認為不可能的目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2673, 'CIA_17', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「傲慢的精英」。相信自己能力出眾且理應獲得特殊回報。警示：容易低估團隊貢獻，認為成功全是個人努力的結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2674, 'CIA_17', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「強勢的專家」。對自己極度自信，因此對「不專業」或「進度慢」的同事容忍度極低，易因恨鐵不成鋼而爆發脾氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2675, 'CIA_17', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「確認方向後穩定收尾的執行者」。面對新領域或高風險任務，他會先花時間確認方向與標準，不急著在不確定中硬衝；但一旦方向拍板，他能主動掌握進度、顧好品質並把收尾做完整，很少需要外部催促。他在陌生任務初期的節奏偏慢，卡在「還沒確認清楚」的階段，一旦跨過這關，產出速度與穩定度會明顯提升。管理上宜在任務初期給清楚的標準與範圍，讓他能盡快從確認期切換到穩定輸出期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2676, 'CIA_17', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「邊衝邊校準的行動者」。在熟悉、步調快的任務上，他習慣先做再說，把評估留到動手之後才補齊，仍能維持衝刺速度；但換到新領域或明顯高風險的任務，他會先停下來確認方向與標準，不敢貿然照原本的節奏衝。標準還沒確認清楚時，他容易在「想快點動手」與「怕方向錯」之間拉扯，行動被拖慢；一旦標準到位，他又能快速切回衝刺模式，把先前累積的動能一次釋放。管理上宜針對高風險項目提前把標準講清楚，減少他在確認期的空轉，也提醒他在快節奏任務中留一點事後複核的空間，降低隱性風險被忽略的機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2677, 'CIA_17', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「沉穩確認後再出手的人」。遇到新領域或高風險任務，他不會被「想趕快有結果」的急迫感牽著走，即使壓力升高，情緒與行為仍維持一致，不會因為一時心急就跳過確認方向這一步。他會把時間花在把標準與範圍問清楚，過程中即使遲遲拿不到明確答案，也能沉住氣繼續等、繼續問，而不是隨便先動手交差。一旦方向確立，他的輸出速度會穩定拉升，且不因為前面等待累積的壓力而做出倉促或高代價的決定。管理上可以放心把不確定性高的任務交給他，只要事先說明「確認清楚會需要一點時間」，不必擔心他在等待期做出情緒化的反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2678, 'CIA_17', 'B (中)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「先求安全感才敢推進的謹慎者」。面對新領域或高風險任務，他會想先確認方向與標準才好使力，同時也容易懷疑自己是不是真的能做好，起步前特別容易卡住。遇到不確定的狀況，他可能遲疑不決，甚至傾向把關鍵判斷交給他人拍板，而不是自己先給出方向。標準確立、也得到足夠的安全感與支持後，他能穩定把事情做出來，只是「準備好開始」的門檻偏高，不只是知道標準就夠。管理上除了把標準講清楚，還需要額外給予肯定與陪伴，讓他有足夠安全感踏出第一步。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2679, 'CIA_17', 'B (中)', 'CIA_18', 'A', '與 CIA_18 (韌性) 高分聯動：表現為「跌倒能快速歸隊的確認型行動者」。面對新領域或高風險任務，他仍會先花時間把方向與標準確認清楚，不會急著在資訊不足時貿然出手；但如果過程中真的踩雷、判斷失準或遭遇挫折，他能很快從打擊中回穩，把失誤轉成具體的修正動作，不會被卡住太久。他不太需要長時間的心理復原期，通常在確認新方向後就能重新投入，甚至比第一次起步時更快進入穩定輸出狀態。管理上即使任務前期需要花時間陪他確認標準，也不必過度擔心他一旦受挫就一蹶不振，他有能力把挫折轉成下一步的修正。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2680, 'CIA_17', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「等標準底定就照成熟做法穩定產出的人」。面對新領域或高風險任務，他會先確認方向與標準，確認過程中也傾向參考既有、成熟的做法，對全新、沒人試過的方法會先觀望，不急著自己開一條新路。標準一旦確立，他能穩定按照可行的既定方式把產出做出來，效率與品質都有一定保障，只是解法通常不會特別突破常規。遇到真的沒有前例可循的狀況，他確認方向所需要的時間會拉長，他更習慣有參照對象，而不是從零想新做法。管理上若能提供類似案例或既有範本作參考，會比要求他自己想出創新解法更快讓他進入穩定輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2681, 'CIA_17', 'B (中)', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「認為確認清楚是應得對待的人」。面對新領域或高風險任務，他會要求先把方向與標準講清楚才願意投入，而且傾向把這種確認視為自己應得的對待，不太覺得需要用實際努力或過去績效去換取這份說明。如果標準遲遲沒有講清楚、或者他覺得自己被要求在資訊不足下硬上，容易出現明顯不滿甚至對抗的反應，而不是自己想辦法先動起來。一旦方向確立、也感覺自己被妥善對待，他能穩定把產出做出來；但這份穩定明顯附帶條件——標準要清楚，而且他要覺得自己有被特別照顧到。管理上宜在任務初期主動說明方向與標準、給予明確的角色說明，減少他因覺得被冷落或條件不足而產生的抵觸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2682, 'CIA_17', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「焦慮的攀登者」。非常想成功（成就動機）但內心不信自己做得到。行為預測：工作中伴隨高度壓力與自我懷疑，需頻繁獲得成功經驗來補足信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2683, 'CIA_17', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「冒名頂替症候群」。要求無暇疵但深怕被看穿能力不足。風險預測：常因恐懼失敗而導致嚴重的任務拖延或過度準備（Over-preparing）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2684, 'CIA_17', 'C (低)', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「習得性無助者」。不相信未來會變好，也不相信自己有能力改變。管理警示：動能趨近於零，在變動環境中容易率先放棄，需透過小目標建立信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2685, 'CIA_17', 'C (低)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「求知若渴的學徒」。強烈想變好但現在沒信心。管理建議：是極佳的培訓對象，適合給予結構化的技能引導與正向回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2686, 'CIA_18', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「長線抗壓執行者」。即便計畫出錯，也能在修復情緒後迅速回歸紀律。預測：在高度不確定且高壓的專案中，產出品質最為持久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2687, 'CIA_18', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「愈挫愈勇的開拓者」。失敗被其視為達成最終成功的養分。預測：是組織進攻困難市場、開發新客戶時最穩定的先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2688, 'CIA_18', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「健康的完美主義」。追求高品質但能容忍過程中的挫折，並從瑕疵中學習。預測：具備極強的自我優化能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2689, 'CIA_18', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「無畏的實驗家」。創新即代表不斷失敗，高韌性確保其在實驗重重受阻時，仍能維持探索的動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2690, 'CIA_18', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「快速冷靜者」。雖然容易受到挫折激怒（易激度高），但能迅速從情緒中復原並重回理性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2691, 'CIA_18', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「扛壓仍守住收尾的自律型」。遇到壓力、逆境或連續受挫時，他會有明顯的影響，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，他對進度與收尾的自我要求並沒有跟著放鬆，工作依然照著節奏往前推、細節照樣顧到。旁人常常看不出他正在低潮，只看到產出持續交出、品質沒有明顯掉檔，直到低潮累積到一定程度，疲態才會顯出來。管理上宜主動關心他的實際負荷、及早提供釐清與支援，別等到他撐不住了才發現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2692, 'CIA_18', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「先求回穩、不搶高標的類型」。遇到壓力、逆境或連續受挫時，他會有明顯的影響，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，他對自己的要求也停在把事情做完、做到堪用即可，不太會主動把難度往上加或多做額外突破。他的動能高低比較跟著主管或環境的要求走：要求清楚、有人持續跟進時他會照著推進，一旦沒人特別要求，也容易停在剛好夠用的水準，不會自己再往上衝。管理上宜先把當下該做的範圍講清楚、給予明確回饋，並持續跟進，避免留白讓他自己停在低標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2693, 'CIA_18', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「低潮中仍不放過細節的類型」。遇到壓力、逆境或連續受挫時，他會有明顯的影響、動能往下掉，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，他對細節與品質的標準沒有跟著往下調，該反覆檢查、該修到位的步驟一樣不會省略。這段期間交出來的東西外觀上仍能維持一定的可靠度，只是這份堅持背後更耗時間與心力，恢復期常常拖得比預期久。管理上宜在他低潮期主動幫忙篩掉非必要的檢查項目，適度幫他抓一個「夠好就好」的停損點，並提供明確方向，把有限心力留給真正需要回穩的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2694, 'CIA_18', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「壓力期靠老方法穩住陣腳的類型」。遇到壓力、逆境或連續受挫時，他會有明顯的影響，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，他更傾向沿用熟悉、已經驗證過的做法把事情做完，遇到需要嘗試新方法的場合多半先觀望、不急著換一套沒把握的做法。他也少走一些不必要的彎路，只是遇到真正需要突破性做法的任務，能提供的新點子比平常更少。管理上宜在他低潮期盡量沿用他熟悉的流程與工具，避免同時要求他嘗試新方法，等狀態回穩後再視情況引入新做法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2695, 'CIA_18', 'B (中)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「壓力一來反應就先衝出去的類型」。遇到壓力、逆境或連續受挫時，他會被明顯拖住，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，反應的門檻會變得特別低，一點否定或不公平的刺激就可能讓他語氣先衝出去，甚至當場正面對抗。這段期間他也比較容易把力氣先花在當下的衝突或反駁上，要等情緒退下來，才有餘力回頭處理真正需要釐清、需要支持的事，整體恢復的時間偏長。管理上宜在他明顯低落的期間，先避免用否定或指責的方式溝通，改以具體、平和的方式把方向講清楚，減少不必要的刺激點，讓他有機會把心力放回真正需要回穩的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2696, 'CIA_18', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「壓力期容易先衝再收拾的類型」。遇到壓力、逆境或連續受挫時，他會有明顯的影響，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，他也比較容易被當下的情緒牽著走，出現衝動的回應、倉促答應一些原本沒把握的事，或是行為明顯過頭。事後他常常得花時間修補、跟人解釋，這些倉促的決定又要他額外花心力處理，回穩的路徑也跟著拖得更長更繞。管理上宜在他低潮期主動幫忙踩剎車、對重要承諾多一道確認，也留意善後與解釋是否造成他額外負擔，協助他把心力留在真正回穩需要的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2697, 'CIA_18', 'B (中)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) 高分聯動：表現為「低潮期仍相信自己扛得住的類型」。遇到壓力、逆境或連續受挫時，他會被明顯影響、狀態往下掉，需要獲得支持、把方向釐清後才能逐步回穩；同一段時間裡，他對自己有沒有能力把事情處理好仍抱持一定信心，遇到新的挑戰或不確定的任務多半願意先接下來、主動找方法，即使正處在低潮，也不太會退縮迴避。只是他也容易低估自己實際需要的恢復時間，把新任務接得比目前狀態能負荷的更多。管理上宜在他低潮期主動幫忙把關新任務的承接量、適度劃出界線，讓他能把恢復所需要的時間真正留給自己，而不是又被新的承擔擠壓掉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2698, 'CIA_18', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「易碎的樑柱」。做事盡責但抗壓性極差。警示：一旦遭遇重大失敗，其「盡責」會轉化為強烈的自我否定，需高度防範燃盡（Burnout）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2699, 'CIA_18', 'C (低)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「沉默的受難者」。雖能管住行為不爆發，但內心緩衝能力極低。管理風險：壓力會持續累積而非排解，易導致無預警離職。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2700, 'CIA_18', 'C (低)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「習得性無助者」。既不信自己有能力，也無法承受壓力。管理預測：在變動環境中會最先喪失功能，需安排在穩定、低壓職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2701, 'CIA_18', 'C (低)', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「悲觀的受災戶」。對未來不抱期待，且遭受打擊後一蹶不振。警示：會擴大團隊的負面氛圍，需注意其對士氣的殺傷力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2702, 'CIA_18', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「心碎的公平追求者」。對不公平現象極度在意，且一旦受到不公對待，修復心理創傷的速度極慢，易產生長期怨懟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2703, 'CIA_18', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「玻璃心的巨嬰」。認為應受特權對待，一旦被指責或遭遇普通挫折，會感到嚴重的心理受傷與憤怒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2704, 'CIA_19', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「務實的樂觀者」。對未來充滿期待，但每一步都經過精確計算以避險。預測：能提出具備野心且高度可行性的商業提案，不會盲目衝動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2705, 'CIA_19', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「進取的完美主義」。追求極致品質，且相信透過努力必能達成。管理建議：其正向心態能緩解完美主義帶來的焦慮，是高品質產出的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2706, 'CIA_19', 'A (高)', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「投機的冒險家」。相信「壞事不會發生在自己身上」，因此更敢於走捷徑或忽視規則。警示：高樂觀掩蓋了道德風險，需加強合規稽核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2707, 'CIA_19', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的傳教士」。相信創新必能改變現狀，且不畏懼初期的挫折。預測：在組織轉型中是極佳的動員者與願景傳播者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2708, 'CIA_19', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「陽光的火藥桶」。雖然容易被激怒，但因具備正向歸因，怒氣消散極快，不會記恨或長期陷入負面情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2709, 'CIA_19', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「先評估後期待的務實樂觀者」。面對新機會或不確定情境，他多半先往好的可能去想，但真正動手前仍會把風險、假設與可能後果攤開來檢查一輪，不會因為一時看好就跳過評估。連續碰壁或壓力拉長時，正向解讀會先淡下來，這種時候他仍然維持動手前先盤點風險與因應方式的習慣，把下一步想清楚才出手，沒有被低落的情緒推著蠻幹。看到具體進展或拿到需要的資源，正向感回升，決策前的評估動作照樣走完，判斷品質不因情緒起伏而跳動。管理上宜在他狀態偏低時提供清楚的資訊與風險盤點，協助他把不確定感落地成具體選項，重新建立對局面的期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2710, 'CIA_19', 'B (中)', 'CIA_07', 'C', '與 CIA_07 (完美主義) 低分聯動：表現為「先衝再補的樂觀推進者」。任務推進時，他傾向覺得先把東西交出去比卡在細節更重要，品質做到堪用就往下一步走，也相信之後有機會再回頭調整。連續出包或壓力拉長時，這種先衝再說的做法沒有改變，但原本偏正向的解讀會先收斂，他可能隱約感覺到放著的小問題在累積，卻仍然先把進度往前推而不是停下來處理。看到具體回饋或資源到位後，正向感回升，他更願意回頭把先前擱置的細節補齊。管理上宜安排固定的檢核或品保節點，在他狀態穩定時把累積的小瑕疵攔下來，並避免在他情緒偏低的階段一次塞入大量待修事項。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2711, 'CIA_19', 'B (中)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：表現為「守住規則的期待型行動者」。面對進度落後或不利局面，他傾向相信情況還有轉圜餘地，同時就算想儘快扭轉，也不會考慮欺騙、佔便宜或犧牲他人利益這類手段，仍堅持用對等、可攤在陽光下的方式去補救。連續受挫或壓力拉長時，正向的解讀會先淡下來，但他對規則一致性與公平底線的堅持沒有跟著鬆動，不會因為想快點翻盤就放寬標準。看到具體進展或拿到需要的支援後，正向感回升，補救行動仍然走在正規途徑上。管理上可在他狀態偏低時提供合乎規則的補救管道與明確資源，讓他能用正當方式重新建立對局面的期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2712, 'CIA_19', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「靠熟悉做法穩住期待的樂觀者」。遇到問題或不確定的局面，他傾向相信照著過去用過、驗證有效的做法走，事情多半能回到正軌，不急著找全新的解法。連續不順或壓力拉長時，正向的解讀會先收斂，但他面對新方法的態度依然是先觀望，不會因為想儘快翻盤就貿然嘗試沒試過的路數，反而更傾向抓住原本熟悉的做法來站穩腳步。看到具體進展或拿到需要的資源後，正向感回升，做法上仍然以延續既有經驗為主。管理上宜在他狀態偏低時提供熟悉、已驗證過的選項，並用小步調整取代大幅變動，讓他能在穩定基礎上重新看到往前的可能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2713, 'CIA_19', 'B (中)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「易被點燃又快回穩的期待型反應者」。碰到被否定、不公平對待或臨場衝突時，他的反應門檻低，情緒升溫很快，可能當場語氣變衝，甚至直接頂回去。對事情整體會不會有轉機，他多半仍抱著能過去的想法，但連續受挫或壓力拉得很長時，這份正向解讀會先退下來，情緒也更容易被小事牽動、反應更快更硬。看到具體的補救空間或資源到位後，情緒降溫的速度也快，對局面的期待感能跟著回升。管理上宜在他情緒升溫的當下先給緩衝與清楚資訊，等他降溫、看見補救路徑後再處理後續，避免在他剛被激怒時要求他立刻正向看待局面。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2714, 'CIA_19', 'B (中)', 'CIA_01', 'C', '與 CIA_01 (盡責) 低分聯動：表現為「相信會補回來的鬆節奏樂觀者」。面對進度落後或收尾沒到位，他心裡多半還相信之後有機會補回來，不會因為拖著而特別焦慮；同一段時間裡，要把自己重新拉回穩定節奏、盯緊收尾細節，對他來說仍然吃力，容易還是拖著、鬆著往後延。連續碰壁或壓力拉長時，這份之後補得回來的期待會先淡下來，自我監控與維持節奏一樣沒有變得比較容易，仍然需要外部拉一把才動得起來。看到具體進展或有人在旁協助盯進度，正向感回升，行動也比較容易被帶動。管理上宜設明確的進度檢核點並在他狀態偏低時主動介入提醒，避免拖延與消沉同時出現卻沒人接住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2715, 'CIA_19', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「卡關也要升級做法的期待型進取者」。遇到挑戰或卡關，他多半相信換個做法應該能突破，同時對表現與成果有明顯企圖心，願意主動投入更多、把方法與目標往上調整。連續受挫或壓力拉長時，這份對局面會好轉的期待會先淡下來，但想達到更高標準的企圖心沒有跟著降，反而可能在信心沒那麼足的狀態下仍然逼自己升級方法、拉高目標。看到具體進展或拿到需要的資源後，正向感回升，主動投入與升級做法的動能更容易延續而不耗竭。管理上宜留意他連續受挫卻仍硬撐高標準的落差，適時給回饋與資源支持，避免他在低潮期單靠企圖心硬撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2716, 'CIA_19', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「防禦性的勤奮者」。因不相信未來會自然變好，所以靠極度努力來對抗焦慮。警示：雖產出穩定但心理壓力極大，需適時給予紓壓支援。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2717, 'CIA_19', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「焦慮的攀登者」。極想成功但總預感會失敗。預測：行為上雖衝刺，但內耗嚴重。成功後常感如釋重負而非喜悅，需關注其身心健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2718, 'CIA_19', 'C (低)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「抑鬱的放棄者」。既不信自己有能力，也不信環境會好轉。管理風險：極易陷入「習得性無助」，在變動中完全喪失動能，需優先輔導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2719, 'CIA_19', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「陰鬱的操縱者」。因對人性悲觀，更傾向於使用權術或欺騙來保護個人利益。預測：職場防禦心極強，難以建立深度夥伴關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2720, 'CIA_19', 'C (低)', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「韌性支撐的求存者」。雖然對未來不樂觀，但遭受打擊時能硬撐並站起來。管理建議：屬於「實戰型」人才，雖然口頭消極，但行為上極其堅韌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2721, 'CIA_19', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「戴著面具的悲觀者」。內心充滿不安，但為了獲得認可而表現出正向樂觀的樣子。警示：這類員工最難察覺其真實壓力水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2722, 'CIA_20', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「實踐型變革者」。不僅有點子，且能透過自律將創意標準化、流程化。預測：能產出既具新意又具備極高完工度的成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2723, 'CIA_20', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「策略型創新者」。在挑戰現狀前會先進行縝密的風險評估。預測：其提出的變革方案通常具備高度可行性，容易獲得高層支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2724, 'CIA_20', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「不穩定的發明家」。雖有大量創新構思但缺乏行為剎車，容易在未經驗證下頻繁更動流程。警示：會對團隊造成執行上的混亂，需專人負責收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2725, 'CIA_20', 'A (高)', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「游走灰色地帶的破壞者」。利用創新力來鑽規則漏洞或損人利己。管理警示：其創意可能帶來合規風險，需嚴格控管其變革權限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2726, 'CIA_20', 'A (高)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「無畏的變革推手」。對創新充滿樂觀與韌性，即便方案被否決也能迅速修正再出發。預測：是推動企業文化轉型的重要火車頭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2727, 'CIA_20', 'A (高)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「精實創業家」。創新是為了極大化效率，追求用更聰明的方法解決問題。管理建議：非常適合負責自動化、數位轉型或流程優化專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2728, 'CIA_20', 'A (高)', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的顛覆者」。為了推動創新方案而無視團隊成員的情緒壓力。風險預測：雖能達成變革，但過程中可能引發強烈的人際衝突與流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2729, 'CIA_20', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「有紀律的流程改良者」。他在既有工作流程裡常能看出可以微調、優化的地方，尤其當任務範圍與規則講清楚時，提案更容易真的做得出來。他推進這些改善點時不太需要人催——會自己排時程、盯進度、把品質顧到收尾。碰到規則模糊、沒人明確定義邊界的情境，新點子的數量會明顯變少，但他仍會維持穩定的產出節奏，先把手上能掌握的部分做紮實。管理上若想要他持續產出改良提案，把限制與目標講清楚會比放給他自由發揮更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2781, 'CIA_23', 'A (高)', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) A聯動：表現為「純粹的藝術家靈魂」。創作不為名利，只為表達獨特的自我。管理建議：難以用金錢激勵，應給予高度的自主權與創作空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2730, 'CIA_20', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先試後修的流程調整者」。他看到既有做法裡可以改的地方時，常常不先做完整評估就先動手試，等跑起來才回頭補判斷、修正方向。任務邊界與限制講清楚時，他能維持先試後修的節奏，很快端出一個可行的新做法；但邊界模糊、又急著推進時，他容易只顧著把新點子跑出來，沒注意到潛在風險就先上了。事後常常需要花時間收拾沒預先想到的狀況，尤其是在步調快、沒人喊停的場合。管理上宜在他啟動新嘗試前先幫忙點出幾個可能的風險點，讓後續的調整能少走一些冤枉路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2731, 'CIA_20', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「穩住情緒推進改良的實踐者」。他在流程裡看出可優化之處時，即使提案一開始被質疑或打回票，也不會當場情緒化，仍能維持一致的判斷去溝通調整方案。任務範圍與規則講清楚時，他能沉著地把觀察到的優化點整理成扎實可行的提案；一旦邊界不明、方向反覆變動，冒出的新點子會明顯變少，但他的情緒與言行不會跟著亂，仍維持一貫的應對方式。他很少因為一時被否定或壓力大就衝動放棄方案或口氣變差，遇到反覆修改的過程也能撐住。管理上在高壓或方向不明時仍可放心讓他持續參與討論，他不容易情緒失控，能提供相對冷靜的觀察。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2732, 'CIA_20', 'B (中)', 'CIA_13', 'C', '與 CIA_13 (公正性) 低分聯動：表現為「搶先卡位的流程改造者」。他發現既有做法能改良、能做得更好的地方時，會優先考慮這個提案能不能幫自己在競爭中領先；規則清楚、依循空間明確時，也比較願意把改善點做成看得見成果的方案去搶功。若規則模糊、沒人盯著成果怎麼分配，他可能把別人先前的觀察或半成品直接接手掛在自己名下，或用站不住腳的理由把不太公平的做法合理化。他提出新點子的量仍然跟著任務邊界清不清楚在起伏——邊界清楚時提案具體，邊界不清時傾向按兵不動、等機會。管理上宜在改善提案的歸屬與分工上先講清楚規則，並留意他是否用不對等的方式取得表現機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2733, 'CIA_20', 'B (中)', 'CIA_15', 'A', '與 CIA_15 (心理資本) 高分聯動：表現為「帶著信心修流程的樂觀改良者」。他看到既有流程裡可以調整、優化的地方時，面對推動過程中的挑戰或卡關仍能維持動能與信心，把每一次被打回票或行不通的嘗試當成可以處理、可以修正的問題，很少因此整個放棄。任務邊界與規則清楚時，他能一邊保持信心、一邊把觀察到的優化點做成一個個可落地的改善方案；邊界模糊、沒有明確依循時，新點子的數量會下降，但他對最終能找到出路仍保持樂觀，不會因此陷入低落。遇到連續幾次提案不被採納，他多半還能重新調整角度再試，很少就此停下。管理上可以放心讓他承接需要多輪嘗試、容易碰壁的改善任務，他遇到反覆修正的過程比較撐得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2734, 'CIA_20', 'B (中)', 'CIA_21', 'C', '與 CIA_21 (效率取向) 低分聯動：表現為「照規矩微調的改善提案者」。他發現流程裡有可以優化的地方時，習慣先確認現有規範與既定步驟，再從裡面找可以微調、精簡的空間，很少去想直接跳過某個步驟抄捷徑。任務邊界與規則講清楚時，他能在維持精確與條理的前提下端出具體可行的小改善；規則不明、沒有既定步驟可依循時，他容易遲疑不知道從哪裡下手，新點子的產出也隨之變少。他做這些調整時偏好一步步確認、留紀錄，很少跳過檢查直接上線新做法。管理上若希望他持續產出改善提案，把現有流程和檢核步驟先建立清楚，會比要求他大膽破格更容易見到成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2735, 'CIA_20', 'B (中)', 'CIA_26', 'A', '與 CIA_26 (同理心) 高分聯動：表現為「貼著他人感受修流程的改良者」。他觀察流程裡可以調整的地方時，會留意這個改動對實際使用的人或執行的同事帶來什麼感受與困擾，說明新做法時也會依照聽的人的狀態調整語氣與說法。任務邊界與規則講清楚時，他能一邊體察他人的處境、一邊把改善點做成貼近使用情境、真正好用的提案；邊界模糊、沒有明確依循時，他能感受到別人的不便，卻不一定能提出具體改法，新點子的產出跟著變少。他推動改動前通常會先問問受影響的人怎麼想，較少自己單方面決定。管理上若想借重他這項特質，可以讓他負責那些需要先了解使用者實際感受、再做流程微調的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2736, 'CIA_20', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「卓越的守成者」。對現有規則極度忠誠且執行到位，但不具備優化意識。管理建議：適合維護既有成熟系統，但不宜指派其負責開發期專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2737, 'CIA_20', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「努力的跟隨者」。極想成功但缺乏原創思維，傾向於複製已證明的成功模式。預測：在成熟市場的執行力強，但難以應對藍海市場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2738, 'CIA_20', 'C (低)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「傳統捍衛者」。對變革有天然的抗拒感，認為穩定勝於一切。警示：在組織面臨轉型時，可能是最難被說服的人群，需給予充足的過渡期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2739, 'CIA_20', 'C (低)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「渴望成長的模仿者」。雖想自我進步，但傾向於吸收外部現成知識而非自己創造新路徑。管理建議：適合透過外部培訓來引導其技能更新。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2740, 'CIA_21', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「高效產能機器」。不僅想做好，還要做得快。預測：能在最短時間內產出高品質結果，是組織中標準的「高潛力人才（HiPo）」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2741, 'CIA_21', 'A (高)', 'CIA_03', 'C', '與 CIA_03 (審慎) C聯動：表現為「速食決策者」。為了趕進度而犧牲思考深度。警示：容易因追求快而遺漏關鍵風險，需他人協助進行最終審核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2742, 'CIA_21', 'A (高)', 'CIA_06', 'C', '與 CIA_06 (條理性) C聯動：表現為「混亂的高效者」。不拘泥於辦公桌整潔或 SOP，只要能最快拿到結果，過程混亂也無所謂。管理建議：適合作為突擊隊員處理緊急任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2743, 'CIA_21', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「精實大師」。在追求無瑕疵的同時不斷優化動作，達成「一次就做對且最快」。預測：具備卓越的自我優化與流程設計能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2744, 'CIA_21', 'A (高)', 'CIA_13', 'C', '與 CIA_13 (公正性) C聯動：表現為「捷徑尋找者」。為了提升效率不惜損害他人利益或遊走道德邊緣。警示：其效率可能建立在合規風險之上，需嚴格監控手段合法性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2745, 'CIA_21', 'A (高)', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「冷酷的數據者」。視人為資源，為求團隊總產出極大化而忽略個別成員的身心狀況。風險：短期績效極高，但長期團隊流失率大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2979, 'CIA_34', 'A (高)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「高效的玩家」。熱愛優化流程，將解決問題視為一種樂趣。預測：會不斷自發性地尋找「更聰明的工作方式」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2747, 'CIA_21', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「守底線的流程精簡者」。他多半不需要旁人盯著就能自己抓緊進度、把品質和收尾顧好；碰到流程明顯繁瑣時，會主動提出精簡做法，但關鍵查核點通常照樣留著，不會為了圖快整段跳過。時程吃緊時，他傾向先把該做的做完，省略步驟只發生在他確認不影響交付品質的地方。管理上可以放心把進度追蹤交給他自己，也可以直接讓他說明哪些步驟能砍、哪些必須留，取得他對流程改動的判斷依據。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2748, 'CIA_21', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「先動手再補判斷的效率行動派」。他在流程明確的任務裡，會照規矩把步驟走完、也願意主動提精簡建議，但很少在動手前先把每個環節的風險都想過一輪，通常是先照著能想到的方式推進，遇到卡點才回頭補評估。步調快、選項不複雜時，他能很快把事情推進到下一步；一旦情況牽涉較多未知變數，事後才發現漏想的地方也不少見。管理上宜在他啟動前追加一次快速風險提醒，或替重大決策安排一道確認關卡，降低邊做邊補評估帶來的返工。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2749, 'CIA_21', 'B (中)', 'CIA_06', 'A', '與 CIA_06 (條理性) 高分聯動：表現為「循秩序找效率的整理型優化者」。他習慣先把資訊分類、把任務排好順序，例行節奏是他工作的底盤；在這個底盤上，遇到明顯多餘的步驟他會提出精簡，但這類建議通常長在既有排程架構裡，不是打掉重練。任務越熟悉、規則越清楚，他越能一邊維持條理一邊找到省時間的做法；一旦流程本身模糊或臨時被打亂，他會先花時間把秩序重建起來，效率上的調整反而會往後放。管理上可以放心讓他負責流程優化的提案，但排程被打亂時要給他足夠時間先恢復基本秩序，再談加速。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2750, 'CIA_21', 'B (中)', 'CIA_07', 'C', '與 CIA_07 (完美主義) 低分聯動：表現為「抓大放小的交付優先者」。他做事會留住幾個他認定必要的查核點，防止流程走歪或出現大錯，但除此之外的細節，只要堪用他就放行，不會回頭反覆打磨。時間有限時，他傾向先把東西交出去、讓後續再修，而不是把每個角落都磨到滿意才罷手；規範內的簡化建議他也常提，但提出的重點多半是「哪裡可以少做」而不是「哪裡要做得更精緻」。管理上若要提高最終品質，需要另外指定人手把關細節，否則小瑕疵可能在他手上一路累積到後面才被發現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2751, 'CIA_21', 'B (中)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：表現為「只在規則內找捷徑的效率型人」。他常盯著哪些步驟可以省、哪些規定其實是繁文縟節，遇到明顯多餘的環節會直接提議拿掉；但一旦精簡的代價是要犧牲對等或占別人便宜，他會停下來不做，即使那樣能更快達標。競爭壓力大的時候，他仍然只在規則容許的範圍內找捷徑，不會用欺瞞、搶功或不對等的手段換取領先。管理上可以放手讓他主導流程精簡，不需要額外防範他為了衝速度而犧牲公平，這條線他自己守得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2752, 'CIA_21', 'B (中)', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「只看流程不看情緒的推進型效率者」。他討論流程精簡時，注意力多半放在步驟本身合不合理、有沒有多餘環節，卻很少注意誰在過程中覺得被忽略或不舒服。互動時他傾向直接把事情往前推，對於言外之意或沒說出口的顧慮不太敏感，事後才可能察覺有人顯得疏遠。規範內的簡化建議他照樣會提，但提案裡通常少了一段「這樣改大家感受如何」的停頓。管理上宜安排別人幫忙留意流程變動對人的影響，補上他在效率討論裡容易漏接的情緒訊號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2753, 'CIA_21', 'B (中)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) 高分聯動：表現為「把心力用在刀口上的高投入效率者」。他對工作本身有明顯的熱情，願意主動多花時間把成果做得更好，能量通常很充足，不太需要外部推一把才動起來。在規範內找效率的同時，他把多出來的力氣優先投入在他認為真正有影響的環節，對於他判斷可有可無的程序，會提議簡化甚至直接跳過。遇到有挑戰性或能學到東西的任務，他投入度特別高；例行、重複性高又看不出成長機會的工作，他仍會做完，但提出精簡或提速建議的頻率會更明顯升高。管理上可以放心把有難度、需要高投入的任務交給他，也可以直接問他哪些流程覺得能簡化，這類問題他答得出來也願意講。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2754, 'CIA_21', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「傳統苦幹者」。非常努力且負責任，但往往使用舊方法、笨方法。管理建議：應指派其參加工作坊學習新工具，提升其數位化能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2755, 'CIA_21', 'C (低)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「耗時的工匠」。為了細節極限而嚴重拖慢進度。警示：容易在非核心細節上投入過多資源，需主管定義任務的「停損點」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2756, 'CIA_21', 'C (低)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「步調緩慢的樂天派」。做事節奏慢但不感到壓力。管理預測：在高度競爭、節奏極快的環境（如電商、金融）中，會顯得格格不入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2757, 'CIA_21', 'C (低)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) A聯動：表現為「僵化的官僚執行者」。嚴格遵守流程即使該流程已明顯不合時宜。警示：是組織冗長流程的維護者，缺乏變革動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2758, 'CIA_21', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「拖延的焦慮者」。因效率低導致任務堆積，進而引發焦慮與負面情緒。預測：在高壓截止日期前極易情緒失控。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2759, 'CIA_22', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「組織的鋼鐵基石」。具備極高的可靠性與服從度。預測：在嚴謹、高壓且需精確執行的環境（如航太、軍事、醫療）中表現最卓越。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2760, 'CIA_22', 'A (高)', 'CIA_20', 'C', '與 CIA_20 (創新力) C聯動：表現為「守舊的官僚者」。過度依賴舊規，對任何改變都有天然抗拒。管理建議：不宜指派其負責開發期專案，但在維護既有成熟系統時極其稱職。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2761, 'CIA_22', 'A (高)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) A聯動：表現為「冷靜的制度執行者」。即便面對極大情緒壓力，也能管住行為不做出任何違規舉動。預測：適合處理敏感、保密且流程僵化的行政事務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2762, 'CIA_22', 'A (高)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「表面服從者」。口頭高度配合公司規則，實則利用規則死角謀求私利。警示：此組合最具隱蔽性，需透過非正式溝通管道瞭解其真實動向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2763, 'CIA_22', 'A (高)', 'CIA_26', 'C', '與 CIA_26 (同理心) C聯動：表現為「死板的鐵面人」。執行制度時毫不留情，無視他人苦衷。管理風險：極易在基層引發反感，需留意其與團隊成員的磨合狀況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2764, 'CIA_22', 'A (高)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「忠誠的受命者」。一旦認同指令，會不計代價地落實。預測：是主管最放心的「交辦對象」，通常不需要二次確認進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2765, 'CIA_22', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「有邊界才穩的可靠執行者」。規則清楚時，他能主動掌握進度、顧好品質與收尾，不太需要人催；一旦規則模糊或沒人明訂做法，他仍願意試著自己找出路，但這時要維持同樣的可靠輸出就得多花力氣，容易在方法上猶豫、進度因此變得不穩。他習慣把「該怎麼做」先問清楚，問到答案後才會展現原本那種扎實的自我要求。管理上把目標與邊界講明，他能持續交出可靠成果；留一大片空白讓他自己摸索方法，反而拖慢他原本擅長的節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2766, 'CIA_22', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「偏好沿用成法的規則配合者」。有既定規則時，他做得很順，照著被接受的方法走就能穩定產出；碰到沒有規則的情境，他也願意試試看，但不太會主動去發明新做法，反而傾向先觀望、找有沒有現成流程可以套用。這種時候他的輸出速度會慢下來，因為他既不排斥沒規則的場面、又缺乏用創新方法自己開路的動力，卡在「要嘗試但沒有既有做法可抄」的空檔裡。管理上若能提供一個可參照的框架或先例，即使規則不完整，他也能較快找到可依循的方向並穩定推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2767, 'CIA_22', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「情緒穩定但方法待定的嘗試者」。沒有規則、方向不明時，他不會因為焦躁而亂了陣腳——面對不確定，他仍能維持一致的行為與判斷、不衝動下決定；但少了明確目標與邊界，他這份穩定的情緒不會自動變成穩定的產出，反而可能出現「態度很平穩、但沒人知道他接下來要做什麼」的空轉。他不會急著硬做出結果，寧可先撐著等狀況清楚一點。管理上他不太會因為模糊情境而情緒失控，這點可放心；但若想要他真正動起來，仍得補上具體的目標與範圍，光靠他情緒穩不會補足方向感的缺口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2768, 'CIA_22', 'B (中)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) 低分聯動：表現為「規則鬆動時容易被利益牽走的配合者」。規則清楚、邊界明訂時，他會照規矩配合行事；但一旦碰上沒有規則、或目標邊界不清的情境，他在「怎麼做」上的空白，容易被想拿到利益、地位或好處的念頭填滿，甚至合理化「先拿到再說」的做法。他不是刻意不守規矩，而是缺乏明確架構時，原本該撐住他行為方向的東西沒了，利益考量就趁虛而入。管理上規則與邊界訂得越清楚，越能約束住他這面；一旦放給他自由發揮又沒人盯著結果分配，風險會明顯升高，需要額外的監督或事後檢核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2769, 'CIA_22', 'B (中)', 'CIA_26', 'A', '與 CIA_26 (同理心) 高分聯動：表現為「能讀懂人但仍需方向的彈性配合者」。不管有沒有既定規則，他都能感受到周遭的人在意什麼、需要什麼，並自然調整自己的語氣與回應方式去貼近周遭人的需要；但這份對人的敏感度並不會自動轉成他對任務本身的清楚方向——沒有規則、目標又模糊時，他仍可能一邊很懂得照顧他人感受，一邊不確定自己該往哪個做法走。他傾向先確認清楚要做什麼、邊界在哪，才會把這份體貼他人的能力穩定地用在推進工作上。管理上給他明確目標，他既能把事情做完，也會把過程處理得讓周遭人感覺被顧到；只給人際空間、不給任務邊界，他的產出仍容易卡住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2770, 'CIA_22', 'B (中)', 'CIA_30', 'C', '與 CIA_30 (個人責任感) 低分聯動：表現為「邊界不清時容易把責任外推的配合者」。有規則可循時，他會照著做，出狀況也還能對照規則說清楚自己該負什麼；但一旦落入沒有規則、目標邊界模糊的情境，他遇到失誤或延誤時更容易把原因往外歸——說是情境不明、沒有人講清楚該怎麼做——補救動作也偏被動，不太會主動去把缺口補上。這種傾向在規則清楚時不太會被看見，但情境一模糊就浮現出來。管理上目標與邊界訂得越明確，越能讓他清楚知道自己該扛什麼；邊界一旦鬆動，需要多一層事後追蹤，否則問題容易被歸咎於「情境不清楚」而拖著不處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2771, 'CIA_22', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「先評估風險才敢動的謹慎嘗試者」。面對沒有規則的情境，他不會貿然行動，而是先評估可能的風險、假設與後果，在不確定中仍維持一定的判斷品質；但這份謹慎也意味著，若目標與邊界一直沒有講清楚，他評估完風險後仍可能停在原地，遲遲沒有真正跨出第一步，因為他不確定自己評估的方向對不對。他不是不願意嘗試，而是需要一個明確的範圍讓他的審慎有地方落地。管理上先把目標與邊界定下來，他能把審慎轉化成穩健的推進；邊界一直懸著，他的謹慎反而可能變成拖延判斷的理由。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2772, 'CIA_22', 'C (低)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「破壞式創新者」。視規則為絆腳石，傾向於「先做再說，被抓到再道歉」。管理建議：適合研發或前線開拓，但必須配備一名行政助手協助合規收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2773, 'CIA_22', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「自律的獨行俠」。對工作品質有高要求（盡責），但非常討厭形式化的規矩。預測：會產出高品質結果，但常因不填日報或不按流程申請而遭行政單位投訴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2774, 'CIA_22', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「精明的規避者」。在不遵循規則前會精密計算過後果，確保自己不會受到懲罰。警示：其違規行為通常具備「戰略性」，難以透過簡單管理糾正。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2775, 'CIA_22', 'C (低)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「俠義的破局者」。會為了團隊利益或夥伴情誼而勇敢挑戰公司「不合理」的制度。管理預測：是潛在的基層意見領袖，若管理不當易形成對立。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2776, 'CIA_22', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「反叛的刺頭」。認為規則是用來約束平庸者的，自己應享有例外權。風險：極易公開挑戰主管權威，對組織紀律的殺傷力極大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2777, 'CIA_22', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易爆的刺客」。對規範有強烈排斥感，一旦被要求遵守規則，極易產生對抗性的負面情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2778, 'CIA_23', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「多產的原創大師」。能將獨特的點子轉化為具體的作品或提案，而非流於空想。預測：能穩定產出具有高度辨識度的專業成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2779, 'CIA_23', 'A (高)', 'CIA_06', 'A', '與 CIA_06 (條理性) A聯動：表現為「結構化的創意者」。能將天馬行空的想法整理成極具邏輯的體系。管理建議：適合作為產品架構師或內容策略開發者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2780, 'CIA_23', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「極致美學追求者」。對原創內容的細節有近乎病態的要求。預測：能創造出具備極高品牌價值的巔峰之作，但開發週期可能較長。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2782, 'CIA_23', 'A (高)', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「反傳統的奇才」。其原創性往往建立在對舊有規定的否定之上。風險：可能在團隊中顯得格格不入，甚至挑釁現有流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2783, 'CIA_23', 'A (高)', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「忠於自我的創作者」。其點子不僅獨特，且反映其真實內在。預測：具備強大的個人魅力與品牌原創性，適合品牌代言或核心價值詮釋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2784, 'CIA_23', 'A (高)', 'CIA_35', 'A', '與 CIA_35 (生活熱情) A聯動：表現為「靈感不斷的發電機」。對生活充滿好奇，能從跨領域的體驗中汲取養分。預測：在腦力激盪（Brainstorming）會議中是不可或缺的點子來源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2785, 'CIA_23', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「穩定收尾的情境型原創者」。他對進度與品質有一致的自我要求，多數任務不需要人催促就能顧好收尾；面對問題時，若刺激夠、題目設計得清楚，他會多花心思找出不同以往的解法。但材料不足或限制模糊時，他不會為了求新而拖延交付，反而先確保有一個可行、扎實的做法先落地，把打磨獨創性的空間留到後段。管理上若希望他發揮新意，宜提前給清楚的問題框架與足夠素材，而不是臨時才丟題目要他想點子。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2786, 'CIA_23', 'B (中)', 'CIA_06', 'C', '與 CIA_06 (條理性) 低分聯動：表現為「即興發想但收尾鬆散的原創者」。他做事不太依賴固定流程，遇到刺激夠、問題設定清楚的場合，常常臨場就能想出不同以往的做法，不需要照本宣科一步步來。但問題模糊或素材不足時，他缺乏一套固定方法可以退回去依循，想法容易停在片段、沒有整理成可執行的形式；就算真的想出好點子，記錄與交接也常不完整，後面接手的人得自己拼湊脈絡。管理上宜在他發想後安排一次整理動作，把臨場冒出的原創想法轉成有紀錄、可交接的成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2787, 'CIA_23', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「反覆打磨型原創者」。問題設計清楚、素材足夠時，他能想出不同以往的解法，而且不會點子一出來就交出去，會反覆檢查、優化到接近無瑕疵才罷手。刺激不足或限制模糊時，他不會硬擠出新想法，而是把同樣的高標準用在既有做法上，把常規解法磨到可靠好用。原創想法剛成形時通常還粗糙、需要快速試錯；他若在這個階段就先反覆檢查優化，交付步調可能比預期慢，好點子還沒機會驗證就卡在打磨階段。管理上宜替新想法設一個「先求可行、再談完美」的階段，避免早期過度優化拖慢原創產出的速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2788, 'CIA_23', 'B (中)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) 低分聯動：表現為「講回報的情境型原創者」。他在乎努力最後能不能換到看得見的東西，加薪、頭銜、被特別看見這類回報對他來說是實在的誘因。遇到刺激足夠、問題設計得好的任務，他確實會花心思想出不同以往的解法；但如果他感覺不到這個場合會被記功或帶來實質回報，即使題目本身有發揮空間，他也傾向省下力氣、直接套用常規做法完成任務，不會特別多花心思求新。他心裡清楚知道這題目好不好發揮，但同時也在意這件事做完後會不會被算進他的貢獻裡。管理上若希望他拿出原創想法，除了給清楚的問題框架，也需要讓他看到投入原創會被看見、被計入貢獻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2789, 'CIA_23', 'B (中)', 'CIA_22', 'A', '與 CIA_22 (紀律遵循度) 高分聯動：表現為「敢闖但視情況求新的開路者」。面對沒有既定規則、沒人先做過的情境，他不會卡住等指示，會自己找出一條路往前推進，不需要先有前例才敢動手。這個情境若剛好線索夠、素材足，他往往能在推進的過程中順勢想出不同以往的解法；但素材貧乏、題目本身模糊不清時，他還是會往前走，只是走的路多半是他熟悉的常規做法。旁人可能因此覺得他這次比較保守，其實他推進的意願和動作沒有變，差別只在那次情境的材料夠不夠支撐一個不一樣的做法。管理上若要他既能開路、又能拿出新意，光給模糊授權不夠，還要搭配足夠的資訊或案例讓他有東西可以組合創造。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2790, 'CIA_23', 'B (中)', 'CIA_24', 'C', '與 CIA_24 (真實性) 低分聯動：表現為「想得到卻不一定說出口的原創者」。刺激足夠、問題設計清楚時，他確實能想出不同以往的做法，腦中不缺新點子。但他也容易被現場的氣氛或旁人的期待牽著走，一旦感覺提出來的想法跟大家預期的方向不一樣、可能引發爭執，他常常選擇先把話收回去，順著大局說一套比較安全的版本。長期下來，團隊可能看不到他真正想過的東西，只看到他附和常規做法，原創的部分留在他自己心裡沒有被說出來。管理上宜營造一個提出不同意見不會被究責的氛圍，並主動追問他「有沒有其他想法」，才有機會把他沒說出口的原創部分引出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2791, 'CIA_23', 'B (中)', 'CIA_35', 'A', '與 CIA_35 (生活熱情) 高分聯動：表現為「帶勁但看場合出新招的行動派」。他做事一向帶著明顯的活力，對接下來要做的事抱著期待，很少用有氣無力的態度面對任務。遇到刺激足夠、問題設計得好的場合，他會很起勁地去找不同以往的做法，一個想法接一個想法冒出來，整個人看起來像是在打一場他很想打的仗。換成限制模糊、素材不夠的場合，他不會因此洩氣或擺爛，還是照樣充滿幹勁地把手上的任務做完，只是這次的幹勁展現在把常規做法執行得漂亮，而不是硬生出新點子。管理上可以放心把陌生、資訊不全的任務交給他，他的投入度不會因為題目不夠新而打折，但若真心想要他的原創輸出，仍要把問題和材料準備清楚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2792, 'CIA_23', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「高產出的複刻者」。雖有強大成功渴望，但傾向於走已驗證的「安全牌」。管理警示：在需要顛覆式設計的環境中會顯得靈魂不足。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2793, 'CIA_23', 'C (低)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「務實的執行專家」。對處理已知領域的任務非常有信心，但對「無前例可循」的創意任務感到不安。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2794, 'CIA_23', 'C (低)', 'CIA_20', 'A', '與 CIA_23 (獨創性) C 與 CIA_20 (創新力) A：表現為「改良型工程師」。擅長優化現有流程，但較難產出顛覆性的新概念。預測：是組織進行漸進式改進（Kaizen）的優選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2795, 'CIA_23', 'C (低)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的從眾者」。為人好相處，思維大眾化，不具威脅性。管理建議：適合作為前線服務或需要大量人際協作的標準化職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2796, 'CIA_23', 'C (低)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「勤奮的學習機器」。能快速吸收現有的知識體系，但較難發展出個人風格的見解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2797, 'CIA_24', 'A (高)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「組織的道德羅盤」。其正直源於深層的內在信念而非恐懼懲罰。預測：在企業面臨倫理抉擇時，會是堅持價值觀而不妥協的關鍵力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2798, 'CIA_24', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「真誠的人道主義者」。對人的關懷不具政治目的，能建立極高質量的深度信任。管理建議：適合作為高階教練或員工關係調解者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2799, 'CIA_24', 'A (高)', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「頑固的真誠者」。不願為了場面圓滑而掩飾想法，說話過於直接。警示：雖值得信任但易在社交中受挫，需主管保護其直言不諱的勇氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2800, 'CIA_24', 'A (高)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的自我」。完全不在乎社會評價，僅追求對得起自己。預測：測評結果極具參考價值，其反饋通常是未經修飾的真相。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2801, 'CIA_24', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「情緒透明者」。高興或憤怒都寫在臉上，絕不隱藏。管理建議：雖有情緒但因透明而好預測，主管能輕易判讀其當下的心理狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2802, 'CIA_24', 'B (中)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：表現為「委婉守線者」。就算眼前有領先或達標的誘惑，他仍拒絕用欺騙、偷竊或利用他人的手段換取優勢，對等與規則一致對他有實際份量。遇到高社會壓力或權威情境，他不會鬆動這條底線，變動的只是表達方式：立場照舊,但語氣會收斂、措辭會挑選,好讓自己在守住原則的同時還留有合作空間。旁人看到的往往是「態度變軟」,實際上他的判斷沒有跟著軟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2803, 'CIA_24', 'B (中)', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「低訊號收斂者」。他對他人情緒或隱含需求本來就不太敏感,互動多半聚焦在把事情推進上。碰到高社會壓力或權威場合,他會收起真實想法、換一種更保守的說法來保留合作空間,但這個調整不是讀懂了現場氣氛才做的,更像是憑經驗判斷「這裡不適合直說」的機械反應。結果是他表達變了、旁人卻看不懂為什麼變,容易被誤解成立場或想法本身也變了。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2804, 'CIA_24', 'B (中)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) 高分聯動：表現為「彈性表達合作者」。他能因應不同性格與風格的人調整互動節奏,懂得緩解人際張力、把關係往互利方向帶。在高社會壓力或權威情境下,這份調整能力會延伸到自我表達上——他會主動收斂真實意見的呈現方式,換成現場更容易被接受的說法,藉此保住繼續合作的空間。這種收斂做得自然,不太顯得勉強或失去自己,反而像是他眾多互動策略裡的一種。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2805, 'CIA_24', 'B (中)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) 低分聯動：表現為「內真外斂者」。他不會為了討好或塑造形象而扭曲自己真正的想法與判斷,私下問起來,他講的多半是心裡實際相信的那一套。可是一旦場合換成高社會壓力或權威情境,他外顯的表達會主動收斂——同一個判斷,他會挑更保留的說法講出來,以保留合作空間。內在認知沒有跟著場合改變,改變的只是他願意把多少真實想法直接說出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2806, 'CIA_24', 'B (中)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「壓住表達的易燃者」。在高社會壓力或權威情境下，他會先收起真實想法、選擇比較保留的說法以維持合作空間，但對挫折、否定或不公平的反應門檻本來就低。當他長時間壓住外顯表達，容易感到憋住；這時只要再遇到一個觸發點，情緒升溫速度會比平常快，語氣可能明顯變衝、甚至當場頂回去。場合一旦放鬆下來，原本壓住的反應也可能浮出來，變成延遲的衝動回應或翻舊帳式的對抗。管理上宜留意他在高壓場合的沉默不代表沒事，適時提供私下抒發的管道，避免情緒累積到爆點才處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2807, 'CIA_24', 'B (中)', 'CIA_25', 'C', '與 CIA_25 (集體意識) 低分聯動：表現為「為己而斂者」。他做事更看重自己的目標與自主性,對「配合團體」這種要求本身投入度不高,清楚的個人責任與回報對他比較有吸引力。遇到高社會壓力或權威情境,他一樣會收斂真實想法的表達方式,但這個收斂算的是自己的處境——說白了可能招來麻煩、影響到自己接下來的空間,而不是顧慮團體和諧或他人感受。同一個「調整表達」的動作,在他身上是自保盤算,不是配合集體。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2808, 'CIA_24', 'B (中)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) 高分聯動：表現為「讓利型收斂者」。他在合作裡看重整體成果與長期互惠,願意先付出、讓一步甚至多扛一些責任,只要能把共同目標往前推。碰到高社會壓力或權威場合,他也會收斂真實意見的表達,把想法換成更容易被接受的說法,為的是保留繼續一起把事情做完的空間。這兩件事在他身上其實是同一種傾向的不同面貌——都是願意先讓出一部分自己,去換取事情能繼續往前走。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2809, 'CIA_24', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「深沉的社交偽裝者」。行為高度受目的驅動，難以判別其真心。風險預測：在職場政治中極其危險，可能為了上位而編造符合高層喜好的價值觀。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2810, 'CIA_24', 'C (低)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「盲從的組織人」。為了融入群體可以隨時修改自己的立場與偏好。管理警示：缺乏獨立見解，容易在團隊中形成集體盲思（Groupthink）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2811, 'CIA_24', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「精明的合約者」。表面表現得不在意，實則內心精密計算每一分回報。警示：一旦感到不公，會使用非直接的方式進行報復或怠工。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2812, 'CIA_24', 'C (低)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的變色龍」。擅長在不同場合展現不同的人格面具以獲取利益。預測：適合業務開發或公共關係，但內部管理時需警惕其承諾的真實度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2813, 'CIA_24', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「隱性特權索求者」。內心認為自己高人一等，但在外表上會包裝成平易近人的樣子。管理風險：當其特權未獲滿足時，會展現出劇烈的被動攻擊（Passive-aggressive）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2814, 'CIA_24', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「完美的模範人設」。行為完全符合職場教科書要求，但缺乏靈魂與感染力。管理建議：需透過深度對話挖掘其真實需求，防止其突然的職業燃盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2815, 'CIA_25', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「組織的榮譽戰士」。將個人成功與團隊勝敗深度綁定。預測：在競爭激烈的市場中，會為了團隊達標而爆發驚人鬥志，是優質的部門主管人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2816, 'CIA_25', 'A (高)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「公平的守護者」。追求集體利益的同時堅持公正不阿，防止團隊內部的分配不均。預測：在管理崗位上能極大化團隊信任感，降低內耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2817, 'CIA_25', 'A (高)', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「無私的貢獻者」。願意默默付出不搶功，將光環留給團隊。管理建議：是建立高凝聚力文化的靈魂人物，需適時公開表揚其貢獻，以免其被忽視。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2818, 'CIA_25', 'A (高)', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「逆境中的黏著劑」。在團隊面臨危機時，其強大的歸屬感會轉化為支撐同僚的韌性。預測：能有效防止團隊在壓力下瓦解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2819, 'CIA_25', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「排外的護城河」。雖對團隊忠誠，但認為自己的小圈子應享有優於其他部門的特權。警示：易引發跨部門協作的衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2820, 'CIA_25', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「看得到舞台就衝的條件型協作者」。他對成果有明顯企圖心，遇到挑戰會主動想辦法升級做法、拉高目標；但真正投入團隊的程度要看任務能不能讓他發揮、回報合不合理，條件到位時他會把衝勁整個投進協作裡，也願意配合分工。一旦任務顯得平淡、看不到表現空間，他的投入度會先降下來，只維持基本配合、不主動加碼。管理上宜替他設計能同時展現能力、又對團隊有具體貢獻的任務，讓他的投入有更穩定的著力點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2821, 'CIA_25', 'B (中)', 'CIA_13', 'C', '與 CIA_13 (公正性) 低分聯動：表現為「規則對自己有利才守規矩的協作者」。他願意配合團隊推進任務，同時心裡盤算著這件事划不划算；競爭壓力升高、資源有限時，他傾向把領先擺在對等規則之前，可能出現搶功、走捷徑或把他人的付出算進自己成果裡的做法。任務公平、回報清楚時，他能維持基本合作、不製造明顯衝突；一旦感覺自己吃虧或制度有空子可鑽，合作的分寸就會鬆動，優先確保自己不落後。管理上需要把公平機制做得可見、可追蹤，減少他能鑽的模糊地帶。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2822, 'CIA_25', 'B (中)', 'CIA_14', 'A', '與 CIA_14 (謙虛) 高分聯動：表現為「不搶功、但照樣算投入產出的協作者」。他看待自己與他人的位置相對平衡，不需要靠出風頭或壓過別人證明價值，團隊裡有人表現好，他能坦然承認、不搶著攬功；但他的投入程度仍會隨任務與回報調整，制度公平、合作看得到實質效果時，他樂於退到協助位置、把舞台留給別人。長期只有付出、缺乏對等對待時，他會開始收斂配合的力道，轉為只做份內的事。管理上可以放心讓他擔任支援型角色，但仍要留意合作的回報是否維持在合理範圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2823, 'CIA_25', 'B (中)', 'CIA_18', 'C', '與 CIA_18 (韌性) 低分聯動：表現為「短期能扛、長期易耗損的協作者」。他願意配合團隊、按分工把事情做完，也會依任務難度與回報調整自己投入的力氣；但在拉長的高壓期或連續變動下，他的能量會明顯往下掉、恢復速度變慢，原本還算穩定的配合度也可能跟著起伏。條件平穩、制度公平的階段，他能維持基本合作、把份內事做好；長時間高壓下則容易先顧自己撐住，對團隊事務的餘力變少。管理上宜留意連續高壓期的節奏，適時讓他喘口氣、補上支援，讓他有機會把配合度拉回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2824, 'CIA_25', 'B (中)', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「肯出力、但覺得該被特別看見的協作者」。他願意投入團隊任務，也會照著分工往前推進，但心底對自己該得到什麼待遇有一套既定期待，不一定跟實際付出或績效對得起來。任務順利、他覺得自己被適當對待時，能維持穩定配合甚至主動補位；一旦回報或關注沒有到位，情緒容易明顯上揚，出現不滿、抱怨甚至對抗反應，合作的力道也跟著收緊。管理上宜把待遇與貢獻的對應關係講清楚、盡量透明化，減少他用主觀期待衡量落差的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2825, 'CIA_25', 'B (中)', 'CIA_01', 'C', '與 CIA_01 (盡責) 低分聯動：表現為「願意配合、收尾卻常拖後腿的協作者」。他重視團隊一起把事情做完，任務清楚、回報合理時也願意主動配合分工；但他的自我要求容易受情境或情緒牽動，遇到瑣碎、缺乏立即回饋的部分，進度容易拖延、細節做得鬆散。有明確截止與檢核點時，他的配合表現會回穩許多；缺乏這些外部提醒，收尾最容易被放到最後、交付品質也容易跟著鬆動。管理上宜替他設清楚的檢核節點與提醒機制，讓合作的意願有機會落地成準時交付。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2826, 'CIA_25', 'B (中)', 'CIA_11', 'A', '與 CIA_11 (誠懇) 高分聯動：表現為「有話直說、也願意配合到位的協作者」。他很少為了達成目標去操縱或欺騙他人，溝通偏直接透明，習慣用真實資訊跟人建立合作關係；同時他對投入團隊的程度仍會視任務與回報做衡量，不會照單全收每個要求。任務目標清楚、制度公平時，他會直接把想法攤開來討論、按分工把事情做好；遇到回報不合理或要求模糊的情況，他也會直說自己的保留，而不是表面配合、私下打折扣。管理上可以放心用透明的方式跟他溝通期待，他傾向以同樣坦率的方式回應與投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2827, 'CIA_25', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「專業的獨行俠」。工作極度負責，但只管好自己的事，不參與團隊事務。管理建議：適合獨立研究或專家職位，不宜強迫其負責團建。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2828, 'CIA_25', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「職場僱傭兵」。僅視組織為跳板，缺乏忠誠度。警示：隨時可能為了更高待遇離職，甚至帶走核心資源，需加強競業條款與資安控管。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2829, 'CIA_25', 'C (低)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「孤傲的顛覆者」。點子極多但常挑戰既有團隊共識。預測：其創新可能因缺乏群體支持而難以落地，需配備溝通力強的搭檔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2830, 'CIA_25', 'C (低)', 'CIA_26', 'A', '與 CIA_25 (集體意識) C 與 CIA_26 (同理心) A：表現為「選擇性關懷者」。同情個體，但對抽象的組織利益無感。行為預測：會為了下屬的私事而違反公司規章。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2831, 'CIA_25', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「計較的交易者」。對個人利益分毫不讓，完全依照合約行事。管理建議：以明確的獎酬與關鍵績效指標（KPI）來對話，勿談願景。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2832, 'CIA_25', 'C (低)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「圓滑的投機客」。表面人緣極佳，實則內心與組織極度疏離。警示：具備強大的帶風向能力，若對公司不滿，會成為潛在的輿論隱憂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2833, 'CIA_25', 'C (低)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「自嗨的工作狂」。對工作本身充滿熱愛，但對團隊合作或組織規範感到煩躁。預測：是高產出的個人工作者，但不具備管理潛質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2834, 'CIA_26', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「溫暖的執行者」。在追求工作產出的同時，會極力避免對他人造成困擾或負擔。預測：是極佳的團隊導師，能以身作則且耐心引導後進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2835, 'CIA_26', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「周全的協調家」。在做決定前會細膩評估對相關人員的心理影響。管理建議：適合處理組織內複雜的人事異動或高難度的客戶關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2836, 'CIA_26', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情感起伏大的照顧者」。雖極具愛心但情緒容易受他人影響。警示：容易因為過度同情而做出不理智的承諾，需注意心理邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2837, 'CIA_26', 'A (高)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「仁慈的裁判」。堅持原則的同時，能以令人舒服的方式傳達紀律。預測：在管理崗位上能將「法、理、情」完美結合，深獲下屬愛戴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2838, 'CIA_26', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「情感敏感者」。對外界情緒極度敏銳，容易感同身受但也容易被他人負能量引燃。風險：在高壓負面環境中極易產生情緒倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2839, 'CIA_26', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「理性傾聽、自律收尾的推進者」。在任務討論中，他能聽懂他人在意什麼、卡在哪裡，但這份理解多半停留在把他人的處境轉譯成清楚的問題描述，較少停下來陪他人梳理情緒。同時他對自己的進度、品質與收尾一直維持一貫要求，不太需要外部催促就能把事情做完做好。當他人的困難能被講成具體任務或障礙時，他會把這份理解直接接進自己的推進節奏裡調整做法；但若他人要的是情緒上的陪伴而不是問題解決，他可能已經在想下一步該怎麼收尾。管理上可以在交辦時明確標出這次需要的是傾聽還是解法，讓他知道什麼時候該放慢腳步、什麼時候可以照一貫節奏推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2840, 'CIA_26', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「快速抓重點、先做再調的回應者」。與人談事情時，他能快速抓到他人在說什麼、要的是什麼，不太需要把細節講清楚就能接上話、給出回應。但他傾向先接手處理、邊做邊調整，較少在回應前停下來反覆確認自己對他人處境的理解是否完整。在步調快的討論中他能俐落跟上、不拖泥帶水，只是一些沒被明講的顧慮或情緒容易在這種節奏裡被跳過，得等他人後續反應浮現，他才察覺自己會錯意。管理上宜在他快速回應後補一個確認的步驟，讓他有機會回頭核對自己對他人狀況的理解，避免因為衝太快而錯讀真正的需求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2841, 'CIA_26', 'B (中)', 'CIA_05', 'A', '與 CIA_05 (衝動管理) 高分聯動：表現為「看得清楚、穩得住場面的理解者」。遇到他人情緒明顯、語氣變衝的場合，他大致聽得懂那股情緒從哪裡來、卡點是什麼，但這份理解偏向把狀況看清楚，不太涉及自己也跟著被情緒帶動。即使場面一時緊繃，他的言行與判斷還是維持一貫，不會因為現場情緒升溫就跟著提高音量或臨時改變決定。他能一邊接住他人丟過來的不滿或壓力，一邊維持原本該做的判斷，不會被一時情緒推著做出代價高的回應。管理上適合讓他處理容易起衝突或情緒張力高的場合，他的穩定能成為緩和局面的支點；只是也要記得他自己承接的情緒份量不會自動被看見，需要另外留意他的狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2842, 'CIA_26', 'B (中)', 'CIA_13', 'C', '與 CIA_13 (公正性) 低分聯動：表現為「讀懂人心、必要時借力佔先的行動者」。在任務討論中，他能準確讀出他人的立場、顧慮與在意的點，這份理解偏向把狀況看清楚，語氣上仍以理性、就事論事為主。遇到競爭激烈或達標壓力大的情境，他有時會把這份對他人狀況的掌握，拿來換取對自己更有利的結果，比如挑他人在意的點去談條件，或是搶先卡住有利位置。這種時候他不一定會把他人的處境或感受放在跟自己目標同等重要的位置，行動仍以自己能不能領先為優先。管理上宜在高利害的合作場合設清楚的規則與底線，讓他對他人狀況的掌握用在把事情談成，而不是變成單方面取得優勢的工具。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2843, 'CIA_26', 'B (中)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) 高分聯動：表現為「懂人在行、自己容易被點燃的人」。在一般任務討論中，他能聽懂他人的立場與顧慮，回應多半平穩、就事論事。但一旦自己遇到被否定、卡關或感覺不公平對待，情緒門檻很快被壓低，語氣可能瞬間變衝，甚至當場頂回去。這種時候，即使他還看得懂旁人在說什麼、要什麼，自己的反應已經先衝出去，沒有餘力把那份理解用在放緩自己的語氣上。管理上宜在對他提出否定或指正時，先給清楚理由與緩衝空間，讓他有機會先消化情緒再回應，也提醒周遭同事挑他語氣平穩的時候把重要的事談完。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2844, 'CIA_26', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「聽懂就做完、不主動加碼的人」。在任務型的對話裡，他能聽懂他人要的是什麼、卡在哪裡，回應也算得上到位、穩定。但他把重點放在把眼前的事做完、做到位，不會主動去想是不是還能替他人多做一點、多爭取一點。如果環境或要求明確表明需要多付出，比如上級交代要多照顧某人的需求，他會跟著調整、把力氣加上去；沒有這樣的訊號時，他多半停在把基本的事處理好就好。管理上若希望他在協助他人時多走一步，宜明確表明期待與支持，而不是預期他會自己主動看見那個需要再加碼。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2845, 'CIA_26', 'B (中)', 'CIA_06', 'A', '與 CIA_06 (條理性) 高分聯動：表現為「聽懂了就排進流程裡的人」。他在對話中能聽懂他人在意的重點，並且習慣把這些理解轉成具體、有條理的後續處理，而不是停留在口頭上的回應。遇到他人反映的問題或需求，他會傾向把它分類、排進既有的流程或待辦裡，按部就班去跟進，降低漏接或忘記的機會。這樣的方式比較不容易遺漏事情，只是他人得到的回應多半是一份清楚的處理步驟，而不一定是當下的情緒回應或安撫。管理上可以放心把需要長期追蹤、容易被忘記的他人需求交給他，同時提醒他在必要時刻補一句口頭上的關心，讓回應不只是流程，也有被聽見的感覺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2846, 'CIA_26', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「冷酷的攀登者」。目標感極強且無視他人痛苦，視團隊成員為達成目標的工具。警示：高產出但伴隨高流失，需注意其對組織氛圍的破壞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2847, 'CIA_26', 'C (低)', 'CIA_06', 'A', '與 CIA_06 (條理性) A聯動：表現為「無情的標準作業機器」。凡事講究程序與邏輯，對他人的情緒訴求感到不耐與困惑。管理建議：適合處理冷冰冰的數據與流程，不宜負責第一線客服。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2848, 'CIA_26', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「掠奪型操縱者」。了解他人弱點（認知同理強）但不在乎其感受（情感同理弱），並藉此進行社交操弄。風險：職場霸凌的高潛在對象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2849, 'CIA_26', 'C (低)', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「鐵石心腸的倖存者」。能在混亂中保持冷靜，不被哀兵政策所動。預測：在執行裁員或重大改革等痛苦決策時，能展現出極強的心理剛性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2850, 'CIA_26', 'C (低)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「精確的會計師人格」。只看數據與對等回報，不談人情。管理建議：以事實與契約為對話基礎，任何情感訴求對其皆無效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2851, 'CIA_26', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「自我中心的特權者」。認為全世界應繞著他轉，完全無視他人需求。警示：對團隊合作極具毀滅性，需建立明確的人際邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2852, 'CIA_27', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「無私的耕耘者」。不僅做事負責，且不計較短期得失。預測：在初創期或資源匱乏的專案中，是最穩定的戰力，不會因獎金遲發而輕易動搖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2853, 'CIA_27', 'A (高)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「組織奉獻者」。願意為了團隊成功而超時工作或共體時艱。管理建議：應定期給予精神激勵與長期承諾，防止其因長期被「佔便宜」而最終崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2854, 'CIA_27', 'A (高)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「熱情的志工心態」。工作本身就是回報，對薪酬以外的價值（如成就感）極度重視，是企業文化的穩定核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2855, 'CIA_27', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「自律穩定、心裡有帳的執行者」。他做事一貫維持高標準，進度自己盯、品質自己顧，收尾不太需要人催，日常輸出穩定可靠。他也在意投入跟回饋是否對等：制度公平、貢獻被看見時，他會主動多扛一點；長期看不到相應回應時，他照樣把份內做完，卻不再多加碼。遇到分工不清、功勞歸屬模糊的專案，他的輸出品質不會掉，額外的主動性卻會先收起來，等看到公平訊號再放出來。管理上，把貢獻與回饋的對應關係說清楚，能讓他在穩定輸出之外也願意多投入一點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2856, 'CIA_27', 'B (中)', 'CIA_25', 'C', '與 CIA_25 (集體意識) 低分聯動：表現為「先顧自己份、看對等再加碼的合作者」。他對團隊任務的投入不算高，更在意自己要做什麼、能拿到什麼，責任邊界一旦模糊就容易退到最低配合。他對付出與回報是否對等也很敏感：制度把貢獻和獎酬對得清楚、能看到相應回饋時，合作意願會提升，願意多接一點份外的事；貢獻被集體目標蓋住、難以被單獨看見時，他傾向只做最低限度。面對需要多扛一點的場合，他不會主動請纓，而是先確認自己的付出有沒有機會被算進回報，才決定要不要多接。管理上，把個人任務範圍與對應報酬拆得越清楚，越容易讓他從被動配合轉為主動投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2857, 'CIA_27', 'B (中)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) 高分聯動：表現為「有熱情、但仍會算對等的投入者」。他對工作本身有明顯熱情，常主動多做一點、想把成果做得更好，工作能量看起來很充足。他也在意努力有沒有被對等看見：遇到制度公平、被看見的情境，投入會再往上加一階；長期只有付出、看不到相應回應時，熱情會慢慢降溫，變成把事做完就好。在草創或資源緊的階段，只要看得到公平對待的訊號，他仍願意先衝一段；一旦感覺自己持續墊底承擔卻沒被對等看待，動能會明顯縮回。管理上，及時給予對等回饋與肯定，能讓他的熱情維持在較高水位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2858, 'CIA_27', 'B (中)', 'CIA_02', 'C', '與 CIA_02 (成就動機) 低分聯動：表現為「看對等給多少、就給多少的達標者」。他做事習慣把工作完成在合理範圍內，不特別追求更高難度或額外突破，動能多半跟著環境要求走。他把「做到位就好」的標準拿捏，也看付出跟回報是否對等：制度公平、回饋看得到時，他會多撐一點、標準跟著拉高；沒有對等訊號時，他守住基本份內，不主動加碼挑戰。面對額外任務，他會先看有沒有相應的認可或條件再決定要不要多做，很少單純只想多突破自己就去承擔更多。管理上，把額外投入與對應回饋掛勾清楚，比單純要求他挑戰更高目標更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2859, 'CIA_27', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「下手前先盤算划不划算的審慎者」。他做決定前習慣先評估風險、假設與可能後果，很少因一時判斷就返工，在資訊不齊的情況下也能維持判斷品質。他也會先看清楚投入跟回饋對不對等：制度公平、看得到相應條件時，他才會答應多扛額外的事；沒把握對等時，他寧可先觀望、不急著表態。遇到需要當場決定是否多幫忙的場合，他不會馬上答應，而是先估算清楚，一旦確認公平合理，投入程度才會明顯提升。管理上，把額外付出的回饋機制先講清楚，能讓他更快做出願意多投入的決定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2860, 'CIA_27', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「不公平感一來就衝、公平了就回穩的人」。他情緒比較容易被牽著走，遇到壓力或不順會出現衝動回應、倉促答應或行為過頭的情況，事後常常還要花時間修補或解釋。他也很在意付出跟回報是否對等：制度公平、努力被相應看見時，合作意願會提升，願意多投入；一旦覺得自己吃虧、沒被對等對待，情緒會先冒上來，話可能說得比較衝，當場就表態不想再多做。在資源分配不透明的場合，他容易先被「這樣公平嗎」的念頭點燃，反應速度比想清楚後果還快，事後才回頭解釋自己的立場。管理上，把公平的判斷標準與回饋講在前面，能讓他少一點衝動表態、多一點穩定投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2861, 'CIA_27', 'B (中)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) 高分聯動：表現為「利益當前守分寸、也記得算帳的人」。即使利益或目標很明顯擺在眼前，他仍能維持誠懇與公正，不會過度追逐財富、地位或特權，也很少佔別人便宜。他也在意付出跟回報是否對等：制度公平、貢獻被相應看見時，投入與合作意願會提升；看不到對等訊號時，他不會用不誠實的手段去爭取，而是傾向收斂投入、只做基本份內。遇到資源有限的競爭情境，他不會靠炫耀或算計去多拿一份，但也不會一直單方面付出，而是先觀察公平與否，再決定要不要繼續加碼。管理上，把分配規則與回饋標準做到公開透明，能讓他更願意主動多投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2862, 'CIA_27', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「精明的績效導向者」。追求成功，但每一步都要求相對應的報酬。管理警示：若制度無法提供「即時且優渥」的反饋，其動能會迅速消失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2863, 'CIA_27', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「風險與收益的精算師」。在投入任何心力前會先精密估算 ROI。預測：極少做白工，但也可能因此錯失需要先行投入的創新機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2864, 'CIA_27', 'C (低)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「情緒化的計較者」。一旦感到分配不公，會立刻表現出憤怒或消極怠工，情緒反應極大且難以安撫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2865, 'CIA_27', 'C (低)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「利己主義者」。不僅計較獲得，還可能為了獲取更多而犧牲他人或組織利益。風險預測：是潛在的誠信風險對象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2866, 'CIA_27', 'C (低)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「心灰意冷的離職預備軍」。在挫折中感到不公平時，修復能力極差。警示：一旦其心裡那把「秤」失衡，會很快進入安靜離職（Quiet Quitting）狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2867, 'CIA_27', 'C (低)', 'CIA_32', 'A', '與 CIA_27 (權益公平感) C 與 CIA_32 (心理特權) A：表現為「職場霸凌或特權索求者」。認為付出是應得的，但回報必須遠超常人。管理風險：會破壞團隊的和諧與公平認知。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2868, 'CIA_27', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「戴著面具的交易者」。表面客氣，實則內心精密計算每一分得失。警示：通常在離職那天主管才發現其對薪資或福利積怨已久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2869, 'CIA_27', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「易怒的維權者」。對微小的不公（如午餐津貼少了十元）會有極大的負面情緒反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2870, 'CIA_28', 'A (高)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「團隊的向心力來源」。不僅認同團體，且會公開表達對同事協助的感激。預測：能極大化團隊成員的心理回報感，降低離職意願。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2871, 'CIA_28', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「真誠的共感者」。能敏銳感知他人的付出並給予溫暖回饋。管理建議：適合作為團隊領導者或 HR，能營造極佳的工作氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2872, 'CIA_28', 'A (高)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) A聯動：表現為「良性循環的發動機」。樂於付出且感激所得，不會斤斤計較。預測：在資源有限的環境下，仍能保持正向積極的心態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2873, 'CIA_28', 'A (高)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) C聯動：表現為「純粹的感恩者」。其感激是發自內心的珍惜，而非社交辭令。預測：其建立的人際關係極為穩固且深厚，具備高度信任度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2874, 'CIA_28', 'A (高)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「高韌性的樂觀派」。習慣從挑戰中看見學習的機會與他人的幫助。行為預測：面對挫折時復原極快，且能帶動團隊維持士氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2875, 'CIA_28', 'B (中)', 'CIA_25', 'A', '與 CIA_25 (集體意識) 高分聯動：表現為「感謝留在心裡、先扛團隊事的協調者」。他習慣先把個人方便放到團隊目標之後，遇到補位、協調資源這類事會主動接下來，不太計較功勞算誰的。有人幫他扛了額外工作，他心裡清楚記得這份人情，但當下常常直接把注意力轉回下一件要協調的事，沒有特地停下來說謝謝。要等到專案收尾、正式檢討這類時間點，他才比較會把某人當時的付出明確講出來。平常共事的人不一定感覺到被感謝，看到的多是他一直在張羅團隊整體的事；管理上安排定期的回顧或表揚時刻，能讓他有機會把心裡那份謝意說出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2876, 'CIA_28', 'B (中)', 'CIA_26', 'C', '與 CIA_26 (同理心) 低分聯動：表現為「把協助記成進度、沒接住背後心情的人」。他對『誰幫忙推進了事情』記得清楚，會知道某個環節之所以順利是有人多做了一步，但這份記憶留在心裡比較像任務資訊，不太延伸去想那個人當下可能希望被看見或聽到一句肯定。互動時他的注意力多半放在下一步要做什麼，不容易接住那個人沒說出口的期待或情緒訊號，協助往往就這樣被收進流程裡，沒有被特別標出來說謝。等到某次成果特別亮眼、或有人明講提起，他才會比較明確地表達謝意。長期下來共事者可能覺得付出沒被看見；管理上若能建立固定的成果盤點或感謝儀式，可以補上他平常不容易主動接住的那個提醒點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2877, 'CIA_28', 'B (中)', 'CIA_27', 'A', '與 CIA_27 (權益公平感) 高分聯動：表現為「先讓利算長期帳、謝意留到後頭說的人」。面對合作裡的付出與回報，他不太會斤斤計較當下誰吃虧；遇到需要有人先讓一步、多扛一點責任才能把整體目標往前推，他傾向自己先接下來。當有人接住他讓出來的部分、給予相應的支持，他心裡會記下這份互惠，但不一定當場說出口，反而先把心力放回怎麼把事情繼續往前推。要到合作告一段落、或被明確問起這段過程時，他才比較會具體點出當時是誰接住了、幫了什麼忙。共事的人可能只看到他一直在讓利、卻感受不到被感謝；管理上若能在合作收尾時安排明確的致謝環節，能讓他把心裡那份對等的感謝實際說出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2878, 'CIA_28', 'B (中)', 'CIA_33', 'C', '與 CIA_33 (社會期望反應) 低分聯動：表現為「謝意不包裝、少說但說了算真的人」。他不太會為了讓場面好看而多講場面話，被人幫忙時，心裡對這份幫助的份量有數，但不會刻意加油添醋去表達，甚至常常就這樣先擱著沒說。真的開口道謝的時候，用詞通常樸素直接，不刻意堆砌感性字句營造感動氣氛，也不會誇大自己的感受去討喜。遇到有人問起某件事做得如何，他給的回饋維持一貫的老實態度——該說謝就說，沒到位的地方也不會用場面話蓋過去。共事的人得到的感謝雖然不多，但每一句聽起來都可信，不像客套；管理上不需要特別提醒他『講好聽話』，反而該給他明確的時機與理由開口，才更容易讓他把心裡真實的謝意講出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2879, 'CIA_28', 'B (中)', 'CIA_15', 'A', '與 CIA_15 (心理資本) 高分聯動：表現為「挫折當下先往前衝、感謝話晚點才補的人」。遇到卡關或計畫被打亂，他不容易被打垮，心裡多半相信這件事有辦法處理，很快就把注意力轉向下一步該怎麼做、還有哪些路可以試。過程中如果有人拉了他一把、給了關鍵的資訊或支持，他心裡清楚知道這份幫助起了作用，但當下的重心還是放在把問題解決，來不及或沒特地停下來說謝。等到事情真的度過難關、回頭盤點這段經過時，他才比較會明確講出當時是誰幫上了忙、幫在哪個點上。共事者可能只看到他一路保持動能往前衝，沒感受到自己的付出被特別提起；管理上若在階段性復盤時特地留一個環節問『這段誰幫了忙』，能讓他把累積的感謝具體說出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2880, 'CIA_28', 'B (中)', 'CIA_32', 'C', '與 CIA_32 (心理特權) 低分聯動：表現為「不覺得該得、心裡記帳但嘴上少說的人」。他對資源怎麼分配、規則怎麼定，通常不會覺得自己應該例外或該拿到比較好的待遇，該照流程來就照流程來，不太會用身份或資歷去要額外的東西。他不預期自己該得到什麼，遇到有人額外幫了忙、多給了資源或方便，這份好意在他心裡份量清楚，但不一定馬上化成一句感謝說出來。他比較常見的反應是把這份人情記在心裡、之後用實際行動回補——比如換他能出力的時候多做一點，而不是急著先講一句謝謝。共事的人可能感受到他做事很到位、很願意回饋，卻不一定聽到明確的道謝；管理上若能明確肯定他『做得對、做得好』，也順帶提示這是被感謝的時刻，能幫助他把心裡的謝意用話講出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2980, 'CIA_34', 'A (高)', 'CIA_35', 'C', '與 CIA_35 (生活熱情) C聯動：表現為「典型的工作狂 (Workaholic)」。生活重心極度向工作傾斜。管理警示：雖短期產能極高，但需強制其休息以避免長期健康受損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3076, 'ANI_03', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「敏捷的決策指揮」。決策快且具備應變力，能在資訊變動時果斷修正決策路徑，避免組織陷入路徑依賴（Path Dependence）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2881, 'CIA_28', 'B (中)', 'CIA_11', 'A', '與 CIA_11 (誠懇) 高分聯動：表現為「謝意不當工具、真心才開口的人」。他跟人溝通時傾向把資訊攤開來講，不太會為了讓場面順利而說一些違心或誇大的話，該說的就直說，不繞彎子去經營別人的觀感。有人幫了忙，他心裡會記得這件事的份量，但不會拿感謝當作維繫關係的工具去頻繁掛在嘴邊；沒特別說出口，單純是還沒到他覺得需要講的時候，不是在算計什麼。真的開口道謝時，講的內容通常對得上實際發生的事，不會為了讓氣氛好而把功勞誇大或講得比實際更感動。共事的人得到的感謝不頻繁，但可以相信每一句都是真的；管理上不需要教他怎麼講好聽話，反而該給明確的時機讓他知道現在適合把心裡的謝意講出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2882, 'CIA_28', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「理所當然的索求者」。認為他人的幫助是應得的，極少表達謝意。警示：會迅速消磨團隊的合作熱情，導致周遭同事產生被剝削感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2883, 'CIA_28', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「功利的表演者」。僅在對自己有利時才表現出感謝。風險預測：其人際關係往往是短暫且具備目的性的交易關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2884, 'CIA_28', 'C (低)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「自我中心的攀登者」。極度關注個人目標與成功，容易忽略過程中他人的支援與貢獻。管理警示：容易造成「收割成果」的負面印象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2885, 'CIA_28', 'C (低)', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「計較的分配者」。更在意自己「沒得到什麼」而非「得到了什麼」，容易對現狀感到不滿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2886, 'CIA_28', 'C (低)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「傲慢的專家」。將成功完全歸功於個人能力，忽視環境因素與同儕協助。管理風險：難以聽取他人建議，協作難度高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2887, 'CIA_29', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「目標導向的社交家」。能為了達成商業目標而精準調整與不同利害關係人的溝通風格。預測：極具商務談判潛力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2888, 'CIA_29', 'A (高)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「圓滑的談判專家」。在社交適應的同時保持警覺與風險意識。管理建議：適合作為高階採購或涉及重大利益的外部對接人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2889, 'CIA_29', 'A (高)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「變色龍般的操縱者」。具備極高的適應力但動機不純。警示：能輕易贏得各方信任，但需警惕其利用社交技巧進行政治操弄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2890, 'CIA_29', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的推客」。能向不同部門的保守者推銷創新的點子，透過調整語境降低變革阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2891, 'CIA_29', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「高 EQ 的和諧大師」。既能感同身受（同理），又能靈活應對（適應）。預測：是組織中處理人際衝突、建立跨部門信任的靈魂人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2892, 'CIA_29', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「優雅的權利追求者」。雖然內心自負，但懂得透過社交手段（偽裝適應）來獲得其想要的特權待遇。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2893, 'CIA_29', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「熟圈衝刺、生疏圈摸底的進取者」。在熟悉的團隊或風格相近的人之間，他很快就能抓到互動節奏，同時對成果抱有明確企圖心，會主動拉高標準、找更好的做法往前推進。換成風格差異很大的人，他對結果的追求不會鬆懈，但得先摸清楚怎麼跟這群人打交道，才能把升級方法的動作用對地方。這段摸索期間，他可能已經想好更高標準的做法，卻還沒抓到用什麼方式讓不熟悉的人接受，時常需要先繞一圈建立基本互動默契。管理上宜在他面對新風格對象時給一段觀察期，並協助搭建初步互動橋樑，讓他的企圖心能盡快找到施力點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2894, 'CIA_29', 'B (中)', 'CIA_03', 'C', '與 CIA_03 (審慎) 低分聯動：表現為「熟悉圈手快、陌生圈易踩雷的行動者」。與熟悉或風格相近的人相處時，他反應快、切入直接，很少花時間反覆評估就能自然對上互動節奏，把事情往前推。遇到差異很大的人，他還是習慣先出手、先試著互動再看情況調整，而不是先花時間摸清楚陌生對象的風格——這種先做再說的節奏，用在還沒摸熟的人身上，容易踩到自己沒預期的互動地雷，事後才發現需要補救。他的行動力沒有因為對象陌生而放慢，反而常常是先撞了一次才知道要調整方式，補救動作因此變得更頻繁。管理上宜提醒他面對陌生風格的人時先做簡單觀察再出手，並在關鍵場合預留補救空間，降低隱性風險的累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2895, 'CIA_29', 'B (中)', 'CIA_11', 'A', '與 CIA_11 (誠懇) 高分聯動：表現為「熟圈順手、生疏圈慢磨的直率者」。在熟悉或風格相近的人之間，他互動起來很自然，說的話直接、真實，靠實際資訊就能快速建立合作基礎。遇到差異很大的人，他不會為了盡快拉近距離而刻意包裝自己或說討喜的話，還是照原本直來直往的方式提供真實資訊，只是在還沒摸清楚怎麼跟這類對象互動之前，這種直接有時顯得生硬、不夠圓融。他寧可花時間慢慢磨合出更自在的互動節奏，也不會靠話術或討好手段加快腳步。管理上可以讓他知道生疏期的直率不需要修飾，同時提醒他不同風格的人接受直接溝通的步調不同，適時給予緩衝時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2896, 'CIA_29', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「熟路沿用、生疏圈先觀望的磨合者」。與熟悉或風格相近的人互動時，他有一套用慣的方式，照舊模式打交道就能維持不錯的合作品質，不太需要另外想新招。遇到差異很大的人，原本熟悉的互動方式不一定管用，但他不會急著嘗試新的相處手法，反而傾向先觀望、看看類似風格的人一般怎麼互動，等看出一點頭緒後才願意調整做法。這種先觀察再行動的節奏，用在陌生風格對象身上會比較保守，磨合期拉得比較長，但一旦找到能重複使用的互動模式，就能穩定沿用下去。管理上宜在他接觸差異大的對象前，先提供一些互動參考範例，減少他從零觀望摸索的時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2897, 'CIA_29', 'B (中)', 'CIA_26', 'A', '與 CIA_26 (同理心) 高分聯動：表現為「熟圈讀心快、生疏圈慢熱的同理者」。在熟悉或風格相近的人身上，他很快就能抓住他人的感受脈絡，用貼近的語氣回應，互動起來自然順暢。遇到差異很大的人，他理解他人處境與感受的能力並沒有消失，但因為還不熟悉這類對象的參考架構，一開始要抓準該用什麼語氣、怎麼回應會需要多花心思，容易先猜錯方向。等他透過幾次互動累積出對這類人的理解後，原本的同理能力才能重新對上、精準地調整語氣與回應方式。管理上宜在他接觸陌生風格對象初期，主動提供一些背景資訊或觀察機會，讓他能更快建立起可用的理解框架。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2898, 'CIA_29', 'B (中)', 'CIA_32', 'C', '與 CIA_32 (心理特權) 低分聯動：表現為「不求特殊待遇、自行補落差的融入者」。與熟悉或風格相近的人共事，他不需要特別的照顧或安排，靠實際做出來的東西就能自然融入、換得應有的合作對待。遇到差異很大的人，互動節奏變慢、需要花更多時間摸索怎麼相處，但他不會因此要求特殊通融或額外的資源配合，還是照一般規則和分配方式來，靠自己多花的心力慢慢補上磨合的落差。他不會把互動不順歸咎於環境虧待他，而是把這段適應期當成自己該投入的成本。管理上可以在他適應差異大的對象時給一點耐心與空間，不需要額外的特殊安排，他自己會用實際投入把落差補齊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2899, 'CIA_29', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「任務穩定、互動慢熱的自律者」。面對熟悉或風格相近的人，他做事一貫要求自己，會主動盯進度、顧品質、收尾也不用催，同時互動起來也順手，兩邊都不太需要別人操心。遇到差異很大的人，他在任務上的自我要求沒有跟著鬆動，還是會準時盯進度、把品質和收尾顧好，可是互動這一塊需要額外時間摸索——他能準時交出可靠的成果，卻不一定能同步跟這類對象建立起自在的合作節奏。這種任務穩定、互動仍在磨合的落差，看在外人眼裡容易被誤讀成他跟這類對象處得不夠好，實際上他只是還沒抓到互動的方式，工作本身從未打折。管理上可以放心把任務品質交給他自己把關，同時額外留意他跟差異大的對象之間的互動磨合，適度給予引介或緩衝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2900, 'CIA_29', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「耿直的模範生」。做事極其到位但做人缺乏彈性，容易在與「風格不合」的同事協作時產生嚴重摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2901, 'CIA_29', 'C (低)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「木訥的正人君子」。堅持原則且不屑於社交包裝，這類人值得信賴但可能在複雜的職場政治中被邊緣化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2902, 'CIA_29', 'C (低)', 'CIA_14', 'A', '與 CIA_14 (謙虛) A聯動：表現為「隱形的技術專家」。不愛社交也不愛表現，傾向於窩在自己的舒適圈。管理建議：適合獨立技術鑽研，不宜負責外務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2903, 'CIA_29', 'C (低)', 'CIA_28', 'A', '與 CIA_28 (感謝) A聯動：表現為「內斂的知恩者」。內心感激他人但不知如何適當地表達或與人互動，導致其社交意圖常被誤解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2904, 'CIA_29', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「人際火藥桶」。社交適應度低且情緒控制差，易因他人的行為不符預期而直接爆發衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2905, 'CIA_30', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「終極執行者」。不僅做事細心，且對結果負百分之百的責任。預測：是組織中最不需要追蹤進度的員工，其承諾即等於結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2906, 'CIA_30', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「熱血的救火隊」。雖行為易衝動出錯，但出錯後會第一時間承擔並拼命補救。管理建議：應肯定其擔當，同時輔導其降低出錯率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2907, 'CIA_30', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「零瑕疵的承諾者」。對自己要求極高，且決不容許因個人疏忽導致計畫失敗。預測：產出品質極高，但心理壓力極大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2908, 'CIA_30', 'A (高)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「職場清流」。堅持正道且對行為後果負責。預測：在面對利益誘惑或灰色地帶時，能基於強烈的責任感與道德感守住底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2909, 'CIA_30', 'A (高)', 'CIA_18', 'A', '與 CIA_18 (韌性) A聯動：表現為「不倒的基石」。在逆境中不僅能自保，還會因為自覺有責任「把事做好」而撐起團隊。管理建議：適合擔任關鍵專案的負責人（Owner）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2910, 'CIA_30', 'A (高)', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) C聯動：表現為「結果導向的破局者」。不在乎死板流程，甚至會為了確保「事情做好」而微調規則。預測：雖有違規風險，但其初衷是為了達成最終目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2911, 'CIA_30', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「看邊界決定承擔的自律者」。他對自己的產出標準一向穩定，進度、品質與收尾都能自己盯著走，不太需要人在後面催。責任範圍講清楚時，他會把整件事扛下來、一路盯到完成，過程中也會自我檢查。一旦分工模糊或該負責的界線和實際權限對不上，他仍然把自己份內顧好，卻會在灰色地帶放慢腳步、不主動跨過去接手。管理上宜在交辦前先把範圍切清楚，讓他的自我要求有機會轉成完整承擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2912, 'CIA_30', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「情緒衝動的界線型承擔者」。責任範圍講清楚時，他會把該做的事穩穩接下來、一路做到收尾。但情緒一上來，他有時話會先衝出口——當場攬下一句承諾、用比較衝的語氣回應，說完才回頭想這件事到底該不該算他的。分工模糊的場合最容易出狀況：他可能在界線還沒講清楚前就先衝動應下，事後才發現權責對不上，得花力氣解釋或收拾殘局。管理上宜在他情緒正熱時先緩一步、等界線確認後再定案，讓他的承諾建立在清楚的責任範圍上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2913, 'CIA_30', 'B (中)', 'CIA_07', 'A', '與 CIA_07 (完美主義) 高分聯動：表現為「邊界內求無瑕的完美者」。責任範圍清楚時，他不只是把事情做完，還會一再檢查、反覆打磨到挑不出毛病，交出去的東西經得起檢驗。這股對品質的堅持，在他認定屬於自己的範圍內特別明顯，細節、收尾都不放過。一旦分工模糊、看不清楚哪塊算他負責，他反而容易縮手——不確定自己有沒有資格去改動不明確歸屬的部分，那份講究只能卡在邊界外，沒有出口。管理上把責任範圍先劃清楚，能讓他把追求無瑕疵的力氣，全部投在真正屬於他的產出上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2914, 'CIA_30', 'B (中)', 'CIA_13', 'C', '與 CIA_13 (公正性) 低分聯動：表現為「模糊地帶挑邊站的爭先者」。責任範圍講清楚時，他會把自己那塊扛起來、做到位，不會拿「不清楚」當藉口閃避。想要往前衝、爭取領先的念頭一直都在，遇到能搶快、搶功的機會，他傾向先出手，也容易把佔到便宜的做法解釋成情勢所需。分工模糊或責任歸屬有爭議時，他挑位置的方式往往偏向對自己有利的一邊——含糊地帶的功勞他願意認，含糊地帶該扛的責任他卻不急著主動攬過來。管理上需要把權責與功勞歸屬都寫清楚，並在分工模糊處主動指派，縮小他能往對自己有利方向解讀的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3017, 'CIA_36', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「情緒上頭仍收得了尾的人」。他平常任務推進穩、能自己盯進度顧收尾；被誤解、時間壓力或連續失敗這類觸發點一來，情緒先衝上來，但他手上在做的事不會跟著散掉，會邊繃著情緒邊繼續把該收的尾收好。事後情緒退了，他會回頭把剛剛衝口而出的部分修正掉。管理上可以放心把有明確收尾點的任務交給他，即使中途踩到他的觸發點，進度品質仍有基本保障。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2915, 'CIA_30', 'B (中)', 'CIA_18', 'A', '與 CIA_18 (韌性) 高分聯動：表現為「先回穩、待指派的補救者」。事情在他清楚負責的範圍內出了狀況時，他很快就能從挫折或衝突的情緒裡回過神，把力氣轉去修正錯誤、把後續補救做好，不會卡在情緒裡太久。這種回彈的速度，不管遇到多大的打擊都差不多穩定。碰到分工模糊、責任歸屬還沒講清楚的失誤，他一樣很快恢復平靜，卻可能因為不確定該由誰出手補救而暫時按兵不動——復原的力氣有了，卻找不到明確的地方擺。管理上宜在出狀況後盡快釐清誰該接手補救，讓他剛回穩的狀態能及時轉成實際行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2916, 'CIA_30', 'B (中)', 'CIA_22', 'C', '與 CIA_22 (紀律遵循度) 低分聯動：表現為「靠前例與範圍才順暢的執行者」。規則講明白、方法有前例可循時，他做事很順手，照著既定路徑推進、效率高也少出錯。責任範圍講清楚的時候，他一樣穩穩把該做的部分接下來完成，不用人多交代。遇到流程本身沒有前例、又拿不準這塊算不算自己該接手的場合，他會愣在原地，寧可等別人先示範做法、或等有人明講這件事該由誰扛，也不會貿然自己拿主意往前衝。管理上宜盡量提供既有做法可依循，並把交辦範圍講清楚，讓他拿到清楚的路徑與範圍後能重新順暢地推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2917, 'CIA_30', 'B (中)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) 高分聯動：表現為「有能力卻等界線才出手的人」。面對困難或不熟悉的挑戰，他很少因為懷疑自己做不做得到而卻步——他相信憑自己的能力和判斷可以找到方法往前推進。責任範圍講清楚時，這份自信直接轉成主動承擔，事情一到手就開始動手處理，不太需要人先給保證。分工模糊、搞不清楚這件事到底輪不輪得到他管的時候，他的猶豫跟能力無關——他知道自己做得來，卻拿不準該不該伸手，於是選擇先等界線明朗，不急著自己出手證明。管理上可以放心把有挑戰性的任務交給他，但務必同時講清楚範圍，讓他把那份自信用在對的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2918, 'CIA_30', 'C (低)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「推諉的天才」。自認能力強，因此一旦出錯，會傾向於歸咎環境、系統或同事太笨，而非自我反省。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2919, 'CIA_30', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「滑頭的操縱者」。擅長透過文字遊戲或社交技巧規避責任，發生問題時總是第一個「消失」或「撇清」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2920, 'CIA_30', 'C (低)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「樂天的甩鍋者」。遇到問題不覺得是大事，樂觀地認為「船到橋頭自然直」，導致問題持續擴大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2921, 'CIA_30', 'C (低)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「依賴團體的成員」。認同團隊但缺乏個人當責感，習慣躲在集體決策背後，缺乏獨立承擔的勇氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2922, 'CIA_30', 'C (低)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「職場巨嬰」。認為自己應得一切，但不願為任何失敗負責。警示：極度破壞團隊士氣，需建立明確的 KPI 責任制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2923, 'CIA_31', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「進取型精英」。追求成功的同時，將自我提升視為達成目標的必要路徑。預測：會主動尋求回饋並迅速修正弱點，成長速度極快。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2924, 'CIA_31', 'A (高)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「謙遜的求知者」。雖對目前能力缺乏信心，但具備強烈變強的渴望。管理建議：是最佳培訓對象，只要給予資源，其回報率極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2925, 'CIA_31', 'A (高)', 'CIA_16', 'A', '與 CIA_16 (希望) A聯動：表現為「願景實踐者」。不僅渴望成長（31），且具備設計成長路徑的能力（16）。預測：能自我規劃職涯路徑，不需要組織過多干涉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2926, 'CIA_31', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「終身進化的變革者」。將創新視為一種學習與成長的機會。預測：在技術更迭極快的產業中，能始終保持競爭力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2927, 'CIA_31', 'A (高)', 'CIA_23', 'A', '與 CIA_23 (獨創性) A聯動：表現為「尋求獨特發展的創意人」。渴望發展出具備高度個人特色與原創性的技能體系。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2928, 'CIA_31', 'A (高)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「自律的修煉者」。基於責任感認為自己有義務「變得更好」以應對工作。預測：是組織內部轉型、接班人計畫的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2929, 'CIA_31', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「待點火的進取者」。他對成果與表現有明顯企圖心，看到可以做得更好的空間就想多投入、把標準往上拉一截。但把這份企圖心轉成「我要怎麼讓自己變得更強」的具體行動，往往要等有人指出路徑、或制度提供明確的下一步才會真正動起來；沒有這層引導時,那股想拚的勁道多半用在把手上任務做好,而不會延伸成主動規劃自我成長。一旦看到清楚的學習路徑或有人推一把,他能把追求卓越的動力接上去,投入度明顯提升。管理上宜替他把「變更強」這件事拆成可見步驟、搭配回饋點,他的企圖心會順勢轉為持續投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2930, 'CIA_31', 'B (中)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「缺乏底氣的成長候選人」。他對改變自己、學新東西並不排斥,但心裡常懷疑自己是否真的做得到,遇到不確定的新領域容易遲疑,想先看到別人怎麼做或等人給明確指示才敢跨出第一步。若沒有人引導、也看不清具體路徑,他傾向留在熟悉的做法裡,成長的念頭就懸在那裡沒有落地。反過來,當有人明確告訴他「這樣做、這是下一步」並且給予安全感,他願意投入去嘗試改變。管理上宜提供結構化的引導與具體示範,先幫他建立「我做得到」的信心基礎,他的成長意願才有機會轉成實際行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2931, 'CIA_31', 'B (中)', 'CIA_16', 'A', '與 CIA_16 (希望) 高分聯動：表現為「領路即啟動的規劃者」。一旦有明確的方向或有人點出可以努力的目標,他很擅長把那個目標具體化,還能同時想好幾條路徑,遇到卡關時懂得改道而不輕易放棄。但若沒人先把「該往哪裡成長」這件事定調,他自己主動去發掘、設定成長目標的動能相對有限,容易停在原地等訊號。制度推動或主管給出清楚方向時,他能迅速把那份規劃能力全用上,並展現出遇阻不放棄的續航力。管理上宜由外部先給定成長方向與初步框架,他就能接手把路徑走完、走出替代方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2932, 'CIA_31', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「照樣板前進的學習者」。他對自我提升這件事保持開放,但不會自己去摸索一套新做法或挑戰既有的成長模式,更傾向照著別人已經驗證過的路徑走。有人引導、有明確的學習框架時,他會照著步驟穩定投入;但要他自己開創一條前所未有的成長路線,動能明顯不足,容易停在觀望。在制度化培訓或有導師帶領的情境裡,他表現穩定;但少了外部方向時,連「該往哪裡努力」都不容易自己定出來。管理上宜提供成熟、明確的成長方案而非要求他自創路徑,他會更願意投入且維持得住節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2933, 'CIA_31', 'B (中)', 'CIA_23', 'A', '與 CIA_23 (獨創性) 高分聯動：表現為「解題有創意、成長靠指引」。面對手上的具體問題,他常能跳脫既定做法、想出另類角度的解法,原創想法輸出得算頻繁。但這份對「問題」的創意,不會自動延伸到「如何讓自己變得更好」這件事上——沒有人指出清楚的成長路徑或制度推動時,他把腦力都用在解眼前的題,卻不太會主動去設計自己的學習或提升計畫。當有人把成長這件事框成一個具體問題並給出方向,他反而能用同一份原創力去想出適合自己的路。管理上可以把「自我提升」也包裝成一個待解問題丟給他,搭配基本引導,他的解題創意就能轉個彎用在自己身上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2934, 'CIA_31', 'B (中)', 'CIA_30', 'C', '與 CIA_30 (個人責任感) 低分聯動：表現為「檢討素材流失的被動學習者」。出狀況或延誤時,他比較容易把原因歸到外部環境,補救動作也偏被動,不太會主動追根究柢挖出自己該調整的地方。連「哪裡該改」都沒被他自己標出來,若沒有人明確指出問題所在並給出改善方向,他很容易就這樣過去,不會自發去反思調整。一旦有人具體點出他該改進的地方、並提供制度化的改善路徑,他仍願意跟著投入。管理上宜在事後覆盤時直接點名可調整之處,而不是等他自己歸納,才能把成長意願接上實際行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2935, 'CIA_31', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「執行可靠、提升待引導」。日常任務上他自我要求一致,能主動掌握進度、顧好品質與收尾,不太需要人催就能維持穩定輸出。但這份對「把眼前工作做好」的可靠,不會自動變成「主動規劃自己怎麼變得更好」的動力——沒有人指出清楚的成長路徑或制度性的推動時,他多半把精力放在把任務做完做好,而不會另外撥心力去設計自我提升的方向。一旦有明確的成長框架或引導出現,他會用同樣一致的態度投入進去、維持得很穩。管理上宜把「持續提升」也變成一項有具體步驟、有人跟進的任務交給他,他執行上的可靠會直接轉移過去。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2936, 'CIA_31', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「穩定的守成勞動者」。做事負責但拒絕改變。警示：雖能處理現有工作，但若職責範疇發生質變，其適應困難度會極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2937, 'CIA_31', 'C (低)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「停滯的自負者」。認為現有能力已足夠，缺乏進一步發展的動力。管理風險：容易產生職場僵化，甚至抗拒新的數位工具或流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2938, 'CIA_31', 'C (低)', 'CIA_12', 'C', '與 CIA_12 (低物質傾向) C聯動：表現為「利潤導向的現狀者」。對成長本身無感，成長的動力僅來自於金錢激勵。管理建議：需將培訓與獎金掛鉤，否則其學習意願極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2939, 'CIA_31', 'C (低)', 'CIA_15', 'C', '與 CIA_15 (心理資本) C聯動：表現為「心灰意冷的被動者」。對自我發展持悲觀態度，不相信努力可以改變現狀。警示：是組織中典型的「負資產」，需注意其消極情緒擴散。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2940, 'CIA_31', 'C (低)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「單一技能的狂熱者」。對目前的工作很有熱情，但不願意跳出舒適圈去學習跨領域技能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2941, 'CIA_32', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「自負的野心家」。追求高成就，但認為組織必須先給予資源或特權作為前提，若不符合其「高標待過」則拒絕投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2942, 'CIA_32', 'A (高)', 'CIA_08', 'A', '與 CIA_08 (自我勝任感) A聯動：表現為「精英主義者」。極度自信且認為自己應高人一等。管理風險：容易挑戰主管權威，認為既有規範不適用於自己。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2943, 'CIA_32', 'A (高)', 'CIA_10', 'C', '與 CIA_10 (誠實謙遜) C聯動：表現為「掠奪型員工」。不僅追求特權（32），且缺乏謙遜與誠實（10），可能為了獲取特殊利益而損人利己。警示：職場舞弊的高潛在群組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2944, 'CIA_32', 'A (高)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「權力操縱者」。擅長透過政治手段或欺騙來維持其特權地位。風險預測：會破壞團隊的公平競爭環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2945, 'CIA_32', 'A (高)', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「傲慢的索求者」。完全不隱藏自己的優越感，對其他「平庸」的同事缺乏尊重。行為預測：極易引發人際衝突，團隊凝聚力殺手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2946, 'CIA_32', 'A (高)', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「不滿足的貪婪者」。對回報極度敏感，且永遠覺得自己拿得不夠多。管理建議：需建立明確的法制化契約，限制其特權索求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2947, 'CIA_32', 'A (高)', 'CIA_28', 'C', '與 CIA_28 (感謝) C聯動：表現為「忘恩負義的受益者」。視他人的幫助與公司的獎勵為理所當然，完全缺乏感激之心。預測：難以建立長期的情感連結，員工忠誠度低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2948, 'CIA_32', 'A (高)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「職場火藥桶」。一旦未獲得預期的優待，會立刻產生劇烈的挫折感與憤怒情緒，出現被動攻擊行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2949, 'CIA_32', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「論功要賞的衝刺者」。在目標清楚、能看見進展時他會主動加碼投入、把標準往上拉，追求比原訂目標更好的結果。投入越深，他心裡對應得回報的期待也跟著升高，覺得自己拉高的成果理應換來相稱的肯定或待遇。一旦事後回報沒跟上他認定的貢獻程度，會明顯感到不甘心，但通常不會私下鬧脾氣，而是傾向找主管或走既有管道把落差講清楚，要求重新評估。若目標本身模糊或看不到進展指標，這股「該有回報」的念頭會跟著動能一起降溫，變得不那麼在意。管理上宜在交付高投入任務時同步講清楚回報機制，讓他的高標準有明確的對應出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2950, 'CIA_32', 'B (中)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) 低分聯動：表現為「既盼認可又怕擔責的人」。當他自覺這次投入或貢獻確實較多時，會期待相應的認可或回報；但一遇到不確定或高風險的任務，又容易懷疑自己是否真有能力扛住，遲疑不決、想先找人確認方向。他不會為了爭取待遇去硬撐或對抗，回報不如預期時傾向透過正式管道反映，而不是自己出面據理力爭；也常等主管或同事先開口、先給評價，才敢跟著提出自己的期待。管理上宜在他投入明顯時主動給予具體肯定，並在他面對陌生任務時提供確認與支持，讓他既感到被公平對待，也更敢獨立推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3018, 'CIA_36', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「觸發點一來反應連帶衝過頭的人」。他大部分時間情緒穩，一遇到被誤解或連續受挫這類點，反應會冒得快，而且不只是情緒上來，連帶做出的回應也容易衝過頭，脫口而出重話、倉促答應了原本該再想想的事。等情緒退了，他會意識到剛剛講太滿或答應太快，回頭收拾局面。管理上宜在他明顯進入觸發狀態時先按下暫停，避免他在情緒頭上做出的承諾直接生效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2951, 'CIA_32', 'B (中)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) 高分聯動：表現為「論貢獻的公正期待者」。他在一件事上投入明顯較多、或自認貢獻超出份內時，心裡會期待拿到相應的回報或肯定，一旦分配落差太大，會真實感到不服氣。即使如此，他開口爭取時仍照實描述自己做了什麼、投入多少，不誇大成果，也不會拿別人的功勞往自己身上算。遇到資源分配不透明、別人沒特別留意細節的場合，他不會趁機多拿或含糊帶過自己的份量，仍傾向把貢獻攤開來說清楚，走正式管道爭取對等待遇。主管若能在事前講清楚評核標準、事後把貢獻與回報的對應關係說明白，他的不滿會降得快，也比較不會演變成對抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2952, 'CIA_32', 'B (中)', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「會包裝訴求的爭取者」。當他判斷自己投入夠多、貢獻夠大時,會產生對應待遇的期待,而在爭取這份期待時,他不一定完全直來直往,可能選擇性強調自己的付出、淡化其他人的角色,用比較有利於自己的說法去鋪陳訴求。這種包裝多半只在他覺得該拿到的東西沒到位時才會出現,平常投入與回報相稱時他不太需要動用這類手法。回報不足帶來的不滿,他仍會透過正式管道提出,只是提出的方式摻了一點策略性修飾,而不是完全如實陳述。管理上宜在績效與回報對話中要求具體事證,避免單憑他單方陳述做判斷,同時確保制度回應夠即時,減少他需要靠話術爭取的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2953, 'CIA_32', 'B (中)', 'CIA_14', 'A', '與 CIA_14 (謙虛) 高分聯動：表現為「不搶戲但暗自計較的貢獻者」。他不太需要透過壓過別人或大聲宣傳來證明自己的價值,也能自然接受同事的表現被看見、被稱讚。但當自己確實投入較多、承擔較重時,他心裡仍會期待相對應的待遇,這份期待不會用高調的方式表達出來,而是安靜地放在心裡等待被看見。落差出現時他不會爭著搶功或大聲抗議,而是傾向用溫和、留有餘地的方式向上反映,期待制度自己給出公道。外界很難從他平和的態度察覺他其實在意回報,他的付出因此常被輕輕帶過。管理上宜主動詢問、定期核對他的投入與回報是否相稱,不要因為他不爭不搶就假設他沒有期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2954, 'CIA_32', 'B (中)', 'CIA_27', 'C', '與 CIA_27 (權益公平感) 低分聯動：表現為「斤斤計較的敏感付出者」。他對自己付出和拿到的回報是否對等特別敏感,只要感覺自己吃虧,情緒很快就會浮上來。這份敏感在他自覺投入多、貢獻大的任務上更明顯,一旦回報沒有跟上他心中的預期,不滿會來得又快又直接。他不會悶不吭聲,通常會主動提出、要求說法,但仍會走詢問或申訴這類正式管道,而不是私下報復或消極抵抗。若制度反應慢,這種「我是不是吃虧了」的念頭會持續發酵,逐漸侵蝕他的投入意願。管理上宜盡量讓回報機制透明、即時回應他的疑問,避免拖延使他的敏感持續累積、不滿越積越深。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2955, 'CIA_32', 'B (中)', 'CIA_28', 'A', '與 CIA_28 (感謝) 高分聯動：表現為「邊道謝邊記帳的付出者」。他容易看見別人的付出並主動說出感謝,對他人的協助有明確、正向的回應,人際互動上顯得溫暖。在自己投入較多的任務上,他一邊向協助過他的人致意,一邊心裡記著自己付出了多少、期待未來能拿到對應的待遇。回報不到位時他會感到不滿,但不至於翻臉,通常會用溫和但清楚的方式提出訴求,期待透過正常管道獲得回應。旁人常從他頻繁道謝的樣子誤判他對回報毫不在意,直到他實際找上主管談待遇才發現看走眼。管理上宜在肯定他人際貢獻的同時,也具體核對他的投入回報是否對等,避免因他表面溫和而忽略他實際的期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2956, 'CIA_32', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「默默耕耘的典範」。不求特權，只求將事情做好。管理預測：是組織中最穩定、最可靠的「樑柱」，通常具備高滿意度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2957, 'CIA_32', 'C (低)', 'CIA_25', 'A', '與 CIA_25 (集體意識) A聯動：表現為「無私的團隊成員」。願意為了群體利益隱藏自我需求。管理建議：應主動給予這類人應有的獎酬，以免其被高特權者「吃掉」資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2958, 'CIA_32', 'C (低)', 'CIA_30', 'A', '與 CIA_30 (個人責任感) A聯動：表現為「高當責的勞動者」。相信回報源於責任與努力（30），而非身分或特權（32）。預測：具備最健康的績效觀念。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2959, 'CIA_33', 'A (高)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) A聯動：表現為「極度在意形象的正直者」。雖然內在誠實，但會過度修飾言辭以符合社會規範。管理預測：其測評結果可能比真實情況更「完美」，需結合面談觀察。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2960, 'CIA_33', 'A (高)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「高階偽裝者」。具備操縱傾向（11C）且極度在意正面形象（33A）。風險預測：極擅長職場政治，會精準提供主管「想聽的內容」，真實動機難以察覺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2961, 'CIA_33', 'A (高)', 'CIA_24', 'C', '與 CIA_24 (真實性) C聯動：表現為「人設經營者」。其展現的自我高度符合組織期望，但與內在價值觀可能嚴重脫節。警示：離職風險極具隱蔽性，往往在崩潰前一刻都表現得非常配合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2962, 'CIA_33', 'A (高)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) A聯動：表現為「社交變色龍」。適應力強且極度在意他人評價，是極佳的公共關係（PR）或服務業人選，但在內部管理時需警惕其表裡不一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2963, 'CIA_33', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「隱性自負者」。內心認為應享特權，但為了維持良好形象（33A）會掩飾這種索求。管理風險：當其優越感未獲滿足時，會產生嚴重的被動攻擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2964, 'CIA_33', 'B (中)', 'CIA_10', 'A', '與 CIA_10 (誠實謙遜) 高分聯動：表現為「淡泊守分但護形象的坦誠者」。面對利益、地位這類外在誘因，他多半能穩得住，不會為了多拿一點就放寬對自己的要求，這部分的坦然相當穩定；但一牽涉到可能損及形象的提問，例如承認判斷失準或能力有落差，他的用詞會不自覺往漂亮的方向靠。多數時候他談自己的經歷相當如實，遇到敏感、可能損及形象的細節時，卻容易先做一輪修飾再開口，說法會比實際情況更完整、更順。旁人若只聽他自陳，容易低估他在弱點或失誤上的真實狀況；不體面的部分，他很少主動講清楚。要拿到他真實的自我評估，宜避開直接質問式的敏感提問，改用具體事例引導，讓他不需要防衛也能說出實情。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2981, 'CIA_34', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「有意義才點火的進取者」。他對表現與成果有明顯企圖心，遇到挑戰會主動升級方法、拉高目標，這股勁不太受任務類型限制。但真正推著他多投入、願意熬夜打磨的，是那份對工作本身有沒有感覺——任務有意義、能看到回饋時，他的方法越滾越猛，主動加碼做到更高標準；一旦任務淪為單純交差、看不到意義，企圖心還在但少了那股熱度撐著，容易變成技術上做到位、心裡卻沒特別想多走一步。管理上宜替他把目標與意義感綁在一起說明，讓他的進取心有材料可以燒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2965, 'CIA_33', 'B (中)', 'CIA_11', 'C', '與 CIA_11 (誠懇) 低分聯動：表現為「選擇性坦白、伺機包裝的推動者」。多數時候他講自己的狀況算直接，不太需要花力氣掩飾；但只要話題敏感、或涉及重要目標，他心裡會先盤算怎麼講比較有利，再決定要露出多少。面對需要說服別人或爭取資源的場合，他不介意把資訊做過修剪再拿出來，該強調的強調、該淡化的淡化，用詞也會挑對他有利的角度。共事的人若只看他嘴上說的，容易誤以為看到的就是全貌，其實他手上留了一些沒說出口的細節，等時機或立場需要才補上。想確認關鍵資訊的完整度，宜多方求證、不只憑他單方陳述，涉及重大決策時可請他把假設與依據攤開講清楚，降低理解落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2966, 'CIA_33', 'B (中)', 'CIA_24', 'A', '與 CIA_24 (真實性) 高分聯動：表現為「行動忠於自己、口述略修飾的人」。他做事、做決定時相當貼著自己的價值觀走，就算周遭多數人選了另一條路，他也不太會為了合群而臨時改變立場，行動上看得出一致性。但換成要用言語描述自己，尤其是碰到可能顯得不夠好看的部分，他反而會停下來想一下怎麼講，用詞不自覺往比較體面的版本靠，跟他實際行動時的坦然不完全對得上。旁人看他做事，會覺得這人講原則、說到做到；但若只聽他自己講心路歷程，可能拼湊出一個比實際更順、更少掙扎的版本。要理解他的真實狀態，觀察他實際怎麼做會比聽他怎麼描述更準；遇到需要他自我揭露的場合，宜多問具體發生了什麼，少問他覺得自己表現如何。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2967, 'CIA_33', 'B (中)', 'CIA_29', 'C', '與 CIA_29 (人際適應力) 低分聯動：表現為「互動策略固定、自述偏修飾的人」。面對風格差異大的人，他常用同一套打法反覆應對，遇到不熟悉的互動節奏容易繃緊，不太知道怎麼隨對象調整，建立合作要花比較多時間磨合。談到自己時，多數場合他講得算直白；但碰上比較不熟、還在摸底細的人，或話題觸及自己的弱項時，他的說法會不自覺變得更修飾、更謹慎，留一手不把細節說滿。在還不熟悉的場合，他一邊按著固定套路應對、一邊把自己講得比較保留，初次共事的人不容易在短時間內摸清他的真實狀態與底線。要跟他建立互信，宜給多一點時間讓互動自然累積，避免一開始就用直接、逼問式的方式挖細節，等熟悉度提高後他的說法通常會鬆動、更接近實情。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2968, 'CIA_33', 'B (中)', 'CIA_32', 'A', '與 CIA_32 (心理特權) 高分聯動：表現為「自覺該得優待、敘事偏向自身有利的人」。他心裡對自己該獲得的待遇有一套標準，不一定跟他實際投入或做出的成果掛鉤；一旦結果沒達到他預期的水準，反應通常不小，可能當場表態不滿，甚至直接要求對等。事後如果有人問起發生了什麼，多數細節他講得還算符合實情；但牽涉到自己在事件裡扮演什麼角色、有沒有理虧的部分，他敘述時容易把自己講得比較無辜、比較站得住腳。在期待落空的時刻，他一邊直接表現不滿、一邊把整件事的說法微調得對自己有利，旁人事後拼湊經過時容易只看到他選擇呈現的那個版本。處理他的不滿時，宜同步蒐集其他當事人或客觀紀錄做對照，不單靠他事後的敘述判斷是非，也能在他情緒過去後，用具體事實跟他核對細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2969, 'CIA_33', 'B (中)', 'CIA_36', 'C', '與 CIA_36 (情緒易激度) 低分聯動：表現為「處事冷靜、自陳偏修飾的人」。遇到心煩的狀況或正面衝突，他的反應門檻偏高，多半能維持冷靜、把事情攤開來理性處理，很少為了一時情緒做出後續要收拾的決定。談自己的事情時，大部分內容他講得平實可信；只有碰到會牽動個人形象的細節，例如自己判斷失誤或處理不夠好的地方，他的措辭才會不自覺往修飾過的方向調整，語氣也會變得比較保留。跟他討論衝突或問題時，場面通常維持得住，不會演變成情緒對撞；但如果話題繞到他自己該負的責任，他描述的版本可能比實際狀況更平順一些。檢討問題時，宜把焦點放在具體事實與時間線，而不是只聽他口頭總結；他情緒上不容易失控，反而更適合用平和、就事論事的方式，把細節一項項核對清楚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2970, 'CIA_33', 'B (中)', 'CIA_13', 'A', '與 CIA_13 (公正性) 高分聯動：表現為「求勝守規矩、自陳偏理想化的人」。就算很想在競爭或目標上搶先，他也不太會去動歪腦筋，像是誇大、隱瞞關鍵資訊或占別人便宜這類手段，他基本上不碰，比較在意大家玩的是同一套規則。描述自己怎麼做到某個結果時，大部分過程他講得算誠實；但如果內容牽涉到自己曾經考慮過的灰色選項、或某次差一點沒守住底線，他傾向把這段輕輕帶過或說得比較好聽。共事的人多半會信任他在規則上的一致性，畢竟他實際行為對得起這份信任；只是若想從他口中完整還原某次決策的所有考量，可能會漏掉他自己覺得不夠光彩的那一小段。要重建完整的決策脈絡，宜搭配當時的紀錄或其他人的觀察一起核對，而不是只聽他事後的說法；他在規則上的堅持是可以信賴的基礎，補上這一步，還原會更完整。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2971, 'CIA_33', 'C (低)', 'CIA_24', 'A', '與 CIA_24 (真實性) A聯動：表現為「坦蕩的求真者」。完全不在乎包裝，即便缺點也直白坦露。預測：此人的測評結果信效度極高，其呈現的數據即為真實的自我。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2972, 'CIA_33', 'C (低)', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「耿直的刺頭」。不在乎他人認可，也不願調整溝通方式以適應環境。管理建議：溝通成本高，但其反饋通常是最真實的「防腐劑」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2973, 'CIA_33', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「真實的火藥桶」。對不滿情緒毫不掩飾，不會為了維持社交和諧而壓抑怒氣。警示：衝突強度高，需注意其對團隊氛圍的直接衝擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2974, 'CIA_33', 'C (低)', 'CIA_13', 'A', '與 CIA_13 (公正性) A聯動：表現為「鐵面無私者」。即便做法會得罪所有人，也會堅持正確的原則，因為他完全不被「社會期望」所左右。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2975, 'CIA_34', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「充滿激情的攀登者」。不僅想贏，且熱愛競爭與達標的過程。預測：在組織中能產生極大的正面渲染力，是帶動士氣的天然領袖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2976, 'CIA_34', 'A (高)', 'CIA_07', 'A', '與 CIA_07 (完美主義) A聯動：表現為「卓越的工匠」。對細節的苛求源於對工作的熱愛。預測：能產出具備「靈魂」的高品質成果，但在情緒過度投入時需注意燃盡風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2977, 'CIA_34', 'A (高)', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) A聯動：表現為「純粹的職人」。工作動機完全來自內在喜悅而非金錢回報。管理建議：應提供其高度的專業自主權，而非僅靠薪資激勵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2978, 'CIA_34', 'A (高)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「韌性十足的熱愛者」。對工作的熱情使其能以樂觀心態看待挫折。預測：即便在組織動盪期，也能靠著內心對工作的喜愛而維持產能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2982, 'CIA_34', 'B (中)', 'CIA_07', 'C', '與 CIA_07 (完美主義) 低分聯動：表現為「看情境決定要不要多磨的交付者」。他平常更重視推進與交付，細節做到可用就往下一步走，在快速迭代的場合效率不錯，但小錯偶爾會累積。氛圍好、任務讓他有感覺的時候，這種「差不多就好」的傾向會鬆動——他願意多花一點心思把東西磨得更順手，因為此刻在乎的不只是交出去。反之遇到單調、看不出意義的任務，交付優先的慣性完全接管，能用就過、不會多停留檢查。管理上宜留意這種波動，在他明顯投入的任務適度給時間讓他把品質補上，而不是假設他每次都會主動磨細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2983, 'CIA_34', 'B (中)', 'CIA_12', 'A', '與 CIA_12 (低物質傾向) 高分聯動：表現為「為意義燒、不為酬勞燒的人」。他做決策時看重的是意義、成長或關係品質，不太被財富、地位這類外在誘因牽著走，這點不太隨情境變。但這也代表他缺少一個常見的備用動力來源——當任務本身沒有讓他覺得有意義、氛圍也平淡時，加薪或升遷這種誘因不太能把他的熱度拉回來，他就只是把事做完。任務一旦碰上他真正在乎的價值或成長機會，他的投入會明顯拉高，主動花額外時間把事情做深做透，不是為了獎金。管理上宜用意義感、成長機會來溝通任務,而非仰賴獎金或頭銜去催動他。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2984, 'CIA_34', 'B (中)', 'CIA_15', 'C', '與 CIA_15 (心理資本) 低分聯動：表現為「熱度容易被挫折拖垮的人」。他遇到挫折時動能下降得比較明顯,對未來的期待感原本就偏薄弱，容易滑向無力或悲觀。原本任務有意義、回饋看得見時他確實會被點燃、投入拉高，但只要中間卡了一次挫敗，他不只是對這次結果悲觀，剛燃起的工作熱度也跟著熄火，很快退回到「做完就好」的狀態，比一般狀況更難靠下一個好消息把自己拉回來。管理上宜提早介入挫折後的低潮期，用具體且即時的正向回饋幫他把熱度接住，避免一次受挫拖成長期低迷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2985, 'CIA_34', 'B (中)', 'CIA_21', 'A', '與 CIA_21 (效率取向) 高分聯動：表現為「興致夠時最愛破框提速的人」。他一向不喜歡被程序綁住，看到繁瑣步驟會忍不住想從不同角度簡化、抄捷徑求快，這種傾向本身跟任務有沒有意義關係不大。但當任務同時讓他覺得有意思、看得到成果時，他不只是想省事，而是主動去實驗更快的做法、樂在其中地重新設計流程，簡化本身變成一件他享受的事。換成一份單調、看不出意義的差事，他還是會想抄捷徑，但動機變成單純想快點結束，簡化的品質跟用心程度明顯不同。管理上宜把他放在能自主優化流程的任務上，並確保任務本身有東西能吸引他,而不只是丟給他「快做完」的差事。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2986, 'CIA_34', 'B (中)', 'CIA_35', 'C', '與 CIA_35 (生活熱情) 低分聯動：表現為「需要外部火苗才會燒起來的人」。他平常較少靠熱情與活力主動驅動自己，對未來的期待感偏薄弱，容易被動或拖延，需要外部刺激才啟動——這是他偏穩定的底色。任務有意義、回饋看得見、氛圍好的時候，他確實會被點燃、動起來；但這份被點燃的狀態本身不太持久,一旦外部條件轉冷、看不到進展,他很快又退回被動狀態,需要下一個明確的外部訊號才會再度啟動。管理上宜提供明確且持續的外部節奏——具體任務、可見的小里程碑、定期檢核——幫他把偶爾點燃的熱度撐得久一點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2987, 'CIA_34', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「沒感覺也照樣把事做完的人」。他做事有一致的自我要求，能主動掌握進度、顧品質與收尾，較少需要外部催促,這條線幾乎不隨任務有沒有意義而鬆動。真正會變的是他心裡的感受：任務有意義、回饋看得見時，他不只是把事做完，還會多一份主動投入的興致，願意多想一步、多花心思;換成單調乏味的任務，外在表現看起來幾乎一樣可靠、按時交出高品質成果，但那份心裡的熱度已經抽掉，變成純粹靠自我要求撐著往前走。管理上可以放心把穩定性交給他，但若想要他展現更高投入而非僅止於可靠，仍需要替任務找出意義點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2988, 'CIA_34', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「枯燥的紀律執行者」。不愛工作但因盡責而完成任務。管理預測：產出穩定但缺乏創意與主動進取的能量，容易出現職業倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2989, 'CIA_34', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「消極的防禦者」。對工作無感且過於謹慎，傾向於推諉變革。管理風險：容易成為組織轉型中的隱形阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2990, 'CIA_34', 'C (低)', 'CIA_11', 'C', '與 CIA_11 (誠懇) C聯動：表現為「職場僱傭兵」。僅視工作為謀生工具，不惜透過操縱手段獲取最大利益。警示：對組織毫無忠誠度可言，隨時可能跳槽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2991, 'CIA_34', 'C (低)', 'CIA_27', 'C', '與 CIA_27 (權益公平感) C聯動：表現為「計較的打工仔」。不愛工作且對回報極度敏感。管理預測：稍有不公便會立刻消極怠工，管理成本極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2992, 'CIA_34', 'C (低)', 'CIA_31', 'A', '與 CIA_31 (個人成長動機) A聯動：表現為「迷惘的求學者」。渴望成長但目前的工作並非其所愛。管理建議：應評估其崗位適配性（Job Fit），考慮內部調動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2993, 'CIA_35', 'A (高)', 'CIA_02', 'A', '與 CIA_02 (成就動機) A聯動：表現為「充滿生命力的開拓者」。不僅想贏，且過程中充滿感染力，能讓追隨者感到振奮。預測：極佳的業務與團隊領袖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2994, 'CIA_35', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「熱情的火藥桶」。雖然活潑積極，但因活力過盛且缺乏控制力，容易在人際互動中顯得過於突兀。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2995, 'CIA_35', 'A (高)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「陽光的韌性者」。即使在逆境中也能靠著天生的熱情找到樂趣。預測：復原力極強，是組織內部最不容易心理受挫的群體。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2996, 'CIA_35', 'A (高)', 'CIA_20', 'A', '與 CIA_20 (創新力) A聯動：表現為「變革的發電機」。對新想法展現出純粹的熱愛，能以強大的動能推動從未嘗試過的專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2997, 'CIA_35', 'A (高)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「溫暖的能量散播者」。其熱情是利他的，能帶動同僚共同追求更美好的生活與工作目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2998, 'CIA_35', 'A (高)', 'CIA_34', 'A', '與 CIA_34 (工作熱忱) A聯動：表現為「職業與生活高度融合的快樂者」。生命中的每一分鐘都在燃燒能量，離職風險與過勞感極低。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3015, 'CIA_36', 'A (高)', 'CIA_29', 'C', '與 CIA_29 (人際適應力) C聯動：表現為「社交防禦者」。不擅長管理社交緊張關係，且情緒容易被他人激發，常導致溝通破裂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3016, 'CIA_36', 'A (高)', 'CIA_32', 'A', '與 CIA_32 (心理特權) A聯動：表現為「憤怒的特權索求者」。認為應受優待，一旦願望落空，會表現出極高的情緒激發強度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (2999, 'CIA_35', 'B (中)', 'CIA_02', 'A', '與 CIA_02 (成就動機) 高分聯動：表現為「起伏中的野心家」。他對成果有明確企圖心，會主動把目標訂高、想辦法多投入一點來換到更好的結果；日常能量夠的時候，這股企圖心能穩定推著任務往前走，方法也願意升級。一旦連續熬夜、壓力堆疊或挫折接連而來，行動力會先掉下去，但想達標的念頭本身不會消失，他仍在腦中反覆盤算下一步該怎麼做。恢復期他常一口氣把落下的進度拉回來，用密集衝刺補上先前的空白。管理上宜留意他低能量期的產出落差不代表企圖心消退，給緩衝時間、事後追蹤成果即可,不需要用高標準持續施壓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3000, 'CIA_35', 'B (中)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) 低分聯動：表現為「亢奮又易失控的行動者」。狀態好的時候他滿是幹勁,說話速度變快、答應事情很爽快,常常還沒仔細想清楚就先點頭接下任務或衝去做。情緒被拉起來時反應也容易過頭,一時興奮就倉促承諾時程,或是遇到阻礙就當場動氣、語氣變衝。等到能量退下來,先前衝動下的承諾常變成負擔,他得回頭解釋或收拾沒想周全的部分。連續受挫或睡眠不足的階段,這種先衝再說的傾向會更明顯,情緒也更快被點燃。管理上宜在他明顯亢奮的時刻多做一次確認,避免當下的承諾變成日後難兌現的坑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3001, 'CIA_35', 'B (中)', 'CIA_15', 'A', '與 CIA_15 (心理資本) 高分聯動：表現為「有底氣的起伏者」。他日常帶著希望感與樂觀,相信事情多半有辦法解決,遇到挑戰時心裡有一定的信心底盤。但活力本身仍會隨壓力、睡眠或連續挫折起伏,精神差的時候動作會慢下來、主動性降低。差別在於能量低落時他不會陷入無力或悲觀,還是把眼前的卡關看成暫時、可處理的狀況,只是需要一點時間恢復。恢復之後,他能把這份底氣重新轉成行動力,回到原本的步調。管理上可以在他明顯疲乏時給予喘息空間,不必過度介入,他自身的復原傾向多半足以撐過低谷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3002, 'CIA_35', 'B (中)', 'CIA_20', 'C', '與 CIA_20 (創新力) 低分聯動：表現為「看狀態決定要不要照舊做」。平常他偏好用熟悉、成熟的做法把事情完成,面對新方法會先觀望,不急著換掉已經用順手的流程。活力充足時,他能把這套熟悉做法執行得扎實、節奏穩定;一旦壓力大或睡眠不足,連現成流程的執行力都會跟著下滑,反應變慢、細節容易漏掉。他不太會在低能量期嘗試新方法來突破困境,反而更緊抓著原有步驟不放,因為那是他當下最省力氣維持產出的方式。恢復之後執行力回升,做事重新回到穩定節奏。管理上宜在他狀態不好時提供明確、既定的步驟讓他依循,而不是趁機要求創新突破。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3003, 'CIA_35', 'B (中)', 'CIA_26', 'A', '與 CIA_26 (同理心) 高分聯動：表現為「動能起伏中的細膩讀人者」。他能很快感覺到身邊的人正處在什麼狀態，誰情緒緊繃、誰需要被多聽幾句，他大致抓得到，並會換一種別人聽得進去的說法與語氣去回應。日常他多半帶著明顯的活力去面對事情，但接連碰壁或連續熬夜後，這股勁頭會明顯降下來，連做事的動能都變得比平常慢。就算在自己動能偏低的那幾天，他還是留意得到別人臉上的變化或話裡的言外之意，只是主動開口安慰或多做一步的意願，會比狀態好的時候少一些。管理上宜留意他近期是否連續熬夜或接連碰壁，適度減壓、給他明確的喘息安排，讓活力回穩後，他原有那份讀懂別人的細膩也能更穩定地發揮出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3004, 'CIA_35', 'B (中)', 'CIA_34', 'C', '與 CIA_34 (工作熱忱) 低分聯動：表現為「偶爾有光、多半盡責的人」。他平時看待工作比較偏向責任與收入的角度,不特別追求熱情投入,把份內事做完就好。但在特定時段——狀態好、精神足夠時——難得會浮現一點主動的活力,願意多花點心思把事情做得更好一些,而不只是完成而已。這種能量上揚通常撐不久,一旦壓力回來或體力下滑,又退回到單純把工作當義務執行的模式,不會刻意去維持那股熱度。他不覺得需要對工作保持長期熱情,只在偶爾狀態允許時讓一點主動性冒出來。管理上不需要用「培養熱情」的方式要求他,穩定給清楚任務與回饋即可,他的可靠度本身不受這種能量起伏影響太多。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3005, 'CIA_35', 'B (中)', 'CIA_01', 'A', '與 CIA_01 (盡責) 高分聯動：表現為「紀律撐住的浮動能量」。他做事有一套穩定的自我要求,能主動掌握進度、顧好品質並把事情收尾,不太需要別人催促。這份自律感不會因為活力起伏而消失——精神好的時候,他不只把事情做完,還帶著明顯幹勁去推進;精神差、連續受挫或睡眠不足時,行動的熱度會降下來,但他仍會撐著把該完成的部分交出去,只是少了平常那股主動加碼的勁。旁人看到的產出品質可能維持得住,只有他自己感覺得到那段時間是硬撐而不是真心投入。恢復之後,幹勁跟自律感會一起回到原本的水準。管理上可以放心把穩定產出交給他,但留意觀察他低能量期是否需要額外的支持或喘息,避免長期硬撐消耗掉底子。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3006, 'CIA_35', 'C (低)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「嚴肅的工蜂」。做事一絲不苟但缺乏活力與笑容。管理建議：應肯定其品質，但避免其負責需要大量感染力、公關或團隊動員的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3007, 'CIA_35', 'C (低)', 'CIA_08', 'C', '與 CIA_08 (自我勝任感) C聯動：表現為「頹廢的自我懷疑者」。既不信自己能做好，也對周遭事物缺乏熱情。警示：易產生憂鬱情緒，需高度關注心理健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3008, 'CIA_35', 'C (低)', 'CIA_19', 'C', '與 CIA_19 (樂觀) C聯動：表現為「陰沉的防禦者」。對未來不抱期待，且行事風格暮氣沉沉。管理風險：容易成為團隊中負能量的擴散點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3009, 'CIA_35', 'C (低)', 'CIA_28', 'C', '與 CIA_28 (感謝) C聯動：表現為「情感乾涸者」。對生活缺乏熱力，且對他人的好意也表現得冷淡、無感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3010, 'CIA_35', 'C (低)', 'CIA_36', 'A', '與 CIA_36 (情緒易激度) A聯動：表現為「焦慮的厭世者」。生活熱情低且易受刺激。預測：在組織中常以抱怨者的身分出現，難以建立和諧關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3011, 'CIA_36', 'A (高)', 'CIA_01', 'A', '與 CIA_01 (盡責) A聯動：表現為「焦慮的完美主義執行者」。雖然做事細緻，但一旦進度受阻或出現錯誤，情緒會迅速波動，產生巨大的心理內耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3012, 'CIA_36', 'A (高)', 'CIA_05', 'C', '與 CIA_05 (衝動管理) C聯動：表現為「職場火藥桶」。情緒燃點低且缺乏行為剎車，容易在衝突中脫口而出傷人的話或做出衝動決策。風險：人際關係高度緊張。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3013, 'CIA_36', 'A (高)', 'CIA_14', 'C', '與 CIA_14 (謙虛) C聯動：表現為「自尊極度敏感者」。因自視甚高，任何指正或不同意見都會被其解讀為冒犯，引發強烈的防衛性憤怒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3014, 'CIA_36', 'A (高)', 'CIA_18', 'C', '與 CIA_18 (韌性) C聯動：表現為「脆性情緒反應者」。面對挫折時情緒反應劇烈且難以自我修復（18C），容易陷入長期的低落或憤怒中。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3019, 'CIA_36', 'B (中)', 'CIA_14', 'A', '與 CIA_14 (謙虛) 高分聯動：表現為「口氣衝但不搶功的人」。平時穩定，遇到特定觸發點（被誤解、時間壓力、連續失敗）情緒會上來，但他不會把這股情緒轉成要證明自己、要壓過誰的動作，說話語氣可能變衝，內容不會變成搶功或看輕別人的貢獻。事後情緒退了，他能坦然承認剛剛口氣不好，不會硬凹自己沒錯。管理上他的情緒起伏較少演變成人際地位之爭，衝突多半停留在事情本身。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3020, 'CIA_36', 'B (中)', 'CIA_18', 'C', '與 CIA_18 (韌性) 低分聯動：表現為「連環觸發下修復跟不上的人」。他平時能維持穩定，但連續遇到失敗或長時間處在高壓、變動頻繁的狀態下，原本會被單一觸發點激起的反應會變得更頻繁出現，退回冷靜的速度也變慢，要花更久時間才能把自己拉回可工作狀態。單一次的情緒起伏他還修得回來，但一輪接一輪下來，補救的力氣會跟不上。管理上宜留意他連續受挫的累積量，在耗損明顯前就給喘息空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3021, 'CIA_36', 'B (中)', 'CIA_29', 'A', '與 CIA_29 (人際適應力) 高分聯動：表現為「情緒上來仍拿捏得住互動分寸的人」。他遇到觸發點情緒會上來，但同時對不同性格的人有一套應對彈性，會依當下對象調整說話方式，把繃住的情緒跟接下來要維持的互動分開處理，不會讓一時的火氣把好不容易建立的合作關係燒掉。事後他能主動找回互動的節奏，把剛剛的衝話圓回來。管理上他情緒波動對關係面的殺傷力相對有限，多數場合能自行收拾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3022, 'CIA_36', 'B (中)', 'CIA_32', 'C', '與 CIA_32 (心理特權) 低分聯動：表現為「情緒歸情緒、不拿委屈換體諒的人」。觸發點一來他情緒會升溫，但升溫的理由多半是事情本身（被誤解、時間壓力），不是覺得自己該被特殊對待卻沒被滿足。他不會把情緒轉成「這種事不該我來扛」的抱怨，事後能就事論事把剛剛的反應收回去，不會拿自己的付出當理由要求額外體諒。管理上他的情緒起伏不容易演變成對待遇或資源的額外索求，處理起來相對單純。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3023, 'CIA_36', 'B (中)', 'CIA_03', 'A', '與 CIA_03 (審慎) 高分聯動：表現為「語氣變硬但判斷不跟著亂的人」。他平常穩，遇到觸發點反應會先冒起來，但同一時間他手上的判斷不會跟著失準，講話語氣可能變硬，要做的決定他還是會先掂過風險跟後果才動作，不會因為情緒上來就倉促拍板。等情緒退了，他也會回頭確認剛剛在氣頭上做的判斷有沒有漏掉什麼。管理上即使他明顯在氣頭上，關鍵決策的品質仍有一定保障，但仍宜留意語氣造成的人際磨擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3024, 'CIA_36', 'C (低)', 'CIA_03', 'A', '與 CIA_03 (審慎) A聯動：表現為「冰冷的策略家」。情緒極度穩定且思維嚴謹，在危機時刻能保持驚人的冷靜，進行最理性的判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3025, 'CIA_36', 'C (低)', 'CIA_15', 'A', '與 CIA_15 (心理資本) A聯動：表現為「情緒穩定的樂天派」。面對煩惱時反應淡定，能以積極且平穩的心態尋求解決方案，是團隊的定海神針。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3026, 'CIA_36', 'C (低)', 'CIA_21', 'A', '與 CIA_21 (效率取向) A聯動：表現為「專注的高效機器」。不被瑣事干擾情緒，能持續維持產出動能，即使在混亂的變動中也不會自亂陣腳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3027, 'CIA_36', 'C (低)', 'CIA_26', 'A', '與 CIA_26 (同理心) A聯動：表現為「溫和的傾聽者」。具備共情能力但自身情緒穩定，能包容他人的負面情緒而不受影響。管理建議：適合作為衝突調解人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3028, 'CIA_36', 'C (低)', 'CIA_33', 'A', '與 CIA_33 (社會期望反應) A聯動：表現為「得體的職場專業人士」。為了形象與本性，展現出極高的修養與情緒控制力，極少流露負面情感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3029, 'ANI_01', 'A (高)', 'ANI_02', 'A', '與 ANI_02 (韌性) A聯動：表現為「冷靜的危機分析官」。在高壓或挫折中，仍能維持極高的邏輯穩定性與結構化思考品質（01A）。預測：在組織混亂期是極佳的解題者，不會因情緒壓力導致決策邏輯崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3030, 'ANI_01', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A聯動：表現為「多維度的邏輯大師」。具備強大的結構拆解能力，且能根據新資訊快速切換不同的分析模型。預測：極具敏捷開發潛力，能快速修正分析偏差，而非固執於單一邏輯。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3031, 'ANI_01', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A聯動：表現為「務實的發明家」。點子具備強大的邏輯支撐與可行性結構。管理建議：其提議通常不是空談，適合負責將抽象願景轉化為可執行的產品原型或專案藍圖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3032, 'ANI_01', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A聯動：表現為「AI應用的戰略家」。能從邏輯層面理解 AI 模型，並有效評估其在實務中的價值與風險。預測：是組織數位轉型中的核心評估者，能精準判斷技術導入的邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3033, 'ANI_01', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「全局架構師」。不僅能拆解細節模式，還能看透各子系統間的相互依存關係。管理建議：適合擔任流程優化或中長程戰略規劃的高層幕僚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3034, 'ANI_01', 'A (高)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A聯動：表現為「精密邏輯控制者」。在複雜分析中能同時確保每一環節的極高精確度。警示：容易出現過度分析（Analysis Paralysis），在追求邏輯完美時可能犧牲交付速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3035, 'ANI_01', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A聯動：表現為「真理的檢驗者」。具備結構化分析力且能審慎評估資訊來源的可信度，極難被假訊息或單一觀點誤導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3036, 'ANI_01', 'A (高)', 'ANI_22', 'C', '與 ANI_22 (高效決策) C聯動：表現為「猶豫的專家」。邏輯分析極強，但面對模糊情境時因追求更多數據而難以定案。管理建議：需由外部力量設定決策期限或提供權重框架。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3037, 'ANI_01', 'B (中)', 'ANI_02', 'A', '與 ANI_02 (韌性) 高分聯動：表現為「穩壓情境下的條件型分析者」。當任務壓力可控、節奏穩定時，他能迅速進入狀態、條理清晰地拆解問題；但一旦情境急速翻轉或資訊來得太破碎，他的分析品質便開始動搖，難以快速重建思路。他並不會在高壓下崩潰——情緒上他能撐住、挫折後很快能重新站穩——但認知層面的整理速度跟不上情境變化的速度：思路卡住的時間拉長，需要停下來喘一口氣、重新釐清才能繼續往下推。管理上適合在變動期提前告知可能的轉折脈絡，讓他有機會在正式混亂來臨前就建好分析框架。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3038, 'ANI_01', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「熟悉框架內的條件性分析者」。他在熟悉的思路與方法下能拆解問題、找出關鍵，但碰到需要切換分析框架的情境，他往往會繼續沿用原本那套做法，不太會主動尋找新的切入方式。一旦情境要求的框架和他習慣的有所出入，分析品質便容易滑落——他可能卡在如何定義問題上，而遲遲無法進入有效分析。管理上宜在要求框架轉換前，先替他說清楚新方向的必要性與操作步驟，幫助他找到穩定的分析起點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3039, 'ANI_01', 'B (中)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) 高分聯動：表現為「結構引路的創意分析者」。當問題邊界清楚時，他一邊提出跳脫框架的新穎想法，一邊把這些想法收進分析框架裡逐條檢驗、排出邏輯順序，創意方向落地成可執行的結論；但一旦他要在概念尚未成形的早期階段就開始分析，他會感到費力——缺少結構性脈絡時，他的推理容易失焦或繞圈。他傾向先整理出「問題是什麼」再投入發想，而非直接在開放空間裡同步生產想法與結論。管理上宜讓他在創意發散後進入分析，而非要求他在兩者之間快速來回切換。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3040, 'ANI_01', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「工具門檻影響下的情境分析者」。在熟悉的工作流程中，他能有效組織資訊並進行邏輯推導；但當任務涉及需要運用 AI 工具輔助分析的環節，他對 AI 概念與操作仍在熟悉階段，得先摸索工具本身怎麼用。這段摸索占走他大半心力，留給思考問題的容量明顯變少：分析節奏放慢，有時甚至繞開工具、改用更費時的方式處理，產出速度落後於預期。周遭若能替他先準備好可直接操作的示範流程，而非只是提供工具入口，他的分析能力便有機會如常發揮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3041, 'ANI_01', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「局部深挖型的系統感知者」。當問題牽涉多個相互連動的層面時，他在全貌感知上能跟上，卻不一定能維持每個局部的分析精度——他的分析能力在結構清楚的切面上很穩，但要在整體系統概念還模糊時就要同步深究細節，他會感到力不從心。他有時會先把系統圖在腦中描出，再逐步聚焦到可操作的分析單位，這個過程需要時間。外部若能先提供整體架構的說明或視覺化，他的局部分析便能更快校準、更有把握。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3042, 'ANI_01', 'B (中)', 'ANI_17', 'C', '與 ANI_17 (準確嚴謹度) 低分聯動：表現為「結構清楚卻粗粒度的分析者」。在情境熟悉、資料明確的條件下，他能有效拆解問題並推出結論；但他對細節的敏感度較低，掌握傾向停在「夠用」的精度，對於規格中的小例外、數字尾數或邊界條件往往一帶而過、容易漏掉。分析框架站得住腳，具體結論裡卻不時藏著可追溯的小誤差，在高精度要求的場景下會成為問題。若任務需要較高的準確度，宜在他產出分析後安排額外的細節核驗環節，而非期待他自行發現並修正。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3043, 'ANI_01', 'B (中)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) 高分聯動：表現為「雙層審視下的條件型分析者」。面對結構清楚的問題時，他能一邊組織分析邏輯、一邊對資訊來源與前提保持審慎，檢視可信度、比較不同觀點、不輕易接受直覺判斷。在資訊量大且脈絡快速變動的場合，他難以同時保持兩個層次的思考：拆解問題本身已經逼近他的負荷上限，批判性的反覆確認往往被排到後面、甚至來不及做。熟悉情境下他的輸出品質高於一般預期，複雜情境下的結論可靠度卻未必如外表穩定。任務若需要高品質判斷，宜在他輸出初稿後留給他額外的反思時間，而非以速度壓縮他的雙層確認空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3044, 'ANI_01', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A聯動：表現為「努力但盲目的執行者」。自我驅動極強，但因缺乏結構化拆解能力，常在錯誤的方向上拼命。管理建議：需主管協助定義「對的問題」，並提供明確的任務清單。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3045, 'ANI_01', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「挫折感強的高標者」。渴望卓越但苦於找不到解決複雜難題的邏輯路徑。風險：容易因產出品質達不到自我期望而陷入自我懷疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3046, 'ANI_01', 'C (低)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A聯動：表現為「資訊的採集者而非整合者」。對新奇事物有熱情，但僅停留於表面探索，難以深入分析其內在模式或商業價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3047, 'ANI_01', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「穩定的守成者」。在標準化任務中極其可靠，但在面對需要複雜分析的新型任務時會感到手足無措。管理建議：應提供標準作業流程（SOP）來彌補其分析短板。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3048, 'ANI_01', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「直覺型決策者」。決策極快，但通常缺乏邏輯與證據支撐，屬高風險型決策風格。警示：在變動大且容錯率低的環境中極具危險性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3049, 'ANI_01', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A聯動：表現為「包裝精美的平庸者」。測評中展現高度合規形象，但在實際需要硬核分析的場景中會顯露支撐力不足。面談重點：應透過具體行為案例考察其邏輯拆解過程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3050, 'ANI_02', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「冷靜的解題戰術家」。在高度壓力和挫折中，仍能運用邏輯拆解資訊並識別模式。預測：在組織危機中能產出具備結構化邏輯的復原計畫，不因情緒壓力而導致思維癱瘓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3051, 'ANI_02', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A聯動：表現為「動態適應的專家」。心理彈性強且能迅速切換思考策略以應對新挑戰。預測：面對突發變革時，能最快從舊框架中跳出，展現出極高的問題解決多樣性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3052, 'ANI_02', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A聯動：表現為「不屈的開拓領袖」。具備強烈主動性 且在不確定環境中仍能維持動能。管理建議：適合作為新業務的發起者，因為他們在遇到拒絕或瓶頸時會自發復原並引導他人前行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3053, 'ANI_02', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「愈挫愈勇的精進者」。追求極致成果的熱情結合高復原力，將挫折視為優化的必要過程。預測：能維持長期的卓越表現而不倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3054, 'ANI_02', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「宏觀的穩定者」。能從整體連動的角度理解局部挫折，並維持心理穩定。管理建議：適合作為變革管理的領導者，能穩定軍心並引導團隊看見長遠願景。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3055, 'ANI_02', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「危機指揮官」。能在變動中果斷決策並承擔風險，不因不確定性而動搖。預測：具備強大的領袖氣場，能在壓力和失敗面前維持執行效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3056, 'ANI_02', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「壓力緩衝後的穩健分析者」。他在節奏穩定、沒有接連突發衝擊時，能夠清楚拆解問題脈絡，分析路徑也相對有條理；但一旦遇到多重壓力接踵而來，他需要先找到喘息空間、獲得情緒支撐，才能讓思考重新收束回來。旁人若在他情緒尚未緩落時急著要他給答案，往往只會得到倉促或片段的判斷，而非他本來有能力做出的完整分析。管理上宜在高壓任務前後設置確認節點，讓他有機會整頓狀態、穩定輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3057, 'ANI_02', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「壓力下的習慣守衛者」。他的情緒調適需要時間：遇到壓力或挫折，他通常先退守到熟悉的做法，等到情緒稍緩才有餘裕考慮是否要轉換方向。碰到需要改變做法的情境，若缺少清楚的必要性說明，他傾向繼續沿用既有步驟，讓自己在情緒回穩的過程中有個可以依循的錨點。管理上宜先穩住他的節奏，再提供新方法的具體理由與步驟，而非在他壓力正高時同步要求調整做法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3058, 'ANI_02', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「目標清晰時的韌性執行者」。在結構完整、目標與期待都明確的任務裡，他會自己訂出具體目標、持續追蹤進度並視情況調整做法，對結果與承諾始終有明確自我要求。一旦任務中出現較大壓力或接連受挫，他需要先花時間沈澱、重新確認方向，自我驅動的節奏才會慢慢回來。這段調整期若缺乏資源或支持，他的自主行動力可能短暫下降，對外看起來像是停住了。給他明確的優先順序與短暫的支援視窗，通常能縮短這段恢復期，讓他較快回到主動推進的狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3059, 'ANI_02', 'B (中)', 'ANI_08', 'C', '與 ANI_08 (卓越追求動機) 低分聯動：表現為「壓力下的基本完成型」。他的交付傾向是完成該完成的，較少主動加碼或追求超出要求的品質；在壓力升高時，他更容易退到「先做到就好」的模式，並且需要一段時間調整才能恢復穩定輸出。對周遭人而言，很難在高壓情境期待他主動提升標準，但只要任務範圍明確且壓力可控，他通常能夠穩定交付。若希望他在品質上有更多投入，需在他情緒穩定的窗口期明確定義期待，而非在任務進行中途加壓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3060, 'ANI_02', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「需要穩定才能展開的系統思考者」。情緒穩定、有足夠時間梳理的時候，他能夠看見不同面向之間的連動關係，並從較整體的角度預判影響；一旦壓力升高，他需要先把自己的狀態收斂，系統層次的思考往往會暫時退位，變得更依賴局部判斷。這意味著他最有價值的判斷通常出現在情緒平穩的場合，高壓簡報或緊急決策時，他未必能即時調出全幅的系統視野。管理上宜在他情緒狀態穩定時創造空間，讓他提前完成系統層次的評估。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3061, 'ANI_02', 'B (中)', 'ANI_22', 'C', '與 ANI_22 (高效決策) 低分聯動：表現為「壓力下卡決的緩衝者」。他在即時落案場合常把評估暫停，任務因此停在待決狀態。面對需要當場拍板的多選項時，他傾向再多看一輪、多問一句，遲遲不把選項收斂成結論。一旦外部壓力升高或連續遇到挫折，他更容易在評估中途停下腳步、拖長比較的時間，而不是先給出一個可調整的暫定結論。等到壓力緩解、有人替他釐清優先順序後，他才比較能把懸置的選項重新排出先後、往下推進。管理上宜在關鍵時點提供明確的收斂提示與時間框，並在他卡住時給予支持性介入，協助他把待決事項轉為可執行的下一步。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3062, 'ANI_02', 'B (中)', 'ANI_11', 'A', '與 ANI_11 (同理心) 高分聯動：表現為「情緒穩定時的貼近回應者」。他能夠從他人的立場理解情緒與需求，並在互動中給出適切的回應；但這份感知能力在他自身承受壓力、需要調整狀態的時候，會出現明顯的落差——當他忙著處理自己內部的波動，對他人的情緒線索就沒那麼敏銳，回應也較為簡短或帶有距離感。周遭人若在他狀態不佳時尋求情感支持，可能感覺到他不若平時貼近。在他恢復穩定後，這種感知與回應的品質通常能快速回來，因此旁人可留意他當下的狀態作為校準的依據。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3063, 'ANI_02', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「焦慮的邏輯者」。分析能力強但心理防禦弱。警示：一旦遇到挫折，情緒波動會干擾其結構化推理過程，導致雖然看見問題卻無法有效行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3064, 'ANI_02', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「玻璃心的完美主義者」。渴望卓越但對失敗的容忍度極低。風險：極易因一次失敗而陷入長期的消沉與自我懷疑，需頻繁獲得肯定來支撐動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3065, 'ANI_02', 'C (低)', 'ANI_11', 'A', '與 ANI_11 (同理心) A聯動：表現為「易碎的共感者」。具備情感連結但心理資源容易耗竭。管理警示：容易被團隊的負面情緒淹沒，面對人際衝突時復原極慢。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3066, 'ANI_02', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「防禦性的守成者」。值得信賴但極度排斥任何可能導致挫折的變革。管理建議：適合放在變動性極低的崗位，一旦面臨轉型需給予大量心理緩衝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3067, 'ANI_02', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A聯動：表現為「脆弱的精算師」。追求細節完美，但一旦出錯便會產生劇烈的挫折反應。行為預測：出錯時可能出現逃避行為，而非積極尋求解決路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3068, 'ANI_02', 'C (低)', 'ANI_21', 'A', '與 ANI_21 (社交智商) A聯動：表現為「社交防禦者」。雖具備社交洞察力，但若在社交場合受挫，會迅速退縮並難以再次主動建立聯繫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3069, 'ANI_02', 'C (低)', 'ANI_23', 'C', '與 ANI_23 (社會期望反應) C聯動：表現為「真實的消極者」。不屑偽裝且面對困難時反應消極。警示：在遭遇不順時會直接表露挫敗感，對組織氛圍具備強烈的負面擴散效應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3070, 'ANI_03', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「多維度的邏輯大師」。不僅能拆解模式，還能隨環境變動切換多種邏輯分析框架。預測：在複雜變局中能產出多套邏輯自洽的替代方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3071, 'ANI_03', 'A (高)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A聯動：表現為「變革的發動機」。思維切換快（03A）且行為調整即時（04A）。預測：在組織轉型期適應極快，能最先從舊模式轉入新賽道，是敏捷開發的核心人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3072, 'ANI_03', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A聯動：表現為「流變的創意者」。不僅想法新穎，且能根據回饋快速修改創意路徑。管理建議：適合負責需要高度迭代的產品開發或概念設計任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3073, 'ANI_03', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A聯動：表現為「AI 共生者」。能快速適應 AI 工具帶來的典範轉移，主動調整工作流程以極大化科技價值。預測：是推動組織數位轉型的先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3074, 'ANI_03', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「動態的策略家」。能看見全局關聯，並靈活調整局部策略以維持系統最優平衡。管理建議：適合作為高階策略幕僚，處理高複雜度的跨部門議題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3075, 'ANI_03', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A聯動：表現為「理性的修正者」。會批判性檢視證據，一旦發現既有策略有誤，能毫無偏執地立即切換思考方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3077, 'ANI_03', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「漸入佳境的問題整理者」。遇到結構清晰、資訊充分的情境時，他能逐步跟上分析的節奏，慢慢把問題梳理清楚；但在初期資訊混亂或思路還未消化時，他往往需要多一點時間才能進入狀態，不會馬上切換到新框架。等他適應之後，對問題的拆解與掌握明顯改善，輸出品質也會穩定下來。管理上宜給他緩衝期理解脈絡，避免在他尚未熟悉情境時就要求立即轉向，才能讓他的分析潛力充分發揮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3078, 'ANI_03', 'B (中)', 'ANI_04', 'C', '與 ANI_04 (適應敏捷) 低分聯動：表現為「緩步消化的習慣守護者」。他對新方式並非完全抗拒，但需要一段時間才能真正理解並內化——在這段消化期裡，他傾向先在心裡確認「這個做法有沒有道理」，而不是立刻切換。遇到情境又快速移動、要求同步調整時，他更容易停留在既有流程上，等待更明確的指示才肯真正挪動。管理上宜把新方向分段說明，讓他有機會逐步釐清必要性，降低他因理解未到位而裹足不前的機率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3079, 'ANI_03', 'B (中)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) 高分聯動：表現為「接觸新框架時的緩慢展開者」。他對跳脫既有框架的新穎想法有接受意願，但需要時間逐步消化、理解其背後的邏輯才能真正轉換思路；在熟悉一個新觀點之前，他往往先用已知的脈絡去對照，而非直接跟上發散思維的跳躍節奏。越是前衛或跳脫常規的視角，他需要越多時間確認方向再跟進。管理上宜在提出突破性思路後給予消化空間，並搭配具體說明幫助他看見新框架的邏輯起點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3080, 'ANI_03', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「在陌生工具情境中放慢切換的人」。他願意嘗試調整做法，但需要一段理解期才能真正消化新方式——當他正摸索如何操作不熟悉的工具、連基本概念都尚在熟悉時，這段消化時間會拉得更長，思考策略的切換也更慢。碰到需要同時吸收工具知識與重新整理方法論的情境，他往往先暫停原有思路，等對工具有了基本掌握才重新出發。管理上宜先提供具體示範幫助他建立操作基礎，再逐步引導他嘗試不同的思考路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3081, 'ANI_03', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「在整體脈絡下逐步展開的消化者」。他對新方式有接受意願，但切換思考策略需要時間——他習慣在理解某個更大的系統框架之後，才逐步消化其中每個環節的做法。當情境的整體連動關係清楚時，他能更快找到新方向的邏輯依據，消化節奏也會加快；若結構脈絡不清，他往往先停在原來的觀點上反覆確認，遲遲未能切換。管理上宜在要求他轉換方法前，先幫助他看到更完整的情境輪廓，讓他的消化有所依附。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3082, 'ANI_03', 'B (中)', 'ANI_20', 'C', '與 ANI_20 (批判性思考) 低分聯動：表現為「在評估惰性中緩慢切換的思考者」。他面對新方式需要時間消化，而在這段理解期裡，他較少主動質疑舊有做法的前提，也較少追問新方向的合理性——傾向沿用既有結論做為暫時的定向依據，直到熟悉度提升後才開始真正調整。沒有人明確要求換方法、也沒有人拿出比較資訊時，他多半沿用原本的做法，一停就是好一段時間，不自覺地錯過重新評估的時機。管理上宜主動提出問題或提供比較資訊，讓他看見舊有框架的侷限，帶動他展開消化與調整。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3083, 'ANI_03', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「在決策已定後仍需消化轉換的跟進者」。他能接受新方向，但思考策略的切換需要時間——即便方向已快速定案，他仍需要一段內化期才能真正調整自己的思考與做法框架。這段消化過程對他而言是必要的，跳過它他會顯得跟不上節奏，即使表面上沒有異議。越是快速且連續的轉換，他需要越多空間來確認自己真正理解了新框架的邏輯。管理上宜在決策落定後留給他明確的說明時間，讓他把新的思考路徑走一遍，而非假設方向對齊等同於做法已切換。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3084, 'ANI_03', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「執著的專家」。邏輯分析力強，但固守單一模型。風險：在產業環境巨變時，容易因拒絕思考替代路徑而導致邏輯優勢失效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3085, 'ANI_03', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「僵化的精進者」。追求完美，但只認同「唯一的正確方法」。警示：在標準化流程中表現優越，但在需要靈活變通的非標專案中會顯得笨拙。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3086, 'ANI_03', 'C (低)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A聯動：表現為「矛盾的收集者」。對新資訊有熱情，但實際運用時仍傾向回歸舊有習慣（03C）。管理建議：其好奇心多停留於表面，需主管引導其將新資訊內化為具體行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3087, 'ANI_03', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「穩定的守位者」。在既定規範內極其可靠，但對「不按牌理出牌」的變革感到焦慮。管理建議：適合法務、審計等需要高度穩定思考路徑的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3088, 'ANI_03', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A聯動：表現為「細節的困獸」。對準確度要求極高，但當環境不確定時，會因無法調整規則而陷入對瑣碎細節的無效糾結。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3089, 'ANI_03', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「固執的快決策者」。決定下得快，但極難回頭修正方向。風險：一旦決策前提發生變化，容易因反應遲緩（03C）而導致嚴重損失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3090, 'ANI_03', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A聯動：表現為「表面服從的保守派」。口頭上配合變革（23A），但思維與實際做法仍偏好舊路（03C）。面談重點：應追問其對新策略的具體拆解與對策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3091, 'ANI_04', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「數據驅動的變革者」。能快速拆解新環境下的邏輯與模式，並據此立即調整資源分配。預測：在組織轉型初期，能最快辨識出新舊邏輯的差異並產出具備結構化支持的行動方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3092, 'ANI_04', 'A (高)', 'ANI_02', 'A', '與 ANI_02 (韌性) A 聯動：表現為「逆境中的生存大師」。面對變動產生的壓力與挫折能快速復原，並以積極回應代替消極抵抗。管理建議：適合作為高壓、高頻率變動專案的領軍人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3093, 'ANI_04', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「全方位的敏捷精英」。思維路徑與行為模式同步調整，完全不具備路徑依賴。預測：極具敏捷開發潛力，能在高度模糊與迭代的任務中維持極高的工作效能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3094, 'ANI_04', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「靈活的自我驅動者」。不需要主管頻繁指示，會自發根據變動目標調整自己的進度與目標。預測：適合遠距辦公或開拓性任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3095, 'ANI_04', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「流變的發明家」。點子新穎且能根據外部反饋立即優化創意，不固執於原始構思。管理建議：是推動產品快速原型開發（Prototyping）的核心戰力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3096, 'ANI_04', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A 聯動：表現為「AI 共生先鋒」。能迅速掌握 AI 技術的迭代更新，並立即將其應用於調整現有工作流程，極大化產出效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3097, 'ANI_04', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「敏捷指揮官」。在資訊有限且環境快速變遷下，能果斷定案並隨時根據最新情報修正決策路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3098, 'ANI_04', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「待脈絡清晰後的穩健行動者」。面對變動，他習慣先在心裡把情況想清楚——這次調整的背景是什麼、影響哪些環節、再行動不遲；等他理解了變化的邏輯，便能條理分明地重整優先順序。若變動太急、來不及建立全局理解，他容易卡在觀望，讓分析暫時空轉而遲遲未動。管理上宜在宣布改變時同步提供脈絡說明，讓他的分析能力有足夠素材支撐，再引導他轉入行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3099, 'ANI_04', 'B (中)', 'ANI_02', 'C', '與 ANI_02 (韌性) 低分聯動：表現為「壓力下的審慎觀察者」。他面對變化，習慣先看懂背景與來龍去脈，才願意跨出調整的腳步；情況平穩、節奏可控時，這樣的審慎一步步向前推進，不至於停滯。連續受挫、或長期處在高壓與情況未明的階段，他明顯出現情緒耗竭、表現起伏加大的樣子，跨出那一步的次數變少，觀望期拉得更長，有時還沒緩過氣，新一輪要求已經逼近。這段期間，調整經常停在「想清楚了」那一步，遲遲沒有轉成實際行動，該推進的事項多半卡在原地，直到情緒緩過來才重新啟動。管理上宜先協助他穩定情緒、給予緩衝空間，再逐步引入變動，讓他在恢復元氣之前不必同時扛住新一波壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3100, 'ANI_04', 'B (中)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) 高分聯動：表現為「理解後快速換軌的執行者」。他不是第一個跳入變化的人，但一旦吸收了新方向的脈絡，思維切換的速度頗快，能在不同做法之間靈活移動、不拖泥帶水。需要時間的是最前段的「搞懂這次為什麼要變」，一旦跨過那道門檻，後續的調整往往流暢。若時間壓力使他還沒完全消化就得執行，切換效果會打折扣。管理上宜在啟動變革前給他簡明的背景說明，讓理解先行，其後的轉換則通常可以放手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3101, 'ANI_04', 'B (中)', 'ANI_05', 'C', '與 ANI_05 (自主領導) 低分聯動：表現為「依賴框架的謹慎調整者」。他對變化的反應本就需要時間理解背景才願意動，而推動自己前行的內在節奏又不夠穩固，較依賴外部的目標設定與進度檢核。在結構明確、有人追蹤進展的環境裡，他能審慎但持續地完成調整；一旦外部框架鬆動或沒有定期回饋，他容易在「觀察」和「等待」之間徘徊，調整行動拖而未決。管理上宜提供清楚的里程碑與固定回饋節點，讓他在有序的外部節奏中把觀望化為行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3102, 'ANI_04', 'B (中)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) 高分聯動：表現為「背景理解後的創意轉化者」。他習慣先弄清楚變化的脈絡再動；一旦那個脈絡站穩，思考會朝多個方向延伸，能提出不同角度的回應方式而不只是照舊複製。如果局勢剛剛翻轉、全局還模糊，他的創意思考容易被懸在空中——方向沒定，點子也難以落地。若環境穩住讓他完成理解的初步消化，他往往能在調整的過程中帶入新穎解法，讓結果不只是「適應」而有所提升。管理上宜等他確認方向後再給予發揮空間，而非在他還摸清楚之前就要求創意輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3103, 'ANI_04', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「審慎觀察下的摸索型適應者」。他通常要先理解變化的背景與影響才會投入調整，面對需要 AI 工具介入的新情境時，他傾向先觀察、等待清楚的示範或步驟說明，再決定如何跟進。遇到工具陌生、情境說明不足時，調整的起點便更模糊，他需要具體的操作範例才能確認方向，在此之前行動會顯得遲緩。管理上宜提供循序漸進的具體示範，讓他在理解了「為何要變、怎麼變」後，能以他慣有的審慎節奏穩定投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3104, 'ANI_04', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「觀察等待型的穩健跟進者」。他在決策上能於資訊尚不完整時就果斷定案、快速調整方向，即使情況仍在演變也不輕易陷入等待；然而在適應層面，他習慣先理解變化的背景與影響，確認方向合理後才全力投入調整。這意味他能迅速決定「做什麼」，卻在「怎麼落地執行這個改變」上保持較審慎的節奏，需要一段消化期才能讓調整行動穩定展開。管理上可善用他快速定案的特點先鎖定優先方向，再給他足夠的背景說明讓後續執行跟得上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3105, 'ANI_04', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理論型學者」。雖然分析能力極強，但在執行層面轉向遲緩，容易陷入「分析癱瘓」，需主管推動其進入實踐階段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3106, 'ANI_04', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「追求完美的守舊者」。極度在意外產出品質，但堅持使用熟悉的既有流程。警示：在遭遇範式轉移（Paradigm Shift）時會產生強烈的抵觸感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3107, 'ANI_04', 'C (低)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「觀察者而非變革者」。對新資訊感興趣，但行為上仍偏好在安全、穩定的環境中進行探索，難以即時轉化為行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3108, 'ANI_04', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的守位者」。高度可靠但極度依賴 SOP。管理建議：在變革發生前需給予充分的預告與緩衝期，否則其一致性優勢會因焦慮而失效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3109, 'ANI_04', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「精確的緩慢者」。為了維持細節品質，在面臨變動時會顯得猶豫不決，不願為了速度犧牲其嚴格的準確標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3110, 'ANI_04', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「剛性的決策者」。決策雖快但一旦定案極難轉彎，面對外部環境的動態修正能力較弱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3111, 'ANI_04', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「表面配合的被動者」。口頭上同意改變以符合認可，但行為仍死守舊流程。面談重點：應追蹤其具體的行為調整紀錄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3112, 'ANI_05', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「獨立的策略執行者」。不僅具備強大拆解問題的邏輯（01A），且能自發性地針對分析結果採取行動（05A）。預測：極具潛力成為專案負責人，能獨自完成從「問題發現」到「計畫實施」的全過程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3113, 'ANI_05', 'A (高)', 'ANI_02', 'A', '與 ANI_02 (韌性) A 聯動：表現為「不屈的開拓者」。面對挫折時能自發性地尋求復原路徑（02A），且不需要他人安慰便能重新找回動能（05A）。管理建議：適合作為開拓新市場或應對高度不確定專案的先鋒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3114, 'ANI_05', 'A (高)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「敏捷的自我進化者」。會根據環境變動主動調整優先順序（04A），而非等待主管告知方向（05A）。預測：在組織轉型期是極佳的活水，能迅速在混亂中找到自身定位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3115, 'ANI_05', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「高標準的自律大師」。對自我要求極高（08A），且這種動力源自內心，不因缺乏監督而降低品質（05A）。管理建議：給予高度自主權能發揮其最大效能，過度微管理（Micro-management）反而會損害其動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3116, 'ANI_05', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A 聯動：表現為「數位轉型自發者」。會主動探索如何將 AI 工具融入日常工作流程中（10A, 05A），不需要公司強制推行學習計畫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3117, 'ANI_05', 'A (高)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「絕對可靠的獨當一面者」。不僅值得信賴（16A），且在承諾任務後能自主完成所有細節（05A）。預測：是組織中最不需要被追蹤進度的「放心指標」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3118, 'ANI_05', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的執行指揮官」。具備強烈的所有權意識（05A），能果斷下達決策並對結果負全責（22A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3119, 'ANI_05', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「結構清晰時的自我調節者」。他拆解問題時邏輯清楚，能把複雜狀況切成幾個關鍵環節、辨識出真正該處理的重點，這份分析上的條理相當穩定。但要讓自己持續往前走，他常需要外部給的節奏當支點：有明確的期待、時間點與進度檢核擺在眼前時，他清楚知道現在該做到哪、目標感維持得住。一旦任務節奏變鬆、沒人問進度，他容易在某個細分步驟上停下來，卡在「這步做完該不該繼續」的猶豫，遲遲等確認才往下走，即使問題本身他早已分析清楚。這種停滯不一定會主動被看見——他不會抱怨卡關，只是安靜地把進度留在原地，直到有人重新對一次進度或確認方向。管理上宜替他設清楚的里程碑與定期回顧點，讓外部節奏補上他自主推進的空缺，他的分析力才有機會穩定轉成持續產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3120, 'ANI_05', 'B (中)', 'ANI_02', 'C', '與 ANI_02 (韌性) 低分聯動：表現為「順境依賴型的目標推進者」。他的自我管理在情境穩定時表現良好，能按部就班完成既定期待；但一旦碰上連續挫折或高度不確定，情緒耗損開始積累，原本就依賴外部節奏的他更難在波動中維持推進力。壓力拉長時，他容易出現動作縮減或等待情勢明朗再行動的傾向，讓進度停滯的時間拉長。管理上宜在任務遇到波折時主動介入、重新確立方向，並縮短回顧週期，讓他在支持到位後能較快回到穩定節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3121, 'ANI_05', 'B (中)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) 高分聯動：表現為「快速回應後需外力錨定的行動者」。他對環境變化反應靈敏，能快速察覺新要求並投入調整；但對自己要做什麼、做到什麼程度，仍需要外部明確的期待或檢核點才能持續維持。當事情快速轉換時，他在應對變動這件事上游刃有餘，卻容易在新任務的目標設定上缺乏內在錨點，等著別人替他框出優先順序。管理上宜在每次任務重組後快速確認新的優先框架，讓他適應快的優勢能落實在明確方向上，而非漫無邊際地回應刺激。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3122, 'ANI_05', 'B (中)', 'ANI_08', 'C', '與 ANI_08 (卓越追求動機) 低分聯動：表現為「框架內的完成者」。目標與期待一旦說清楚，他通常能按節奏做到，但做到就停——不會自己往更高標準再推一步，也不會在沒有外部要求的情況下主動加碼。如果外部的進度提醒或里程碑設計跟著鬆掉，他也容易停在原地而不是自己想辦法補。管理上宜把「完成標準」寫清楚，同時定期設小型回顧點，否則他的輸出容易維持在恰好達標而不再往上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3123, 'ANI_05', 'B (中)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) 高分聯動：表現為「能識風險卻需框架撐起的執行者」。他對 AI 工具的應用情境與邊界有自己清楚的判斷——哪些用途存在風險、哪些情境並不適合套用，不需旁人提醒就能自行評估；這份判斷力在他安靜考量時其實相當到位。問題在於，他的行動節奏高度依賴外部的目標框架與定期檢核：只要里程碑清楚、節奏有人或流程撐住，他能把這份評估轉化為穩定推進；一旦外部結構鬆散或期待模糊，執行容易漂移，就算他對工具價值的判斷依然清醒，也難以自行維持推進的密度。管理上宜給他明確的階段目標與固定回顧節點，讓他的 AI 風險判讀有機會落實成可預期的行動成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3124, 'ANI_05', 'B (中)', 'ANI_16', 'C', '與 ANI_16 (可靠性) 低分聯動：表現為「需要外部錨點的波動完成者」。他在有清楚節奏與檢核機制時能穩定投入，但一旦流程或時間表出現模糊，他的交付就容易跟著漂移——有時延誤，有時降規，而且他自己不一定會主動拉警報。別人試著估算他何時能交出什麼，往往比預期更難抓準。管理上需要明確的截止點與定期確認，讓他有外部節奏可跟，而非等他主動回報。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3125, 'ANI_05', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「決策有力但自驅待喚醒的行動者」。他遇到需要決策的時刻反應果斷，能在資訊不完整的情況下做出判斷並承擔結果；但推動自己主動啟動、持續前進的動力，需要有清楚的期待與外部節奏才能穩定觸發。問題在於：沒有明確任務框架時，他的決策能力往往處於待機狀態，等著有人提出問題或設定方向。管理上宜把任務的第一步問題明確丟給他，並設計固定的推進節點，讓他果斷決策的能力有機會被頻繁呼叫，而不只在關鍵時刻才顯現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3126, 'ANI_05', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理論型顧問」。邏輯分析能力極強（01A），但缺乏將分析轉化為具體行動的推動力，傾向於「只說不做」（05C）。管理建議：需主管明確指派行動步驟或搭配高主動性的夥伴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3127, 'ANI_05', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「被動的完美主義者」。渴望卓越（08A），但若缺乏外部明確的指示與目標設定，會因為猶豫不決而陷入停滯（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3128, 'ANI_05', 'C (低)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「分散的探索者」。對新資訊有熱情（13A），但缺乏將其整合進具體職責的目標導向，容易在廣泛的學習中迷失主線（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3129, 'ANI_05', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「優秀的指令執行員」。在明確的規範下非常可靠（16A），但若任務模糊或缺乏主管督導，其產出會顯著下降（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3130, 'ANI_05', 'C (低)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「批判性的觀望者」。能看出問題所在（20A），但因為缺乏主動擔當的意識（05C），通常不會主動站出來提出解決方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3131, 'ANI_05', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「過度合規的溫順者」。在行為上高度追求認可與合規（23A），這反而削弱了其在灰色地帶進行自主決策的勇氣（05C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3132, 'ANI_06', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「邏輯說服者」。其影響力建立在嚴密的數據拆解與事實基礎上。預測：在面對高階決策者或工程技術團隊時，能以高度理性的結構贏得認可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3133, 'ANI_06', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「靈活的遊說家」。能根據不同聽眾的需求快速調整說服策略（03A, 06A）。管理建議：適合作為跨國、跨領域專案的溝通橋樑，能克服認知隔閡建立共識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3134, 'ANI_06', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「主動的變革推手」。具備強烈的所有權意識（05A），並會自發性地爭取資源與他人支持以達成目標（06A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3135, 'ANI_06', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「感性的共鳴領導」。說服過程極具溫度，能精準洞察對方需求並建立雙贏共識。預測：在團隊中具備極強的心理凝聚力，能推動員工自發性追隨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3136, 'ANI_06', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「戰略架構說服者」。能從全局角度說明決策的必要性，說服他人配合整體的長遠發展。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3137, 'ANI_06', 'A (高)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「傑出的談判家」。能在複雜利益關係中運用影響力達成有利的協議，確保組織利益最大化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3138, 'ANI_06', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的決策引導者」。決定下得快且能迅速爭取團隊認可（22A, 06A），降低決策落地時的阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3139, 'ANI_06', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「職責邊界內的邏輯說服者」。他在自己負責的範疇裡，能把複雜問題拆得有條有理、抓到關鍵、整理成清楚的推論鏈，並以這套分析直接說服周遭的人，即便情況混亂，他在這個領域的判斷也不太會動搖。一旦議題跑出他的角色範圍，這套影響力就會明顯縮水——他仍能提供條理清晰的看法，但別人未必買單，他自己也不太去強推。管理上若能讓他在擅長領域主導分析並對外溝通，他的說服效果會最穩；跨界議題宜給他明確授權或配對適合的窗口，而不是讓他自行去建立影響力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3140, 'ANI_06', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「慣性框架下的有限推動者」。他在角色內能帶動他人，但當情境需要轉換做法時，他自己也傾向維持既有思路，難以示範新方向或給出讓人信服的轉型論據。遇到改變型任務，他說服他人的底氣會隨著自身的猶豫而流失，影響力難以延伸到推動調適的層次。建議在需要他帶動改變的場合，提前給他充分的背景說明與步驟框架，讓他先穩住自身立場再展開溝通。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3141, 'ANI_06', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「目標導向的主動推進者」。他能自主設定方向並持續追蹤進度，在職責範疇內帶動他人跟上節奏，不需要外部催促就能維持影響的一致性。不過一旦議題超出自己的角色邊界，他的主動性往往退為靜待，影響力也隨之收窄。管理上可善用他在責任區內的高自主性，明確授予他推進特定事項的範圍，讓他的驅動力有清楚的施力點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3142, 'ANI_06', 'B (中)', 'ANI_11', 'C', '與 ANI_11 (同理心) 低分聯動：表現為「任務導向的角色型推動者」。他在自己負責的任務範圍內能把方向講清楚、直接推動別人照著做，效果通常不錯；一旦事情跨出他熟悉的角色分工、需要靠交情或臨場說服才能推得動，他的帶動力就明顯弱下來。互動當下他很少主動去感受別人的情緒起伏，講完該講的重點就準備往下一步走，遇到有人語氣低落或欲言又止，他多半沒接住、直接切回進度或任務內容。在熟悉的工作場景裡，他能穩定把事情推進；但一旦場面牽涉到人際敏感、需要先安撫情緒才能繼續，他常常話都說對了，卻推不動人。管理上宜替他明確界定任務範圍、減少臨場需要察言觀色的環節，並在涉及情緒安撫或關係維繫的場合搭配他人協作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3143, 'ANI_06', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「全局視野輔助的角色影響者」。他在職責範圍內帶動他人時，能串連相關脈絡、點出牽動效應，讓說服更具說服力。但超出角色邊界的議題，即便他看得見系統連動，也未必有足夠的位置發言，影響力受限於角色權重而非視野本身。建議在跨部門或全局性討論場合，適時賦予他發言的正式位置，讓他的整體觀點能真正進入決策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3144, 'ANI_06', 'B (中)', 'ANI_19', 'C', '與 ANI_19 (協商談判) 低分聯動：表現為「職責型的溫和影響者」。在自己負責的專業範圍內，他能清楚表達立場、提出主張、帶動同事往同一方向走，日常協作中互動順暢、也拿得出說服力。一旦場面轉為正式的利益攻防或需要正面捍衛自己這方的立場，他容易先退一步，選擇讓步或避開對抗，原本在角色內能發揮的說服力這時明顯收著。他不太主動把場子撐住、堅持要求，衝突拉高時常是先鬆手，事後才發現自己這邊的條件被壓縮了。管理上宜在明知會進入正式談判或利害衝突的場合，替他先備好底線與可用籌碼，必要時安排支援或共同進場，避免關鍵利益在他退讓的瞬間流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3145, 'ANI_06', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「果斷支撐下的角色帶動者」。在職責範疇內，他說服到位後能很快推進決策，讓他人感受到清楚的方向感與行動訊號。他人跟進的意願也因此提升，因為他的影響力不只停在「說好」，而是緊接著轉化為具體行動。但一旦到了角色邊界以外，即使他有意願推動，欠缺決策權的處境仍會讓他的帶動效果打折，需要借助正式管道或上層授權才能延續動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3146, 'ANI_06', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「孤傲的數據專家」。邏輯分析能力極強（01A），但因缺乏說服技巧（06C），其精闢見解常因無法獲得共識而被束之高閣。管理建議：需為其配備強大的溝通介面或協助其簡化報告語言。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3147, 'ANI_06', 'C (低)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「懷才不遇的藝術家」。點子新穎（07A），但由於不擅長向外推銷與爭取認同（06C），其創新構思難以在組織內獲得資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3148, 'ANI_06', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「孤軍奮戰的高標者」。自我要求極高（08A），但因無法帶動他人共同前行（06C），常導致自己過度工作而團隊卻無動於衷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3149, 'ANI_06', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「可靠的幕後工作者」。工作極度穩定且值得信任（16A），但在需要展現個人觀點或影響群體時傾向於退縮（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3150, 'ANI_06', 'C (低)', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「被動的訊息傳遞者」。能清晰轉達工作指令（18A），但缺乏主動改變他人立場或化解異見的能力（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3151, 'ANI_06', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「合規的隨行者」。過度在意社會規範與認可（23A），使其不願在公共場合發表具衝突性或需要強力推動的觀點（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3152, 'ANI_07', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「務實的發明家」。不僅能產生新穎想法（07A），還能運用邏輯拆解並驗證其可行性（01A）。預測：其創新產出具備高度結構化，易於被組織轉化為具體的商業成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3153, 'ANI_07', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「多維度的創意者」。想法多樣且能根據反饋快速切換思考路徑（03A, 07A）。管理建議：適合作為產品迭代或概念驗證階段的核心人才，能不斷提供替代方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3154, 'ANI_07', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具感染力的遠見者」。不僅有點子，且極度擅長向外推銷並說服他人認同其創新觀點（06A）。預測：能有效爭取創新資源，推動組織內的範式轉移。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3155, 'ANI_07', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 賦能的藝術家」。能運用 AI 工具擴展個人創意邊界（10A），將科技視為靈感的放大器而非替代品。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3156, 'ANI_07', 'A (高)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「廣博的探索家」。強烈的好奇心為創意提供源源不絕的異質素材。預測：擅長跨領域整合，能從看似不相關的領域提取概念應用於現有問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3157, 'ANI_07', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「嚴謹的革新者」。在產生新想法的同時（07A），會客觀檢驗其證據支持與潛在偏誤（20A），避免流於「為創新而創新」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3158, 'ANI_07', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的創意領導」。在多個新穎方案中能快速定案並承擔風險。管理建議：適合帶領需要快速突破的任務編組。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3159, 'ANI_07', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「實務優化的清晰改良者」。他在既有方案上進行調整的意願，只有在問題本身有明確結構時才會真正展開——遇到資料清楚、問題邊界劃定的情境，他能把既有流程拆開來看、找到可以優化的環節，並提出符合現實限制的改版方式。但如果情境模糊、方向不明，他的改良想法往往停在感覺層面，難以轉化成具體動作。對周遭而言，他是務實又可靠的改善提案者，但需要協助他先釐清問題結構，才能讓創意真正落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3160, 'ANI_07', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「既有路徑上的改良者」。他在日常工作中確實會提出改進，但這些改動通常建立在原本的做法上做微調，很少整套換掉重來、也很少跳出框架另闢一條路。方案已經定案、只是要修細節時，他能想出實際可用的優化點；一旦要求的是全新做法或跳脫慣用流程，他會傾向先問清楚為什麼非改不可、具體步驟是什麼，才願意動手，過程也偏慢。管理上宜把創新任務框成「在現有基礎上改良」，需要的是根本性創新時，則要提供明確理由與可依循的步驟，並預留較長的轉換時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3161, 'ANI_07', 'B (中)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) 高分聯動：表現為「有說服力的改良提案者」。他的創意慣於從既有方案出發——看到一個流程或做法，思考哪個環節可以動、怎麼調整更合理，點子往往來自實際操作過的限制而非憑空發想。遇到有具體框架可改的問題，他通常能拿出紮實的優化方案，也能把調整的理由說清楚、帶著周遭的人一起接受這個方向；但若任務要求從無到有創造全新構想，缺乏任何既有基礎，他的創意動能會明顯下降，此時他更可能先花力氣收斂問題範圍，而非直接產出新方案。管理上宜給他「有底可改」的題型，提供既有框架或初稿作為起點，他在改良型任務中的創意產出與推進效果較為穩定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3162, 'ANI_07', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「經驗型改良者」。他習慣在既有方案上做優化與調整，靈感多來自過去做過的案子與手邊資源,而不是從零構思新方向。他對 AI 概念與應用還在熟悉階段,遇到需要具體示範與情境說明才敢動手用。碰到需要靠新工具打開做法的題目,他往往先卡在不知道怎麼下手嘗試,只能繼續沿用熟悉的流程修修改改。這使他的改良速度容易落後,也更容易把創意侷限在既有資源與經驗範圍內。管理上宜先給他 AI 工具的具體操作示範與情境案例,讓他從熟悉的改良模式延伸出新的可能性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3163, 'ANI_07', 'B (中)', 'ANI_13', 'A', '與 ANI_13 (好奇心) 高分聯動：表現為「主動追問的實務優化者」。他對陌生的領域、還沒被定義清楚的問題都有強烈探究欲，不用等問題先被講清楚、框好，就會主動發問、找資料、動手試，理解的邊界不斷往外推。他的創意落在改良而不是憑空發明——接觸到一個已經存在的做法時，他很快就能從裡面挑出可以調整的角落，改法通常貼著實際操作過的限制走；但如果眼前完全是空白，沒有任何既有結構可以依附，即使他還在到處打聽、蒐集資訊，構想也容易停在描述層、難以具體成形。管理上讓他在能接觸到既有資料、初稿或案例的環境中發揮：材料先備齊，他探索完就能接著把方案改細；若任務真的要求從零開始，宜先給他一兩個參考案例當立足點，讓他能把新發現收斂成具體改法。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3164, 'ANI_07', 'B (中)', 'ANI_20', 'C', '與 ANI_20 (批判性思考) 低分聯動：表現為「直覺主導的實務調整者」。他在改良既有做法時，有時是靠直覺和實務經驗判斷怎麼改，而較少主動檢視改法的假設是否成立、或比較不同選項的利弊。在情境熟悉、節奏穩定時，這種風格可以快速產出可用的調整方案；但一旦問題涉及多個前提或有較大決策風險，他可能因為簡化了評估流程而漏掉重要考量。對周遭的影響是：他的提案有時缺乏論證支撐，不容易說服持不同看法的人。管理上搭配更嚴謹的評估夥伴，能讓他的改良想法更具說服力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3237, 'ANI_11', 'A (高)', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) A 聯動：表現為「全神貫注的同頻者」。不僅理解話語，更能感受弦外之音。預測：能建立極深度的信任關係，在人才導師（Mentoring）角色中表現卓越。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3238, 'ANI_11', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「人文關懷的架構師」。在思考系統優化時會優先考量對「人」的影響。管理建議：適合制定涉及大規模員工權益的組織政策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3165, 'ANI_07', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「邊想邊拍板的實務改良者」。他不需要把所有資訊蒐集齊全才敢拍板，資料不夠完整時仍能做出決定、扛起後續結果；一旦情況變了，他也能很快重新定案、調整方向，不會卡在原本的判斷裡出不來。改良提案上，他不會把所有可能的改法都想過一輪才收斂——想到一個他覺得夠用的調整方向，就直接推進、動手做，再依實際結果修正細節；碰到需要先在腦中篩過大量構想、比較各種可能性才能挑出最佳解的場合，他容易在還沒把選項想全之前就先定了案，事後才發現漏看了某個更好的路徑。管理上可在改良方案定案前，安排他先過一輪快速的選項比較，讓他在維持推進速度的同時，也把明顯更好的路徑看過一遍再拍板。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3166, 'ANI_07', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「卓越的優化者」。雖難以產生顛覆性新點子（07C），但極擅長分析現有模式並進行漸進式改良（01A）。管理建議：適合維護成熟系統，透過精確分析提升既有效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3167, 'ANI_07', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「勤奮的既定路線執行者」。主動性高（05A），但行動高度依賴現有的 SOP 或標準規範，難以在模糊地帶自創方法（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3168, 'ANI_07', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「執著於傳統的高標者」。渴望卓越（08A），但追求方式傾向於「將舊方法做到極致」而非嘗試新途徑（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3169, 'ANI_07', 'C (低)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「穩健的全局守護者」。能看清系統關聯（15A），但面對系統性崩潰時，傾向於修補舊結構而非重新建構（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3170, 'ANI_07', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「組織的定時器」。極度可靠且穩定（16A），對任何偏離傳統做法、不具備預測性的點子感到排斥（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3171, 'ANI_07', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「精密的工匠」。專注於細節的精確與合規（17A），發散式思維極弱。風險：在需要破框思考的場合會顯得極度僵化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3172, 'ANI_07', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「高度社會化的傳統主義者」。行為追求社會認可與合規（23A），這進一步壓抑了其可能展現的獨特想法（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3173, 'ANI_08', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精準的卓越者」。不僅追求高標準（08A），且具備強大的邏輯拆解能力（01A）來識別達成目標的關鍵路徑。預測：能產出具備高度結構化且品質卓越的成果，是組織中處理高難度核心任務的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3174, 'ANI_08', 'A (高)', 'ANI_02', 'C', '與 ANI_02 (韌性) C 聯動：表現為「脆弱的完美主義者」。自我要求極高（08A），但面對挫折時復原緩慢（02C）。警示：容易因一時的失敗而陷入嚴重的自我否定或心理潰敗，需主管及時給予技術性支持與信心引導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3175, 'ANI_08', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「自發性精英」。主動追求突破（08A）且不需監督便能獨立推進任務（05A）。管理建議：給予高度自主權與具備成長空間的專案，是組織最核心的自我發展動力源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3176, 'ANI_08', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「顛覆式的精進者」。追求卓越的方式不侷限於舊法（08A），能跳脫框架產生新穎方案（07A）。預測：能推動組織的範式轉移（Paradigm Shift），將產出提升到全新層次。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3177, 'ANI_08', 'A (高)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「清醒的成長者」。追求卓越的同時（08A），能客觀評估自身能力的優劣勢與情緒影響（09A）。預測：能進行有針對性的補強，避免盲目努力，成長效率極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3178, 'ANI_08', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) A 聯動：表現為「數位增強的高標者」。為了追求卓越（08A），會主動掌握並高效運用 AI 工具來優化產出（10A）。預測：能引領團隊進行 AI 化生產力的轉型，對新科技的實踐力極強。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3179, 'ANI_08', 'A (高)', 'ANI_14', 'A', '與 ANI_14 (終身學習) A 聯動：表現為「知識驅動的卓越者」。將學習視為追求進精通的唯一路徑（14A, 08A）。管理建議：是組織培訓體系中的「領頭羊」，會主動將新知轉化為卓越的工作標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3180, 'ANI_08', 'A (高)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「無懈可擊的交付者」。對品質要求高（08A）且承諾絕對兌現（16A）。預測：是組織中信任度最高的員工，承接的任務幾乎不會出現品質下滑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3181, 'ANI_08', 'A (高)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「極致工匠」。對細節精確度的執著源於對卓越的承諾（17A, 08A）。風險：可能在瑣碎細節上耗費過多精力，需協助其平衡「整體突破」與「細節完美」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3182, 'ANI_08', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「有標準卻缺穩定燃料的分析執行者」。他拆解問題的方式很到位——能辨識關鍵點、在複雜情境下仍能維持條理——但要讓這份能力真正運轉起來，得先有夠清楚的目標或看得見的里程碑。沒有這個錨點時，他常做到一半停下來，重新確認「這件事值不值得繼續投入」，過程中分析能力並沒有消失，只是推不動自己往前走。管理上給他可見的階段性成果與回饋節點，他的分析與執行才容易保持一致。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3183, 'ANI_08', 'B (中)', 'ANI_02', 'C', '與 ANI_02 (韌性) 低分聯動：表現為「順境投入、逆境容易失速的目標追求者」。只要節奏順、看得到成果，他就能穩定地把自己推向更高標準；但一旦遭遇連續挫折或長期高壓，情緒耗損會很快把動能吃掉，那個「我想做好」的念頭還在，卻很難再轉化成實際行動。他往往不是放棄了標準，而是不確定自己還撐不撐得住，在這個猶疑區間裡表現波動明顯。安排緩衝、確保情緒穩定週期，能幫他從波谷較快恢復投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3184, 'ANI_08', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「自我驅動但動能需要外部錨定的高標準執行者」。他能自己設定目標、追蹤進度、對承諾有明確的自我要求，這些不需要靠別人催；但要讓這股驅動力真的持續燒，底層還是需要清楚的目標方向與里程碑作為參照。當目標模糊或缺乏回饋機制時，他的自主管理依然運作，只是投入強度會悄悄下降，選擇把精力放在他覺得「有意義的事」而不一定是當前最重要的事。管理上不需要頻繁督促，但定期確認方向對齊仍然必要。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3239, 'ANI_11', 'A (高)', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「溫暖的交際大師」。具備敏銳的社交洞察力且真心關懷他人。預測：是團隊中的核心潤滑劑，能自然地化解隱形衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3185, 'ANI_08', 'B (中)', 'ANI_07', 'C', '與 ANI_07 (創造性思考) 低分聯動：表現為「精進既有、不主動跨框的漸進型執行者」。他對把事情做好有真實的在意，但「做好」在他身上很少意味著另闢蹊徑。目標明確時，他會把心力放在把現有流程做得更熟練——反覆對照過去的做法，抓出哪個步驟還能再收緊、哪個環節可以省掉重工，較少主動去找沒試過的新構想或冒險方案。這種精進帶出來的成果一次比一次扎實，只是解法本身很少跳出原本的框架；一旦任務真的需要換一種思路才能達標，他不會立刻抗拒，而是先在既有做法上多調整幾輪，直到反覆碰壁才願意承認得換方向。管理上及早點出「這條路已經到頂、該換思路了」，能縮短他在兩種選項間來回嘗試的時間，讓精進的動能提早轉向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3186, 'ANI_08', 'B (中)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) 高分聯動：表現為「有感知、待觸發的謹慎追求者」。里程碑清晰時，他投入得很紮實——他當場能察覺自己正在加速、說得出哪個環節最卡、知道自己需要更多確認才能繼續前進。但目標模糊或回饋斷掉時，動能就淡了下來：他看得出自己在拖、能描述那個滯感從哪裡來，卻不一定能靠自己把動力拉回來。管理上宜提供明確的檢核點與進度回饋，同時給他空間說出自己卡在哪——他通常說得很準，那個描述本身就是重新啟動的入口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3187, 'ANI_08', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「有投入意願但工具門檻拖慢步伐的目標導向者」。在目標清楚、回饋可見的情境下，他有意願把事情做到一定品質；但當達標路徑需要應用他還不熟悉的 AI 工具或概念，還在摸索階段的技術陌生感會吃掉他的動能——他在乎成果卻卡在工具入口。這時他通常不是拒絕嘗試，而是不確定從哪裡下手、只能等有人示範，行動就這樣一路往後拖。給他具體操作示範、清楚說明情境用途，能讓他較快越過門檻、把投入意願轉化為實際行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3188, 'ANI_08', 'B (中)', 'ANI_14', 'A', '與 ANI_14 (終身學習) 高分聯動：表現為「目標驅動的選擇性學習者」。他有持續吸收新知的習慣，也會主動規劃自己要學什麼、把新技能安排進日常節奏裡。但這份主動有方向性——目標清楚時，他學得快、學的東西緊貼著實際要用的場景，新能力會被他馬上拿去試；目標模糊或沒有明確里程碑推著他時，學習就往熟悉的、已有基礎的方向縮，主動開拓新領域的意願明顯降低。管理上宜在分派學習任務前先確認目標連結，讓他知道學了能用在哪——這樣他的主動學習能量才會全開。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3189, 'ANI_08', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「消極的分析師」。邏輯能力強（01A），但缺乏追求更高難度挑戰的慾望（08C）。管理建議：適合擔任「查核」或「顧問」角色，而非主導需要突破性的第一線開拓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3190, 'ANI_08', 'C (低)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「靈活的隨行者」。能快速適應環境變動（04A），但其動機多源於「外在環境要求」而非「內在卓越追求」（08C）。預測：配合度高，但不會主動提出具備變革性的高標準方案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3191, 'ANI_08', 'C (低)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「廣泛但淺層的學習者」。對新資訊有熱情（13A），但缺乏將其磨練至「技能精通」的決心與動能（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3192, 'ANI_08', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的標準化勞動力」。在明確職責內非常可靠（16A），但較少主動設定額外挑戰（08C）。管理建議：適合配置在流程穩定、不需要頻繁「超越現狀」的職位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3193, 'ANI_08', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「風險規避的決策者」。決策雖快（22A），但通常以「滿足基本要求」為底線，不願承擔追求卓越所帶來的失敗風險（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3194, 'ANI_08', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「完美的合規者」。行為高度追求他人認可（23A），使其更傾向於做「正確的事」而非「卓越的事」，以避免失敗帶來的負面評價。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3195, 'ANI_09', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「後設認知專家」。不僅能邏輯拆解問題（01A），還能覺察自己思考過程中的盲點與偏誤（09A）。預測：在解決複雜難題時，能主動修正個人的思維定式，確保分析結果的客觀性與正確性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3196, 'ANI_09', 'A (高)', 'ANI_02', 'A', '與 ANI_02 (韌性) A 聯動：表現為「心理資源管理者」。在壓力下能敏銳察覺自身情緒波動與疲勞信號（09A），並運用韌性自發進行修復與能量調節（02A）。管理建議：其高穩定性來自於主動的心理維護，適合擔任高壓環境下的長期關鍵崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3197, 'ANI_09', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「高情商說服者」。能精準感知自己的社交行為對他人的影響（09A），並據此動態調整說服策略以取得共識（06A）。預測：其影響力極具策略性且不留痕跡，能建立極高質量的信任關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3198, 'ANI_09', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「深層共鳴者」。能清楚區分「自身情緒」與「他人感受」（09A, 11A）。預測：在處理人際衝突或輔導下屬時，能提供具備邊界感且深具溫度的引導，是極佳的團隊教練人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3199, 'ANI_09', 'A (高)', 'ANI_14', 'A', '與 ANI_14 (終身學習) A 聯動：表現為「標靶式學習者」。清楚知道自己的能力短板與成長需求（09A），能針對性地投入學習資源（14A）。管理建議：其成長效率極高，能主動吸收回饋並轉化為具體的進步動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3200, 'ANI_09', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「覺醒的架構師」。能意識到「自己作為系統一環」的作用與責任（09A），並從宏觀角度調整自身行為以優化整體連動（15A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3201, 'ANI_09', 'A (高)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「自我監控大師」。能敏銳感知社交場合的期望（09A），並在不失真誠的前提下展現符合公認優秀標籤的行為（23A）。警示：其完美表現可能隱藏了真實壓力，需關注其職業燃盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3202, 'ANI_09', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「思路清晰、反思靠事件觸發的行動者」。他拆解問題的結構很穩，即使資訊複雜或情境模糊，分析品質也能維持住——但對自己在這個過程中的狀態，他不一定有同步的注意。語氣是否強硬了、有沒有忽略某個關鍵人的回應、思路是不是已經跑偏，這些往往要碰到卡點或有人點出，才會進入他的視野。條件好的時候他能快速校正，但如果沒有外部觸發，他有可能一直推進、卻沒留意到過程中已經有些地方走歪了。管理上適合建立固定的任務後回顧節點，讓他有機會定期停下來看自己的行為模式，而不是全靠事中即時感知。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3203, 'ANI_09', 'B (中)', 'ANI_02', 'C', '與 ANI_02 (韌性) 低分聯動：表現為「情緒出現才察覺的波動者」。長期處於高強度或高度不確定的狀態下，他容易出現情緒耗竭或表現起伏，而他對自身狀態的覺察，通常要到情緒已經明顯波動之後才浮現。等他真正發現自己已經撐不住時，往往已經接近耗竭邊緣，很少能在那之前主動喊停或放慢腳步。旁人有時比他自己更早看出狀態不對，他卻還在往前撐，直到某個明顯的信號出現才停下來檢視自己。管理上宜安排固定的節奏檢查點，讓外部結構補上他目前還不穩定的自我覺察，在耗竭真正發生前先踩一次煞車。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3204, 'ANI_09', 'B (中)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) 高分聯動：表現為「間歇覺察的共識推動者」。他能在互動中以溝通與信任說服他人、主動拉攏不同立場建立共識，在這個過程中自然地吸引他人支持；但他對自身在過程裡的情緒狀態與言語影響，並非時時清晰。通常要等到他人明顯反應——沉默、保留、或場面轉涼——才會意識到自己的節奏或語氣其實偏了。管理上可在關鍵互動後提供具體的行為回饋，幫助他把外在線索轉化為下次更即時的自我校準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3205, 'ANI_09', 'B (中)', 'ANI_11', 'C', '與 ANI_11 (同理心) 低分聯動：表現為「重任務、覺察靠觸發的務實執行者」。他在執行過程中很專注於任務本身，互動的目的多半是推進工作，對周圍的情緒氛圍不太會主動去感知或回應。自身狀態的覺察也是同樣的節奏——不到特定時刻或有人直接說出來，他不容易意識到自己剛才的語氣或行為對氛圍留下了什麼。有時一個討論結束，別人帶著明顯的情緒走開，他仍然專注在下一步要做什麼，需要被明確告知才會回頭確認。對他而言，覺察不是缺席，而是在沒有觸發點時不會自動啟動。管理上適合給他直接、具體的情境回饋，說明何時他的反應方式對他人產生了影響，讓他有清楚的參照點來調整。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3206, 'ANI_09', 'B (中)', 'ANI_14', 'A', '與 ANI_14 (終身學習) 高分聯動：表現為「主動學習但自省節奏慢的發展者」。他有自發規劃長期學習的動力，能持續投入技能更新而不等外部要求啟動；但他對自己在學習過程中實際吸收了什麼、哪些盲點還沒有被觸及，並不總是有清楚的感知。只有在某個具體情境觸發——實際用到卻答不上來，或被他人點出落差——他才會停下來審視自身的進展。管理上可定期安排結構化的自評或同儕對話，讓他的覺察節奏和學習投入保持同步。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3207, 'ANI_09', 'B (中)', 'ANI_15', 'C', '與 ANI_15 (系統性思考) 低分聯動：表現為「片段連結的自我觀察者」。他思考多集中於單一面向，較少主動考慮連動影響，對自身狀態的覺察也呈現類似的片段性——他能察覺當下的情緒或反應，但不容易將它串回更早的觸發點，或預見這個情緒狀態接下來會影響什麼決策。當外部環境開始出現連鎖變化時，他的內在狀態有時已悄悄轉移，卻要等到結果出現才意識到。管理上宜提供視覺化的情境追蹤工具，讓他的覺察有外部結構可以依附，減少因連結不足而錯過的自我調整時機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3208, 'ANI_09', 'B (中)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) 高分聯動：表現為「形象壓力下的選擇性反思者」。在想留下好印象或感受到評鑑壓力時，他傾向以社會期待方式回應，偶爾也意識到自己的回答比實際狀態更理想化——但這份察覺通常在事後才浮現，當下的形象管理衝動往往跑在前面。他不是沒有自我覺察，而是在敏感或高期待情境下，覺察容易被壓下去，讓他在評估場合呈現出比真實狀態更整齊的樣子。管理上宜創造低評鑑感的對話情境，讓他的真實狀態有空間自然出現，減少形象保護對覺察的遮蔽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3209, 'ANI_09', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「盲目衝鋒的孤狼」。主動性極強（05A），但較少察覺自身行為對團隊的負面影響（09C）。風險：容易在追求目標的過程中，因無視他人反饋或過度擴張而造成組織內耗或個人口碑崩壞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3210, 'ANI_09', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「不知疲倦的過勞者」。一心追求高標準（08A），卻難以覺察身心耗竭的訊號（09C）。管理建議：主管需強制介入其休息節奏，並透過量化數據提醒其產出效率的下滑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3211, 'ANI_09', 'C (低)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「技術偏執的賦能者」。擅長運用 AI 工具（10A），但難以察覺個人偏見如何滲透進 AI 的應用過程中（09C）。風險：其產出的結果可能具備邏輯硬傷或忽視了現實中的倫理與情感維度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3212, 'ANI_09', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「刻板的執行員」。雖然高度可靠（16A），但在犯錯或表現下滑時難以自發察覺（09C）。管理建議：需提供即時、具體且非抽象的負面回饋，以啟動其被動的調整機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3213, 'ANI_09', 'C (低)', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「技巧型的外交官」。具備社交洞察力（21A），但對自身「動機」或「帶給人的壓力」覺察較淺（09C）。警示：容易讓人感到圓滑但缺乏真心，需輔導其強化內在反省。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3214, 'ANI_09', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「直覺型快決策者」。決策極快（22A），但往往意識不到個人偏好或情緒如何左右了決策（09C）。預測：在決策失敗後容易歸咎於外部環境而非個人判斷偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3215, 'ANI_10', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A聯動：表現為「AI應用的戰略家」。能從邏輯層面理解 AI 運作邏輯（01A），並精準評估其產出在實務中的價值與風險（10A）。預測：能引導組織做出穩健的技術導入決測，避免盲目跟風。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3216, 'ANI_10', 'A (高)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A聯動：表現為「數位轉型先鋒」。不僅能理解新工具（10A），還能隨技術迭代快速調整自身工作流程（04A）。管理建議：適合作為數位工具導入的種子人員（Early Adopter）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3217, 'ANI_10', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A聯動：表現為「AI賦能的發明家」。能將 AI 視為靈感的放大器（10A），利用科技產出跨越傳統框架的創新方案（07A）。預測：能大幅縮短從概念到原型的研發週期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3218, 'ANI_10', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A聯動：表現為「數位架構師」。能從全局角度思考 AI 導入後對各部門與流程的連動影響（15A），確保科技應用與整體戰略對標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3219, 'ANI_10', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A聯動：表現為「理性的監督者」。能敏銳察覺 AI 的局限性、幻覺或偏見（10A），並批判性地審核其產出的真實性與倫理風險（20A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3220, 'ANI_10', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A聯動：表現為「數據驅動的決策者」。能快速利用 AI 產出的資訊作為佐證（10A），並在不確定性中果斷下達具備實務支撐的決策（22A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3221, 'ANI_10', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「工具操作者遇上結構分析者」。他能開啟 AI 工具、跑出產出，在步驟清楚的情境下能完成任務流程，但碰到需要判斷產出是否合理、風險在哪裡的時候，他往往停在結果本身，不確定該從哪個維度切入評估。他在複雜或不確定的情境下仍能拆解問題、辨識模式、維持分析品質，而這份結構化判斷力在評估 AI 輸出時也同樣運作——他能比對資訊、找出邏輯缺口，不因情境模糊就失去框架。管理上宜讓他在 AI 操作後多一個自主評估環節，提示他把分析習慣帶進工具產出的核查流程，而非等待外部引導才觸發判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3222, 'ANI_10', 'B (中)', 'ANI_04', 'C', '與 ANI_04 (適應敏捷) 低分聯動：表現為「工具熟練但框架依賴的穩步操作者」。他能把 AI 工具跑起來、產出結果，在既有流程清楚的環境裡上手速度不慢；但當工具升版、任務情境轉變或需要自行判斷該用哪種 AI 方法時，他會停在原地等人告訴他怎麼接下去，不容易自己拆問題、重新摸索方向。碰到沒人給說明的新情境，他往往先繼續沿用熟悉的操作步驟，即使產出已不太對路也難以察覺問題出在哪。管理上宜預先給他明確的使用指引與情境說明，並在工具或流程有異動時主動給銜接說明，不要預設他能自行判斷適用範圍或評估風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3223, 'ANI_10', 'B (中)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) 高分聯動：表現為「工具執行者搭上框架外思考者」。他能穩定操作 AI 工具、依流程產出成果，但在策略層面——什麼情境值得用、風險在哪、有沒有更好的問法——仍需要旁人或情境提示才能判斷。他在思考上不受既有框架束縛，能提出跨越常規的新穎解法和觀點，對問題的看法有時出乎意料；但這份跳脫式發想在應用到 AI 工具時，缺少一個評估機制去確認哪些想法是可行的、哪些風險是工具無法自動排除的。管理上宜在創意發想後設一個實務可行性確認步驟，讓他把策略性判斷補進來，避免新穎想法停在嘗試操作而未經風險評估就推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3224, 'ANI_10', 'B (中)', 'ANI_15', 'C', '與 ANI_15 (系統性思考) 低分聯動：表現為「局部可用但全貌模糊的工具使用者」。他的思考多聚焦於單一面向，遇到 AI 工具整合進現有流程時，容易只看到「這個工具能做到 X」而不太考慮它對上下游的連動影響；AI 素養本身也停在操作層，策略性評估仍需引導。系統整體不透明時，他較難判斷何時該介入或停止。管理上需要替他明確描繪整個流程圖，並說明 AI 輸出在哪個節點可能造成擴散效應，才能幫助他做出邊界清楚的使用決策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3225, 'ANI_10', 'B (中)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) 高分聯動：表現為「工具操作者配上審慎評估者」。他能上手 AI 工具、跑出成果，但對於那些成果在策略上是否合適、底層邏輯有沒有問題，他不容易自行判斷，通常需要引導才會啟動評估。他在面對資訊時能穩定檢視可信度、比較不同觀點、不輕易跟著直覺走；即使時間有壓力，他也不急著簡化評估流程，而是保持對前提與依據的審慎態度。遇到 AI 工具的產出時，這份批判習慣同樣發揮——他會注意輸出是否有矛盾或不合邏輯之處，而不是照單全收。管理上宜引導他把批判性評估明確連接到 AI 應用情境，補上策略判斷的語言與框架，讓他有意識地把兩者整合運用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3226, 'ANI_10', 'B (中)', 'ANI_22', 'C', '與 ANI_22 (高效決策) 低分聯動：表現為「工具依賴下的決策延遲者」。他在多選項情境下本就傾向多蒐集資訊再定案，在 AI 應用場合更明顯——能操作工具產出多種結果，但缺乏策略性判讀能力時，這些產出反而成為決策的「更多選項」而非收斂依據。他可能反覆跑 AI 工具、比較輸出，卻難以判斷哪個結果可信或哪個時間點該停止蒐集。管理上宜預先替他設定「使用 AI 產出後的決策截止條件」，讓工具使用有確定的終止點，而非持續延伸不確定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3227, 'ANI_10', 'B (中)', 'ANI_02', 'A', '與 ANI_02 (韌性) 高分聯動：表現為「工具探索者配上穩定復原者」。他能操作 AI 工具、摸索流程、跑出基本產出，但在判斷這些產出的實務價值、評估風險或決定策略方向時，他還不確定自己的判準是否足夠，容易停在操作層等待確認。面對挫折或不順的情境，他不需要旁人特別介入就能自己調整過來，把困難看成可以調整的訊號而非卡關；就算 AI 工具沒給出預期結果、或流程出了差錯，他也能快速重整再試，不容易被單次失敗拖住情緒或節奏。管理上宜在他恢復後給予明確的策略框架或風險評估提示，讓他的韌性不只停在重跑操作，而能帶進更深層的判斷改善。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3228, 'ANI_10', 'C (低)', 'ANI_02', 'C', '與 ANI_02 (韌性) C聯動：表現為「數位焦慮者」。對 AI 感到陌生（10C），且在面臨科技衝擊時心理復原力較弱（02C），容易產生強烈的排斥感或職業恐慌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3229, 'ANI_10', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A聯動：表現為「傳統路徑的奮鬥者」。主動性高（05A），但因缺乏對 AI 工具的理解（10C），傾向於用傳統高耗能的方式完成任務。管理建議：應提供具體示範以引導其自發轉型。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3230, 'ANI_10', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A聯動：表現為「受限的精進者」。渴望卓越（08A），但因不熟悉 AI 應用（10C），其工作天花板受限於現有的人力產能，需透過培訓打破瓶頸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3231, 'ANI_10', 'C (低)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A聯動：表現為「數位轉型的潛力股」。雖目前仍處於摸索期（10C），但強烈的好奇心（13A）將驅動其快速學習。管理建議：提供安全且具體的試點專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3232, 'ANI_10', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A聯動：表現為「守穩傳統規範的執行員」。在既有系統中極其可靠（16A），但對缺乏 SOP 的 AI 工具持觀望態度（10C）。管理建議：將 AI 導入納入正式流程與規範。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3233, 'ANI_10', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A聯動：表現為「表面的數位配合者」。口頭認同科技重要性以獲取認可（23A），但實際操作時仍因不熟練而感到困頓（10C）。警示：應追蹤其真實的使用深度而非報告。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3234, 'ANI_11', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理性的療癒者」。能運用邏輯拆解他人的情緒來源與需求模式。預測：在提供支持時不僅具備溫度，還能給出具備結構化與可行性的建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3235, 'ANI_11', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「深具感染力的領導者」。能精準捕捉群體情緒並建立共識。預測：其說服力建立在「懂你」的基礎上，能大幅降低變革推行時的人際阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3236, 'ANI_11', 'A (高)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「高 EQ 溝通專家」。能清楚區分自身與他人的情緒邊界。管理建議：其高共鳴力不會導致個人情緒燃盡，是處理高度緊張人際議題的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3240, 'ANI_11', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「仁慈的指揮官」。決策果斷但會細膩地處理受影響者的心理安撫。管理建議：適合執行需要高執行力但涉及人事情感的組織任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3241, 'ANI_11', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「理性拆解型的務實關懷者」。他能感受到別人的處境，但情感回應偏理性與務實，而在複雜或不確定情境下，分析能力仍能穩定維持。別人說自己很困難時，他很快開始梳理事情的輪廓、追問根因，卻較少在意別人那一刻的感受是否需要被接收。他知道別人卡在哪、問題出在哪個環節，卻可能讓別人覺得被理解的是處境，而非自己當下的情緒。管理上宜提醒他在給出分析前先確認別人是否需要被聽，而非被解題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3242, 'ANI_11', 'B (中)', 'ANI_06', 'C', '與 ANI_06 (人際影響力) 低分聯動：表現為「低調的靜默觀察者」。他對別人的處境有一定的務實理解，但影響力多來自專業產出而非互動帶動，鮮少主動去說服或號召他人行動。他知道誰卡在哪、誰需要什麼，卻傾向把這份理解放在心裡，繼續專注完成自己的工作。外部看起來存在感不強，但因為他不輕易誤讀別人，在關鍵時刻反而能給出一針見血的意見。管理上宜創造讓他分享觀察的場合，否則他掌握的資訊容易留在個人層面、無法對群體產生作用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3243, 'ANI_11', 'B (中)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) 高分聯動：表現為「理性拆解型共感者」。他聽別人說話時，能站到別人的立場，理解別人在意什麼、卡在哪裡，但接下來的回應多半偏理性、務實，不太會停留在情緒本身。同一時間，他對自己當下是不耐、焦慮、還是真的在意，分得清楚，也說得出自己哪些反應容易被別人解讀成冷落或催促。遇到情緒濃烈的場合，他常先把別人的處境拆成幾個可以談的重點，再據此決定接下來要怎麼回應、要不要放緩語氣。別人有時覺得被看懂了，卻不一定覺得被陪著；管理上宜提醒他在拆解清楚之後，留一點時間單純陪伴，不急著給結論。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3244, 'ANI_11', 'B (中)', 'ANI_12', 'C', '與 ANI_12 (積極傾聽) 低分聯動：表現為「輪廓掌握但細節易失的理解者」。他對別人的狀況有務實的理解，但積極傾聽的穩定性不足，容易在多工或高壓下漏掉細節、或錯誤掌握別人真正說的重點。他在判斷別人「大概是什麼情況」上往往沒錯，但具體細節——別人說了哪一句、那一句的分量——可能很快就跑掉。開會時他點了頭，說了「了解」，但回去確認時常發現他抓到的是輪廓，不是別人那一層真正要表達的意思。管理上宜在重要互動後要求他複述關鍵訊息，幫助確認吸收的深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3245, 'ANI_11', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「系統框架中的處境分析者」。他能理解別人的觀點與處境，且能從整體角度看問題、預判連動效果。在他眼裡，別人的困境不只是個人問題，而是某個系統架構下自然會產生的結果；別人還在抱怨時，他已在想是哪個環節出問題、後面會波及什麼。但對別人當下那股情緒，他往往先跳過——他更想搞清楚的是「這個處境為什麼會發生」，不是「你現在感覺怎麼樣」。管理上宜在他開始系統分析之前，先確認別人是否需要被聽見，再進入診斷模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3246, 'ANI_11', 'B (中)', 'ANI_21', 'C', '與 ANI_21 (社交智商) 低分聯動：表現為「說出口才能理解的務實感知者」。他對別人說出來的處境能務實地理解，但對社交線索和關係動態較不敏感，容易忽略沉默、臉色、氣氛轉向這些沒說出口的信號。他能理解別人陳述的狀況，卻可能完全不知道別人同時釋放出的弦外之音。在人少且關係單純的場合他還能應付，一旦進到多人互動或權力結構複雜的場合，他看見的別人只剩「說出口的那一半」。管理上宜在複雜互動前給他明確的社交脈絡說明，不能假設他自己會讀到。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3247, 'ANI_11', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「行動先行的效率型關懷者」。他對別人的處境有理性的理解，且在資訊有限時能果斷定案、遇到變化也能快速調整。聽到別人的狀況，他很快就做出判斷、給建議、或直接幫忙拍板；他不是不在意別人，只是他的「在意」驅動的是行動，而不是停留在感受那一層。別人有時覺得他反應快、很有用，有時又覺得自己的情緒根本還沒被看到就被「解決」了。管理上宜提醒他在快速行動前，留給別人一點被聽見的節奏，才不會讓關懷落在別人感受不到的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3248, 'ANI_11', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「無情的計算機」。邏輯極強但無視人的情感成本。風險：其優化方案雖然理論正確，但往往因忽視人心反彈而在執行階段慘遭失敗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3249, 'ANI_11', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「自負的獨行俠」。自我驅動極強但缺乏對團隊的情感連結。管理建議：適合個人貢獻型工作，不宜放入需要高度協作或輔導他人的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3250, 'ANI_11', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「冷酷的高標者」。為達成卓越目標可以毫不猶豫地犧牲他人的感受。警示：高產出但會造成團隊的高流失率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3251, 'ANI_11', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「刻板的執行機器」。行為高度可靠但缺乏溫度。管理建議：適合與物、數據或規範打交道，而非與「人」的高頻對接。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3252, 'ANI_11', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「瑣碎的裁判者」。糾結於細節精確（17A）卻無視他人所處的困境或壓力（11C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3253, 'ANI_11', 'C (低)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「強悍的掠奪者」。談判技巧高（19A）但不在乎長遠關係與對方利益。預測：能贏得短暫勝利，但難以建立長期的戰略夥伴關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3254, 'ANI_11', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「虛偽的表演者」。行為符合社會禮儀以獲取認可（23A），但內心對他人需求毫無感應（11C）。面談重點：應觀察其在突發情緒衝突下的真實反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3255, 'ANI_12', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精準的解題專家」。能完全理解對方的意圖與細節（12A），並運用強大邏輯拆解問題（01A）。預測：其產出的方案不僅符合邏輯，且能精準擊中問題核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3256, 'ANI_12', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「深具魅力的溝通領袖」。說服力建立在「聽懂對方需求」的基礎上（12A），能透過引導與共識達成目標（06A）。管理建議：適合作為高階談判或變革管理中的共識建立者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3257, 'ANI_12', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「卓越的輔導教練」。不僅理解資訊，更能覺察情緒（11A）並透過提問確認需求（12A）。預測：在團隊中具備極高的信任感，能有效提升部屬或同事的向心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3258, 'ANI_12', 'A (高)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「戰略型談判者」。能精準捕捉對方隱藏的利益點與需求（12A），並在複雜利益衝突中找到共贏方案（19A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3259, 'ANI_12', 'A (高)', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「高敏銳的社交者」。在各種社交場合中，能透過傾聽快速掌握環境氛圍與他人動機，從而做出最得體的社交回應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3260, 'ANI_12', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「週全的決策指揮官」。決策雖然快速（22A），但並非魯莽，而是基於對所有利害關係人反饋的充分理解（12A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3261, 'ANI_12', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「條件清晰的結構接收者」。目標明確時，他聽進別人說的話後會自動歸納結構、找出關鍵資訊，分析品質相當可靠。但一旦任務多或注意力被分散，傾聽本身先掉線，聽到的內容殘缺，分析力再強也沒有完整材料可施展。給他明確的談話焦點，他能把接收到的東西整理得很到位；放進無結構的多議題對話，容易漏接又難補，事後需要額外確認才能重建完整資訊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3262, 'ANI_12', 'B (中)', 'ANI_06', 'C', '與 ANI_06 (人際影響力) 低分聯動：表現為「聽後輸出、難以即時帶動的溝通者」。他不太擅長在對話中感染或推動別人，影響力多半靠事後整理出具體建議或行動來取得認可。傾聽狀態穩時，他能把聽到的內容轉化為書面或結構性產出，這時他的影響才有機會落地；但對話進行中，他既不太容易接住全部資訊，也難以即時調整說法去說服他人。管理上，讓他在交流之後整理成書面建議，比要求他靠當場互動帶動他人更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3263, 'ANI_12', 'B (中)', 'ANI_11', 'A', '與 ANI_11 (同理心) 高分聯動：表現為「情境投入時的情感精準接收者」。當話題讓他全神貫注，他聽到的不只是字面，還能感受到別人說話時的情緒脈絡，並在聽完後給出切題的回應。問題在於傾聽底層有條件限制——多工或高壓時他先分心，這時他對別人情緒的感受也跟著出現缺口，給出的回應容易錯位。管理上，避免讓他在嘈雜或多任務的場合處理需要細膩感受的對話，給他專注的對話空間，他才能把情感線索接住並做出有效回應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3264, 'ANI_12', 'B (中)', 'ANI_19', 'C', '與 ANI_19 (協商談判) 低分聯動：表現為「傾聽不穩下的慣性讓步者」。他在聽取別人立場時容易被說服，又因為傾聽本身不穩定，有時漏接了自己真正在意的關鍵點，就已經點了頭。在意見分歧的場合，他既不太想對抗，又沒有穩定抓住全局，容易在還沒想清楚前就做出讓步。管理上，重要討論前讓他先整理自己的底線與核心訴求，並在過程中給他暫停確認的機會，防止他在傾聽不完整時就答應自己其實不同意的條件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3265, 'ANI_12', 'B (中)', 'ANI_21', 'A', '與 ANI_21 (社交智商) 高分聯動：表現為「聚焦時的線索敏感協調者」。目標清楚時，他不只接收資訊，還能察覺說話者的語氣轉換與言外之意，並在後續互動中自然調整應對方式。但一旦進入多工或高壓，傾聽先出缺口，社交線索的接收也跟著失準，有時話沒全聽完就已經在評估關係策略，反而造成落差。管理上，讓他在人數可控、目標明確的場合擔任傾聽與協調角色，效果明顯；避免讓他在資訊過載的群體場合同時承擔主要聆聽與關係調節的責任。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3266, 'ANI_12', 'B (中)', 'ANI_22', 'C', '與 ANI_22 (高效決策) 低分聯動：表現為「資訊不全下的反覆確認者」。他在聽取別人意見後整合起來，更容易陷入反覆比較、遲遲難以定案。加上傾聽本身不穩，漏聽的資訊讓他覺得還需要再問、再確認，決策時程因此拉長。管理上，討論結束後幫他整理聽到的重點，明確標出真正需要比較的選項，給他結構化的判斷框架，減少他在資訊不完整時自己兜圈子的機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3267, 'ANI_12', 'B (中)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) 高分聯動：表現為「追求卓越的選擇性傾聽者」。他對成果品質的標準抓得很緊，時常主動找方法把事情做得更精進、更突破現有水準。目標明確的討論裡，他一邊維持這樣的高標準，一邊也聽得專心，能抓住重點、主動追問、該確認的地方會確認清楚。一旦同時處理多件事、或時間壓力拉高，他的注意力會收窄，只聽進當下最貼近成果的部分，其餘細節容易漏接，就算那些細節事後看來同樣重要。管理上宜替他把每場討論的目標先說清楚、次要但必要的資訊另外用文字記錄，避免在他分身乏術或高壓的時段安排需要他全面接收訊息的場合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3268, 'ANI_12', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「自負的邏輯者」。分析能力強（01A），但因傾聽不佳（12C），容易在未聽完對方需求前就開始推演，導致「用正確的邏輯解決了錯誤的問題」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3269, 'ANI_12', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「急躁的追求者」。為了追求卓越績效（08A），往往忽視了他人的細節回饋（12C）。警示：雖有衝勁，但常因誤解指令而導致無效勞動，需主管頻繁確認進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3270, 'ANI_12', 'C (低)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「充滿善意的誤解者」。內心關心他人感受（11A），但因傾聽不足（12C）而常錯過對方的重點需求，造成「關心不到位」的尷尬。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3271, 'ANI_12', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「需書面化的執行員」。對承諾負責（16A），但口頭領受任務時容易漏失資訊（12C）。管理建議：所有的重要溝通必須留存文字紀錄或回報確認。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3272, 'ANI_12', 'C (低)', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「單向的傳遞者」。擅長發送訊息與資源協調（18A），但缺乏對他人的接收確認與雙向回應（12C），溝通鏈結易斷裂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3273, 'ANI_12', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「禮貌的失神者」。表面上點頭微笑以維持形象（23A），但實際上並未處理對方的資訊細節（12C）。面談重點：需觀察其對談話內容的具體摘要能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3274, 'ANI_13', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「深度的知識探究者」。不僅有探索渴望（13A），更具備拆解與理解底層邏輯的能力（01A）。預測：在面對新技術或新市場時，能迅速建立結構化的專業認知，而非僅停留在表面興趣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3275, 'ANI_13', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「多產的創新發明家」。好奇心驅動異質資訊的採集（13A），創意則將這些碎片連接成獨特方案（07A）。管理建議：其提議往往具備破框性質，是組織研發與前瞻計畫的核心推手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3276, 'ANI_13', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 應用的無限實驗者」。強烈的好奇心驅動其不斷挖掘 AI 的應用邊界（10A, 13A）。預測：能引領團隊探索出非典型、高效率的數位工作流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3277, 'ANI_13', 'A (高)', 'ANI_14', 'A', '與 ANI_14 (終身學習) A 聯動：表現為「自發性的學習機器」。將好奇心轉化為長期的教育投入（14A），其知識庫會隨著職涯長度產生複合增長效應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3278, 'ANI_13', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「跨領域的關聯發現者」。對各個領域的運作方式感興趣（13A），並能識別出這些領域如何作為一個系統相互作用（15A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3279, 'ANI_13', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「審慎的真相追尋者」。不僅想知道「是什麼」，更會運用批判性思維質疑現狀（20A），找出「為什麼不是」的改進契機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3280, 'ANI_13', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「問題導引下的分析探索者」。當面前的任務有清楚的問題框架時，他的探索動機會明顯升起，願意主動追問、深入細節；但若問題模糊或目標不明，探索的衝動便難以持續，容易停留在表面。遇到邏輯清晰、可逐層拆解的議題，他能一邊分析一邊延伸出新的提問，在來回推敲中逐漸進入狀況。管理上宜在任務啟動時先幫他釐清「到底要回答什麼問題」，有了清楚的入口，他的分析投入會明顯提升。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3281, 'ANI_13', 'B (中)', 'ANI_07', 'C', '與 ANI_07 (創造性思考) 低分聯動：表現為「有限框架內的謹慎試探者」。他的探索動機需要引導才能被喚起，而在發想階段又偏向沿用既有做法、不太主動提出新構想，因此對於開放式的創意任務往往反應冷淡，甚至感到不知從何著手。一旦有人提供具體問題或範例，他能依此展開探索，但探索的方向仍偏實務導向，很少主動往未知領域延伸。管理上建議給他有邊界的探索任務——明確說明「在這個範圍裡試試看」，比起讓他自由發揮更能讓他投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3282, 'ANI_13', 'B (中)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) 高分聯動：表現為「被清晰問題點燃的實務評估型探索者」。他的探索動機有賴問題清楚成形——話題模糊或缺乏具體需求時，他不太會主動追問或試探；但一旦情境聚焦，他的興趣便明顯升溫，願意繼續深挖。他能理解 AI 工具的應用範圍與限制，並對哪些場景值得投入、哪些風險需留意形成自己的判斷，不需等人引導才得出結論。管理上宜在會議或提案前先給他具體問題框架，讓他的探索動能有地方著力，也更能善用他對工具實務價值的評估眼光。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3283, 'ANI_13', 'B (中)', 'ANI_14', 'C', '與 ANI_14 (終身學習) 低分聯動：表現為「需求觸發才啟動的短期探索者」。他的探索傾向被動——有人提問或有任務壓力時，才會開始認真深入；平時不太有自發延伸學習的動力，對新技能的追求也多停在「夠用就好」的層次。工作中遇到明確的知識缺口，他能在短期內集中探索；但一旦任務結束，探索的動能也隨之消退，較少將這段投入轉化為持續累積。管理上需要定期提供新的挑戰性任務或問題，讓他維持間歇性的探索節奏，避免長期停在舒適圈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3284, 'ANI_13', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「脈絡連結下的延伸提問者」。當他能看見各個環節之間的關聯，好奇心會明顯升起，他從一個節點出發，順著連動關係延伸提問，逐步加深理解。但若任務缺乏整體脈絡，只丟給他零散資訊，他的探索動機就難以啟動，容易只停在表面回應。他能看出系統間的相互影響，探索時新發現往往被他直接擺進既有的整體框架裡對照、比較，而不是各自零散記著。管理上適合在任務初期給他整體概覽，讓他看見問題的系統輪廓，探索的投入度會隨之提升。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3285, 'ANI_13', 'B (中)', 'ANI_20', 'C', '與 ANI_20 (批判性思考) 低分聯動：表現為「引導啟動但缺乏深究動力的探索者」。他的探索依賴外部問題的帶動，批判評估資訊的動機也偏弱，探索過程中他傾向直接接受表面說法，很少主動質疑前提或追問證據。一旦得到一個「看起來合理」的答案，探索往往就此打住，沒有動力再往下追。他的探索多半繞著眼前這個問題打轉，離題稍遠的線索他很少主動去碰，對議題的理解也容易停在單一角度、沒有交叉比對。管理上宜在他回報進展時，主動追問「你怎麼確定這個結論是對的」，幫他養成對自己探索結果再做一層審視的習慣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3286, 'ANI_13', 'B (中)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) 高分聯動：表現為「目標驅動下的精進型探索者」。當任務目標清楚、他也在乎成果品質時，探索的動機最容易被啟動——他願意主動追問、嘗試不同角度，直到對成果感到滿意。但若任務重要性不明確或缺乏回饋，探索便只是隨機回應而非主動深入。遇到他高度投入的領域，他能在探索中持續精進、不輕易停在「夠用」；但這種狀態需要對目標的認同感作為前提。管理上適合在分派任務時說明「這件事為什麼值得做好」，讓他的探索動機與成果期待掛鉤，投入品質會明顯提升。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3287, 'ANI_13', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「專注的局部專家」。分析力強（01A），但對超出既有職責範圍的新知興趣低落（13C）。管理建議：適合擔任成熟穩定系統的分析師，但需注意其可能錯失跨領域的創新機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3288, 'ANI_13', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「目標導向的精進者」。追求完美（08A），但路徑高度固定，傾向於「將舊有技藝磨練到極致」而非探索新技術（13C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3289, 'ANI_13', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩健的既定程序守護者」。高度可靠（16A），不輕易偏離熟悉的流程去嘗試未知風險（13C）。警示：在需要破舊立新的變革環境中，其阻力通常來自於對舊秩序的安全感依賴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3290, 'ANI_13', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「細節控制的工匠」。對現有規範的精確度極高（17A），但對新規範或新知識的導入顯得被動且抗拒（13C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3291, 'ANI_13', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「基於過往經驗的快決策者」。決策雖快（22A），但因缺乏對新趨勢的好奇心（13C），容易陷入舊思維，忽視了環境已產生的重大變數。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3292, 'ANI_13', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「得體的守舊人士」。為了維持正面形象（23A），表面上可能表示接受新知，但內心缺乏真實的驅動力去學習（13C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3293, 'ANI_14', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「深度的專業建構者」。不僅投入學習（14A），且能透過邏輯拆解將零散資訊轉化為結構化的專業體系（01A）。預測：在面對複雜新領域時，能迅速建立具備商業價值的專業深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3294, 'ANI_14', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「靈活的跨域學習者」。學習動機強且能快速切換不同領域的思維框架（03A, 14A）。預測：極具斜槓潛力，能在多樣化的任務中不斷提取並遷移知識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3295, 'ANI_14', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「自我驅動的進化者」。不需要組織強制，會自發制定學習計畫並承擔個人成長責任（05A, 14A）。管理建議：應提供高度自主的培訓資源，鼓勵其帶動團隊學習氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3296, 'ANI_14', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「精英式的技能精通者」。將學習視為追求卓越、提升標準的唯一路徑。預測：其能力成長曲線呈複合式上升，是組織中高潛力人才（HiPo）的核心指標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3297, 'ANI_14', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位轉型長青者」。會積極且持續地追蹤 AI 技術發展（10A），並不斷更新個人應用策略以維持生產力領先。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3298, 'ANI_14', 'A (高)', 'ANI_13', 'A', '與 ANI_13 (好奇心) A 聯動：表現為「無限的知識探索家」。好奇心提供燃料，終身學習提供結構化的續航力。預測：知識庫廣博且更新速度極快，是組織內的知識中心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3299, 'ANI_14', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「清醒的學習家」。在吸收新知時具備極強的篩選能力（20A），確保所學資訊具備高度可信度與實務價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3300, 'ANI_14', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「需求觸發的結構化自學者」。當角色出現新要求或任務邊界擴張時，他才會啟動學習模式，但一旦投入，便能用邏輯框架快速拆解知識缺口，找到關鍵資訊並建立結構。沒有明確的任務壓力時，學習動機偏弱，傾向維持既有能力作答；一旦需求到來，他會先看清楚哪個知識缺口擋著眼前的目標，再把學習時間集中投在那裡。管理上宜定期以新任務或角色升級作為觸發點，幫他把學習與具體工作成果掛鉤，而不是期待他自發規劃長期課表。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3301, 'ANI_14', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「需求驅動但切換遲緩的學習者」。他的學習節奏跟外在需求走，需求清楚時會投入；然而在消化新知時傾向維持熟悉的思維路徑，對與既有認知差距較大的新方法需要比較長的時間磨合。角色需求出現後，他開始學習，但若新知識要求改變習慣做法，適應速度明顯較慢，初期可能卡在舊框架裡反覆套用不合適的方式。管理上宜在交付新要求時一併提供明確的步驟說明與過渡範例，讓他有具體錨點跟上節奏，不要只給大方向就期待他快速轉換。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3302, 'ANI_14', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「外部要求啟動、自我節奏執行的學習者」。他能在目標明確時自律規劃進度，對承諾有自我要求；但學習本身需要外在需求先出現才會啟動，並非主動規劃長期技能路線圖。一旦角色或任務帶來明確學習信號，他便能自主排定時程、追蹤進度，不需要頻繁督促。真正的風險在於沒有外部觸發的靜默期間，他較難主動為未來預備技能，可能在需求突然升級時出現短暫能力缺口。管理建議：定期透過角色對話或績效框架埋入前瞻需求，讓他有起跑信號，啟動後便能放手讓他自己執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3303, 'ANI_14', 'B (中)', 'ANI_08', 'C', '與 ANI_08 (卓越追求動機) 低分聯動：表現為「夠用就好的應需學習者」。他只在角色出現明確缺口時才啟動學習——有個具體任務要交才去搜資料、讀文件，任務結束後動能就自然停下來，不會延伸到任務以外的地方繼續鑽。對學到的東西，他的標準是「能用就夠了」：能讓眼前工作跑起來、不出包，就不再往下深挖或往上拉高。遇到工作相對穩定、沒有新需求敲門的時期，他幾乎不會自發去補新技能或修正舊做法，整體知識庫跟著節奏停在原地。管理上宜主動安排具體學習任務與明確目的，避免讓「自主更新」成為預設期待，並在新任務啟動前就植入學習環節，確保他有機會在需求出現前就備妥所需能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3304, 'ANI_14', 'B (中)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) 高分聯動：表現為「任務觸發的高辨識力學習者」。他對 AI 相關概念、應用情境與限制有紮實掌握，遇到要不要導入某項技術，能自己評估實務效益與潛在風險，不必依賴他人先做判斷。真正的學習開關，是角色或工作端出的具體要求：需求出現，他才開始收集資料、摸清操作方式，把新技術兜進手上的任務裡，成果也在動手做的過程中逐步產出。任務告一段落、沒有新要求進來的期間，他很少主動查看最新的技術動態或工具更新；手上的能力範圍停留在上一輪任務用到的部分，跟外部最新進展之間留著一段沒被追上的距離。管理上適合定期主動拋出具體的新工具或新場景任務，讓他在被賦予的情境中把評估與學習能力一起發揮，而不是留待他自己找空檔去追新。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3305, 'ANI_14', 'B (中)', 'ANI_13', 'C', '與 ANI_13 (好奇心) 低分聯動：表現為「需求觸發、興趣有限的技能補充者」。他在任務或角色要求明確時才啟動學習，而且投入範圍緊貼需求邊界，較少因為有趣或好奇就往外延伸探索。拿到一個學習任務，他會補足恰好夠用的知識，但不太會在找到答案後繼續深挖相關領域或延伸發問。對周遭而言，這樣的人在需求壓力下能穩定補技能，但在開放性探索任務或需要自發拓寬視野的場合會顯得動力不足。管理上宜給他清楚界定範圍的學習目標，讓他知道「學到什麼程度算完成」，避免模糊的自學要求讓他陷入毫無方向的焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3306, 'ANI_14', 'B (中)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) 高分聯動：表現為「審慎評估驅動的按需學習者」。當工作或角色需求觸發他投入學習時，他不只是接受新知，而是會先檢視資訊的可信度，比較不同來源，篩選出值得採納的部分。在關注重點明確的情境下，他學得紮實、留下的知識經得起檢驗；但若學習邊界模糊或時間緊迫，篩選與比較的步驟一道道走完，節奏就慢下來，對同類工作速度較快的同事而言顯得謹慎。他輸出的知識較為可靠，但學習啟動慢、範圍偏保守。管理上宜提前告知需求，讓他有足夠時間做評估性學習，而非等到最後才拋出任務，否則評估步驟易被壓縮，反而失去他的強項。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3307, 'ANI_14', 'C (低)', 'ANI_02', 'C', '與 ANI_02 (韌性) C 聯動：表現為「變革中的焦慮守舊者」。因缺乏更新技能的動機（14C），在面臨挫折或環境劇變時容易感到無力與恐慌（02C），應對策略極其單一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3308, 'ANI_14', 'C (低)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「應激式的調整者」。能快速適應新環境（04A），但其調整多來自外在壓力而非主動內化的技能提升（14C）。警示：雖短期配合度高，但長期可能因專業能力原地踏步而掉隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3309, 'ANI_14', 'C (低)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「工具型的使用者」。對現有 AI 工具具備基本掌握（10A），但缺乏持續追蹤技術迭代的熱情（14C）。管理建議：需主管主動推動技術升級資訊，否則其技術優勢會迅速過時。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3310, 'ANI_14', 'C (低)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「穩健的體系守護者」。能理解現有系統的運作（15A），但面對需要引入新技術或新範式的系統升級時，會因偏好舊能力（14C）而展現隱形阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3311, 'ANI_14', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「忠誠的守位執行員」。在既有職責與技能範圍內極其可靠（16A），但不願脫離舒適圈去學習新作法。管理建議：適合配置於穩定性高、知識更新需求較低的後勤部門。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3312, 'ANI_14', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「經驗導向的快決策者」。決策雖快，但決策基礎多來自過往舊經驗而非最新數據或新知（14C）。風險：在需要新知識判斷的場合容易因守舊而產生偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3313, 'ANI_15', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「總體架構師」。不僅能拆解細節（01A），還能看清各組件如何相互作用形成整體（15A）。預測：能精確診斷組織深層病灶，提出的方案兼具邏輯細節與全局穩定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3314, 'ANI_15', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「靈活的動態佈局者」。能理解全局（15A），並根據外部環境變動迅速調整系統內的關鍵權重（03A）。管理建議：適合作為複雜變革專案的總協調人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3315, 'ANI_15', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具備全局觀的遊說家」。說服他人時不僅靠口才，更會說明該變更對各部門的長遠連動效應，建立更穩固的跨部門共識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3316, 'ANI_15', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「系統性創新者」。其創意並非單點突破，而是能改變整體運作模式的結構性創新。預測：能引發組織內的典範轉移。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3317, 'ANI_15', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位生態架構師」。能預見 AI 導入對組織整體流程、人才佈局與倫理風險的全面影響（10A, 15A），確保科技應用與企業戰略深度融合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3318, 'ANI_15', 'A (高)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「嚴謹的風險預測家」。在審視全局時（15A），會主動質疑系統內的前提假設，識別出可能導致「蝴蝶效應」的隱藏偏誤（20A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3319, 'ANI_15', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的全局指揮官」。決策雖快（22A），但基於對整體關聯的精確預測（15A），能有效避免決策帶來的副作用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3320, 'ANI_15', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「清晰拆解下的系統局部整合者」。他在結構明確的場合能快速切入關鍵連結，把問題分層、找出主要脈絡，分析過程清晰有條理。一旦系統規模擴大、層次增加，他掌握全貌的能力開始跟不上，往往需要圖示或外部框架才能把各部分接回整體。這時他的邏輯依然紮實，能把局部拆得很準，但全局預判容易有缺口。管理上宜提供系統架構圖或視覺輔助，讓他的分析能力有機會與整體連結，而不是各自切塊後整合失焦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3321, 'ANI_15', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「熟悉框架內的局部關聯者」。他在熟悉的系統架構中能掌握主要關聯，知道哪些環節互相影響、哪裡可能出問題。當系統或做法需要調整時，他傾向在原有框架內找路徑，對需要更換底層邏輯的做法較難快速跟進，需要明確的必要性說明與具體步驟才願意轉換方向。遇到環境快速變動的場合，他的系統掌握能力容易因為框架不對位而失效。管理上宜先協助他理解舊框架與新要求之間的橋接關係，再推動他進行系統觀的調整。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3322, 'ANI_15', 'B (中)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) 高分聯動：表現為「能帶動共識的局部系統整合者」。他能在職責範圍內掌握主要關聯，並透過溝通與信任感讓周遭的人跟上他的系統思路，在需要建立共識的討論中能有效推動。當問題牽涉到更複雜的全局視野時，他需要視覺化或外部說明才能完整呈現系統樣貌，這時他的影響力仍在，但論述的系統深度可能不夠支撐長期說服。管理上宜協助他在主導溝通前先建立足夠的系統全圖，避免只靠影響力帶著眾人走，卻在細節連結上留下空缺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3323, 'ANI_15', 'B (中)', 'ANI_07', 'C', '與 ANI_07 (創造性思考) 低分聯動：表現為「按脈絡操作的穩健系統執行者」。他在理解現有系統的主要連動關係時表現穩定，能按照既有流程找出問題點並提出符合規範的處理方式。遇到系統需要重新設計或從零構想時，他較少主動跳出既有框架，解法多在現行做法的範圍內優化。高度複雜系統的全局整合仍需要視覺輔助，而突破性的系統再造不是他自然發出的動作。管理上宜將他安排在需要可靠執行既有系統邏輯的場合，若需要創新解法，則搭配發散型思考者共同作業。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3324, 'ANI_15', 'B (中)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) 高分聯動：表現為「能評估應用價值卻仍需視覺化輔助的系統分析者」。他能理解 AI 工具的應用情境與限制，也能自行評估引入某個工具帶來的實務價值與風險，不需要人從頭示範。遇到高度複雜的系統場景，他仍傾向於掌握主要關聯，若缺少結構圖示或分步說明，細部連動容易在腦中模糊。管理上可善用他的 AI 評估能力讓他為方案把風險關，但涉及多層系統互依的場景要為他提供視覺化框架，讓他的判斷有圖可靠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3325, 'ANI_15', 'B (中)', 'ANI_20', 'C', '與 ANI_20 (批判性思考) 低分聯動：表現為「觀察到關聯卻少自我追問的局部整合者」。他能掌握問題主要脈絡，在熟悉情境下看出系統間的重要關聯，但在高複雜場景需要輔助才能完整整合。他較少主動質疑自己整理出的前提與假設，傾向沿用既有結論而不把邏輯鏈拉回再驗證。在關鍵分析告一段落後，他往往停在「主要關係說得通」就收手，未必會追問是否有未被檢驗的邊界條件。管理上宜在他完成系統梳理後加入一輪外部追問，或指定一個明確的假設清單由他自查，避免遺漏未被觸碰的系統盲點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3326, 'ANI_15', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「快速定案但系統全局有缺口的行動者」。他在資訊不完整時也能快速做出判斷、往前推進，遇到變化能即時調整決策。他對主要關聯有一定掌握，能在決策時納入幾個關鍵連動因素，但對更深層的系統影響和邊緣效應容易低估，特別是在高度複雜系統中，他的決策速度有時走在系統理解的前面。這種落差在短期執行中看不出問題，在較長的行動周期後才顯現為未預料到的系統副作用。管理上宜在他拍板前安排一個檢核節點，幫助他確認主要系統連動已納入考量，而不是等副作用浮現才回頭補救。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3417, 'ANI_20', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「精確的指揮官」。決策快速且具備深度（22A, 20A），能確保決策品質在「速度」與「準確」間取得最優平衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3327, 'ANI_15', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「專注的局部專家」。細節拆解能力極強（01A），但難以察覺該局部優化是否會損害整體利益（15C）。警示：容易出現「贏了局部，輸了全局」的狀況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3328, 'ANI_15', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「盲目衝鋒的部門主管」。自我驅動極強（05A），但因缺乏系統觀（15C），其主動採取的行動常意外干擾其他單位的運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3329, 'ANI_15', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「狹隘的追求者」。追求最高標準（08A），但標準往往侷限於個人或當下職責，無視長遠或跨單位的負面衝擊（15C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3330, 'ANI_15', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的守位者」。高度完成任務（16A），但僅在被告知的範圍內負責，較難預見自己的延誤會對後續流程產生的骨牌效應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3331, 'ANI_15', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「見樹不見林的精算師」。糾結於局部數據的絕對精確（17A），卻未察覺該數據在整體系統中已失去參考價值（15C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3332, 'ANI_15', 'C (低)', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「單點式的傳令兵」。能清晰傳達訊息（18A），但缺乏對訊息背景與後續連動的理解，難以處理複雜的多方資源協調。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3333, 'ANI_15', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「迎合當下的老好人」。為了獲取即時認可（23A），可能做出讓當下滿意但對組織整體長期有害的承諾（15C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3334, 'ANI_16', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精確的工程師」。不僅能以邏輯拆解問題（01A），且能穩定兌現分析後的執行承諾（16A）。預測：其產出高度可預期，是負責核心架構與長期專案的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3335, 'ANI_16', 'A (高)', 'ANI_02', 'C', '與 ANI_02 (韌性) C 聯動：表現為「和平時期的模範生」。在穩定環境中極其可靠（16A），但一旦面臨變動或挫折，其一致性會因心理受創而出現短暫斷裂（02C）。管理建議：應在變動期給予其心理支持，以維持其原本的穩定輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3336, 'ANI_16', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「絕對獨立的推進者」。具備強烈的所有權意識（05A），且在無需監督的情況下仍能保持高標準交付（16A）。預測：這是組織中最珍稀的「自動駕駛型」人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3337, 'ANI_16', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「承諾必達的精進者」。追求卓越的標準（08A）並將其轉化為穩定的產出行為（16A）。預測：不僅做得好，且每一次都能如期交出高水準成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3338, 'ANI_16', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「穩健的數位實踐者」。能正確運用 AI 工具（10A）並確保留其產出的可靠性與合規性（16A），不會因技術過度依賴而產生風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3339, 'ANI_16', 'A (高)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「零失誤的執行官」。對細節的精確度（17A）與交付的時程（16A）有雙重執著。警示：容易自我加壓過重，需適時提醒其資源分配的彈性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3340, 'ANI_16', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「沉穩的指揮官」。決策果斷（22A）且對決策後的行動方案負責到底（16A），不因難度增加而推諉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3341, 'ANI_16', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「架構下的穩定輸出者」。目標明確、範疇說得清楚時，他很快就能把問題拆成幾個可執行的環節，抓住其中的關鍵變數與規律，對整條推進路徑有踏實的把握。他會按拆解出來的步驟逐項往前走，該交付的時間點提前講明、也準時兌現，合作的人對他的節奏漸漸抓得住預期。一旦任務邊界說不清楚、目標本身還在變動，他的分析照樣運轉、還是拆得出脈絡，找得到問題的切入點，只是少了明確落點可以判斷「做到什麼程度算完成」。這種時候他常反覆重新評估範疇、把同一份工作改了好幾個版本卻遲遲不拍板，原本說好的交付節點也跟著一延再延。管理上宜在任務啟動時就與他一起把具體範疇和驗收條件講清楚，讓清晰的問題結構替他撐起穩定的交付節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3342, 'ANI_16', 'B (中)', 'ANI_02', 'C', '與 ANI_02 (韌性) 低分聯動：表現為「壓力期易鬆動的條件可靠者」。目標明確、流程穩定時，他準時交付、說到做到，工作步調可以預期；一旦任務邊界變得模糊、方向又跟著變動，且這種狀態拖得夠久，他會明顯陷入情緒耗竭、精力跟不上，原本說好的交付時間開始往後挪，有些事項甚至被默默擱置沒說。這種掉下來的時間點通常沒有預兆，協作的人常常是到了原訂日期才發現他其實已經撐了一陣子。管理上宜留意他連續處於高壓或高度不確定的訊號，提前介入減少他當下承接的量、給予恢復空間，才能讓他在壓力期也維持住原有的交付節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3343, 'ANI_16', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「自驅但需要邊界的可靠交付者」。方向一旦確定，他會自己訂進度、主動往前推，不太需要別人催促，對自己承諾的成果也有明確要求；但任務邊界一旦模糊、目標還沒定案，他即使仍想主動推進，也常常抓不到該對齊的基準，進度容易停在原地一段時間，說好的時程跟著往後挪。任務越開放、邊界越沒訂清楚，這種停滯出現的頻率就越高，而且多半要等別人主動來問，才會被發現他其實已經卡住了。宜協助他在任務早期就自己先訂出幾個里程碑檢核點，讓他的自我管理有明確的錨點可以對齊，交付節奏才穩得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3344, 'ANI_16', 'B (中)', 'ANI_08', 'C', '與 ANI_08 (卓越追求動機) 低分聯動：表現為「低標穩定交付者」。目標明確時，他會依基本要求穩定交付，不拖延也不過度承諾。他在收到清楚範圍與流程後，會按部就班把每個項目完成到符合要求的程度，交件時間也大致可預期。但他不太會主動加碼、把成果拉到超出要求的水準，也很少自己額外檢視能不能做得更好。一旦目標本身變得模糊或中途調整，他的交付步調容易跟著鬆動，需要有人重新把範圍講清楚才能穩住。管理上宜在指派任務時把目標與驗收標準寫清楚，並在情境變動時盡快重新對齊，才能維持他原本的穩定產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3362, 'ANI_17', 'B (中)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) 高分聯動：表現為「品質驅動的條件性精準者」。當對任務成果有高度要求、清楚知道卓越標準的樣子時，他會在關鍵環節主動放慢節奏，仔細確認每個影響品質的細節。這種把關不是習慣性的，而是目標感強烈時才會觸發的專注狀態。一旦進入多工模式或目標感變模糊，他的細節注意力會分散，次要細節開始被放行。對周遭的影響是：他在高期待任務上往往令人放心，但在目標不明確或例行作業上需要額外的標準提醒，才能維持一致的把關品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3345, 'ANI_16', 'B (中)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) 高分聯動：表現為「熟工具期穩定、換工具期需要重新校準的執行者」。他能看懂一項 AI 工具適合用在哪裡、限制在哪，也能判斷值不值得投入、風險大不大；流程一旦確立、工具用法摸熟，他會把這些工具穩穩嵌進日常節奏，交付準時又穩定。但工具或任務要求出現大幅更新時，他得重新摸清楚新工具能用在哪、限制在哪，原本穩定的交付跟著鬆動、時程往後挪。熟悉的工具與流程裡他交付得又準又穩；一換到新工具或大改的流程，前面那幾週的交付常會掉下來，得花時間重新抓回節奏。新工具上線或流程大改時，宜提前給他清楚的過渡說明與適應期，讓他有機會重新評估應用情境與風險，交付才不會在轉換期掉鏈子。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3346, 'ANI_16', 'B (中)', 'ANI_17', 'C', '與 ANI_17 (準確嚴謹度) 低分聯動：表現為「結構明確時的可信交付者」。他在流程清楚時能按時完成，但對細節的敏感度不高，交出的產出裡偶有遺漏或小錯誤；在多工或時程緊縮時，細節落差更明顯，且他本人不一定察覺問題的存在。接收他產出的人需要預留檢核時間，尤其在精度要求高的任務上，不能單憑他說「完成了」就放行。給他搭配清楚的品質檢核清單，能幫助他把「按時交付」和「品質到位」同時做到。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3347, 'ANI_16', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「果斷出手、交付跟不穩的推進者」。資訊還沒到齊時，他不會等，很快就能拍板方向、往下推進，也願意承擔定案後的結果；狀況一變，他也能快速重新拍板、調整做法，不會卡在原本的決定上。只要拍板後的方向能維持一段時間、範圍沒有再變，他會照著新定案的內容準時交付，說到做到。但如果拍板後緊接著又是模糊的執行情境——這次的完成範圍算到哪裡、新的優先順序要不要正式取代舊的都還沒講清楚——他自己也未必第一時間意識到需要重新對齊，投入的心力就在「這個算不算數」之間忽高忽低。同一項任務有時被他調整方向兩三次，原本答應的交付時間點也跟著悄悄往後挪。管理上宜在他每次拍板或調整方向後，明確重新界定交付範圍與時間點，讓他的果斷判斷有清楚的執行錨點可以對齊，交付品質才穩得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3348, 'ANI_16', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「斷續的智多星」。思維極其敏捷（01A），但交付品質不穩定，容易因狀態不佳或瑣事分心而延誤（16C）。管理建議：需為其配置明確的進度追蹤系統。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3349, 'ANI_16', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「虎頭蛇尾的發起者」。主動發起專案的能量極高（05A），但缺乏持續收尾的毅力與責任感（16C）。警示：需有人協助其處理專案後期的「落地」執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3350, 'ANI_16', 'C (低)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「不穩定的天才」。想法極具突破性（07A），但產出的時效性與行為的一致性極低（16C）。管理建議：適合短期創意激盪，但不宜負責有嚴格 Deadlines 的正式流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3351, 'ANI_16', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「焦慮的夢想家」。渴望做出驚人成就（08A），但常因細節執行不力或一致性差（16C）導致理想無法變現，產生強烈的自我挫折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3352, 'ANI_16', 'C (低)', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「只說不做的傳令兵」。擅長傳遞與協調資源（18A），但當涉及需要個人親自承擔的最後一哩路交付時，往往會掉鏈子（16C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3353, 'ANI_16', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「禮貌的放鴿子者」。為了維持良好關係與認可（23A），會過度承諾自己能力以外的事，最後因無法達成（16C）而損害誠信。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3354, 'ANI_17', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精密邏輯分析師」。不僅能運用邏輯拆解問題，且能確保分析過程中的數據與細節無懈可擊。預測：在審計、精密研發或複雜數據建模中具備極高價值，產出極度可信。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3355, 'ANI_17', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「卓越的工匠型創作者」。具備跳出框架的點子，且對實現創意的每一處細節都有極高的品質堅持。管理建議：其作品通常兼具美感與實用性，適合負責高端產品設計或關鍵技術研發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3356, 'ANI_17', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「高品質的精進者」。對卓越的渴望 體現在對每一個小細節的極致打磨上。預測：會主動發現他人忽略的細微錯誤，是組織內部的品質標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3357, 'ANI_17', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 產出的嚴謹監督者」。擅長運用 AI 提升效率，但會對 AI 產出的結果進行細緻的人工查核，確保不出現技術性幻覺或偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3358, 'ANI_17', 'A (高)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「絕對零失誤的交付者」。行為穩定可靠，且交付內容永遠符合規格、無細微瑕疵。管理建議：適合擔任涉及重大合規、法務或關鍵營運流程的最後把關者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3359, 'ANI_17', 'A (高)', 'ANI_22', 'C', '與 ANI_22 (高效決策) C 聯動：表現為「因糾結細節而猶豫的專家」。為了追求絕對準確，常因資訊不夠完美而推遲決策。警示：容易出現過度分析（Analysis Paralysis），需外部給予明確的決策期限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3360, 'ANI_17', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「精準分析、重點守關的條件型把關者」。他在重要環節能認真核對、逐步拆解，遇到複雜或模糊的問題時，仍能調動邏輯結構把局勢理清楚，這種分析能力在高壓下沒有消失。但他對細節的把關力道是有條件的：任務優先序明確、專注資源充裕時，他能把關到位；一旦同時跑多條線、時間壓縮，精力自然往他認定的主軸集中，次要環節的細節就可能滑過去而沒被抓住。風險點在於他的分析視野未必同步覆蓋所有細節層次——能看清整體結構，卻可能在局部細節留下盲點，而他自己察覺不到。管理上宜替他列出哪些細節屬於「不可漏的次要項」，讓他在多工情境下仍有錨點，避免整體判斷準確、但細節執行出包的落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3361, 'ANI_17', 'B (中)', 'ANI_07', 'C', '與 ANI_07 (創造性思考) 低分聯動：表現為「創意保守下的細節守門人」。他在既有流程與標準作法的框架中工作，這種環境反而讓他的細節把關有了著力點——清楚的規格和慣例讓他知道要核查什麼。然而，當工作重心不在產出新方案而在執行既定程序時，他有時會把注意力花在合規查核而非主動辨識潛在風險，重要細節可能在忙碌的例行任務中滑過。管理上宜定期安排明確的查核點，提醒他在完成步驟之外也確認整體品質，避免細節把關流於表面。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3363, 'ANI_17', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「要害把關、末梢待熟悉的執行者」。他對任務的重要環節——結構正確性、規格符合、核心邏輯——通常能主動停下來確認，不輕易放過關鍵錯誤；但一旦多工並行或時間緊迫，注意力往往先留在要害處，次要的細節和邊緣格式就容易滑過。對於 AI 工具的操作，他還在摸索熟悉期，遇到需要示範或情境說明的步驟，會先停下來等待具體引導，不貿然假設自己已看懂。管理上宜替他明確標出哪些是必查項目，讓他在把關重點之外有具體清單可對照次要細節，並在引入新 AI 工具時提供逐步示範，縮短他的熟悉期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3364, 'ANI_17', 'B (中)', 'ANI_16', 'A', '與 ANI_16 (可靠性) 高分聯動：表現為「說到做到的重點把關者」。他答應的事幾乎都準時、如質交付，產出穩定到不太需要別人費心確認。細節上他會看情況：任務不趕、能專心處理一件事時，重要環節他都會查核到位、不輕易放過關鍵錯誤；但一旦身兼多工或時間吃緊，他的注意力會先留在要害處，次要格式或邊緣細節就容易被放過。管理上宜在任務初期確立查核清單與交付標準，把「哪些是必查項」講清楚，讓他的細節把關不必仰賴自己臨場判斷抓重點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3365, 'ANI_17', 'B (中)', 'ANI_22', 'C', '與 ANI_22 (高效決策) 低分聯動：表現為「猶豫決策下的細節漂移者」。他在面對多個選項時容易停在比較與觀望，把關的焦點也跟著散開——他知道細節重要，卻難以判斷現在應該停下來核查哪個。當決策點延後，他的細節注意力往往分散在多個待確認方向上，反而漏掉具體環節。對周遭而言，他的細節把關輸出不穩定，問題有時在最後才浮現。管理上宜為他設定明確的決策截點與查核順序，讓他知道何時停止評估、集中把關，避免細節在反覆猶豫中流失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3366, 'ANI_17', 'B (中)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) 高分聯動：表現為「敏捷環境中的節點型把關者」。他能快速覺察環境變化、積極回應新要求，快節奏裡他仍能挑出最關鍵的環節集中把關，而不是對每個細節一視同仁地耗時核查。但切換得快，轉去下一項前，細節確認常還沒收尾，次要細節便在快速推進中被略過。他的細節把關偏向「完成關鍵節點就移動」的模式，對品質要求嚴格的產出可能需要額外設定回顧機制，讓他在快速適應的同時，也能守住整體準確度、不隨節奏打折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3367, 'ANI_17', 'C (低)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「敏捷但粗放的先遣軍」。反應與調整速度極快，但在快速轉向中容易忽視細節規範。管理建議：適合開拓期任務，但需配備嚴謹的助理或查核系統進行後續補位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3368, 'ANI_17', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「高行動力但粗心的發起者」。具備強烈主動性，但因對細節敏感度低，其產出的方案往往需要頻繁修改才能落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3369, 'ANI_17', 'C (低)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「過度依賴工具的快速使用者」。雖懂技術應用，但容易直接照搬 AI 生成內容而不加核實細節。風險：可能導致系統性的小錯誤在組織中擴散。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3370, 'ANI_17', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「雖守時但常需退件的執行員」。會如期交付任務，但成果中常伴隨規格不符或小錯誤。管理建議：應提供結構化的 Check-list 強制其進行自我檢核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3371, 'ANI_17', 'C (低)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「能識大體但疏於校對的評論家」。能看出邏輯偏誤或大前提錯誤，但對文書格式、具體數據的小數位數等細節缺乏耐心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3372, 'ANI_17', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果斷但高風險的指揮官」。決策速度極快，但常因忽視細微變數或關鍵細節 而導致執行階段出現意想不到的紕漏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3373, 'ANI_18', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「結構化溝通大師」。不僅能協調資源，還能運用邏輯（01A）將複雜的工作流拆解成易懂的指令。預測：在跨部門合作中，能精準對接技術與業務語言，顯著降低溝通損耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3374, 'ANI_18', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「強大的共識建立者」。除了傳達訊息，還具備說服他人配合資源調整的能力（06A, 18A）。管理建議：適合作為大型變革專案的協調樞紐，能主動化解部門間的協作阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3375, 'ANI_18', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「高品質的同步者」。為了追求卓越成果（08A），會主動確保所有協作節點都保持高標準的資訊透明與效率（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3376, 'ANI_18', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「有溫度的協調者」。在分配資源或協調任務時，能理解並尊重各方的感受與困難（11A, 18A）。預測：其協調方式極具包容力，能有效凝聚團隊心理向心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3377, 'ANI_18', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局協作架構師」。能看清系統各部分的連動關係（15A），並據此做出最優化的資源配置與資訊同步（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3378, 'ANI_18', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果斷的調度者」。決策迅速（22A）且能第一時間將決策指令準確傳達到所有執行末梢（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3379, 'ANI_18', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「分析清晰但表達看情況」。他拆解問題的能力紮實，即使情境複雜也能維持條理，但把分析結果轉化成別人能收到的語言，就是另一回事了。工作方向明確時，他能把關鍵訊息說清楚，讓他人跟上思路；一旦同時處理多條線，他腦袋裡的分析照常運轉，但口頭或書面的交代開始跳節、細節交代不全，他人實際收到的資訊比他掌握的少。管理上宜在多工任務設下溝通節點，讓他定期把分析結果結構化輸出，避免頭腦清楚、協調卻出現落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3380, 'ANI_18', 'B (中)', 'ANI_06', 'C', '與 ANI_06 (人際影響力) 低分聯動：表現為「任務型溝通、鮮少主動帶動」。他的溝通以傳遞工作資訊為主軸——把事情說清楚、確認理解，互動就算完成；他不會主動透過對話去說服他人或帶動改變。工作方向明確時，這種模式足夠運作，事情能推進。但當情境需要他去凝聚共識或改變別人想法時，他往往把資訊說完就停下，缺少後續的推動動作，他人是否真的被帶到位，他不太去追。管理上宜在需要推動共識的場合替他設定明確的推進機制，不能只靠他自己察覺到需要更多跟進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3416, 'ANI_20', 'A (高)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「冷靜的談判專家」。能看穿對方在談判桌上的資訊誤導或心理戰術（20A），基於事實底線達成協議（19A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3381, 'ANI_18', 'B (中)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) 高分聯動：表現為「高標準、溝通轉譯是弱環」。他對做好事情有真實的在意，品質標準高，對成果的要求不會輕易妥協。但他腦袋裡對品質的高要求，不見得都能被轉譯成別人可接收的清楚訊息；工作場景簡單時他能說明到位，同時處理多件事或壓力升高時，重要的規格、期待或修改意見可能只說了一半，甚至沒說出口，結果他人按照自己理解做出來，與他心中的標準有落差，他才意識到溝通哪裡沒到位。管理上宜養成習慣在交辦後確認他人接收到的版本，以便提早發現落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3382, 'ANI_18', 'B (中)', 'ANI_11', 'C', '與 ANI_11 (同理心) 低分聯動：表現為「任務導向、情緒訊號接收薄的溝通者」。工作需求明確時，他能把該交代的事項講清楚，重點與進度也能有效傳達，訊息一來一往順暢，事情持續往前推進。但他在互動當下很少主動去體會他人正帶著什麼情緒進入對話，訊息說完、別人點頭或簡短回應，他就當這輪溝通已經完成，不會再多留意語氣裡透出的猶豫或不安。高壓或多工的時候，他原本就容易漏掉部分資訊，這時若他人是帶著顧慮或不滿前來，他往往接不住那層訊號，仍照原本步調把任務往下推，對話表面順利、情緒面卻沒被碰到，久了容易在關係或氣氛上悄悄留下落差。管理上宜在重要溝通後另外確認他人的實際感受，不能只看任務是否交代完成，就判定溝通已經到位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3383, 'ANI_18', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「全局在胸、溝通轉譯不穩定」。他能從整體角度掌握問題的連動關係，腦袋裡有一張系統圖，知道各部分如何牽動彼此。把這張圖說給他人聽時，成效會隨情境起伏——任務邊界清楚、節奏穩定時，他能把系統邏輯講清楚，他人能拼出完整樣貌；一旦同時要處理多個脈絡或溝通頻次增加，他的表達開始跳點，交代不完整，他人接收到的是碎片而非全圖，在協調或分工上就容易出現誤解。管理上宜在多脈絡任務要求他用結構化格式輸出系統邏輯，補足口頭溝通的落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3384, 'ANI_18', 'B (中)', 'ANI_22', 'C', '與 ANI_22 (高效決策) 低分聯動：表現為「立場未定前的猶豫傳達者」。需求清楚、情境單純時，他能有效組織語言、傳達想法，溝通是流暢的。但面對有多個選項的議題，他在心裡的反覆比較尚未收斂，話說出口時往往帶著猶疑的邊緣——不是缺乏溝通意願，而是他自己還沒有定案，訊息說到一半就被自己重新評估拉回。高壓或多工的情境下，資訊遺漏的風險本就升高，這時他對要傳達的方向又持續斟酌、不易落地，讓聽的人難以抓住他真正的立場。管理上宜在溝通前先協助他收斂選項範圍，讓他帶著相對確定的方向開口，而非期待他在對話中邊說邊定案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3385, 'ANI_18', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「框架到位時的穩定推進者」。他在溝通上的發揮與外部框架的清晰度緊密連動：當任務目標明確、節奏由他主導且有清楚的檢核點時，他能主動傳達進度、同步資訊，並在互動中保持穩定的節奏感；但一旦框架模糊或期待不清，他往往在溝通上退到等待確認的狀態，資訊傳遞的主動性也跟著下降。他不是缺乏意願，而是在方向未定時難以確定該說什麼、說給誰聽。這在需要對多方持續更新的複雜任務中，可能造成關鍵資訊傳遞出現斷點。管理上宜在任務啟動時協助他設定溝通節奏與對象，讓他的表達動能有清楚的出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3386, 'ANI_18', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「孤軍奮戰的執行者」。自發性極強（05A），但因協調意願低（18C），常在不與他人同步的情況下超前部署，造成團隊節奏脫節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3387, 'ANI_18', 'C (低)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位孤島的使用者」。雖擅長 AI 工具（10A），但缺乏將科技產出分享給團隊或進行跨員調度的習慣（18C）。警示：其個人生產力極高，但難以轉化為團隊資產。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3388, 'ANI_18', 'C (低)', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) A 聯動：表現為「沉默的吸收者」。能聽懂所有細節（12A），但較少主動將這些資訊對外傳遞或用於協調資源（18C）。管理建議：需強制其設定定期回報機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3389, 'ANI_18', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「穩定的末端執行員」。對自身任務高度負責（16A），但不擅長與上下游環節進行協作與進度同步（18C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3390, 'ANI_18', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「沈默的細節控」。在個人範圍內極度精確（17A），但面對需要多方配合、模糊度高的資源協調時會感到手足無措並退縮（18C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3391, 'ANI_18', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「避免衝突的傳令兵」。過度在意正面認可（23A），使其在需要強力協調資源或傳遞困難訊息時，傾向於避重就輕（18C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3392, 'ANI_19', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「理性的價值挖掘者」。能運用邏輯拆解對方的利益結構（01A），並據此設計多套雙贏的替代方案。預測：在複雜的採購、併購或合約談判中，能精準找到利益交集點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3393, 'ANI_19', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「敏捷的策略家」。能根據談判桌上的動態變換思考框架，當 A 方案受阻時，能迅速切換至 B 方案（03A, 19A）。管理建議：適合處理高度模糊、非典型且需要即興發揮的談判任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3394, 'ANI_19', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「強悍的氣場掌控者」。不僅具備策略，更懂得運用心理技巧與說服力（06A）來引導對方接受自己的條件。預測：在需要爭取核心資源或改變對方既定立場時表現卓越。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3395, 'ANI_19', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「溫和的價值創造者」。能真心理解對方的痛苦與需求（11A），透過建立信任來消除防禦感。預測：能與合作夥伴建立長期、互惠的戰略關係，而非一次性掠奪。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3396, 'ANI_19', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局利益維護者」。談判時不只看當下利益，更能預測協議對整體組織生態的長遠影響（15A）。管理建議：適合擔任涉及公司戰略轉型的核心談判官。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3397, 'ANI_19', 'A (高)', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「外交官般的談判手」。具備極強的社交洞察力（21A），能敏銳捕捉對方的微表情或情緒變化，精準拿捏進退分寸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3398, 'ANI_19', 'A (高)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢的協議終結者」。在談判陷入膠著時，能果斷判斷底線並做出決定（22A），避免因過度拉鋸導致機會成本喪失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3399, 'ANI_19', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「備戰型的沉穩拆解者」。準備充分或面對熟悉場合時，他能把利益、底線、可能走向都推演清楚，談判桌上條理分明；即便場面轉趨複雜或訊息不完整，他也能維持邏輯拆解、辨認出關鍵資訊與模式，不輕易被表象牽著走。但一旦現場節奏加快、出現他沒預設的方向，原本準備好的框架開始不夠用，他需要多花時間重新拆解眼前局面，反應速度會慢下來。管理上宜在事前給他充足的資料與準備時間，臨場變化大的場合搭配即時支援，讓他的分析力有機會延續到框架之外。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3400, 'ANI_19', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「劇本依賴型的談判者」。準備充分或熟悉場合時，他能照著設想好的路徑推進、掌握節奏；面對突如其來的轉折，他傾向先維持原本的做法，需要看到明確理由和具體步驟才願意換方向。一旦情勢偏離準備好的劇本，他容易卡住：原有框架失去效力，新的因應方式又還沒建立，他的立場會顯得僵固，甚至被他人察覺策略固定、失去主導。管理上宜替他準備多套備案並明確標出切換時機，降低他臨場改弦更張的門檻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3401, 'ANI_19', 'B (中)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) 高分聯動：表現為「人際資本豐厚的情境型談判者」。在準備充分或熟悉的談判場合，他能把影響他人的能力發揮出來——透過建立信任、說服、調整溝通方式，讓推進過程帶著人情潤滑；即便在技術性強的議題上，他也能靠關係維持合作氣氛。但臨場突發變化一出現，他傾向先回到人際策略——靠關係緩衝、靠氣氛維持——而這有時會讓他在需要果斷重劃條件的時刻猶豫，繞道用人情取代直接的立場調整。管理上宜幫他練習在人際優勢之外，同步鎖定核心條件的底線，避免人情優勢成為讓步的軟化劑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3402, 'ANI_19', 'B (中)', 'ANI_11', 'C', '與 ANI_11 (同理心) 低分聯動：表現為「條款導向的任務推進者」。準備充分或面對熟悉對象時，他能穩健推進立場與條件，聚焦在把事情談成；但他對他人情緒的主動感受和回應本來就少，互動多半圍繞在任務本身進行。談判過程中，他容易只盯著議題本身往前走，對現場的情緒起伏、語氣變化較無感知，關係層面出現裂縫也不容易察覺。若情緒因素影響到談判走向，他往往等到局面卡住才意識到問題不只在條件本身。管理上宜為他補上情緒線索的提醒機制，或安排能補足這塊的人一起參與。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3403, 'ANI_19', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「全局布局的框架談判者」。準備充分時，他會把這場談判牽動的上下游關係、後續影響都納入考量，從整體角度預先設想連動效果，談判策略不只放在眼前條件上。但這套布局建立在事前準備之上，一旦臨場出現重大變化，他既有的整體規劃被打亂，需要重新梳理各環節如何互相牽動，節奏放慢下來。若現場節奏被主動打亂，他可能得先花時間確認全局是否還成立，才敢再往下推進。管理上宜在快速變動的場合為他保留重新校準全局的時間，別急著要他立即回應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3404, 'ANI_19', 'B (中)', 'ANI_21', 'C', '與 ANI_21 (社交智商) 低分聯動：表現為「框架依賴的線索遲鈍者」。熟悉對象或準備充分時，他能照著預期的節奏把談判推進到位；但他對場上釋出的社交暗示與關係變化本來就不敏感，互動策略偏固定，不太會因應細微訊號調整做法。情勢起變化時，他特別容易吃虧：既沒有現成框架可以套，也難即時讀出他人語氣或態度已經鬆動，容易在心裡積累誤會，或錯失他人其實留了轉圜空間的訊號。管理上宜替他建立明確的訊號檢查清單，並在重要談判前後安排覆盤，補足他對關係動態的感知。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3405, 'ANI_19', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「果斷但框架依賴的情境型談判者」。現場需要快速定案時，他能在資訊不完整的情況下做決定、不拖、不反覆猶豫；遇到突發狀況也能迅速選定方向繼續推進，不讓談判因猶疑而失速。但他的果斷是在既有框架下的快速執行——準備充分的場子他決得快也決得準，若現場要求他跳出原框架重新定義條件，他的決策速度依然快，但著陸點可能停在熟悉的舊位置而不是最合適的新位置。管理上宜在談判前就把可接受的調整空間和底線明確化，讓他的果斷有更精準的落點，而不只是快速回到既有腳本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3406, 'ANI_19', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「勤奮但易妥協的執行者」。主動性高且對自身任務負責（05A），但一旦需要與外部爭取資源或面對強勢對手時，容易退讓（19C）。管理建議：其身後需有強力的法務或商務輔助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3407, 'ANI_19', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「自省但無力的完美主義者」。自我要求極高（08A），但因不擅長對外爭取支持或處理衝突（19C），常導致其高標準因資源匱乏而無法實現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3408, 'ANI_19', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「忠誠的秩序維護者」。非常可靠（16A），但在面對不合理的組織要求或外部壓力時，容易因避免衝突（19C）而承擔過多不合理的責任。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3409, 'ANI_19', 'C (低)', 'ANI_18', 'A', '與 ANI_18 (協調溝通) A 聯動：表現為「單純的訊息傳遞者」。能清晰同步各方資訊（18A），但在協調資源分配發生衝突時，傾向於犧牲己方利益以求和諧（19C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3410, 'ANI_19', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「討好型談判者」。過度在意社會認可與形象（23A），使其在談判桌上不敢堅持立場，破壞「好人」形象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3411, 'ANI_20', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「嚴密的邏輯檢察官」。不僅能拆解問題模式（01A），還會嚴格審核數據來源與邏輯前提的可信度（20A）。預測：在組織面臨重大策略抉擇時，能提供最客觀、去偏誤的專業審核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3412, 'ANI_20', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「理性的策略切換者」。具備切換思維框架的能力（03A），且每次調整都基於對證據的冷靜評估（20A），而非盲目跟風。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3413, 'ANI_20', 'A (高)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「務實的革新者」。點子多樣（07A）但能自我審查創意的可行性與邏輯漏洞（20A）。管理建議：其提議往往最具備實施價值，因已預先排除不切實際的幻想。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3414, 'ANI_20', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 幻覺的終結者」。理解 AI 應用（10A）但對其產出保持高度警覺，能識別出 AI 生成內容中的偏見與錯誤（20A）。預測：能確保組織在安全、合規的軌道上運用 AI 產能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3415, 'ANI_20', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局風險精算師」。能看清系統連動（15A），並批判性地評估系統中關鍵節點的脆弱性（20A），預防連鎖反應導致的崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3418, 'ANI_20', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「結構清晰下的選擇性檢視者」。他能穩定拆解資訊、辨識模式，在議題聚焦、節奏從容時，批判性的追問會在清楚鎖定的環節充分展開。一旦任務量增大或時間收緊，他會把評估資源集中在已拆解出的關鍵點，其餘部分的前提與假設未必受到同等的主動質疑。管理上宜在高壓期協助他明確標出「哪些假設尚未核查」，讓他在時間充裕的節點有機會補上選擇性略過的環節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3419, 'ANI_20', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「框架穩定下的聚焦評估者」。他在既有思考架構內能對關注的重點進行扎實的判斷，面對需要切換方法或引入新視角的情境，則傾向維持熟悉的評估路徑，對框架外的新角度較少主動納入檢視範圍。時間壓力一來，評估流程更容易縮窄在已知框架的核心假設上，框架外的可能性較難進入稽核視野。管理上宜在變化情境出現時，提供具體的必要性說明，協助他看到展開更廣評估的理由。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3420, 'ANI_20', 'B (中)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) 高分聯動：表現為「新穎構想下的批判稽核者」。他能在議題重點明確時展開判斷，面對來自不同觀點與跳脫框架的新穎解法，他的批判性評估有機會在探索期找到著力點，對構想的可行性與前提進行追問。時間壓力升高或議題邊界模糊時，評估流程容易收窄，對構想背後假設的主動質疑可能減少。管理上宜在構想多元、節奏快速的情境中，給他預留稽核的時間窗口，避免評估在壓力下過早收攏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3421, 'ANI_20', 'B (中)', 'ANI_10', 'C', '與 ANI_10 (AI科技素養) 低分聯動：表現為「工具陌生下的評估收窄者」。他在關注重點清楚、情境熟悉時能有效展開批判性判斷；遇到對 AI 概念與應用尚在熟悉階段的情境，工具運作邏輯仍需具體示範才能掌握，批判性評估的著力點較難穩固落地，評估範圍容易收窄到可直接觀察的輸出面。時間壓力再疊加時，評估流程進一步簡化的機率更高。管理上宜搭配具體的示範與情境說明，讓他能在工具較熟悉後找到足夠的評估基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3422, 'ANI_20', 'B (中)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) 高分聯動：表現為「系統連動下的聚焦評估者」。他能從整體角度理解各環節相互影響、預判連動效果，在重點明確時，批判性的追問有機會落在系統的關鍵節點，對核心假設進行細緻評估。時間壓力一來，評估流程容易簡化，部分連動環節的假設未必受到主動質疑，整體稽核深度隨之收窄。管理上宜在任務規劃階段協助他標出高風險節點，讓批判性評估在壓力期仍能集中在最關鍵的連動假設上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3423, 'ANI_20', 'B (中)', 'ANI_19', 'C', '與 ANI_19 (協商談判) 低分聯動：表現為「看得清楚、卻說不出口的觀察者」。當討論的焦點夠明確、節奏不急時，他能識破論點中的漏洞、注意到前提站不住腳；但一旦進入有爭議的對話，他傾向先讓一步、繞開衝突，那些剛剛看清楚的問題往往就沒說出口。時間一拉長，他會察覺自己其實早就看出問題、卻在當下選擇避開，事後心裡有些悶，卻也不一定回頭再開口。管理上宜在評估階段給他充分的獨立思考時間，讓他能在非衝突情境中書面提出觀察，降低他因為不想正面對抗而把判斷壓回去的機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3424, 'ANI_20', 'B (中)', 'ANI_22', 'A', '與 ANI_22 (高效決策) 高分聯動：表現為「果斷決策下的選擇性評估者」。他即使在資訊有限的情境下也能快速定案並承擔結果，遇到變化能迅速調整方向。在關注重點明確時，他的批判性評估會在決策前展開，對關鍵假設進行追問；一旦時間壓力加劇，評估流程容易簡化，決策雖仍能果斷推進，但部分前提與證據的稽核深度可能不足。管理上宜在快速定案後預留回頭驗證的節點，讓批判性稽核在決策週期中有機會補上壓力期略過的環節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3425, 'ANI_20', 'C (低)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具感染力的傳聲筒」。雖具備說服他人的能力（06A），但因缺乏獨立判斷（20C），容易將錯誤的資訊或未經證實的觀點有效擴散至團隊，具備隱性誤導風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3426, 'ANI_20', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「勤奮但盲目的追求者」。極度追求高標（08A），但因不善質疑任務的前提與證據（20C），容易在錯誤的方向上投入極大心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3427, 'ANI_20', 'C (低)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「AI 生成內容的順從者」。雖懂得操作 AI（10A），但傾向於無條件相信 AI 的答案（20C）。警示：容易因疏於查核而產出具備低級錯誤或誤導性的工作成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3428, 'ANI_20', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「守舊的規範執行員」。非常可靠地執行承諾（16A），即便既定流程已出現明顯邏輯漏洞，也會因為缺乏質疑意識（20C）而繼續執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3429, 'ANI_20', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「魯莽的快決策者」。決策極快但過於依賴直覺或他人觀點（20C），在高風險情境下極易因偏誤而導致重大失誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3430, 'ANI_20', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「盲從社會共識的老好人」。為了獲得認可與合規感（23A），傾向於接受大多數人的觀點而不加反思（20C），缺乏獨立人格。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3431, 'ANI_21', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「人際策略分析家」。能運用邏輯拆解社交線索與利益關係（01A），並精準調整互動策略（21A）。預測：在複雜的政治環境或高階社交場合中，能迅速辨識權力核心並建立有效的聯盟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3432, 'ANI_21', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「深具魅力的領導者」。不僅具備說服力（06A），更能讀懂對方的心理防線並適時轉換風格（21A）。管理建議：適合作為跨組織協作的對外代表，能以高度靈活的手腕達成共識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3433, 'ANI_21', 'A (高)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「內外合一的社交高手」。對內能察覺自身情緒（09A），對外能讀懂關係動態（21A）。預測：互動風格真誠且具備邊界感，極少發生社交失言，是建立心理安全感的關鍵人物。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3434, 'ANI_21', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「溫暖的連結者」。能感同身受（11A）並轉化為得體的應對方式（21A）。預測：在團隊中具備極強的非職權凝聚力，是調解衝突、安撫人心的核心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3435, 'ANI_21', 'A (高)', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) A 聯動：表現為「高敏銳的接收處理者」。透過傾聽吸收細微資訊（12A），並即時根據情境反饋最合適的社交語言（21A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3436, 'ANI_21', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「組織動態架構師」。能從全局看清各部門間的關係網路（15A），並透過關係管理優化整體工作流（21A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3437, 'ANI_21', 'A (高)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「頂尖的外交官」。談判時能讀懂對方的「潛台詞」（21A），在多方利益糾葛中游刃有餘地達成雙贏協議（19A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3438, 'ANI_21', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「分析清晰但社交切換有時差的觀察者」。一般場合他能拆解問題、維持清晰邏輯，與人互動也不成問題；一旦進入人際關係複雜、潛規則多的場合，他的分析能力仍在持續運作，卻需要時間讀懂誰在意什麼、誰和誰之間有什麼。這段適應期間他往往先把精力放在理解問題本身，社交層面的感知與調整稍微落後。管理上宜在複雜人際任務前先讓他有觀察期，或提供社交情境的背景說明，讓他能在分析與人際兩個維度同步進入狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3439, 'ANI_21', 'B (中)', 'ANI_06', 'C', '與 ANI_06 (人際影響力) 低分聯動：表現為「情境調適型的產出影響者」。一般情境下他能穩穩維持互動、跟上節奏；一旦碰上複雜的權力關係或衝突場面，需要主動帶領的場合他傾向繼續等待，複雜場合的窗口期常在他還沒出手時就過去。他平常想影響人，靠的多半是把事情做出成果，不是靠當場說服或帶動；主動站出來要別人改變想法，這種畫面在他身上並不常見。需要即時穩住場面、化解衝突的時刻，他常還在觀望要不要開口，等他真的要動作，時機已經過了大半。管理上宜在複雜或衝突情境提前為他標出關鍵時間點，並適度指定他在特定環節主動發聲，讓他的專業份量有機會轉成當下的帶動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3440, 'ANI_21', 'B (中)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) 高分聯動：表現為「慢半拍但看得清的調整者」。一般的日常互動他能維持得順、應對自然；一旦場面牽涉複雜的權力位階或情緒對峙，他需要一段時間才跟得上狀況，當下常有反應慢半拍的幾拍。但他對自己的情緒與行為模式向來看得清楚，那幾拍卡住的時候他能具體感覺到自己正在跟不上，事後也說得出來：「剛剛那裡我沒跟上」，並且清楚知道卡住的是哪一句話、哪個反應。下一次遇到類似的權力或衝突場面，他會主動放慢自己開口的速度、先觀察一輪再回應，慢半拍的落差一次比一次小。管理上可以在他進入高張力場合前先給背景資訊、留準備時間，複雜的權力互動後也適合安排簡短覆盤，讓他把卡住的地方講清楚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3441, 'ANI_21', 'B (中)', 'ANI_11', 'C', '與 ANI_11 (同理心) 低分聯動：表現為「先顧進度、後補情緒的互動者」。一般的日常互動他能維持得順、對話自然；複雜的權力或衝突場面則需要一段時間才跟得上狀況，那段適應期他容易只顧著把任務往前推。他的互動節奏本來就偏任務導向，情緒性的線索——聲音變小、話講到一半停下、視線飄開——這類訊號常常沒被接住，適應複雜場面的當下更容易只回應字面內容、漏掉底下的情緒。等場面穩定、他跟上狀況之後，互動又能回到順暢，但漏接的情緒線索不會自動補回來，可能已經在互動裡留下小落差。管理上遇到高張力或情緒濃的場合，適合事前或事後幫他標出情緒訊號出現的位置，補上他在還沒跟上狀況那段空檔裡容易漏掉的部分。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3442, 'ANI_21', 'B (中)', 'ANI_12', 'A', '與 ANI_12 (積極傾聽) 高分聯動：表現為「聽得完整、跟上得慢的互動者」。一般情境下他互動得自然，聽誰說話都能接得住；一旦場面轉向複雜的權力或衝突，他需要一段時間才跟得上狀況。那段適應期他反而聽得特別仔細——會多問一句確認自己聽到的沒錯，也會把別人講出來的內容盡量接完整，不急著回應，先把內容層面顧住，不因為還沒讀懂全局就漏掉關鍵資訊。等他跟上整體狀況之後，原本靠提問補的那部分理解會被自己的判斷取代，互動節奏也跟著回到順暢。管理上複雜的權力或衝突場合適合讓他多問、多確認，先把資訊面顧住，再給他時間跟上情緒與局勢層面的部分。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3443, 'ANI_21', 'B (中)', 'ANI_15', 'C', '與 ANI_15 (系統性思考) 低分聯動：表現為「顧眼前型的互動應變者」。一般情境下他能維持順暢的互動，但組織情境複雜、牽涉多方關聯時，他需要一點時間才能跟上局面、抓準該怎麼應對。這種場合他多半只顧著眼前的一對一互動，把注意力放在當下這條線上；另一邊受到的牽動他常沒算到，張力就這樣冒出來。旁邊出現反應時，他常是第一次意識到，剛才專心處理的那一頭，其實牽動了別處。管理上宜在多方關聯的複雜情境中，提前替他標出還有哪些關係人會被牽動，讓他在專注眼前互動之餘也能兼顧到其他角落。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3444, 'ANI_21', 'B (中)', 'ANI_19', 'A', '與 ANI_19 (協商談判) 高分聯動：表現為「策略清楚、上手需要暖身的協商者」。一般的互動場合他順暢自然；一旦談判牽涉複雜的權力位階或正面衝突，他需要一段時間才跟得上場面的變化，開場前段常顯得比較保守、還在摸清楚狀況。同時他對協商本身的方法很清楚——懂得平衡各方利益、朝雙贏方向找空間，就算場面轉向對立也不會立刻放棄合作路線，持續尋找能讓步與該堅持的分界。問題常出在策略的執行仰賴讀懂當下局勢——誰正在讓步、誰的立場正在鬆動、什麼時候該拋出替代方案——這些判斷正好落在他還沒跟上狀況的那段時間裡，容易慢半拍。等他讀懂整體局勢之後，原本清楚的協商方法才真正發揮出來，節奏也明顯加快。管理上複雜或高衝突的協商適合安排暖身時間，先讓他觀察一輪局勢，再進入正式的策略執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3445, 'ANI_21', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「木訥的天才」。邏輯推演無懈可擊（01A），但因讀不懂社交暗示（21C），常在不合時宜的場合說出「正確但傷人」的話。警示：容易與團隊產生隔閡，需專人負責其外部協作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3446, 'ANI_21', 'C (低)', 'ANI_04', 'A', '與 ANI_04 (適應敏捷) A 聯動：表現為「尷尬的變革者」。行為調整雖快（04A），但因缺乏社交敏感度（21C），其轉向往往顯得生硬且未考量他人的情感負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3447, 'ANI_21', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「低 EQ 的追求者」。為了追求卓越成果（08A）會無視團隊動態與關係成本（21C）。風險：高產出但會伴隨極高的人才流失風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3448, 'ANI_21', 'C (低)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「耿直的執行員」。言出必行且高度可靠（16A），但在處理複雜的人際請託或跨部門博弈時，顯得過於僵化、不懂變通（21C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3449, 'ANI_21', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「專注於細節的獨行者」。在專業數據上精確（17A），但完全無視社交情境的微小變化（21C），溝通方式通常較為單向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3450, 'ANI_21', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「僵化的合規者」。為了獲取認可而死守禮儀規範（23A），但因缺乏真實的社交直覺（21C），其互動顯得刻意且無法應對非正式場合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3451, 'ANI_22', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精確的戰略官」。決策不僅快，且具備深厚的邏輯支撐（01A）。預測：能在短時間內處理大量數據並產出高品質決策，是處理突發營運危機的核心人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3452, 'ANI_22', 'A (高)', 'ANI_03', 'A', '與 ANI_03 (認知彈性) A 聯動：表現為「敏捷的修正者」。決策果斷（22A），且當環境變動時能迅速切換思路（03A）做出動態調整。管理建議：適合作為高頻率迭代專案（如新產品測試）的決策主導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3453, 'ANI_22', 'A (高)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「獨立的指揮官」。不需要等待主管下令（05A），能在其職權範圍內迅速定案並推動執行（22A）。預測：極具所有權意識，是推動組織「扁平化、去中心化」管理的標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3454, 'ANI_22', 'A (高)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「清醒的承擔者」。清楚自己為何做此決策（09A），且對決策後的風險有心理準備。預測：不會因壓力而導致決策偏誤，能維持極高的決策穩定度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3455, 'ANI_22', 'A (高)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「數位增強決策者」。能快速利用 AI 分析產出作為判斷依據（10A），結合個人直覺做出高效率定案（22A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3456, 'ANI_22', 'A (高)', 'ANI_15', 'A', '與 ANI_15 (系統性思考) A 聯動：表現為「全局指揮官」。能看清系統連動（15A），在確保整體利益不損害的前提下，迅速對局部衝突做出裁決。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3457, 'ANI_22', 'A (高)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「可靠的終結者」。決定下得快（22A），且對決策後的承諾與執行維持高度一致性（16A），不輕易反覆。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3458, 'ANI_22', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「資料到位才敢拍板的審慎行動者」。他在面對需要決策的情境時，會先把問題拆解清楚、梳理關鍵資訊，待邏輯與結構都到位後才真正定案；這個流程在條件充分時運作得很順，但一旦資料殘缺或情境模糊，他就會感到難以收束，決策節奏明顯放慢。旁人若催促他在資訊不齊備時出結論，他往往內心抗拒，更傾向多問一輪、多確認一次。管理上宜在決策前提供清晰的資訊框架，並預留他收斂分析所需的緩衝時間，避免在資訊混亂時要求即時定案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3459, 'ANI_22', 'B (中)', 'ANI_03', 'C', '與 ANI_03 (認知彈性) 低分聯動：表現為「熟悉框架內謹慎定案的固守者」。他在既有流程清晰、選項範圍熟悉的狀況下能穩定做出決策；但當情境突然改變、需要切換評估角度或接受全新方法時，他會同時感受到判斷標準的動搖與行動的猶豫，難以快速在新框架內重新定錨。遇到環境轉換時，他容易反覆比較舊方案，延遲承諾新方向。管理上宜在變動初期給他足夠的說明與緩衝，讓他先消化新框架的邏輯，再要求他在新條件下拍板。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3460, 'ANI_22', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「自訂節點推進、拍板前仍等資訊到位的決策者」。他很少等別人交代下一步：接到任務後會自己把大方向拆成幾個檢核點，照自己訂的節奏往前推進，對最終要交出的成果也有明確自我要求。拍板前他看的是資訊夠不夠，不是進度排到哪——資訊不齊備時，他更難放行自己的決定，寧可在自訂的節點前多留一輪核對，不讓節奏表牽著他勉強拍板。資訊來源分散或不明時，他會主動追、主動問，把缺口一項項補齊，再回頭調整自己訂的節點；節點挪後了，但進度仍是他自己在掌握，不是被動被拖著走。管理上宜協助他把大目標切成具體的決策節點，並在節點之間保留他核對資訊缺口所需的時間，而非只緊盯進度表。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3461, 'ANI_22', 'B (中)', 'ANI_09', 'C', '與 ANI_09 (自我覺察) 低分聯動：表現為「資訊主導但自我盲點易被忽略的決策者」。他在決策時傾向聚焦外部資訊的完整性，較少停下來審視自己當下的情緒狀態或偏見是否正在影響判斷；當壓力升高或急於收尾時，這個盲點會變得更明顯，他可能在不自覺的情緒干擾下傾向某個選項，卻以為是純粹的理性評估。他人的直接回饋往往是他修正判斷的主要觸發點，否則他難以主動察覺偏移。管理上宜在關鍵決策前引入他人視角的確認機制，幫助他把習慣忽略的自身狀態納入判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3462, 'ANI_22', 'B (中)', 'ANI_10', 'A', '與 ANI_10 (AI科技素養) 高分聯動：表現為「知情待齊的謹慎決策者」。他能清楚理解 AI 工具的適用情境、能力邊界與潛在風險，不需要外部引導就能自行判斷某個工具是否可信賴、在哪個環節容易出錯。遇到需要借助工具產出來輔助判斷的場合，他會先盤點清楚有哪些限制還沒摸透，傾向等資訊更完整、評估更確定後才拍板，決策速度隨資訊到位程度上下起伏。管理上宜事先釐清他已掌握哪些風險面向，聚焦尚未釐清的缺口，有助於縮短他等待齊全的循環，讓決策在保有品質的前提下提早落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3463, 'ANI_22', 'B (中)', 'ANI_15', 'C', '與 ANI_15 (系統性思考) 低分聯動：表現為「局部資訊充足即定案的單點決策者」。他在蒐集到足夠的局部資訊後能夠做出穩定的決策，但較少主動思考決策的連動效果或對其他環節的外溢影響；他在單一事項上看起來審慎可靠，但在高度互依的複雜系統中，他的決策可能在局部合理卻在系統層產生預料外的衝突。他在事後才被告知連動影響時往往感到意外，而非事先納入考量。管理上宜在決策前提供系統連動的說明或視覺化，協助他把關鍵的外部影響列入評估，避免局部最優但整體欠佳的結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3464, 'ANI_22', 'B (中)', 'ANI_16', 'A', '與 ANI_16 (可靠性) 高分聯動：表現為「交付穩定、拍板速度隨資訊起伏的決策者」。他在任務上向來說到做到：答應的期限會準時交出結果，過程中的進度也一路可預期，旁人不太需要花心思盯他。真正耗時的是拍板前那一關——資訊蒐集齊全、評估到位之前，他不輕易鬆口定案；即使期限逼近，他也會提前告知旁人「還差哪一塊」，不讓進度懸而不明。資訊來源分散或邊界模糊時，這道確認關卡會拉得更長，最終定案的內容常常等到最後一刻才成形。管理上宜提早備妥決策所需的資訊來源，並在排定期限時預留他核對最後細節的餘裕，讓謹慎判斷不必靠壓縮交期才能完成。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3465, 'ANI_22', 'C (低)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「分析癱瘓的專家」。邏輯能力極強（01A），但因追求資訊完備而陷入無限分析（22C）。管理建議：需為其設定強制性的決策截止時間（Deadline）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3466, 'ANI_22', 'C (低)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「追求完美的猶豫者」。渴望達成卓越（08A），但因擔心決策不夠完美而遲遲不敢定案（22C）。警示：容易在重要機會點前因反覆斟酌而錯失良機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3608, 'SPA_06', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的應付者」。行為上雖然顯得匆忙且具競爭欲望（13A），但其實並未將心力真正奉獻在任務本質上（06C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3467, 'ANI_22', 'C (低)', 'ANI_17', 'A', '與 ANI_17 (準確嚴謹度) A 聯動：表現為「糾結細節的保守派」。過度專注於數據的精確性（17A），在不確定環境中顯得畏縮，難以在模糊資訊中做出決斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3468, 'ANI_22', 'C (低)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「優柔寡斷的談判手」。具備策略概念（19A），但在談判桌上最後一刻收網時，往往猶豫不決（22C），導致談判對手掌握節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3469, 'ANI_22', 'C (低)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「嚴謹但被動的審核者」。能看出各種方案的漏洞（20A），但因為缺乏決斷動能（22C），最終僅停留在「批評」而非「拍板」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3470, 'ANI_22', 'C (低)', 'ANI_23', 'A', '與 ANI_23 (社會期望反應) A 聯動：表現為「隨大流的合規者」。因害怕做出錯誤決策而影響他人認可（23A），傾向於等待群體共識或上級指示後才跟進（22C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3471, 'ANI_23', 'A (高)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) A 聯動：表現為「精明的社交棋手」。能運用邏輯（01A）判斷當前環境最被期望的行為，並精準呈現符合優秀標準的產出（23A）。預測：在組織政治中游刃有餘，其專業展現往往極具策略性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3472, 'ANI_23', 'A (高)', 'ANI_06', 'A', '與 ANI_06 (人際影響力) A 聯動：表現為「具魅力的合規領導」。擅長運用說服力（06A）來推動符合組織主流價值觀的計畫，並以此獲取廣泛的認可（23A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3473, 'ANI_23', 'A (高)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) A 聯動：表現為「模範生式的卓越者」。追求高標準（08A）的一部分動力來自於渴望被社會視為優秀精英（23A）。管理建議：其動能深受「榮譽感」與「外部肯定」影響。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3474, 'ANI_23', 'A (高)', 'ANI_11', 'A', '與 ANI_11 (同理心) A 聯動：表現為「極致的貼心者」。能理解他人感受（11A），且行為上高度符合社交禮儀與期望（23A）。警示：容易因過度在意他人評價而產生心理內耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3475, 'ANI_23', 'A (高)', 'ANI_16', 'A', '與 ANI_16 (可靠性) A 聯動：表現為「完美的秩序維護者」。因渴望符合期望（23A），會不遺餘力地履行每一項承諾（16A），是組織中最穩定的正面力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3476, 'ANI_23', 'A (高)', 'ANI_21', 'A', '與 ANI_21 (社交智商) A 聯動：表現為「得體的外交官」。具備極高的社交洞察力（21A），能精準捕捉社交規範並做出最得體的反應（23A），關係管理能力極強。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3477, 'ANI_23', 'B (中)', 'ANI_01', 'A', '與 ANI_01 (分析性思考) 高分聯動：表現為「敏感場合的選擇性過濾者」。他平時能穩定運用邏輯拆解問題，資料清楚、結構明確時也確實呈現出紮實的分析品質，推論步驟交代得完整。但一旦評估結果會讓人留下不好印象，他會先在心裡篩過一輪，把對自己不利的推論、還沒把握的假設先放到一邊，只挑站得住腳、聽起來穩妥的部分講出來。表達上會變得比平常更保守、用詞更謹慎，段落之間的跳躍也比實際思考歷程更順、更少破綻，讓外人看到的分析比他腦中真正跑過的路徑更整齊、更少猶豫。管理上宜設計心理安全的回饋環境，讓他知道呈現思考過程中的不確定性不會被扣分，才更能發揮真實的分析深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3478, 'ANI_23', 'B (中)', 'ANI_06', 'C', '與 ANI_06 (人際影響力) 低分聯動：表現為「自我包裝的低調輸出者」。他在多數情況下能如實呈現自己的想法，但一遇到覺得需要給人好印象的場合，就會開始修飾措辭、把自己說得比實際狀況更理想。在日常互動中，他對說服或帶動旁人並不積極，影響力主要靠工作產出本身說話，不靠主動推動旁人改變。所以在需要展示自己有多大影響力或溝通能力的場合，往往就是他最容易給出理想化回答的時候——他實際上鮮少主動帶動他人，但在需要表態這方面時，他會把自己描述得比平日更有說服力、更主動積極。管理上，若要評估他對周遭的實際影響力，宜以他的工作產出與具體情境記錄為依據，而非他自述的能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3479, 'ANI_23', 'B (中)', 'ANI_08', 'A', '與 ANI_08 (卓越追求動機) 高分聯動：表現為「高標準但選擇性透明的追求者」。他對成果品質有明確要求，日常工作中能穩定投入並自我加碼；然而在評估或需要公開說明自身表現的場合，他對失誤或不足的呈現會出現選擇性，傾向以接近期待的角度描述，讓外界對他的表現掌握出現落差。這種內外不一致在需要跨部門交接或接受正式評核時容易引發信任問題。管理上宜在日常進度中建立坦承的盤點習慣，讓他習慣把進展中的缺口視為正常，而非需要掩飾的弱點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3480, 'ANI_23', 'B (中)', 'ANI_11', 'C', '與 ANI_11 (同理心) 低分聯動：表現為「說的比做的更體貼的任務導向者」。平時多數問題他能坦率作答，但碰到和「關心他人、有沒有同理心」相關的題目，就容易浮出防衛——他感覺到這類題目會影響別人對他的觀感，因而傾向把回應寫得比實際行為更體貼、更有感受力。在真實的互動場合，他對他人情緒的回應並不多，互動的重心落在把事情做完，而非確認他人的感受是否被接住。這個落差在他的自述中往往被遮蓋，最後呈現出說的比做的更溫暖的樣子，但實際行為仍以任務完成為主軸。管理上，若要了解他在人際溫度上的真實狀態，比起看他在評估中如何描述自己，觀察他在具體事件裡如何回應他人困境更能反映真實情況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3481, 'ANI_23', 'B (中)', 'ANI_16', 'A', '與 ANI_16 (可靠性) 高分聯動：表現為「穩定交付中的選擇性揭露者」。在流程清楚或目標明確的情境，他能夠穩定兌現承諾，讓周遭人建立起對他的基本信任；但當碰到狀態波動或任務出現延誤跡象時，他傾向先把問題處理掉再揭露，或以較樂觀的說法回應進度詢問，避免留下不可靠的印象。這在短期內維持了形象，卻使合作方缺乏預警，遇到真正延誤才感到意外。建議建立定期進度說明機制，讓他在結構化的回報框架下習慣呈現真實進度，降低對被評價的焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3482, 'ANI_23', 'B (中)', 'ANI_21', 'C', '與 ANI_21 (社交智商) 低分聯動：表現為「互動策略固定的形象管理者」。他對社交線索的讀取較不敏感，面對複雜的人際情境時互動策略較為固定；加上在想留下好印象的場合容易偏向理想化表述，使他的應對常停留在一套統一模板，難以隨情境調整出適配的互動方式。周遭人在不同場合從他身上得到相似反應，久了容易覺得難以真正接近或了解他。管理上宜提供具體的情境回饋，指出他的回應與當下氛圍的落差，幫助他逐步校正讀取社交訊號的能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3554, 'SPA_04', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「可持續的高標工作者」。高度投入工作且不容易因疲勞或小挫折而退縮。預測：能維持長期的卓越表現，是部門中的穩定軍心柱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3555, 'SPA_04', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「從失敗中獲益的成長者」。能承受負面評價帶來的衝擊（04A），並積極尋求反饋以進行自我優化（08A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3483, 'ANI_23', 'B (中)', 'ANI_05', 'A', '與 ANI_05 (自主領導) 高分聯動：表現為「自律框架下的有限自我揭露者」。在目標與期待清楚時，他能自主設定節奏並穩定推進，展現出明確的自我管理能力；但在需要對外說明挫折、調整方向或坦承進度落後的場合，他習慣先把狀況整理到看起來可接受的樣子，再對外呈現，讓旁人難以及時掌握他真實的執行狀態。這種模式在他一個人推進時風險不大，但在協作任務中會讓他人的資源調配出現盲點。宜鼓勵他把中期盤點納入自主管理的一部分，讓如實回報成為自律習慣的延伸，而非待克服的形象問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3484, 'ANI_23', 'C (低)', 'ANI_05', 'A', '與 ANI_05 (自主領導) A 聯動：表現為「特立獨行的開拓者」。主動性極強（05A），但完全不在意他人眼光或傳統規範（23C）。預測：能推動顛覆性變革，但常因不屑偽裝而得罪組織內的保守勢力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3485, 'ANI_23', 'C (低)', 'ANI_07', 'A', '與 ANI_07 (創造性思考) A 聯動：表現為「反叛的創意天才」。創意不受社會期望約束（07A, 23C），其方案通常極具衝擊力，但也可能因過於前衛而難以被主流接受。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3486, 'ANI_23', 'C (低)', 'ANI_09', 'A', '與 ANI_09 (自我覺察) A 聯動：表現為「坦率的求真者」。能看清自己的優缺點（09A），且不屑為了迎合他人而掩飾或包裝真實的自我（23C）。管理建議：其反饋極具真實參考價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3487, 'ANI_23', 'C (低)', 'ANI_10', 'A', '與 ANI_10 (AI 科技素養) A 聯動：表現為「技術實務派」。對 AI 的應用僅看重實效（10A），不願為了符合數位轉型的「形象噱頭」而做表面功夫（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3488, 'ANI_23', 'C (低)', 'ANI_19', 'A', '與 ANI_19 (協商談判) A 聯動：表現為「硬派談判手」。在談判桌上堅持底線（19A），不會為了維持客氣或討好對方而輕易讓步（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3489, 'ANI_23', 'C (低)', 'ANI_20', 'A', '與 ANI_20 (批判性思考) A 聯動：表現為「批判性的獨覺者」。具備獨立判斷能力（20A），且敢於挑戰大眾共識，不擔心發表不合群但正確的言論（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3490, 'ANI_23', 'C (低)', 'ANI_22', 'A', '與 ANI_22 (高效決策) A 聯動：表現為「果敢但不討好的決策者」。決策迅速（22A），且願意做出「正確但不得人心」的艱難決定，不被社會壓力所左右（23C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3491, 'SPA_01', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「目標導向的戰士」。心理資本充足（01A）且目標路徑清晰（02A）。預測：在複雜任務中能自發找到多種解決路徑，不因暫時的挫折而放棄目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3492, 'SPA_01', 'A (高)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「無懈可擊的穩定源」。心理資源充沛且復原極快。管理建議：適合作為組織危機處理的先鋒，能長時間維持高強度輸出而不斷電。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3493, 'SPA_01', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「高效的永動機」。高度投入工作（06A）且有足夠的心理資本支撐（01A）。風險預防：這類人容易因自我加壓而忽略休息，雖資源充沛仍需留意長期燃盡風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3494, 'SPA_01', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自信的成長者」。因心理資本高（01A），能將負面回饋視為成長工具而非否定（08A）。預測：其能力提升速度極快，能主動優化自身行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3495, 'SPA_01', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「具基石的衝刺者」。強大的企圖心（15A）配合穩健的心理資本（01A）。管理建議：是組織中極佳的高潛力人才，敢於追求極致目標且具備承擔失敗的底氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3496, 'SPA_01', 'A (高)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「理性的守護者」。具備高心理韌性且情緒極度穩定。預測：在衝突場合中能展現出驚人的冷靜，是跨部門協調與高壓談判的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3497, 'SPA_01', 'B (中)', 'SPA_02', 'A', '與 SPA_02 (希望) 高分聯動：表現為「會累但認路的推進者」。目標清楚時他能把想做的事拆成具體路徑，也準備了備案，卡關時不會只停在原地嘆氣，而是會找別的走法。只是遇到連續挫折、目標變模糊或後援不足時，那股往前推的動能會先鬆下來，需要一段時間才回得來。回穩之後，原本找路的能力還在，他又會把備案拿出來重新試。管理上宜在他動能下滑的階段先幫忙把目標重新講清楚，讓找路的本事有機會接回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3498, 'SPA_01', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「撐得住一陣、撐不住太久的人」。平時他還能維持一定表現，遇到單一挫折也能撐過去，但如果高壓拉長、不確定感持續累積，疲乏與挫折感會冒出來，復原的速度明顯變慢，表現起伏也跟著變大。連續受挫的階段對他影響特別明顯，動能會往下掉，得等壓力源鬆開、有人幫忙釐清下一步，才慢慢回穩。管理上宜留意他連續處於高壓的時間長度，適時安排喘息與拆解任務，避免耗損疊到臨界點才處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3499, 'SPA_01', 'B (中)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) 高分聯動：表現為「把工作當自我價值來源、卻會有淡下來時刻的人」。他優先把時間心力放在職責與成果上，做得好不好對他來說接近自我重要感的一部分，平時投入程度很高。但目標模糊、支援不足或連續碰壁的時候，那股平常撐著的動能會先垮下來，原本主動加碼的行為會變少、變被動。等情境回穩，他又會把心力拉回工作上，重新投入。管理上宜在他動能下滑時給明確方向與具體支援，避免讓他因為看不到路而把高投入的習慣硬撐到耗竭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3500, 'SPA_01', 'B (中)', 'SPA_08', 'C', '與 SPA_08 (反饋尋求) 低分聯動：表現為「悶著撐、不太求救的人」。平時他能靠自己維持表現，不太主動找人確認做得好不好，可能覺得沒必要或擔心被否定。連續受挫或目標變模糊時，他還是習慣自己扛，很少開口求助，動能下滑的狀態沒有被說出來，也就沒有外部回饋介入，修正的窗口容易被錯過。等到壓力鬆開、有人主動關心進度，他才比較願意把卡住的地方講出來，狀態才慢慢回升。管理上宜主動定期確認他的進度與心情，不要等他開口才介入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3501, 'SPA_01', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「想衝但會被現實磨掉勁的人」。他對成果有明確企圖心，想把事情做到最好、遇到目標會主動往上拉，平時這股勁頭很明顯。可是連續挫折、目標模糊或缺乏支援的時候，原本想往上衝的力道會先被消磨，行動會慢下來、標準也可能暫時降低，直到情境回穩才重新把企圖心找回來、再度加碼。這種起伏在他身上特別容易出現在長期沒有進展回饋的專案。管理上宜適時給予具體進度回饋與階段性目標，讓他的企圖心有依附的對象，不至於在空轉中消退。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3556, 'SPA_04', 'A (高)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「強悍的競爭對手」。強大的求勝欲（14A）結合高度的挫折容忍力（04A）。管理建議：在激烈的業績競賽中表現極佳，能在落後時展現驚人的追分能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3502, 'SPA_01', 'B (中)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) 低分聯動：表現為「情緒穩、但動能會悄悄退場的人」。遇到煩惱或衝突時他大致能保持冷靜，不太會因為一時情緒就衝動反應或做出高代價的決定，表面上看起來狀態平穩。但連續挫折、目標模糊或支援不足時，問題不會用情緒爆發的方式表現出來，而是動能悄悄往下掉——他可能還是一樣冷靜，行動力卻已經在退場，不容易從情緒訊號察覺。等壓力緩解、方向重新釐清，他才會慢慢把動能找回來。管理上不能只看他情緒平不平穩來判斷狀態，還要主動確認實際產出與進度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3503, 'SPA_01', 'B (中)', 'SPA_03', 'A', '與 SPA_03 (效能感) 高分聯動：表現為「信心底子在、動能會隨情境浮動的人」。他對自己能靠努力達成目標有明確信心，敢承擔結果，遇到困難也不容易退縮，這份底子平時撐得住表現。不過連續受挫、目標模糊或後援不足時，即使信心本身沒有崩掉，實際投入的動能還是會先鬆下來、行動變得比較保守，需要一段時間回穩才能重新把力氣使出來。這種浮動比較容易出現在長期缺乏正向回饋的階段。管理上宜留意他動能下滑時仍保有的底子，適時提供資源與明確下一步，讓信心能盡快轉回實際推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3504, 'SPA_01', 'C (低)', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「深度自我懷疑者」。心理資源偏緊（01C）且缺乏信心（03C）。管理建議：需主管透過「拆解小目標」來建立成功經驗，否則易陷入習得性無助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3505, 'SPA_01', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「悲觀的預測者」。傾向將失利視為永久且無法改變。風險：在面對變革或不確定性時會率先退縮，對團隊士氣可能產生負面連鎖反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3506, 'SPA_01', 'C (低)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「焦慮的防禦者」。因自身心理資源不足（01C），對外部回報與公平性極度敏感（09C）。警示：容易因微小的資源分配不均而產生強烈不滿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3507, 'SPA_01', 'C (低)', 'SPA_11', 'C', '與 SPA_11 (可塑性) C 聯動：表現為「僵化的守舊派」。不相信自己能改變（11C）且缺乏重新啟動的心理動能（01C）。管理建議：應給予極其明確的指令與外部推力，減少其面對改變的心理負荷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3508, 'SPA_01', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「高壓的自燃者」。具備強烈的競爭欲與時間緊迫感（13A），但內在心理資源卻支撐不足（01C）。風險：極度容易發生身心崩潰或職業倦怠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3509, 'SPA_01', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「情緒的易燃者」。面對挫折時心理緩衝力弱（01C）且情緒升溫極快（18A）。管理建議：絕對不宜放在需要高度人際協作或面對客戶投訴的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3510, 'SPA_01', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「表面的堅強者」。雖然心理資源匱乏（01C），但在作答或互動中會努力維持正面形象（12A, 23A）。隱憂：可能隱藏真實的求救信號，主管需透過非正式對話觀察其真實能量狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3511, 'SPA_02', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全能型推進者」。希望感提供的路徑規劃（02A）與強大的心理底蘊（01A）結合。預測：在資源匱乏的環境中，能主動創造條件達成目標，是開拓陌生市場的關鍵人才。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3512, 'SPA_02', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「深具信念的執行者」。既相信自己能做到（03A），又能找到做到的方法（02A）。管理建議：其主動性極高，適合承擔高度模糊、需要自創戰術的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3513, 'SPA_02', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「策略型職人」。在遵循職業規範（07A）的同時，能靈活調整方法（02A）來解決客戶難題，而非死守教條。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3514, 'SPA_02', 'A (高)', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「自我進化的領航員」。因看見未來目標的路徑（02A），故極度願意學習新技能（11A）以填補路徑上的缺口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3515, 'SPA_02', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「清醒的野心家」。強大的成功欲望（15A）配合具體可行的達成路徑（02A）。預測：其成就導向極強，且不會盲目衝刺，能精準將動能轉化為結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3516, 'SPA_02', 'A (高)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「多線程的策略大師」。能同時規劃多條路徑達成多項任務（16A, 02A）。警示：雖路徑規劃力強，但需留意資源分散導致每一條路徑都「淺嚐輒止」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3517, 'SPA_02', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「資源到位就衝的築路者」。他有明確的目標感，也想得出下一步該往哪走，但真正把路徑鋪穩往往要等外部資訊或前例對齊之後；同時他手上一直握著一份底氣——遇到卡關時不至於慌了手腳，還能把壓力拆成能處理的小任務去消化。框架一旦清楚，他能一邊穩住情緒一邊把步驟具體化，執行得又快又不亂；但若外部資訊遲遲不到位，他會先靠著那份底氣撐住場面、繼續嘗試找路，而不是原地卡死。管理上把方向與參考案例儘早給他，能讓他的目標動機直接轉成穩定產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3518, 'SPA_02', 'B (中)', 'SPA_03', 'C', '與 SPA_03 (效能感) 低分聯動：表現為「有方向卻不敢邁步的規劃者」。他對目標本身有想法,也願意花心思把步驟想清楚,尤其是在有外部資訊或前例可以參考的時候,規劃會做得相對細;但一旦要真正動手執行,他常常對自己能不能做到沒把握,容易在踏出第一步前反覆猶豫。碰到挫折時,原本已經想好的路徑計畫可能就這樣被擱著,他傾向先收手觀望而不是繼續往下推進。框架與參考案例清楚時,他的目標感還能撐住整個規劃過程,但缺了他人肯定或明確的成功先例,啟動門檻會拉得更高。管理上除了給方向,更需要提供小步驟的成功經驗或陪跑,幫他把「想到」推成「做到」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3519, 'SPA_02', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「框架內的穩健執行者」。他接到任務時，會先確認目標範圍與交付標準是否已經講清楚，框架明確時才動手排出執行的先後順序。路徑確定後，他會照著既定流程逐步推進，過程中留意每個環節是否符合該有的規範，不只求做完，還會回頭檢查細節與呈現方式。遇到框架模糊、規則沒講清楚的情況，他容易卡在「該怎麼走」上，這時即使他對品質的要求還在，執行的穩定度也會跟著下降。對外代表出面的場合，他格外在意一致性，會在動作前多看一次是否符合該有的形象再送出。管理上，把目標與路徑先講清楚，能讓他兼顧穩定執行與專業品質；框架一旦鬆散，宜補上更明確的檢核點或範例，幫他把「該怎麼做」的部分接上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3557, 'SPA_04', 'A (高)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「沉穩的防禦盾牌」。抗壓性強且情緒反應低。預測：面對客戶的無理取鬧或突發危機，能表現出極致的冷靜與專業處理能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3520, 'SPA_02', 'B (中)', 'SPA_11', 'C', '與 SPA_11 (可塑性) 低分聯動：表現為「等模板卻懷疑學了也沒用的行動者」。他對目標有明確的期待,也知道自己想往哪裡走,但規劃路徑時偏好依循別人走過的方法或既有經驗,較少自己去試探新做法;同時他心底對「自己是不是能透過學習變得更好」抱持保留態度,面對需要改變做法的情境容易先觀望,覺得再怎麼調整結果可能也差不多。有明確框架與前例可循時他能穩定執行,但一旦環境要求他學新方法、換新角度去規劃路徑,他容易停在原地,既不確定路怎麼走、也懷疑學了有沒有用。遇到挫折時,這份懷疑會進一步壓低他嘗試新路徑的意願。管理上除了提供清楚範例,更要讓他看見「調整方法確實帶來不同結果」的具體證據,才能撬動他重新規劃的動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3521, 'SPA_02', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「野心撐著找路的推進者」。他規劃路徑時仍習慣參考外部資訊或既有經驗,不是那種天馬行空自創打法的人;但他對「把成果做到最好」這件事有強烈的驅動,只要看見目標,就會想辦法把它往上拉、自我加碼,不甘於只是達標。框架清楚、路徑有依據時,他常衝出超出預期的成果,把借來的路徑走出自己的力道;可是一旦外部資訊或前例不足,他那股想衝更高的企圖心容易找不到施力點,反而顯得急躁或原地打轉。看到具體回饋與成效時,他會立刻把力氣灌注下去、加速往前推。管理上給他清楚的參照點與可衡量的進度指標,能讓他的企圖心穩穩轉成看得見的產出提升。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3522, 'SPA_02', 'B (中)', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) 低分聯動：表現為「一條路走到底的穩步規劃者」。他規劃目標路徑時偏向依賴外部資訊或前例把步驟想清楚,不急著自己摸索;同時他做事習慣專注完成一件事再切換到下一件,不喜歡同時攤開太多任務。框架清楚的情境裡他特別穩——先把路徑確認好,再一步步扎實地走完,不容易因為手上事情太多而分心亂了節奏。但如果外部資訊沒到位、又被迫同時處理多條任務線,他會感到明顯的壓力,規劃品質與效率都可能下降,既缺路徑依據、又不擅長多線並行。管理上減少同時交辦的任務數量、把資訊與方向先梳理清楚,能讓他把目標動機穩穩轉成一步到位的成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3523, 'SPA_02', 'B (中)', 'SPA_04', 'A', '與 SPA_04 (韌性) 高分聯動：表現為「跌了會馬上找新路的規劃者」。他規劃路徑時仍需要一些外部資訊或經驗當依據才走得穩,不是憑空就能生出新方法的人;但一旦計畫落空或遭遇拒絕,他能很快回穩,不會被一次挫折困住太久,而是重新盤點手上的資訊、調整策略再出發。框架清楚時他執行得穩,遇到路徑被打亂時,他也不至於陷在挫折裡出不來,反而會把心力放回「還能怎麼走」上面,持續嘗試修正方向。多變或反覆碰壁的情境裡,比起停滯不前,他更常見的是一次次微調重來。管理上在他受挫後及時補上新的資訊或參考案例,能讓他的回穩力直接轉成下一輪更準的路徑規劃。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3524, 'SPA_02', 'C (低)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「被動的防禦者」。能扛住壓力（04A），但不知道下一步該往哪走（02C）。管理建議：這類人具備續航力，但主管需扮演「導航儀」，為其指派明確路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3525, 'SPA_02', 'C (低)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「盲目的勤奮者」。極度努力工作（06A），但缺乏達成目標的有效策略或替代方案（02C）。風險：一旦現有方法失效，會因找不到出口而陷入嚴重的職業燃盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3526, 'SPA_02', 'C (低)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「依賴回饋的學徒」。主動尋求建議（08A），主因是缺乏自覺的路徑規劃能力（02C）。管理建議：應給予具體的指令引導（Coach），而非僅僅給予抽象建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3527, 'SPA_02', 'C (低)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高耗能的徘徊者」。體力與能量充足（10A），但行動缺乏清晰目標與導向（02C）。預測：在重複性、體力消耗型任務中表現佳，但在策略研討中參與感弱。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3528, 'SPA_02', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「受挫的競爭者」。渴望贏過他人（14A），但在競爭陷入僵局時，缺乏變通路徑以取得優勢的能力（02C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3529, 'SPA_02', 'C (低)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「緊迫的焦慮者」。感覺時間不夠（17A），又因找不到達成任務的路徑（02C）而加劇焦慮。管理建議：主管需介入協助排定優先順序，化解其心理僵局。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3530, 'SPA_02', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「絕望的爆發者」。面對阻礙時因找不到替代方法（02C），極易引發強烈的挫折感與情緒衝動（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3531, 'SPA_03', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全能的推進者」。具備足夠的心理底蘊且對成功有明確信心。預測：在面對未知或高難度挑戰時，能將壓力完全轉化為可執行的步驟，是組織開拓新業務的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3532, 'SPA_03', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「具備導航力的戰士」。既有達成的信念（03A），又能主動規劃多種路徑（02A）。管理建議：其主動性極強，適合承擔高度模糊、需要自創戰術的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3533, 'SPA_03', 'A (高)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不屈的執行大師」。即便遭遇失敗，不僅能快速復原（04A），且仍維持對成功的信心而不退縮（03A）。行為預測：是團隊中極其穩定的輸出源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3534, 'SPA_03', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「自信的勞模」。高度投入工作且深信努力會有成果。風險：可能因過度自信而承接超出負荷的任務，需主管協助控管任務邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3535, 'SPA_03', 'A (高)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的進攻者」。充滿活力且行事果斷。管理建議：適合節奏極快、需要第一時間反應的職務（如第一線業務或公關）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3536, 'SPA_03', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「目標導向的精英」。強大的慾望配合對能力的自信，使其產出具備極強的穿透力，能持續挑戰業績天花板。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3537, 'SPA_03', 'A (高)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「強勢的火藥桶」。對成功有執著，但若目標受阻，其自信會轉化為強烈的衝動或對抗情緒。警示：需建立情緒降溫機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3573, 'SPA_05', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「自信的進攻者」。預期結果是積極的（05A）且相信自己有能力達成（03A）。行為預測：行動啟動門檻極低，能主動捕捉每一個潛在機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3574, 'SPA_05', 'A (高)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不屈的彈性核心」。遭遇失敗時視其為暫時（05A），並能快速從衝擊中回穩（04A）。預測：在高度不確定的環境中，能表現出極致的心理穩定度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3538, 'SPA_03', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「先求穩、後推進的信心型行動者」。他多數時候相信自己能靠努力把事情做成，遇到挑戰仍保有信心與行動力，能把壓力拆解成一步步可處理的任務。碰到新產品、新市場或風險偏高的專案，他會想先把做法確認清楚，一旦掌握脈絡就能穩定輸出，不容易被壓力打垮。他在希望感、韌性與樂觀上都有底子，就算前期多花時間確認，也不至於陷入焦慮或停擺。管理上宜在啟動階段給他明確資訊與討論空間，讓他把不確定感降到可接受範圍，之後就能放手讓他穩定往前推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3539, 'SPA_03', 'B (中)', 'SPA_02', 'C', '與 SPA_02 (希望) 低分聯動：表現為「敢做但缺路徑感的執行者」。他多數情境下相信自己能靠努力達成目標，願意投入去做；面對新產品、新市場或高風險任務，他會想先確認做法，理解後才敢加速推進。他較難把目標拆成具體策略與步驟，一旦卡關容易停在原地打轉，或臨時改走比較短線、見效快的選擇，而不是重新規劃路徑。在需要長線布局的任務上，他常常動力足夠卻方向感不足，容易做了很多卻繞不出困局。管理上宜在他確認做法的階段就一起把路徑拆解清楚，避免卡關時他只能憑感覺硬撐或轉去做容易的事。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3540, 'SPA_03', 'B (中)', 'SPA_04', 'A', '與 SPA_04 (韌性) 高分聯動：表現為「先求穩、跌了也快速起身的推進者」。他在多數情境下相信自己能靠努力達成目標，但碰上新產品、新市場或高風險任務時，會想先把做法確認清楚，理解後才願意全力投入。一旦遭遇拒絕、衝突或目標落空，他能快速回穩，重新調整策略並繼續輸出，不太會被一次挫折打亂整體節奏。確認過做法之後他敢放手一搏，就算中途踢到鐵板，也能很快重新出發、不被卡住太久。管理上可以放心讓他承接需要前期確認、後期又可能碰壁的任務，只要一開始給他足夠資訊，後續的挫折他多半能自行消化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3541, 'SPA_03', 'B (中)', 'SPA_06', 'C', '與 SPA_06 (工作投入性) 低分聯動：表現為「先求穩、不隨意加碼的執行者」。他多數時候相信自己能靠努力把事情做好，但面對新產品、新市場或風險偏高的任務，會想先確認做法，理解後才穩定輸出。他把工作視為責任的一部分，投入程度容易隨外部要求變動，較少主動加碼或做長線的耕耘與投入。確認完做法之後，他傾向把該做的部分做到位就好，不會額外把時間拉長去追求更多；一旦沒有明確要求，投入強度也會跟著收斂。管理上若希望他在高風險任務上發揮更多，除了先把做法講清楚，還需要額外給出明確的期待與要求，否則他容易止於完成基本份內。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3542, 'SPA_03', 'B (中)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) 高分聯動：表現為「先確認、後全速衝刺的快節奏行動者」。他多數情境下相信自己能靠努力達成目標，行動與生活步調都偏快，做事積極、反應迅速，喜歡把事情往前推。碰到新產品、新市場或高風險任務，他會先停下來把做法確認清楚；一旦理解到位，馬上切回快節奏，用高能量把進度往前拉，也容易帶動身邊的速度感。前期的確認通常不會拖太久，他本來就傾向盡快把事情處理掉，一確認完就想立刻動起來。管理上可以善用他確認後的爆發力，在風險較高的階段把資訊與決策給快一點，他就能很快切進高效推進模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3543, 'SPA_03', 'B (中)', 'SPA_15', 'C', '與 SPA_15 (企圖心) 低分聯動：表現為「確認後求穩、不強求突破的行動者」。他多數時候相信自己能靠努力把事情做成，面對新產品、新市場或風險偏高的任務時，會想先確認做法，理解清楚後就能穩定輸出。他不太把「往上衝」放在第一順位，比較在意把手上的事情做好，不一定要追求極致突破，也重視生活與工作之間的平衡。確認完做法之後，他傾向把任務做到穩、做到位，較少主動加碼去挑戰更高目標或搶進度。管理上若期待他有更大突破，除了先把做法講清楚，還需要額外設定具體的挑戰目標，否則他很容易停在「做好就好」的狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3544, 'SPA_03', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「確認後推進、卡關時情緒容易升溫的行動者」。他多數時候相信自己能靠努力達成目標，碰到新產品、新市場或風險偏高的任務，會先想把做法確認清楚，理解後才敢加速推進。面對煩惱或挫折時他反應快、情緒升溫也快，可能出現急躁、語氣變硬，甚至當場對抗或做出代價較高的回應。當確認階段被拖延、或推進中屢屢卡關，他容易先冒出煩躁感，場面還沒釐清問題就先變得緊繃。管理上宜盡量縮短他確認做法的等待時間，並在他情緒升溫的當下先給緩衝，等他冷靜後再一起處理卡關的部分。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3545, 'SPA_03', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「含蓄的潛力股」。雖有心理資源，但缺乏自我肯定的「板機」。管理建議：需主管透過具體的成功經驗（Mastery Experiences）來啟動其能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3546, 'SPA_03', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「習得性無助者」。不相信自己能行，且預期結果會持續惡化。風險：極易在挫折中徹底癱瘓，需密集的正面引導與外部結構支撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3547, 'SPA_03', 'C (低)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「尋求安心的依賴者」。主動要回饋的主因是內在信心不足，需要他人肯定才能繼續。面談重點：應多給予「過程肯定」而非僅看結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3548, 'SPA_03', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「焦慮的競速者」。行為上急迫且想掌控，但內心極度擔心失敗（03C）。警示：其高壓行為多源於不安，容易產生極大的人際張力與身心負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3549, 'SPA_03', 'C (低)', 'SPA_11', 'C', '與 SPA_11 (可塑性) C 聯動：表現為「僵化的自保者」。不相信能力可變，且對當前任務沒信心，會表現出極強的抗拒改變與學習意願低下。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3550, 'SPA_03', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「脆弱的火藥桶」。因沒把握而焦慮，一旦受挫會迅速情緒爆發以掩飾內心的自我懷疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3551, 'SPA_04', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強大的復原基石」。心理資源完整且抗壓性極強。預測：在組織經歷大規模轉型或市場寒冬時，能維持極高的心理穩定度並帶動團隊動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3552, 'SPA_04', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「不屈的導航者」。遭遇失敗時能快速復原（04A），且因具備希望感，能立即規劃出第二條路徑達成目標（02A）。管理建議：適合作為高難度商務開發（BD）人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3553, 'SPA_04', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「無懈可擊的推進者」。不僅對自我能力有信心（03A），且具備強大的壓力吸收能力（04A）。行為預測：這類人幾乎不被外界負面評價影響，執行力極其穩定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3558, 'SPA_04', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「有底氣出發、跌倒後仍要回血的人」。他在還沒真正碰壁之前，通常帶著把握出發：面對新挑戰時相信自己有辦法，也習慣把壓力拆成一件件可以處理的任務，整體態度偏積極。但當挫敗真的發生——提案被否決、合作生變、責任忽然加重——他還是會先愣一下、情緒被拉住，不是那種完全不受影響的人。只要能拿到明確的下一步、或身邊有人幫他把局面說清楚，他通常在不久後就能把腳步找回來，重新用原本的信心往前走。需要留意的是這段回穩期容易被誤讀成「沒事」，其實是暫時卡住，給他一點時間跟清楚的方向，比催他立刻恢復更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3559, 'SPA_04', 'B (中)', 'SPA_02', 'C', '與 SPA_02 (希望) 低分聯動：表現為「情緒會回穩、方向卻補不上的人」。遇到挫折時他一樣會受到影響，情緒往下掉、動力一時停擺。只要給他一點時間緩衝，情緒通常能慢慢平復，不會卡在挫敗感裡太久。真正卡住的是下一步：他不太擅長自己把「接下來要怎麼走」具體拆解成路徑或步驟，情緒過去之後常常還是停在原地，或是先挑一個比較省事的方向做著再說。這種狀況下，光讓情緒緩過來不夠，還需要有人幫他把下一步講清楚、列出具體動作，行動才接得上情緒的回穩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3560, 'SPA_04', 'B (中)', 'SPA_03', 'A', '與 SPA_03 (效能感) 高分聯動：表現為「留在場上硬撐、但仍需要喘息的人」。面對困難任務時他通常不會打退堂鼓，心裡對「自己努力就能做到」有明確把握，也願意扛下結果繼續投入。但真的踩到挫折——被打回票、進度卡死、臨時被交付超出原本負荷的工作——他還是會有一段當下被影響的時間，不是表面看起來那樣毫無感覺。他不會真的離開崗位或放棄任務，只是節奏會慢下來，需要一點空間把狀況想清楚、確認下一步該怎麼做。只要給他明確的下一步或適時的支持，他很快就能把原本的投入拉回來；若被要求立刻恢復全速，反而容易讓外顯的堅持跟內在的疲乏拉開差距。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3561, 'SPA_04', 'B (中)', 'SPA_06', 'C', '與 SPA_06 (工作投入性) 低分聯動：表現為「受挫會停一下、不會自己硬撐拉回來的人」。遇到挫折或責任忽然加重時，他一樣會有明顯的當下反應，情緒或動力會先掉一截，不會裝作沒事。他平常就不是把工作當成生活全部的人，任務多半被他視為份內責任之一，投入程度容易隨外部要求增減，不太會自己主動加碼或長期經營。挫折發生時他不會整個人陷進工作情緒裡出不來，波動範圍相對有限；不過他也不太會靠自己的意志力把狀態硬拉回來，動力回升往往要等外部要求或期限重新出現才會啟動。管理上若想讓他儘快恢復節奏，與其等他自行調適，不如直接給明確任務或時限，用清楚的外在框架幫他把下一步定出來，回穩速度會比放任他自行恢復快。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3562, 'SPA_04', 'B (中)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) 高分聯動：表現為「受挫後會主動出去找答案的人」。挫折發生的當下他一樣會受到衝擊，情緒或步調會先亂一下，不是那種完全不受干擾的類型。但他很快就會動起來去核對狀況：主動問主管、同儕或客戶自己哪裡出了問題、接下來該往哪個方向調整，把回饋當成弄清楚現況的工具。一旦拿到具體意見，他調整的速度相當快，通常沒多久就能把節奏找回來、重新投入。對他來說最怕的是回饋管道被堵住——沒人給明確意見時，他容易卡在「知道自己受影響、卻不知道下一步」的狀態，回穩的時間會被拉長。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3563, 'SPA_04', 'B (中)', 'SPA_14', 'C', '與 SPA_14 (競爭欲望) 低分聯動：表現為「不為輸贏所動、卻仍會被狀況打亂的人」。他對輸贏本身沒有太強的執念，比賽或排名式的競爭不太能刺激到他，真正在意的是表現穩不穩、跟人之間的關係好不好。單純被人超前或排名往後掉，這類狀況對他來說殺傷力有限，通常不會激起太大情緒。但一旦遇到關係緊張、合作出狀況，或原本穩定的表現被打亂，他還是會明顯受到影響，需要時間才能把心情跟步調拉回來。要幫他回穩，關鍵做法是先協助修復關係、把混亂的狀況理出頭緒，讓他確認接下來怎麼走，他通常就能重新穩定下來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3564, 'SPA_04', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「當下容易上火、事後仍要慢慢收尾的人」。遇到讓人惱火或受挫的狀況，他的第一反應通常來得又快又直接：語氣可能瞬間變硬，忍不住想當場頂回去，甚至當場說了重話、做了後來要花力氣收拾的回應。那股火氣退下去之後，他並不會立刻回到平常的狀態，需要一段時間才能把情緒跟步調重新收回來。在這段收尾期，如果有人願意陪他把事情理清楚、告訴他接下來可以怎麼處理，他通常能比較快找回平常心；若只留他自己消化，他停留在低落或防衛狀態的時間會拖得比較長。管理上與其在他情緒剛上來時跟他硬碰硬，不如先讓衝突降溫，等最初的反應過了，再協助他釐清下一步，回穩的效果會好很多。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3565, 'SPA_04', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「脆弱的悲觀主義者」。一旦受挫復原極慢（04C），且傾向將失敗視為長期不可逆的結果（05C）。風險：容易在壓力下產生習得性無助，進而導致職務流失或長期低迷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3566, 'SPA_04', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「易碎的競速者」。行為急迫、追求效率（13A），但一旦事情不順或被延誤，心理復原力跟不上，會產生巨大的心理挫折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3567, 'SPA_04', 'C (低)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「高度焦慮的攀登者」。雖然目標遠大（15A），但因缺乏韌性（04C），每一次的小挫敗對他而言都是重大打擊。管理建議：需主管頻繁給予心理緩衝與支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3568, 'SPA_04', 'C (低)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「時間壓力下的崩潰者」。因時間緊迫感強（17A）加上抗壓韌性不足（04C），在期限將至時容易出現失誤或逃避行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3569, 'SPA_04', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「高壓下的易爆物」。受挫時心理防禦迅速潰散（04C），隨即引發強烈的情緒衝動或對抗行為（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3570, 'SPA_04', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「壓抑的受挫者」。心理復原緩慢（04C），但為了符合社會期望與認可（12A），會表現出「沒關係」的假象，容易累積成內在的心理疾病。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3571, 'SPA_05', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強大的心理能量源」。樂觀的歸因（05A）能有效保護並補充心理資本（01A）。預測：在長期高難度專案中，能持續維持高士氣，並將外部壓力轉化為正向的推進力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3572, 'SPA_05', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「充滿希望的開路者」。相信事情會變好（05A）且能找出變好的多種路徑（02A）。管理建議：適合作為新市場或前瞻計畫的領導者，其信心具備極強的團隊渲染力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3575, 'SPA_05', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「開放的自我優化者」。相信改進能帶來更好的結果（05A），故會積極尋求反饋（08A）。管理建議：其成長潛力巨大，能將負面回饋轉化為具體的進步動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3576, 'SPA_05', 'A (高)', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「深信成長的學習者」。對未來的正向預期（05A）強化了對「能力可變」的信念（11A），展現出極高的學習投入度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3577, 'SPA_05', 'A (高)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「理性的樂觀實踐者」。態度積極（05A）但情緒表達冷靜且受控（18C），不會因為過度樂觀而顯得浮誇，決策更具專業深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3578, 'SPA_05', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「低潮期短的正向行動者」。多數時候他能保持正向、相信情況會轉好，但連續受挫或壓力升高時也會有一段短暫消沉。不過他手上的心理資源相對充足，遇到挑戰時信心與行動力都還在，容易把眼前的困局拆成可以動手處理的小任務。消沉往往維持不久，看到一點進展或拿到支持後就能重新把節奏拉回來，不會被單一挫折卡住太久。管理上可在他情緒剛開始下滑時給一個明確可執行的小任務，讓他的行動力有出口，能加速他自己把狀態穩回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3579, 'SPA_05', 'B (中)', 'SPA_02', 'C', '與 SPA_02 (希望) 低分聯動：表現為「有心情沒路徑的樂觀者」。他平時願意相信事情會有轉機，連續碰壁或壓力大時情緒會跟著往下掉一段時間。問題是他對「怎麼把目標拆成具體步驟」本來就比較弱，消沉當下更容易停在原地、講不出下一步該怎麼走，甚至隨手抓一個短線做法先應付過去。情緒回穩之後，若沒有人幫他把方向具體化，正向感受也很難真的轉成往前的動作。管理上宜在他情緒開始鬆動時，直接遞出一條清楚的路徑或幾個可選步驟，讓他的期待感有地方落地，而不是任由他自己摸索。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3580, 'SPA_05', 'B (中)', 'SPA_03', 'A', '與 SPA_03 (效能感) 高分聯動：表現為「情緒低落但信心不垮的人」。他多半保持正向看法，遇到連續挫折或高壓時情緒會短暫往下沉、對整體局勢的期待感變薄。但他對自己能靠努力做出成果這件事仍有明確信心，敢承擔結果、不太容易因為心情低落就整個人退縮下來。等看到一點進展或資源到位，正向感受和行動力會一起回升，不需要花太多時間重新說服自己。管理上可以在他消沉時強調他過去靠自己努力達成的具體成果，讓他從「我做得到」出發，帶動情緒比較快回穩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3581, 'SPA_05', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「消沉拖得比較長的人」。平常他能維持正向、相信不順只是暫時的，但一旦碰上連續高壓或長期不確定，情緒下滑的那段時間會被拉得更久。他在承受壓力或衝擊後恢復本來就比較慢，容易累積疲乏與挫折感，這段期間表現的起伏也會比較明顯，可能忽高忽低。要等狀況緩下來、看到具體進展，正向的一面才慢慢回來，過程中他不太能靠自己快速拉回節奏。管理上宜提早留意他連續受挫的訊號，主動給支持與喘息空間，讓他有機會在壓力持續期間喘一口氣、縮短恢復所需的時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3582, 'SPA_05', 'B (中)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) 高分聯動：表現為「消沉時主動找出口的人」。他多數時候相信情況會好轉，但連續受挫或壓力大時也會有一段短暫的情緒低落。這段低潮裡他不會只是悶著等，而是會主動去問主管、同儕或客戶自己現在做得如何、哪裡還能改進，把回饋當成幫自己重新確認方向的工具。拿到具體意見後，他調整動作的速度也快，正向感受跟著回來得比較快。管理上可以在他狀態偏低時主動釋出回饋管道，讓他一問就有得問，能明顯縮短他自己走出消沉的時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3583, 'SPA_05', 'B (中)', 'SPA_11', 'C', '與 SPA_11 (可塑性) 低分聯動：表現為「低潮時容易認命的人」。他平常保有正向期待，連續挫折或高壓來的時候情緒會跟著往下掉一段時間。這時候他比較傾向認為自己的能力與狀況大致固定，容易把當下的低潮解讀成「這方面大概就是這樣了」，面對需要改變的地方會先觀望，覺得再努力也未必有用。要等他親眼看到具體的進展或成效證據，正向感受才會慢慢回來，光靠口頭鼓勵效果有限。管理上宜在他消沉時提供看得見的小成果或具體案例，讓他有實際證據支撐，避免他停留在觀望與徒勞感裡太久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3584, 'SPA_05', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「消沉時容易帶情緒衝動的人」。他多半能維持正向，連續受挫或壓力升高時會出現一段短暫低落。這段時間他面對煩惱或挫折的反應門檻也比較低，情緒容易升溫得快，可能話講得比較衝、語氣變硬，甚至當場做出比較高代價的反應，不只是單純心情變差。看到進展或拿到支持後，情緒和正向感受會一起緩下來，衝動的部分也跟著收斂。管理上宜在他狀態明顯下滑的當下先給緩衝、避免立刻正面交鋒，等他情緒降溫後再處理問題，能減少當場衝突的機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3585, 'SPA_05', 'C (低)', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「心理脆弱的悲觀者」。傾向於災難化思考（05C），這導致其心理資源迅速枯竭（01C）。風險：在壓力環境下極易崩潰，需高度關注其心理健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3586, 'SPA_05', 'C (低)', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「習得性無助者」。不相信未來會好轉（05C），也不相信自己有能力改變（03C）。管理建議：這類員工常處於「防禦模式」，需透過大量的外部鼓勵與成功示範來引導。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3587, 'SPA_05', 'C (低)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「防禦性的公平追求者」。因對未來預期消極（05C），會更計較當下的付出與回報是否對等（09C），以求自保。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3588, 'SPA_05', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「焦慮的競爭者」。想贏（14A），但內心總預見會失敗（05C）。警示：其競爭行為可能帶有強烈的攻擊性或不安全感，容易造成人際張力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3589, 'SPA_05', 'C (低)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「受困的野心家」。想往上衝（15A），但容易被潛在的困難嚇阻（05C）。管理建議：應協助其將長遠大目標拆解為可控的具體小目標，以降低其悲觀預期帶來的阻力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3590, 'SPA_05', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「易碎的火藥桶」。對事物解讀消極（05C）且情緒反應劇烈（18A），在受挫時極易爆發並做出毀滅性的反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3591, 'SPA_05', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「消沉的悲觀者」。內在缺乏對未來的預期（05C），生理上亦表現出能量不足（10C）。預測：在團隊中表現極度被動，需透過環境刺激或高度結構化的激勵來拉動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3592, 'SPA_06', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「永不枯竭的動力源」。具備足夠的心理資本（01A）支持其高強度的投入（06A）。預測：這類人能維持長時間的高效產出，是組織在開拓期或衝刺業績時的核心戰力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3593, 'SPA_06', 'A (高)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「抗壓的執行長跑者」。在面對高壓與挫折時，不僅復原快（04A），且能迅速回到專注與奉獻的工作狀態（06A）。行為預測：即便在市場低迷期，仍能維持穩定且積極的工作節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3594, 'SPA_06', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自我迭代的工作狂」。極度投入工作且渴望透過外部回饋（08A）來提升工作效能。管理建議：給予具體的優化方向與資源，其轉化效率會極高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3595, 'SPA_06', 'A (高)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的現場指揮官」。體力充沛（10A）配合精神上的高度專注（06A）。預測：在第一線銷售或高頻率互動場合中，具備極強的氣場與感染力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3596, 'SPA_06', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「使命必達的精英」。強大的晉升與成就慾望（15A）完全驅動了其在工作中的奉獻精神（06A）。警示：需關注其工作與生活的平衡，預防因過度透支而產生的崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3597, 'SPA_06', 'A (高)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「全神貫注的多面手」。雖然節奏急促且處理多項任務（16A），但每一項都能保持高度的專注力（06A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3598, 'SPA_06', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「心理資本撐底的看情境投入者」。他的希望感、效能感與韌性都算充足，碰到困難時不容易慌，能把壓力拆解成一步步可處理的任務；但心力要往哪個方向擺，仍然看這件事的目標是否清楚、成果是否看得見。目標明確、回饋及時的專案，他會全神貫注、心力全押上去；一旦任務意義模糊或看不到具體成效，投入的比重會自然往下收，即使當下信心與復原力都還在。管理上宜替他把目標與意義講清楚、把進度回饋做出來，讓他把底氣穩定地用在該投入的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3599, 'SPA_06', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「回饋撐得住、連續消耗撐不住的投入者」。在目標清楚、能看到成果的階段，他願意把心力都放進工作裡、表現得相當專注；但只要遇上連續的高壓或拖長的不確定，疲乏與挫折感會很快堆起來，復原的速度也偏慢，工作上投入的力道也跟著明顯起伏。同一段時間，他常前半段全力衝、後半段明顯放緩，這時候的耗損已經累積到他撐不動的程度，工作本身的意義感其實還在。管理上宜留意連續高壓期別拉太長，適時給他喘息與階段性收尾，投入才有機會維持在較穩定的水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3600, 'SPA_06', 'B (中)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) 高分聯動：表現為「靠回饋校準投入方向的人」。他不太會悶頭做完才知道結果，會主動找主管、同儕或客戶確認自己做得如何、哪裡該調整，把每一次回饋都當成加速進步的材料，調整動作也快。拿到清楚的回饋、確定方向沒錯時，他會明顯加碼投入、心力放得更重；但若回饋遲遲拿不到、任務意義又模糊不清，他容易不確定該往哪使力，投入程度隨之下滑。管理上若能建立穩定且即時的回饋管道，讓他主動要來的資訊有地方落地，投入也比較不會懸在半空。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3601, 'SPA_06', 'B (中)', 'SPA_10', 'C', '與 SPA_10 (精力充沛) 低分聯動：表現為「按部就班、看情境加碼的投入者」。他做事的步調本來就不追求快，傾向按部就班一步步來，在步調拉得很快的環境裡容易感覺被推著走、消耗感明顯。目標清楚、能看見成果時，他願意把時間心力多放一些進去，只是動作仍是穩紮穩打而非衝刺；一旦任務意義不明或步調被逼得太快，他既難拉高投入，也難維持原本的節奏與品質。管理上宜給他相對可控的節奏與清楚的目標，而不是用高速趕工逼他，這樣他投入的部分才撐得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3602, 'SPA_06', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「看得到意義就自我加碼的衝刺型」。他對把事情做到最好有明確企圖心，遇到目標常會想再往上拉一點、追求更高的成就，不甘於只是及格。任務方向清楚、能看見具體成果時，他會主動加碼、把時間精力大量往這件事集中，衝勁十足；但若任務意義曖昧、看不出努力會通向哪裡，他的投入容易先降下來，那份想做好的企圖心仍在，只是暫時找不到可以使力的地方。管理上宜把目標與價值講清楚，讓他清楚知道往哪個方向衝、衝了會有什麼結果，才接得住他這股企圖心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3603, 'SPA_06', 'B (中)', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) 低分聯動：表現為「專注單線、看情境決定投入強度的人」。他習慣把一件事做完再換下一件，不喜歡同時攤開太多任務，在被要求高度多工的環境裡容易感到吃力、效率跟著往下掉。這種一次一件的節奏底下，他對眼前這件事的投入程度仍然看情境：只要這件事本身目標清楚、成果看得見，他會把全部注意力都收攏在上面、做得很專注；但一旦被迫同時應付多頭任務、又看不出意義所在，他的專注力被拉散，投入的深度也跟著變淺。管理上宜盡量讓他一次處理少量、目標明確的工作，而不是逼他同時開多線，投入的品質才維持得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3604, 'SPA_06', 'B (中)', 'SPA_05', 'A', '與 SPA_05 (樂觀) 高分聯動：表現為「正向但要看得到意義才全力壓上的人」。他傾向把不順利的狀況解讀成暫時、可以改善，遇到不確定時仍願意嘗試、邊做邊修正，情緒和行動力大致能維持住。目標清楚、能看到具體回饋的工作，他會樂觀地把心力大量放進去，遇到小挫折也不太當一回事、很快調整心態繼續做；但若任務意義模糊、成就感遲遲出不來，他的投入還是會往下收，即使嘴上仍可能說得雲淡風輕。管理上宜替他把工作的目標與意義說清楚，讓他的正向心態有方向可以承接，投入才不會停留在嘴上樂觀而已。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3605, 'SPA_06', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「休眠中的穩定者」。具備心理資源（01A）但目前處於低度參與狀態（06C）。管理建議：這類人具備能力，但缺乏被點燃的火種，需主管賦予具備「使命感」或「趣味性」的目標來活化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3606, 'SPA_06', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「消極的旁觀者」。對未來預期消極（05C），導致其在工作中僅投入最低限度的精力（06C）。風險：容易成為團隊中的負能量源，需介入輔導其歸因風格。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3607, 'SPA_06', 'C (低)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「心理罷工者」。因感到不公平（09C），故主動降低工作投入度（06C）以尋求心理補償。管理建議：應優先處理公平感議題，否則給予任何激勵都無效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3609, 'SPA_06', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「投機的競爭者」。想贏過他人（14A），但不想付出實質的專注與奉獻（06C）。預測：這類人可能追求「短平快」的成果，但在需要深耕的長期業務中表現不佳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3610, 'SPA_06', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「因不滿而離職的風險者」。投入度低（06C）且情緒易衝動（18A），一旦遭遇小挫折極易產生「不幹了」的極端行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3611, 'SPA_06', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「完美的安靜離職者」。行為上維持著社交認可的表現（12A），但內在精神已完全脫離工作（06C），極具隱蔽性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3612, 'SPA_07', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「穩健的高標專家」。心理資源充沛（01A）支持其長期的專業堅持（07A）。預測：在面對長期且高標準的客戶服務時，能維持極高的一致性，不因心理疲勞而降低專業水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3613, 'SPA_07', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「策略型的高標者」。既能找到達成路徑（02A），又能在過程中維持極佳的專業細節（07A）。管理建議：其產出的方案不僅「可行」，且具備極高的「品牌價值感」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3614, 'SPA_07', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「極致的專業勞模」。高度投入工作（06A）且對產出標準有強烈執著（07A）。行為預測：是組織內流程與品質的標竿，能引導團隊建立高水準的工作慣性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3615, 'SPA_07', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自我修正的高標者」。為了維持職業高度（07A），會極度主動地尋求並吸收改進建議（08A）。預測：其專業能力會隨職涯長度呈線性以上的成長。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3616, 'SPA_07', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「追求頂峰的精英」。強大的企圖心（15A）透過嚴謹的職業素養（07A）變現。管理建議：適合負責品牌關鍵業務或高端客戶開發，能建立極佳的市場口碑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3617, 'SPA_07', 'A (高)', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) C 聯動：表現為「慢工出細活的匠人」。不喜歡多工並行以防損害品質（16C），堅持完成一項高品質任務後才切換（07A）。警示：在節奏極快、需要大量「快餐式」產出的環境下可能感到壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3618, 'SPA_07', 'A (高)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致冷靜的專業代表」。遇到挫折時情緒穩定（18C），且始終維持代表公司的專業形象與應對準則（07A）。預測：在客訴或爭議場合中，是維護公司信譽的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3619, 'SPA_07', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「壓力下自己撐住品質的人」。他維持專業細節與流程一致性的表現會隨情境起伏，一忙起來、任務一多，某些環節容易漏掉或做得比較粗；但他手上有信心、有動能，遇到這種波動不會慌，會把它當成一個可以處理的問題來面對。碰到高壓多工時，他常主動先把最要緊的幾件事挑出來顧好，剩下的分批補齊，而不是任由品質整片下滑。清楚的優先順序加上一點喘息空間，會讓他把落下的水準重新拉回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3620, 'SPA_07', 'B (中)', 'SPA_02', 'C', '與 SPA_02 (希望) 低分聯動：表現為「標準鬆動時找不到補救路徑的人」。他平時能守住基本規範與品質，但一旦事情多起來、時間吃緊，細節就容易跟著掉；問題是他也不太擅長把「怎麼補回來」想成具體幾步，卡關的時候常常說不出下一步該做什麼。這種時候他容易停在原地乾著急，或是先挑眼前最省事的方式把事情交出去，品質落差就這樣被放著。有人幫他把補救步驟拆清楚、指出先做哪一步，他才比較容易把水準拉回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3621, 'SPA_07', 'B (中)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) 高分聯動：表現為「把守住水準當自我價值硬撐的人」。他做事的細膩度與一致性會因情境而有起伏，忙碌或身兼多頭時容易露出破綻；但他把工作表現看得很重，幾乎當成自己重不重要的證明，所以一旦感覺到自己做得不夠好，會很難輕輕放過。碰到品質開始鬆動的時刻，他常見的反應是投入更多時間精力去硬撐、去補，而不是調低標準了事。長期處在這種狀態容易把自己耗到疲乏，需要有人幫他判斷哪些該堅持、哪些可以放手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3622, 'SPA_07', 'B (中)', 'SPA_08', 'C', '與 SPA_08 (反饋尋求) 低分聯動：表現為「落差悄悄累積、被動才發現的人」。他基本上守規矩、守流程，但高壓或多工一來，某些細節會不自覺跑掉；偏偏他也不習慣主動去問別人「這樣做對不對」，覺得沒必要，或有點怕聽到不好的答案。結果是品質波動常常沒人即時點出來，落差就一路累積，直到被別人發現或出了狀況他才驚覺。若能建立固定的檢核點，讓回饋不靠他自己開口就會出現，他的表現會穩定不少。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3623, 'SPA_07', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「波動一出現就想自我加碼拉回來的人」。他維持品質的表現會隨情境浮動，高壓或多工時容易露出縫隙；但他對「做到最好」有很強的企圖心，並不甘於只交出堪用的成果。所以只要感覺到自己表現不如平常，他常常會主動加碼、多花心力想辦法把水準往上拉，而不是接受一個比較低的結果。這股勁頭給了他把落差補回來的機會，但也可能在已經很緊繃的狀態下又給自己加壓，需要有人適時提醒他量力而為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3624, 'SPA_07', 'B (中)', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) 低分聯動：表現為「被迫多工時節奏和品質一起亂的人」。他其實比較習慣一次專注做好一件事，照著自己的步調走時，品質與流程都能顧得穩；但工作環境常常不由他選，一旦同時被塞進好幾件事，他既要應付不熟悉的多工步調，又要撐住原本的專業標準，兩邊都在同一時刻被拉扯。這種時候容易看到他手忙腳亂、細節顧不周全，交出去的東西跟平常水準有落差。若任務能盡量單線排列、給他清楚的先後順序，他撐住品質的能力會明顯回穩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3625, 'SPA_07', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「顧不好細節又容易被激出情緒的人」。他多數時候守得住基本專業，但高壓或任務一多，品質容易出現波動、有些環節會被漏掉；同一時刻，他面對挫折或被指出問題時也比較容易上火，情緒升溫快，語氣可能變硬，甚至當場頂回去。這兩件事常常在同一個緊繃時刻一起冒出來——一邊在補救沒顧好的細節，一邊情緒還沒完全平復。事後他多半能自己緩下來、把該修正的修正掉，但當下若有人能先給他一點緩衝空間、晚一點再談問題，會比較容易把情緒和品質兩邊都穩住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3626, 'SPA_07', 'C (低)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「自信但粗放的行動者」。相信自己能搞定（03A），但容易忽略標準流程或職業禮儀（07C）。風險：個人表現雖強，但容易因不合規範而給公司帶來潛在的品牌形象風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3627, 'SPA_07', 'C (低)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高耗能的粗心者」。做事積極、步調極快（10A），但因為標準感較鬆（07C），容易在高速推進中漏失細節或破壞規範。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3628, 'SPA_07', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的交差者」。為了效率與掌控感（13A），往往會為了「做完」而犧牲「做精」（07C）。管理建議：需提供明確的 Check-list 強制其回頭確認細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3629, 'SPA_07', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「只問贏不問流程的競爭者」。勝負心強（14A），但在追求第一的過程中可能採取非標準或有損一致性的路徑（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3630, 'SPA_07', 'C (低)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「時間壓力下的粗製濫造者」。當感到時間緊迫時（17A），會第一個放棄專業規範以求時程達標（07C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3631, 'SPA_07', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「表面專業的隨意者」。口頭上極度配合規範（12A），但實際操作時卻容易因為缺乏內在標準（07C）而出現行為落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3632, 'SPA_08', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「自信的優化者」。具備充足心理資源（01A）以緩衝負面反饋的衝擊，視回饋為成長工具而非否定。預測：面對嚴苛批評時能維持情緒穩定並精準提取改進建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3633, 'SPA_08', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「目標導向的精進者」。對能力有信心（03A），故敢於詢問「我如何能做得更好」（08A）。管理建議：其成長曲線斜率最高，能將指導快速轉化為產出質量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3634, 'SPA_08', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「高標準的職人」。為了維持專業高度（07A），會反覆確認自身產出是否符合期待（08A）。預測：極少出現嚴重的執行偏差，是組織內部的品質標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3635, 'SPA_08', 'A (高)', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「終身學習者」。相信能力可變（11A）且積極透過他人視角識別盲點（08A）。管理建議：非常適合負責新技術導入或需要頻繁轉型的專案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3636, 'SPA_08', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「具侵略性的晉升者」。為了達成個人目標與權力（15A），會主動收集所有有利於調整戰術的資訊（08A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3637, 'SPA_08', 'A (高)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「冷靜的資訊吸收者」。能去情緒化地處理反饋內容。預測：即便是具備高度衝突性的回饋，也能理智地過濾雜訊、保留核心建議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3638, 'SPA_08', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「底氣撐住的情境核對者」。他平常做事有底氣、對自己能扛住任務相對有把握；日常也不太主動追著要別人給意見，多半到眼前出現落差——績效有波動、被指出具體問題，或有人明確要求說明——他才會真正回頭去核對。到了那個時刻，他不會被一時的壞消息壓垮，願意正面接住不好聽的評語，把找出問題出在哪當成一件可以拆解、按部就班處理的事去推進。遇到連續的挑戰或不確定，他多半還能維持基本的信心與行動力，把壓力拆成一個個可以先動手的小任務，不容易因為一次挫折就停下腳步。管理上宜在落差還小的時候就主動給予具體、階段性的回饋，讓他把核對與調整做在更早的節點，不必等到問題明顯了才被動接手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3639, 'SPA_08', 'B (中)', 'SPA_03', 'C', '與 SPA_03 (效能感) 低分聯動：表現為「遲疑縮手的被動核對者」。他心裡常對自己能不能把事情做到位沒有十足把握，卡關或被挑毛病時容易先往壞處想，一度想先縮手、拖著不動；真的要主動開口去問別人怎麼看他，這一步他也不容易踏出去，多半要等到問題被明確攤開、或有人直接要求他說明，他才會回頭把狀況問清楚。一旦真的被推到要核對的位置，他能聽進具體的意見，只是聽完之後的下一步，常常要花一段時間才重新提起行動力，中間容易卡在猶豫要不要動手。平時沒有主動找人核對的習慣，落差就容易在他自己沒察覺的情況下持續累積，直到影響已經明顯了才被看見。管理上宜主動、定期、用具體且不帶指責的方式提供回饋，並在他表現出猶豫時給予明確的下一步指引，降低他重新啟動行動的門檻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3640, 'SPA_08', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「內建高標的觸發核對者」。他做事習慣照著自己一套偏高的標準走，重視流程與細節，也在意對外代表出去的形象是否一致；日常不常主動開口問別人自己表現如何，多半要等到有人具體點出落差，或績效出現波動，他才會停下來回頭核對。被指出問題的當下，他不會為了維護形象而迴避，反而願意把意見聽進去、仔細比對哪裡沒到位，把調整做得跟平常做事一樣講究。他平時靠自己內建的標準把關，較少倚賴外部確認；落差有時要等到被明確攤開，才真正進入他的視野，中間可能已經累積一段時間。管理上宜把回饋做得具體、對齊他重視的專業標準，並在還沒演變成明顯落差前主動提供，讓他能把修正做在更早的節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3641, 'SPA_08', 'B (中)', 'SPA_11', 'C', '與 SPA_11 (可塑性) 低分聯動：表現為「觀望保留的觸發核對者」。他平常不太主動找人核對自己的表現，多半要等到問題被具體點出、績效出現落差，或被要求說明，他才會回頭去問；聽到意見的當下，他心裡容易先浮現「這樣真的能改變什麼嗎」的疑問，而不是立刻想著怎麼調整。面對被指出的落差，他有時會先觀望一陣子，看看情況是不是真的需要動，而不是馬上把回饋轉成具體行動。一旦挫折感出現——例如試了一次沒有明顯改善——他投入去消化、應用那些意見的意願容易跟著降低，回饋核對的頻率也就更依賴外部持續推動。管理上宜搭配具體可見的小改善案例，並在他觀望時給予明確、分階段的引導，讓他能把回饋真正落地，而不只是停在「聽過」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3642, 'SPA_08', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「先衝後核的高企圖者」。他做事常會自己把目標往上加碼，想把成果做到超出原本要求，這股衝勁多半是靠自己往前推；平常不太會主動停下來問別人自己做得夠不夠好，直到績效出現波動、或有人明確指出落差，他才會回頭去核對。真正核對起來，他會很認真把意見聽進去，把已知的落差當成還沒達標的部分繼續處理，核對後常會立刻想著怎麼把下一步拉得更高。主動核對的頻率不高，中間的落差有時會被他用「先衝再說」的節奏蓋過去，等真正被攤開時，可能已經跑了一段時間、需要調整的幅度也變大。管理上宜趁著他還在往前衝刺的階段，就主動、具體地給予回饋，並把回饋跟他在意的目標高度連結，讓他能更早把調整併入衝刺的路徑裡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3643, 'SPA_08', 'B (中)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) 低分聯動：表現為「冷靜以對的低頻核對者」。他平常不太會主動追著問別人自己表現如何，多半在績效出現落差、被具體點出問題，或有人要求說明時，才會回頭去核對；但當那一刻真的來了，他多半能保持冷靜，不太會因為聽到不好聽的話就情緒上來或急著辯解。面對煩惱、衝突或被質疑的場合，他傾向先把情況看清楚再回應，核對問題時也是同一種態度——先聽完整，再判斷哪裡真的需要調整，較少出現當場翻臉或迴避對話的狀況。一旦真的進入核對，過程通常能維持理性、聚焦在事實上，不太會被一時情緒帶偏；只是主動開啟核對這個動作的頻率仍然偏低，落差往往要先被攤開，才會真正進入處理階段。管理上可以放心用直接、具體的方式給予回饋，不需要過度包裝；但仍宜主動、規律地建立核對的節奏，才不會讓問題累積到後期才被處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3644, 'SPA_08', 'B (中)', 'SPA_04', 'A', '與 SPA_04 (韌性) 高分聯動：表現為「挫折快回穩的觸發核對者」。他平常不常主動去問別人自己表現如何，多半要等到眼前出現落差——績效被質疑、目標沒達成，或有人明確要求說明——他才會停下來回頭核對；被指出問題的當下即使不好聽，他也很少因此亂了陣腳。遭遇拒絕、衝突或目標落空之後，他多半能在不久之後重新回穩，把接收到的意見拆解成可以調整的具體項目，繼續往下推進，不容易被單一次的挫折卡住太久。即使核對的頻率不高、落差累積了一段時間才被攤開，他事後也還能迅速消化、調整策略並保持輸出，不至於因為一次性湧入的大量意見就被壓垮。管理上可以在績效落差出現時直接、完整地給予回饋，不必擔心一次講太多會擊垮他；但宜同時建立更規律的核對節奏，讓問題有機會在還小的時候就被處理，而不是每次都等到累積成一次性的大調整。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3645, 'SPA_08', 'C (低)', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「躲避評價的萎縮者」。因缺乏信心（03C）而害怕暴露弱點，故極力避免詢問他人意見（08C）。風險：容易在錯誤的道路上悶頭苦幹，最終導致無效產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3646, 'SPA_08', 'C (低)', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「玻璃心的自我封閉者」。抗壓韌性低（04C），為了保護脆弱的自尊而排斥外部評價（08C）。管理建議：需主管主動建立非正式、溫和的溝通管道。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3647, 'SPA_08', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「悲觀的宿命論者」。傾向認為現狀無法改變（05C），因此認為尋求反饋沒有意義（08C）。警示：容易產生職場怠惰或習得性無助。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3648, 'SPA_08', 'C (低)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「多疑的防禦者」。對公平性敏感（09C）且不信任外部評價（08C），傾向認為他人的反饋是出於偏見或權力打壓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3649, 'SPA_08', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「固執的競速者」。追求效率與掌控（13A），往往會因為「沒時間」或「我最懂」而忽視外部修正意見（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3650, 'SPA_08', 'C (低)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「忙中出錯的執行員」。因感到時間緊迫（17A）而捨棄了必要的確認與回饋環節（08C）。風險：雖然交得快，但準確率往往堪憂。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3651, 'SPA_08', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「表面服從的封閉者」。口頭上同意回饋的重要性（12A），但實際上從不主動去開啟具備實質意義的評價對話（08C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3652, 'SPA_09', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「組織的定海神針」。心理資源充沛（01A）且對回報不計較（09A）。預測：在公司草創期或艱困期，能無怨無悔地投入，不因短期的待遇不均而動搖，是組織忠誠度的標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3653, 'SPA_09', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「純粹的奉獻者」。對工作高度投入（06A）且較不看重即時回報（09A）。管理建議：其動能來自成就感而非物質激勵，是極具使命感的員工，但須提防因過度付出而遭不當利用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3654, 'SPA_09', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「自省的關係維護者」。主動尋求回饋（08A）是為了確保自己對團隊的貢獻足夠，而非爭取更多資源（09A）。其互動風格極具合作性，能降低團隊摩擦成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3655, 'SPA_09', 'A (高)', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「高彈性的長線投資者」。相信能力可變（11A），且願意在看到明確回報前先行投入學習與調整（09A）。預測：在需要跨領域轉型且前期回報不明時，其適應力最強。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3656, 'SPA_09', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「具格局的衝刺者」。有強大企圖心（15A），但能忍受「延遲滿足」。為了更宏大的長遠目標，願意承受當下的不對等對待或高強度付出（09A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3657, 'SPA_09', 'A (高)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「豁達的穩定器」。面對資源分配不均時情緒極度冷靜（18C）且內在容忍度高（09A），能有效緩衝團隊內的對立情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3658, 'SPA_09', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「撐得住等待的互惠協調者」。他會留意自己的付出跟拿到的回報是否對等，但只要有人把背景講清楚、看得到補償或改善的做法，他多半願意接受一時的落差、繼續把事情做下去。碰到分配不如預期的狀況，他不會立刻陷入無力或停擺，通常能維持基本的信心與行動力，把這次沒拿到對等回報當成一個可以處理、可以等待改善的狀況。他會主動找人確認差異背後的原因，理解之後便重新投入，不容易因為單次落差就對整體失去信心。管理上可以坦白說明分配邏輯與後續調整的時間表，他有足夠餘裕撐過等待期，合作關係也能維持住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3659, 'SPA_09', 'B (中)', 'SPA_06', 'C', '與 SPA_06 (工作投入性) 低分聯動：表現為「看對等給投入的份內責任型」。他把工作當成生活裡的一部分責任，投入的程度容易隨外部要求增減，不太會主動加碼或做長線耕耘。但如果制度講得清楚、看得到補償或改善機制，即使一時付出與回報不對等，他也能接受差異、把份內的事做完。遇到分配明顯偏差又沒人說明時，他不容易多花力氣去補，投入度會跟著往外部要求靠。他在意的是這次合作划不划算，一旦理解背後的考量，仍會維持基本的配合，不會因此翻臉或消極抵制。管理上宜清楚交代分配依據與調整方向，避免讓他把落差直接解讀成不值得投入更多。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3675, 'SPA_10', 'A (高)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「高壓競速的超人」。具備強烈的競爭欲與時間緊迫感（13A），且其生理能量（10A）剛好能匹配這種高節奏需求。警示：雖短期表現優異，仍需防範因長期無視疲勞信號而導致的突發性崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3660, 'SPA_09', 'B (中)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) 高分聯動：表現為「邊要回饋邊核對等的成長型」。他會主動找主管、同儕或客戶確認自己的表現與可以改進的地方，把回饋拿來當加速成長的工具，調整速度也快，同時心裡也在算這份付出跟拿到的回報是不是對等，只要理解背景、看得到補償或改善的做法，落差他還能接受並繼續合作。要回饋的過程裡，他常順勢問到分配或待遇的邏輯是什麼，把這當成確認公平性的機會，而不只是問表現好壞。得到清楚說明後，他會把注意力放回怎麼把事情做更好，不會卡在不對等的情緒裡太久；但如果回饋只講表現、迴避分配問題，他的投入可能悄悄打折。管理上給回饋時不妨一併說明資源與待遇的分配邏輯，他消化得快，也能更早回到穩定的合作節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3661, 'SPA_09', 'B (中)', 'SPA_11', 'C', '與 SPA_11 (可塑性) 低分聯動：表現為「觀望心態下仍認帳的對等計算者」。他傾向認為自己的能力與特質相對固定，面對要求改變時常先觀望，甚至覺得努力調整也未必有用，學習的投入度容易被一次挫折打掉；不過在付出與回報這件事上，只要背景講得通、看得到補償或改善的機制，落差他仍願意接受並維持合作。遇到制度調整又同時被要求跟著改變做法時，他容易先卡在這樣做有用嗎的懷疑，行動會慢下來。但如果調整後看得到相對合理的補償或說法，他還是會把手上的事情完成，不至於直接抵制。管理上若要推動改變，宜同時把公平性的說明放進去，例如清楚交代誰調整了什麼、換來什麼，能降低他觀望的時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3662, 'SPA_09', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「邊衝邊核對等的高成就衝刺者」。他企圖心強，想把成果做到最好，容易自我加碼、追求更高的成就，遇到目標時會想辦法往上拉一截，同時也在意這份衝刺換來的回報合不合理，只要理解背景、看得到補償或改善的機制，中間的落差他還能接受並繼續往前推。設定目標時他常自己加碼，但也會留意升遷、獎酬或資源分配是否跟得上他投入的強度。一旦覺得長期付出多、回報明顯沒跟上又缺乏解釋，他的衝勁可能開始打折，甚至把力氣轉去對自己更划算的方向。管理上宜讓成就與獎酬的連結保持透明，適時說明調整的邏輯，他的高標準與衝刺動能才比較留得住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3663, 'SPA_09', 'B (中)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) 低分聯動：表現為「穩得住情緒的對等盤點者」。他的情緒反應門檻偏高，遇到煩惱或衝突多半能保持冷靜、理性處理，不太會因為一時情緒就做出代價高的決定；碰到付出與回報不對等的狀況，他通常會先想辦法弄清楚背景，只要看得到補償或改善的機制，落差他仍能接受並維持合作。這種穩定用在討論分配問題上很有幫助：他比較能就事論事、不把話題變成情緒對抗，也比較容易換來主管進一步說明的空間。但也因為表現得穩，不滿有時不容易被看出來，要等落差累積到一定程度才會明顯表現出保留或抽身。管理上不能只看他表面平靜就認定沒事，宜主動確認他對分配公平性的感受，及早處理避免長期累積後才發現問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3664, 'SPA_09', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「守高標準也核對等的專業型」。他傾向遵守規範、維持專業品質，做事不只求達標，還想追求更好，對外代表公司接觸時也在意形象與一致性，同時心裡對付出跟回報是否對等有一把尺，只要理解背景、看得到補償或改善的機制，中間的落差他還能接受並繼續維持合作。面對規範或流程要求時，他多半願意配合到位，但也會留意這份高標準要求換來的資源、肯定或待遇是否合理跟上。一旦長期感覺自己守著標準、對外撐著形象，換到的回報卻沒有相應調整又缺乏說明，他可能開始質疑這樣做值不值得，甚至把力氣收斂到守住基本、不再多做。管理上宜讓對外標準與內部支持、獎酬之間的對應關係保持清楚，適時說明分配邏輯，他的高標準與合作意願比較能一起維持住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3665, 'SPA_09', 'C (低)', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「焦慮的防禦者」。心理資源緊繃（01C）且對公平性極度敏感（09C）。風險：一旦察覺資源分配微小不公，會迅速進入自我保護模式，降低產出甚至引發激進抗議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3666, 'SPA_09', 'C (低)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「條件式的拼命三郎」。投入度極高（06A），但要求回饋必須與其付出精確對等（09C）。管理建議：必須提供極其透明、量化的考核與獎勵機制，否則其高產出會瞬間消失。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3667, 'SPA_09', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「具備契約精神的專業職人」。嚴守職業標準（07A），同時也要求公司必須嚴守制度一致性（09C）。警示：若公司帶頭破壞規則，他將是第一個站出來質疑規範合法性的人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3668, 'SPA_09', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的利益爭取者」。進取心強（13A）且對資源分配極度敏感（09C）。其競爭行為往往伴隨著對權益的強烈防禦，容易與同事產生激烈的地盤或資源爭奪。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3669, 'SPA_09', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「精算型的競爭者」。求勝心切（14A），且會緊盯對手的回報與資源是否優於自己（09C）。風險：容易因感知不公而將競爭轉化為對體制的敵意。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3670, 'SPA_09', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「公平的正義使者（火藥桶型）」。對不公極度敏感（09C）且反應劇烈（18A）。管理建議：絕對不宜對其採取模糊的黑箱管理，任何決策的公平性解釋必須第一時間到位，否則會引發強烈對抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3671, 'SPA_09', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「隱蔽的計較者」。雖然極度在意回饋（09C），但在公共場合會努力表現得合乎規範與優雅（12A）。隱憂：不滿情緒會轉向地下化，容易在背後影響團隊氛圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3672, 'SPA_10', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全方位的續航戰士」。體能充裕（10A）且心理韌性強（01A）。預測：在長期、跨國或極高壓的專案中，其身心穩定度極高，是帶領團隊衝破困難期的高產出領袖。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3673, 'SPA_10', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「高自信的衝鋒者」。既相信自己能做到（03A），且具備充足體力去實踐（10A）。管理建議：其行動力極強，適合承接第一線業務開拓，能維持極高密度的拜訪與工作頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3674, 'SPA_10', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「心流狀態的體踐者」。高度專注工作（06A）且生理動能十足（10A）。行為預測：在工作現場表現出極強的感染力，能同時維持高品質的產出與高昂的精神面貌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3676, 'SPA_10', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「目標導向的高產能精英」。對成功的強烈渴望（15A）與充沛精力（10A）結合，使其在追求目標時極具侵略性與持久力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3677, 'SPA_10', 'A (高)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「快節奏的多線處理者」。能在多項任務中快速切換且不顯疲態，是快節奏環境（如快消品、電商）中的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3678, 'SPA_10', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「起伏中仍有底氣的行動者」。多數時候他做事有衝勁、步調偏快，遇到連續高壓或成果感薄弱時能量會明顯降下來，動作變慢、主動性減弱。即使在低點，他也不容易被一次挫折打空信心，仍傾向相信自己能把壓力轉成可處理的任務，即使動作變慢也不至於整個停擺，往往還能撐著把當下的事推進一小步。等資源補上、看到具體回饋，他很快就把節奏拉回來。管理上可以放心讓他自己找回穩定，重點是持續給他看得到的成果訊號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3679, 'SPA_10', 'B (中)', 'SPA_03', 'C', '與 SPA_03 (效能感) 低分聯動：表現為「動能鬆手時連帶卻步的人」。他多數時候有活力、做事積極,但一旦連續碰壁或看不到具體成果,能量會先掉下來,動作變慢、主動出手的次數變少。這時候他對自己能不能靠努力達成目標也會跟著沒把握,容易因為一次失手就縮手、把手上的事往後拖,啟動下一步的門檻變高。兩件事疊在一起的低點,常常不是單純沒力氣,而是連帶懷疑自己做不做得到,拖延感會比只是累還要更明顯。等到補給到位、有人幫他釐清下一步該怎麼做,他才比較容易重新提起腳步往前走。管理上宜在他能量下滑時同步給具體可行的小步驟,不要只補資源不補方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3680, 'SPA_10', 'B (中)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) 高分聯動：表現為「把工作擺第一的起伏衝刺者」。他把大部分時間與心力放在職責與成果上,做事偏快、積極,願意主動把事情往前推。這股投入不代表能量永遠在線上,連續高壓或看不到成就感的階段一到,他的行動力會先降下來,推進速度變慢、拼勁減弱。因為工作本來就佔他自我價值感很重的位置,能量低的時候他反而更容易往工作上鑽、想靠再多做一點來找回感覺,而不是先停下來喘口氣。等到有清楚回饋或補到資源,他很快又能拉起節奏加碼投入。管理上要留意他在低點時的加碼衝動,適時提醒他先回穩再推進,避免耗損累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3681, 'SPA_10', 'B (中)', 'SPA_13', 'C', '與 SPA_13 (A型性格) 低分聯動：表現為「衝勁起伏、底色平穩的人」。他多數時候有活力、做事積極,連續高壓或缺乏成就感時能量會往下掉,動作變慢、主動出手變少。即使在拼勁上來的時候,他也不太靠競速或掌控局面過日子,遇到進度受阻也少見急躁或對抗的反應,傾向用穩定合作的方式把事情往前挪。能量低點來的時候,他不會因為落後而焦躁催促,比較像是先安靜地慢下來,等資源補上、看到回饋再重新提速。他的起伏因此比較不外顯,旁人有時會低估他當下其實正在耗損。管理上宜主動關心而非等他喊累,適時補上成就感訊號幫他回穩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3682, 'SPA_10', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「企圖心撐住的衝刺型行動者」。他做事積極、步調偏快,想把成果做到最好,遇到目標會想往上拉。連續高壓或成就感不足的階段,行動力還是會下滑,推進速度變慢、拼勁明顯減弱。但他對「變更好」這件事的在意程度不太隨能量高低而消失,即使動能偏低,他仍傾向在有限力氣裡挑最能拉高成果的事去做,而不是隨意放掉。等看到具體回饋或資源補上,他很快就從局部發力切回全面加速,把落下的進度追回來。管理上宜在他低點時聚焦少數高槓桿任務,避免他用有限能量硬撐全面推進而加速耗損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3683, 'SPA_10', 'B (中)', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) 低分聯動：表現為「起伏中偏好收斂戰線的人」。他多數時候有活力、做事積極,連續高壓或缺乏成就感時能量會下降,行動變慢、主動性減弱。他做事的習慣本來就傾向專注完成一件事再切換,不太靠同時開很多線來衝速度,所以能量低的時候,他更明顯地把戰線收窄,一次只推一件,而不是硬撐多頭並進。低點時他手上事情不多,不容易因為多頭並進而更加混亂,但整體產出量會明顯縮小。等資源補上、看到成果回饋,他才會重新拉開步調、願意多接一點。管理上宜在他低點時主動減少交辦項目數量,讓他能守住品質再逐步加量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3684, 'SPA_10', 'B (中)', 'SPA_04', 'A', '與 SPA_04 (韌性) 高分聯動：表現為「低點快速回彈的衝勁型」。他多數時候有活力、做事積極,連續高壓或缺乏成就感時能量還是會往下掉,動作變慢、拼勁減弱。不同的是,他遭遇挫折或目標落空後不容易被打亂節奏,能相對快速地重新調整策略、把自己拉回軌道,不會在低點停留太久。他的能量起伏因此偏向短暫的凹陷而非長期停擺,落下去之後只要補到一點資源或回饋,他很快就能重新啟動、恢復原本的積極步調。管理上可以不用過度介入他的低點,適時提供支持與明確下一步,他多半能自行回穩並繼續往前推。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3685, 'SPA_10', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「精神強大的穩健者」。雖然體能充沛度較低（10C），但靠著強大的內在心理底蘊（01A）維持穩定。管理建議：應優化其工作流程，減少無謂的體力消耗，發揮其心理資源的優勢。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3686, 'SPA_10', 'C (低)', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「易碎的低能耗者」。生理動能弱（10C）且抗壓韌性低（04C）。風險：在突發的高強度壓力下極易產生逃避心理或生理不適，不宜配置於變動劇烈的環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3687, 'SPA_10', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「自律的長跑者」。雖能量有限（10C），但靠著對標準的堅持（07A）精準分配體力，確保留在場上的每一刻都符合專業水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3688, 'SPA_10', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「心有餘而力不足的競爭者」。想贏（14A），但體力跟不上其野心（10C）。管理建議：需教導其「智慧工作（Smart Work）」而非體力透支，避免其因力不從心產生憤怒情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3689, 'SPA_10', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「疲憊導致的火藥桶」。生理能量低落時（10C），情緒調控力隨之下降，極易因為勞累而對身邊同事或客戶發火。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3690, 'SPA_10', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「強打精神的禮貌者」。生理已感到疲憊（10C），但為了維持正面形象（12A）仍苦撐社交。警示：下班後會有嚴重的「社交脫水」現象，需給予其安靜的補能空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3691, 'SPA_11', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全方位的進化者」。相信能力可變（11A）且具備充足心理資源（01A）去支撐改變過程中的陣痛。預測：在企業轉型期能率先適應新角色，並將改變視為累積心理資本的機會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3692, 'SPA_11', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「具備路徑靈活性的學習者」。因相信自己能改變（11A），故在目標受阻時，能更有動力去規劃全新的達成路徑（02A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3693, 'SPA_11', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「高效的自我重塑者」。對現有能力有信心（03A），且相信未來能透過學習變得更強（11A）。管理建議：給予挑戰性極高的任務，他們會將其視為「升級」的必經過程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3694, 'SPA_11', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「主動尋求進化的精英」。相信改進是有效的（11A），因此會不遺餘力地從回饋中挖掘優化空間（08A）。預測：其能力成長速度會顯著高於同儕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3695, 'SPA_11', 'A (高)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「具備戰術調整力的競爭者」。渴望贏過他人（14A），且願意為了取勝而不斷調整自己的行為模式與技能（11A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3696, 'SPA_11', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「無邊界的攀登者」。強大的成就欲望（15A）配合對自我改造的開放性（11A）。管理建議：適合作為組織內部的跨領域人才儲備。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3697, 'SPA_11', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「務實驗證後全力投入型」。面對新挑戰，他的信心與行動力都足夠，能把壓力轉成可處理的任務去推進；但他不會照單全收「這個能力一定練得起來」的說法，會先確認方向有沒有實際回饋。一旦看到小幅進展，他能把手上的動能與樂觀全部押上去加速投入，練習節奏明顯拉快。若遲遲看不到成效，他傾向先觀望而非硬撐。管理上可先給他一次小規模、能快速見效的練習機會，讓他把充沛的心理資源導向對的方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3698, 'SPA_11', 'B (中)', 'SPA_02', 'C', '與 SPA_02 (希望) 低分聯動：表現為「知道能變好卻缺路徑型」。他清楚某些能力可以透過努力提升，但很難把「可以變好」的信念轉成具體的步驟與里程碑，遇到卡關時容易停在原地，或臨時改走比較短線、見效快的做法。因為缺乏清楚路徑，他判斷「有沒有看到成效」時標準會飄動，有時練了一陣子卻說不清自己進步了沒有，投入度也跟著波動。給他一份明確的階段任務單，比只跟他說「你可以做到」更能讓他持續投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3699, 'SPA_11', 'B (中)', 'SPA_03', 'A', '與 SPA_03 (效能感) 高分聯動：表現為「篩選後才押注型」。他對於「哪些能力值得練、能練到什麼程度」抱持務實態度，不會每個改變建議都照單全收；但一旦他自己選定要投入的方向，就會展現出明確信心，敢承擔結果、持續投入，遇到困難也不容易退縮。這種篩選讓他的努力集中在少數幾個他判斷有機會的地方，而不是分散嘗試每一種可能。旁人若想推動他改變，先讓他看到這條路可行、值得，比直接要求他全面配合更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3700, 'SPA_11', 'B (中)', 'SPA_08', 'C', '與 SPA_08 (反饋尋求) 低分聯動：表現為「自估進度容易失準型」。他要看到成效才會加碼投入練習，但他很少主動去問別人自己到底進步了沒有，可能覺得沒必要或擔心被否定。於是他判斷「有沒有效」常常只靠自己觀察與猜測，容易錯過別人能給的修正訊號，一旦自估的進度不如預期，投入意願會悄悄下降，卻說不清真正原因。安排固定的檢核點主動把回饋送到他面前，會比等他自己開口更有效果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3701, 'SPA_11', 'B (中)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) 高分聯動：表現為「看得到贏面才練型」。他對勝負與能不能拿第一高度在意，傾向把要不要投入練習放進「這樣做能不能贏」的框架裡評估，而不是單純因為別人說能變好就去做。當某個方向被他判斷有機會贏過別人、主導局面，他會展現高度企圖去加碼練習；一旦看不出贏面，即使理論上能力可以提升，他的投入也會明顯降溫。把進步幅度轉成可比較、可看見名次的形式，通常比抽象地談成長更能拉住他的動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3702, 'SPA_11', 'B (中)', 'SPA_15', 'C', '與 SPA_15 (企圖心) 低分聯動：表現為「夠用就好不硬拼頂尖型」。他相信某些能力可以透過努力提升，也願意在看到成效後投入，但沒有非把自己推到極致不可的驅力，練到有感、夠用就容易停下來，比較看重生活其他部分的平衡。這代表他的成長曲線容易在中段趨緩，不是能力到頂，而是他覺得繼續拼下去的代價划不來。若想讓他再往上推一段，給出具體、看得到的下一步好處，會比要求他自我加碼更有用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3703, 'SPA_11', 'B (中)', 'SPA_04', 'A', '與 SPA_04 (韌性) 高分聯動：表現為「挫折復原快但重新投入仍看效益型」。練習過程中遇到卡關、失敗或目標落空，他能快速回穩、調整策略後重新上手，不容易被一次挫敗打亂節奏。但他決定要不要再投入下一輪練習，仍然回到務實的判斷——這條路是否顯示出效果、幅度與速度合不合理。他不會因為自己復原得快就無條件死守一個看不到成效的方法，而是把快速回穩的能力用在「換一個更值得的方向再試」。管理上可以放心讓他承擔失敗風險，但需要在關鍵節點協助他評估方向是否值得繼續。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3704, 'SPA_11', 'C (低)', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「認命的枯竭者」。心理資源匱乏（01C）且不相信現狀能改善（11C）。風險：極易陷入長期的職業倦怠，對任何激勵與變革都表現出防禦性的消極。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3705, 'SPA_11', 'C (低)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「頑強的守舊者」。能扛住壓力不崩潰（04A），但其應對方式僵化，拒絕透過改變自我來適應新環境（11C）。管理建議：需主管透過外部強制作為強制其踏出舒適圈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3706, 'SPA_11', 'C (低)', 'SPA_05', 'C', '與 SPA_05 (樂觀) C 聯動：表現為「宿命論的悲觀者」。認為未來是灰暗的（05C），且能力是天生的、不可改變的（11C）。警示：容易散播「努力無用論」，影響團隊士氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3707, 'SPA_11', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「刻板的職人」。高度遵守既定標準（07A），但對超越標準的新方法或技能轉型表現出極強的心理抗拒（11C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3708, 'SPA_11', 'C (低)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「防禦性的計算者」。因不相信未來可期（11C），故極度計較當下的得失與公平性（09C），缺乏為了長遠成長而暫時忍讓的格局。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3709, 'SPA_11', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的慣性者」。雖然行為匆忙、追求速度（13A），但其實只是在用舊有的方法加速運作，拒絕反思或調整核心策略（11C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3710, 'SPA_11', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「易爆的定型者」。當被要求改變或遭遇不順時，因認為自己「就是這樣」（11C），會引發強烈的情緒對抗或衝動反應（18A）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3711, 'SPA_12', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「無懈可擊的職業典範」。心理資源充足（01A）且極其在意專業形象（12A）。預測：這類人會努力展現出完美戰士的狀態，即便感到疲累也會隱藏，直到資源耗盡。警示：主管需主動偵測其「面具」下的真實負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3712, 'SPA_12', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「極具感染力的模範生」。高度投入工作（06A）且展現出符合組織期望的高能量狀態（12A）。行為預測：能有效帶動團隊士氣，因為他們不僅做得多，且「看起來」極度樂觀積極。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3713, 'SPA_12', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「謙遜的認可追求者」。主動要回饋（08A）的一部分目的是為了確認自己是否符合他人的「優秀標籤」（12A）。管理建議：其改進動機深受外部肯定驅動，應多給予正面回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3714, 'SPA_12', 'A (高)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「優雅的競速者」。具備 A 型性格的急促與競爭欲（13A），但會透過形象管理（12A）修飾其侵略性。風險：這種長期的「外圓內方」會帶來極大的心理內耗，易在私下爆發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3715, 'SPA_12', 'A (高)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「壓抑的火山」。天性情緒反應快（18A），但極力維持得體形象（12A）。行為預測：在公眾場合表現得體，但一旦在壓力點超過臨界值，會發生令人驚訝的斷裂式崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3716, 'SPA_12', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「多數誠實、關鍵時刻報喜的推進者」。日常匯報他多半照實說，卡關的地方會講出來；但一遇到敏感議題或想留下好印象的場合，他會把描述往理想化的方向修一點，讓進度聽起來比實際更順。他手上的心理資源相對充足，遇到挑戰能維持信心與行動力、把壓力轉成可處理的任務，所以就算描述有點修飾，後續執行力仍跟得上，落差不至於太大。管理上聽他報告時對敏感節點多問一句細節，其餘可信度仍高，不必逐項複查。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3717, 'SPA_12', 'B (中)', 'SPA_06', 'C', '與 SPA_06 (工作投入性) 低分聯動：表現為「選擇性修飾、投入起伏藏在話術裡的執行者」。他多數時候講真話，但碰到自己表現不如預期或想維持好印象的時刻，會把措辭調得比實際樂觀。他把工作視為一部分責任而非生活重心，投入度容易被外部要求牽著走，若某段時間動能明顯下滑，他不一定會主動講清楚，反而可能用「還在推進」這類含糊說法帶過。管理上遇到進度異常靜默時要主動追問具體卡點，別只憑他口頭回報判斷投入狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3718, 'SPA_12', 'B (中)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) 高分聯動：表現為「主動要回饋、但敏感點會先包裝再問的求進者」。他會主動找主管或同儕確認自己的表現與該改進的地方，把回饋當成加速成長的工具；但問法上，若牽涉到讓自己看起來不夠好的部分,他習慣先把狀況講得體面一點，再問「這樣是不是還可以更好」，而不是直接攤開問題本身。這種包裝不影響他願意調整的意願，只是讓給出回饋的人得多花一點力氣才能看清他實際卡在哪。管理上給回饋時可主動點出具體行為而非只回應他描述的版本，幫助校準更準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3719, 'SPA_12', 'B (中)', 'SPA_13', 'C', '與 SPA_13 (A型性格) 低分聯動：表現為「整體平和、偶爾為留面子而修飾的合作者」。他大多數時候如實表達,較不以競速與掌控作為主要驅動,重視合作與步調穩定,在高競爭環境也不容易被逼得亢奮。但在需要維持形象的場合,他仍會把自己的立場或表現講得比實際更順一些,尤其是牽涉個人責任的敏感話題。這種修飾不是出於好勝或掌控欲,單純是想被看得順眼一點。管理上這類人衝突風險低,只需留意他報告中「聽起來太順」的段落,多確認一次即可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3720, 'SPA_12', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「情緒一上來就藏不住、事後才補修飾的反應者」。他多數時候陳述算真實,但遇到敏感議題或想維持好印象時會偏理想化;不過他面對煩惱或挫折的當下容易衝動、情緒升溫快,可能出現急躁、語氣變硬或當場對抗,這種即時反應會先洩露出真實狀態,把原本想維持的形象打破。等情緒過去,他才會回頭把敘述修得體面一些。管理上與其看他事後的說法,不如留意他當下的第一反應,那才是更接近真實狀態的訊號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3721, 'SPA_12', 'B (中)', 'SPA_07', 'C', '與 SPA_07 (職業素養) 低分聯動：表現為「標準感鬆散、卻仍想把話說得體面的人」。他日常陳述多半真實,但遇到敏感話題或想留好印象時會偏理想化。同時他對流程與規範的敏感度較低,做事可能以完成為主而忽略一致性與細節,對外互動時風險較高;這種鬆散一旦被問起,他傾向把交代得不夠仔細的地方講得比實際更完整,而不是承認漏了什麼。聽的人容易被他這種說法帶著走,誤以為流程都有顧到,實際查核時才發現落差。管理上對他經手的對外事項宜實際抽查細節,不能只聽口頭確認。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3722, 'SPA_12', 'B (中)', 'SPA_09', 'A', '與 SPA_09 (權益公平感) 高分聯動：表現為「隱忍配合型的印象管理者」。他對付出與回報是否對等本來就不太計較，遇到分配不均或安排對自己不利時，他多半先忍讓下來，把焦點放回關係或任務本身，不急著爭取或表態。到了敏感議題，或他想留下好印象的場合，他會把表面說法修得比較理想化，用詞往聽者偏好的方向靠攏。因此他真實的不滿或保留意見不容易被看見，旁人常誤以為他真的沒有意見。管理上宜主動、私下確認他的實際想法，不要只憑他表面配合的樣子就判斷他沒有異議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3723, 'SPA_12', 'C (低)', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「透明的困境者」。心理資源不足（01C）時會直白展現其無助與疲憊（12C）。管理建議：這是最容易識別並提供支援的對象，其求救信號通常是真實且及時的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3724, 'SPA_12', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「求真務實的專才」。堅持標準（07A）並直接指出不合規之處（12C），不屑於為了職場政治而粉飾太平。預測：是組織中極佳的品質監察者或風險預警者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3725, 'SPA_12', 'C (低)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「直白的利益捍衛者」。對不公平敏感（09C）且會不加修飾地表達出來（12C）。警示：在資源分配衝突中，他們會是第一個發難的人，雖可能造成尷尬，但其反饋具有高度的環境真實性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3726, 'SPA_12', 'C (低)', 'SPA_11', 'C', '與 SPA_11 (可塑性) C 聯動：表現為「頑強的自保者」。不相信改變（11C）且不屑於假裝配合（12C）。管理建議：這類人的阻力是顯性的，需透過硬性的資源交換或清晰的因果邏輯來說服，而非情感動員。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3727, 'SPA_12', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「赤裸的競爭者」。渴望贏過他人（14A）且毫不掩飾這種勝負欲（12C）。預測：在競爭中極具侵略性，不計較社交和諧，是以結果為絕對導向的戰士。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3728, 'SPA_12', 'C (低)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「坦蕩的野心家」。不掩飾對權力與成就的渴望（15A, 12C）。管理建議：給予清晰的晉升路徑即可有效激勵，他們對虛偽的讚美不感興趣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3729, 'SPA_12', 'C (低)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「火爆的直腸子」。情緒反應快（18A）且從不修飾（12C）。行為預測：喜怒哀樂全寫在臉上，雖容易造成人際張力，但合作者能隨時知道其真實狀態，溝通透明度高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3730, 'SPA_13', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強悍的動力火車」。心理資源充沛（01A）支持其高競爭、快節奏的行為模式（13A）。預測：能承受極高強度的連軸轉工作，是組織在極端環境下搶占市佔率的核心力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3731, 'SPA_13', 'A (高)', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「易折斷的利刃」。進取心強且急躁（13A），但抗壓與復原力弱（04C）。警示：一旦進度受阻或遭遇突發打擊，這類人極易產生劇烈的挫折感甚至身心崩潰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3732, 'SPA_13', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「嚴苛的高效職人」。既追求極致速度（13A），又不允許品質打折（07A）。管理建議：其自我要求極高，但也容易將壓力轉嫁給下屬或同事，需關注其在團隊中的人際張力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3733, 'SPA_13', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「迫切的自我修正者」。為了贏得競爭（13A），會主動要回饋以求第一時間調整（08A）。其對回饋的需求帶有強烈的目的性與時效感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3734, 'SPA_13', 'A (高)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「永動型戰鬥員」。體力與精神能量（10A）完全匹配其快節奏的追求（13A）。行為預測：在第一線銷售或高頻率商務開發中，展現出驚人的產能與氣場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3735, 'SPA_13', 'A (高)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「極致的競技選手」。視所有任務為競賽（14A），且行動具備強烈的掌控欲與時效性（13A）。風險：可能因過度求勝而忽略團隊協作或合規細節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3736, 'SPA_13', 'A (高)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「易燃的進取者」。時間緊迫感強（13A）且情緒反應快（18A）。管理建議：在任務延誤或遭遇不配合時，極易爆發衝突。需建立明確的「降溫溝通規範」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3737, 'SPA_13', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「沉著推進的目標型」。他想贏、想把進度攥在自己手上，遇到能往前衝的機會會主動加快腳步、盯緊時程，多數討論仍維持在理性交換做法的層次，不急著壓過別人。計畫被卡住時，他確實會浮起一股不耐，但同時仍相信情況有辦法翻轉，手上動作是去盤點還有哪幾條路可以推，不會停在原地發火。連續碰壁時，他對能力沒有明顯的自我懷疑，情緒不容易整個垮下來，仍能維持基本的行動輸出；只有在資源持續卡死、進度看不到任何鬆動跡象時，他才會口氣變硬、態度轉為強勢主導，想直接跳過討論自己把事情推走。管理上，在需要撐長線韌性的任務裡可以放心把主導權交給他，在關鍵卡關點提供一次清楚的資源或方向確認，通常就能讓他重新回到穩定推進的節奏，而不是被拖進對抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3738, 'SPA_13', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「短跑型的目標推進者」。他很想掌握進度、把事情往前推，一般任務裡能維持在理性溝通、跟人配合的狀態，不會隨便把情緒攤出來。遇到單一次的受阻或被延誤，他多半還壓得住，先皺個眉、口氣稍微硬一點，就轉去想下一步怎麼推；但如果卡關的狀況一波接一波、時間又持續拖長，他的疲乏感會冒得比預期快，復原也需要更多時間才能拉回來。連續高壓一段時間後，他的表現容易忽高忽低——某幾天還能維持衝勁與條理，某幾天則明顯提不起勁、對進度落後特別敏感，語氣跟著變得急躁強硬。管理上宜在長週期任務裡替他安排明確的階段休整點，在連續受挫後給他一段緩衝時間再交付下一個高壓任務，讓他有機會把耗損補回來，而不是一路被推著跑到垮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3739, 'SPA_13', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「守品質的衝刺型」。他想把進度掌握在自己手上，遇到能加快的機會會主動催時程、盯緊交付，但對怎麼把東西做出來有清楚的標準，不會為了搶快隨便交差；代表團隊對外露面時，特別在意呈現出來的一致性與專業度。多數時候他能把急切收在合作的框架裡——一邊催效率，一邊仍照著該有的流程走，不會為了搶快而跳過該有的步驟。真的被卡住、時程又逼近時，他才會明顯急躁起來，語氣變快變硬，但即使在急的狀態下，他仍然緊盯著品質，不太會為了衝快而放低標準，反而會緊盯著時程、也緊盯著品質，兩邊都不肯放掉。管理上可以放心把對外代表性高、又需要效率的任務交給他，在他被多頭夾擊時提前給資源或人力支援，能讓他不用一個人扛時程壓力，維持住原本兼顧快與好的節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3740, 'SPA_13', 'B (中)', 'SPA_08', 'C', '與 SPA_08 (反饋尋求) 低分聯動：表現為「悶頭衝的目標型」。他想把進度和結果掌握在自己手上，設定好方向後就會加快腳步往前推，多數時候還能維持在理性溝通、跟人配合的狀態，不會隨便情緒化。他不太主動回頭問別人「這樣做對不對」——覺得自己已經看得夠清楚，或者不想在還沒做出成果前先被挑出問題，於是傾向悶頭把事情做完，再看結果說話。這種做法在方向抓對時能跑得很快，但一旦中途偏了，他往往要等到問題明顯浮現、進度被打回票，才會意識到早該先確認一下；看到時程已經被拖住的當下，他反而容易表現得更急躁、更想直接壓過去把事情推完，而不是先停下來檢討。管理上宜在關鍵節點主動幫他排進一次簡短的中途對焦，而不是等他自己開口，能讓他在偏離前就被拉回來，也少一點事後補救的急躁。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3741, 'SPA_13', 'B (中)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) 高分聯動：表現為「高速運轉的目標型」。他步調偏快、做事積極，想把進度掌握在自己手上，很自然會把事情一件接一件往前推，也容易帶著身邊的節奏一起加速。多數時候這股速度感是正面的——他能量夠、反應快，把催進度這件事做得很順，還能維持在理性溝通的範圍內，不會隨便把人壓過去。真的卡關、進度被硬生生擋下來時，他這股快節奏會轉個方向冒出來，從「積極推進」變成「明顯坐不住」，講話變快、動作變急，想立刻找到出口把事情重新推動起來。管理上可以放心讓他帶需要衝勁與速度的任務，但遇到必須等待的環節，宜提前跟他說明卡關的原因與預估時間，讓他有事可忙、有節奏可循，而不是空等到坐不住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3742, 'SPA_13', 'B (中)', 'SPA_14', 'C', '與 SPA_14 (競爭欲望) 低分聯動：表現為「重掌控、不爭排名的推進者」。他很在意進度跟結果是不是握在自己手上，遇到能往前衝的機會會主動加快腳步、盯緊時程，多數時候還能維持理性溝通，跟人一起把事情往前帶，不會隨便情緒化。但他對「贏過誰」「排第幾」這件事本身興致不高——比起壓倒性勝出，他更在意事情最後有沒有穩定做出來、關係有沒有維持住，就算某次表現不是最突出的那個，他也不會特別耿耿於懷。真的被卡住、時程又逼近時，他還是會明顯急躁起來，但這股急躁多半是衝著「進度沒推動」去的，不是衝著「輸給誰」去的——他很少把卡關解讀成排名上的威脅，反而更常直接去想怎麼把事情重新推起來。管理上可以放心讓他負責需要主導與掌控的任務，不必特別用排名或比較去刺激他，給清楚的進度指標跟推進空間，能讓他把急切收在解決問題上，而不是花力氣在爭輸贏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3743, 'SPA_13', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「平時穩、卡關瞬間變陣的推進者」。多數時候他把想贏、想掌控進度的驅力收在合作的框架裡，跟人討論、分派工作都還算理性，不會動不動就翻臉。一旦真的被卡住、時程又逼近，他心裡那股不耐會冒得很快——幾乎不用醞釀，當下就轉成臉色變、語氣變硬，講話速度也跟著加快。他容易當場就開口質問、要求立刻處理，語氣強硬、甚至講出事後會後悔的重話，而不是先緩一口氣、把話想清楚再說。事情過了以後，他多半能意識到剛剛反應有點大，但下一次遇到類似的卡關，同樣的模式還是容易很快重演。管理上宜在他被卡住的第一時間就先給明確的處理方向或時程調整，搶在情緒升溫之前把問題收斂掉，能讓他把力氣放回推進事情上，而不是耗在當場發火。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3744, 'SPA_13', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「沉穩的長期主義者」。具備心理資源（01A），但不急於表現或爭奪，傾向步調穩定的產出（13C）。預測：在需要耐心蹲點、深耕關係的業務中展現極強的穩定性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3745, 'SPA_13', 'C (低)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的佛系戰士」。能量充裕（10A）但節奏平穩、不追求競速（13C）。管理建議：適合需要長時間、重複性高品質輸出的崗位，能做到「高效而不急躁」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3746, 'SPA_13', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「溫和的職場公關」。行為不具備侵略性（13C），且高度在意社交形象（12A）。行為預測：是建立團隊和諧氛圍的理想人選，深受客戶與同事信賴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3747, 'SPA_13', 'C (低)', 'SPA_14', 'C', '與 SPA_14 (競爭欲望) C 聯動：表現為「協作導向的守位者」。不以贏過他人為榮（14C），且工作步調穩定不亢奮（13C）。適合環境：強調內部支援、技術研發或法務控管等非強競爭崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3748, 'SPA_13', 'C (低)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「從容的多面手」。雖然同時處理多項任務（16A），但內在不帶有競速的焦慮（13C）。預測：在混亂環境中能保持清醒，一件一件穩紮穩打完成。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3749, 'SPA_13', 'C (低)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致理性的穩重者」。不具備敵意特質（13C）且情緒極度穩定（18C）。管理建議：是組織中最理想的衝突調停者與高階後勤支持者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3750, 'SPA_14', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「強悍且穩定的競賽者」。具備足夠的心理資源（01A）支持其強烈的贏球慾望（14A）。預測：在激烈的業績排名戰中，能維持高昂鬥志且不容易因為暫時落後而產生心理挫折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3751, 'SPA_14', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「自信的進攻方」。既想贏（14A），也深信自己有贏的能力（03A）。管理建議：其主動性極高，適合承接對手強勁、需要「搶旗」的業務場景，是組織的突擊隊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3752, 'SPA_14', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「有風度的贏家」。追求領先（14A）但絕不以犧牲專業標準或品牌形象為代價（07A）。預測：能為組織爭取最高榮譽，且產出兼具競爭力與專業品質感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3753, 'SPA_14', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「戰術驅動的領先者」。為了確保贏過對手（14A），會極度主動地尋求反饋（08A）以找出敵我盲點。其回饋尋求帶有強烈的目的性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3754, 'SPA_14', 'A (高)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「對資源分配極度敏感的競爭者」。想贏（14A）且會緊盯自己與他人的回報對等性（09C）。風險：容易因為覺得公司分配不公而將競爭轉向內部摩擦，需明確其獎勵與付出的量化關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3755, 'SPA_14', 'A (高)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「侵略性極強的先行者」。競爭欲（14A）結合了急躁、掌控欲與敵意傾向（13A）。警示：雖能創造驚人戰績，但容易在團隊中造成「零和遊戲」的對立感，需注意人際張力管控。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3756, 'SPA_14', 'A (高)', 'SPA_15', 'A', '與 SPA_15 (企圖心) A 聯動：表現為「攀登權力巔峰的鬥士」。強大的晉升渴望（15A）與實戰中的勝負欲（14A）結合。管理建議：這類人是組織的核心幹部預備人選，應給予具備晉升誘因的戰鬥型職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3757, 'SPA_14', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「選戰而戰的穩健型」。碰到關鍵任務時他會認真想贏，也拿得出行動去爭；遇到日常性質的工作，他不會硬把每件事當競賽，能安心切進合作模式。心理資本充足撐著他，就算在關鍵場合爭輸了，也能很快把情緒收好、重新評估下一步，不會因為一次沒贏就自我懷疑。選擇合作而不出手爭，對他來說是判斷這場不需要打，不是沒本錢打。管理上可放心把有輸贏意味的任務交給他，他既敢出手也扛得住結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3758, 'SPA_14', 'B (中)', 'SPA_03', 'C', '與 SPA_03 (效能感) 低分聯動：表現為「想贏卻不敢確定的猶豫者」。遇到關鍵任務,他心裡會冒出想贏的念頭,但那份念頭和「相信自己做得到」是分開的兩件事——想爭歸想爭,真要啟動行動時常會猶豫,反覆確認自己是不是真有把握。碰到挫折或落後的訊號,他容易先縮手,把原本想拚一把的氣勢壓下去。合作性質的場合反而讓他鬆一口氣,不用獨自扛輸贏的壓力。管理上宜在他表現出想爭的訊號時,及時給具體肯定與資源,幫他把「想贏」接上「敢做」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3794, 'SPA_16', 'A (高)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「極速前進的戰鬥機」。多工、競速（16A）且帶有強烈的時間緊迫感與競爭欲（13A）。管理建議：其攻擊性與節奏感極強，但容易對慢節奏的同事展現敵意，需配置同樣高節奏的隊友。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3759, 'SPA_14', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「贏了也要站得住的品質型」。他在關鍵任務會想贏,但不是隨便贏一次就滿足,做事時仍維持高標準,不容許為了搶快而降低品質。遇到不算競賽的日常任務,他也不會因為沒有輸贏壓力就放鬆自我要求,規範與細節照樣顧到。爭取成果的過程裡他仍守著這份自律,不容易為了衝第一而犧牲該有的水準。管理上可信任他代表團隊出面爭取重要成果,他既有企圖心也顧得住專業形象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3760, 'SPA_14', 'B (中)', 'SPA_08', 'C', '與 SPA_08 (反饋尋求) 低分聯動：表現為「悶頭衝刺型競爭者」。他遇到關鍵任務時會先鎖定想贏的目標，接著埋頭把節奏拉快、自己判斷怎麼做最有機會領先，很少中途停下來找主管或同儕確認方向對不對。他傾向靠自己過去的經驗評估進度，覺得中途去問等於承認不確定或拖慢速度，因此即使方法出現偏差，也常要等到結果揭曉或被明確要求檢討時才會發現。管理上宜在他投入衝刺前先約定固定的檢核時間點，主動提供進度回饋而非等他開口，才能在他偏離路徑前及時拉回。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3761, 'SPA_14', 'B (中)', 'SPA_09', 'A', '與 SPA_09 (權益公平感) 高分聯動：表現為「為任務而爭、不計較公不公平的投入型」。他在關鍵任務會想贏,但這股好勝心很少牽扯到過程中資源分配對不對等——他想贏是因為在意任務本身或那份成就感,不太會去算自己是不是比別人多付出。遇到合作場合,這個特質更明顯,他不太計較誰做得多誰做得少,能把心力直接放在把事情做好上。管理上可放心讓他參與資源分配不那麼精確對等的競爭型任務,他不會因為過程有落差就卡住不前。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3762, 'SPA_14', 'B (中)', 'SPA_13', 'C', '與 SPA_13 (A型性格) 低分聯動：表現為「務實求勝、退場自然的競爭者」。他在需要爭取成果時能投入競爭，任務結束後又能退回合作位置，切換相對順暢。他不會把每個場合都當成比賽，只在真正關鍵的任務上才明顯想贏、想主導結果；平常步調偏穩，也不靠掌控局面或搶快來確立自己的位置。爭取成果的當下，他仍以完成任務為主要考量，較少出現急躁或對抗性的反應；一旦任務結束或情境轉為需要協作，他便自然回到重視合作、配合節奏的狀態，不會持續帶著競爭姿態。管理上可放心在關鍵任務交付明確目標讓他發揮企圖心，日常則不需刻意維持競爭氛圍，穩定、合作導向的環境對他同樣有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3763, 'SPA_14', 'B (中)', 'SPA_15', 'A', '與 SPA_15 (企圖心) 高分聯動：表現為「選定戰場就要贏得漂亮的加碼型」。他不會把每個情境都當競賽,但一旦判斷是關鍵任務,想贏的念頭會被企圖心往上拉,不只求贏過別人,還想把成果做到亮眼、自我加碼追求更高標準。在真正在意的場合,他會展現出明顯的衝勁,願意投入額外心力把事情做到最好。碰到判斷不值得全力投入的日常任務,他仍收得住,不會逼自己每件事都拚到底。管理上宜幫他辨識哪些任務真正值得他全力加碼,避免把有限的衝勁分散在不需要的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3764, 'SPA_14', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「淡泊名利的穩健派」。具備心理資源（01A）但對贏過他人不感興趣（14C），更看重自身的穩定與成長。預測：在團隊中扮演協作者與守成者角色，是極佳的穩定力量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3765, 'SPA_14', 'C (低)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「利他的勞模」。高度投入工作（06A）並非為了贏過誰，而是為了達成團隊使命或個人價值實現。其投入行為不具攻擊性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3766, 'SPA_14', 'C (低)', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「共好型的學習者」。相信努力能改變（11A），且願意分享自己的學習所得，不擔心被他人超越（14C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3767, 'SPA_14', 'C (低)', 'SPA_12', 'A', '與 SPA_12 (社會期望反應) A 聯動：表現為「溫和的團隊潤滑劑」。較少展現進取心與敵意（14C），且高度在意社交形象與和諧（12A）。適合環境：需要高度團隊協作、客戶經營與客服相關的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3768, 'SPA_14', 'C (低)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「忙碌但無害的支援者」。節奏雖快且處理多工（16A），但並非為了爭強好勝，而是為了維持流程運作（14C）。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3769, 'SPA_14', 'C (低)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致穩定的協作者」。既不想與人爭鋒（14C），情緒亦極其受控穩定（18C）。管理建議：是組織中最理想的資源分配者與後勤窗口，能客觀處理多方需求而不帶私利色彩。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3770, 'SPA_15', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「基石穩固的征服者」。強大的成功渴望（15A）配合充沛的心理資源（01A）。預測：在追求高難度目標時，不僅具備攻擊性，更能承受長期壓力而不崩潰，是高階管理者的核心特質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3771, 'SPA_15', 'A (高)', 'SPA_02', 'A', '與 SPA_02 (希望) A 聯動：表現為「具路徑感的野心家」。既想往上衝（15A），又能主動規劃出達成晉升的多條可行路徑（02A）。管理建議：應給予明確的晉升階梯，他們會自發性地找到方法達標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3772, 'SPA_15', 'A (高)', 'SPA_03', 'A', '與 SPA_03 (效能感) A 聯動：表現為「極致自信的拓荒者」。追求頂尖成功（15A）且深信自己具備勝任的能力（03A）。行為預測：會主動請纓承擔難度最高、曝光度最大的任務以累積戰功。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3773, 'SPA_15', 'A (高)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「使命必達的精英」。將工作視為獲取成就的唯一修煉場，展現出驚人的奉獻精神（06A, 15A）。其投入往往帶有高度的目的性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3774, 'SPA_15', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「追求專業權威的精英」。不僅想贏，更要以極高標準贏得漂亮（07A）。預測：其成就不僅體現在數據，更體現在建立行業影響力與品牌標竿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3775, 'SPA_15', 'A (高)', 'SPA_11', 'A', '與 SPA_11 (可塑性) A 聯動：表現為「無極限的進化者」。為了攀登更高職位（15A），極度願意學習新知識與改變舊習（11A）。管理建議：是組織進行跨領域輪調、培養接班人的首選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3776, 'SPA_15', 'A (高)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「侵略性的競技者」。渴望成功（15A）且必須透過擊敗對手來證明（14A）。風險：在內部合作中可能過於強勢，需建立良好的「共贏制度」來引導其能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3777, 'SPA_15', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「有底氣的看勢加速者」。他想把事情做得更好，但真正卯起來衝刺前，會先評估手上的資源、回饋跟勝算；不過就算一時看不到明確訊號，他仍能靠著底子撐住信心、維持行動力，不至於卡在原地。遇到挑戰或壓力升高時，他能把壓力拆成可以動手處理的任務，一邊觀察情勢一邊繼續往前推。等真正看見成效或轉機，他的投入強度會明顯拉高、加速衝刺。管理上可放心讓他自行判讀情勢，只需適時提供進度回饋，就能讓他的企圖心穩定轉成行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3778, 'SPA_15', 'B (中)', 'SPA_02', 'C', '與 SPA_02 (希望) 低分聯動：表現為「有心衝刺卻抓不到路徑的推進者」。他對變好這件事是真心在意的，看到資源到位或有明確回饋時會想加把勁往前衝；但要把「想更好」轉成具體的路徑跟步驟，對他來說並不容易，常常空有動力卻不知道下一步該怎麼拆解。一旦卡關，他容易停在原地打轉，或是臨時改走比較快但不見得扎實的捷徑，衝勁也跟著鬆掉。等環境把路徑鋪清楚、或收到明確的回饋訊號，他又會重新拉高投入。管理上宜替他先把目標拆成具體步驟、定期給進度回饋，才能穩住他的衝刺節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3779, 'SPA_15', 'B (中)', 'SPA_03', 'A', '與 SPA_03 (效能感) 高分聯動：表現為「先算勝算、再全力壓上的信心衝刺者」。他不會不看情況就悶頭衝，通常會先評估資源夠不夠、回饋明不明確、勝算高不高，再決定要投入多少力氣；但只要判斷值得做，他對自己能靠努力做到會有明確的信心，也敢把結果扛下來、持續投入。遇到困難時，他不容易輕易退縮，反而會把挫折當成調整做法的訊號，繼續往前推。一旦看到成效浮現，他的投入強度會明顯拉高，把資源優先押在有機會成功的方向。管理上可以放手讓他自己判斷投入時機，並在關鍵階段給予清楚的成效回饋，讓他的衝勁有依據可以加碼。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3780, 'SPA_15', 'B (中)', 'SPA_06', 'C', '與 SPA_06 (工作投入性) 低分聯動：表現為「看到訊號才加碼的有限投入者」。他對把事情做好有真實在意，也會依資源、回饋跟勝算來調整要投入多少力氣；但平常他把工作看成職責的一部分，不會把全副心力都押在上面，投入程度比較跟著外部要求走。若沒有明確的成效訊號或要求出現，他不太會自己主動加碼，也較少花長時間耕耘一件事到底。一旦看到具體成效或收到清楚的回饋，他會明顯拉高投入、把力氣集中衝一段時間，但熱度不一定能自己延續下去。管理上宜提供明確的階段性目標與即時回饋，才能讓他的企圖心持續有燃料可燒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3781, 'SPA_15', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「守著品質底線再衝刺的專業型推進者」。他做事會先守住規範跟專業品質這條線，不只求達標，也在意做得比基本要求更好；至於要不要進一步加碼衝刺，則要看資源、回饋跟勝算而定。在對外代表工作成果或跟外部接觸時，他特別在意形象與一致性，即使投入強度正處在觀望階段，品質也不會因此打折。等看到明確成效或有把握拿下結果，他會把專業標準跟衝勁一起往上拉，用更高規格去完成。管理上可以透過清楚的品質標準搭配進度回饋，讓他在守住底線的同時願意持續加碼。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3782, 'SPA_15', 'B (中)', 'SPA_11', 'C', '與 SPA_11 (可塑性) 低分聯動：表現為「看得到效果才願意改的務實衝刺者」。他想把表現往上推，但要不要真的加碼投入，得先看資源、回饋跟勝算夠不夠明確；同時他比較傾向認為能力跟特質是相對固定的，面對要求他改變做法時，容易先觀望甚至覺得改了也沒用。一旦嘗試後遇到挫折，他的學習投入度會明顯受影響，衝勁也跟著降溫，比較不會主動再去嘗試新方法。但只要能親眼看到具體成效、證明改變真的有用，他的投入強度會明顯拉高，願意繼續往那個方向推進。管理上宜用小規模的成效證明來說服他，並在他嘗試後及時給回饋，減少挫折對投入度的拖累。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3783, 'SPA_15', 'B (中)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) 高分聯動：表現為「盯著勝算等訊號出手的求勝衝刺者」。他對勝負與是否能拿第一高度在意，容易把手上的任務當成一場要贏的競賽，也很想主導局面；但真正卯足全力衝刺前，他會先評估資源夠不夠、回饋清不清楚、勝算高不高。一旦判斷有機會贏、或看到具體成效浮現，他的投入強度會明顯拉高，把心力集中在能拿下結果的方向上全力推進。若情勢還不明朗或看不到勝算，他的衝勁會先收著，寧可觀望也不貿然全押。管理上可以適時揭露局勢中的具體訊號與階段性戰果，讓他的求勝欲望有明確的依據可以轉成持續投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3784, 'SPA_15', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「精神富足的穩定者」。具備心理韌性與能量（01A），但對於權力或職位晉升缺乏強烈興趣（15C）。預測：在穩定崗位中表現極佳，是團隊中的「壓艙石」，不會因未獲提拔而抱怨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3785, 'SPA_15', 'C (低)', 'SPA_04', 'C', '與 SPA_15 (企圖心) C 聯動：表現為「安於現狀的自保者」。缺乏動力攀升（15C）且抗壓韌性低（04C）。管理建議：應配置於變動極小、無需主動開發的環境中，以發揮其守成功能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3786, 'SPA_15', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「純粹的職人」。對晉升沒興趣（15C），但對專業標準有極高執著（07A）。行為預測：會把現有工作做到極致，是技術、品質或內控領域的「隱形冠軍」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3787, 'SPA_15', 'C (低)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的執行員」。活力充沛、做事積極（10A），但缺乏成為領袖或追求社會地位的野心（15C）。管理建議：適合需要高度體力、重複性高能產出的職務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3788, 'SPA_15', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「急躁的守位者」。雖然行為步調快且具緊迫感（13A），但動機並非追求更高的職位（15C），而是源於對現狀的掌控欲。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3789, 'SPA_15', 'C (低)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「淡泊的智者」。不追求功名（15C）且情緒極其穩定冷靜（18C）。適合角色：內控、審核、或任何需要高度客觀且不受利益引誘的崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3790, 'SPA_16', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「全能的高速引擎」。具備充足心理資源（01A）來支撐多線並行的心理負荷（16A）。預測：能同時處理多個高壓專案且維持積極態度，是組織在業績衝刺期或多角化經營時的核心戰力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3791, 'SPA_16', 'A (高)', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「高速行駛的易碎者」。步調極快且多工（16A），但心理復原力與抗壓性不足（04C）。風險：極度容易發生身心燃盡（Burnout），一旦其中一項任務崩潰，會引發連鎖性的挫折感與失能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3792, 'SPA_16', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「具備高品質的競速者」。追求速度（16A）的同時，對專業標準有極高執著（07A）。警示：這類人常處於高度自我焦慮中，因其在「快」與「好」之間不斷拉扯，需適時提醒其資源分配的輕重緩急。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3793, 'SPA_16', 'A (高)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的現場指揮官」。生理動能充足（10A）完全匹配其多工需求（16A）。行為預測：在動態環境中具備極強的反應力與覆蓋面，能同時推進多個客戶關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3795, 'SPA_16', 'A (高)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「與時間賽跑的焦慮者」。因同時處理多項事務（16A），加上對時間極度敏感（17A），常處於緊繃與催促狀態。預測：雖然出件極快，但需嚴格複核其收尾細節，預防粗心導致的錯誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3796, 'SPA_16', 'A (高)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「忙碌中的火藥桶」。多工帶來的心理負荷（16A）一旦遇到延誤，會迅速轉化為情緒爆發（18A）。風險：容易在忙碌中失言或做出衝動決定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3797, 'SPA_16', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「帶著底氣趕工的多工者」。手上事一多，他會先評估哪些能並行、哪些得排隊，工具跟情境到位時能把好幾條線同時往前推，品質也守得住。碰到連續卡關或某條線卡住，他不太會慌，多半先穩住信心、重新盤點任務再繼續切換，不會因為一時受阻就整個節奏亂掉。真的忙到極限、資訊又不夠明確時，切換會變得零散，收尾容易被擠壓、細節跟著漏。管理上宜給清楚的任務框架與工具支援，讓他忙而不亂，也持續給正向回饋維持他推進的信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3798, 'SPA_16', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「越忙越耗的多工者」。任務明確、資源到位時，他能同時處理好幾件事並守住品質，願意接下多工的安排。一旦進入連續高壓或長時間不確定，先垮下來的常常是恢復力：疲乏感會累積得比平常快，切換任務時的判斷跟著變得遲鈍、容易漏掉該收尾的細節。這種狀態下要他再開一條新線，他會明顯拖延或反應變慢，需要先緩一口氣才回得去原本的效率。管理上宜留意他連續多工的時長，適時抽掉幾條線、給喘息空間，等狀態回穩再逐步加回任務量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3799, 'SPA_16', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「有底線的多工執行者」。他習慣同時開好幾條線往前推，但對外交付的品質有一條不願意退讓的底線，即使趕工也會把該有的規範跟形象顧到。任務明確、支援足夠時，他能維持又快又不失準的表現，甚至主動把某些環節做得比要求更完整。真的忙到滿載，他會優先犧牲效率也要保住那條品質底線，寧可放慢某條線、也不讓交付變得粗糙。管理上可放心把對外或高規格任務交給他，但要留意過度堆疊多工時他可能為了守品質而拖慢整體速度，需協助排出優先序。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3800, 'SPA_16', 'B (中)', 'SPA_10', 'C', '與 SPA_10 (精力充沛) 低分聯動：表現為「被多工推著走的穩步者」。任務明確、工具支援足夠時，他能把幾件事同時推進並守住品質，但骨子裡更習慣一件一件按部就班做完。同時開多條線一陣子後，他容易感到被推著走、耗損感偏快出現，切換的速度跟著慢下來，不像天生快節奏的人能一直保持高速並行。高多工又持續拉長的情境下，他傾向主動收斂，把手上任務排出先後、一次專心處理一小段，藉此換回節奏感與品質。管理上宜控制同時交辦的任務條數，給他能按序推進的空間，避免長時間高頻切換造成耗竭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3801, 'SPA_16', 'B (中)', 'SPA_13', 'A', '與 SPA_13 (A型性格) 高分聯動：表現為「搶進度的多工衝刺者」。任務清楚、節奏對得上時，他會同時抓好幾件事往前衝，重視掌控進度與效率，切換之間也想守住成果。手上事一多又碰上時間被卡住，他容易被競爭感跟時間感一起推著走，動作變得更急，對拖慢他速度的人事物耐性明顯下降，語氣也可能變得直接甚至帶點火氣。多線推進到一定壓力後，他寧可犧牲一點細節收尾也要維持整體進度不掉速，不太願意主動放慢。管理上宜提前排定優先序、減少臨時插件，並在他明顯急躁時適時介入緩衝，避免衝過頭犧牲品質或關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3802, 'SPA_16', 'B (中)', 'SPA_17', 'C', '與 SPA_17 (時間壓力) 低分聯動：表現為「看情境調速的多工者」。多工是他的能力而非常態焦慮，任務明確時他能同時處理好幾件事，但不太會覺得時間在追著他跑，步調偏穩、少有催促感。條件差、事情堆疊又缺乏清楚框架時，他仍會意識到需要收斂，但不會像天生時間敏感的人那樣立刻進入緊迫狀態，反應速度相對慢半拍。這種偏穩的步調在快節奏團隊裡有時會被誤讀成不夠急，即使他手上其實同時扛著好幾條線。管理上宜明確標示真正的優先順序與期限，避免只靠他自己感受急迫程度，才能讓他的多工能力在對的時間點被用上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3803, 'SPA_16', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「壓力下易上火的多工者」。任務明確、節奏可控時，他能同時處理多件事並維持品質，切換之間也算冷靜。一旦多線同時卡住、又碰上被打斷或進度被質疑，他的情緒容易先升溫，可能出現語氣變硬、當場反駁或急躁的反應，收尾品質也跟著受影響。等火氣過去，他多半能回頭把混亂的任務重新理出頭緒、修正剛才衝動下沒顧到的細節。管理上宜在多工又高壓的時段留意他的情緒訊號，給予短暫緩衝或介入降溫，避免情緒化的當下決定影響交付品質或人際關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3804, 'SPA_16', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「穩定且深耕的職人」。心理資源穩定（01A），傾向於一次處理好一件事（16C）。預測：在需要長期經營、複雜邏輯或高品質打磨的任務中，能展現出極高的可信度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3805, 'SPA_16', 'C (低)', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「步步為營的遲疑者」。因信心不足（03C），故更依賴一次專注一件事（16C）來累積掌控感。管理建議：應避免將其置於多變、零散的工作環境，否則會因無法兼顧而產生嚴重的失能感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3806, 'SPA_16', 'C (低)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不屈的慢跑者」。雖不追求多工並行（16C），但面對壓力極具韌性（04A）。行為預測：適合處理具有長期挑戰、需要耐心與持續磨合的難搞專案，雖然慢，但絕不放棄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3807, 'SPA_16', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「注重細節的匠人」。堅持標準（07A）高於速度，偏好專注完成高品質作品（16C）。管理建議：適合品質控管、法務審查或精密數據分析等低容錯率崗位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3808, 'SPA_16', 'C (低)', 'SPA_13', 'C', '與 SPA_13 (A型性格) C 聯動：表現為「平衡感極佳的協作者」。不急躁、不競速（13C, 16C），更重視合作與步調穩健。適合環境：強調團隊和諧與長線口碑經營的組織環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3809, 'SPA_16', 'C (低)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致穩定的協調者」。節奏穩定（16C）且情緒極其理性冷靜（18C）。管理建議：在混亂的衝突現場，他是理順流程、穩定軍心的最佳協調人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3810, 'SPA_17', 'A (高)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「抗壓的短跑健將」。具備充足心理資源（01A）來緩衝高時間壓力（17A）。預測：能在極短期限內爆發高產能，且心理狀態不會崩潰，是處理緊急專案與危機公關的最佳人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3811, 'SPA_17', 'A (高)', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「焦慮的溺水者」。時間敏感度高（17A）但心理復原力弱（04C）。風險：在截止日期臨近時，極易因為壓力過載而產生生理性不適或判斷力癱瘓，需主管介入協助任務拆解。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3812, 'SPA_17', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「追求極致的快槍手」。要在時限內（17A）交出超越標準的作品（07A）。警示：這類人常處於「自我壓榨」狀態，雖然產出優質，但長期身心損耗極大，需注意過勞風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3813, 'SPA_17', 'A (高)', 'SPA_10', 'A', '與 SPA_10 (精力充沛) A 聯動：表現為「高能的競速者」。生理動能十足（10A）配合強烈的時間緊迫感（17A）。行為預測：在第一線銷售開發中，其開發頻率與結案速度會顯著高於平均，適合節奏極快的環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3814, 'SPA_17', 'A (高)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「分秒必爭的戰士」。時間緊迫（17A）與競爭欲（13A）高度重合。管理建議：其效率驚人，但對「延誤」容忍度極低。需防範其因他人速度跟不上而引發的職場衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3815, 'SPA_17', 'A (高)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「高效但混亂的處理器」。同時做很多事（16A）且急於完成（17A）。風險：容易在追求速度的過程中發生細節失誤或「欲速則不達」，需配置行政輔助進行收尾查核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3816, 'SPA_17', 'A (高)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) A 聯動：表現為「壓力下的火藥桶」。時間緊迫（17A）且情緒易衝動（18A）。預測：在截止日當天最容易對同事發火，情緒波動與任務時程呈強烈正相關。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3817, 'SPA_17', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「有底氣的趕路人」。他做事一路帶著「時間在跑」的感覺，交付期接近或手上工作一多時，會明顯感到緊迫、盯著進度表看。同時他心裡的資源相對充足：遇到卡關仍相信自己能找到辦法，一次沒趕上進度不會就此洩氣，很快能重新盤點手上還有哪些選項。資源到位、目標明確時，他能把這股緊迫感收成穩定的推進節奏，一項項往前清；但遇到連續受挫，他仍會出現催促、坐立不安的反應，只是恢復速度比較快。管理上宜讓他掌握足夠的資訊與資源，讓他把時間壓力轉成具體的行動清單，而不是單純的情緒緊繃。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3818, 'SPA_17', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「耗損提早浮現的趕路人」。他做事習慣性帶著時間在追的感覺，重要任務逼近時會明顯繃緊、催自己也催進度。同時他的復原力偏薄：一旦壓力連續不斷，他容易先出現疲乏與挫折感，情緒和產出開始跟著波動，要花比較久的時間才回穩。規劃清楚、階段性任務能拆得開時，他還能維持節奏往前推；但遇到狀況一路拖著不解決，他的耗損會先浮現，反而拖慢原本想搶快的進度。管理上宜替他拆解任務、設置中繼點，讓他有機會在壓力拉長前先喘一口氣、重新校準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3819, 'SPA_17', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「守住標準的趕路人」。他做事帶著明顯的急迫感，交付期近或事情一多，會不自覺加快步調、盯緊時程，對拖延特別沒耐心。同時他對品質與規範的要求沒有因此放鬆：即使趕，他仍傾向照標準把事情做到位，對外代表出去的東西尤其在意一致性與形象，不會為了搶快隨便交差。規劃清楚、資源到位時，他能一邊維持準時交付、一邊守住原本的專業標準，把工作收得又快又整齊；但若時間被壓縮到極限，他容易在最後關頭出現焦躁，甚至得回頭補救品質上的疏漏。管理上宜提前給他清楚的時程與資源，讓他不必在最後關頭被迫在速度與品質之間做取捨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3820, 'SPA_17', 'B (中)', 'SPA_10', 'C', '與 SPA_10 (精力充沛) 低分聯動：表現為「心裡趕、腳步穩的人」。他心裡常有時間在跑的感覺，交付期近時會明顯感到緊迫、對拖延沒什麼耐心。但他做事的節奏本身偏穩、不追求快：習慣按部就班一步步來，不會因為心裡急就自動加快手上動作的速度。任務拆解清楚、步驟明確時，他還能在自己熟悉的節奏裡把事情穩穩做完，不至於因急迫感亂了套；但遇到高節奏、需要立即反應的場合，他容易感覺被推著走、動作跟不上心裡想要的速度，顯得比旁人更焦躁卻不一定更快。管理上宜給他相對充裕的執行時間，或把急件拆成他熟悉的步驟，讓他不必被迫用不適應的節奏應戰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3821, 'SPA_17', 'B (中)', 'SPA_13', 'A', '與 SPA_13 (A型性格) 高分聯動：表現為「分秒必爭的掌控者」。他對時間特別敏感，總覺得在跟時程賽跑，行程一有延誤就坐立難安、忍不住催進度。同時他做事也明顯進取好強：重視效率與掌控，喜歡把事情往前推、想比別人快、比別人好，這種驅動力在時間緊迫或有輸贏可比的場合特別明顯。規劃清楚、節奏在他掌控之中時，他能一邊維持高速推進、一邊還保有原本的水準，產出快也扎實；但一旦時程被打亂、進度落後預期，他容易變得又急又衝，語氣變硬，對造成延誤的狀況明顯失去耐性。管理上宜讓他有明確的時程主導權與可見的進度指標，避免在他已經緊繃時再臨時打亂順序。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3822, 'SPA_17', 'B (中)', 'SPA_16', 'C', '與 SPA_16 (匆忙/多工性) 低分聯動：表現為「趕時間仍一次一件的人」。他心裡常有時間緊迫感，重要交付近了會明顯繃緊，對事情一拖再拖特別沒耐心。但他做事的方式偏好專注：習慣一次處理好一件事再切換到下一件，不太喜歡同時開很多攤子，就算心裡急，手上動作仍傾向按順序來。任務能排出先後順序、一件一件交付時，他能把急迫感轉成專心趕工的動力，品質跟速度都能維持；但遇到需要不斷切換的場合，他容易感覺被打亂節奏，效率和情緒都跟著往下掉，比別人更明顯地喘不過氣。管理上宜替他把工作排序、一次交付一項任務，讓他的急迫感有機會轉成專注推進，而不是被迫同時應付多頭馬車。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3823, 'SPA_17', 'B (中)', 'SPA_18', 'A', '與 SPA_18 (情緒反應) 高分聯動：表現為「被逼到臨界就上火的急性子」。他對時間特別敏感，覺得自己一直在跟時程賽跑，只要進度被拖延就會明顯不耐煩、忍不住催促。同時他面對煩躁或挫折時反應也快：情緒容易升溫，可能當場語氣變硬、直接表達不滿，甚至做出比較衝動、代價較高的回應。規劃清楚、節奏掌握得住時，他還能把急迫感控制在催促、緊盯進度的範圍內；但遇到接連的延誤或挫折，他容易情緒瞬間升高，當場對造成延誤的狀況發火或硬碰硬。管理上宜提前預告時程變動、給他消化的空間，讓他在情緒升溫前有機會先被告知、先做準備。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3824, 'SPA_17', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「從容的指揮官」。心理底蘊深厚（01A）且不受時間左右（17C）。預測：在混亂與延誤中仍能保持優雅節奏，是建立長期、穩定、高品質客戶關係的理想人選。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3825, 'SPA_17', 'C (低)', 'SPA_06', 'A', '與 SPA_06 (工作投入性) A 聯動：表現為「沉浸式的職人」。高度投入（06A）且不被時間壓力干擾（17C），容易進入「心流」狀態。管理建議：適合負責需要深度思考、策略研究或長線耕耘的任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3826, 'SPA_17', 'C (低)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「慢工出細活的專家」。堅持標準（07A）重於速度，對他們而言，「做對」比「做快」更重要（17C）。適合角色：法務、風控、精密技術研發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3827, 'SPA_17', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「冷靜的競爭者」。渴望贏（13A）但行動不帶有時間焦慮（17C）。行為預測：這類人像冷血殺手，會精確計算時機再出手，而非盲目衝刺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3828, 'SPA_17', 'C (低)', 'SPA_16', 'A', '與 SPA_16 (匆忙/多工性) A 聯動：表現為「穩健的多面手」。能處理多項任務（16A）但步調極穩（17C）。預測：雖然多線進行，但產出節奏極度可信，不會因為趕工而犧牲任何一線的品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3829, 'SPA_17', 'C (低)', 'SPA_18', 'C', '與 SPA_18 (情緒反應) C 聯動：表現為「極致穩定的防線」。不被時間催促（17C）且情緒極受控（18C）。管理建議：是組織中最理想的緊急應變協調人，能在眾人焦慮時提供冷靜的決策支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3830, 'SPA_18', 'A (高)', 'SPA_01', 'C', '與 SPA_01 (心理資本) C 聯動：表現為「脆弱的易燃物」。心理資源匱乏（01C）使其對負面訊號毫無緩衝力，受挫時會迅速爆發（18A）。預測：在業績不佳或被拒絕時，容易出現情緒崩潰或遷怒他人的行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3831, 'SPA_18', 'A (高)', 'SPA_04', 'C', '與 SPA_04 (韌性) C 聯動：表現為「情緒復原慢的引爆點」。受挫時反應劇烈（18A），且因為韌性差（04C），情緒升溫後極難降溫，會長時間受困於負面心境中。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3832, 'SPA_18', 'A (高)', 'SPA_07', 'A', '與 SPA_07 (職業素養) A 聯動：表現為「追求專業的焦慮者」。雖然重視標準與形象（07A），但因天性衝動（18A），在流程出錯或他人不合規範時會立即展現嚴厲、語氣僵硬的對抗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3833, 'SPA_18', 'A (高)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「反應激烈的受教者」。雖主動要回饋（08A），但聽到批評的瞬間仍會反射性地防禦或情緒激動（18A）。管理建議：反饋應分段進行，並給予情緒冷卻期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3834, 'SPA_18', 'A (高)', 'SPA_09', 'C', '與 SPA_09 (權益公平感) C 聯動：表現為「公平的正義使者（火爆型）」。對不公極度敏感（09C）且會立即、大聲地表達不滿（18A）。風險：極易在資源分配不均時引發公開的衝突或集體抗議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3835, 'SPA_18', 'A (高)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「最具侵略性的戰將」。追求速度、掌控（13A）且伴隨易激發的敵意（18A）。警示：這是人際張力最高組合，雖能衝刺目標，但極度破壞團隊和諧。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3836, 'SPA_18', 'A (高)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) A 聯動：表現為「期限前的炸彈」。隨時間緊迫（17A），情緒升溫極快（18A），常因趕工對同事展現出極度不耐與急躁。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3837, 'SPA_18', 'B (中)', 'SPA_01', 'A', '與 SPA_01 (心理資本) 高分聯動：表現為「情緒起伏快但底氣足的回穩型」。在被否定、受委屈或連續受挫的時刻，他的情緒會明顯升溫，語氣變得比平常直接、動作也顯得急促。同一時間他心裡對目標的希望感、對自己能力的信心和對局面轉好的預期都還在，激動過後很快能把注意力拉回任務，把當下的挫折重新拆成可以動手處理的下一步。連續遭遇挑戰時，他不會停在低潮太久，通常能自己找到重新出發的施力點。管理上宜在他情緒正高的當下先給緩衝、少當場硬碰硬，等他自行回穩後再一起確認任務怎麼往下走，讓他的信心與行動力有機會接手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3838, 'SPA_18', 'B (中)', 'SPA_04', 'C', '與 SPA_04 (韌性) 低分聯動：表現為「單次能回穩、連續高壓下容易透支的類型」。被單一一次否定或誤解刺激時，他的情緒會升高、話說得比較衝，但事後多半能自己消化、把姿態調回來。不過一旦壓力拉長、挫折一件接一件，他的耐受力會明顯往下掉，疲乏感與挫折感堆積得比別人快，要花更長時間才能把狀態拉回正常水準。這段期間他的表現起伏會變大，某些時候還能維持水準，某些時候又明顯掉下去，難以預期。管理上宜留意連續壓力的累積量，適時安插喘息點與階段性收尾，避免長時間不間斷的高壓把他的回穩速度整個拖慢。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3839, 'SPA_18', 'B (中)', 'SPA_07', 'A', '與 SPA_07 (職業素養) 高分聯動：表現為「當下會被激起、事後迅速拉回專業水準的類型」。遇到被誤解或連續受挫的場面，他的情緒仍會明顯升高，說話可能比平常直接，態度也顯得緊繃。同一時間他對自己該維持的專業水準要求很高，尤其在對外代表場合特別在意一致性與形象，把一時的激動當成需要立刻修正的例外情況。激動過後，他很快會主動把互動修回原本該有的水準，補一句說明或調整語氣，將場面拉回專業範圍內。管理上可在他情緒正高的當下先給一點緩衝空間，等他自行收回節奏，通常不需要外部提醒他也會自己校正回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3840, 'SPA_18', 'B (中)', 'SPA_08', 'C', '與 SPA_08 (反饋尋求) 低分聯動：表現為「事後能自行降溫、卻不太回頭確認的類型」。在被否定或連續受挫後，他的情緒會明顯上升、語氣變得直接，但通常過一段時間就能自己冷靜下來，把姿態調回平常樣子。不過調回平常之後，他很少主動回頭問別人剛才那段互動造成什麼影響，也較少去確認自己需不需要調整做法，多半覺得沒必要特地重提，也不想再把自己攤開來被評價。一些原本可以趁機修正的細節，就這樣被跳過、沒有真正處理掉。管理上宜在他情緒回穩後主動找個時間簡短同步一下當時的狀況，而不是等他自己開口，才不會錯過修正的窗口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3841, 'SPA_18', 'B (中)', 'SPA_09', 'A', '與 SPA_09 (權益公平感) 高分聯動：表現為「在意當下被怎麼對待、卻不計較長期付出回報的類型」。當場被誤解、被指責得不合理，或是連續碰壁時，他的情緒還是會明顯上揚，反應比平常直接。但如果把時間拉長來看資源分配或付出跟回報是否對等，他其實不太計較，也不太會拿這個當標準去衡量該不該繼續投入，比較在意的是這段關係還在不在、這件事本身值不值得做。就算某段時期分到的資源或肯定比別人少，只要關係與任務本身還算合理，他多半能接受，怨氣不太會累積下來。管理上可以放心讓他承擔一些短期不對等的安排，但當下互動中若讓他覺得被冤枉或誤解，還是需要即時澄清，避免情緒當場升高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3842, 'SPA_18', 'B (中)', 'SPA_13', 'C', '與 SPA_13 (A型性格) 低分聯動：表現為「步調穩、不愛競速，被冤枉時仍會情緒升高的類型」。他平常不太需要靠競爭或掌控局面來獲得動力，比較偏好穩定的步調和跟人一起把事情做完，就算身處競爭激烈的場合，也不太容易被那種求勝的亢奮感帶著走。一旦被誤解、被不合理指責，或是接連碰上失敗，他的情緒仍會明顯升高，語氣變得比平常直接。這種激動跟輸贏或搶快沒什麼關係，比較像是被冤枉或被誤會的當下反應，事情釐清、姿態調回來之後，他很快又會回到原本平穩的步調。管理上不需要用競爭或急迫感去驅動他，反而要留意當下有沒有誤會或不公平的對待，先把這類狀況處理掉，他自然能維持穩定輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3843, 'SPA_18', 'B (中)', 'SPA_17', 'A', '與 SPA_17 (時間壓力) 高分聯動：表現為「追時程追得緊、又會被誤解或連續受挫激起情緒的類型」。他常覺得時間不夠用，做事像在跟時程賽跑，對進度延誤特別敏感，看到事情卡住或有人拖慢容易催促、語氣也顯得急。身邊一起共事的人，也容易被他的節奏帶得跟著繃緊。在被否定、受委屈或被誤解的當下，他的反應也會明顯上升，說話比平常直接、動作變得更急促，事後多半能自己收回節奏、把姿態調回來。管理上，進度掌握清楚、延誤提早告知，能降低他對時程的焦躁；互動中若出現誤會，也建議儘早澄清，讓他不必帶著情緒繼續往下推。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3844, 'SPA_18', 'C (低)', 'SPA_01', 'A', '與 SPA_01 (心理資本) A 聯動：表現為「深不可測的守護者」。強大的心理底蘊（01A）配合極高的情緒門檻（18C）。預測：即便在重大危機中也能面不改色地調度資源，是組織中最強的決策壓艙石。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3845, 'SPA_18', 'C (低)', 'SPA_03', 'C', '與 SPA_03 (效能感) C 聯動：表現為「沉默的自我懷疑者」。雖對自己沒信心（03C），但受挫時情緒亦不會劇烈起伏，傾向於安靜地縮手。管理建議：需主管主動探詢，因為其負面情緒極其隱蔽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3846, 'SPA_18', 'C (低)', 'SPA_04', 'A', '與 SPA_04 (韌性) A 聯動：表現為「不動如山的長跑者」。遭遇打擊時能理性分析（18C）並快速重回戰場（04A）。行為預測：在長期、高頻被拒絕的業務中表現最為堅韌、穩定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3847, 'SPA_18', 'C (低)', 'SPA_08', 'A', '與 SPA_08 (反饋尋求) A 聯動：表現為「完美的學習者」。主動尋求回饋（08A）且能淡化情緒雜訊、理性吸納建議（18C）。其成長效率在 18 項特質組合中排名第一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3848, 'SPA_18', 'C (低)', 'SPA_13', 'A', '與 SPA_13 (A型性格) A 聯動：表現為「冷靜的競速者」。追求效率與成果（13A），但過程情緒穩定、不具敵意（18C）。管理建議：適合作為跨部門專案經理，能推動節奏而不引發反感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3849, 'SPA_18', 'C (低)', 'SPA_14', 'A', '與 SPA_14 (競爭欲望) A 聯動：表現為「理性的競技選手」。渴望贏（14A），但輸贏皆不形於色（18C）。這類人會精確分析對手強弱而非情緒化對抗，極其難纏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3850, 'CSR_01', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「衝刺後才補評估的進取者」。他對高標準有強烈企圖心，遇到挑戰傾向立刻升級方法與目標；同時他在行動前較少系統評估風險，常在執行中途才發現需要調整。具體情境裡，他一邊全力推進任務到更高難度，一邊靠做中學補上事前沒掌握的隱性問題。推進力強、願意接硬任務，但也容易在快節奏下略過重要的預判步驟；管理上宜在任務啟動前設置簡短的方向確認，讓進攻動能不因事後返工而受挫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3851, 'CSR_01', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「目標堅定但易情緒失速的衝刺者」。他對工作表現有明確企圖心，遇到挑戰願意主動把標準往上推；在壓力或衝突升高時，他較容易被情緒推著走，出現衝動回應或倉促決定。具體情境裡，他一邊全力推進高難度任務，一邊在摩擦時刻容易言行過激，事後常需要修補。推進力強、有挑戰意願，在看得見進展的環境最有動能；分工模糊或負面情境一旦累積，衝動風險升高，管理上宜在節奏緊張的時間點主動設緩衝點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3852, 'CSR_01', 'A (高)', 'CSR_26', 'C', '與 CSR_26 (條理性) C聯動：表現為「目標持續升級但流程散亂的進攻型」。他對表現有明顯企圖心，遇到挑戰傾向主動把方法與目標往上拉；對例行程序與細節整理的偏好較低，傾向臨場處理，記錄與交接常不足。具體情境裡，他一邊全力把任務做到更高難度，一邊略過整理步驟直接衝進下一個目標。推進速度快、願接挑戰，在短期衝刺任務中有優勢；需要系統追蹤或多人協作時，管理上宜設最低結構節點，讓高效衝刺不因資訊散落而累積隱患。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3853, 'CSR_01', 'A (高)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「進取心強但利益感知明顯的衝刺者」。他對工作表現有明確企圖心，願意多投入達到更高標準；較重視財富、地位或外在象徵，對回報分配的公平性敏感，容易把投入的多寡與可見回報掛鉤。具體情境裡，他一邊把任務目標往上推，一邊留意自己能不能拿到相應的利益與認可。推進力強，在回報透明的環境最有動能；分配不清時容易出現比較心態，管理上宜把貢獻與回報的對應關係說明清楚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3854, 'CSR_01', 'A (高)', 'CSR_23', 'C', '與 CSR_23 (低物質傾向) C聯動：表現為「高產出高物質期待的目標衝刺者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標；較重視財富、地位與外在象徵，容易把物質激勵視為投入與努力的主要交換條件。具體情境裡，他一邊把任務標準往上推，一邊留意成果是否帶來相應的實質回報。推進力強，在薪酬與晉升連結清楚的環境最有動能；感知到付出與物質回報脫鉤時，企圖心容易降溫，管理上宜讓高績效與具體獎酬直接對應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3855, 'CSR_01', 'A (高)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「求表現也求肯定的進取者」。他對成果有明確企圖心，遇到挑戰會主動把方法和目標往上推；做事時他同樣在意自己的投入被看見，誰拿到功勞對他不是小事，旁人光芒太亮時他會敏感。具體情境裡，他常一邊全力把任務做到更高，一邊留意這份成績有沒有清楚記到自己名下。實務上他推進力強、願接硬任務，在看得見回饋的環境最有動能；分功一旦模糊，他容易覺得貢獻被埋沒而生張力，管理上宜把成果歸屬講清楚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3856, 'CSR_01', 'A (高)', 'CSR_12', 'A', '與 CSR_12 (目標效能感) A聯動：表現為「敢接高目標且信自己能到的推進者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標；對努力能換來成果有明確信心，遇到高難度任務會主動拆解推進，較少因不確定而退縮。具體情境裡，他一邊把任務難度往上拉，一邊自信地評估路徑並持續前進。推進力強、敢承擔且不易被風險嚇退，在需要大膽攻克瓶頸的場景是強力推手；管理上需給予足夠挑戰的任務規模，讓這份動能得到充分釋放。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3857, 'CSR_01', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「衝勁強但逆境復原慢的進取者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標；在長期高壓或連續變動下容易出現能量耗竭，補救與恢復較吃力，表現波動會增大。具體情境裡，他一邊全力推進高難度任務，一邊在逆境累積後失去快速回彈的能力。推進力強、願接硬任務，在順風期爆發力明顯；進入逆境後恢復緩慢，管理上宜在高強度衝刺階段設置緩衝，讓進攻動能不因連續耗損而崩塌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3858, 'CSR_01', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「進攻性強但悲觀解釋拖腳的衝刺者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標；傾向把不如意視為長期且普遍，遇阻礙容易預期失敗，抗挫力相對薄弱。具體情境裡，他一邊主動承接高難度任務，一邊在挫折累積後快速降低嘗試意願。順境或有清楚進展時爆發力強；一遭遇阻礙，悲觀解釋快速壓縮動能，管理上宜在低點及時給予「可以改善」的訊號，讓進攻動能不被過度打折。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3859, 'CSR_08', 'A (高)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「責任自驅的規範執行者」。他對自己的輸出有一致的自我要求，主動掌握進度，細節與收尾很少需要催。遇到邊界不清的情況，他傾向選最可被交代的做法，而非往有利自己的方向解釋。在看得見規範架構的環境裡，他的可靠度穩定展現；一旦規則本身模糊或衝突，他可能花相當多精力確認自己站在「對的那一邊」，才願意繼續推進。管理上，給他清楚的責任邊界與可遵循的標準，他就能持續穩定交付。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3860, 'CSR_08', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「自律表現的策略包裝者」。他做事有一致標準，進度與品質靠自己管，不需外部催促；溝通上，他傾向用對自己最有利的方式組織敘事，可能選擇性揭露資訊或用話術影響他人判斷。在有回報壓力或競爭情境裡，他一邊保持高輸出，一邊調整對外說法。實務上他是能交付成果的人，但周遭對他的資訊透明度可能有疑慮；管理上宜在重要決策節點建立多方確認機制，降低資訊被策略性過濾的風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3861, 'CSR_08', 'A (高)', 'CSR_23', 'C', '與 CSR_23 (低物質傾向) C聯動：表現為「以回報驅動的高標準執行者」。他做事有一致的自我要求，不需催促就能保持可靠輸出，但對財富與地位象徵的敏感度同樣明顯。他把高品質的表現視為爭取對應回報的籌碼，在回報清楚的環境最有動能；若激勵模糊或察覺付出與回報不對等，他的動力下滑速度比外表顯示的更快。管理上宜讓績效與回報的關係保持透明，並在長期高投入期間給予明確肯定，才能維持他穩定的輸出水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3862, 'CSR_08', 'A (高)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「以正當手段追求卓越的執行者」。他在品質與進度上有高度自我驅動，不靠外部催促；同時，即使目標有壓力，他傾向拒絕欺騙或利用他人換取優勢，把對等與規則一致視為工作的底線。在透明競爭的環境裡，他的可靠度與信任感都高；若環境裡其他人普遍走捷徑，他可能感到沮喪或有落後的壓力，需要管理者明確肯定正當手段的長期價值。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3863, 'CSR_08', 'A (高)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「嚴以律己、也急於被認可的執行者」。他自我要求高，不需要人催就能主動掌控進度與品質收尾；遇到任何一個步驟出漏，他比別人更先察覺也更快收拾。遇到分工模糊時，他容易在心裡計算貢獻份額，若結果被算在別人名下，他的不舒服來得又快又明顯。在需要長期協作的環境，他往往同時扮演最可靠的推進者與對功勞歸屬最敏感的那個人；管理上最有效的做法是讓成果與姓名保持清楚對應，他在這種條件下既可靠又穩定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3864, 'CSR_08', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「高投入但難抗耗損的執行者」。他對進度與品質有一致的自我要求，能主動掌握節奏，穩定期的輸出值得信賴；但在長期高壓、連續挫折或責任變動的情境下，他的能量耗竭速度比表面看起來快，補救行動相對吃力，恢復也需要較長時間。實務上他在有節奏的環境表現最穩，遭受連續衝擊後需要明確的緩衝空間；管理上宜主動分段任務、避免連續高負荷，並在逆境後給予重新整理的時間點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3865, 'CSR_08', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「嚴格執行但容易預期失敗的完成者」。他能主動掌握進度，對品質有一致要求，不需催促也能收尾；但對不如意的解讀傾向長期且普遍，遇到障礙容易預期接下來也會失敗，抗挫力不如外表顯示的穩定。在任務順利時他的輸出高且可靠，但一旦連續碰壁，動能下滑的幅度超過一般人。管理上宜主動在逆境時幫他拆解可見進展、具體肯定局部成果，才能維持他穩定的推進節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3866, 'CSR_08', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「高度自律且主動攬責的執行者」。他做事有一致的自我要求，能主動掌握節奏、顧品質、確保收尾；遇到問題或延誤，他的第一反應是自己承擔並主動找出補救方法，很少把責任推給情境或他人。在需要高度可靠度的環境裡，他是管理上最省力的那類執行者；但他對問題的當責度可能高到連非自己範圍的事情也會攬進來，長期下來可能形成不必要的負荷，管理上宜幫他清楚界定責任邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3867, 'CSR_10', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「深思進取者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標，但每次升級前都會先評估風險、假設與後果，確認路徑可行才動手。在有難度的情境裡，他一邊盤算要把目標推到哪個高度，一邊審視潛在的返工代價，通常要確認過才會全力投入。這種節奏讓他的產出可靠，但在需要快速切換目標的環境裡，決策前的評估期可能被誤讀為遲疑。管理上宜給他清楚的時間框架，讓思考和衝刺都能落在對的節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3868, 'CSR_10', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「謹慎卻不穩的推進者」。他習慣在行動前評估風險與後果，不確定情境中也能維持判斷品質，這是他日常運作的基本模式。然而在壓力累積或衝突升溫的時刻，他較容易被情緒推著走，出現超出預期的衝動反應，事後常需解釋或修補。在平穩節奏下，他的謹慎展現得完整；在高張力場合，衝動風險會浮現，判斷品質容易出現落差。管理上宜減少讓他在情緒高點快速表態的情境，重要決定盡量給他緩衝空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4012, 'CSR_02', 'C (低)', 'CSR_34', 'A', '與 CSR_34 (誠懇) A聯動：表現為「冷淡但可信的直話者」。他在人際中保持距離與戒備、少展現熱情，但溝通直接透明、不靠操弄或包裝達成目的——疏離讓他難親近，誠懇卻讓這份冷淡屬於『不熱情但可信』而非帶心機。其價值在於說真話、不口蜜腹劍；代價是缺少人際潤滑、初期易被誤讀為敵意。管理上不必期待他的熱度，但可高度倚賴其陳述的真實性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3869, 'CSR_10', 'A (高)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「想清楚仍不確定能否做到」。他行動前會評估風險和假設，分析能力明顯，但在完成評估、確認方向後，對自身能力的懷疑常隨之浮現。他遇到挑戰任務時一邊把問題拆得很清楚，一邊懷疑自己是否真能執行，實際推進常需要安全感確認才願意動手。在有外部確認的情境下他能穩定輸出；獨立面對不確定任務時，謹慎評估和信心不足容易讓他在啟動階段卡著。管理上宜在分工明確的基礎上給他明確的授權訊號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3870, 'CSR_10', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「審慎但善於包裝立場」。他行動前評估風險與假設是真實的習慣，但評估的範疇也包含如何讓自己的立場被他人接受。在一般情境他呈現謹慎可信的形象，遇到競爭或目標壓力時，他可能把資訊選擇性組合、包裝成對自己最有利的呈現方式。他不是衝動行事，而是算清楚了再說，說出來的版本是計算後的結果。管理上宜建立透明資訊文化，並在重要討論中確認他呈現的是完整圖像而非策略性選取。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3871, 'CSR_10', 'A (高)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「思慮周全卻動能薄弱」。他在行動前評估風險和假設的習慣使他的計畫品質穩定，但心理資源的不足讓他在評估完成後難以維持推進動能。他一邊把任務拆得很清楚，一邊感到對結果的期待感偏弱，遇到挫折時復原速度慢，評估好的計畫可能在執行階段就卡住。在資源充沛、結構清楚的環境他能發揮分析優勢，但長期壓力或連續不順很快會讓動能耗盡。管理上宜縮短任務周期、及時提供可見的進展回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3872, 'CSR_10', 'A (高)', 'CSR_25', 'A', '與 CSR_25 (樂觀) A聯動：表現為「穩健評估的樂觀行動者」。他在行動前評估風險和後果，在不確定情境也能維持判斷品質，而對挫折的解釋習慣讓他把不順視為可改善、可轉機。他遇到阻礙時一邊重新評估路徑，一邊保持可以找到出路的期待感，較少因單次失敗而放棄推進。這個組合讓他在持續有阻礙的任務中仍能穩定輸出，較少落入分析癱瘓或悲觀停滯。管理上適合安排需要長週期持續推進、允許他從容評估調整的工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3873, 'CSR_10', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「承擔到底的謹慎者」。他在行動前評估風險和假設，執行後遇到問題主動承擔並補救，在需要可信賴輸出的任務中因此表現穩定。他在確認路徑可行才動手，動手後出了問題不推給外部，而是重新評估、自己收尾，延誤或失誤的頻率低，即使出現也修補得完整。潛在壓力是他同時對思考和執行都抱著高度自我要求，在資源不足或多工時可能讓自己超載。管理上宜主動確認他的負荷量，避免讓他一個人扛過多責任範圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3874, 'CSR_11', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「可信賴的高標執行者」。他對承諾與品質有同等的重視，把任務完成到可被信任的標準是他的基準線，不達到這條線他不會放手。工作中他主動掌控進度，也留意規範邊界，遇到不確定的做法寧可多花時間確認，也不輕易繞道。這類人在高度依賴規則與品質的環境中輸出穩定；管理上只需給清楚的邊界，他會自己把事情做好、做對。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3875, 'CSR_11', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「守規但動能受環境牽動的執行者」。他對規範與責任的遵守不打折，不論情境都能選擇可被信任的做法；但他對任務的投入感與進取心容易被外部條件左右，成果看不到或要求不明確時，他的動力更多停在「做完」而非「做好」。他在邊界清楚的情境下是可靠的執行者；管理上宜提供進展回饋與明確目標，以避免他只守線不突破。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3876, 'CSR_11', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「審慎守規的決策者」。他在下決定之前習慣評估風險與後果，也同樣習慣確認自己的做法是否落在可被信任的邊界內。遇到不確定情境，他不輕易動手，而是先釐清再行動。這讓他在複雜或高風險場景中尤其可靠；代價是速度較慢。管理上給足確認管道，他能在高標準下穩定輸出，若催促他跳過確認步驟則容易引發抗拒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3877, 'CSR_11', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「規範堅守卻衝動外溢的執行者」。他在日常工作中重視承諾與規則，偏向選擇可被信任的做法；但在壓力累積或衝突升高的情境，他的情緒控制相對脆弱，容易被推著做出超出原則的倉促反應，事後往往需要補救。旁人觀察到的是他「原則很強但情緒有時不穩」。管理上宜避免讓他在高壓情境孤立決策，並在衝突後給他冷靜收場的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3878, 'CSR_11', 'A (高)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「嚴謹自律的高品質守門人」。他對品質與規則的要求同樣嚴格，在交付之前會自我審核，任何不確定的做法都要先釐清；他也會在細節上反覆打磨，直到確信輸出可被信任為止。這讓他在精密度要求高的場景極具價值，但也可能讓他成為工作流程中的瓶頸。管理上宜明確定義「夠好」的標準，以免他陷入過度優化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3879, 'CSR_11', 'A (高)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「守規但利益傾斜的矛盾守門人」。他對承諾與規範有真實的重視，但對外在利益和地位象徵也有明顯的敏感；在兩者不衝突時他表現穩定且可信，但當遵守規則意味著放棄具體回報，他的行為可能在邊界上尋找詮釋空間。旁人會感受到他「整體守規，但在涉及自身利益時會算得很精」。管理上宜明確獎懲機制，讓守規與得到合理回報之間的連結清晰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3880, 'CSR_11', 'A (高)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「原則守正的誠信執行者」。他重視承諾、也堅持公平，在競爭或壓力情境下都不容易走向欺騙或利用他人的捷徑。他認為值得信任的做法和對等的規則是一件事，在灰色地帶寧可選擇可被交代的方式。這讓他在需要高度誠信的場景中是極佳人選；代價是他可能對他人稍微使用策略的行為反應過敏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3881, 'CSR_11', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「守規卻耗損積累的執行者」。他在多數工作情境中能選擇可被信任的做法，承諾的重量對他是真實的；但他在面對持續逆境或連續變動時，恢復力有限，能量消耗後整體輸出穩定性也跟著受影響。長期下來旁人會觀察到他「平時可靠，但在連續高壓下容易撐不住、開始鬆動」。管理上宜在高壓階段提供節奏調整空間，而非只預設他能持續維持高標準輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4163, 'CSR_09', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「雙重收窄的謹慎者」。他在可掌握範圍內才傾向主動出手，而對自身能力的低信心又為這個判斷再加一層過濾——兩種機制都偏保守，讓他實際投入行動的門檻明顯偏高；在新情境或條件模糊的任務中，觀望與等待是常見姿態。建議先從能力確認度高的小任務建立成功記錄，逐步同時拓寬掌控感與能力感的主觀邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3882, 'CSR_11', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「自我驅動的全責守規者」。他對承諾和規則的堅守，不只來自外在要求，也來自他對結果負責的強烈決心。遇到問題他的第一反應是承擔、追根究柢並補救，而不是尋找外部解釋。這讓他在需要高度可信賴度的場景中表現突出；旁人感受到的是「這個人說到做到，出了問題也不推」。管理上幾乎不需要催促，給清楚的方向與邊界即可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3883, 'CSR_11', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「高產但規範靈活的執行者」。他做事有一致的自我要求，能主動掌控品質與進度，在工作輸出上是可靠的；但他對規範的態度較有彈性，遇到目標壓力或灰色地帶，傾向以結果導向詮釋規則，而非先確認邊界。旁人觀察到他「做得快、做得好，但有時讓人不確定他是否真的守住了規則」。管理上宜在重要流程點設置明確的合規確認環節，以補其彈性帶來的風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3884, 'CSR_12', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「自驅高標的自律執行者」。他對目標的掌控感高，確信只要做對方法就能達到想要的結果；做事時他不只求完成，更在意整件事做到什麼標準。遇到挑戰性任務，他會主動把目標分拆，一邊執行一邊維持自我監控，較少需要外部提醒來保持節奏。在旁人眼裡，他是那種既能啟動又能收尾的人，交出去的東西通常不讓人擔心。長期在高要求環境裡，他傾向成為標準的來源而非跟隨者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3885, 'CSR_12', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「先想清楚再全力推進的信心型思考者」。他對努力能換到結果有穩定的信念，在面對高難度目標時不容易退縮；同時他的行動節奏帶有一種習慣性的前置評估，傾向先把風險和假設想清楚再全速推進。遇到複雜任務，他常先拆解關鍵節點、確認前提可信後，才把全部能量投入執行。這讓他的信心不是衝勁式的，而是建立在判斷上的；即使面對不確定，他也能在評估後決定「值得全力做」。管理上他通常不需要被提醒，但給他時間想清楚方向，他的輸出品質會明顯更高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3886, 'CSR_12', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「推進力強但行為易出格的自信執行者」。他確信只要持續投入就能把目標達成，遇到高標任務也不容易被嚇退；在進展順利時，他是最快往前推的人，能量充沛、行動力強。遇到阻力或壓力升高時，他的反應節奏加快，可能在情緒還熱著的時候就做出承諾或決策，之後才發現需要收拾。旁人在合作時常感受到他的驅動力，但也會注意到他在緊張時刻的反應難以預測。管理上宜在高壓關頭多設一個確認環節，給他一點喘息空間再決定行動方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3887, 'CSR_12', 'A (高)', 'CSR_32', 'A', '與 CSR_32 (自我勝任感) A聯動：表現為「對成果有把握也對自己有信心的能動者」。他對自身能力和對努力會有回報這兩件事都有清楚的把握，遇到高標目標時既不懷疑自己是否做得到，也不擔心做了會沒有結果。他傾向主動承擔新任務、在不確定中找出前進路徑，不需要特別多的保證才能開始行動。在旁人眼裡，他是一個在挑戰面前會讓人放心的人——不只是衝勁強，而是對整件事的掌控感都在。管理上這類人的最大風險是被過度分配，需要確保資源與任務量同步對齊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3888, 'CSR_12', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「推進力強但抗壓容量有限的信心型執行者」。他相信努力能換到結果，啟動任務時有清楚的信心和行動力；在任務環境穩定時，他是能持續推進的可靠執行者。當壓力長時間累積、挫折連續出現時，他的耗損速度比他自己預期的快，動能和信念都可能因此出現明顯落差。旁人有時會看到他在高壓後變得遲疑、收縮，跟任務初期的姿態落差明顯。管理上宜在高強度任務中間設置緩衝節點，讓他有機會補充資源再繼續投入，而非一路拉到底。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3889, 'CSR_12', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「企圖心強但信心跟不上的進取者」。他對表現和成果有明確的追求，遇到挑戰願意多投入、想把目標推得更高；但在真正行動時，他對能否完成缺乏足夠的把握，這份不確定會在關鍵節點讓他踩剎車、過度求證、或把決策推給他人。旁人有時感受到他的企圖心和實際推進速度之間的落差——他想要的比他願意獨力走的要多。在有足夠確認與支持的環境下，他能釋放企圖心、穩定產出；若任務含糊或回饋不足，他的推進節奏容易碎片化。管理上宜把任務拆小、給明確里程碑，讓他每走一段都能驗證方向是對的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3890, 'CSR_12', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「高標準要求但缺乏完成信心的反覆檢核者」。他對細節與品質有強烈的要求，能敏銳察覺哪裡還不夠好，並願意反覆優化；但他對「我能把這件事做到位」這件事本身缺乏把握，讓他很難在某個節點判斷「這已經夠好了，可以交出去」。結果他常處在持續修改、無法真正結案的循環裡，輸出速度遠比他的投入程度要慢。旁人感受到他對品質的認真，但也會在等待交付時感到焦慮。管理上需要幫他設定明確的「完成標準」，讓他有一個外部錨點來終止反覆確認的迴圈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3891, 'CSR_12', 'C (低)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「預期失敗又缺乏信心的高阻力停滯者」。他對自己能否把目標推到位缺乏把握，對挫折的解釋又傾向視為長期且普遍，面對任何挑戰時都先感到沉重。遇到困難，他的第一反應不是「怎麼解決」而是「這可能本來就做不到」，行動意願明顯下降。旁人常看到他對任務猶豫很久才開始，一旦遇到阻礙又容易提早放棄或轉交他人。在環境支持充足、任務有清楚可見的進展里程碑時，他能改善投入狀態；若環境回饋模糊，他的停滯狀態容易拉得很長。管理上需要主動切分小目標、讓他能快速看到階段性成果，重建行動信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3892, 'CSR_14', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「公平競爭的進取者」。他對成果有明確企圖心，遇到挑戰會主動把方法和目標往上推，全力在可行範圍內把任務做到更高。他對欺騙、利用他人這類手段有穩定的拒絕反應，即使眼前的競爭對他形成壓力，這條線也不會移動。具體情境裡，他一邊以更高標準要求自己、一邊把不公平選項直接排出去，不依賴規則提醒，而是自發排除。實務上他推進力強，在透明、對等的環境裡能發揮最大動能；管理上宜給他足夠空間展現真實努力，過度管控反而消耗他的自驅力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4164, 'CSR_09', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「壓力下邊界加速縮退」。他在可掌握範圍內有穩定的行動傾向，但在長期高壓或連續逆境中，韌性資源的快速耗損使他對「什麼在掌控內」的判斷提前悲觀——行動邊界比外界可見的壓力程度更早收縮、更慢恢復。建議在任務安排上，避免長時間高壓連續運作，並在壓力信號出現初期就提前補充支援，而非等到耗竭後才介入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3893, 'CSR_14', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「情緒易衝動但底線守公平」。他在情緒激動或壓力升高時容易出現衝動反應，語氣或行為可能失控，事後常需要修補關係或解釋。遇到被惹怒或不公平對待時，他一邊感受到強烈的情緒衝動，一邊對欺騙或利用他人的選項有清楚的排斥。他的衝動多落在情緒宣洩上，而非道德邊界上。實務上他在人際摩擦情境容易留下後遺症，管理上宜提供情緒緩衝機制並事後覆盤，而不需要擔心他在激動中做出手段性的傷害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3894, 'CSR_14', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「結果掛帥的強勢競爭者」。他對成果有清楚的企圖心，願意多投入以達到更高標準，遇到挑戰會主動把方法往上推。他同時容易把領先視為第一順位，可能把不公平手段或利用他人的選項合理化為達成目標的途徑。具體情境裡，他一邊全力衝刺任務、把自己逼到更高，一邊對手段邊界的敏感度偏低，遇到灰色地帶不一定會停下來確認。實務上他的推進力很強，需要透過清楚的規範框架與後果機制來讓邊界具體可見；若缺少外部約束，他可能在高壓競爭中逐漸向手段方向滑移。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3895, 'CSR_14', 'C (低)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「精算謀略的手段傾向者」。他行動前會仔細評估風險、假設與後果，不輕易在不確定情境中倉促行動。他同時容易把領先視為首要考量，並傾向把利用他人或不公平手段合理化為可用途徑。具體情境裡，他一邊周詳計算每個步驟可能的風險，一邊把手段選項納入計算框架而非事先排除。他不是衝動型的，而是刻意且有計畫的。實務上他做事穩健、少有返工，但若置於強烈競爭情境，其謀略性的手段傾向可能對周圍造成深遠影響；管理上宜透過透明度要求與互評機制讓行為暴露在監督下。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3896, 'CSR_14', 'C (低)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「情緒衝動且手段不設防者」。他在壓力或衝突升高時容易被情緒帶著走，出現衝動回應、倉促承諾或過頭行為。他同時對不公平手段的排斥感偏弱，遇到能讓自己領先的機會，合理化的速度快。具體情境裡，他一邊被情緒推著快速行動、一邊在道德邊界上缺乏足夠的煞車，使得衝動行為更容易踩到不公平的區域。實務上他在高壓情境下容易留下難以收拾的後果，管理上宜設置明確的冷卻期與結果後果機制，讓他在行動前多出一個自我確認的節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3897, 'CSR_14', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「話術操弄的結果導向者」。他傾向把包裝與話術視為達成目標的工具，溝通中容易選擇性揭露資訊、用策略性表達影響他人判斷。他同時容易把領先視為第一順位，對利用他人換取優勢有較高的容忍度。具體情境裡，他一邊透過措辭與資訊管控引導對方按他想要的方向行動，一邊在利益配置上往自己傾斜，兩條線同步推進。實務上他在需要透明溝通的場域容易引發信任危機，管理上宜設定具體的資訊揭露標準與多方核查機制，讓單方面話語的影響力受到結構性制衡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3898, 'CSR_19', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「誠正驅動的進取者」。他對表現與成果有明確企圖心，遇到挑戰會主動把方法和目標往上拉；在這個過程裡，他對財富、地位的執著不強，不太傾向靠炫耀或佔便宜換取優勢。具體情境裡，他常一邊全力投入任務、一邊維持直接透明的溝通，不誇大自身貢獻，也少在功勞分配上計較。對周遭而言，他給人的印象是可靠且不滑頭的推進者；管理上宜持續給他可見的高標目標，回饋給到真實進展即可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3899, 'CSR_19', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「自律包裝下的利益盤算者」。他在日常工作中展現高度的自我驅動，能主動顧品質與收尾、不需外部催促；但對於財富、地位或個人優勢，他的自我要求較弱，容易把利益擺在公平之前。在具體情境裡，他一邊維持讓人印象深刻的可靠輸出，一邊在回報不明確時悄悄傾向對自己更有利的詮釋或拿取。對團隊而言，他是產出穩定的成員，但在分功、資源分配或評估透明度不足時可能帶來張力；管理上宜建立清楚的公平評估機制，讓勤奮與誠正的標準都能被看見。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3900, 'CSR_19', 'C (低)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「審慎算計的利益優先者」。他在行動前習慣評估後果，在不確定情境下仍能維持判斷品質，外表給人謹慎可信的印象；另一面，他對財富與地位的重視程度較高，對公平與謙遜的自我約束偏弱，較容易合理化先拿到再說。具體情境裡，他常一邊把決策環境想得很周全，一邊把這份周全用在對自己有利的詮釋上，讓不公平的拿取在表面上顯得有依據。對組織而言，利益分配的透明度與外部稽核是管理重點；他在規則清楚、可溯源的環境下，帶來的負面行為空間會明顯縮小。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3901, 'CSR_20', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「有方向有節奏的推進者」。他對目標有具體輪廓，腦中常備著主路徑與替代路線，一旦遇到阻礙就調整方向繼續走而不是原地空轉。做事時他習慣把工作拆成可核查的段落，逐段確認品質與進度，自發維持完整收尾而不需要外部催促。遇到複雜任務，他會在推進節奏和輸出可靠度上同時施力，確保每個交付點都站得住腳。長期而言這樣的工作方式容易建立信賴，但也要留意不讓路徑規劃變成對細節的過度打磨，以免消耗在完善計畫本身。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3902, 'CSR_20', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「審慎規劃的目標執行者」。他腦中同時保有清楚的目標輪廓和對應的替代路徑，不輕易在沒想清楚的情況下啟動，行動前會先過一遍風險與假設。遇到阻礙時不是停下來，而是切換到備案繼續往前，改道而非放棄是他的自然反應。在需要判斷品質的場景他的輸出較少返工，但若評估過程拉太長，他可能在時效敏感的任務上慢半拍，管理上給予合適的時間框架有助於發揮這個特質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3903, 'CSR_20', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「方向清晰但情緒易衝的行動者」。他腦中有具體的目標地圖，能把動機和策略路徑連結起來，遇到阻礙也備有改道方案，不輕易放棄。不過在受挫或被質疑的當下，情緒容易搶在理性路徑之前反應，出現言語或行為過頭的情況，需要事後補救或解釋。具體情境裡，他在計畫順利推進時展現穩定的目標感，一旦路上出現意外衝突，應對方式可能比他原本規劃的更快、更激。管理上留出讓他緩一口氣再決定的空間，能幫他把清楚的目標思維在關鍵時刻真正用出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3904, 'CSR_20', 'A (高)', 'CSR_19', 'A', '與 CSR_19 (誠實謙遜) A聯動：表現為「誠正有策略的目標推進者」。他有清楚的目標輪廓，能把動機轉換成可執行的路徑，遇到阻礙會換道而不是放棄。在推進過程中他對財富與地位的追求保持節制，也不會為了加速到達目標而走機巧或佔便宜的路線，溝通偏向直接透明。遇到利益誘惑或捷徑時，他的第一反應通常是重新確認這條路是否可以被公開交代，而不是先抓住再說。這樣的工作方式在需要長期信任的情境下最能發揮，但若環境充滿競爭壓力，他可能因不願搶灰色地帶而偶爾落後於更進取的同儕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3905, 'CSR_20', 'A (高)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「打擊後快速重啟的目標守持者」。他對目標有具體的動機與多條備用路徑，遇到阻礙不放棄而是改道，這份清晰的目標感在逆境中成為他維持動能的錨。壓力或挫敗發生後他能快速回到可工作狀態，把打擊轉成找補救方案的行動，而不是在原地消耗。在連續高壓或計畫反覆受阻的環境裡，他能持續往前；旁人也相對容易和他共事，因為他不容易被一次失敗拉倒，態度恢復快，不拖累整體節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3906, 'CSR_20', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「企圖心旺盛但路徑易卡的衝刺者」。他對工作成果有明顯的企圖心，願意多投入以達到更高標準，挑戰出現時直覺反應是把目標再往上推。不過在把動機轉換成具體策略路徑這一段，他常常難以建立穩定的備案思維，遇到阻礙時容易停滯或換方向而不是重新構築路徑繼續前進。具體情境裡，他在起跑時爆發力強，但若中途碰到不預期的障礙，動能可能大幅波動；給他可拆解的里程碑和方法引導，有助於把進取心維持到最後一段。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3907, 'CSR_20', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「品質追求者缺少前行路徑」。他對細節與品質有高度要求，傾向反覆確認直到接近無瑕才交付，在需要精準的任務上能顯著提升可靠度。不過他把動機連結成可執行路徑的能力相對薄弱，遇到阻礙時備用方案不清楚，容易卡在原本的方法上繼續優化而不是重新構思走法。實務上他交出來的東西品質不差，但若情境要求快速調整方向或接受不完美再推進，他的節奏容易停住，管理上宜協助他明確化「夠好即可交付」的門檻以及遇阻時的備選方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3908, 'CSR_20', 'C (低)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「容易預期失敗且路徑不足的停滯者」。他可能有想達成的目標，但把動機和具體執行路徑連結起來對他是吃力的一件事，遇到阻礙時也難以迅速重新規劃繞路方案。在這個基礎上，他對挫折的解讀又容易偏向長期且普遍，不順的事情在他眼中傾向成為「結果就是這樣」而不是「暫時的，可以再試」。具體情境裡，一旦計畫撞到第一個真實障礙，他同時承受路徑不清和希望感下滑的雙重壓力，推進節奏容易就此打住；管理上需要主動提供具體的下一步選項，並在他看到進展後幫助他建立「不順是可克服的」的解讀框架。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3909, 'CSR_21', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「穩定推進的高標追求者」。他對工作表現有明確企圖心，遇到挑戰時會主動把方法與目標往上推；推進過程中，他能管理情緒節奏，不讓一時的挫折或興奮打亂判斷，維持可靠的輸出品質。具體情境裡，他在壓力下仍能保持決策一致，不做高代價的衝動選擇，同時持續把執行標準往更高處帶。實務上他推進力強，在需要耐力衝刺的長程任務中特別有表現；管理上宜給予清晰的里程碑，讓他的精力有明確落點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3910, 'CSR_21', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「沉得住氣的審度者」。他在出手前習慣把風險、假設和可能的後果都先過一遍，在資訊不明時也守得住判斷品質；面對需要決定的當下他內在是平穩的，不容易被一時情緒推著走，所以那段思考的空檔不會被焦躁吃掉。遇事他傾向先沉一下、想清楚再行動，較少因為衝動或慌亂而造成事後返工。這種人適合交付需要冷靜判斷、不能憑情緒拍板的任務，但在要求極快反應的場合可能需要旁人幫忙把節奏往前推一點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3911, 'CSR_21', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「情緒穩定但目的優先的行動者」。他在各類互動中都能管理自身情緒，不因衝動或緊張而失態；然而他對「如何達成目標」的判斷，傾向把結果有效性擺在透明誠懇之上。具體情境裡，他在談判或說服場合中能保持冷靜，卻可能選擇性揭露資訊或用話術形塑對方的判斷。實務上他的穩定給人可信賴感，但長期下來對方可能逐漸感受到資訊不對稱；管理上宜鼓勵他在資訊分享上建立透明習慣，讓穩定帶來更持久的信任。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3912, 'CSR_21', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「不易衝動但耗損後難回彈的承壓者」。他在壓力下能管理情緒，不讓衝動影響判斷；但在長期高壓或連續變動中，他的內在資源會逐漸耗盡，恢復速度明顯變慢。具體情境裡，他在短程衝刺任務中表現穩定，但連續高壓超過負荷時，他雖然不容易爆發，卻可能默默縮短補救與自我修正的空間。實務上要注意他的靜默式耗損，不能只看表面穩定；管理上宜主動安排回復期，避免長期高壓把他的可靠輸出基底磨損殆盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3913, 'CSR_21', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「品質要求高但衝動干擾執行的矛盾者」。他對細節品質有強烈要求，願意反覆檢查與優化；但他較容易被情緒推著走，在壓力或衝突時出現倉促回應，事後需要修補。具體情境裡，他在從容狀態下能做出精細的工作，但一旦受到催促或情緒激起，就可能跳過自己平時堅持的確認步驟。實務上高品質的輸出與衝動性失誤會交替出現；管理上宜提供穩定的節奏環境，減少突發衝突，讓他的品質傾向有機會充分發揮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3914, 'CSR_21', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「衝動且手段傾向的行動者」。他較容易被情緒推著走，在衝動回應後需要修補；他同時對領先與結果有強烈在意，傾向把不公平手段視為可接受的選項。具體情境裡，當他感受到競爭壓力時，衝動反應與手段合理化會同時升高，讓他在急切中做出可能傷害他人或規則的行為。實務上他在高壓競爭環境的行為可靠度偏低，需要清楚的規則底線提醒；管理上宜把邊界講清楚，並在考核設計上避免製造讓他合理化手段的誘因。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3927, 'CSR_25', 'C (低)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「預期失敗的退縮者」。他傾向把不如意解讀為持久且難以改變，同時覺得自己不夠有能力應對，面對難題時不安感格外明顯。具體情境裡，他可能在任務初期就表現出明顯的猶豫，或反覆確認卻仍不敢推進，旁人看起來像是在拖延。管理上宜拆細任務讓他先取得一個小成功，再搭配具體的能力肯定，逐步縮小「預期會失敗」的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3915, 'CSR_23', 'A (高)', 'CSR_24', 'A', '與 CSR_24 (謙虛) A聯動：表現為「意義驅動的低調行動者」。他做事的出發點在於工作本身有沒有份量，物質回報不是他的第一考量，而他也不太需要透過炫耀或佔到聲望來感受自我認可。遇到有挑戰性的任務，他願意投入全力，不在乎名分怎麼分、誰多拿了掌聲。具體來說，他在選擇投入哪件事時，看的是意義與成長空間，不看薪酬排名；在交付完成後，他不會刻意搶先被看見，也不在乎功勞如何分配。管理上他適合有深度的任務，但若績效框架只靠物質誘因，他的動能可能顯現不出來，給予明確的任務意義比加薪更能激發他。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3916, 'CSR_23', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「以成果換取回報的積極進取者」。他對表現有明確企圖心，遇到挑戰願意衝刺；同時他對財富與地位的訊號高度敏感，把物質激勵當成投入的主要前提。在高回饋環境裡他能大幅超越基本要求，一旦感覺付出沒有匹配的回報，動能就會明顯往下掉。實務上他接硬任務的前提是先確認報酬與升遷路徑清楚，分配一旦失衡，他會選擇把力氣留在能看到具體回報的事情上。管理上宜把物質誘因和成果目標明確綁在一起，否則他的企圖心容易只停留在談判桌上，而不是在任務裡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3917, 'CSR_23', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「目的導向、回報優先的行動者」。他高度重視財富與地位的訊號，在競爭場合中較容易把「領先」放在第一位；當公平規則和個人利益發生衝突時，他傾向選擇對自己更有利的做法，而不是堅守對等原則。遇到利益分配不均的情境，他不太會忍耐，而是直接採取對自己最有利的行動。管理上這類組合在目標明確、激勵清楚的環境可以快速推進，但若競爭壓力下缺乏監督，他可能把邊界往自己這邊推，需要明確的合規底線與後果設計。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3918, 'CSR_24', 'A (高)', 'CSR_32', 'A', '與 CSR_32 (自我勝任感) A聯動：表現為「低調承擔者」。他對自身能力的信心讓他敢於接下高難度任務，面對挑戰時主動找方法而非等待他人指示。遇到不確定的情境，他仍能穩定推進，較少因懷疑自己而退縮。工作中他較能接受他人的貢獻，不需要靠壓過別人來確認自己的位置。管理上他適合獨立任務，也能在協作環境中讓空間給其他人，不易因分功而起衝突。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3919, 'CSR_24', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「全力衝刺、也渴望舞台的進取者」。他樂意接下別人不敢接的任務，遇到阻礙會主動把方法和目標往上推而非往下調；舞台夠大的時候，他是環境裡最敢衝的那個人。他對自身貢獻被看見有明確需求，分工一旦模糊，不安感比一般人來得快；旁人受到大量肯定的時候，他的情緒會出現細微但明顯的起伏。在有清楚成果歸屬與公開肯定的環境，他的進取動能最穩定也最持久。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3920, 'CSR_24', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「包裝自我的能見度爭取者」。他把被看見視為重要需求，面對利害關係時傾向用話術或選擇性揭露來突顯自身貢獻，較少讓真實全貌自然呈現。彙報成果時他會調整說法讓自己的角色更顯核心，遇到功勞分配模糊的情境他會積極介入話語框架。這使他在需要推銷自己的場合具有優勢，但也可能讓合作對象對他的透明度產生疑慮；管理上若要他公開進度，宜設明確客觀的紀錄格式，減少主觀包裝空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3921, 'CSR_24', 'C (低)', 'CSR_30', 'A', '與 CSR_30 (心理資本) A聯動：表現為「充沛自信的舞台爭取者」。他具備較高的效能感、樂觀與韌性，面對挑戰時動能不易中斷，把挫折視為可調整的問題而非終點。在這股正向資源的支撐下，他持續主動出現在值得被看見的場合，強調自身貢獻並尋求外界確認。他在高壓環境也能維持積極姿態，不輕易退縮；管理上宜定期給予具體的成果認可，讓他的貢獻被明確記錄，否則他可能持續消耗額外精力在爭取能見度而非專注任務本身。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3922, 'CSR_25', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「謹慎前行的樂觀推進者」。他把挫折解釋成可以被改善的情況，行動前也習慣先評估風險與假設，確認方向後才動手。具體情境裡，他遇到變數不會慌，而是停下來重新整理思路，再以較有把握的方式重新出發。這種節奏讓他的樂觀感有落地的支撐，較少在倉促行動後才發現方向錯誤。管理上宜提供清楚的進展回饋，讓他的正向預期持續有事實可依靠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3923, 'CSR_25', 'A (高)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「高標準的樂觀者」。他對細節與品質要求很高，會反覆檢查與優化追求無瑕疵；同時，他把挫折與不足解讀成可改善、可轉機，因此在高標準帶來的反覆修正裡仍維持得住希望感與動力。這讓他的苛求不至於變成內耗——看見問題會想『還能更好』而不是『又搞砸了』。實務上他很適合品質要求高又需要長期投入的工作，但管理時仍要留意他追求無瑕疵可能拉長時程，必要時協助他界定『夠好可交付』的線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3924, 'CSR_25', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「樂觀取向的手段進取者」。他傾向把不利局面解釋成暫時的，行動力維持得住；遇到競爭或落後，他更多想的是怎麼翻盤，對使用不對等手段的戒心較低。具體情境裡，他可能一邊充滿幹勁地尋找機會，一邊在公平界線上模糊操作。這種模式在可見目標清楚時推力強，但也可能因邊界處理引發同伴或組織的信任問題。管理上宜定期把公平底線說清楚，並對成果歸屬進行公開覆核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3925, 'CSR_25', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「自律投入的隱性悲觀者」。他把不如意預期為可能是長期問題，但做事仍有強烈自我要求，不容易因為悲觀就鬆掉品質。具體情境裡，他常一邊默默擔心結果不會好，一邊把自己能控制的部分做得很紮實。這種狀態在短期能維持高輸出，但若長期缺乏成功的正向回饋，悲觀預期會逐漸侵蝕動能。管理上宜主動給予具體的進展肯定，幫助他把成果連結到努力，而非只停留在負面預測。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3926, 'CSR_25', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「驅動強但預期低的進取者」。他對成果有企圖心，樂意接高難度任務，但同時對結果持悲觀解釋，傾向把不順視為長期困境。具體情境裡，他一邊積極爭取機會、把目標往上推，一邊在心裡認為最終可能做不到。這種落差讓他在起步時有強勁的推力，但遭遇挫折後恢復比預期慢。管理上宜在他達成階段性里程碑時明確指出，幫他把「已做到的」變成下一步的動能支撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3928, 'CSR_25', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「悲觀驅動的策略操控者」。他傾向把不如意解釋為長期困境，同時較容易把操弄或選擇性揭露視為達成目標的工具。具體情境裡，他在感受到局面不利時會加速啟動策略性表達，可能用話術影響他人判斷，而這些行動本身又強化了他「只有如此才能撐住」的悲觀假設。管理上宜強化透明溝通的期待與後果，並在局面不順時主動進場協助他找到正當的轉圜路徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3929, 'CSR_25', 'C (低)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「韌性高但預期悲觀者」。他遇到壓力或失敗後能快速回到可工作的狀態，把打擊轉成行動；但他對未來結果的解釋仍傾向悲觀，認為不順可能持續下去。具體情境裡，他一邊在行為上修正補救、重新上線，一邊心裡保留著「大概還是會不順」的底色。旁人看到的是行動力，但他的心理電量沒有同步充回。管理上宜在他完成補救後提供明確的正向回饋，幫他把「我做到了」轉成對下一次的期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3930, 'CSR_26', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「秩序推進達標者」。他對工作流程有一貫的自我要求，會把資訊分類、任務排程，確保做法一致、不遺漏細節。對於要把成果推向更高難度或額外突破，他的驅動力較薄弱，動能更多被環境的要求牽著走而非自發升級目標。在具體工作裡，他會把現有任務的每個步驟走得紮實，交出完整而可查的記錄，但較少主動去爭取更高挑戰或突破既有標準。管理上給他清楚的範疇與指標，他能穩定維持條理；若要激發他往更高標準走，需要外部明確的期望與反饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3931, 'CSR_26', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「有序深思精準者」。他在每項工作開始前都傾向把資訊整理成清楚分類，設好節奏與追蹤機制；同時他在做判斷時不急，會先評估風險與假設，確認方向可行再執行。面對複雜任務時，他一邊保持流程可追蹤，一邊防止因倉促判斷造成返工。在需要可靠輸出的環境中他表現穩定，但在高速需要頻繁拍板的場景，他可能因準備程序較完整而讓節奏放慢，管理上可以在關鍵判斷點提前標出，幫助他縮短評估週期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3932, 'CSR_26', 'A (高)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「流程品質雙軌把關者」。他一邊把工作納入固定的排程與追蹤節奏，一邊在每個輸出上維持高品質標準，不輕易放過細節。在需要既可靠又精準的工作環境，他能顯著降低遺漏率與品質波動。但在時間壓力下他更容易卡關——流程沒走完不安心、細節沒到位也不安心，可能拖慢整體節奏。管理上宜提前設定明確的「可接受門檻」，協助他在必要時釋放卡關點，而不是讓完整性和完美性都成為不動的底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3933, 'CSR_26', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「彈性衝刺高標者」。他有明顯的企圖心，遇到挑戰會主動把方法和目標往上推，衝刺力道強；但他對固定流程和系統化記錄的依賴度不高，傾向臨場處理。在有回饋的成果導向環境裡他動能充沛，但快速推進的過程中容易出現紀錄不足或交接不清的狀況，下游接手者可能感受到資訊斷差。管理上宜在關鍵里程碑設定交付物清單，把記錄動作嵌入他的衝刺節奏，而不是期待他自發建立結構。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3934, 'CSR_26', 'C (低)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「臨場應急易失控者」。他不靠固定流程工作，習慣臨場處理、彈性因應；在情緒容易被推著走的狀態下，衝動回應的傾向也讓工作記錄和交接更容易出現漏洞。在低壓、節奏穩定的環境他仍能有效推進，但在衝突或高壓情境下，臨場判斷和衝動反應可能同時發作，讓後續的補救與解釋成本顯著升高。管理上建議在高壓決策點引入確認機制，給他一個暫停思考的結構，降低在情緒峰值做出的決定留下難以收拾的後果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3935, 'CSR_26', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「品質追求不建系統者」。他對輸出品質有嚴格要求，習慣反覆確認細節、不讓瑕疵過關；但他不靠固定流程工作，記錄和排程對他來說是臨場補足的，不是結構性的習慣。這讓他的個人輸出可能品質穩定，但過程缺乏可追蹤性——旁人難以看到他如何走到這個結果，交接或協作時容易出現資訊斷差。管理上若要發揮他的品質敏感度，宜幫他設定最低限度的文件節點，把品質的把關成果轉換為團隊可見的資產。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3936, 'CSR_26', 'C (低)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「擔責補救不靠流程者」。他對結果有強烈的責任感，出了問題不推卸，主動追根究柢並補救；但他不靠固定流程來預防問題，工作記錄和交接機制對他來說是次要的。這讓他在事後補救的能力上值得信賴，但在需要穩定預防和記錄的環境，同樣的問題可能會在不同情境下反覆出現。管理上可善用他強烈的責任感，把建立基本追蹤習慣定義為「讓補救更有效」的工具，幫他把被動補救轉向主動預防。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3937, 'CSR_27', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「精雕細琢的謹慎執行者」。他對品質與細節有高度自我要求，做事前先評估風險與隱性疏漏，不確定的地方絕不輕易跳過。執行中他會反覆確認每個環節，將可能的瑕疵逐一補齊，才認為工作完成。這種對缺陷的敏感在需要高可靠度的場景能大幅提升輸出品質；在時間緊迫時，旁人需留意他容易因追求完整而放慢節奏，宜事先對齊「可接受的完成標準」，讓他知道哪個層級的品質已經夠用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3938, 'CSR_27', 'A (高)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「高標要求卻信心不足的執行者」。他對品質有強烈的苛求傾向，看到任何細節不完整都會想繼續修整；但同時對自己能否真正達到那個標準缺乏把握，常常在修改過程中懷疑自己是否走對方向。面對挑戰任務，他容易陷入反覆打磨卻遲遲無法交出的迴圈，需要外部確認才能踏出關鍵一步。管理上建議預先設定明確的完成標準並定期給予肯定，幫助他在確保品質的同時也能建立推進的節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3939, 'CSR_27', 'A (高)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「求表現也重被看見的品質進取者」。他對輸出的品質有明顯的自我要求，做事傾向反覆檢查與優化，不願交出有瑕疵的成果；同時在意自己的投入被誰看見，誰拿到功勞對他不是小事，旁人光芒太亮時他會敏感。具體情境裡，他常一邊把任務做到更高，一邊留意這份成績有沒有清楚記到自己名下。管理上宜把成果歸屬講清楚，讓他知道貢獻有被確認，他便能把精力聚焦在持續提升品質，而不是花在確認自己有沒有被看見。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3940, 'CSR_27', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「高標堅持卻耗損累積的執行者」。他對細節與品質的要求貫穿整個執行過程，不到滿意不輕易放手；但長期維持高標對他來說消耗不小，遇到挫折或批評後要回到可工作狀態需要較多時間。在短期高品質任務中，他的表現往往亮眼；若連續面對長週期高壓或重複碰壁，能量耗竭的跡象會逐漸明顯。管理上宜控制高壓任務的密度，並在大任務完成後主動安排緩衝，避免他在最需要品質的時刻已無餘力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3941, 'CSR_27', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「衝勁強但不拘細節的執行者」。他有強烈的目標企圖心，願意主動承接難度更高的任務，遇到挑戰會升級方法繼續推進，動能充沛；同時對細節品質的要求較低，做到可用就傾向往下走，不會在收尾修整上花太多力氣。在快速迭代的場景中，他的推進力是明顯優勢；若任務對可靠度或精度有高要求，容易在細節層出現累積性疏漏，管理上宜在關鍵里程碑前安排明確的品質確認步驟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3942, 'CSR_27', 'C (低)', 'CSR_30', 'A', '與 CSR_30 (心理資本) A聯動：表現為「充滿正向動能的完成優先推進者」。他對挑戰的正向預期穩定，具備足夠的效能感、韌性與樂觀傾向，能在逆境中持續保持動能；同時對細節品質的要求較低，傾向把東西做到可用就先交出，再根據回饋調整。他在需要快速迭代或頻繁應變的環境表現突出，面對阻礙不容易卡住；但在對精準度有高要求的任務中，容易因提早收手而留下細節疏漏，管理上宜設定明確的品質查核點，幫助他在推進節奏中也顧及完整度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3943, 'CSR_28', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「可靠的負責推進者」。他對把事情做好有強烈決心，而這份決心配上穩定的自我要求，使他在沒人盯的情況下也能自己掌握進度、顧品質、把尾收乾淨。遇到差錯時，他的第一反應是接手補救、追到根因，而不是說明為什麼不是自己的問題。對團隊而言他是低維護成本的承擔者；管理上可放心授權，但要留意他容易把過多的局往自己身上攬，適時幫他界定合理的責任邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3944, 'CSR_28', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「急切問責後補救」。他對自己做的事有強烈的負責意識，事情一出錯就會主動站出來承擔、追根究柢，從不把責任推給外部；同時他的情緒容易在壓力或衝突的當下被觸發，反應往往比思考快半拍。具體情境裡，他常一邊積極主動認領問題，一邊說出或做出情緒驅動的回應，讓他事後不只要補救事情本身，還得花力氣解釋或修補自己的言行。實務上他在問責這件事上十分可靠，但不穩定的情緒反應可能讓周遭對他的判斷力存疑；管理上宜在高壓時點提供緩衝，協助他先穩住再處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3945, 'CSR_28', 'A (高)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「高標準的把關者」。他對把事情做好的決心，落在對細節與品質的高度要求上：出了狀況他主動扛起、追根究柢，而衡量『做好了沒』的尺也訂得很高，會反覆檢查與優化到近乎無瑕。在重視可靠度的場景他是極強的把關者；管理上要留意，承擔感與完美標準疊在一起時，他可能對收尾的時點過於嚴苛，適時和他校準『夠好可交付』的界線，能避免他在追求極致時拖慢節奏或過度自我加壓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3946, 'CSR_28', 'A (高)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「守規則的當責者」。他把事情做好的決心和對公平的堅持是同一套價值：出狀況時主動扛責、追根究柢，但他承擔的方式始終守在規則之內，即使想領先也傾向拒絕欺騙、佔便宜或利用他人。他要的是站得住腳的成果，而不只是好看的結果。對組織而言他是能託付棘手任務又不必擔心走偏的人；管理上可給他需要高度誠信的責任，並讓制度的對等與透明配得上他的標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3947, 'CSR_28', 'A (高)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「扛壓快復原的擔當」。他對結果負全責的決心，配上遇挫後快速復原的能力，讓他在壓力與失敗面前格外耐操：出了狀況他主動扛起、追根究柢，而且不會卡在打擊裡，能很快把情緒收住、回到可工作狀態，把挫折轉成修正行動。他是危機時能頂上又不容易垮的人；管理上適合把他放在高壓或需要快速止血的位置，但也要留意他連續承壓、又不喊累，需有人主動替他補上喘息與支援。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3948, 'CSR_28', 'C (低)', 'CSR_32', 'A', '與 CSR_32 (自我勝任感) A聯動：表現為「自信但少認帳者」。在他身上，對自身能力的高度自信和遇錯往外歸因的傾向同時存在：他面對挑戰願意承擔、主動找方法，看起來很有掌控感，但一旦事情沒做好，他更容易把原因放在環境或他人，補救也偏被動。能力上的篤定並沒有延伸成對結果的當責。管理上他適合衝挑戰，但要把責任歸屬與覆盤機制定清楚，讓他的自信對準『我來修正』而不是『不是我的問題』，以免錯誤重複而學習變慢。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3949, 'CSR_28', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「說法靈活的卸責者」。他遇錯時既傾向往外歸因，也懂得用包裝、選擇性揭露當工具：事情沒做好時，他會把原因放到環境或他人，又用有利的說法把這層歸因鋪得合理，補救動作則相對被動。難處在於旁人不易從他的解釋裡看出真正的責任歸屬。管理上不宜只憑他的口頭說明判斷，建議用可查證的事實、明確的權責紀錄與覆盤來定位問題，否則錯誤容易在漂亮的說法下重複發生。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3950, 'CSR_28', 'C (低)', 'CSR_30', 'A', '與 CSR_30 (心理資本) A聯動：表現為「樂觀但責任外放者」。他擁有較高的希望、效能感、韌性與樂觀，面對挑戰能維持動能，把挫折看成可處理的問題；但這股正向資源主要朝前看，遇到失誤時他傾向歸因外部、補救偏被動，較少回頭自我究責。結果是他情緒上很有韌性，責任承擔卻偏弱——挫折不太打倒他，但也不太轉成自己的改進。管理上要善用他的正能量帶動氣氛，同時把覆盤與責任歸屬明確化，讓樂觀對接到『我來修正』，避免同類問題在好心情中反覆出現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3951, 'CSR_30', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「動能充沛的高標追求者」。他對成果抱持高度企圖心，遇到挑戰傾向把方法與目標一起往上調，不光是完成，而是要做到更好。他的信心與樂觀感讓他把阻礙解讀為可處理的問題，即使失敗也很快重整並再次加速。在有清楚成果指標的環境，他能長期維持極高投入，旁人眼中他像是用不完動力的人；管理上須注意他可能持續加碼而忽略資源消耗速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3952, 'CSR_30', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「沉穩的審慎行動者」。這個人行動前會認真評估風險、假設與後果，較少因一時判斷造成返工；同時在他心裡，希望感、信心與復原力都很充足，使他把不確定看成可處理的問題而非威脅。因此他的謹慎帶著從容——不是怕犯錯的猶豫，而是看清楚再走、走了就穩住的篤定，即使在模糊情境也能維持判斷品質。管理上可以放心把需要縝密判斷又得頂住壓力的事交給他，他既不衝動也不會因不確定而停滯。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3953, 'CSR_30', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「外表穩定、內力不足的盡責者」。他在行為上有一致的自我要求，能主動推進、顧收尾，旁人看到的是可靠的輸出。但他對未來的信心偏低，動能容易在挫折後滑落而難以自行回升。遇到延誤或失誤，他會補上，但補救的過程裡帶著一種沉重感而非積極感。實務上他能撐住基本品質，但在需要突破或長期高壓的情境，動能下降速度比外表顯示的更快；管理上需要定期給予明確的進展確認和鼓勵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3954, 'CSR_30', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「恐懼驅動的高標審查者」。他對品質有嚴格要求，做出來的東西會仔細查核、持續修整；但他反覆確認的動力來自對失敗的警戒，而非對更好成果的期待。他對未來容易感到悲觀，因此每一個輸出都帶著「這樣夠嗎」的焦慮，難以確定何時真正完成。在需要高品質輸出的情境他能過濾掉小錯，但往往耗費超過預期的時間；管理上宜提前確認完成標準，避免他在已達標的作品上繼續消耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3955, 'CSR_30', 'C (低)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「守底線但動能低落的原則者」。他對欺騙、投機或利用他人的手段有清楚的拒絕，即使在高度競爭的情境也不動搖。但他對未來的期待感薄弱，當別人靠捷徑往前時，他不跟進，卻也沒有強烈動力用正道追上。結果是他守住了自己的底線，但停在原地的機率也較高。實務上他是可信賴的參與者，在公平規則清楚的環境表現更穩；若要提升動能，需要幫他看見努力確實連結到可見的結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3956, 'CSR_30', 'C (低)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「攬責卻缺乏復元力的承擔者」。出了問題他不把責任往外推，會主動出面承擔、補救並找出根因，這一點在團隊中值得信任。但他對未來的信心不高，悲觀感讓修補之後的恢復過程相當吃力——他認帳，卻難以從打擊中快速重整動能。在高壓連續情境下，他一邊攬責一邊累積耗損，表現的起伏會比外觀更大。管理上宜在他承擔之後主動確認支援，避免單人扛著持續滑落。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3957, 'CSR_31', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「高壓下仍穩定輸出的執行者」。他對自己的工作要求一致，做事不需要別人催也能維持可靠的節奏；遇到衝突或失敗，他會快速回穩、把打擊轉成補救行動，而非讓動盪侵蝕往後的品質。具體情境裡，他常在事情出問題後主動清點損失、重整計畫，並把細節和收尾再拉回可交代的水準。實務上他在高負荷場景特別有韌性，但也因此容易被賦予更多責任；管理上需要定期確認負荷邊界，避免無限擔責而後積累隱性風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3958, 'CSR_31', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「挫折後加碼投入的拚勁者」。他有明確的企圖心，遇到挑戰傾向把目標與方法往上推；逆境來時他能快速恢復工作狀態，把打擊轉成動力繼續前行，不需要很長的沉澱期。具體情境裡，他常在事情出錯後不只修補，還順手把標準往上調整，讓下一輪更到位。實務上他在需要持續突破的場景有強韌的推進力，但也容易在恢復後立刻接新挑戰；管理上宜確認每次回彈後有足夠緩衝，而非無間隔地累積壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3959, 'CSR_31', 'A (高)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「打擊後反覆精修的堅持者」。他對品質和細節有一致的高要求，遇到失敗或衝突後能快速回到工作狀態，並把補救的過程當作再精修的機會，不容易因為打擊就降低標準。具體情境裡，他常在事情出問題後不只修補，還會把前後的細節都重新檢視一遍，確保沒有遺漏。實務上他在需要可靠度與精準度的任務中表現出色，但恢復期間的仔細程度可能延長收尾時間；管理上宜明確界定「夠好」的標準，避免在恢復階段反覆優化而影響交付節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3960, 'CSR_31', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「消耗後撐著維持的執行者」。他做事有一致的自我要求，不需要外部催促也能維持輸出品質；但在長期高壓或連續變動下，他的恢復速度慢、耗損累積快，會出現撐著做完但能量已不足的狀態。具體情境裡，他常在逆境中繼續完成任務，表面看起來穩定，但背後的恢復空間越來越薄；當壓力未解除時，表現波動會逐漸浮現。管理上宜定期觀察能量訊號，而非只看產出是否維持，否則恢復赤字可能在後段集中爆發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3961, 'CSR_31', 'C (低)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「消耗後仍克制反應的沉默者」。他能管理情緒與衝動，在壓力下仍維持一致的外在行為；然而在長期高壓或連續逆境下，他容易出現能量耗竭，恢復較吃力，持續的自我克制反而加重了難以補充的消耗。具體情境裡，他常讓旁人看不出他已到極限，直到某個時間點才明顯見到表現波動。管理上宜主動創造讓他卸下壓力的機會，而非等到他主動開口，因為他未必會。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3962, 'CSR_31', 'C (低)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「逆境中信心加速流失者」。他對自身能力本就缺乏把握，面對任務時容易遲疑；在長期高壓或連續變動下能量耗竭又讓他更難找回節奏，補救和恢復的過程往往比一般人吃力得多。具體情境裡，他在逆境後的回彈速度明顯慢，往往需要外部明確支持才能重新推進，自主恢復的資源有限。管理上宜在逆境期主動給予具體回饋與方向，而非等他自己找回信心，因為這個等待期可能比預期長。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3963, 'CSR_31', 'C (低)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「逆境中預期持續惡化者」。他傾向把不如意解釋為長期且廣泛的狀態；在長期高壓或連續變動下，耗竭讓他更難找到回彈的起點，他又預設接下來也不會好，恢復的動能因此明顯受限。在逆境期他容易一面能量見底、一面對未來失去期待，整個人陷入停滯。管理上宜優先切開「恢復」與「評估未來」這兩件事，先創造具體的小進展，再談對後段的展望。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4011, 'CSR_02', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「靠流程而非交情的可靠單兵」。其安全感來自任務掌控與自我要求、而非人際連結——對事踏實、對人帶距離與警覺；面對合作會先評估對方意圖，偏好用清楚的規則與介面取代信任默契。獨立作業產出穩定、無需催促，但置於高度依賴信任與人際潤滑的位置容易摩擦。建議給明確分工與書面規則，少用搏感情式管理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3964, 'CSR_32', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「自信積極的高標追求者」。他對自己的能力有穩定的把握感，這讓他在評估新挑戰時不會停在猶豫，而是直接盤算怎麼做到更好。遇到高難度任務，他願意主動挑起並升級方法，推進過程中目標常隨能力感同步提高。在有回饋的環境他動能特別強，一旦看見可以做得更好的空間，就難以停在「夠用就好」的程度。旁人感受到的是一個穩定承擔、不太需要催促也能自我升級的人，但若任務缺乏可見的進展指標，動能可能出現落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3965, 'CSR_32', 'A (高)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「沉穩有序的信心實踐者」。他對自身能力的把握感在壓力情境中也不容易動搖，這讓他在多數場合能持續輸出而不需要情緒來推著走。面對挑戰時，他習慣評估方法而非先感受威脅，判斷較少被一時的情緒推高或打亂。旁人感受到的是一個在高壓下仍能保持可預測行為的合作者；管理上宜給予清楚方向與標準，他能在這種架構內自律地把事做完，也較不容易因外部躁動而跑偏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3966, 'CSR_32', 'A (高)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「主動搶眼的能力彰顯者」。他對自己能做好事情有明確把握，行動時不需要等別人確認就敢推進；做完後，他同樣會在意這份成果有沒有清楚掛在自己名下。在需要表現的場合，他一邊有條件地承擔並完成任務，一邊留意功勞歸屬有沒有跑偏。旁人光芒太亮或成績被稀釋時，他容易產生敏感反應；管理上宜把成果歸屬說清楚，讓他的貢獻有明確的可見度，他的推進力與投入度就能穩定展現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3967, 'CSR_32', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「反覆修整卻難以安心的完善者」。他對細節與品質有強烈要求，會主動反覆檢查並持續優化；但在這個過程中，他對自己是否有能力做到真正的無瑕仍抱持懷疑。遇到需要拍板的時刻，他常常再多做一輪確認，不是因為有新的問題，而是他對「已經夠好了」這個判斷本身沒有信心。在高標準場景他的輸出可靠，卻也容易出現進度拖慢；管理上宜在固定時間點給予外部的品質確認，讓他有安心送出的依據，否則他可能陷入無止境的修整循環。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3968, 'CSR_32', 'C (低)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「安全感匱乏的謹慎迴避者」。他對自己是否有能力做好事情缺乏把握，面對有難度的任務時，這種對自身的懷疑讓他難以自信出手；加上對努力能否換來結果也沒有信心，在起步階段特別容易遲疑或過度求證。旁人常感受到他需要更多確認與支持才能推進，在缺乏安全感的環境裡行動幅度明顯收窄。管理上宜提供明確、可拆解的任務範圍，並在早期給予正向回饋，協助他逐步建立「我做了是有效的」的經驗基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3969, 'CSR_32', 'C (低)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「反彈快但信心難以同步的復原者」。他在遭遇逆境或失敗後能相對快速地回到可運作狀態，打擊對他工作節奏的影響時間較短，也願意把注意力轉向補救和修正。然而這份快速復原並不代表他對自身能力的信心因此提升——回到工作狀態後，遇到需要主動出手的新挑戰，他仍然容易猶豫或依賴他人決定。旁人看到的是一個在失敗後不會垮太久的同事，但在分配責任或獨立承擔時，他需要更多明確的支撐才能真正進場；管理上宜在他恢復後給予具體的任務確認，讓他的回穩轉化成可見的投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3970, 'CSR_33', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「穩步推進的進取者」。他對表現與成果有強烈企圖心，遇到挑戰傾向主動把方法和目標往上拉；而支撐這份野心的，是他能為長遠成果延遲滿足、不被眼前的舒適或捷徑拉走。想得高、又坐得住，使他的高標準不只是口號，而能透過持續投入真正兌現。對組織而言他是能扛長線目標的人；管理上可放手交付有難度的任務，並留意他容易把標準不斷往上加，適時協助他界定階段性的完成點，避免長期高張力造成過度自我消耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3971, 'CSR_33', 'A (高)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「沉得住氣的執行者」。他在行動前會評估風險、假設與後果，即使在不確定情境也能維持判斷品質；而這份謹慎配上他延遲滿足、抗拒短期誘惑的自制，使他不只想得清楚，也能照著想清楚的路長期走下去。他既不衝動起步，也不半途鬆手。在需要穩健推進的長線任務上他特別可靠；管理上可把要求縝密與持久的工作交給他，但要留意他可能因前期反覆權衡而起步偏慢，必要時幫他設定一個『可以開始』的判斷門檻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3972, 'CSR_33', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「守計畫但易動氣者」。在他身上，抗拒誘惑的自律和管不住情緒的衝動落在兩條不同的軸上：面對偷懶、即時享樂這類誘惑他能穩穩延後、守住長期目標，但一遇到情緒被點燃，就容易倉促回應、語氣變硬甚至行為過頭。他不是缺乏自我約束，而是約束力在『計畫』上很強、在『當下情緒』上偏弱。管理上可信任他守得住長線承諾，但需替他在情緒高張時加一道緩衝，例如重要回應前的短暫暫停，能讓他少走許多事後修補的回頭路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3973, 'CSR_33', 'A (高)', 'CSR_23', 'C', '與 CSR_23 (低物質傾向) C聯動：表現為「物質導向的長線延遲者」。他對財富與外在回報有明顯偏好，把物質激勵視為衡量投入是否值得的主要尺度；同時他能為了這個長期目標延遲滿足，面對短期誘惑時維持節奏、不輕易偏離計畫。具體情境裡，他常一邊評估當前任務的物質回報是否夠大，一邊對高回報目標保持長達數月的穩定投入，不因中途的即時誘惑分心。實務上他在回報明確的任務中最有動能，若目標物質誘因不清楚，自律節奏容易下滑；管理上宜把物質回報的條件與時間軸講清楚，以維持他的持續投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3974, 'CSR_33', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「高標準但難貫徹者」。他對細節與品質的要求很高，會反覆檢查、優化以追求近乎無瑕；然而在抗拒短期誘惑、維持長期節奏上他較吃力，明知該持續打磨仍常被當下的輕鬆或即時回報拉走。結果是他的標準與他的執行力之間出現落差——想得到位，卻不一定守得住。管理上他適合把關品質，但需要外部結構來補足貫徹力，例如清楚的階段檢核與較短的回饋週期，能幫他把高標準從『心裡想要』真正落到『穩定做到』。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3975, 'CSR_33', 'C (低)', 'CSR_30', 'A', '與 CSR_30 (心理資本) A聯動：表現為「有衝勁但易分心者」。他具備較高的希望、效能感、韌性與樂觀，面對挑戰能維持動能、把挫折看成可處理的問題；但在延遲滿足、抗拒短期誘惑上他較弱，明知長期目標重要，當下仍容易被即時回報或新鮮刺激拉走。於是他不缺信念與恢復力，缺的是把計畫穩定執行到底的自我約束——起步快、反彈快，卻不一定走得遠。管理上可善用他的正能量啟動與帶動，同時用外部節奏與里程碑補足持續力，把他的衝勁接到能落地的軌道上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3976, 'CSR_33', 'C (低)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「責任感強但節奏易鬆動的執行者」。他對結果有強烈的主人翁意識，出問題不推、主動承擔補救，責任感紮實；在執行過程中則較難持續抗拒短期誘惑，計畫節奏容易在日積月累的小分心下出現鬆動與拖延。具體情境裡，他常一邊在事後快速接下失誤責任、積極追根補救，一邊在執行前段出現當下舒適優先的決定而延遲推進。實務上他在補救與善後階段動能充沛，但預防性的自律管理需要外部結構支撐，管理上宜加入明確的進度節點與即時回饋來穩定他的執行節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3977, 'CSR_34', 'A (高)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「透明自制的穩定者」。他不靠話術拿對話，溝通時習慣把真實狀況攤開講，即使那對自己不利；遇到摩擦，他也不讓情緒先跑，而是把節奏壓下來再開口。在需要明確表態的場合，他給的是乾淨的立場而非策略性模糊；在衝突升溫時，他是少數能在透明度與穩定度都不打折的人。管理上他在資訊開放的環境最有效率，若要求他保留訊息或隱晦表達，他會出現明顯的不適感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3978, 'CSR_34', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「目的包裝的進取者」。他對結果有明確企圖心，遇到挑戰願意把方法與目標一路往上推；在這股強烈驅動下，他對達成路徑的底線相對有彈性，可能把選擇性揭露或包裝話術當作正常的進攻手段。具體情境裡，他常一邊全力把任務推到更高，一邊視需要管控別人收到的資訊版本。旁人感受到的是一個衝勁十足又難以完全讀透的人，管理上需要明確要求資訊透明度，否則他的成果導向很容易在不知不覺間越過溝通的誠信底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3979, 'CSR_34', 'C (低)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「算計周全的謀略者」。他行動前習慣把風險與後果評估到位，不輕易讓一時判斷造成返工；然而這份審慎也被用在規劃溝通策略上——哪些資訊釋出、哪些保留、哪個角度切入最能影響對方判斷，他都想在出手前想清楚。遇到複雜局面，他能冷靜拆解，也能在不確定中維持判斷品質；旁人感受到的是一個深思熟慮卻不完全透明的人，管理上宜要求資訊來源與論點的完整性，不只接受他給出的結論版本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3980, 'CSR_34', 'C (低)', 'CSR_24', 'A', '與 CSR_24 (謙虛) A聯動：表現為「低調操作的務實者」。他不太需要透過炫耀或壓過他人來證明自己，對他人貢獻的接受度也較平衡；在這個低自我中心的底色下，他推進目標的方式有時並不靠透明溝通，而是靠選擇性呈現資訊或用話術影響對方判斷。他的操作往往不帶明顯的自我宣示，旁人較難在第一時間察覺他在管控資訊。管理上，他謙遜的外表容易讓人忽略對他溝通透明度的要求，需要明確建立資訊完整揭露的期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3981, 'CSR_01', 'A (高)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「自發超越、全力推高標準的主動者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標；在各類情境中都能自發開啟行動並超越既定要求，缺乏明確指令也不影響投入。具體情境裡，他一邊把任務難度往上拉，一邊主動找職責範圍以外的事情去推進。在開拓性工作中獨立推進力極強，不需外部催動就能持續輸出；管理上宜設置清楚的邊界，讓這份主動衝勁集中在最高優先目標上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3982, 'CSR_01', 'A (高)', 'CSR_19', 'A', '與 CSR_19 (誠實謙遜) A聯動：表現為「守原則的高效能追求者」。他很想贏、願意為更好的結果多付出，而在他心裡，「贏」從一開始就內含一個條件：不能靠欺騙、佔便宜或踩到別人的方式去贏。對他而言誠正不是事後替衝勁踩煞車的另一隻手，而是他界定「什麼才算真正達成」時就含在裡頭的一部分。於是他拼得很猛卻不踩線，寧可多花功夫換取正當的成果。這種「猛而乾淨」的工作模式，在需要高度信任的角色——客戶端、跨部門合作——上，是特別可靠的訊號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3983, 'CSR_01', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「高壓下的焦慮衝刺者」。他對成果有強烈企圖心、想快速攻上更高的標準，偏偏他對模糊與未知又格外無法忍受。對這樣的人來說，路徑清楚時他衝得又快又猛；可是一旦目標不明、結果懸而未決，他並不會降低對自己的高要求，反而因為「失敗或迷路」對他代價感受更重，而陷入反覆確認、難以動彈的緊繃。於是他可能同時擁有很高的能量、卻在模糊專案裡推不動，形成內耗。對他最有效的，是給清楚的里程碑與階段回饋，把懸空感壓到最低，讓他的衝勁有明確的著力點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3984, 'CSR_01', 'A (高)', 'CSR_04', 'C', '與 CSR_04 (厭倦傾向) C聯動：表現為「目標清楚下的持久投入者」。他對工作有明顯企圖心，而且不太會因為任務單調重複就失去興致——在他身上，這兩點合成同一種特質：他在意的是事情有沒有往更好的方向前進，而不是過程有不有趣，所以重複、精細、長週期的活兒也消磨不掉他的勁。對他而言，「想做得更好」這件事本身就足以撐住投入，不需要靠新鮮刺激來續命。於是他特別適合那種需要長期專注、細節綿密的任務，能在別人覺得乏味的地方維持穩定而向上的產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3985, 'CSR_01', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「進取心強、手段彈性的衝刺者」。他對工作表現有明確企圖心，遇到挑戰傾向主動升級方法與目標；較容易把領先視為第一順位，在強烈競爭或目標壓力下可能合理化不公平手段或利用他人換取優勢。具體情境裡，他一邊把任務目標往上推，一邊在壓力情境下降低對手段正當性的門檻。推進力強、願接硬任務，在公平競爭環境中是高產出貢獻者；管理上宜設定清楚的行為底線，讓進攻動能沿著正確的軌道釋放。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3986, 'CSR_01', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「指標清楚時的主動推進者」。其成就動能在目標清楚、回饋可見時穩定投入，搭配對「自身能影響結果」的強烈信念，在這類情境下形成清楚可靠的推進模式；但當任務目標模糊或缺乏進展指標時，成就動能下降，而強烈的控制感卻使他仍試圖主動行動，導致能量散在多個方向而效率下滑。B 段屬情境敏感、非固定狀態；管理建議：確保任務指標清楚再交付，避免讓他在模糊期消耗過多主動行動的資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3987, 'CSR_01', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「遇阻容易放棄的條件型投入者」。他的投入本來就吃「看得到進展」這碗飯：目標清楚、回饋可見時他穩定使力，看不到進展時動能就偏弱。而他解讀挫折的方式又偏悲觀，容易把一次做不到讀成「我本來就達不到」。於是這是一個在順境裡還不錯、一遇阻礙就特別容易鬆手的人——少了「不順只是暫時」的那層底氣，他在動能本就下滑的關口會退得更快。對他而言關鍵不在加壓，而在阻礙期主動讓進展看得見、把難題拆成跨得過去的小步，替他補上那份「再試一下也許就成」的支撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3988, 'CSR_01', 'B (中)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「回饋可見才投入、不見則離的目標者」。在目標清楚、有進展回饋的情況下，他會穩定投入；若缺乏指標或看不到進展，動能容易下降；對所處環境的心理依戀與承諾較低，面對逆境或不利條件時傾向考慮離開而非堅守。具體情境裡，他一邊在回饋可見時認真推進，一邊在環境轉差時快速評估留下的意義。實務上他在順風期是可靠的執行者，逆境累積時流失風險升高；管理上宜保持目標與回饋的清晰度，讓承諾感有足夠的支撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3989, 'CSR_01', 'B (中)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「變動環境的彈性推進者」。他的投入需要看得到目標與進展，而他又把頻繁的變化視為理所當然、不需要特別調適。對這樣的人來說，環境怎麼變並不會直接動搖他——只要方向和進展還看得見，變動本身就只是日常背景。於是在「步調快速調整、但目標仍清楚」的情境裡，他是少數不會被動盪晃掉動能的人；組織處於高速轉型卻仍有明確任務指標時，他的輸出穩定度往往優於同段的人。真正會讓他熄火的，是變動大到連目標和指標都一起模糊掉的時候。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3990, 'CSR_01', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「動能與信心雙重依賴情境者」。他要有清楚目標和充足回饋才使得上勁，同時對自己能不能做好也常沒把握。對這樣的人，缺乏外部確認時最難熬：他既不確定「努力到底有沒有用」，也不確定「自己到底行不行」，兩種沒底氣其實是同一種「需要外界先給我訊號」的心理。於是一旦少了清楚指標或安全感，他的動能和信心會一起往下掉，特別容易卡在新任務的起步階段。對他最有效的，是在交付新任務時就同步給他初期看得見的小成功，縮短他起步時的摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3991, 'CSR_01', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「回饋驅動、逆境後難快速復原的目標者」。在目標清楚、有進展回饋的情況下他會穩定投入；若缺乏指標或看不到進展，動能容易下降；在長期高壓或連續變動下容易出現能量耗竭，補救與恢復較吃力，表現波動增大。具體情境裡，他一邊在順境中穩定推進，一邊在逆境累積後失去快速回彈的能力。管理上宜把任務拆成可見的里程碑，讓每個完成節點都能補充動能，降低逆境對持續性的衝擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3992, 'CSR_01', 'C (低)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「被動等待指令的基本完成者」。他既不會自己去追求更高的目標，也不會主動發起超出範圍的行動——對他而言，這其實是同一種「沒人推就不動」的底色：少了向上的內在拉力，也少了自發出擊的習慣，待機便成了他的預設狀態。於是他的行動幾乎只停在被交代的基本事項上，超越既定要求的事極少發生，他的貢獻多寡幾乎完全取決於外部把任務講得多清楚。對他需要的是明確的任務清單與固定的確認節點，用結構把他該做的範圍框出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3993, 'CSR_01', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「環境驅動但持續分心的低動能者」。他對更高難度的目標沒什麼追求，又特別容易對手上的活動失去興致——這兩點在他身上不是各自獨立的毛病，而是合成一種「既沒有往前的目標、又坐不住」的工作狀態：因為沒有目標牽引，他的注意力本就無處安放；因為一無聊就想換，他便不斷在各種活動間漂移以逃避乏味。結果是他啟動得快、轉換得頻繁，卻很難把任何一件事好好收尾，輸出呈現碎片化、低完成度。對他在需要完整交付的位置上風險明顯，需要用結構化的節點與清楚的完成條件把收尾率拉起來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3994, 'CSR_01', 'C (低)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「逆境不倒但目標不高的穩守者」。他面對逆境有充沛的內在資源可以緩衝、不容易被壓垮，但這份韌性並沒有把他變得更有野心——他依然傾向把工作做到夠好就停，不主動追求突破。於是這是一個「撐得住，但也不想要更多」的人：高壓環境裡他極少崩潰或放棄，能穩穩維持基本輸出，卻也不會把目標往上拉。對於需要長期承壓、但不要求創新突破的執行型崗位，他是難得可靠的穩定力量；若組織期待的是成長驅動，就得另外替他提供外部誘因。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3995, 'CSR_01', 'C (低)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「動能薄弱的雙重資源不足者」。他本來就不太追求更高的目標，加上希望、效能感、韌性、樂觀這四種正向心理資源全面偏低，於是他整個人透出一種普遍的無力感與對未來的低期待。在他身上，「達到合理範圍就好」的低動機，和「容易悲觀、不太相信自己」的薄弱心理底子，是同一種缺乏內在燃料的狀態——遇到任何挑戰都容易停滯、退縮或轉移責任，逆境裡恢復最慢，也很難從外部進展裡重新點燃自己。這是長期輸出穩定性風險最高的組合之一，強烈建議提供結構化的輔導與目標設定支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3996, 'CSR_01', 'C (低)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「疏離旁觀的低融入完成者」。他傾向把工作做到合理範圍就好，動機多半靠外部環境牽動；同時他也很難真切感受到自身興趣與價值觀在這份工作裡的份量，面對需要深度投入的場合傾向站在旁邊看。在他身上，這兩點其實是同一種「和工作只有工具性連結」的疏離：既沒有向上的拉力，也沒有把任務當成對自己有意義的情感歸屬，於是他的投入幾乎只停在維持功能運作的最低水準。這樣的人在需要主動學習、自發精進或長期承諾的崗位上風險偏高，比較適合邊界清楚、交付標準明確的執行型任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3997, 'CSR_01', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「目的導向的低要求運作者」。他對高標準沒什麼追求，把工作做到夠用就停；同時他也不太把溝通的透明當回事，傾向用包裝、選擇性揭露來達成目的。在他身上這呈現為一種行事方式：他既然不在意品質要不要真的更高，自然樂得用話術去填補做得不夠紮實的地方，讓成果「看起來達標」。風險就在這裡——他的輸出表面過關，實際品質卻可能長期低於外觀，而且因為他擅長包裝，缺陷不容易被及時發現。對他需要的是在驗收節點建立獨立的客觀品質核查，而不是依賴他的自我回報。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3998, 'CSR_01', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「結果為先的規範低依從者」。他對達成目標沒有強烈企圖，又把規範看成可以通融的工具——這兩點在他身上指向同一種行事傾向：既沒有「想把品質做得更好」的主動拉力，也沒有「該守的流程一定要守」的被動底線。於是當目標壓力一來或資源吃緊，他很自然會挑最省事的路走、跳過該走的程序。值得注意的是，因為他的成就驅力本就偏弱，他不太會是「為了追更高目標而踩線」那種人，反而更可能是「為了少做事而走捷徑」。在資源緊張或壓力大時，這樣的組合合規風險最高，需要用明確的底線規範與督核機制把他框住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (3999, 'CSR_01', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「守基本線、問題外歸的穩定達標者」。他傾向把工作完成在合理範圍，不一定追求更高難度或額外突破，動機更受環境支持與要求牽動；遇到失誤或延誤較容易歸因外部，補救動作相對被動，改進速度偏慢。具體情境裡，他一邊維持在環境要求內完成任務，一邊在問題出現時等待外部解決而非主動承擔。在穩定環境中是可靠的基本執行者；管理上宜設定清楚的完成標準與問責機制，讓他不停在基本線上原地踏步。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4000, 'CSR_01', 'C (低)', 'CSR_20', 'C', '與 CSR_20 (希望) C聯動：表現為「目標路徑雙缺的停滯型工作者」。他不追求更高的目標，也很難把「想達成」轉化成一條條可行的推進路徑——對他而言，這合成一種「不知道要去哪，也沒有很想去」的狀態：既缺乏主動設定高目標的意願，就算真給了他目標，他也難以自己生出替代的做法繞過阻礙。於是他在有明確指令時能完成基本事項，一旦碰到需要自行定方向、自己找路的情境就容易停滯或轉向。這是對外部指引依賴度最高的組合之一，在需要自主導航或獨立解題的場景裡，必須有非常紮實的任務結構與定期引導，他才運作得起來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4001, 'CSR_02', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「熱情待人話術用事者」。他在各類人際場合都能自然流露信任與熱情，面對新認識的人也不設防，關心與善意是真實的；遇到需要達成目標的情境，他習慣選擇性地呈現資訊，用包裝過的說法引導對方，而非直接攤開全貌。具體來說，他對人的注意力是真誠的——他記得對方說過的事、會在恰當時機表達關心——但在重要對話中他的措辭往往精心拿捏，哪些話說、哪些略過，都有盤算。旁人感受到的是一個讓人舒服的合作者，但若深入交手才會察覺他溝通的選擇性。管理上，讓他說清楚決策依據、核心數字或分歧點，能有效降低資訊落差帶來的誤判。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4002, 'CSR_02', 'A (高)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「可信賴的善意夥伴」。他在各類情境自然展現信任與熱情，同時即便想達成目標也拒絕欺騙或利用他人的手段——親和給了連結的溫度，公正給了連結的安全感。這使他的合作不只是討人喜歡，而是可被長期倚賴：善意有原則托底，不會因交情而徇私。可放心賦予需兼顧人和與公正的協調角色。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4003, 'CSR_02', 'A (高)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「無防備的善意者」。他在各類人際情境自然展現熱情，又以善意預設他人意圖、即使有負面經驗也很少收回信任——他在人際與信任兩面都幾乎不設防，合作極為順暢卻也最易被有心者利用。這是一種良性卻脆弱的組合：建議在涉及資源、承諾或敏感資訊的場合，由制度或他人替他補上一道盡職查核，而非依賴他自我設防。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4004, 'CSR_02', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「熱情開放衝動易燃者」。他對各類人際互動都帶著真誠的熱情，願意信任、願意投入，在團隊裡很容易讓人感到被接納；當情緒被觸發時，這份開放沒有緩衝，反應迅速且直接，衝動性的言行在壓力或衝突場合中容易出現。他在輕鬆狀態下是受歡迎的合作者，但在高張力會議或競爭情境中，他可能已經說出去了才意識到那句話帶來的代價。這種模式對周遭的影響是：氛圍好時他是凝聚者，氛圍緊張時他容易成為導火線。管理上，設計固定的緩衝機制（如讓他先離席再回覆）比事後糾正更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4005, 'CSR_02', 'A (高)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「穩定供能的支持者」。他在各類互動自然展現信任與熱情，又能對他人困境維持不被消耗的深度關懷——廣度與深度相疊，使他成為團隊裡持續供應協作與情緒支持的人。這對凝聚力極有價值，但也讓他最容易被過度依賴。建議主動為他設界並輪替支持負荷，避免長期單向消耗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4006, 'CSR_02', 'A (高)', 'CSR_07', 'A', '與 CSR_07 (法規遵從) A聯動：表現為「極致親善的避衝突者」。他自然展現信任與熱情，面對衝突又一貫以順從合作因應、極少對抗，在團隊中格外好相處、潤滑力強。風險在於必要的異議與壞消息容易被和諧需求壓下，問題可能延後浮現。管理上應主動創造安全發聲的機制，明確邀請他表達保留，而非假設沒反對就是沒問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4007, 'CSR_02', 'A (高)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「親切合作利益先行者」。他在人際互動中展現的熱情與信任是真實的，對人有好感、樂於助人，很快就能和新同事建立關係；一旦進入資源競爭的場景，他對利益、地位和外在象徵的敏感度同樣鮮明，較少對公平原則有強烈自我約束。在日常合作中，他是讓人信任的搭檔；在需要分功論賞或爭取資源時，他會積極確保自己不吃虧，甚至合理化先拿再說的做法。旁人有時會感受到這兩種樣貌之間的落差。管理上，明確訂定資源分配標準，能讓他把精力導向合作貢獻而非內部競爭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4008, 'CSR_02', 'A (高)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動熱情全方位投入者」。他對人際互動和任務推進都有真切的熱情：他信任他人、樂於協作，同時不需要別人授權就能自發開啟行動，方向不明也不會讓他停下。在沒有清楚指令的環境裡，他是最早動起來的人，也會主動把有意願的人招募進來；他的行動力和親和力讓他在早期推動階段很有優勢。潛在的張力在於，他的主動有時超過團隊準備好的節奏，或把自己的時間與精力分散在太多線上。管理上，讓他聚焦在有槓桿的方向，能讓他的投入帶出最大效益。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4009, 'CSR_02', 'C (低)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「預設不利的疏離者」。他在人際中傾向保持距離與戒備、面對合作易生猜疑，又以善意之外的不利意圖為預設——他在親近意願與信任基準上都偏低，因此極難被靠近、連結建立極慢。獨立、警覺、不易被話術左右是其長處，但置於高度互賴的位置會明顯摩擦。建議用清楚事實與一致行為逐步累積信任，避免搏感情式或施壓式的拉近。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4010, 'CSR_02', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「戒備疏離直接對立者」。他在人際上保持明顯的距離感，對陌生或不確定的互動傾向戒備，主動示好或展現熱情的場合很少出現；遇到意見不合或衝突時，他的回應是直接表達立場甚至爭辯，而非退讓或協調。他在需要建立信任和化解衝突的場景都處於弱勢：他不主動靠近，也不擅長軟著陸。他對周遭的影響是：協作關係難以自然建立，衝突容易升級而非化解。管理上，為他設計清楚的任務邊界與獨立運作空間，能減少人際摩擦；需要跨人協作時，則宜由外部橋接而非仰賴他自行建立關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4013, 'CSR_02', 'C (低)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「記恨的築牆者」。看懂他要從一點切入:他本來就沒有一個『信任』的起點。對人保持距離與戒備是他的預設,所以當他被冒犯,那不是從信任跌落、需要修復的傷口,而是替他早已半閉的門找到了關上的理由。也因此,他幾乎沒有想主動和解的內在拉力——放下對他不是『努力一下就做得到』,而是違反他看人的基本姿態。一道裂痕於是很容易固化成長期的疏遠,而不是有起有落的循環。這讓與他修復關係的成本特別高。管理上要趁早、正面處理摩擦,別讓誤會累積成『證據』;同時要理解,一旦他對某人收回信任,重建需要相當漫長且具體的過程,光靠時間或善意難以軟化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4014, 'CSR_02', 'C (低)', 'CSR_13', 'C', '與 CSR_13 (同理關懷) C聯動：表現為「冷靜抽離的旁觀者」。他在互動中保持距離與戒備，面對他人困境又情感平淡、傾向理性看待——他在親近意願與同理回應上都偏低，因此在人際與情感上都高度抽離。長處是不易被情緒與人情左右、能保持冷靜判斷；短處是缺乏協作所需的溫度與承接力。適合需要客觀抽離的分析或審查角色，但不宜放在以情感支持與關係經營為核心的位置。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4015, 'CSR_02', 'C (低)', 'CSR_17', 'C', '與 CSR_17 (溫和有禮) C聯動：表現為「疏離且嚴厲的批評者」。他對人的冷淡和他評價時的嚴厲,根出同一處:他既沒有想靠近對方的暖意,也沒有想替判斷包上一層緩和的衝動,於是他看到缺失就直接說、不修飾。問題是,因為他平時沒有累積任何溫度,別人接到這樣赤裸的評價時,手邊沒有別的線索可供解讀,很容易就讀成敵意。疏遠與尖銳對他是同一種傾向——清楚地看見問題、且不覺得需要把它裹起來。其長處是敢指出問題、不和稀泥;風險是團隊感到壓力、關係張力升高。管理上可借重其挑錯的眼光,但宜替其回饋加上結構與場合,並明確區分『對事』與『對人』以降低殺傷力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4016, 'CSR_02', 'C (低)', 'CSR_03', 'A', '與 CSR_03 (利他行為) A聯動：表現為「冷面熱心的低調付出者」。他在人際中保持距離與戒備、少展現熱情，內在卻有不因自身成本而退縮的付出意願——疏離壓低了表達的形式，無私維持了實質的行動，使他『不熱絡卻會出手』。這類人常被表面的冷淡低估其貢獻。管理上宜以實際行為而非互動熱度來評價他，並主動肯定其默默承擔，以免其付出被忽略而漸漸收手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4017, 'CSR_02', 'B (中)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「驗證後才靠近」。其合作善意本就視情境調節，他對他人信任偏低、又預設『意圖可能不利』，因此投入門檻更高、收回更早——對方意圖不明時明顯保留，須先證明安全才展現合作。關係建立較慢但一旦確立則穩定，新合作初期應預留較高的信任建立成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4018, 'CSR_02', 'B (中)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「察言觀色的條件合作者」。其合作善意本就隨對方意圖收放，他又傾向選擇性揭露與話術，因此在投入前先讀情勢、也盤算自己露多少底——善意是有的，但與自我保護式的算計交替出現。這在低信任或競爭情境是靈活的防身術，在需要坦誠協作時則可能讓人覺得難摸清底牌。管理上宜營造安全、低威脅的溝通環境，降低他啟動策略性保留的必要。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4019, 'CSR_02', 'B (中)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「有原則的審慎合作者」。其善意本就隨情境收放，但內在守著拒絕欺騙與利用他人的公平底線——使他的『保留』屬於審慎評估而非伺機自利。意圖不明時他會先觀察，一旦投入則恪守對等與規則。這是值得信賴的謹慎型協作者：建立關係需要一點時間，但過程乾淨、可預期。可放心交付需兼顧分寸與公正的把關工作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4020, 'CSR_02', 'B (中)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「穩住分寸的調節者」。其合作善意本就隨情境調節，他又有良好的情緒與衝動管理，因此這份收放出於冷靜判斷而非情緒反彈——面對摩擦他會暫緩觀察，卻不會翻臉或忽冷忽熱。這讓他在需要拿捏人際距離的場合顯得成熟可靠，互動節奏可預期。管理上可信任他自行掌握投入時機，無須過度介入其人際判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4021, 'CSR_02', 'B (中)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「審慎但有溫度的承接者」。其合作善意本就視意圖收放，但對他人困境的深度關懷穩定不退——對泛泛交往他謹慎觀望，對具體的苦難卻會越過保留主動承接。這形成『慢熟但暖』的樣貌：信任需要時間，真有需要時卻靠得住。管理上可借重他在關鍵時刻的支持力，但別誤把他初期的保留當成冷漠。B 屬情境敏感、非固定的調節狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4022, 'CSR_02', 'B (中)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「保留卻敢攤牌者」。其善意本就隨意圖收放，他面對衝突又傾向直接表達、不退讓——平時他收著觀察，認定該爭時卻會把分歧攤開、直球對峙。這讓他不至於壓抑真實意見，但摩擦情境下『收回熱情』與『正面對抗』可能一起出現，張力較明顯。管理上宜先釐清意圖與資訊以縮短其觀望，並把他的直接導向就事論事的辯論。B 屬情境敏感、非固定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4023, 'CSR_02', 'B (中)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「善意觀察利益敏感者」。他在一般互動中能展現合作與善意，但不是無條件開放——對方意圖不明時，他會先收一收，觀察後再決定投入多少；在涉及利益、地位或資源的場景，他的計算心明顯浮現，對公平與謙遜的自我要求較弱。在穩定、低競爭的環境裡，他是可靠的合作者；一旦進入有輸贏的局面，他會轉向保護甚至擴大自身優勢，選擇性地遵守規則。旁人有時難以判斷他的合作意願到底到哪裡結束、利益考量從哪裡開始。管理上，讓他看到合作對自身利益有正向連結，比要求他遵守公平原則更能驅動持續的協作行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4024, 'CSR_02', 'B (中)', 'CSR_03', 'A', '與 CSR_03 (利他行為) A聯動：表現為「慢熟但肯付出者」。其合作善意本就視情境收放，但內在有不因成本退縮的付出意願——親和的條件性決定他『何時開始投入』，利他的無私決定他『投入後給多少』。於是他慢熱、初期觀望，一旦建立信任便相當慷慨。管理上別被他前期的保留誤導，給予足夠的互動基礎後，他會成為可靠的實質支援者。B 屬情境敏感、非固定的調節狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4025, 'CSR_03', 'A (高)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「感同身受的無條件給予者」。他對他人的困境有強烈的情感捲入，看見需求時身體會先行動，理性評估留在後面。在高度消耗的情境中，他仍能維持體貼與付出，而非關上情感的閘門。周遭的人感覺他不是出於義務，而是出於真實的情感衝動。實務上他容易被需要幫助的同事或任務磁吸，管理上宜協助他識別界線，避免體力與精力過度透支。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4026, 'CSR_03', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「無私付出卻容易被利用的行動者」。他面對他人需求時自然投入，付出意願不因代價高而動搖；同時，他周遭可能出現把領先視為優先的人，容易把他的給予解讀為可借用的資源。他的體貼行為是真實的，但在不公平手段盛行的環境中，他的不設防使他容易承擔過多。管理上宜明確劃定分工邊界，讓他的付出指向有意義的任務而非被動吸收他人的漏洞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4027, 'CSR_03', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「慷慨付出但對他人保持警戒的矛盾者」。他給予的行為是真實且不計代價的，但他不會因為付出而全然開放自己的信任。在實際互動中，他一邊伸出援手，一邊留意對方是否可能辜負他；這使他的關懷感覺真誠，但又不容易進入完全放鬆的合作關係。長期下來，若周遭的合作者未能通過他的觀察門檻，他可能持續給予卻保持距離，管理上宜協助他找到適合的盟友，讓付出有回應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4028, 'CSR_03', 'A (高)', 'CSR_02', 'C', '與 CSR_02 (親和性) C聯動：表現為「主動付出但人際疏離的給予者」。他對他人的需求有敏感的行動反應，付出的意願不隨個人成本而退縮；但在人際連結的層面，他傾向保持距離，較少展現信任或熱情。旁人感受到他是個會出手幫助的人，但不容易感覺到溫度或親近感。在需要既付出又建立關係的任務情境中，他的行動力充沛，但情感互通的部分需要有人持續搭橋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4029, 'CSR_03', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「願意犧牲但遇衝突會直接表態的行動者」。他在需要付出的情境中給得乾脆，不因個人成本而退縮；但在意見分歧或利益衝突浮現時，他不選擇退讓，而是直接亮出立場。這讓他在沒有衝突的情境裡顯得溫暖主動，一旦進入對立局面，態度的轉換幅度可能讓周遭的人感到意外。管理上宜建立清楚的意見溝通管道，讓他的付出精神和直接性格都有合適的出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4030, 'CSR_03', 'A (高)', 'CSR_19', 'A', '與 CSR_19 (誠實謙遜) A聯動：表現為「誠正節制的無私給予者」。他的付出不以個人成本為計算起點，也不以建立形象或換取特權為終點。面對利益衝突或目標壓力，他仍維持公正誠懇的態度，付出的動機是純粹的。周遭的人感受到他的幫助帶有信賴感，因為他不會在付出之後轉頭要求回饋或拿來當談判籌碼。實務上他在需要誠信合作的高壓情境中表現穩定，是建立長期信任的良好基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4031, 'CSR_03', 'A (高)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動超越的無私驅動者」。他的行動力與付出意願幾乎同步運作，察覺到需求後不等指示便開始投入，且不受個人成本或支持不足影響。他常在職責邊界之外主動補位，周遭的人發現他做的事往往比被要求的多，且幾乎不強調自己多做了什麼。實務上他在資源有限、需要主動補漏的情境特別有價值；管理上要留意他不容易開口提醒自己已到達疲乏點，宜主動確認他的負荷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4032, 'CSR_03', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「帶著焦慮付出的過度照料者」。他不因個人成本退縮的利他傾向，加上對不確定性的強烈負面反應，使「不知道對方是否需要幫助」本身成為驅動付出的焦慮源——他的給予有時反映的是消除自身不安，而非對方的實際需求。此組合在高頻協作環境中容易造成過度介入，建議引導其在付出前確認對方需求，而非以主動出擊來化解自身的模糊感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4033, 'CSR_03', 'A (高)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「持續給予但難以深度融入的旁觀者」。他的付出行為是真實且主動的，對個人犧牲不設防；但他對所在環境缺乏深度融入感，較難從歸屬感中汲取動力。在需要幫助的任務場景，他是可靠的行動者；在需要展現對組織或群體的心理連結時，他卻容易顯得疏離。實務上他的貢獻有其穩定性，但長期投入仰賴外部有意義的連結點，而非內建的歸屬感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4034, 'CSR_03', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「有分寸的關懷型進取者」。他在日常互動中展現體貼與關心，遇到不需要大幅犧牲的幫助需求會自然投入；同時他對成果有明確的企圖心，主動把方法和目標往上推。當兩者出現資源競爭，他通常選擇不讓關懷行為干擾自己的推進節奏，體貼的範圍會隨任務壓力收縮。在績效回饋清楚的環境他最有動能，管理上可善用他的自驅力，同時保留讓他關注他人的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4035, 'CSR_03', 'B (中)', 'CSR_13', 'C', '與 CSR_13 (同理關懷) C聯動：表現為「按情況給予但情感投入有限的協助者」。他在日常互動中展現體貼與關心，遇到個人犧牲較大的需求會評估後再決定投入程度；面對他人困境時，他不容易自發產生強烈的情感共鳴，關懷更多是理性判斷的結果。行動上他可以提供協助，但那份協助缺乏情感驅動的溫度。在需要實質解決問題的情境中他有價值，但在需要情感支持的互動中，他可能讓對方感覺到一種禮貌性的距離。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4036, 'CSR_03', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「自身有限的關懷者」。當一個人既是適度關懷、付出大時會評估投入，又在面對困難壓力時內在緩衝資源有限、容易受負面影響，他的善意就帶著明顯的天花板：他願意在日常付出體貼，但他自己也是個在逆境中容易被耗損的人，所以當情況變得艱困、需要他高強度地撐住別人時，他往往同時也在勉力撐住自己。這代表他的關懷在風平浪靜時穩定可親，一旦壓力升高，他的投入會因為自身韌性吃緊而縮減——不是不願意，而是他的儲備本就不厚。這種人不適合被當成危機時的單一支柱。建議在高壓情境替他預備外部支援，讓他不必在照顧他人與保全自己之間獨自硬撐，也避免他因過度透支而崩盤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4037, 'CSR_03', 'B (中)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「保有關懷但可能包裝表達的協助者」。他對他人有真實的關心傾向，在日常情境中願意付出體貼；但面對競爭或有利益的情境，他可能選擇策略性地包裝自己的協助行為，讓表面的給予也兼顧自身目標。他的幫助是存在的，但接收端不一定能完整讀到背後的動機。在需要信任基礎的長期合作中，這種不完全透明的模式可能使人對他的關懷產生疑惑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4038, 'CSR_03', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「評估後主動出手的務實關懷者」。他在日常中展現體貼，遇到需求不缺席，但他的付出決策帶有清楚的可行性評估；他相信自己能影響結果，所以在有效的地方投入，在無法著力的地方不做無謂消耗。他的關懷行為有時會讓人感覺精算，但本質上是真實的——只是配合著他對局面的掌控判斷在運作。管理上給他清楚的施力點，他的付出行為會更充分展現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4039, 'CSR_03', 'B (中)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「願意關懷但也在意被看見的協助者」。他對他人有真實的關懷傾向，日常中展現體貼；同時他較傾向強調自身貢獻，被看見對他不是小事。當給予行為能帶來清楚的貢獻歸屬，他的投入度最高；若付出的成績被埋沒或歸到他人，他的關懷行為會在評估後收縮。實務上他在功勞分配透明的環境表現最穩定，管理上宜把貢獻認可做到清楚，避免因功勞模糊引發張力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4040, 'CSR_03', 'B (中)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「容易失去耐心的日常關懷者」。他在日常中展現體貼與關心，但他的注意力很難在單調情境中維持，厭倦感一旦出現，關懷行為的持續性就受到影響。他的付出在有活力、有變化的互動場合最充分，在需要長時間重複投入的情境則容易消退。管理上若要讓他的關懷行為持續發揮，宜設計有節奏變化的工作環境，讓他的刺激需求與付出意願能同時被滿足。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4041, 'CSR_03', 'C (低)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「感受得到但行動優先自身的旁觀者」。他對他人的痛苦有敏感的情感共鳴，那種感受是真實的；但他的行動邏輯仍以自身利益為優先，情感的觸動不容易驅動他做出個人犧牲。他能感受到你需要幫助，也可能表達同情，但真正涉及他要付出代價的行動，他通常會停在評估的位置。對周遭的人來說，這個人理解你、但不太會動員自己幫你解決問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4042, 'CSR_03', 'C (低)', 'CSR_07', 'A', '與 CSR_07 (法規遵從) A聯動：表現為「順從環境但不主動給予的配合者」。他在衝突或紛爭中傾向以溫和順從的方式回應，較少出現對抗；但這份溫和不是來自想付出或照顧他人，而是對抗帶來的不適讓他選擇退讓。面對他人的實際需求，他的行動仍以自身利益為起點，主動體貼或犧牲不是他的自然反應。旁人在衝突情境中感覺他好說話，但若真的需要他付出代價，往往發現他的彈性到此為止。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4043, 'CSR_03', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「自我優先且手段傾向的利益者」。他面對他人需求時的第一反應是自身利益評估，較少主動展現體貼或犧牲行為；同時，他對用不公平手段換取優勢的接受度也較高，把領先視為優先順位。在競爭情境中他顯得強勢且靈活，但在需要合作信任的環境中容易引發摩擦。管理上若安排他進入高度協作的任務，宜設計清楚的誘因結構，讓對他有利和對群體有利的方向一致。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4044, 'CSR_03', 'C (低)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「自我保護且持有怨念的內斂者」。他對他人需求的自然反應是優先考量自身，體貼或犧牲的行為不是他的起點；同時，他面對過去的冒犯或傷害不容易釋懷，恢復信任需要漫長的時間。這讓他的人際關係傾向收縮——不主動給予、又難以復原受損的連結。在需要長期合作或修復關係的情境中，他需要明確的情境重設與足夠時間，管理上宜避免讓他長期暴露在衝突未被處理的環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4045, 'CSR_03', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動行動但目標指向自身的發動者」。他的行動力十足，在各類情境中都能自發開啟任務，不需要外部催促；他面對他人的需求時，優先考量的仍是自身利益，主動精神的動能更多指向個人目標而非關懷他人。在需要主動推進的任務情境中，他是有效的行動者；在需要團隊互助的情境中，他的主動力量不太會自然流向補位他人。管理上宜設計讓他個人利益和團隊目標對齊的機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4046, 'CSR_03', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱情近人但行動優先自身的互動者」。他在各類人際情境中都能自然展現信任與熱情，面對陌生互動也不例外；但他對他人需求的行動回應，仍以自身利益為優先考量。這讓他給人的感受有一種落差——進入關係容易，感覺有溫度，但當你真的需要他做出犧牲，他的實際行動比他的態度保留得多。在高度仰賴互助的環境中，這種落差可能引起周遭的期待錯位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4047, 'CSR_03', 'C (低)', 'CSR_17', 'A', '與 CSR_17 (溫和有禮) A聯動：表現為「待人溫和但不為他人犧牲的禮貌者」。他在各類互動中保持溫和寬容的態度，較少做出嚴厲評斷，互動表面上讓人感覺好相處；但面對他人的實際需求，他的行動仍以自身利益為優先，溫和的風格不等於主動體貼或犧牲的意願。旁人感覺他不難相處，卻發現在需要他真正付出的時刻，他的好脾氣到此為止。管理上若需要他的協助，宜明確告知而非期待他自發感知並行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4048, 'CSR_03', 'C (低)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「對自身成果負責但對他人需求保留的行動者」。他對自己負責的任務有強烈的承擔意願，遇到問題主動追根究柢、補救到位；面對他人的需求，他的行動優先考量自身利益，體貼或犧牲不在他的自然反應範圍內。這讓他在個人績效上是可靠的，在需要協作補位的情境則需要明確分工才會動作。管理上宜把需要他協助的事明確歸屬為他的責任邊界，讓責任感機制自然啟動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4049, 'CSR_03', 'C (低)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「對組織忠誠但對同事需求保留的留守者」。他對所在組織有強烈的依戀與奉獻，逆境中仍願意堅守共進退；面對他人的個別需求，他的行動邏輯仍以自身利益為優先，體貼或犧牲不是他對周遭的自然反應。他忠於組織但不特別關懷同事，在需要上下一心的困難時期有其穩定性，但在需要橫向互助的場景中貢獻有限。管理上若要激活他對他人的協助，宜把這份協助與他對組織的承諾連結，讓他感覺是在兌現忠誠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4050, 'CSR_04', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「高期待卻快速熄火的達標者」。這是一個把『做到合理範圍』當成完成定義、不會自己往上加碼的人，而他的內在投入又會在任務還沒做完前就快速消退。於是他心裡常同時存在兩個聲音：一個說「交差就好，不必更好」，另一個說「這件事已經沒意思了」。因為他既沒有把標準自動拉高的習慣，又留不住對眼前工作的興趣，產出就自然停在勉強可用、且越往後越潦草的位置——不是抗拒，而是熱度先散、底線也跟著鬆。管理上若想讓他穩定交付，得把任務切成密集的進度節點並即時給回饋，讓外部要求接手他自己提不起的那部分動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4093, 'CSR_05', 'C (低)', 'CSR_15', 'C', '與 CSR_15 (遵循指示) C聯動：表現為「堅守現有框架的獨立反抗者」。他對變化有不適，同時對既有指示的配合度偏低，呈現獨特的張力——他傾向維持習慣做法，但這種堅守並非來自遵從，而是來自自主偏好。外部要求他改變會遇到阻力，外部要求他配合規則同樣會遇到質疑，形成頑強的獨立路線。在需要標準化或轉型的情境中，他是最需要個別說服的角色；建議以協商與論述取代指令，讓他在接受新做法前先感受到自主性被尊重。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4051, 'CSR_04', 'A (高)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「找不到歸屬感的旁觀者」。這個人本來就很難真心覺得某件事跟自己的興趣或價值有關，又留不住對活動的投入；所以當他坐在一個需要深度參與的場合裡，浮現的第一個念頭往往是『這跟我有什麼關係，何必這麼認真』。對他而言『沒意思』和『不屬於我』根本是同一種感覺的兩種說法——既不覺得這是自己的事，自然也不會在這上面投入心神。結果他在長期、需要持續在場的任務裡傾向最低限度地出席，刺激一退就抽身。要讓他留得住，得把工作拆成短週期、看得見成果的小段，並在很早就讓他感覺到這個角色與他本人有具體連結。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4052, 'CSR_04', 'A (高)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「刺激流失的鬆散者」。他對活動的新鮮感消退得很快，投入感常在任務還未完成時就已先一步流失；自我監控也不是他的強項，節奏一旦中斷很難靠意志力拉回。具體工作時，他容易在中途反覆停下，不是不想完成，而是對當下的任務已感到陌生的倦意，動作越來越慢，收尾越拖越久。旁人看到的，是一個開頭時還算投入、到後段卻明顯鬆脫的人。實務上安排他做需要持續專注的長任務風險較高，任務切成短循環並定期換換形式，能幫助他維持較穩的完成率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4053, 'CSR_04', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「逆境中先倒的快速放棄者」。這個人面對壓力時內在儲備有限、容易被打擊動搖，而他對手上的事又留不住熱度。所以困難一出現，他的解讀很快滑向『這不值得繼續』——一方面是真的撐不住，一方面是本來也沒那麼想做。對他而言『撐不下去』和『不想再做』幾乎同時到位，於是放棄這個選項在他心裡的阻力極低，往往在最需要堅持的關頭就先退場、也很少回頭補救。在需要長期硬撐的高壓任務裡，他需要外部的韌性支撐（階段性成果確認、同伴配對），把退出的時點往後拉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4054, 'CSR_04', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮驅動的高速轉換者」。這個人對不確定極度敏感，模糊的局面會讓他焦躁地想立刻把事情弄清楚；可是他對任何單一動作的興趣又消退得很快。於是他陷在一種彆扭的內在狀態：急著想確認、卻又受不了確認過程的枯燥。實際表現出來，就是在模糊任務裡焦慮地高速切換——確認一項馬上跳下一項，注意力碎成片段，常在某件事還沒查清就因為膩了而擱下、轉去別處。結果是動作很多、完成度很低，模糊的事情始終懸著。要讓他收斂，得事先把確認步驟結構化，並把每一輪要查的範圍縮到很小，讓焦慮有出口、又不至於撐到他厭倦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4055, 'CSR_04', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「等待刺激的被動出席者」。這個人不太會自己發起行動，習慣等別人開口；而他對眼前的事又很快感到無聊。這兩點疊在他身上，呈現的是一種徹底的低能量待命：他既不會主動去找點什麼讓自己重新有勁，遇到無聊也只是任它蔓延，反正他本來就不打算自己動。即使被指派了任務，他也只做到最低限度，交完就退回等待。整個過程他幾乎全程被動，沒有外部催動就會快速掉出節奏、安靜消失。要他維持輸出，得在任務全程鋪設密集的外部驅動節點，並在每個節點當場確認下一步該做什麼。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4056, 'CSR_04', 'A (高)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「短期吸引力的易動者」。他對無聊的忍受力本來就低，任何活動一旦少了即時的刺激便覺得難以持續；同時，短期誘惑對他的拉力遠比長期目標更強，兩個感受在他身上同時運作。在一天的工作裡，他常常從一件事跳到另一件讓他當下更有感的事，計畫裡的任務反覆被推後；到了下班前，手上有幾件事都做了一半，卻沒有一件做完。實務上給他做事要有短週期的收束點，讓他每隔不久就能看見「做完了一件」，否則長任務對他而言容易變成一個無解的長期誘惑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4057, 'CSR_04', 'A (高)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「條件不佳即離的流動者」。這個人對所處環境的心理依戀很淡，一遇不利就先想到離開；而他對日常事務的興趣又留不住。對他而言，『離開』本來就是隨時放在桌上的選項，而頻繁的無聊正好不斷給他遞上『反正也沒意思了』這個按下選項的理由。所以只要環境一單調、條件一變差，他評估去留的反應就比別人來得早。環境穩、刺激足時他勉強留守，一旦逆境或乏味出現，留任意願就明顯鬆動。組織在逆境期、轉型期要預先管理這類人的流失風險，平穩期也得持續注入新鮮刺激，把他重新評估去留的時點往後推。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4058, 'CSR_04', 'A (高)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「偏好穩定卻又快速厭倦的困局者」。這個人把穩定、可預測當成理想，變化或未知會讓他不安；可是穩定帶來的重複，又正是最容易讓他感到無聊的東西。於是他活在一個自相矛盾的處境裡——他追求的東西恰好會生出他最受不了的感覺。想要安定，安定卻讓他發悶；想擺脫無聊得求變，求變又讓他焦躁。他常在『穩定讓我無聊、變化讓我不安』之間來回擺盪，很難穩穩往前推進：在穩定環境裡抱怨無趣，在變動環境裡又渾身不對勁。管理上不該逼他擁抱大變動，而是在他熟悉、可預期的框架內安排適度的任務輪換，讓節奏仍可掌握、又有足夠新意化解那份悶。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4059, 'CSR_04', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「以挑戰維持動能的進取者」。他在任務有新穎感與難度時能保持相當的投入，對表現的企圖心也讓他在挑戰期間願意多給力一點。實際上，這個人在拿到高難度任務的前段表現最突出，不斷把方法和目標往上推；然而一旦任務進入執行後段、重複的動作多過新鮮的判斷，他的動能便開始洩漏，容易把注意力轉向其他更有新鮮感的事。管理上讓他做突破型任務比讓他守維持型任務更能發揮，並在交棒前確認他確實做好收尾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4060, 'CSR_04', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「自信推進但刺激耗盡即退」。這個人深信自己能左右結果，遇到新局面會立刻動手掌控；而他的投入又仰賴挑戰與未知。對他而言這兩點構成一個有點諷刺的循環：他越是迅速把陌生的問題摸透、納入掌握，那個問題對他就越失去新鮮感——而失去新鮮，正是他開始覺得無聊的時候。所以在開創、解決新問題的階段他貢獻突出、充滿動能；可一旦問題被『搞定』、進入例行維持，他的動能就失去了著力點，眼睛開始飄向下一個新問題，有時還會因此分神、放掉手上已掌握的事。適合交替安排開創性任務，而不是讓他長期守著一個已經解決的攤子。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4061, 'CSR_04', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「刺激不足時雙重打擊的停滯者」。這個人對自己能不能達成目標常沒把握，碰到挑戰先遲疑；而他的投入又得靠任務本身有挑戰、有回饋來維繫。麻煩在於，正是那種單調、看不到回饋的活動，會同時戳中他兩處軟肋：沒有回饋，他既得不到『我做得到』的確認，也得不到讓自己提神的新鮮感。於是他內心是一種『不知道自己能不能做到，也提不起勁去試』的複合卡住——越沒把握就越不想費力求證，越無聊就越懷疑這值不值得做。在缺乏反饋的例行任務中他幾乎停擺，表現為明顯拖延、過度請示、輸出縮水。此時需要把任務拆成極小、可驗證的步驟，每一步都給即時回饋，同時補上他缺的把握與刺激，否則事情容易整個懸空。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4062, 'CSR_04', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「挫折後快速放棄的悲觀退出者」。這個人習慣把不順讀成長期、普遍、難以翻盤的；而他的投入又得靠任務有挑戰、有回饋撐著。當任務恰好單調又看不到回饋，他內在發生的是一件整合在一起的事：枯燥讓他本就稀薄的動能更難維持，而悲觀又替這份提不起勁找到一個聽起來很合理的結論——『反正繼續也不會變好』。於是『不想做』和『做了也沒用』在他心裡合成同一個結論，要他再試一次的門檻變得極高。一遇阻礙或回饋缺口，他很容易迅速轉向悲觀預期並退出，在新專案的摩合期、低成果期特別脆弱。這類人需要外部主動提供進展框架——明確指出已完成的子步驟——用看得見的進度，去頂住那個『繼續也沒用』的念頭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4063, 'CSR_04', 'B (中)', 'CSR_30', 'A', '與 CSR_30 (心理資本) A聯動：表現為「資源充沛下能穩住的有條件投入者」。這個人帶著相當的希望、效能感、韌性與樂觀，挫折在他眼中多半是可以處理的問題、卡關時也找得到替代路徑；而他的投入則需要任務本身有挑戰、有回饋來維繫。把兩者合在一個人身上，呈現的是一種『有條件的耐久』：在有挑戰、回饋看得見的任務段，他靠這份心理底氣穩穩推進，比一般刺激依賴者更晚才覺得膩、更不容易被卡關打退。但他的正向資源解決的是『遇挫折怎麼辦』，補不了『活動本身太單調』這個洞——所以任務一進入長段的低刺激例行，那份底氣能延緩、卻擋不住投入慢慢下滑。規劃上應在低刺激段主動注入新的變量，給他的正向資源一個能持續發揮作用的對象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4064, 'CSR_04', 'B (中)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「無聊觸發衝動的高風險決策者」。這個人本就容易被情緒推著走、來不及多想就反應；而他的投入又得靠任務有挑戰、有回饋來撐。當工作陷入長段單調，他心裡會積起一股『非得做點什麼改變不可』的躁動——這正是他最受不了的悶。問題是他幾乎不會在這股躁動和行動之間留一個緩衝去審視，於是悶很快就直接外化成行動：臨時改方向、打斷別人的節奏、倉促拍板。在新鮮夠多時他還算受控，越是穩定執行、低刺激的時段，他的行動品質越糟，事後常要別人收拾。穩定執行期反而是最需要外部節奏管控的高風險節點，目的就是替他補上那個他自己缺的『先停一下再做』。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4065, 'CSR_04', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「意志驅動的穩定挑戰者」。他在多數活動中自然維持投入，較少因為任務變得單調就感到難以為繼；對表現的企圖心讓他願意在各個階段都多給一點力。在實際工作中，他常常是那個從頭到尾都投入、在挑戰升高時反而更積極找方法的人，而不是任務平淡了就開始鬆脫。周遭人觀察到的是一個穩定輸出且願意把目標往上推的人；讓他帶有難度又需要持久投入的任務，通常能有不錯的完成品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4066, 'CSR_04', 'C (低)', 'CSR_06', 'A', '與 CSR_06 (承諾) A聯動：表現為「深度融入的穩定承諾者」。這個人對自己的興趣與價值有穩固的認同，無論環境順逆都能全心融入；而他又不太會因為缺少新鮮刺激而對所在的事感到厭倦。對他來說，這兩件事其實是同一種『把自己放進去』的安定：他打從心裡認這是自己的事、覺得有意義，所以投入；又因為投入得起來、不容易膩，這份認同就不會隨時間被磨淡。於是他在需要長期、深度融入的任務或關係裡能持續在場，即使進入平穩期也不會輕易抽身——別人靠新鮮感維繫的東西，他靠的是內在的歸屬。在長期合作、複雜專案、需要持續在場的角色裡，他展現高度可靠，適合擔任跨週期的整合者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4067, 'CSR_04', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「自律托底的長線穩定者」。他在各類活動中都能自然維持投入，外部刺激是否充足對他的節奏影響不大；加上做事有一貫的自我要求，進度與品質從頭到尾都能維持在水準之上。在工作中，他是那個即使任務進入沉悶的執行期也不掉鏈子的人，品質管控與收尾都交給他放心。遇到需要長時間穩定輸出的任務，他的可靠度特別突出；管理上給他清楚的目標範圍，他通常不需要太多外部催促就能完成。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4068, 'CSR_04', 'C (低)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「壓力累積卻仍留守的耗損者」。這個人面對壓力時內在資源有限、容易被負面影響打垮；可他偏偏又不容易對手上的事失去投入、不會主動抽身。這組合在他身上長出一種危險的安靜：他把『留下來、繼續做』當成理所當然，即使能量已經見底也照樣撐著——但這份留守底下沒有真正的韌性托著，與其說是『打不倒』，不如說是『走不了』。外人看到的是他在高壓環境裡比別人留得更久、依舊在崗，於是容易誤判他狀態良好；實際上他的損耗也比別人更深，往往要到接近崩潰才被察覺。組織不能憑他『還在、還在做』來判斷，得主動盯實際指標——輸出品質的趨勢、他自我回報的能量水平——才看得見表面平穩下的累積耗損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4069, 'CSR_04', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「內心警覺卻持續行動者」。他在日常任務中能自然維持投入，不容易因缺少新鮮感就掉落；然而只要任務裡出現不明確的環節，強烈的焦慮感便同時浮現，讓他在投入時帶著一層持續的警覺。具體工作時，他一邊穩定推進，一邊對每個說不清楚的地方反覆確認，哪怕已有初步答案也難以完全放心繼續走。旁人看到的是一個能持續做事，但在資訊模糊時需要被多解釋一輪的人；管理上給他清楚的任務邊界與可查閱的說明，能幫助他把焦慮控制在不干擾節奏的程度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4150, 'CSR_08', 'C (低)', 'CSR_15', 'C', '與 CSR_15 (遵循指示) C聯動：表現為「鬆散且不易配合的執行風險者」。他在自我監控與節奏維持上較吃力，同時對既有指示與規定的配合度偏低、傾向質疑程序要求；盡責薄弱已需要外部結構補位，但低配合度又讓結構工具的效用大打折扣。這是需要最密集個別化管理的組合，建議以雙向協議取代單向指令，讓他理解並認同後再執行，以降低抗拒成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4070, 'CSR_04', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動自發且持久投入的推進引擎」。這個人不等指示就會自己起頭、做超出要求的事；而他又能在多數活動裡自然維持投入，不靠新鮮刺激撐。在他身上，這不是『一個負責點火、一個負責續航』的兩段式，而是一種一以貫之的主動：他從頭就有自己動起來的衝勁，而這股衝勁因為他不容易膩，能一路燒到任務尾端而不在過了新鮮期後熄掉。於是他在整個任務週期都主動、輸出穩定、常常超標，即使缺方向、缺支持也能獨立往前推。這類人適合放在資源或方向都比較模糊的開創性情境，給他充分的自主空間去發揮——他本身就是那台不太需要外推的引擎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4071, 'CSR_04', 'C (低)', 'CSR_33', 'A', '與 CSR_33 (自律性) A聯動：表現為「沉穩持守的長期執行者」。他在多數活動中都能自然維持投入，不需要持續的新鮮刺激才能做下去；延遲滿足的習慣讓他在面對枯燥的執行段落時，也能把短期誘惑放到一邊，繼續按計畫走。在實際工作中，他是那種把長任務從頭做到尾、中途不輕易鬆動的人，即使工作內容逐漸重複，他仍能維持水準的品質直到完成。這類型的人特別適合需要長週期、穩定輸出的工作；管理上只要給清楚的方向，他自己會找到推進的節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4072, 'CSR_04', 'C (低)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「逆境留守的高忠誠投入者」。這個人對所處環境有強烈的心理依戀，即使逆境也願意共度；而他又能在多數活動裡自然維持投入，不太會因為缺乏新鮮刺激而對工作本身失去興致。把兩者合在一個人身上，他的留守就不是常見那種『有感情、但其實已經做得很勉強』，而是依戀和投入同時在線：他既因為認同而不想離開，又因為對手上的事仍有真實的興趣而留得心甘情願。所以在組織逆境期，他展現的是一種少見的穩定——人在、心在、動能也在，不只是被責任綁著的被動留任。這種長期留任又持續有效的搭配相當稀缺，組織應主動辨識並好好珍惜。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4073, 'CSR_05', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「表面躍躍欲試的內在焦慮者」。他相信變化是常態並主動尋求新情境，但對不確定性的高度敏感同時存在，使他持續把自己推進難以真正平靜接受的模糊處境。外顯上看起來積極，但內在焦慮不斷消耗資源，多重變化疊加時情緒狀態容易崩盤。建議在他主動承接高不確定任務時，主動協助他建立確認機制與階段節點，以降低持續懸空的心理耗損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4074, 'CSR_05', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「在動盪中不斷升級目標的進取者」。對他而言，『環境在變』和『我要做得更好』並不是兩股各自運作的力——每一次局勢變動，他幾乎是同一瞬間就把它讀成可以把標準再往上推的缺口。正因如此他不等局勢收斂就出手，因為不穩定的局面在他眼裡本來就等於機會本身。這讓他在高度動態的環境中轉換極快，但同樣的閱讀方式也使他容易在方向尚未明朗時就鎖定目標，把變動底下的風險一併讀成了機會。建議在全力衝刺前替他補一個風險檢查點，確認方向可行再投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4075, 'CSR_05', 'A (高)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動把變局轉為自己牌局的行動者」。他對變化毫無阻力，同時對「自己能影響結果」有穩定信念，在局勢流動時不只是適應者，而是試圖主動左右走向的人。這種特質在需要快速決策並帶領方向的情境中極具優勢，但也容易高估可控範圍、做出超出實際掌控的承諾，需留意設定邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4076, 'CSR_05', 'A (高)', 'CSR_26', 'A', '與 CSR_26 (條理性) A聯動：表現為「以秩序駕馭變動的執行者」。他在頻繁變動的環境中自然找到節奏，而非等待局勢穩定。做事時他習慣把不確定的走向轉化成具體步驟與排程，讓流動的狀況有可依循的骨架。遇到方向調整，他第一反應是重新整理任務清單、釐清分類，而非消化焦慮。這使他在快速迭代或頻繁轉換任務的環境下仍能維持輸出品質；但在極端混亂或結構根本無法建立時，他的動能會受到較大考驗。管理上宜給他足夠的空間自訂工作節奏，避免外部干預打亂他已建立的秩序架構。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4077, 'CSR_05', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「以變化消解厭倦的刺激追尋者」。他不是『需要新刺激的人』再加上『能輕鬆切換的人』——讓熟悉的事物在他眼裡迅速褪色的那股不安，和讓新情境對他顯得鮮活的，其實是同一種心理。所以他幾乎沒有靜止狀態：新局面讓他全心投入，熟悉之後投入感同樣快速消退，往往在前一件事還沒收割成果時，他已經被下一個變化吸走。這讓他在高變動環境裡是天然的適應者與發起者，卻在穩定期最難留住。建議在需要鞏固成果的階段，替他設計清楚的短期里程碑，讓『把一件事完成』本身能短暫地重新點燃投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4078, 'CSR_05', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「主動迎變卻易耗竭的衝鋒者」。他天然地把變動視為工作的正常樣態，遇到環境調整不需要動員意志力去接受。然而在持續的高壓與接連不斷的改變中，他的恢復速度跟不上消耗的速度，表現波動會逐漸浮現。旁觀者可能以為他適應力強、不需要特別照顧，但他自己承受的耗損早已在悄悄累積。一旦他開始出現遲滯或品質下滑，往往已是耗竭中後期。管理上宜在任務轉換頻繁的階段主動設置緩衝期，並提早留意他的恢復狀況，而不是等到明顯失常才介入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4079, 'CSR_05', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「擁抱變化卻易悲觀解讀挫敗的探索者」。他對變化本身不設防，主動走入不確定的環境，能自然從流動中找到動能。但他在事情出了差錯時，卻傾向把挫折解讀為根深蒂固、難以扭轉的訊號，讓繼續行動的意願迅速消退。這形成一種落差：開始新嘗試時動能充沛，一旦出現阻礙便預期結果已定，前進的步伐變得猶豫。在看得見進展的環境中他表現活躍；一旦碰壁，需要外部確認才能重新評估情況而非鎖定失敗解讀。管理上宜在他受挫後提供明確的改善脈絡，幫助他區分暫時困難與長期障礙。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4080, 'CSR_05', 'A (高)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「隨變化漂流、卻找不到落腳點的移動者」。他對外部變動有很高的接受度，情境頻繁改變對他不構成壓力，切換幾乎無摩擦。他對所處環境、所做任務的興趣感與價值感卻持續偏低，進得去、留不深；他在各種情境裡都能運作，卻少有一個地方讓他覺得非在這裡不可。需要長期聚焦的工作對他最吃力，不是因為他不適應變動，而是他找不到讓自己沉進去的理由；提前協助他把任務與個人意義做顯性連結，比等他自己找到節錨更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4081, 'CSR_05', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「渴望脈絡卻高度不安的謹慎接受者」。他對變化並非完全排斥，在改動有合理說明與方向時能把它視為成長機會。但他對模糊情境的容忍度極低，只要走向不明確，內心就會出現強烈的負面反應與持續焦慮，很難在等待中保持穩定。在快速迭代但缺乏說明的環境裡，他會先停下來尋求確認，而不是帶著不確定繼續向前，這讓他在資訊不透明的情境下行動變慢。他的壓力反應也容易被旁觀者誤讀為抗拒改變，實際上他抗拒的是「說不清楚的改變」。管理上宜在推動變動時提供清楚的脈絡說明，讓他有充分的資訊框架可以落腳，減少不確定感的累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4082, 'CSR_05', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「按脈絡投入的穩健者」。這是一個對改變有條件開放、同時把工作做在合理範圍的人：當變化有清楚脈絡，他會把它視為成長並願意跟進，但若變動頻繁又看不清方向，他會先尋求穩定再評估；在表現這件事上，他傾向把任務完成在被要求的水準，不特別追逐更高難度或額外突破，動能多半隨環境的支持與要求起伏。他踏實、可被預期，接受變化但不主動加碼，需要的是清楚的方向感與外部期待。要讓他多投入，與其指望他自我升級標準，不如把改變的理由講明白、把期望與支持給足，他穩定產出的那一面自然會接上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4083, 'CSR_05', 'B (中)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「情境不明時原地等候的被動者」。他對變化的接受本就需要合理脈絡，而對自身能影響結果的信念偏弱，讓他在面對不確定情境時既不確定要不要接受、也不覺得主動出手有用，形成雙重被動。在變動環境中容易停在等待位，需要外部明確指示才能啟動。建議在有明確方向的情境中優先使用他，並在高不確定任務中提供清楚的行動框架，降低模糊帶來的停滯。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4084, 'CSR_05', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動精神彌補接受門檻的行動者」。他對變化有條件性接受，但自發超越的主動精神讓他在察覺到機會或需求時傾向先行動，部分抵消了等待合理脈絡的門檻。這使他在情境條件適中時能率先推進、帶入新做法。然而主動性帶他進入方向不夠明確的情境後，仍可能出現行動後的重新評估期，需留意後續調整成本。建議善用他的主動精神承接明確機會，同時在高模糊情境前提供方向引導以減少反覆。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4085, 'CSR_05', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「不確定中更容易打退堂鼓的猶豫者」。他對變化的接受本就需要合理脈絡，而對自己能否完成目標缺乏把握，使他在進入新情境前先被自我懷疑鎖住——他既要先有合理脈絡才肯接受變化，又被自我懷疑往後拉，於是投入啟動時間明顯拉長。在高度不確定的任務中，節奏受影響尤為明顯。建議在推進時為他提供清楚的目標拆解與初期的小勝利設計，以建立效能感並縮短進入狀態的時間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4086, 'CSR_05', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「雙重迴避變化的高風險保守者」。他對變化本就傾向不適，同時對不確定性有無論程度輕重都強烈的負面反應，在任何帶有模糊的情境中都會觸發強烈的迴避衝動。在高度動態的環境或轉型期，這種保守可能產生明顯的阻力，甚至影響周遭的決策氛圍。建議在涉及變革的場合給他明確、分步驟的說明，並提供預測性足夠高的時間框架，以降低焦慮強度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4087, 'CSR_05', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「在穩定路徑上全力掌控的執行者」。他把穩定視為理想狀態，同時對自己能影響結果有強烈信念，呈現強大的「維護現狀」驅力——他會主動採取行動讓環境維持在已知軌道上，對偏差快速響應，讓已知流程極為可靠。然而在必須改變既有做法的情境中，這種掌控驅力容易轉化為對變化的抗拒，需要在說服與設計上花較多工夫。建議在啟動任何變革前先讓他理解為何現有路徑已不足，再逐步導入新方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4088, 'CSR_05', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「在固定賽道上衝刺的高成就者」。他在目標清楚、路徑已知的情況下能全力衝刺並持續升級標準，是穩定環境中的高效推進者。然而偏好穩定把企圖心的動能鎖定在現有軌道上，一旦環境要求改變方向，投入感與方向感都會受衝擊。適合深耕現有路徑的核心角色，不宜頻繁承接需要重新定義方向的任務；若面臨轉型，需要充足的過渡時間讓他重建對新方向的確信。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4089, 'CSR_05', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動出擊卻聚焦已知領域的開拓者」。他有強烈的自發行動意願，但對變化與未知的不適使這種主動精神主要聚焦在熟悉領域內的深耕與超越，而非拓展到新的方向或情境。在既有框架內他是高效的主動者，但在需要跨入真正未知的機會面前，傾向收手等待局勢明朗。建議將他安排在需要深化現有優勢的角色，若要拓展新領域，須搭配充分的方向引導與確信建立期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4090, 'CSR_05', 'C (低)', 'CSR_04', 'C', '與 CSR_04 (厭倦傾向) C聯動：表現為「在安全地帶深耕的持續投入者」。他偏好穩定，也不容易感到厭倦，在已知情境與長期例行任務中能維持遠超平均的持續投入，是重複精度與長期品質的可靠保障。他不主動尋求改變，可能在環境確實需要轉型時最後一個察覺或接受。適合需要長期穩定執行的核心崗位；在變革期需要主動讓他理解改變的必要性，而非等待他自發認知。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4091, 'CSR_05', 'C (低)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「雙重脆弱的穩定依賴者」。他對變化有不適感，同時在高壓下耗竭較快、恢復吃力，最佳狀態高度依賴穩定低壓的環境。一旦面對連續變動或逆境，他的表現波動明顯。這是需要重點支持的高敏感狀態，建議避免將他長期暴露在高度不確定的任務中，確保有足夠的緩衝期；若必須面對變動，應主動提供節奏控制與資源支援。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4092, 'CSR_05', 'C (低)', 'CSR_06', 'A', '與 CSR_06 (承諾) A聯動：表現為「在穩固環境中深根的全心投入者」。他把穩定視為理想狀態，同時對自身興趣與價值觀的認同深而穩固，呈現強烈的深根傾向——在與自身價值契合的穩定環境中，他是最可靠的長期力量，歸屬感高、忠誠穩定。然而他也「難以移植」：環境轉型期容易使他對穩定的預期失落，連帶影響承諾感。建議在變革期優先協助他找到新環境與自身價值的連接點，再推動投入的轉移。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4094, 'CSR_06', 'A (高)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「深度扎根的共進退者」。在他身上，「這件事對我有意義」和「我屬於這個地方」幾乎分不出先後——對所處環境的奉獻不是因為待習慣了，而是這份環境已經和他認定值得投入的東西長在一起。正因如此，逆境或不利處境出現時，離開的念頭會直接撞上他對自己是誰的認知，於是他傾向留下並繼續深耕，而不是衡量去留。這使他成為長期艱難任務裡最具預測性的留任者與夥伴。需要留意的反面是：當環境其實已經不值得他這樣付出，他的根植感也會讓他遲遲不肯抽身，管理者應主動替他確認這份投入的對象是否仍然健康。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4095, 'CSR_06', 'A (高)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「自我驅動卻低度歸屬」。他對自身興趣與價值觀的認同穩固，在各種條件下都能維持全心融入；但對所處環境的心理依戀較低，投入的根源是意義契合而非組織歸屬。當任務符合他的價值觀時，表現與留任均無問題，一旦環境改變使意義連結鬆動，對組織的低依附很快會轉化為離開的選項。留任管理上應聚焦於持續提供意義感，而非假設他因「看起來很投入」就不會離開。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4096, 'CSR_06', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「深度融入的穩健完成者」。他對自身所在的環境與事物有很深的投入感，不受逆境動搖，全心在其中工作；做事時他傾向把手上的任務完成到合理水準，不一定往更高難度推進，動機更多來自環境本身的需求與支持，而非主動追求突破。具體情境裡，他常能在其他人分心或退出時維持穩定投入，但較少主動提高標準或要求更大挑戰。管理上宜設置清楚的品質要求與反饋機制，讓他的投入感有具體出口；若期望他向上挑戰，需要明確的外部刺激來啟動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4097, 'CSR_06', 'A (高)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動掌舵的全心投入者」。他在乎一件事的方式，天生帶著「我做得到也做得動它」的姿態——對他來說，認定某事值得投入，就同時意味著相信自己能讓它往更好的方向走，這兩者在他心裡不分先後。所以逆境對他不是「要不要撤退」的訊號，而是「該怎麼出手」的訊號：困難越大，他越傾向主動調整方法、推進局面，而不是停下來承受。在需要長期自我管理、又得在不確定中持續往前的任務裡，這是高可靠度的樣貌。要留意的是，當外部資源明顯不足時，他這種「我能影響結果」的篤定可能讓他攬下超過合理範圍的責任。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4098, 'CSR_06', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「心理在場但等待結果的融入者」。他對所在的環境有很深的認同與融入，各種條件下都能保持心理的全然在場；然而當事情發展出現波折或不確定性時，他較少相信自己能影響結果，傾向被動等待而非主動出手。具體情境裡，他能穩定參與日常，但遇到需要主動推進或扭轉局面的時刻，容易因覺得「結果未必在我這邊」而保持觀望。管理上宜為他提供清楚的行動窗口與回饋，讓他看見自身介入能帶來可見的改變；長期依賴等待容易使他的投入感難以轉化為影響力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4099, 'CSR_06', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「心理全投但等指示才動的參與者」。他對所在環境有不受逆境動搖的歸屬感，心理上完全融入；但行動上傾向等待明確任務或他人發起，較少自行開啟新事項或超越既定要求。具體情境裡，他在被指派任務後能全神貫注地完成，但缺乏指示的空白期容易以待命取代主動。管理上宜把待完成事項明確拆解交付，讓他的投入感有清楚的承接點；若希望他自發推進，需要降低初始啟動的門檻並給予充分的環境信號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4100, 'CSR_06', 'A (高)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「投入深但耗損後難撐的融入者」。他對所在環境有不受逆境動搖的歸屬感，各種條件下都能維持全心投入；但他的內在正向資源較為有限，一旦遭遇挫折或累積壓力，動能會明顯下降，對未來也容易轉向悲觀，復元過程相對費力。具體情境裡，他能在穩定期間穩定貢獻，但在高挫折或連續變動的階段容易觸底，表現波動大。管理上宜主動提供支持與進展的能見度，讓他在逆境中看見可掌握的小成果，避免讓他長時間獨自消化壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4101, 'CSR_06', 'B (中)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「契合時擁抱變化的彈性投入者」。他是不是全心投入，要看這件事與環境跟自己契合到什麼程度；而他又天生把變動當常態、不需要額外調適。這兩種特性在他身上合成一種特定樣貌：只要方向與自己對得上，再頻繁的變動他都能順勢吸收、甚至從中拿到動能，投入反而更廣更深。但同樣的開放性也有另一面——當他開始覺得方向不再契合，外在又一直在變，這兩件事會一起把他推向「我還該不該投入」的重新評估，於是撤退的念頭來得比一般人快。管理上，在調整方向前應先確認他對新方向是否仍有價值觀上的認同，別因為他向來不排斥變化，就假設他不需要重新對齊。此為情境敏感的表現，非固定模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4102, 'CSR_06', 'B (中)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「穩定契合才能完全融入的求穩型」。對他來說，要真正投入一件事，光是覺得有意義還不夠，還得這個環境本身是穩的、可預期的——因為他面對變動與未知時會本能地不舒服，把穩定視為理想狀態。於是他需要的其實是雙重保證：這件事值得，而且腳下這塊地不會一直晃。一旦環境出現較大變動，他會同時感到「這裡是不是不再適合我」和「我不喜歡這種說不準的感覺」，於是投入品質下滑得比表面反應更快。管理上，變動前主動預告、把來龍去脈講清楚，讓他在心理上先重新長出「這裡仍然對」的踏實感，他的投入才穩得住。此為情境敏感的表現，非固定模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4103, 'CSR_06', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動尋找契合以維持投入」。他的投入確實要看環境與自己契合到什麼程度，但他同時深信自己能影響事情的走向，於是「契合與否」對他從來不是被動的既定條件，而是可以動手調整的對象。當他感覺契合度開始下滑、價值觀受到挑戰時，他的第一反應不是盤算去留，而是「我能做什麼讓這裡變回對的樣子」——主動重塑條件，試過之後若確認真的改不動，才退到重新評估留下的階段。這讓他在有自主空間的工作裡表現最好，也是最好的早期警訊來源：等他真的開始抽離時，通常代表他已經嘗試過改變而未果。此為情境敏感的表現，非固定模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4104, 'CSR_06', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「契合感動搖時焦慮驅動的重新評估」。他的投入以環境與自己契合為前提，本就會在條件改變時重新衡量；而他對不確定性又極為敏感，面對模糊情境容易陷入強烈而持續的焦慮。所以對他而言，環境一出現讓契合感變模糊的訊號，浮現的就不是冷靜的「我還該不該投入」，而是一邊問這個問題、一邊被焦慮緊緊纏住的狀態——在情況沒釐清之前，他幾乎沒辦法回到安穩的投入裡。管理上，方向、期望與角色定義要儘量清晰，變動前先把脈絡溝通好，別讓他在資訊不足時，同時扛著焦慮和投入重估這兩件最折磨他的事。此為情境敏感的表現，非固定模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4105, 'CSR_06', 'B (中)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「忠誠兜底的條件型投入者」。他投入與否會隨契合度起伏，契合感一降就想重新衡量；但他對所處環境同時有一份不太受條件好壞影響的依戀與奉獻。契合感動搖時，他心裡「想重估」和「捨不得這個地方」會同時在場，結果通常不是立刻走人，而是傾向再給機會、再找方法對齊一次。一般波動下他因此顯得穩定；但在真正不健康的環境裡，他可能撐得比對自己有利的更久。管理上，看到他出現低契合的訊號就該主動對話，別把「他還沒離開」誤讀成「他還好」。此為情境敏感的表現，非固定模式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4106, 'CSR_06', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「契合時投入、出錯後難承接的人」。他在環境與個人興趣契合時能充分融入，投入感高且狀態穩定；但一旦遭遇失誤或問題，他較容易把原因歸結到外部條件，補救行動相對被動。具體情境裡，他在順境中是可依賴的參與者，出現問題後卻容易等待情況自行改善而非主動介入，拉長了解決周期。管理上宜在他投入狀態良好時預先設置責任邊界，讓他清楚知道哪些事項屬於他需要跟進的範圍；出問題後給予明確的補救指引，有助縮短被動期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4107, 'CSR_06', 'C (低)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「意義與歸屬雙重疏離者」。他既不太感覺得到某件事對自己的意義，也不太對所處的環境產生依戀——對任務沒有「這值得我做」的牽引，對環境也沒有「我屬於這裡」的羈絆。在他身上這兩種疏遠其實是同一種狀態：心裡沒有任何一處定錨點把他留在場上，所以他要不要投入、要不要留下，幾乎全看眼前有沒有實際好處或短期需要。一旦遇上逆境或不利條件，他離開的門檻很低，留任動機相當脆弱。這種情況下的留任風險應被當成持續性的警訊；管理上要先找找看，有沒有任何任務設計能替他建立一點意義連結，若短期內看不到改善，對他能否留下的預期就該放保守。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4108, 'CSR_06', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「任務驅動的低歸屬高企圖者」。他對成果與表現有明顯的企圖心，遇到挑戰傾向主動把目標和方法往上推；但他對所在的環境或組織的融入感偏低，歸屬感薄，心理上保持相對的旁觀距離。具體情境裡，他能在困難任務中全力衝刺，但較少把這份投入轉化為對群體的情感連結，分功、協作或文化共識對他的動能影響有限。管理上宜以清楚的成果框架和任務難度作為主要激勵槓桿；不要期待他因為歸屬感而自然加強協作，合作需求要轉化為具體任務才能有效驅動他。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4109, 'CSR_06', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「疏離加速厭倦的快速撤退者」。他本來就不太覺得某件事對自己有意義，面對深度參與傾向旁觀；他又是那種無論活動怎麼變都很快失去投入感、頻繁感到無聊的人。別人可能還靠「這件事對我有意義」撐著熬過枯燥期，他連這層意義感都沒有，於是新鮮感一退，就再沒有什麼東西替他把投入接住。他或許會因為一開始的新鮮被短暫吸引，但融入的深度和持續度都低，撤退往往比外觀顯示的更早發生。他在需要持續專注與深度投入的任務裡風險最高；建議先評估有沒有任何真正能引起他長久興趣的領域，再據此安排任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4110, 'CSR_06', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「旁觀規範的低責任投入者」。他既不太覺得手上的事對自己重要，又傾向把規範當成可以調整的工具——所以無論是「我在乎所以我把它做好」這種內在驅力，還是「規矩要求我做好」這種外在約束，對他都不太起作用。在他身上這合成一種特定樣貌：任務上鬆散、不太用心，一旦遇到目標壓力，他容易挑最省力、最看結果的做法繞過該守的規範，出了狀況補救也偏被動。這在需要嚴格守規的崗位上是要特別留意的組合——不能指望他自我驅動，得靠更強的外部監督框架和明確的底線提醒把品質與合規兜住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4111, 'CSR_06', 'C (低)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「雙重低信心的被動邊緣者」。他既很難覺得某件事對自己重要，又對自己能不能把目標做成沒什麼把握。因為不在乎，他更不願冒著「可能做不到」的風險去投入；因為不確定做不做得到，他更傾向把這件事歸到「跟我無關」那一邊。結果是進入任何需要主動承擔的任務，他的門檻都特別高，面對挑戰常遲疑、過度求證或乾脆等別人決定。對他得從最小、最看得見成果的單位開始，讓他同時嚐到「我做得到」和「這值得做」——意義感和效能感得一起補，只處理其中一面都不夠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4112, 'CSR_06', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動四射但心理疏離的行動者」。他的主動精神十分穩定，在各類情境中都能自發開啟行動並超越既定要求；但他對所在環境的融入感偏低，較難感受到自身與群體的深層連結，參與感停留在任務層面而非情感投入。具體情境裡，他在推進事項上高度積極，但對群體向心力的貢獻有限，分享、凝聚或慶祝成果等活動對他的吸引力低。管理上宜接受他以任務為核心的主動方式，把對群體的期待轉化為明確的協作任務，而非訴諸歸屬感；若組織需要文化凝聚，這方面需要透過他人補位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4113, 'CSR_06', 'C (低)', 'CSR_02', 'C', '與 CSR_02 (親和性) C聯動：表現為「雙重疏離的高牆孤立者」。他既不太覺得某件事對自己重要，在人際上又傾向保持距離與戒備，對合作容易先起猜疑。對他來說，要真正融入一個情境，本來就需要「這件事值得」和「身邊的人可信」這兩種感受，而他這兩處都偏空：對任務沒有意義上的牽引，對人也沒有信任的基礎，於是凡是需要投入、需要協作的場合都讓他不自在。他的參與多停在最低限度，合作時保留而多疑，很難長出真正的協作關係。在重視協作與投入的環境裡這是高風險組合；建議先從建立安全的一對一關係著手，等他在人際上稍微有點安全感，再嘗試替任務建立意義，這兩件事沒辦法同時硬推。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4114, 'CSR_07', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「退讓中的失控感」。衝突當前他自然往順從、配合的方向走，而這份退讓底下還連著另一種感受——他本來就不太相信自己能改變事情的走向。對他而言，保持和氣最省力，主動爭取大概也換不到不同結果，於是順著局面走成了最合理的選項；讓步不像在選擇息事寧人，更像確認了一件他早已認定的事：爭也未必有用。外人看到的是極度平和、好說話，但這份平和不帶「我選擇不爭」的底氣，而像「我不覺得爭得動」，久了容易被誤判成他根本沒有底線。建議定期主動詢問其意見並給予明確的反饋渠道，讓他實際看見表達立場確實能改變結果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4115, 'CSR_07', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「隱性取利的和解者」。他面對任何明顯的對立都傾向退讓，在現場從不硬碰硬，衝突快升溫時他會先開口緩和氣氛。然而在安靜的表面下，他對競爭結果並不淡然，當涉及利益分配或晉升機會時，他願意以非直接的方式取得優勢，合理化「不衝突但先拿到位置」的做法。具體情境裡，他常一邊在會議中展現協作姿態，一邊在私下的安排中優先確保自己不吃虧。實務上他容易被視為好相處，但實際的利益運算不透明，管理上宜對資源分配規則講清楚、讓標準公開，減少他在灰色地帶操作的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4116, 'CSR_07', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「被衝動推著的順從者」。他在衝突裡的本能是退讓、求和，但情緒一旦被頂到某個點，反應會搶在思考前面冒出來——平時想息事，當下卻按不住。多數時候他順從配合，偶發的情緒衝動卻可能讓他突然反應激烈，說出重話或做出過頭的動作，隨即又因本質順從而退回低姿態、急著修補。對旁人來說，難的不是他平時太硬，而是平時太軟、偶爾的爆發落差太大，反而更難預測他真正的底線在哪，也讓爆發後的修復成本更高。給予明確的壓力緩釋出口，並在摩擦初期就早期介入，能有效降低意外爆點的頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4117, 'CSR_07', 'A (高)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「讓步與彈性取捨共構」。在各類衝突情境中他都傾向退讓，同時對規範本身也傾向彈性詮釋、視目標壓力調整；當衝突涉及合規邊界時，他可能同時選擇「不對抗」又選擇「放掉規定」，而非在其中任何一端撐住。對於需要他維護程序底線的崗位而言，應在分工上明確標示哪些事項是硬性不可妥協，並建立外部檢核機制，不可單靠其自我監控。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4118, 'CSR_07', 'A (高)', 'CSR_16', 'A', '與 CSR_16 (寬恕) A聯動：表現為「衝突後迅速重置」。他在衝突中傾向退讓，衝突結束後又能快速放下怨恨、恢復對對方的好感，幾乎不留尾韻；這讓他成為極易相處、氛圍友善的人。但這也意味著衝突對他的「代價」幾乎為零，對方缺乏必要的壓力去修正問題行為。建議他與主管或支持者建立機制，在重複性冒犯情境中引入外部記錄與回饋，避免因其個人快速重置而讓問題行為缺乏後果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4119, 'CSR_07', 'A (高)', 'CSR_17', 'A', '與 CSR_17 (溫和有禮) A聯動：表現為「雙重柔化的磁場」。在紛爭場合中他既不對抗也不嚴厲評判他人，在高摩擦情境中他往往是天然的緩衝力量，能有效降低場域張力。同時他也幾乎無法傳遞清晰的邊界訊號或具指向性的負面反饋，對方可能長期接收不到需要改變的訊息。在需要直接問責或明確要求改正的場合，應有其他角色介入，或預先設計他能以結構化方式傳達問題的出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4120, 'CSR_07', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「警戒中的配合面孔」。在各類衝突情境中他傾向順從因應，但同時對他人的信任度偏低、互動中帶有保留與警戒；配合不代表放心，退讓的同時仍在持續評估對方是否懷有不利意圖。他從外部看起來易於合作，但真實投入程度可能大打折扣。對於需要深度協作的任務，應創造可驗證彼此意圖的結構（如透明目標設定、進度共享），讓他有機會逐步建立信任、提高實際合作深度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4121, 'CSR_07', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「靜待指令的和平者」。衝突情境中他不對抗、退讓，同時也較少在沒有明確要求時主動發起行動，在模糊的高壓場合幾乎完全依賴外部指令才會移動。行為上他表現為極度配合、不製造麻煩，但也不主動推進或協助解決問題。若崗位需要他在衝突或危機中帶頭行動，應預先設定明確的觸發條件與角色期待，而非期待他自發跨出行動邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4122, 'CSR_07', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「順從掩不住的焦慮底流」。衝突情境天然製造不確定性，他又對模糊狀態有極強的負面反應，因此退讓的背後常帶著一種緊迫的「快點結束這個狀態」的動力——選擇配合未必因為認可對方，而是為了恢復確定感。外表看起來是溫和好說話，但決策可能因焦慮而提前收口，未能充分評估結果是否合理。建議在重要議題上設計緩衝步驟（如「先確認再承諾」），給他消化不確定性的時間，降低因焦慮而過快讓步的風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4123, 'CSR_07', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「協商中的主動駕馭」。面對一般紛爭，他偏好透過溝通協調處理，而強烈的掌控信念讓這種協調不只是被動因應，而是主動設定對話框架、引導局勢走向；衝突成為他展現影響力的舞台，而非需要迴避的場域。當衝突升級且協商失效時，才會視情況轉向堅持立場。在需要主導衝突化解、推動共識的情境中，這種組合效能高；但要留意主動引導與強迫接受之間的邊界。B 段情境敏感，前提是衝突可被溝通推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4124, 'CSR_07', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「衝突消耗殆盡的彈性」。他在面對一般紛爭時能以溝通協調因應，但承受長期壓力或多重逆境的韌性資源有限；一旦衝突持續升高、對方長期強硬，堅毅性這塊底板提早消耗，靈活的協調空間隨之縮減，後續反應可能在過度退讓或突然強硬之間搖擺，不再可預測。短暫衝突中他是有效的協調者，長期衝突中則需要外部支持（拆解壓力、明確進度）才能持續運作。B 段情境敏感，衝突強度與持續時間是關鍵變量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4125, 'CSR_07', 'B (中)', 'CSR_02', 'C', '與 CSR_02 (親和性) C聯動：表現為「戒備驅動的有限協調」。在一般紛爭中他會嘗試溝通協調，但人際互動的基底帶有距離感與猜疑，使他在協調過程中同時保持高度警覺——分享有限、觀察持續。若對方表現出強硬態度，這往往快速確認了他對對方意圖的負面預設，彈性窗口因此提前關閉，轉向保留或堅持立場。合作夥伴若希望開啟有效協調，應在前期建立可驗證的善意訊號，而非期待他自然開放。B 段情境敏感，人際安全感是關鍵前提條件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4126, 'CSR_07', 'B (中)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「策略性的衝突周旋者」。面對紛爭時他傾向以溝通協調代替對抗，但同時把選擇性揭露與話術視為達成目標的正當工具；他的衝突協調帶有不透明性——外表在溝通，實質在引導。對方感受到的是靈活願意談，但事後可能發現談判框架從一開始就被塑造過。在需要高誠信度的衝突處理情境（如申訴、勞資協商）中，應引入有紀錄的透明程序，讓協調結果可被事後驗證。B 段情境敏感，有無利益壓力是觸發因素。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4127, 'CSR_07', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮壓縮的彈性視窗」。面對一般紛爭，他有意願透過溝通判斷要退讓還是堅持；但衝突本身製造持續的不確定感，而他對這種模糊狀態的忍受度極低，使他在協調過程中容易提前收口——焦慮主導了決策時機，靈活評估的窗口被壓縮。在需要充分協商才能取得好結果的情境中，建議設定清楚的討論節點與預期時程，給他可預測的結構，降低焦慮對決策品質的干擾。B 段情境敏感，衝突持續時間是觸發因素。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4128, 'CSR_07', 'B (中)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「穩定框架中的彈性協調」。他在紛爭中傾向以溝通協調因應，同時偏好穩定可預測的結構，對變動帶來的不適感真實存在；當衝突本身就牽涉組織改變或方向不明時，他既要應付衝突壓力、又要承受對變動的不適，於是傾向選擇能最快恢復穩定的方案，而非最優的解決路徑。在涉及結構性調整的衝突場合，應為他預先說明改變的走向與邊界，降低不確定感，讓他能把協調能量用在問題本身，而不是對「變化本身」的適應上。B 段情境敏感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4129, 'CSR_07', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「衝突後的責任模糊地帶」。在紛爭進行中，他能靈活運用溝通與協調讓局面暫時平息，但對執行結果的主動承擔較弱，遇到失誤或執行落差傾向歸因外部情境。這意味著他擅長衝突的「前半段」（讓步或協商），但衝突解決後的追蹤、補救和學習往往需要他人補位。在他主導協調的議題上，建議明確指定他對後續結果的追蹤責任，並設計定期確認節點，避免衝突解決後責任真空。B 段情境敏感，責任邊界清晰度是觸發因素。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4130, 'CSR_07', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動出擊的強勢推進者」。面對紛爭他傾向直接表達立場，同時持續相信自己能影響結果並採取積極行動；衝突不是讓他焦慮的場域，而是讓他發揮掌控感的舞台。他在高對立情境中能有效推進立場、防止被動挨打，但在不需要對抗的常規問題上也可能提前升溫。建議協作時給他清楚的參與邊界，讓他的強勢動能在真正需要的問題上發揮，並在日常溝通中設計反饋機制以監控不必要的衝突製造。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4131, 'CSR_07', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「溫情包裹的直接對抗」。面對紛爭他傾向直接表達立場、較少退讓，但同時在各類人際情境中都能自然展現信任與熱情；對抗不是拒絕關係，而是他認為真實的夥伴關係本來就可以承受直接的摩擦。衝突中鮮明、衝突後溫暖，恢復合作基調的速度比典型對抗型更快。對方若能調整預期——直接不等於攻擊性——這種組合能成為高效的衝突清楚者；但對不習慣直接風格的人，初始衝擊仍需注意管理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4132, 'CSR_07', 'C (低)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「規則背書的強硬捍衛者」。在紛爭中他傾向直接表達立場、很少退讓，加上對規範與承諾有高度的重視，他的對抗行為帶有清楚的原則基礎——爭辯不是個人意氣，而是他認為遵守規則本就是義務。在合規或倫理邊界被挑戰時，他能有效守住底線；但衝突一旦涉及他認定的原則，幾乎不存在柔性出口，可能使協調成本升高。建議在可能涉及原則邊界的議題上提前對齊期待，避免讓他在公開場合才第一次表態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4133, 'CSR_07', 'C (低)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「直言而少緩衝的回應」。面對紛爭時他傾向直接把立場攤開、不太迎合，這份正面回應的傾向本身又帶著未經冷卻的熱度——話常在情緒最滿時就出口，據理力爭之餘也容易說得太快、應得太急。於是他既不繞圈子，事後卻常得回頭收尾、補一句解釋來緩和力道。和他協作時，把重要決定留到他情緒平復後再確認，並用書面把承諾與界線記下來，能讓他的直率發揮效用而少留後遺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4134, 'CSR_07', 'C (低)', 'CSR_17', 'C', '與 CSR_17 (溫和有禮) C聯動：表現為「直接加嚴厲的雙重鋒芒」。他在衝突中傾向直接表達立場，同時評價他人時傾向嚴厲批評而非寬容；他在衝突中的語言帶有明確的批評鋒芒，對方感受到的不只是立場對立，還有對自身的負面評斷。即便本意是陳述事實，這種風格容易讓衝突迅速從議題層面滑向個人層面。在需要持續協作的情境中，建議引入結構化的反饋框架（聚焦行為與結果、不評價人格），並提供語氣調整的具體示範，以降低關係損傷的累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4135, 'CSR_07', 'C (低)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「衝突後的長期冷戰者」。他在衝突中傾向直接表達立場、出現對抗性反應，衝突結束後又難以放下不滿、恢復信任需要很長時間；每一次公開衝突都可能留下持久的負面尾韻，並為下一次互動預埋更高的敵意底線。在需要持續協作的環境中，這種組合的長期關係損耗最為顯著。建議在衝突解決後引入明確的復原步驟（如雙方共同確認共識、由第三方見證），以打破自然循環——每次衝突留下的疤痕若不被處理，關係將螺旋式惡化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4136, 'CSR_07', 'C (低)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「在信任中坦然爭辯」。他在衝突中傾向直接表達立場，同時對他人有穩定且不受負面經驗動搖的高度信任；因為預設對方沒有惡意，他的直接不帶防衛色彩，而是一種「我相信你能承受我的真實立場」的表達方式。衝突中觀點碰撞清楚，但情感傷害相對少，修復也較自然。這種組合在心理安全感高的環境中效能最好；若對方信任容量低或組織文化不支持直接表達，仍需調節語氣以避免不必要的傷害。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4137, 'CSR_07', 'C (低)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「快速出口的衝動對抗」。在紛爭中他傾向直接表達立場，同時傾向先行動再評估；衝突中的第一反應幾乎未經完整風險評估就出口，言詞定調快且強，事後補充或修正往往難以抹去初始留下的印象。這種組合在緊急情境中能快速切入，但也容易讓小摩擦因第一波反應過強而升溫。建議在重要衝突場合提供緩衝提示（如冷靜後再回應、設定等待時間），讓他的直接能量在評估後才釋放，減少事後修補的代價。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4138, 'CSR_07', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「目標驅動的衝突突圍者」。面對紛爭他傾向直接表達立場、很少退讓，加上對成果有強烈企圖心並願意為高標準多投入；衝突對他而言是目標路徑上的障礙，需要被直接清除而非繞道迴避。他在衝突中的持久性高，對方強硬不會讓他輕易收手，因為讓步等於讓目標受損。這種組合在需要強力推進、突破阻力的情境中效能顯著；但在需要多方協調的情境中，應預設他的對抗性可能升高他人的防衛，建議搭配清楚的利益共識建立機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4139, 'CSR_07', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「衝突場域中的刺激追求者」。他在紛爭中傾向直接對抗，同時在各類情境中容易迅速失去投入感、需要新鮮刺激；衝突恰恰提供了高張力的投入感，對他而言不是需要迴避的壓力，而是能讓他自然保持專注的場域。這可能讓他在衝突趨向平息時不自覺地提出新議題、擴大討論，以維持張力。在高頻衝突環境中他能保持耐力，但也可能成為衝突延長的變因——建議留意衝突是否真的有新的實質問題，還是已進入他對刺激的追求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4140, 'CSR_07', 'C (低)', 'CSR_15', 'C', '與 CSR_15 (遵循指示) C聯動：表現為「質疑規則的直言者」。他遇到衝突時第一反應是表態，不迴避也不拖延；面對既有程序或上級指示，他同樣不會自動配合，傾向先判斷合理性再決定是否照做。遇到他認為站不住腳的要求時，他會直接說出質疑，語氣不一定溫和，也不在意這樣做會不會讓場面尷尬。在需要獨立判斷、快速做決定的環境裡，他的主見是資產；在強調程序一致或層級服從的場景，他對規則的低配合度和對立場的直接表達都容易製造張力，管理上需要事先解釋規則的理由，而非要求他先執行再說明。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4141, 'CSR_08', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「自律嚴謹但難耐單調的執行者」。他對品質與進度有強烈的自我驅動，在挑戰性高的任務裡輸出穩定且可靠；但面對重複性或缺乏新鮮刺激的工作，他迅速失去投入感的傾向會浮現，很難單靠自律維持持久的熱情。在任務有足夠變化和難度的環境裡，他的高標準特別能發揮；長期執行例行作業時，收尾品質可能出現鬆動，需要額外的外部刺激或任務重新設計來維持他的注意力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4142, 'CSR_08', 'A (高)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「勤奮推進卻遲疑停頓的矛盾者」。他做事有一致自我要求、幾乎不需外部催促，卻對努力能否換來成果缺乏把握，面對挑戰時遲疑、過度求證或依賴他人決策；盡責的勤奮表象下有對自身能力的持續不確定，在高挑戰任務中尤其明顯。建議以明確目標分解和即時確認回饋強化其效能感，避免猶豫消耗高自律的驅動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4143, 'CSR_08', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「壓力下雙重崩潰風險者」。在目標清楚時他能穩定投入，然而一旦逆境出現，他既面臨盡責的情境波動，又缺乏承諾、控制與挑戰三種內在資源作為緩衝；這兩道防線同時弱化，使持續壓力下的表現滑落幅度遠超單一因素。建議在高壓節點預先配置外部支持結構，而非等待他自行撐過去。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4144, 'CSR_08', 'B (中)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「任務可靠但等待外力的執行者」。目標和責任範圍清楚時，他能穩定投入、按部就班完成；但他較少相信自身能主動影響結果，面對不確定或需要主動出手的情境，傾向被動等待而非採取行動。在高度結構化的任務裡他的可靠度高；在需要主動拿回主導權、處理超出既定框架的問題時，他的反應相對慢且需要外部引導。管理上宜提供清楚的責任框架，並在需要他主動出手時給予明確授權與方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4145, 'CSR_08', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「任務清楚時主動超越者」。他本身就是個自發性很強的人——不太需要別人指方向，看到事情就會自己開始做、而且會往超出被交代的範圍去做。差別在於他的盡責是看情境的：目標、範圍清楚時，他這股主動勁有地方落下，會把可靠交付再往上加，做出超過要求的成果，是團隊裡很值得倚重的人；但當優先序混亂、責任邊界不清時，他的不確定不在於『要不要主動』，而在於『往哪主動才不會白費』，於是同樣的主動性反而可能撞牆或做白工。所以對他要先把框架釐清，而不是用他的主動去補結構的洞——他不缺發動的意願，缺的是值得發動的清楚方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4146, 'CSR_08', 'B (中)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「穩定環境才能可靠的執行者」。他在目標與時程清楚時能穩定輸出，但面對變化或未知時容易產生不適；當組織頻繁變動或優先序不清，他一方面感到盡責輸出失去清晰依據，一方面又對缺乏穩定與可預測感到不安，於是他的可靠性下降速度遠超預期。建議在變動期預先溝通調整後的清晰框架，減少雙重不確定對其輸出的衝擊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4147, 'CSR_08', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「情境波動且容易預期失敗者」。在目標清楚時他能穩定推進，但他看事情的底色偏向把不順當作長期而普遍的。對他而言，碰到阻礙的那一刻，並不是先有動能、再被悲觀澆熄；而是『遇到阻礙』本身就直接被他讀成『這件事大概做不成了』——這個解讀就是他停下來的理由。也就是說，他的停滯不是悲觀把幹勁打掉，而是對他來說『卡住了』幾乎等於『不會有好結果』，於是繼續推下去的意義感先消失了。管理上，光鼓勵沒用，要在他卡住的當下給他『這個阻礙具體可以怎麼被解掉』的證據，打斷『卡住＝完蛋』這個直接連結，他的推進節奏才回得來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4148, 'CSR_08', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「失誤外移且難以收尾的迴避者」。他在自我監控與節奏維持上較吃力，遇到失誤或延誤又傾向歸因外部、補救動作相對被動；盡責的低自主推進與個人責任感的低承責傾向形成雙向缺位，問題既難被自主發現，發現後也難被主動處理。這是最容易累積隱患且最難自我糾正的組合，需要主管設定明確責任邊界與即時反饋機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4149, 'CSR_08', 'C (低)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「壓力下雙重耗損的搖擺者」。他在自我監控與維持節奏上本就比較吃力，情境或情緒的波動容易帶來拖延與收尾不足；遇到壓力、衝突或連續變動，補救與恢復的速度更為緩慢，能量耗竭明顯。平穩期他能完成工作，但一旦情況出現波瀾，他需要相當長的時間才能重新穩定下來，這段空白期對整體節奏的影響不小。管理上宜盡量提供有節奏的工作環境，避免長期高壓，並在逆境後主動給予支持，幫助他縮短恢復期。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4151, 'CSR_09', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮的主導者」。對他來說，「我能影響結果」和「我受不了任何懸而未決」其實是同一種面對世界的姿態：凡是還沒被確定的地方，他既相信自己有責任去處理，也無法安於不去碰它。於是他的行動與介入幅度都超出客觀所需——備案一個接一個、確認一次又一次、該放手的也收在手裡，不是因為缺乏掌控，而是任何模糊地帶都同時觸發他的責任感與不安。實務上他在需要積極推進的局面很有價值，但容易把精力耗在抹平每一處不確定。建議替自己設一條「到這裡就算夠好」的明確界線，讓掌控落在真正關鍵處，而非鋪滿所有角落。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4152, 'CSR_09', 'A (高)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「掌控信念卻缺乏效能感」。他對影響結果有強烈信念，任何情境下都傾向主動採取行動，但同時對自己能否真正達成目標缺乏把握；這使他進入一種「一定要做、但做了不放心」的循環——行動量不小，心理耗損卻不成比例。建議把大目標拆解成可驗證的小里程碑，讓每次完成都能實質回補效能感，而非僅靠掌控信念支撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4153, 'CSR_09', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「快速出手的掌控者」。他相信自己能左右事態，而對他而言「相信能影響」的自然表達就是立刻動手——先做、邊做邊修，評估擺在行動之後。這不是一個謹慎的人少了煞車，而是他根本把「現在就介入」當成施展影響力的方式，停下來預想風險對他並不順手。在講求速度與推進的場合，他的執行力很突出；但隱藏風險、細節漏洞往往要等到事後才浮現。對結果要求精準、或代價不可逆的任務，最好替他在流程上嵌入一道強制停頓（例如動手前必過的確認清單），把他天生不會主動做的事前評估外化成步驟。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4154, 'CSR_09', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「咬牙推進卻悲觀判讀的行動者」。他相信自己能影響結果，遇到任何情況都習慣主動出手，這份掌控感十分穩定；然而他對結果走向的預期卻長期偏低，傾向把每一次挫折都解讀成不可扭轉的訊號。在具體情境裡，他常一邊持續推進、一邊預期這次一樣不會成功，動能靠的是習慣或責任感而非希望。實務上他算可靠，但他自己的情緒庫存在反覆受阻後會悄悄耗損，管理上宜把小的進展明確回饋給他，讓他看見行動與結果之間確實存在的連結。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4155, 'CSR_09', 'A (高)', 'CSR_06', 'A', '與 CSR_06 (承諾) A聯動：表現為「高度自主融入的篤定推進者」。他持續相信自身能影響結果，各種條件下都主動採取行動；對自身興趣與價值觀的認同也不受逆境動搖，讓他的投入在困難環境中格外穩定。具體情境裡，他常一邊在外部條件不利時繼續推進、一邊深度融入而非淺嚐即止，旁人幾乎找不到讓他撤退的理由。實務上他在混亂或資源不足的環境特別有存在感；在決策需要妥協或外部力量不可控時，管理上宜給他清楚的邊界說明，避免他持續以為憑自身意志就能扭轉不可掌控的格局。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4156, 'CSR_09', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「獨力掌控、難以借力」。他對自身能影響結果的信念很強，任何情境都主動出手；但同時對他人抱持高度警戒、傾向預設對方意圖可能不利，使他習慣把行動路徑收回到自己手中。這個組合在個人執行層面效率突出，但在需要協作放大規模的情境，不易授權與求援的傾向會成為明顯瓶頸。建議刻意練習「可信任對象清單」，把部分掌控感分配給已驗證的協作者。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4157, 'CSR_09', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「有動能卻欠驅力」。他始終相信自己能影響事情，所以不會消極等待；但這個人對「做得更好、更難、更高」並沒有內在的渴望，把工作收在合理完成的範圍就覺得足夠。於是他穩定地把分內事做好、可靠地把局面顧住，卻很少自己提出要突破現狀或拉高標準——這不是掌控力被什麼東西擋住，而是他施展能動性的方向天生停在「做好該做的」，沒有往「做到更多」延伸的拉力。需要他承擔更高標準時，得靠外部明確設定目標與清楚回饋來補上這股缺席的進取心，他才會把可靠的執行力導向更高的標的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4158, 'CSR_09', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮壓縮行動範圍」。他在可掌握範圍內有主動行動的傾向，但同時對不確定性極度敏感；這使他主觀認定的「可掌握範圍」比客觀情況更窄——稍有模糊訊號，就傾向退縮至已確認邊界，而非嘗試小步延伸。B 段情境敏感的特性在高不確定環境下會特別凸顯。管理上建議把任務拆解成確認度高的小段，逐步擴大他的有效行動區。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4159, 'CSR_09', 'B (中)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「劃定邊界、在穩定格局內可靠行動的執行者」。他在可掌控的任務框架內有穩定的行動意願，做事可靠有交代；他同時把穩定與可預測視為理想工作狀態，不太把變動視為成長的機會。遇到需要快速切換或頻繁調整的情境，他的行動邊界會比一般人更早收緊，投入空間縮到可掌握的最小範圍內。他最能發揮的位置是節奏穩定、責任清楚的任務；一旦環境持續動盪，需要搭配外部結構或明確的分階段指引，才能維持他的行動半徑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4160, 'CSR_09', 'B (中)', 'CSR_12', 'A', '與 CSR_12 (目標效能感) A聯動：表現為「效能感拉大行動邊界」。他傾向在可掌握範圍內主動行動，而對完成目標的強烈信心，使他對「什麼算可掌握」的判斷偏向積極——目標清楚時他啟動快、觀望期短，整體行動半徑比沒有這份效能感時更寬。這個組合在有明確任務方向的情境效能較高，建議配合明確目標和可量化里程碑，充分發揮這種「有信心就推進」的特性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4161, 'CSR_09', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動精神擴張掌控邊界」。他傾向評估可掌握範圍再行動，而強烈的主動精神在察覺到機會或需求時往往快一步推著他超越邊界；實際行為是主動精神帶路、掌控評估跟進——行動範圍比他自己預設的更廣。這在快速回應機會的場景是優勢，但在需要嚴格管理資源邊界的情境，應留意主動精神是否把他帶入超出實際影響力的承諾。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4162, 'CSR_09', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「企圖心衝破範圍門檻」。他傾向在可掌握範圍內行動，但同時懷有強烈的成就追求，不斷想往更高標準推進——目標清楚時，他的動能充沛且主動。他的特點是「做到夠了還不想停」，在成熟任務中是推力，但在情境複雜、掌控度不足時，這股驅力可能讓他過度承諾、超前部署。管理上可善用他的企圖心，同時為他提供清晰的資源邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4165, 'CSR_09', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「盡職超越卻不信自己能左右大局的行動者」。他在各類情境中都能自發開啟行動、做超出要求的事，這份主動精神不依賴外部推動；然而面對事態走向他較少相信自己能產生影響，傾向被動等待結果而非主動介入格局。具體情境裡，他常一邊超越任務要求、一邊把成果走向視為由外部決定的事，自己做好本分就算盡責。實務上他是可靠且高產出的執行者；在資源爭取、影響決策或扭轉局面的場合，管理上宜明確告知他的行動對結果有什麼實際連結，幫助他認識自身的影響力範圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4166, 'CSR_09', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「拚命做好卻不信自己能左右結果的進取者」。他對表現與成果有明確企圖心，遇到挑戰會主動把標準和方法往上推；面對事態走向時，他卻較少相信自己能產生影響，傾向被動等待結果。具體情境裡，他常一邊把手頭的工作做到更高標準、一邊對能否換來他期望的結果抱有保留，努力的背後帶著「做了也未必算數」的底色。實務上他是可靠的高標準貢獻者；在需要爭取資源、談判或主動影響決策的場合表現薄弱，管理上宜把他的付出與可見的結果清楚連結，讓他感受到行動確實在改變局面。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4167, 'CSR_09', 'C (低)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「被動加自我懷疑的雙重撤退」。他既缺乏影響結果的信念、傾向被動等待，又對能否完成目標深度懷疑——這兩種低信念都指向同一方向，使他在面對挑戰時幾乎找不到主動行動的著力點；迴避、依賴他人決策、行動前過度求證是常見表現。管理上需要高度結構化的支撐：明確任務拆解、一對一確認、以及充足的正向回饋，才能讓他穩定產出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4168, 'CSR_09', 'C (低)', 'CSR_25', 'A', '與 CSR_25 (樂觀) A聯動：表現為「樂觀解讀、靜待轉機」。他把挫折與不如意解讀為暫時可改善，情緒上維持相對穩定；但缺乏影響結果的主動信念，使樂觀成為「等待好轉」的心理安慰，而非推動主動行動的燃料。相較於低掌控感加悲觀的組合，他不容易陷入沮喪，但在需要快速主動應對的情境，這種「相信會好、但不急著做」的姿態可能延誤關鍵窗口。建議在機會窗口出現時明確指出行動時機，協助他把樂觀轉化為行動訊號。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4169, 'CSR_09', 'C (低)', 'CSR_32', 'A', '與 CSR_32 (自我勝任感) A聯動：表現為「有能力但不出手」。他對自身能力與掌控感有清楚信心，遇到挑戰願意承擔、能穩定輸出；但同時缺乏「自己能影響事情發展走向」的基本信念——這不是能力不足，而是「做了有用嗎」的底層懷疑抑制了主動發起行動的衝動。在有清楚任務指派時表現可靠，但自發推動改變或開創局面的動作少。建議為他設計需要主動影響結果的經驗，讓能力與掌控信念逐步對齊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4170, 'CSR_09', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「接受變化卻不主動應對」。他在高度不確定與頻繁變動的環境中能自然接受變化、不產生不適；但缺乏影響結果的主動信念，使這份從容停留在接受與觀察層次，而非化為主動把握機會的行動——不慌亂但也不出手。這個組合在需要穩定心態的場景是資產，但在需要快速抓住變化中的機會時，主動性不足會造成時機錯失。配上明確的行動指引，他的變化接受度能轉化為穩定推進的基底。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4171, 'CSR_09', 'C (低)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「被動旁觀、對內外都缺乏連結的疏離者」。他少有「自己出手能改變事情」的信念，遇到情境變動傾向等待而非介入；他對所處環境的興趣與價值感也很低，很難感覺到有什麼值得去融入或堅守。在需要主動參與的場合，他幾乎都留在邊緣——不是刻意抗拒，而是既不覺得自己介入能改變什麼，也找不到非投入不可的理由。在管理上，從環境歸屬感著手比直接要求行動更有效；先讓他感覺「這個地方跟我有關」，才有機會觸發他嘗試影響結果的意願。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4172, 'CSR_10', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「深思不前行的高品質守望者」。行動前的評估做得扎實，較少出現草率失誤，但整體動機只求完成在合理範圍、不傾向追求突破；當評估結果顯示「差不多可以」，就不會再加壓。審慎的品質把關讓輸出穩健，卻也讓進取動能受到抑制——高風險高難度的任務往往停在「評估後不推進」的狀態。管理上應主動給予明確挑戰目標，防止審慎成為不前進的掩護。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4173, 'CSR_10', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「想清楚後直接表態者」。他面對紛爭或衝突前會評估情勢，但評估結果是為了讓他更有底氣表達立場，而非尋找退讓方案。他不傾向以溫和或迎合化解衝突，遇到對方不讓步時容易出現直接的對抗性回應。他的謹慎讓他不魯莽，但不代表他會為了和平而收起立場。在需要協商與共識的環境裡，他的直接可能拉長談判時間甚至製造張力。管理上宜事先建立衝突處理機制，讓他的評估和表達都有清楚的結構框架。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4174, 'CSR_10', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮驅動的過度審查者」。他在行動前有完整的評估意願，又對不確定情境極低忍受度，兩者都讓他放慢行動；然而他審慎追求的是品質，對不確定的強烈敏感帶來的卻是持續焦慮——他越評估、看到的模糊越多、越難結束。結果是他的準備期拉長、決策點遲疑，即使評估本已充分也難以判斷「什麼時候可以行動」。管理上應協助區分「仍需評估的資訊缺口」與「焦慮觸發的持續搜集」，並設定評估終止條件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4175, 'CSR_10', 'A (高)', 'CSR_26', 'A', '與 CSR_26 (條理性) A聯動：表現為「流程嚴謹的系統評估者」。對這個人而言，行動前的謹慎不是一種額外的思考，而是天生就長成有條理的樣子——『先想清楚再做』和『先蒐集、再分類、再評估』在他身上根本是同一個動作，想得深入本身就表現為一步一步走。所以他的準備工作高度結構化：知道從哪裡開始、資訊怎麼歸位、什麼時候回頭檢查，遺漏率低、輸出可複製。在穩定環境裡這是很強的可靠性。代價是當環境突變或出現例外時，他那套『又想又排』的節奏一旦被打斷，會比別人更需要時間重建；建議在標準流程之外預先設計一條『例外評估路徑』，讓他遇到突發狀況時仍有可依循的結構。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4176, 'CSR_10', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「等待被問才審慎的評估者」。行動前的評估能力完整，能識別風險、設想後果，但行動發動本身需要外部觸發——傾向在被要求時才回應，不傾向超出範圍主動掃描問題。審慎變成一個「反應型資產」：任務來了品質高，但潛在風險在還沒有人交辦時就不太會被主動揭露。在需要提前識別問題的情境中，這組合可能造成延遲；建議設計固定的主動回報節點，讓評估習慣不只在被問時才啟動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4177, 'CSR_10', 'A (高)', 'CSR_33', 'A', '與 CSR_33 (自律性) A聯動：表現為「計畫扎實的長期自控者」。他在行動前評估風險和假設，確認路徑後就按計畫執行，面對短期誘惑也能維持自我約束。他在推進過程中較少因臨場誘惑或即時回報而偏離既定方向，謹慎的評估和對長期目標的堅守讓他的輸出節奏一致。長週期、需要持續投入的任務是他最能展現優勢的場景；他的風險在執行靈活度上，有時因不輕易偏離計畫而在需要快速調整時反應稍慢。管理上宜定期給他中期回饋節點，讓他確認計畫仍在正確方向上再繼續。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4178, 'CSR_10', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「急著推進的情境評估者」。企圖心強、願意多投入以達到高標準，但審慎程度視情境調節——在目標清楚、回饋快速時，成就導向容易讓評估被壓縮；只有判斷「這件事夠重要」時才會主動拉高審慎程度。這意味著快節奏任務中隱性風險較容易被跳過，而一旦出現返工代價也高。建議在高企圖心任務中設立強制評估節點，避免他在急著推進時壓縮了該有的判斷品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4179, 'CSR_10', 'B (中)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「熟悉後跳過評估的衝刺者」。厭倦感在各類活動形式中都容易迅速出現，而他的審慎本就在熟悉任務中容易被簡化；在重複性工作或長期執行中，他的評估品質風險最高——看似例行的步驟往往成為漏洞累積的地方。在新奇情境中他的判斷尚穩定，但隨著任務熟悉度上升，評估品質可能系統性下滑。建議對例行流程設計外部查核機制，不依賴本人維持審慎節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4180, 'CSR_10', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「疑慮驅動的不完整評估」。他在重要任務上確實有拉高審慎程度的意識，但對自己是否能達成目標本就缺乏把握；於是他的評估不止於「分析夠了」，而是持續往「我有沒有漏掉什麼」的方向延伸——過度求證、反覆確認，反而讓決策窗口被拉長或拱手他人。管理上應設定明確的評估完成條件，並在提供方向確認後推動本人主導後續推進，避免低效能感讓審慎變成拖延的包裝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4181, 'CSR_10', 'B (中)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「有韌性支撐的彈性評估者」。審慎程度隨情境調節，而堅毅性帶來的充沛內在資源讓他不害怕評估做得不夠完整——即使決策後出現問題，也能快速承受、修正。這讓審慎的彈性空間更大，在熟悉任務中偶爾加速也不至於崩潰；但也可能讓他對評估品質的要求過於輕鬆，以「反正我能補」合理化略過某些風險評估。建議區分「可補救的低評估」與「不可逆的高風險點」，對後者設立強制審核門檻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4182, 'CSR_10', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「悲觀偏誤的評估者」。在判斷重要決策時確實會提高審慎程度，但對不如意的解釋傾向長期且普遍——評估過程被悲觀基調所著色，分析時高估失敗機率、低估修正與轉機的可能性。這讓評估流程看起來完整，實則結論可能系統性保守或迴避。管理上應在評估完成後主動請他說明「什麼條件下這個選項值得嘗試」，補充正向路徑的思考，避免審慎與悲觀共同壓縮行動空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4183, 'CSR_10', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動開展但評估時鬆時緊」。在各類情境中都能自發發起行動，主動精神穩定；但審慎程度視情境調節——在熟悉任務或察覺機會的興奮中，評估容易被壓縮成「確認一下」的快速過場。主動性是資產，但若恰好在評估薄弱的節點快速啟動，隱性風險就容易被帶進執行。建議對主動發起的行動設計輕量的結構化評估清單，確保主動性不以跳過風險識別為代價。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4184, 'CSR_10', 'B (中)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「猜疑過濾的評估者」。在重要決策中確實會提高審慎程度，但對他人的偏低信任讓評估框架中多了一個過濾層——分析時不只評估事件風險，也持續猜疑對方意圖是否不利。這使評估更保守，但也更易被社會猜疑而非客觀風險主導。在需要與他人協作的決策情境中，審慎可能退化為對人的防衛性測試；建議區分「對事的風險評估」與「對人的信任判斷」，各自處理而非讓兩者混合污染分析品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4185, 'CSR_10', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「衝向變化的快速行動者」。傾向先做再調整，加上把變化視為常態且自然從中獲取動能，讓他在高不確定環境中推進力強——不需要等到情況穩定才行動，方向模糊也不成阻礙。這組合在快速迭代場景具有明顯優勢，但也讓評估更難插入；「先做」加上「把不確定視為正常」容易讓隱性風險或不可逆點被忽略。對需要不可逆決策或高代價錯誤的情境，建議事前設立固定的風險識別問題清單。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4186, 'CSR_10', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「行動先行規範後補的執行者」。傾向先做再調整，加上較容易把規範視為可調整工具；在目標壓力下，評估和合規查核都被推到「執行後再說」，速度成為主要驅動。這組合在快速推進上有明顯效率，但在有底線要求的情境中容易累積合規盲點——不是有意逾越，而是「先跑再問」的節奏讓邊界審查常常來得太晚。建議在任務開始前設立簡短的「紅線確認」步驟，以低門檻方式補強合規意識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4187, 'CSR_10', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「快速且手段彈性的推進者」。這個人傾向先做再調整，又把『領先』放在第一順位——所以『這個做法公不公平、有沒有越線』這個問題，在他出手之前根本不會浮現：不是他想過了再決定不管，而是對他來說，停下來評估、和回頭檢查邊界，都不在他啟動一件事的方式裡。於是他推進得很快，但在競爭壓力下不公平的手段很容易就『順手』被用上，因為攔截它的兩道關卡——事前評估和公平意識——對他都不是預設動作。在有底線要求的情境，這不能靠他自己事中察覺；管理上必須在任務啟動前就明確框定邊界條件，並設計事中的公平性查核點，把守線的責任放到流程裡而不是放在他身上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4188, 'CSR_10', 'C (低)', 'CSR_20', 'A', '與 CSR_20 (希望) A聯動：表現為「快速有方向的目標衝刺者」。傾向先做再調整，但同時具備把目標具體化、規劃替代路徑的能力；快速行動不是漫無目的的衝撞，遇到阻礙能改道繼續推進。這讓他在動態環境中有實際的推進力，不容易因方向不清而停滯。然而快速行動加上評估後補的習慣，意味著沿途的隱性風險（尤其是不在主路徑上的側面損失）仍容易被忽略；建議在目標路徑規劃中納入明確的風險識別步驟，讓路徑清晰同時帶動風險意識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4189, 'CSR_10', 'C (低)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「快行且需要被看見的展示者」。傾向先做再調整，加上對自身貢獻與地位有強烈的展示需求；行動不只是推進，也是讓自己被看見的場合。這讓行動方向常偏向可見度高的選擇，而非最需要審慎的地方——他既在評估上偏薄弱，又被展示需求驅動，於是可能在重要但不顯眼的風險點上快速略過，在熱鬧但風險可見的場合則投入較多。建議在任務分配上明確說明「低調但高影響的工作」的重要性，並讓這類工作的貢獻能被看見，減少可見性偏誤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4190, 'CSR_10', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「衝進去後又反覆磨的矛盾者」。傾向先做再調整，加上對細節品質的高要求；啟動快，但執行中對不夠完善的容忍度很低，大量時間花在磨修和優化。結果是「先做省了前期評估的時間，後期品質追求卻消耗更多」——不一定比慢慢想清楚再做更有效率，甚至帶來更多挫折感。這組合在快速迭代環境中張力最大：快衝的節奏與精雕的品質要求難以同時滿足。建議明確設定每個交付階段的「足夠好」標準，讓完美主義有邊界地運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4191, 'CSR_10', 'C (低)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「補救力弱的高頻失誤者」。他傾向先做再調整，隱性風險容易被忽略，評估不足帶來的返工或錯誤是可預期的；而在長期高壓或連續變動下他恢復能量較慢、補救較吃力。他不只更容易出錯，每次出錯的代價也更高——因為補救本身對他就是一項耗損。在高複雜度或高代價錯誤的情境中，這是一個需要主動管理的組合；建議在任務中期設置強制的進度確認點，讓問題早發現，避免累積到韌性撐不住的程度才補救。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4192, 'CSR_10', 'C (低)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「快速且開放的高信任推進者」。傾向先做再調整，加上對他人善意的預設穩定且不因不確定而收回；合作啟動快、不需要驗證期，在正向信任環境中推進效率高。然而這組合對兩個方向的評估都偏薄弱：對事的風險評估後補，對人的意圖識別也幾乎不設防。若遇到對方確實不誠信，損失可能在發現前已累積相當規模。建議在重要合作中設計基本的「共識確認」步驟，讓開放與信任維持同時，也保留最基礎的風險識別機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4193, 'CSR_11', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「守規卻直接對抗的原則者」。他對承諾與規則有強烈的信念，且不會因衝突而退讓——遇到不守規的人或情境，他傾向正面表達立場，而非以溫和方式迴避。這讓他在維護規則上有一定的震懾力，但在講究和諧的環境中可能引發較多摩擦。管理上宜給他直接反映問題的正式管道，讓這份對抗能量有出口，而非在日常互動中擴散。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4194, 'CSR_11', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「守規卻策略包裝的矛盾者」。他對承諾的重視是真實的，在行為上也會選擇可被信任的做法；但在溝通與資訊呈現上，他較容易使用策略性包裝，選擇性揭露或用話術引導他人判斷。他的自我認知是「守規」，但旁人有時感受到他說的和做的之間有落差。管理上宜在涉及資訊透明的場合設立明確的揭露標準，減少灰色地帶給他操作空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4195, 'CSR_11', 'A (高)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「躲在合規後面的卸責者」。他對遵守程序是認真的，照章辦事幾乎找不到破綻——但對『結果好不好、有沒有真正解決』的承擔卻很薄。對他而言，『我有照規定做』不只是事實陳述，更是出了事時的免責盾牌：問題若發生，他第一反應是指向流程不全、別人沒配合或環境因素，而不是回頭追補。於是合規與負責在他身上被切開了——形式上的步驟他守得住，實質的結果責任他容易置身事外。管理上不能用『他合規』來代替『他有把事情做成』，必須另外設結果追蹤與補救責任，否則他會一直停在『程序我盡到了』的位置上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4196, 'CSR_11', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「想守規卻衝在評估前面的人」。他是真心想守規的——不踩線、可被交代，是他內在認同的東西。麻煩在於他的做事節奏是先動手、邊做邊修，停下來把風險與後果想清楚不是他的習慣。於是他的守規意圖常常追不上他的行動速度：等他衝出去之後，才發現某個環節已經擦到灰色地帶，而那並非他存心,只是評估補在了行動之後。他最大的風險因此不是『故意違規』，而是『無意識踩線』。管理上不必懷疑他的合規動機，而要在高風險環節替他內建事前確認的節點，讓他想守的那條線，能被執行品質真正接住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4197, 'CSR_11', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「規範堅守的進取執行者」。他對成果有明確企圖心，遇到挑戰會主動把方法和目標往上推；在追求高標準的同時，他也高度重視承諾與責任邊界，較少為了達標而忽略規範。遇到灰色地帶，他的反應是確認而非繞道。這讓他在複雜情境中兼具推動力與可信賴度；管理上給清楚的合規邊界，他會在邊界內全力衝刺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4198, 'CSR_11', 'A (高)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「以規矩錨定秩序的人」。對這個人而言，規則不只是該遵守的行為準則，更是讓世界可預測、讓自己安心的秩序本身；而他本來就把穩定與可預測當成理想狀態，面對變動容易不適。這兩件事在他身上其實是一回事：守規讓他覺得踏實，變動則同時動搖了規矩與他的安全感。於是在穩定環境裡他是極一致、極可靠的合規主體；但一旦碰上制度轉型或流程更新，他會對舊規格外依附，對新做法接受得慢——不全是不認同新規，而是改變本身就讓他不安。管理上在穩態中可放心交付，在變革期則要給他充分的過渡時間與清楚說明，幫他把新秩序也建立成可依賴的東西。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4199, 'CSR_11', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「目標一逼近就替規矩鬆綁的人」。多數時候他守規範，但他的守規帶有條件——資源不夠、目標衝突時，他會去找折衷。把這放進一個對成果有強烈企圖、會主動把目標往上推的人身上，就出現一個特定的脆弱點：目標壓力越高，他心裡『稍微彈性一點應該還好』的聲音就越大。他不是想違規，而是當『嚴守每條規矩』可能擋住他想達到的高標時，他會傾向自己判斷哪裡可以鬆、鬆多少——而這個判斷會隨壓力上升而放寬。這是情境觸發、會隨壓力變動的表現，不是固定樣貌。管理上要在高績效壓力場景裡，事先把哪些底線絕對不可動講死，讓他的衝勁在清楚邊界內運作,而不是交給他臨場拿捏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4200, 'CSR_11', 'B (中)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「需要底線卻敢正面衝突的執行者」。他對規範的遵守有程度之分——在條件清楚時他願意守規，遇到資源不足或目標衝突時傾向尋求折衷；同時他在衝突情境中較少選擇退讓，傾向正面表達立場。這讓他在維護自身立場上不缺力道，但在需要折衷與規範遵守的情境可能引發張力。管理上需明確哪些邊界不可動，並給他合適的衝突出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4201, 'CSR_11', 'B (中)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「壓力一來就擦邊的求勝者」。平時他守規範，但在資源或目標衝突時會找折衷；而他對公平的自我約束本來就弱，傾向把『領先』擺在第一位、容易替不公平的手段找理由。於是在低監督或競爭壓力的場景下，他原本『省點麻煩、彈性一下』的折衷會自然往前延伸成擦邊與規避——因為對他而言，先贏比先公平更要緊，而擦邊在當下感覺起來是合理的。這不是時時如此，而是被競爭與壓力觸發、會隨情境放大的傾向。管理上在涉及競爭或共享資源的場景，要把底線預先設清楚，並用實際的行為稽核取代口頭承諾,別等他自己收手。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4202, 'CSR_11', 'B (中)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「規則彈性且利益敏感的中間者」。他在多數時候願意遵守規範，但對外在利益與地位象徵有明顯敏感度；在資源不足或目標衝突時，他容易尋找折衷，且折衷的方向往往對自己有利。旁人感受到的是他「原則上守規，但每次折衷都很巧合地對他個人有利」。管理上宜設定清楚的折衷邊界，讓他知道哪些調整可以接受，哪些不能碰。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4203, 'CSR_11', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「守規折衷但責任外移的中間者」。他在一般情境有遵守規範的意圖，也能把多數工作做到基本標準；但在遇到失誤或延誤時，他較傾向將原因歸於外部，補救動作相對被動。旁人觀察到的是他「多數時候守規，但出問題就說是環境或別人」。管理上宜在出問題後主動引導他進行責任追溯，而非讓外部歸因成為慣例。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4204, 'CSR_11', 'B (中)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「守規但自律容易鬆動的中間者」。他有遵守規範的意圖，在條件明確時能做到；但他的自律維持相對吃力，在短期誘惑或立即回報面前，守規的堅持容易被說服「這次例外」。旁人感受到他的守規程度隨情境波動，高監督下表現穩，一旦少了提醒就開始鬆動。管理上宜在規範敏感的環節設定定期確認機制，而非依賴他自發維持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4205, 'CSR_11', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「結果優先的彈性行動者」。他把規範視為可調整的工具，也把領先視為第一順位，在兩者都指向「結果說話」時，他的行為邊界尤其容易模糊。遇到目標壓力，他可能合理化不公平的手段，或在規則灰色地帶主動取利。這在強競爭環境中讓他有短期優勢，卻也讓他在誠信判斷上留下明顯缺口。管理上需要強硬的底線提醒，並把合規紀錄納入績效評估。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4206, 'CSR_11', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「目的導向的靈活策略者」。他對規範與溝通誠實度的要求都相對寬鬆——只要目標能達成，他認為詮釋規則的彈性空間和策略性包裝資訊都在合理範圍內。旁人觀察到他在推進目標時很有效率，但難以判斷他說的是否是完整的資訊、做的是否在規範內。管理上需要在重要節點設定明確的透明度要求，並建立定期合規稽核。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4207, 'CSR_11', 'C (低)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「利益傾斜的彈性規範者」。他對規範的態度本來就有彈性，加上對外在利益和地位的高度敏感，讓他在目標壓力下幾乎必然優先選擇對自己有利的詮釋空間。他不一定會公然違規，但會持續在邊緣操作，合理化先拿到再說的做法。管理上需要強硬且明確的底線設定，在高誘因場景尤其要建立明確的合規監控機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4208, 'CSR_11', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「對抗且規範彈性的強硬者」。他面對衝突不退讓，面對規範也不無條件服從，兩者都指向他傾向以自己認定的方式行事。遇到不同意的規則或對立的情境，他更可能的反應是正面表達不滿，同時在規範上尋找對自己有利的詮釋空間。這讓他在需要原則堅守的場合是缺口，在強調協調的環境中更是如此。管理上需要設定強制性的邊界，且用清楚的後果框架取代說服。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4209, 'CSR_11', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「高動能但規範彈性的進取者」。他對成果有強烈企圖心，在挑戰面前會主動升級做法與目標；但他對規範的態度偏向彈性取捨，在目標壓力高的情況下容易把規則詮釋為可調整的工具，而非硬性邊界。旁人感受到他推進力強、敢接難題，但在規範敏感的場景讓人不放心。管理上宜在任務啟動時明確設定哪些邊界不可碰，並在里程碑節點做合規確認。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4210, 'CSR_11', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「責任外移且規範彈性的迴避者」。他對規範的遵守偏向以目標壓力為準則做彈性調整，遇到問題也傾向把原因歸於外部、等待他人解決。出問題後他的處理模式容易變成「規則本來就有彈性，問題又不是我的錯」。這在需要可靠度與誠信的場景是明顯風險。管理上需要在關鍵節點設定強制的責任確認機制，不能期待他自發承擔與守規。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4211, 'CSR_11', 'C (低)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「先行後補且規範彈性的衝刺者」。他傾向先行動再思考後果，同時也傾向把規範視為可彈性調整的工具；這讓他在快速推進時很有效率，但也最容易在事後才發現踩了邊界。遇到不確定情境，他的直覺是先衝，而非先確認邊界在哪。管理上需要在啟動任務前設定強制的邊界確認點，讓他在行動前至少看見規範紅線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4212, 'CSR_11', 'C (低)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「衝動行事且規範隨宜的高風險者」。他較容易把規範視為可調整的工具，在壓力下的衝動反應也容易把這份彈性推到極限。在情緒被觸發的情境，他不只容易說出或做出超出本意的事，也容易在規範邊界上做出草率的判斷。旁人觀察到他「平時已經守規不穩，一遇到衝突就更難預期」。管理上需要明確的底線與後果框架，並避免讓他在衝突情境中單獨做高風險決策。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4213, 'CSR_11', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「擁抱變化但規範彈性的彈性者」。他把變化視為常態，對新情境能快速適應，不需要太多調適期；但他對規範的態度同樣充滿彈性，容易把「應對變化」延伸成「規範也可以隨之調整」的邏輯。在快速變動的環境中他的適應力是明顯優勢，但這份適應力也讓他在規範遵守上缺乏穩定的底線感。管理上宜在變動情境中明確哪些規範不隨情況調整，並設定不變的合規基準線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4214, 'CSR_12', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「有信心也有企圖心的目標驅動進取者」。他對努力能換到結果有穩定的信念，對更高的表現標準也有強烈的追求；他在面對高難度目標時既不自我懷疑、也不缺乏動力，行動起來有清楚的方向感。遇到挑戰，他的反應是「怎麼把方法再升一級」而不是「我能不能做到」，推進意志強、能量充沛。旁人常看到他主動接下困難任務，並在過程中不斷調整方式、不輕易收手。在有明確回饋的環境中他表現最好；需要注意的是，他對自我標準的要求可能讓他接下超出資源的承諾，管理上宜協助他設定優先序。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4215, 'CSR_12', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「信心撐不住逆境的脆弱衝鋒者」。他在任務啟動時以強烈信心主動衝前，遇到高標目標傾向拆解推進而非退縮，然而一旦逆境強度超出預期，用來緩衝打擊的承諾感、控制感與挑戰資源均十分有限，內在撐持出現明顯缺口。於是他帶著效能信心比他人起跑更猛，潰退時的落差卻也更顯突然——因為他外表的積極掩蓋了底層資源的薄弱。建議為其設計中途壓力閥，避免讓積極姿態累積到資源耗盡才被看見。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4216, 'CSR_12', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「信心強但悲觀底色讓推進出現落差的矛盾執行者」。他對自己的執行能力有清楚的把握，開始一項任務時能主動拆解路徑、全力投入；然而他對「最終結果是否能如願」這件事帶著偏悲觀的底層解釋，不如意時容易把失敗視為長期且普遍，讓他在挫折後難以維持原本的動能。旁人感受到的落差是：他前期非常有能量，但遭遇阻礙後的恢復速度比預期慢，有時甚至對繼續努力是否值得提出疑問。在有明確進展可見、回饋及時的環境中，他的信心會壓過悲觀底色；若阻礙拉長，兩者的張力就會浮現。管理上在卡關時及時提供正向進展回饋，能有效幫助他維持推進節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4217, 'CSR_12', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「動能強卻頻繁受困於模糊的行動者」。他同時是『確信自己能完成目標』的人，也是『極難忍受模糊與未知』的人——這兩件事都真實，只是隨情境清晰度輪流現身。資訊充分、方向明確時，他的把握感全然展開，主動拆解、直接推進；可是一旦訊號變得不明，他並不是對自己的能力起了疑，而是那份『懸而未決』本身令他坐立難安，於是反覆確認、再三求證來消化焦慮。對他而言，模糊不是能力問題而是體感上的不適，因此他的高動能在清楚的環境裡是優勢，在曖昧的環境裡卻被求證的動作佔住。管理上應主動提供結構、里程碑與明確的確認點，把不確定先行壓低，他的行動力才能順暢釋放，而不是只丟一句『去做』。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4218, 'CSR_12', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「確信達得到卻不覺得自己能主導的矛盾推進者」。他對努力轉化為結果抱有明確信心，會主動接下挑戰並拆解推進；然而同時對自身能否影響事態走向缺乏把握，遇到超出直接掌控的變數時，傾向被動等待而非繼續搜尋路徑。這意味著他在可控情境中表現強，但當障礙來自外部或結構層面，需要協助辨識哪些槓桿點仍在他手中。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4219, 'CSR_12', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「快速出手且確信達成的衝刺者」。他對自己能把目標推到位有明確信心，同時傾向先行動再補評估，啟動速度相當快——遇到高標目標時往往直接拆解就衝，不會在不確定點停留太久。這在快速迭代場景極具效率，但他也容易在推進後才碰到原本可以事前識別的隱性風險，補救成本較高。建議在重要決策節點設置結構性的評估停頓，讓速度優勢與風險意識都能發揮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4220, 'CSR_12', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「信心充足卻只在被呼喚時才現身」。他確實對自己能完成目標有清楚把握，被指派的任務上執行可靠、遇到高標也不因不確定而退縮；但他同時是『主動發起的念頭很少自己冒出來』的人——不是有什麼東西卡住了他的信心，而是這個人本來就把『要不要自己去接』留在被要求之後。於是他的篤定是真實且看得見的，只是它出現在任務送到他面前之後，而非之前。對管理者而言，他是極佳的任務承接者：交給他、講清楚，他就穩；但若只是等他自己走來拿，多半等不到。要讓他的能力完整展開，需要設計明確的邀請或指派機制，讓那份本已存在的信心有被啟動的入口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4221, 'CSR_12', 'A (高)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「確信能成卻收尾不足的進取者」。他樂於接下高難度目標，信心讓他在啟動與推進上毫不猶豫；然而在自我監控、節奏維持與收尾品質上，盡責的底層資源較為薄弱——情緒或情境一旦干擾，就容易出現拖延或交付不完整。這意味著他的潛力實現率取決於外部結構的強度：若有清楚里程碑與收尾機制，信心才能轉化成穩定的高品質輸出；若缺乏，啟動時的積極姿態會與最終結果產生落差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4222, 'CSR_12', 'B (中)', 'CSR_20', 'C', '與 CSR_20 (希望) C聯動：表現為「能力不差但沒有前進路徑」。他的能力感通常足夠、有基本推進意願，但在新情境或遇到阻礙時，希望感的路徑化能力較弱——較難把動機轉化為替代策略，容易在方法受阻後停在原地而非改道。管理上應主動提供路徑框架與阻礙後的導引，避免讓他單獨面對「路不通了，現在怎麼走」的空白。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4223, 'CSR_12', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「確認後能跑卻難以從打擊中復原」。他在標準清楚且環境穩定時能穩定輸出，但韌性資源有限——遇到失敗、衝突或責任重新分配後，復原速度較慢，能量耗損容易累積。這意味著他對環境的穩定性有較高依賴：支持充足時表現可靠，一旦高壓持續或打擊連發，信心容易被耗空且難以自行重啟。建議定期設置緩衝節點，並確保他在挫折後能及時獲得方向確認與支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4224, 'CSR_12', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「企圖心推著但需確認才加速」。他對表現與成果有明顯企圖心，願意多投入以達到更高標準；然而在新領域或高風險情境，效能感需要先確認方向才能完全釋放——他的高成就動機帶來強烈的投入意願，但這份意願在不確定中會先暫停等確認，而非直接衝出去。當標準清楚後，他就能推出高強度輸出。建議縮短確認週期，讓企圖心不至於在等待中消散。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4225, 'CSR_12', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「需要雙重確認的謹慎等待者」。他在新情境或高風險任務中，效能感本就需要方向確認才能加速，而對自身整體能力與掌控感也同樣信心不足——他的啟動門檻明顯偏高，確認需求也比單一維度不足時更強烈。得到確認與支持後他能穩定下來，但若資訊或支持缺位，他的猶豫期與求證行為會相應延長。管理上需要更主動地提供結構與能力確認，而非等待他自行克服。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4226, 'CSR_12', 'B (中)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「穩定中才能確認並前進」。他的效能感在標準清楚後能穩定釋放，而對變化與不確定的不適傾向則讓穩定環境成為必要條件——兩者指向相同的「先求穩才加速」需求。在環境可預測且方向清楚的情境下，確認後便能快速進入持續輸出狀態；但頻繁變動不僅讓確認難以完成，對環境本身的不適也會同步消耗他的行動動能。建議在變動期主動提供節奏錨點與明確分段目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4227, 'CSR_12', 'B (中)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「責任感強但信心需確認才展現」。他有強烈的責任決心，遇到問題會主動承擔補救，不輕易推卸；但在新領域或高風險情境，效能感的確認需求使他在全力投入前傾向先釐清標準。他即使在等待確認時仍積極求證，一旦確認到位便以高責任感驅動穩定且可靠的執行。管理上提早給予標準和範圍說明，能讓他的責任感更快被釋放出來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4228, 'CSR_12', 'B (中)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「信任他人讓確認成本變低的溫和推進者」。他的效能感在確認後能穩定釋放，而高度信任他人的傾向使確認過程本身更有效率——他不帶防禦地接收上級或同儕的引導，反饋吸收快且善意解讀，讓確認週期縮短。這組合使他在有良好溝通氛圍的環境中特別容易發揮，但也需要注意：過度信任有時會讓他在指引不準確時缺乏自行校正的警覺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4229, 'CSR_12', 'C (低)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「逆境撐得住卻始終懷疑自己」。他具備充沛的承諾感、控制感與挑戰資源，面對壓力與逆境時不容易垮；然而對能否完成目標的信心依然薄弱，面對挑戰時仍傾向遲疑、過度求證。這形成一種獨特的「持久但猶豫」模式——環境再難他不離場，但在場卻常常停在確認與懷疑的循環中。管理上宜善用其韌性資源提供拉力（告訴他「你一定撐得過去」），再輔以能力確認（告訴他「你也確實做得到」），兩個維度都需要。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4230, 'CSR_12', 'C (低)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「不信自己也不信能影響局面的雙重被動」。他對能否完成目標缺乏把握，同時也不太相信自己的行動能影響結果走向——他既不確定做不做得到，也不確定做了有沒有用，於是行動的啟動理由被雙重削弱。這不只是缺少信心，而是缺少「做了有用」的基本信念，使他在缺乏外部推力時幾乎無法自主前進。管理上需要從可觀察的小範圍因果鏈開始，讓他先看見「我做了→結果改變了」，再逐步建立效能與掌控的雙重信念。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4231, 'CSR_12', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「遲疑者遇上強硬者」。他在任務面對挑戰時傾向遲疑、過度求證或依賴他人決策；但面對紛爭或分歧時，卻傾向直接表達立場甚至出現對抗反應。他在任務上看起來被動、不確定，在人際邊界上卻強硬且直接，形象不易被讀懂。管理上需要分別處理——任務面提供能力確認降低遲疑，關係面則預先設計衝突緩解機制，避免直接對抗在他已處於懷疑狀態時進一步消耗他的資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4232, 'CSR_12', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「不確定感觸發強烈焦慮的低信心猶豫者」。他對自己能否達成目標缺乏把握，對不確定又有強烈的負面反應，讓他在面對任何含糊任務時都陷入高強度的焦慮狀態。他的啟動門檻非常高——在看清楚所有條件之前，他很難讓自己開始行動；即使開始了，一旦碰到預期外的變數，行動就容易中斷，轉而進入反覆確認的迴圈。旁人感受到的是他行動力極低、需要大量細節和保證才能移動；在高不確定的環境中，他可能幾乎處於停滯。管理上需要把任務切成資訊充分、邊界清楚的小段，讓他每次只面對有限的不確定，給他一個能穩步推進的脈絡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4233, 'CSR_12', 'C (低)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「規範守得住但任務推進不下去」。他高度重視承諾與責任邊界，遇到灰色地帶也傾向選擇可被交代的做法，誠信層面非常可靠；然而在目標推進上，對自身能力缺乏把握使他頻繁遲疑或依賴他人決策。這形成一種不對稱的形象：可以完全信任他不會走錯邊，但無法期待他在難題面前主動拆解出路。建議在評估時分開看待他的規範可靠性與績效主動性，並在任務層面提供額外的信心確認結構。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4234, 'CSR_12', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「容易放棄又容易失去投入感」。他對完成目標的信心薄弱，遇到挑戰傾向遲疑或依賴他人；同時在活動缺乏新鮮感時很快失去投入，兩種退出動力同時運作。任務初期若能吸引他，他會投入，但信心不足可能讓早期推進就已搖搖欲墜；中後期的厭倦感再接力，使完整交付面臨雙重障礙。管理上需要同時設計能力確認結構與情境新鮮度維持機制，缺一不可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4235, 'CSR_12', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動出擊卻在門口自我否定」。他具備自發開啟行動的強烈意志，即使方向模糊或缺乏支持也不影響想主動的衝動；然而效能感的薄弱讓他在真正執行前反覆遲疑——主動精神推著他往前，自我懷疑又把他拉回來，形成一種在起跑線上反覆來回的狀態。外部觀察者可能看到他表達很多主動意願，但實際執行卻相對有限，容易產生言行落差的印象。建議針對他主動發起的事項，立即提供小範圍可成功的執行入口，讓信心在行動中累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4236, 'CSR_13', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「無聲付出的關懷者」。他對他人困境的同情不因消耗而退縮，但本身對達成更高目標或主動改善的企圖心偏低；這讓他成為穩定的情感後盾，卻可能停留在撫慰而非推動改變。對需要長期支持的人而言這是安全的存在，但若對方需要的是積極的解決動能，他可能難以提供。管理建議：搭配有明確目標導向的協作夥伴，讓關懷轉化為有節奏的行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4237, 'CSR_13', 'A (高)', 'CSR_03', 'C', '與 CSR_03 (利他行為) C聯動：表現為「情感濃但不付出」。他能深刻感受到他人的困境，同情反應是真實的，但同時以自身利益為優先考量，較少主動展現體貼或犧牲行為；這造成一種特殊的張力：高度的情感接收，配上相對收斂的實際行動。在輕度支持場景尚可，但當對方需要具體幫助時，言行落差會讓信任受損。建議明確區分「理解他人」與「願意為他人行動」的責任邊界，避免過度期待帶來的失落。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4290, 'CSR_15', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「確認後仍擔心能否做到」。他在指示理由充分時才決定配合，且對自己完成目標的能力缺乏把握——他的兩個「需要確認」傾向同時存在，於是他在執行全程都有較高的求證頻率。B 段呈情境敏感狀態：指示清楚後他可以啟動，但推進中他仍需主管定期確認方向正確，幫助他建立執行節奏，減少因不確定而中斷的風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4238, 'CSR_13', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「護弱卻不退讓的直言者」。他對他人困境的同情不因頻繁接觸而減損，即使長期面對大量需求也能持續投入情感；在各類互動中，他對需要關懷的人自然靠近。在衝突或紛爭場合，他不選擇退讓或回避，而是直接把自己的立場說清楚，必要時會繼續爭辯到底。具體情境中，他可能一邊積極為處於困境的人發聲，一邊在認為對方立場站不住腳時毫不收手地反駁；他的關懷和他的強硬同樣真實，也同等持久。管理上，他適合需要主動介入弱勢處境的工作，但要留意在團隊對話中對抗性反應可能使協作摩擦升高。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4239, 'CSR_13', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「同情卻不公平的助人者」。他對他人困境的同情是真實的，但同時較容易把領先視為第一順位、合理化不公平手段；這形成一種危險的組合：對人的情感感知能力很強，讓他在互動中容易建立信任，但當利益來臨，他可能選擇利用這份信任換取優勢。建議在評估此人可信度時，以可查核行為記錄為依據，不單以其展現的情感溫度作判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4240, 'CSR_13', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「重情卻難以撐持的關懷者」。他對他人困境的同情在正常情況下確實穩定深厚，但他的堅毅性由承諾、控制、挑戰三種內在資源組成，而這三方面都偏弱——逆境一旦加劇，他用於緩衝壓力的內在資源有限，於是在他人最脆弱的時刻，他自己也承受不住。對長期服務高壓群體的角色尤需留意，避免過度要求穩定支持而忽略其承壓極限。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4241, 'CSR_13', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「深情卻容易衝動回應的關懷者」。他對他人困境感同身受的強度是穩定且真實的，但在情緒高張時較容易被推著走、出現衝動承諾或行為過頭；這讓他在危機時刻可以第一時間衝上去，但也可能許下無法兌現的承諾或做出事後需要解釋的行動。建議在高壓情境中建立「先停頓確認」的機制，讓關懷的溫度不因衝動損耗信任。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4242, 'CSR_13', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「悲觀卻持續關懷的陪伴者」。他不因情感消耗而退縮，持續陪伴困境中的他人，但對不如意的解讀傾向長期且普遍——他能給的是穩定的情感在場，卻難以提供「情況可以改變」的希望感。這對需要有人「在」的人是禮物，但對需要被帶出困境的人可能是困境的延長。建議搭配具積極框架的夥伴，讓穩定陪伴與希望重建互補。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4243, 'CSR_13', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「深情包裝的操控者」。他對他人困境的同情在感受層面是真實的，但同時較容易把包裝或操弄視為達成目標的工具、選擇性揭露資訊；問題在於，深度的關懷行為讓對方更容易卸下防備，使操弄更難被察覺。這是一種高風險的組合，尤其在信任度高的關係中。評估建議以行為一致性和可查核的承諾兌現率作為判準，而非以情感共鳴深度替代信任依據。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4244, 'CSR_13', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「單向付出的溫情孤島」。他對他人的同情與關懷在行為上持續穩定，但對他人意圖的預設是警戒而非善意；結果是一種奇特的關係樣態：他在付出，但從未真正放鬆防衛，對方感受到溫暖卻也感受到某種保留的距離。這種組合使深度關係難以成形。若任務需要他長期穩定支持他人，建議提供信任佐證的機制，而非期待他自然降低防衛。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4245, 'CSR_13', 'B (中)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「情緒過載時也保持友善」。他在日常互動中能察覺並回應他人需求，面對多重壓力時會主動調節情感投入程度；但因親和性的熱情與合作傾向穩定，即使在調節同理的時刻，對方仍感受到友善而非冷漠。這讓他的壓力下行為不易被誤讀為疏離，是一個對高壓環境有緩衝效果的組合。建議善用其在壓力期仍維持的人際溫度，適當分工避免情感耗竭。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4246, 'CSR_13', 'B (中)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「有心無力的關懷支持者」。他能在日常中感知並回應他人困境，但盡責維度（包含自律、條理與收尾等多個層面）偏弱，意味著當情緒負荷升高時，「情感關注」與「實際執行承諾」同步承壓；這讓他在支持他人時可能讓對方感受到被理解，卻不一定被可靠地幫到。建議以明確的任務切割取代模糊的「我會幫你」式承諾，讓支持行為有可預期的邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4247, 'CSR_13', 'B (中)', 'CSR_17', 'A', '與 CSR_17 (溫和有禮) A聯動：表現為「柔軟但可能過度包容的接納者」。他在日常互動中能察覺他人需求並展現關心，又即使面對高度摩擦也維持溫和，於是他形成一個幾乎不批評、難以說「不」的樣子；對方感受到高度接納，但他反饋的誠實性會下降。這對需要安全感的人是資產，但在需要指出問題的場景他可能無法提供真實的校正訊號。建議為其設計明確的反饋責任，避免過度包容讓問題累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4248, 'CSR_13', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮中仍努力關懷的支持者」。他在日常互動中能敏感察覺他人的需求，但無論情境不確定性輕重都容易產生強烈的負面反應；當環境模糊度升高，他需要同時承擔自身的焦慮與他人的困境，此時他的情緒資源吃緊，支持品質下降且自身也快速消耗。管理建議：在高模糊情境中減少其情感支持責任，先穩定其自身的確定性需求，再期待其有效支持他人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4249, 'CSR_13', 'B (中)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「感知到痛苦卻難以帶出力量」。他在日常中能敏感回應他人困境，但心理資本的四個組成（希望、效能感、韌性、樂觀）都偏弱，意味著他能進入對方的痛苦，卻難以從中帶出面向未來的行動動能或希望框架；當雙方都在低資源狀態，支持反而可能相互加重消沉。建議在需要此人提供情感支持的場景，同步引入外部的積極資源或目標框架，避免支持陷入共同的無力感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4250, 'CSR_13', 'B (中)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「情感投入有節制的堅守者」。他在日常互動中能察覺並回應同儕的需求，同時對組織的忠誠與承諾不受條件好壞影響；他既是人際層面的情感資源，也是組織層面的穩定錨點。當多重壓力升高時，他的情感調節機制保護了忠誠的兌現能力，讓他不至於因過度燃燒而斷線。這是一個在高壓環境中具備持續貢獻潛力的組合。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4263, 'CSR_14', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「不妥協的直接抗辯者」。他不只拒絕自己使用不公平手段，在面對他人違規或擦邊球時也傾向直接對抗而非默許退讓——公平原則成為他爭辯的依據，而非只是個人底線。這種組合在需要揭露不當行為的場景很有效，但在需要外交彈性或衝突管理的環境中容易造成關係張力。建議在涉及規則執行的角色中善用他，並協助他區分「值得正面衝突的邊界」與「可以協商的灰色地帶」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4251, 'CSR_13', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱情外殼下的情感空洞」。他對人際接觸真心自在、合作善意穩定展現，但面對他人困境的情感反應平淡，較少自發產生同情；結果是一種令人迷惑的組合：接近你的行為頻繁而友善，但在你最需要被理解的時刻，對方感受到的只是禮貌式的回應而非真正的共鳴。在需要高情感敏感度的支持角色中，此組合可能產生期待落差，建議明確分工讓其發揮人際潤滑的功能，而非深度情感支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4252, 'CSR_13', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「冷靜轉向的變革推動者」。他面對他人困境時情感反應平淡、傾向理性看待，同時在各類不確定與變動情境中能自然保持開放，不需額外調適；這讓他在動盪時期成為穩定的推進力量，不被情緒面的混亂打亂節奏。但人際支持的缺席在組織變革或危機期間可能讓其他人感到孤立無援。建議搭配情感資源豐富的夥伴，讓理性推動力與人情溫度互補。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4253, 'CSR_13', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「結果導向的主控者」。他面對他人困境時傾向理性看待、不易產生情感投入，而自控力的強烈主動掌控傾向使他快速將困境轉化為「需要解決的問題」；這在需要行動的時刻非常高效，但對方感受到的是主導式的介入而非被理解。在人際支持場景，此組合可能讓對方覺得「被處理」。建議在解決問題之前先確認對方需要的是協助還是陪伴，避免行動速度超過關係建立。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4254, 'CSR_13', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「彈性規則下的疏遠執行者」。他面對他人困境情感反應平淡、傾向理性看待，加上較容易把規範視為可調整的工具、優先選擇結果導向做法；他在執行場景中可能快速推進，但對他人的感受和規則的邊界都採取實用主義態度。這在高壓任務中有效率，但也可能對周遭同事造成可感受卻難以具名的疏離感與不公感。建議提供明確的規則底線提醒，並補足人際影響的反饋機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4255, 'CSR_13', 'C (低)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「冷感記恨的距離維持者」。他面對他人困境情感反應平淡，較少自發產生同情，同時面對冒犯或過錯傾向長時間持有不滿、難以釋懷；於是他形成一個人際距離持續擴大的動態：他不主動靠近受苦的人，也不主動修復受損的關係，關係中的疏離趨向自我加固。若此人處於需要高度協作的環境，人際關係的消耗與斷裂速度值得早期介入，避免積累成不可逆的隔閡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4256, 'CSR_13', 'C (低)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「理性自利、情感疏離的務實者」。他面對他人困境時情感反應偏向平淡，較少自發湧現同情或想幫忙的衝動，習慣用理性視角看待周遭發生的事。對於利益、地位或外在象徵，他有清楚的重視與敏感，傾向把對自己有利的選項放在前面，對公平或謙遜的自我約束要求不高。在具體情況裡，他遇到他人需求時會先評估介入是否對自己有意義，才決定投入程度；在資源或機會的分配場合，他不太因道義壓力而退讓，更習慣用手上的條件爭取對自己有利的結果。管理上，給予明確的個人回報機制較能驅動他的投入；情境若要求他主動關照他人感受或主動分享資源，需要清楚的規範或外部問責才更可靠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4257, 'CSR_13', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「追求完美卻忽視人的執行者」。他對細節與品質有反覆檢查與優化的高度要求，同時面對他人困境情感反應平淡、傾向理性看待；在工作場景中他是品質標準的捍衛者，但也是人情溫度的缺席者——同儕在壓力與挫折中不會從他這裡得到情感支持，只會得到品質要求。這個組合在交付質量上是加分，但在高壓期的人際氣候上是減分，管理者需主動補充情感支持的資源，避免完美標準在缺乏人性緩衝下變成壓力放大器。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4258, 'CSR_13', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動出擊卻不感同身受的推進者」。他在各類情境中都能自發超越要求地投入，同時面對他人困境情感反應平淡；這讓他成為一個行動力十足的推進者，但他在推進過程中不感知也不調整對他人情緒的影響——對方既感受到被帶著跑的動能，也感受到自己的狀態未被看見。在需要高速推進的任務中這是加速器，但在需要人心凝聚的場景中可能適得其反。建議搭配能感知並承接情緒的夥伴，讓主動精神有人性溫度護航。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4259, 'CSR_13', 'C (低)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「雙重脆弱的孤立個體」。他面對他人困境情感反應平淡，同時在長期高壓或連續變動下容易能量耗竭，補救與恢復較吃力；這讓他既缺乏對外的情感連結資源，也缺乏對內的緩衝恢復能力，兩種資源的同步薄弱在危機情境中風險最高。對需要長期穩定輸出與人際協作的角色而言，此組合需要外部支持結構的積極介入，包括明確的角色邊界、壓力監控與定期資源補充機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4260, 'CSR_14', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「守公平卻擅包裝的說服者」。他在利益與手段上守得住對等——不偷、不貪、不靠占人便宜取勝；但在資訊怎麼呈現上沒有同樣的不安，慣於強調對自己有利的一面、必要時選擇性揭露、用漂亮的說法影響對方判斷。對他而言「我沒有占你便宜」和「我把話講得對我有利」是兩回事。管理上要注意：他的公平名聲是真的，但不宜據此推論他在溝通上也完全透明；涉及需要完整揭露的場景，應明確要求事實的完整性，而非倚賴他的自陳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4261, 'CSR_14', 'A (高)', 'CSR_23', 'C', '與 CSR_23 (低物質傾向) C聯動：表現為「原則守場卻受物質誘惑拉扯」。他不因為利益豐厚就改用不公平手段，但物質敏感讓每次放棄捷徑都更真實地感受到代價——堅守公平對他而言不是輕鬆的預設，而是重複的主動選擇。這種組合在高誘因環境下是壓力來源，長期積累可能出現隱性不滿或對公平規則本身的質疑。建議定期讓他感受到「用正當手段得到的成果」被看見，否則原則容易被侵蝕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4262, 'CSR_14', 'A (高)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「界線合一的守正者」。對他來說，『這件事不能做』和『這樣對人不公平』往往是同一個感覺，而不是兩道分開的檢查——所以面對灰色地帶他幾乎不替結果導向找理由，越界與否的判定是直覺性、一體的。這讓他的行為高度可預測，也很難被說服『這次是例外』。這種人在需要高度廉潔或合規的角色是強項，但在彈性需求高的環境會顯得僵；管理時給他清楚的規則框架，否則模糊地帶會讓他持續消耗判斷資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4264, 'CSR_14', 'A (高)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「善意出發的公平連結者」。他以善意預設他人意圖，也拒絕用任何形式利用對方，形成真正對等的互動起點——既不設防、也不占便宜。這種組合在成熟互惠環境中建立快速且高品質的合作，但在對方並非同樣善意的情境中，容易成為被利用的一方而難以早期察覺。管理上需提醒他，信任可以是預設，但仍要建立基礎的自我保護機制，尤其在資源或利益分配不對等的場景。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4265, 'CSR_14', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「自負其責的公平行動者」。他把事情做不好視為自己的問題、主動補救，也拒絕透過剝削或利用他人來逃避困境——兩個特質形成完整閉環：歸因往內、路徑往正。這種組合在高壓情境中可靠度極高，但若環境長期提供的資源不足以配合他的自我要求，會形成單向耗損。建議確保他的責任範圍與對應資源對等，否則「自負其責 × 不走捷徑」的組合可能導致持續透支。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4266, 'CSR_14', 'A (高)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「守規但低黏度的過客」。他對公平原則的執守不因環境利誘而動搖，卻也不因對環境的深度依戀而留下——在崗時行事公正，條件不利時傾向離開而非堅守。對團隊而言，他是短期可靠、長期難以預期的成員；公平守住了，但連續性受環境好壞牽動。建議把他安置在條件相對穩定的場景，並在制度設計上讓公平行為有可見的回報，降低「守規但無留因」的流動風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4267, 'CSR_14', 'B (中)', 'CSR_34', 'A', '與 CSR_34 (誠懇) A聯動：表現為「壓力下情境鬆動的誠實者」。他平時溝通直接透明，不擅長話術也不傾向包裝；但在強烈競爭或目標壓力下，公正性開始視環境容忍度調整，出現擦邊球心態——不是說謊，是選擇揭露的完整性開始有選擇性。這種組合讓問題不在「他欺騙了」而在「資訊提供是否完整」，外部很難早期辨識。需要在高壓任務節點提醒他，部分揭露與完整透明的差距，並建立資訊完整性的明確標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4268, 'CSR_14', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「追高標時邊界漸移」。高企圖心讓他在競爭情境中持續尋找方法優化結果，公正性在多數情況守住，但「卓越就該做到」的思維框架讓擦邊球的心理門檻降低——邊界的移動不是惡意的，是被目標合理化的。問題往往出在「我只是在找創意方法」與「我利用了資訊不對等」之間的模糊地帶。建議在高競爭任務中定期做行為倫理盤點，讓他主動釐清方法的邊界，而非等到結果出問題才回頭看。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4269, 'CSR_14', 'B (中)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「衝動誘發下的擦邊行動者」。他對公平規則沒有強烈敵意，在平靜狀態也多半守住；但他衝動管理弱，於是在競爭升溫或情緒拉高的瞬間，他往往在尚未完成倫理評估前就已行動，擦邊球不是他規劃出來的，是他的速度超過反思造成的。事後他常需修補，但信任成本已付出。建議在高壓任務中加入強制暫停機制（如二人確認），讓他的公正性在重要決策點有機會追上衝動速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4270, 'CSR_14', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「掌控感驅動的邊界測試者」。他對能影響結果有強烈信念，也主動採取行動；他的公正性在競爭壓力下已視環境容忍度調整，傾向更系統性地探索規則邊界能走到哪裡，而不只是偶爾擦邊。在規則清晰的環境中這是可管理的競爭力，但在規則模糊或文化寬鬆的環境中可能快速滑向更明顯的手段。需要在規則設定層面給予清楚的硬底線，讓他的掌控感有明確邊牆。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4271, 'CSR_14', 'B (中)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「記住虧欠的機會主義者」。他在競爭中的公平守則本就有情境彈性，加上面對冒犯時長期持有不滿，使得過去的不公平經驗成為現在鬆動邊界的心理許可——「他們先不守規，我也不必太嚴」。這不是衝動，是有記憶、有對象的計算。在需要跨團隊長期合作的場景，這種組合容易讓歷史摩擦積累成結構性衝突，建議在發生冒犯後主動介入修復，而非等他自行消化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4272, 'CSR_14', 'B (中)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「被看見需求推動的灰色選擇者」。他有強烈的被看見需求，在競爭和評估場景中傾向凸顯自身貢獻；他的公正性本就在壓力下帶有情境彈性，而他又有這份被看見的動機，於是他在「是否完整歸功他人」或「選擇性呈現成果」上更難守住邊界。問題不一定以明顯剝削表現，更多是出現在歸功、責任分配與成果呈現的細節。管理上需要在評核設計中納入多方來源的事實核對，而非只看個人自陳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4273, 'CSR_14', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動出手的資源竊取者」。他對結果有掌控信念、主動採取行動，同時對不公平手段沒有抑制力——這讓利用他人不是偶發行為，而是穩定的系統性策略。每次機會出現，他都有意願也有執行力把它轉成優勢，且行動方式較為穩定，外部難以從單一事件辨識模式。建議在角色設計上讓他的績效有清楚的方法可追溯性，而非只看結果，並搭配多方交叉確認。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4274, 'CSR_14', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱情包裝下的利用型合作者」。他能在幾乎所有人際場景建立快速信任和熱情連結，也正因為如此，公正性 C 的利用傾向有了最好的掩護——人們對他的第一印象是善意和可靠，難以將後來的佔便宜行為和他本人連結。問題的嚴重性在於影響範圍廣：廣泛的信任網絡意味著更多潛在的被利用對象。建議在高誠信需求的角色，不以人際印象作為主要評估依據，而需建立可追溯的行為記錄。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4275, 'CSR_14', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「結果優先的義務規避者」。規範對他是可調整的工具，公平也是可合理化繞過的限制——在目標壓力下，兩道過濾都失守，行為幾乎完全轉向「最有效路徑」，不管那條路是否損害他人或違反規範。這種組合是合規風險最高的類型之一，因為他有雙重的自我合理化基礎。建議在流程設計層面加入強制的合規查核節點，而非依賴個人良知或一般提醒，並確保問責機制清楚可執行。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4276, 'CSR_14', 'C (低)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「既取巧又輕信的盲區型操作者」。他把領先擺前面，願意利用他人換優勢；但對人卻有近乎不設防的善意預設，很少懷疑別人也在算計他。這讓他出手取利時毫無顧忌——他預設對方不會防他、不會反將他一軍；可同一份輕信也成了他最大的破口：他算計別人，卻防不住別人算計自己，容易過度依賴合作對象、把不該交的信任交出去，事後被自己信任的人所傷而毫無預警。管理上要雙面看：既要防他取巧，也要意識到他因輕信而生的判斷漏洞，別把他放在容易被同類反噬、或他的盲目信任會放大損失的位置。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4277, 'CSR_14', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「自發尋找機會的優勢竊取者」。他能在沒有方向、沒有支持的情境下自發開啟行動，這種主動性與手段傾向結合後，意味著他不是等待利用機會——他主動創造。在沒有人要求他的情況下，他也會識別可利用的情境並推進，使問題行為更難追溯至具體任務指令。管理上需要對他的自發行為範圍設定清楚邊界，並對超範疇行動建立透明的事後報告機制，讓主動性在有限的邊界內運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4278, 'CSR_14', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「高自律驅動的精算剝削者」。他的工作表現一貫可靠，主動掌握進度、少需催促，這個高自律的外在形象很難讓人聯想到手段問題；但正是盡責帶來的系統性，讓他對不公平手段的使用更有計畫、更難被察覺——不是衝動失誤，而是穩定安排。這種組合製造了最強的「反差保護」：靠著高可靠度的外在形象，維持對內部手段選擇的長期掩護。建議在績效評估中同時納入方法透明度的追蹤，而非只看輸出結果的品質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4279, 'CSR_15', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「規矩框內的穩定執行者」。他對既有流程與指示的配合度高，面對各類程序要求都能穩定遵從，較少出現質疑或抗拒；在工作完成的目標上，他傾向做到合理範圍即可，不會主動尋求更高難度或額外突破。執行任務時，他一邊嚴格對照要求把每個步驟落實，一邊對超出任務範疇的事保持距離，不主動爭取表現空間。在回饋明確、要求具體的環境裡他能穩定產出，但若情境需要自發超越或自行提高標準，他通常不會率先啟動；管理上宜清楚設定任務範圍，並在需要更高貢獻時明確提出要求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4280, 'CSR_15', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「遵令卻抗衝突」。他是那種「對上服、對人不讓」的人：上面交代的事他真心願意照辦，可一旦這件事得靠跟旁人協調、退讓才推得動，他骨子裡直來直往的那一面就頂上來——對他而言「服從指示」和「凡事好商量」根本是兩回事，他只認前者。於是任務啟動沒問題，真正的關卡在落地：凡是需要多方磨合的指令，別預設他會自動把人和氣處理掉，最好把衝突該怎麼解也一併寫進指示裡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4281, 'CSR_15', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「系統內的可靠支柱」。在他身上，「該照規矩做」和「我本來就會把事做好」是同一份對自己的要求，分不出哪個先哪個後：他遵守流程不是被逼的，而是和他主動盯進度、顧品質、收好尾的習慣長在一起，所以不必有人在後面催，產出就維持在高水位且合規。代價是這份自我要求幾乎都朝「把現有流程做到最好」使力——若流程本身有瑕疵，他極少會停下來質疑，管理者該主動留一條讓他願意指出問題的回饋通道。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4282, 'CSR_15', 'A (高)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「規則雙重守護者」。他既從外部指示方向服從，也從內在義務感堅守規範與責任邊界——兩個準則軸向高度對齊，使其在程序與承諾上極為可信賴。在規範明確的環境中是極高穩定度的資產；但若制度需要彈性或快速調整，可能因雙重規則錨定而難以靈活因應，管理上宜搭配清楚授權說明。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4283, 'CSR_15', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「服從中的高脆弱點」。他不分情境都願意照指示走，但他用來撐過困難、消化長期壓力的內在存量本來就不厚——於是會出現一種錯位：行為上他還在乖乖配合，內裡其實已經在一點一點被磨損。問題不在他「藏」什麼，而是他的配合本來就跟狀態好壞無關，所以表面穩定反而成了最不可靠的訊號。管理者得靠定期主動確認他的真實負荷，而不是把「他還在照做」讀成「他還撐得住」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4284, 'CSR_15', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「靠規則緩解焦慮的遵從者」。他對不確定與模糊情境極度敏感，面對任何未明朗的狀況都容易產生強烈焦慮；與此同時，他對指示與規定的遵從度在各種情境下都維持在高點，質疑或偏離的反應極為少見。在日常工作中，他一邊嚴格依照程序與指令執行每個步驟，一邊對任何超出規定範疇或說明不夠清晰的任務感到不安；有明確指引時他能高度配合，一旦指示模糊或例外狀況出現，焦慮情緒會明顯升高。管理上宜提前給出清楚的步驟與預期，減少模糊情境的出現，他在結構完整的環境中會有最穩定的表現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4285, 'CSR_15', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「等待指令的被動執行者」。他對指示保持高度遵從，同時本就較少自發開啟行動或超越既定要求——他的輸出幾乎完全由指令決定，沒有指令就沒有行動。在精確規格化的執行任務中他是穩定資產，但在需要自主判斷、補充細節或察覺機會的角色中，需要主管持續密集的任務驅動與指示設計。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4286, 'CSR_15', 'A (高)', 'CSR_34', 'A', '與 CSR_34 (誠懇) A聯動：表現為「透明服從不算術」。他對指示的高度配合建立在真實的服從意願之上，加上不傾向操弄或策略性包裝的誠懇，形成相當透明可信的執行風格。這份真實感使他在組織中容易被信賴，但也較少用策略性表達保護自己——管理者應確保他的服從不會在指示不合理時轉為吃虧，給予他適當的回饋與說明空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4287, 'CSR_15', 'A (高)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「深度嵌入的制度盟友」。他對指示的高度服從性，與對職場的強烈心理依戀共同形成雙重的組織錨定——遵從規範是他表達忠誠的方式，即使面對不利條件也不輕易動搖。在制度穩健的環境中是高穩定度的核心成員，但若組織方向需要調整或制度本身失靈，他較難自發提出質疑，管理者應主動設立反饋機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4288, 'CSR_15', 'B (中)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「開放變化但需要說清楚的執行者」。他對變動與不確定的環境有很高的接受度，在頻繁轉向的情境中也能將變化視為常態，不需要特別調適就能保持開放；然而在遵循指示上，他的配合取決於指令是否清楚且說明充分，若指示模糊或缺乏理由，他會先確認意圖再決定遵循程度。他能跟上快速變動的節奏，一邊接受環境的調整，一邊對具體執行步驟保持核實習慣；當變動方向清楚、指令到位，他的配合度會明顯提升，但若說明不足，他不會直接照單全收。管理上宜在每次方向調整時附帶清晰的理由，他在理解到位後能有效銜接變動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4289, 'CSR_15', 'B (中)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「等待清楚後再接手」。他在指示清楚時穩定配合，但指示模糊時傾向先確認，又較少相信自己能主動影響情況，於是這段等待確認的窗口更難由他自身填補——主動採取行動或自行判斷的意願明顯不足。B 段呈情境敏感狀態：在指示明確的場景他表現可靠，管理者若需他在模糊環境中仍保持推進，需要更密集的方向確認與賦能支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4291, 'CSR_15', 'B (中)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「理解時穩、壓力大就衝」。平常的他是個會先弄懂指示再配合的人，可他同時是情緒一上來就坐不住的人——所以他穩不穩，其實取決於壓力大小：低壓時「先確認」這個習慣站得住，連續高壓或衝突一逼近，那個還沒問清楚就先反應、先答應的自己就跑到前面去了。與其期待他在高壓下還能維持一貫的理性確認，不如在壓力事件來臨前就先跟他約好確認的步驟，把「先停一下」變成講好的流程而非臨場的自制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4292, 'CSR_15', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「確認意圖後轉嫁責任」。他在指示充分說明時才配合，執行時也確實按指示走，但若結果出現問題，傾向歸因外部而非主動補救——確認指示的行為在這個組合中可能帶有責任劃分的功能，而非純粹的執行謹慎。B 段呈情境敏感狀態：在分工明確環境中尚可管理，但在責任邊界模糊的任務中，宜預先釐清期待，避免事後的責任爭議。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4293, 'CSR_15', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「雙重確認才能動」。他在指示清楚時才配合，同時對自身是否能做好缺乏信心——他接到任務後需要同時解決「我清楚要做什麼嗎」和「我做得到嗎」兩個問題，才能真正啟動。B 段呈情境敏感狀態：在提供充分說明和確認支持的環境中他能穩定輸出，但若需要快速啟動或自主推進，他雙層的確認需求會形成明顯的節奏瓶頸。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4294, 'CSR_15', 'B (中)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「信任低時更難配合」。他本來就是理由充分才配合的人，加上他對人預設幾分戒心——這兩點疊在同一個情境裡，他的「先問清楚」會帶上不一樣的味道：在信任薄弱的上下關係裡，那不再只是想搞懂任務，而更像是在防著對方意圖不單純。於是對方解釋得越不到位，他的配合就越往保留甚至拒絕滑。B 段呈情境敏感：先把信任關係建起來，是他願意穩定配合的前提，碰上新主管或不透明的環境尤其要留意。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4295, 'CSR_15', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「主動追求但走自己路的衝刺者」。他對表現與成果有明顯企圖心，遇到挑戰傾向主動升級方法與目標，投入程度高且不需要外部催促；在對指示的配合上，他的遵從度較低，面對程序或規定時傾向質疑或挑戰，較少直接照辦。在工作中，他一邊積極推進目標、設法突破現有成果，一邊對限制行動的規定感到不耐，可能繞開程序或自行決定做法；他的衝勁是驅動力，但也讓他在需要對齊流程的情境容易產生摩擦。管理上宜把目標和空間說清楚，在結果一致的前提下給他彈性，他在有明確挑戰且自主度高的環境最有爆發力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4296, 'CSR_15', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「主動改寫規則」。他對指示配合度低，同時在高度不確定與頻繁變動的環境中仍能自然從中獲取動能——對現行程序的質疑不帶焦慮，反而把它視為需要更新的舊穩態，並主動推動改變。在需要流程革新的職能中可能是推進引擎，但在合規要求高或需要穩定執行的情境中，此組合的摩擦係數極高，需要明確的制度邊界和升級討論管道。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4297, 'CSR_15', 'C (低)', 'CSR_07', 'A', '與 CSR_07 (法規遵從) A聯動：表現為「獨立判斷不衝突化」。他對指示配合度低，但面對紛爭也傾向用順從態度因應——不正面拒絕，也不真正配合，而是用溫和的外在表現包住實質上的自行其是。這個組合的管理難度在於問題不易被早期察覺，需要透過可驗證的成果追蹤而非表面態度來評估實際的指示執行情況。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4298, 'CSR_15', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「堅信自己能掌控局面的挑戰者」。他對各類情境都持續相信自身能影響結果，主動採取行動是穩定的傾向，掌控感不因外部條件改變而下降；在遵循指示上，他的配合度偏低，面對程序和規定時傾向直接挑戰，較少選擇順從。他在處理任務時，一邊從自己的判斷出發調整步驟與節奏，一邊對他認為無效或多餘的規定提出異議；掌控感強讓他執行力十足，但也讓他在需要配合流程的情境與團隊或管理層產生張力。管理上宜直接說明為何這個程序有必要，並在可能的範圍內讓他在規定內仍有決策空間，對齊後他的行動力是資產。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4299, 'CSR_15', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「規則外的手段傾向」。他對指示配合度低，同時在強烈競爭或目標壓力下較容易把不公平手段合理化，都圍繞著「目標優先於規則」在運作，對制度合規有明確風險。管理上需要清楚的底線說明和可觀察的行為追蹤，而非僅靠信任其自我判斷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4300, 'CSR_15', 'C (低)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「衝動強化的衝突挑戰」。他對程序本來就不服氣，偏偏又是情緒一上來就壓不住的人——於是他的不滿少了一道過濾：別人可能先在心裡盤算再決定要不要講，他則往往是當下就頂出去。質疑和衝動在他這裡其實是同一個反應的快慢問題，慢不下來，所以挑戰很容易直接升級成公開對抗，事後才回頭收拾。這是合規風險和人際摩擦最容易同時引爆的組合，管理上要在壓力情境發生前就先介入，而不是等衝突爆了再處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4301, 'CSR_15', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「自發啟動卻不受框架約束的行動者」。他在各類情境中都能自發開啟行動並超越既定要求，不依賴外部指令就能持續投入，主動精神穩定且強烈；在遵循指示上，他的配合度較低，對程序和規定傾向質疑，不太容易直接照既有指令執行。在工作中，他一邊自發察覺機會並率先推動，一邊對不符合他判斷的既定做法提出挑戰，傾向走他自己認為更有效的路徑；他的主動性是推進力，但在需要對齊程序的場合，他的質疑傾向可能讓上游或旁邊的人覺得難以協作。管理上宜給他清楚的目標與足夠的發揮空間，讓他知道什麼是不可逾越的底線，他在有自主度的情境會把主動精神轉化為具體成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4302, 'CSR_15', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「當下優先遠離規範」。他對指示配合度低，且難以延遲滿足以維持長期自律——兩者都指向在即時選擇與制度要求之間選擇前者的傾向。在任何需要持續合規的情境中，這個組合都是可預測的高風險節點；管理上宜將制度要求與即時可見的正向回報連結，降低規範對他而言的「成本感」，而非僅靠督促。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4303, 'CSR_15', 'C (低)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「隨時可離的規則質疑者」。他對指示配合度低，對職場的心理依戀也偏低——質疑程序不是暫時狀態，而且若情況持續不利，離開比適應更可能是他的選擇。這個組合在合規要求高、需要長期穩定的角色中是最高風險的配置；管理者若希望維繫此類人才，需要在自主空間與意義感層面提供足夠吸引力，制度約束本身幾乎無法起到留存作用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4304, 'CSR_16', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「單向赦免的脆弱開放」。他面對冒犯後能穩定選擇放下怨恨並恢復好感，但對方預設他人意圖不利、長期保持警戒；即使他主動釋出善意，對方的保留態度讓修復動作無法形成真正的雙向互動。他的寬恕不是被拒絕，而是被忽略——對方的警戒機制讓對方根本無法確認他的善意是真實的。管理上需幫助他認識「釋懷對自己有價值，但關係修復需要對方也願意開放」，避免因單方努力耗損感到受挫。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4305, 'CSR_16', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「寬恕卻引發對抗升級」。他對衝突後的怨恨天然傾向放下並恢復好感，但對方面對紛爭時傾向直接對抗、少選擇退讓——他的和解姿態因此被對方解讀為讓步空間，而非關係修復的邀請。他越寬容，對方越難感受到需要調整的壓力；衝突模式因此傾向單方吸收。建議為這類配對設定明確的分工界線，讓和解不等同於職責退讓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4306, 'CSR_16', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「寬恕緩衝焦慮的循環」。他能在重大冒犯後仍快速選擇原諒並恢復好感，但對方對模糊與未知的忍受度極低，缺乏明確說清楚的過程會持續引發焦慮——他的寬容速度反而讓對方陷入「事情是否真的解決了」的不確定迴圈。他越不追究，對方越無從確認關係狀態；建議搭配明確的修復確認儀式，讓寬恕對雙方都能落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4307, 'CSR_16', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「寬恕保護不公正手段」。他被欺騙或被利用之後，仍把放下怨恨、恢復好感當成自己的選擇，並不認為不追究就等於認可對方；而對方習慣把領先擺第一，會替不公平的手段找理由。把這兩個人放在一起看：他這邊不會傳出任何「這樣不行」的反應，對方那邊也就讀不到調整的必要——同一套佔便宜的做法既沒有被他擋下，也沒有換來任何代價，於是自然而然地一再重演。這是寬恕特質風險最高的配對之一：他越是穩定地放下，對方越能安心維持原樣。管理上不能靠他個人追不追究來把關，要設定制度性的邊界（如留下紀錄、用明確的績效與行為指標），讓公平與否不取決於他的情緒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4308, 'CSR_16', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「誠意不對稱的修復」。他願意放下被欺騙的怨恨並恢復對對方的好感，但對方習慣以話術與選擇性揭露達成目標；他的寬恕被對方接收後，對方調整的是說法包裝，而非操弄傾向本身。他主觀上以為關係已恢復誠實基礎，實際上對方的行為邏輯未改變。建議在他寬恕後引入行為觀察窗口——以對方後續行為模式作為修復是否真實的判斷依據，而非依賴他自身的感受。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4309, 'CSR_16', 'A (高)', 'CSR_17', 'A', '與 CSR_17 (溫和有禮) A聯動：表現為「柔性共振的和解促進者」。他放下怨恨的穩定傾向與對方在各類互動中都維持溫和寬容的方式高度共振——衝突幾乎不會演變成長期緊張，兩人都自然傾向讓不滿消散。這種配對在需要心理安全與協作信任的場合是資產；但當有重要問題需要被指出、被追究時，雙方都傾向柔化，議題容易因「太早釋懷」而無從處理。適合搭配明確的問題回顧機制以彌補這一盲點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4310, 'CSR_16', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「衝動傷害後總被輕放」。他對冒犯的釋懷十分穩定，幾乎不會記在心上；對方則容易被當下情緒推著走，做出衝動的回應甚至行為過頭，事後常需要回頭收拾。把兩個人擺在一起：對方每一次衝動造成的傷害，到了他這裡都很快被原諒、關係很快回到原點，於是對方幾乎不必為衝動付出什麼，調整自己的動力也就一直起不來。這組配對長期的隱憂在於，衝動的成本始終沒有真正落到對方身上。管理上需要引入明確的回饋，讓衝動行為帶來的後果不全部由他一個人默默承接。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4311, 'CSR_16', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「責任自承與寬厚釋放」。他面對冒犯後的穩定釋懷與對方在失誤後主動承擔、追根究柢的傾向形成高度互補——對方負責消除根因，他負責消除怨恨，雙重機制讓修復既快速又有實質內涵。這是寬恕特質少數能避免「原諒而不改善」陷阱的配對；衝突後的關係品質通常優於衝突前。適合作為高信任團隊的核心組合，遇到誤差能快速自我修正。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4312, 'CSR_16', 'A (高)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「私下釋懷擋不住規則鬆動」。他能在對方踩灰色地帶、甚至沒守住承諾之後，仍選擇放下、恢復好感；而對方本就把規範當成可調整的工具，目標壓力一來就先看結果。問題在於這兩件事不在同一個層次：他的寬容是個人之間的釋懷，本來就替代不了一條規則該有的約束力。對方每一次彈性取捨都換來他的不追究，久而久之，會把『反正他不會怪我』當成可以操作的空間。管理上要把他個人願不願意釋懷，和制度層面該不該問責這兩件事分開，別讓私下的寬厚被誤當成規則已經默許。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4313, 'CSR_16', 'B (中)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「善意背景讓他更傾向原諒」。他在一般冒犯後能較快放下，遇到嚴重傷害則需要更久；而對方無論過去經歷如何，都預設別人懷著善意、很少因為風險收回信任。當他正卡在『對方到底是不是故意的』這個猶豫上時，對方一貫把人往好處想的態度，給了他一個很實在的參照——既然連對方都不覺得這是惡意，他也更傾向把這次冒犯理解成可以原諒的範圍。這組合在日常的工作誤差裡修復得很順；但要留意的是，當兩人都偏向往善意解讀時，真正嚴重、需要認真處理的衝突，也可能被一起看輕了。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4314, 'CSR_16', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「傷害累積耗損寬容資源」。他的寬容本身視情境而定，嚴重傷害需要更長修復時間；對方在壓力逆境中內在緩衝資源有限，容易受負面影響並在行為上出現退化。他與對方的情境敏感性在同一段高壓時期同時觸發：對方在壓力下更可能造成摩擦或失誤，而他在自身也疲憊的情況下，寬容的條件更難達成——於是形成「傷害增加、寬容門檻也升高」的雙向惡化。管理建議：在高壓期主動降低任務密度，為雙方預留恢復空間，避免逆境期摩擦累積成難以修復的裂痕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4315, 'CSR_16', 'B (中)', 'CSR_07', 'A', '與 CSR_07 (法規遵從) A聯動：表現為「溫和化解創造修復條件」。他對一般冒犯能較快釋懷，嚴重背叛才需要更長時間；而對方面對任何衝突幾乎都以順從、合作的方式因應，極少擺出對抗姿態。對方這份溫和讓衝突本身就燒不起來，他遇到摩擦時，更容易把它看成『可以處理的誤差』而不是深層的背叛——他視情況而定的寬容，於是更多落在釋懷這一邊。這組合在日常合作的小摩擦裡修復得很有效率；但兩人都不愛把話挑明的傾向，也可能讓真正該被正面處理的問題一直懸著。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4316, 'CSR_16', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「悲觀預期延緩修復」。他在嚴重或反覆傷害後需要更長時間恢復信任；對方傾向把不如意視為長期且普遍，遇到關係裂痕容易預期無法改善。兩者的情境敏感性方向相同——一個需要時間評估是否釋懷，另一個傾向預設修復困難——共同形成修復進程缺乏動能的局面：不快速原諒，也不快速決定放棄，而是長時間懸置在不確定狀態。管理建議：主動為這類配對安排具體的修復確認節點，避免雙方因惰性而讓裂痕無聲固化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4317, 'CSR_16', 'B (中)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「同理讀懂寬容的條件」。他的寬容視情況而定，一般冒犯後能較快放下；而對方對別人的處境與難處有著不因消耗而減退的關懷，在各種互動裡都穩定流露。對方這份深切的關懷，讓他在衡量要不要釋懷時多了一層真實的理解——『換成那個處境，對方會這麼做是說得通的』——他因此更容易把冒犯看成情境壓力下的結果，而不是針對自己的惡意。這組合在需要跨過誤會、重新建立信任的場合特別有優勢；管理上要留意的，是別讓『都有苦衷』成了反覆傷害也不必面對的理由。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4318, 'CSR_16', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「修復資源不足的緩慢釋懷者」。他的寬容視情況而定，嚴重傷害後需要更長時間確認是否恢復信任；在長期壓力或連續變動下他容易能量耗竭，補救行動較吃力。他在高壓情境下既需要時間確認對方的修復誠意才能啟動釋懷，自身又處於耗竭狀態、缺乏資源做出有品質的回應，因而停滯在修復門檻之前。管理建議：在逆境期優先恢復他的基本運作能量，再期待修復動作，否則善意容易因資源不足而無法落地。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4319, 'CSR_16', 'C (低)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「善意投入記恨防火牆」。他在被冒犯後長時間持有不滿、恢復信任的過程漫長；但對方對他人預設善意的傾向極為穩定，即使面對不確定處境也幾乎不收回信任。對方持續展現的開放姿態對他而言有時反而成為阻力——對方的快速信任讓他感受到自己的傷害「被輕描淡寫」，反而強化了記恨的合理性。建議對方理解他需要明確的修復確認而非單純的善意投放，信任不等同於釋懷，兩者的節奏需要顯性對齊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4320, 'CSR_16', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「冒犯後的對抗僵局」。他對冒犯或過錯難以釋懷、持有不滿的時間漫長；對方面對紛爭傾向直接表達立場、容易出現爭辯與對抗性反應。衝突發生後兩者都無自然的緩解傾向——他不主動釋懷，對方不主動退讓——形成雙向持續的緊張與沉默對峙。這類配對在缺乏外部調解機制的環境下容易讓小衝突固化成長期緊張。管理建議：為這一配對設立明確的衝突處理程序，確保不依賴雙方自行恢復。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4321, 'CSR_16', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱情遇上長久芥蒂」。他對冒犯難以釋懷、記恨的時間很長；而對方在各類人際互動中都自然流露信任與熱情，連面對不確定也不例外。對方的熱情讓兩人在日常往來上看起來順暢，但他心底那股不滿並沒有因此消解——當對方一如往常地熱絡，他接收到的反而可能是『連事情有多嚴重都沒察覺』，這讓他更覺得自己受的傷沒被當回事。表面流暢、底下卻有裂痕，是這組配對最典型的樣子；偏偏雙方都不會主動把它攤開：對方忙著維持熱絡，他則把不滿收在心裡。管理上要先認出這種『表面正常、深層裂痕』的模式，主動替他開出一個能安全說出不滿的空間，而不是指望日常的熱情自己把問題化解掉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4322, 'CSR_16', 'C (低)', 'CSR_17', 'C', '與 CSR_17 (溫和有禮) C聯動：表現為「嚴厲批判鞏固長期不滿」。他對冒犯難以釋懷、長時間持有不滿；對方在互動中傾向直接嚴厲、容易做出批評性判斷。兩者的低寬容傾向在冒犯後相疊：對方的持續嚴厲為他的記恨提供不斷更新的材料，讓他難以找到「對方已不再是傷害來源」的判斷依據。這種配對在衝突後容易形成自我強化的負向循環——對方不自覺地維持了他不滿的合理性。建議主動引入正向互動節點，並為對方的回饋方式提供結構引導，避免嚴厲語氣成為唯一的溝通頻道。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4323, 'CSR_16', 'C (低)', 'CSR_03', 'A', '與 CSR_03 (利他行為) A聯動：表現為「付出換不回好感的落差」。他對冒犯難以釋懷，恢復好感需要漫長時間；對方面對高度犧牲也不減損付出意願，無私體貼是穩定的反應模式。即使對方持續的無私行為讓他在理性上知道「對方是真心的」，他的記恨仍讓好感的恢復速度遠慢於對方的付出速度——對方感受到的是持續給予卻無法獲得應有回應的疲憊。管理建議：辨識這一落差模式，不依賴對方持續付出來換取他的釋懷；而是主動處理他長期記恨的根因，讓兩者的互動恢復對等動態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4324, 'CSR_16', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「不確定焦慮遇上長期記恨」。他對冒犯後長時間持有不滿，關係好壞長期懸而未決；對方對任何不確定性都容易產生強烈的持續焦慮，忍受度在各類情境中都極低。他的記恨讓關係狀態長時間不清楚，直接成為對方焦慮的持續觸發源——對方反覆確認「我們還好嗎」，他無法給出正向確認，對方的焦慮進一步升高。這是高互相耗損的配對。管理建議：主動設立時間節點，讓他明確表達目前關係狀態，降低對方在不確定中持續消耗的成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4325, 'CSR_16', 'C (低)', 'CSR_06', 'A', '與 CSR_06 (承諾) A聯動：表現為「承諾深投遇上信任寒冬」。他在被冒犯後長時間持有不滿，恢復信任需要漫長過程；對方對自身所在環境的承諾不受逆境影響，各類條件下都能維持全心融入。對方的強烈歸屬感讓他繼續全心投入這段合作，但他的長期記恨讓信任基礎缺位——對方的承諾找不到對等的接收方，所有投入都在沒有被充分接收的狀態下持續流出。管理建議：識別承諾強但信任已斷裂的配對，避免讓高承諾一方在沒有回饋的狀態下持續單方耗損，主動為信任修復建立明確機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4326, 'CSR_16', 'C (低)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「雙向資源匱乏難以修復」。他對冒犯長時間持有不滿，恢復信任的過程漫長；對方心理資本不足，容易感到無力或悲觀，面對挫折動能下降明顯。衝突後的修復需要至少一方主動發起——他不傾向主動釋懷，對方沒有足夠的正向資源發起修補——兩者共同讓關係停留在裂痕固化的狀態。這是修復最困難的配對之一，需要外部結構性介入。管理建議：不依賴雙方自發修復，應主動安排有引導的對話節點，並為對方補充必要的支持資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4327, 'CSR_16', 'C (低)', 'CSR_19', 'A', '與 CSR_19 (誠實謙遜) A聯動：表現為「誠正承擔等待記恨解凍」。他對冒犯後長時間持有不滿，恢復好感的情感歷程漫長；對方在利益壓力下仍能維持誠懇與公正，不合理化特權或佔便宜行為。對方的誠正態度在冒犯後提供了「值得被寬恕」的客觀信號，但他的記恨讓情感上的釋懷速度遠落後於理性認知——他可能在理智上認可「對方確實誠懇」，但情感上仍維持距離與不滿。管理建議：辨識這種理性與情感修復的時差，為他提供結構化的情感表達空間，讓感受被看見後才有條件真正釋懷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4328, 'CSR_17', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「溫和外殼下的強硬信號」。他在各類互動中都能保持溫和有禮，面對高度摩擦也不例外；但當衝突升級時，其實有明確表達立場甚至對抗的傾向在運作——只是被溫和的語氣包裝住了。結果是一種「語氣柔、立場硬」的溝通型態：不爭辯但也不迎合，對方往往要到事後才發現這個人其實沒有讓步。管理上需留意這種組合容易被誤讀為同意，應鼓勵更明確地聲明立場而非讓善意語氣掩蓋真實意向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4329, 'CSR_17', 'A (高)', 'CSR_02', 'C', '與 CSR_02 (親和性) C聯動：表現為「溫暖外表的單向付出」。他在任何情境下都不輕易對人嚴厲或批評，讓人感受到一貫的善意與禮貌；但這份溫和並不來自於對人際的開放與信任，互動中他其實傾向保持一定的戒備與距離。外人看到的是一個讓人如沐春風的人，卻可能在深度合作中發現他並不容易真正靠近。建議留意此組合在需要高信任協作的情境中，表面溫和可能遮掩實際的人際疏離。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4330, 'CSR_17', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「溫言話術者」。他在各類互動中始終維持溫和有禮的態度，即使對方反覆出錯也不容易看見他的批評或對抗性反應；但在同一場溝通裡，他習慣把要說的話仔細包裝，選擇性地釋放對自己有利的資訊，用話術讓對方往特定方向判斷。旁人感受到的是他的柔和與有禮，卻難以從外表看出他在過濾和操弄哪些訊息。實務上他的溫和讓衝突不容易浮上檯面，但資訊的真實度可能打折；在需要透明溝通的情境，宜要求他明確交代底層假設與完整資訊，而不只是態度的友善。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4331, 'CSR_17', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「柔和外表下的手段者」。他在各類互動中都展現溫和有禮的態度，面對高度摩擦也不容易出現批評或對抗性回應，給人可親的第一印象。在同樣這些情境裡，當涉及領先或利益時，他較容易把不公平手段或利用他人的做法合理化為情況所需，且全程以溫和的態度呈現，讓旁人難以即時察覺手段的存在。具體處境裡，他在對話中不直接衝突，但在行動選擇上可能繞過公平規則以換取優勢。管理上宜透過透明的流程與規則邊界做事前約束，而不只依賴互動品質來評估他的行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4332, 'CSR_17', 'A (高)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「客氣而重利的互動者」。他對人客氣、不輕易批評苛責，這份溫和是真實的；同時，他對利益、地位這類實質回報相當在意，容易把『先拿到再說』合理化，對謙遜與公平的自我約束偏弱。在他自己看來，待人好和爭取自己想要的並不衝突——他不是用笑臉去掩護算計，而是這個人本來就既愛和氣、又務實地把回報放在心上，於是即使在替自己爭取時，他也用一貫溫和的方式進行，不顯得咄咄逼人。結果是一個讓人相處愉快、卻在利益面前相當實際的人。建議在涉及獎酬分配或利益衝突的情境，以結果與事實而非相處印象作為評估基準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4333, 'CSR_17', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「溫和底線下的衝動暗流」。他在各類互動中維持一貫的溫和態度，很少讓人看到嚴厲或批評的一面；但當情緒被觸發時，他實際上較容易衝動行事或做出倉促承諾，而事後的修補也是以溫和語氣帶過，不容易被外界發現真正的代價。結果是風險被低估：周遭人因為他的溫和形象而不容易預期或正視其衝動決策的後果。建議為他建立明確的冷靜機制，特別在涉及承諾或資源投入的情境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4334, 'CSR_17', 'A (高)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「溫厚而規範彈性的行動者」。他在各類情境中都能保持溫和有禮，面對對方犯錯或反覆出問題也幾乎不做批評性回應，互動中呈現的是寬厚的態度。在同樣的工作脈絡裡，他對規範與承諾的遵守程度相對彈性，遇到目標壓力時會優先選擇能推進結果的做法，而把規則視為可協商的參考框架。他的溫和讓他不會對規範破口提出強烈反對，對自己偏離規範也不會嚴厲問責自己。管理上宜把關鍵規範的底線明確說出來，並搭配清楚的驗收節點，而不只依賴他的自發遵守。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4335, 'CSR_17', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「不確定性下的焦慮溫和者」。他在外部互動中始終溫和有禮，再大的摩擦也少見他批評或催促；但只要情境一有模糊、未定，哪怕程度很輕，他內心都會升起相當強烈的不安。關鍵在於：對立、尖銳本來就不在他的反應方式裡，所以這份焦慮極少以煩躁或對人施壓的形式冒出來——它更可能化為反覆向人確認、或悄悄迴避那些講不清楚的情境。於是周遭看到的還是那個溫和的人，不容易察覺他其實正承受著不小的不確定性張力。建議在資訊不完整或進度未明時，主動為他設置確認節點，而不要等他開口，因為他的溫和習慣讓他更難主動催促或表露不安。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4336, 'CSR_17', 'A (高)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「溫和面對失誤的外歸因者」。他在各類互動中維持溫和有禮的態度，即使面對高度摩擦或對方反覆犯錯也鮮少做出嚴厲或批評性的回應。遇到失誤或延誤時，他的態度同樣保持平和，不激烈指責自己或他人；但他也較少主動把問題的成因歸到自己身上，傾向找到情境、資源不足或外部因素的解釋，補救行動相對被動。具體情境裡，他在問題發生後不會製造衝突，但可能也不主動承擔、跟進或追根究柢。管理上宜在問題發生後主動釐清各方責任份量，並明確要求他負責的具體補救步驟，才能促進行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4337, 'CSR_17', 'B (中)', 'CSR_07', 'A', '與 CSR_07 (法規遵從) A聯動：表現為「溫和禮讓的自然對齊」。他在多數互動中展現溫和與禮貌，遇到問題反覆出現時會嘗試在寬容與直接表達間調整；但在任何衝突中他都傾向順從，於是在情境壓力下幾乎找不到直接表達立場的空間，整個人往溫和退讓的方向走。建議為他設立明確的「需要直接說明」的情境訊號，幫助他在衝突中辨識何時溫和退讓反而放大問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4338, 'CSR_17', 'B (中)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「情境中的溫暖連結者」。他在多數互動中展現溫和禮貌，再加上在各類情境都能自然展現信任與熱情的人際傾向，日常中顯示出真誠的溫暖與合作性。問題是，當衝突或反覆問題出現時，溫和習慣與親和傾向都在推著他維持關係，使他要切換到直接表達的門檻相當高。建議幫他建立清楚的觸發點，讓他能辨識何時溫和維持關係反而是在縱容問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4339, 'CSR_17', 'B (中)', 'CSR_19', 'A', '與 CSR_19 (誠實謙遜) A聯動：表現為「真誠溫和的誠正風格」。他在多數互動中展現溫和禮貌，加上在利益可見情境下仍能維持誠懇與公正、不過度執著於佔便宜，讓他的溫和有實質的誠信支撐——對人好不是表演，意圖也相對透明。當問題反覆時，他偶爾切換為直接表達，也不容易被解讀為報復或攻擊。這是一種信任成本較低的互動組合，適合需要高透明度的協作環境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4340, 'CSR_17', 'B (中)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「情境調節的穩定表達者」。他在多數互動中展現溫和，在反覆問題或對方態度不佳時能切換為較直接的表達；加上管理情緒衝動的能力在壓力下仍穩定，他的這種切換不容易演變為失控或傷人。這是一個能有效管理自身溝通邊界的組合——溫和時真誠，直接時可控。建議在他切換為直接表達後，提供明確的情境確認，以強化這份有效切換的學習。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4341, 'CSR_17', 'B (中)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「禮貌卻難以靠近的互動者」。他通常展現溫和禮貌，但對他人的信任度本就偏低、傾向預設對方意圖不利，讓這份禮貌帶有明顯的距離感——態度客氣，但不太開放。當對方態度不佳或問題反覆時，他可能在切換為直接表達和選擇直接退出之間猶豫，而不一定選擇溝通解決。建議在需要深度合作的情境，預留較長的信任建立期，並避免以語氣上的溫和誤判為心理上的靠近。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4342, 'CSR_17', 'B (中)', 'CSR_13', 'C', '與 CSR_13 (同理關懷) C聯動：表現為「溫和語氣中的情感距離」。他在多數互動中展現溫和與禮貌；但對他人困境的情感反應偏平淡，傾向理性看待而非情感投入。他的溫和更多是風格上的禮貌，而非情感上的關懷——別人可能感受到他的客氣，卻未必感受到被真正理解。在需要在寬容與直接間切換時，缺乏同理暖度的直接表達也可能讓對方更難接受。建議在情緒性議題出現時，補足明確的關懷確認語言。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4343, 'CSR_17', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「強硬批評的對立主導者」。他評價他人時傾向直接且嚴厲，在紛爭中也傾向直接對抗、少退讓，於衝突情境中既批評不留情，又不迴避正面交鋒。在標準明確的情境中他能帶來清晰的問責，但在需要協調與妥協的情境，可能快速激化對立。建議為他設置明確的升溫門檻，提示何時直接對抗已超過必要，並鼓勵在堅持立場的同時保留解決空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4344, 'CSR_17', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「批評夾帶的溫暖矛盾體」。他在各類人際互動中都能自然展現信任與熱情，讓人感受到真誠的親近；但他同時在評價他人時傾向直接且嚴厲，讓批評頻繁出現在已建立的親密關係中。對接受他的人而言，這是一種「很在乎卻很難相處」的體驗——關係可能因為批評反覆而受傷，即使動機是善意的。建議他在給出批評時，明確區分評估行為與評斷人格，以減少熱情善意被嚴厲語氣抵消的情形。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4345, 'CSR_17', 'C (低)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「犀利批評下的深層關懷」。他對他人困境有真實而持久的同情與關懷，不因情感消耗而退縮；但對他人行為的評價傾向直接且嚴厲，讓他的關懷常以批評的形式呈現——他在乎你，所以更直接說問題在哪。這種組合對心理承受力強的對象有激勵效果，但對需要先被接納再接受回饋的人，可能因為批評遮蓋了關懷，使互動效果打折。建議他在給出批評性評估前，先明確傳達關懷基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4346, 'CSR_17', 'C (低)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「批評記恨的雙向累積者」。他評價他人傾向直接嚴厲，且面對冒犯或過錯難以釋懷、恢復信任漫長。他的批評不只是單次的直接評估，而是帶著過去累積的負向記憶，呈現批評越來越重的樣貌。對方可能發現同樣的問題，被批評的力道卻越來越強，甚至感覺被追溯舊帳。建議設立明確的「評估聚焦當下」的回饋規範，並提醒他記錄過錯與當下批評之間應有明確邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4347, 'CSR_17', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「高標準下的嚴格督導者」。他對表現有明顯企圖心，願意主動投入以達更高標準；加上評價他人傾向直接嚴厲，讓他不只嚴格要求自己，也對他人缺乏積極性或表現不足有強烈批評傾向。這種組合在高表現環境中能帶動標準，但對動能本就不強的人可能產生壓迫感，進一步抑制其投入意願。建議他在批評表現的同時，明確說明具體可做的改善路徑，而非停在對不足的指責。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4348, 'CSR_17', 'C (低)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「嚴厲評斷的高警戒者」。他對他人信任度偏低，傾向預設意圖不利，且在互動中保持警戒；加上評價他人傾向直接嚴厲，讓他對新接觸的對象更容易早早做出批評性判斷——尚未建立信任，批評已先到來。這種組合會顯著增加合作的摩擦成本，對方需要在批評和不信任的雙重壓力下建立關係，難度很高。建議在初期合作中明確聚焦行為事實，避免在信任尚薄弱時過早做出人格層面的批評。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4349, 'CSR_17', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮驅動的批評反應」。他對不確定性的容忍度極低，各類模糊情境都容易引發強烈焦慮；加上評價他人傾向直接嚴厲，讓批評在不確定情境中成為他試圖恢復掌控感的一種行為出口。問題是這種批評可能與當下問題的實際嚴重程度不相稱，讓他人感到被過度苛責。建議在高度不確定的情境中，提前為他提供資訊更新節點，以減少焦慮轉化為批評的觸發頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4350, 'CSR_17', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「自律高標的嚴格評判者」。他做事有一致的自我要求，在成就追求、審慎、盡職、條理等各方面都保持高標準；他評價他人時又直接嚴厲，於是他在與他人協作時，容易以自身的高盡責標準作為評判基準，差距即成批評。這類組合在品質要求高的環境中能有效帶動水準，但可能低估他人能力的情境差異，並讓批評密度超過對方的接受閾值。建議他在批評前先確認對方是否有相同的資源與條件，避免以自身盡責水準作為對所有人的預設期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4351, 'CSR_18', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「撐得住卻回不了速的硬撐者」。他在壓力與困境中能維持充沛的內在資源，不被擊垮，承受力相當穩定；壓力過去之後，恢復的節奏卻明顯拖沓，疲勞會累積而非清空，難以把打擊轉化為修正動能。具體情境裡，他能在逆境高峰獨力撐場，展現的是堅守而非崩潰；待情況穩定後，後段的補救與重整卻常常流於被動，容易停在「已過去」而非「已改善」。長期下來，他的抵禦力讓他在危機期間成為可靠支柱，但反覆的消耗卻因恢復不足而悄悄積累，管理上宜在逆境結束後主動為他創造修復節奏，而非等待他自行追上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4352, 'CSR_18', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「撐得住但預期不了好結果的堅守者」。他有充沛的內在資源來緩衝逆境，面對持續壓力仍能維持在場，不輕易退出；對挫折與不順的解釋卻傾向長期且普遍，不容易從「暫時」的角度重燃動能。在具體情境裡，他能穩住危機期間的陣腳，拒絕被壓力拉走；同時對下一步的期待偏向悲觀，需要外部的進展訊號才能保持行動意願。實務上他展現的是持久型的穩定，但因為難以從前景中獲取動力，長期任務尤其需要有人定期提供可見的進展回饋，讓他的堅守有更清楚的落腳點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4353, 'CSR_18', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「有韌性卻被不確定性持續磨耗的堅持者」。他具備充沛的堅毅資源，任何強度的逆境都能維持在場；面對模糊與未知情境，他同樣難以容忍，持續產生強烈的焦慮與不安。在具體情境裡，他一邊扛住壓力、不讓自己垮掉，一邊被缺乏明確資訊的狀態高度緊繃。實務上他是危機中的可靠支柱，但在長期不確定的環境下會比一般逆境更快見底，管理上宜盡早提供決策框架與階段性訊號，讓他的韌性能用在對的地方而非不斷消耗在等待不確定的解除上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4354, 'CSR_18', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「扛得住的穩定達標者」。這個人韌性很足，壓力再大、逆境再久內在資源都撐得住，不會因打擊而崩;但他對成果的企圖心是平的，把工作完成在合理範圍就滿足，不特別想升級標準或多投入突破。兩者擺在一起，是一個在風浪裡很可靠、卻不會自己往上加碼的人：他能守住陣地、穩定交付，但要他主動拔高難度則動能不強。管理上適合把他放在需要持久承受、穩定產出的位置，若期待他追更高標準，得靠清楚的要求與外部驅動，而非預設他會自發進取。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4355, 'CSR_18', 'A (高)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「撐得下去卻不確定能否完成的困境者」。他在各類壓力處境中都能維持充沛的內在資源，不論逆境多長都不輕易離場；對自己是否有能力完成目標，卻缺乏明確的信心，面對挑戰容易出現遲疑和過度求證。在具體情境裡，他能在壓力下堅守、繼續執行，不被擊退；遇到需要拍板或扛下更高標準任務的時刻，他會先反覆確認而非直接承擔，讓堅毅帶來的穩定沒能充分轉化為行動效率。實務上他是逆境中的穩定存在，但需要搭配清楚的分工與明確的標準，才能讓他從撐著轉變為真正推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4356, 'CSR_18', 'A (高)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「有耐受力卻對自身缺乏信心的堅守者」。他能在任何強度的壓力下維持充沛的內在資源，不因逆境而潰散；對自身能力與掌控感的信心，卻相當薄弱，遇到不確定任務就容易懷疑、等待或依賴他人定方向。在具體情境裡，他一邊撐住局面不讓場子垮掉，一邊在需要主動扛責或做判斷時猶豫，行動節奏比應有的慢上一截。實務上他在危機與壓力中是穩定的在場者，但承接複雜任務需要搭配清楚的角色授權與進度確認，才能讓他的耐受力真正化成輸出動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4357, 'CSR_18', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「韌性足夠卻被模糊感持續拉扯的撐場者」。他有適度的韌性資源可以因應一般困境，但如果壓力持續或多重壓力同時到來，承受力會出現明顯下滑；而他對不確定情境的焦慮反應強烈，任何模糊與未知都能持續觸發負面緊繃。在具體情境裡，他能在已知的逆境下撐住節奏，不讓自己垮掉；遭遇方向未定或資訊殘缺的情境時，他一邊繼續運作，一邊被焦慮大量消耗，讓原本的韌性比正常更快見底。實務上他需要足夠清楚的進展訊號和決策框架，避免模糊情境把他的韌性儲備拉到臨界前就開始侵蝕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4358, 'CSR_18', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「壓力下勉強在場卻難以重整的消耗者」。他面對一般困難時能動用內在資源因應，但逆境強度持續升高時，他的韌性會明顯下降；事態平息後，他的恢復速度又偏慢，補救與重整的能量相對有限。在具體情境裡，他一邊撐住不讓自己在危機高峰就棄陣，一邊在壓力消退後難以把經歷的挫折轉化為修正行動，兩段狀態他都在消耗而非蓄積。實務上他需要明確的支撐結構——在壓力期有人協助分流，在恢復期有主動的復原節奏安排——才能避免消耗不斷累積而最終失去維持的能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4359, 'CSR_18', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「撐過去卻不追根的過關者」。他在困難與壓力下能運用適度的內在資源維持在場，不因逆境輕易垮掉；遇到失誤或結果不如預期時，卻傾向把原因歸向外部，補救動作相對被動，改進循環難以啟動。在具體情境裡，他一邊在壓力期間穩住自己不退場，一邊在逆境過後等待外部推動才去處理根源問題，而不是主動承擔並追改善。實務上他展現的韌性讓他在困境期間維持可用，但長期的進步需要管理者主動介入歸因對話，把「過關」轉化為真正的學習與改善動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4360, 'CSR_18', 'B (中)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「勉強維持的有限韌性者」。他面對一般性困難時能運用內在資源因應，但逆境持續升高時他的韌性會出現明顯下降；他的希望感、效能感與樂觀傾向本就薄弱，於是他整體心理資本的儲備不足以支撐長期壓力。在具體情境裡，他一邊在困境初期繼續撐場，一邊因為正向資源不足而難以從前景中汲取動力，於是他的可工作期比預期短。實務上他需要定期的正向回饋與明確的進展確認，在韌性見底之前讓他的心理資本有機會補充，否則長期逆境會讓他的在場快速轉為耗盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4371, 'CSR_19', 'B (中)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「原則彈性遇規範彈性者」。他多數時候能維持公平與誠實，但在強壓或利益衝突下，原則邊界容易鬆動；他對規範的態度也偏彈性，遇到目標壓力傾向把規則視為可調整的工具而非固定底線。在具體情境裡，他常一邊在低壓下表現出合理的遵守與誠正，一邊在高壓情境同時讓原則和規範都出現縫隙，行為預期度因此偏低。對管理者而言，清楚的底線說明和結構性監督比單純靠他的自我要求更可靠；宜讓他在壓力出現前就確認哪些是不能動的，減少他自行詮釋的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4361, 'CSR_18', 'C (低)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「容易受損又難以重燃動力的脆弱持續者」。他面對困難或壓力事件時較容易受到負面衝擊，內在用來緩衝逆境的資源有限；他對不如意的解釋傾向長期且普遍，很難從「暫時」的角度找回行動動力。在具體情境裡，他一邊在壓力下感受到明顯耗損、難以維持穩定輸出，一邊把挫折解讀為持續性的困境而非可以改變的狀態，於是他恢復更加困難。實務上他在逆境期和恢復期都需要外部結構的支撐——清楚的短期目標讓他有抓手、可見的小進展讓他不預設悲觀，避免他在兩個方向上的脆弱同時拖累他陷入長期低動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4362, 'CSR_18', 'C (低)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「資源匱乏下的低韌性者」。他面對困難與壓力事件時較容易受到負面影響，緩衝逆境的內在資源本就有限；希望感、效能感與樂觀傾向的整體儲備也偏低，讓他在困境中難以從這些正向資源獲取補充。在具體情境裡，他一邊在壓力下感受到明顯的能量損耗，一邊因為缺少對前景的期待與路徑感，在逆境結束後也難以主動恢復動能，需要外部較多的支撐才能重回工作狀態。實務上管理上宜提供高頻的進展確認與具體的下一步指引，讓他在低韌性、低心理資本的狀態下仍有結構可依附，而非等他自行找回動力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4363, 'CSR_18', 'C (低)', 'CSR_20', 'C', '與 CSR_20 (希望) C聯動：表現為「既脆弱又找不到出路的困頓者」。他面對困難時內在緩衝資源有限，較容易受到壓力事件的負面衝擊；對目標的策略化路徑感也不足，遭遇阻礙時難以找出替代方案，容易停滯或放棄方向。在具體情境裡，他一邊在逆境中感受到明顯的耗損與不穩定，一邊無法靠清楚的前進路徑提振自己，讓困境期比一般情況拉得更長。實務上他需要非常具體的任務拆解與階段性回饋——讓路徑可見、讓下一步清楚——才能在韌性不足又缺乏方向感的雙重條件下維持基本的行動力，避免他在低韌性與缺乏方向時愈陷愈深、停滯不前。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4364, 'CSR_18', 'C (低)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「既撐不住又不願久留的易出走者」。他面對困難與壓力事件時較容易受到負面衝擊，緩衝資源不足；對所處環境的心理依戀與承諾程度也低，遇到逆境和不利條件時傾向考慮離開而非堅守。在具體情境裡，他一邊在壓力下耗損明顯、難以維持穩定，一邊在環境條件惡化時很快出現退出傾向，讓留守的門檻比一般人低。實務上他在逆境期需要明確且具體的支持——看得見的改善訊號和清楚的歸屬感——才能讓他在韌性與忠誠度都偏低的條件下仍有動機繼續承擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4365, 'CSR_18', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「高自律標準下難以因應逆境的超載者」。他做事有一致的自我要求，能主動掌握進度與品質，不需催促也能維持可靠輸出；面對困難與壓力事件時，內在用來緩衝逆境的資源卻相當有限，較容易受到負面衝擊。在具體情境裡，他一邊用高自律的標準驅動自己繼續維持品質，一邊因為抗壓資源不足而在逆境中消耗得比一般人快，高標準和韌性不足的差距在壓力升高時會讓他陷入難以喘息的超載狀態。實務上他的可靠性在穩定環境下是真實的優勢，逆境期需要主動降負、縮小即時要求範圍，讓他的盡責性在合理壓力水位內發揮，而非在脆弱狀態下繼續用高標準壓垮自己。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4366, 'CSR_19', 'A (高)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「對標準幾乎沒有例外的人」。在這個人身上，誠懇公正與對承諾、規則、責任邊界的高度重視，其實是同一種信念的兩種說法——他不是『既誠正、又守規矩』兩件事相加，而是打從心裡認為『什麼能做、什麼不能做，在標準面前不該有例外』，而誠正只是這個信念最核心的一條。遇到灰色地帶，他會自動選最可被交代、最站得住的做法，幾乎沒有給自己留通融的餘地。實務上他在需要高倫理標準的崗位是極可靠的資產；但同一份堅定，在真正需要彈性折衷、在規範邊緣快速權衡的情境，可能讓他顯得過於剛硬、難以推動協商。建議這類場合事先把授權邊界與可動空間講清楚，而不是期待他在現場自行解讀彈性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4367, 'CSR_19', 'A (高)', 'CSR_33', 'A', '與 CSR_33 (自律性) A聯動：表現為「自制守正的長期耕耘者」。他能為長期目標延遲滿足，面對短期誘惑維持自我約束；在利益與目標可見的情境下，他仍傾向誠懇與公正，對財富、地位與特權的執著較弱。具體情境裡，他常一邊按節奏穩定推進、不隨波逐流，一邊在資源分配或功績評定上不去搶或誇大，行為上給人直率可信的印象。對周遭而言，他是自律與誠正都到位的穩定型；管理上適合授予有邊界的自主空間，清楚的長期目標比短期激勵更能持續驅動他。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4368, 'CSR_19', 'A (高)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「誠正溫厚的信任建立者」。他在各類人際情境中自然展現信任與熱情，合作與助人成為穩定的反應模式；在利益與目標可見時，他仍能維持誠懇與公正，對財富、地位與特權的執著不強，也較少炫耀或佔便宜。具體情境裡，他常一邊主動與人建立良好合作關係，一邊在資源與功勞分配上保持直接透明、不搶不誇的風格，讓周遭對他的信任度穩定累積。對團隊而言，他是凝聚氣氛與維持誠信底色的重要成員；管理上給他可以展現助人與誠正的情境，他的穩定輸出和人際信任都能持續發揮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4369, 'CSR_19', 'A (高)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「誠正但責任易外移者」。他在利益可見時能維持誠懇與公正，不傾向炫耀或佔便宜；但遇到失誤或延誤，他的歸因傾向朝外，補救動作較被動，改進速度也因此偏慢。具體情境裡，他一邊給人直率不滑頭的印象，一邊在承擔結果的時候展現出推諉的傾向，讓誠正的好口碑與責任感的不足形成明顯落差。對合作者而言，他的誠信底色可信，但在有問題需要他快速接手處理時反應可能令人失望；管理上宜給具體的補救框架，減少他把歸因外移的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4370, 'CSR_19', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「把真話說得又直又清楚的人」。他以誠正為底線、不佔便宜不炫耀，面對紛爭又傾向直接表達立場、不太退讓——正因為他在意對錯，他不只說真話，而且說得直接、毫不修飾。遇到不公平或被要求違反原則的情況，他不會只是默默拒絕，而是會把理由明確攤開，立場鮮明、不留模糊空間。在需要有人對不公發聲、需要清楚異議的場域，他特別有效；但同一種直接，在需要漸進協商、維繫關係或佈局的情境，可能讓對話提前僵住、談判提早破裂。建議他在戰略性對話前先判斷「現在是說真話的場合，還是需要鋪陳的場合」，再決定直接表態的力道與時機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4372, 'CSR_19', 'B (中)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「原則易在衝動壓力下失守者」。他多數時候能保持公平與誠實，但在情緒被拉動或績效壓力下，原則邊界容易讓位給衝動反應；容易被情緒推著走的傾向，使得他在關鍵時刻的判斷更難預期。具體情境裡，他常一邊在平靜狀態維持誠正風格，一邊在壓力或衝突情境裡快速滑向對自己有利的倉促行動，事後再補救或解釋。對合作者而言，他在穩定環境下是可以信賴的；管理上宜在高壓決策前建立冷靜確認的節點，降低衝動下的行為偏差。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4373, 'CSR_19', 'C (低)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「守規範但利益優先的執行者」。他高度重視承諾與規則邊界，遇到灰色地帶傾向選擇可被交代的做法，這讓他在程序遵守上十分可靠；另一面，他對財富、地位與外在象徵的重視程度較高，公平與謙遜的自我要求偏弱，在回報分配上傾向積極謀取。具體情境裡，他常一邊嚴守規範讓人信任，一邊在利益分配問題上悄悄往自己這邊靠，把謀取包裝成盡責的自然延伸。對團隊而言，他的程序可靠性強，但在評估與分配機制不透明時可能成為問題根源；管理上宜把利益分配的標準公開化，減少他自行解釋的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4374, 'CSR_19', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「短期誘惑下的利益即時者」。他較容易被短期誘惑牽動，明知長期目標重要仍常在當下選擇即時回報；對財富與地位的重視讓他在利益出現時更難維持公平與謙遜的自我要求，較易合理化先拿到再說的做法。具體情境裡，他常一邊在即時利益面前快速行動，一邊讓既有計畫或公平原則在這個時刻退場，事後才評估是否需要補救說明。對周遭而言，他在利益明確時的行為預期度偏低；管理上宜用清楚的規則與外部稽核縮短他自行詮釋的空間，並給他可見的長期回饋讓延遲滿足有所連結。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4375, 'CSR_19', 'C (低)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「信任他人但自身利益優先者」。他對他人以善意預設為穩定傾向，很少因風險而收回信任，讓合作氣氛容易建立；但對財富與地位的重視程度偏高，公平與謙遜的自我要求偏弱，在利益可見時容易優先確保自己的份額。具體情境裡，他常一邊展現信任他人的開放姿態，一邊在資源或功勞的分配上朝對自己有利的方向移動，利用良好的合作氛圍換取更大的操作空間。對周遭而言，他的人際風格討喜，但在利益分配透明度不足的環境裡存在潛在風險；管理上宜建立可溯源的分配機制，讓誠正與信任都能在可見的規則下運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4376, 'CSR_19', 'C (低)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「強責任感與個人利益的拉扯者」。他對把事情做好有強烈決心，遇到問題主動承擔並追根究柢；但對財富與地位的重視程度偏高，公平與謙遜的自我要求較弱，在回報分配上容易合理化多拿的邏輯。具體情境裡，他常一邊展現高度責任感讓人留下深刻的可靠印象，一邊在利益分配時積極確保自己的份額，用付出多寡當理由推動對自己有利的評估。對合作者而言，他是負責任但不易接受吃虧分配的成員；管理上宜把責任與回報的對等機制明確化，讓他的付出與獲取都在公開可見的標準下運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4377, 'CSR_20', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「藍圖完備卻推力有限」。他能把目標拆解清楚並準備好替代路徑，但工作動力更受環境支持和外部要求牽動，自身主動投入意願偏向完成合理範圍即可。在他身上，路徑策略的精密程度與實際衝刺力道並不相稱，計畫完備卻不一定被自己執行到位。管理上應在確認路徑後補上明確的績效預期與進度節點，把外部要求轉化為他願意全力推進的觸發條件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4378, 'CSR_20', 'A (高)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「看得到路卻懷疑自己能走完」。他能把目標具體化並想出替代路徑，但對自己能否完成目標缺乏把握，每到行動關鍵點便容易遲疑或尋求他人的確認。這兩個狀態的碰撞讓路徑策略停在腦中而難以落地：方案愈充分，他愈難決定從哪條開始。建議在任務分配時先從範圍可控、回饋快速的子目標入手，讓他從早期成果中建立推進信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4379, 'CSR_20', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「改道意願強但預期悲觀」。他具備遇到阻礙改道而不放棄的能力，卻習慣把不如意詮釋為持久且普遍的訊號，使每次換路後的推進動能快速衰減。兩者的衝突在於：路徑策略的靈活與悲觀解釋的頑固同時存在，形成「能換路、不相信新路」的內在張力。這類人的管理重點在提供可見的早期勝利，打斷「阻礙必然持續」的預期循環。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4380, 'CSR_20', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「路徑充足卻消耗難補」。他在短中期能靈活切換路徑、不因單次阻礙放棄，但長期高壓或接連挫折後，恢復能量匱乏讓這套路徑靈活度失去燃料——知道怎麼改道，卻沒有力氣去改。對需要長期持續推進的任務，應在工作設計上內建減壓節點，確保韌性消耗不超過補給速度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4381, 'CSR_20', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「策略主動卻執行被動」。他能把目標清楚描繪並規劃備用方案，但較少相信自己的行動能真正影響結果，傾向等待外部訊號再出發。這形成一個落差：路徑規劃能力超出實際啟動意願，方案停在紙上的時間遠比應有的長。管理上建議給予明確的啟動觸發條件，把等待的空間縮到最小。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4382, 'CSR_20', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「改道能力強但焦慮感持續」。他能把目標具體化並備好替代方案，但對模糊與未知極度敏感，使路徑規劃從有效工具變成焦慮管理的出口——不是因為需要，而是因為「再多備一條才安心」。在他身上，這往往呈現為過度規劃與分析癱瘓。建議設定清楚的方案上限，把精力從無止盡備援轉回實際推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4383, 'CSR_20', 'A (高)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「路徑清晰加韌性厚實」。他能把目標具體化並隨時準備切換路徑，同時有充沛的內在資源——對投入事物的歸屬感、相信自己可以影響局面的控制信念、以及把變動視為常態的挑戰觀。他既能規劃出清晰路徑，又有這幾種堅毅要素撐住意志，因此遇到阻礙時他不只知道怎麼換路，還有足夠的意志資源真的走完新路。這是面對複雜長期挑戰時最可靠的配置之一。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4488, 'CSR_25', 'A (高)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「正向但不攬責」。他對挫折天生有輕描淡寫的詮釋能力——事情不順是暫時的、情況會好轉——但同時遇到失誤較少主動承擔，傾向把原因歸向環境與他人，讓他的「快速復原」實際上跳過了失敗的反思。外表樂觀開朗、不糾結，實際上學習迴圈卡在外部歸因這一環。建議在覆盤場合主動設定結構化的「我能控制的部分」分析，而非讓他自由詮釋失敗原因。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4384, 'CSR_20', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「換路快但難以持續深耕」。他遇阻礙能迅速啟動替代路徑，同時又很容易對手上的事失去投入感，於是從他自己的角度看，『因為這條路走不通而換』和『因為膩了而想換』幾乎是同一種衝動——他常常分不清自己究竟在繞過真實障礙，還是只是在逃離單調。結果是他的路徑切換頻率高於任務實際需要，推進顯得很有動感，深度耕耘同一條路的耐力卻有限。對這種人，工作設計上可把任務拆成多個階段性成果，每個節點給予新鮮的刺激輸入，讓他易膩的能量被導向『一段段往前推』而不是『一再換路』。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4385, 'CSR_20', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「外部引導補足路徑缺口」。他有目標動機，但路徑規劃有時需要外部對齊，而強烈的自控信念讓他不會在卡住時消極等待——會主動去找方向、找資源，一旦確認路徑便快速啟動。在他身上，卡住期相對短暫：主動掌控的驅力縮短了他等待引導的窗口。在有清楚指導資源的環境中，這個組合能穩定輸出；給予階段性路標是最有效的支援方式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4386, 'CSR_20', 'B (中)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「需引導又缺主動雙重等待」。他的目標動機需要外部引導幫助規劃路徑，而主動發起行動的傾向本就偏弱，卡住時也較少自己去找方向。他既等著別人給方向，也等著別人推一把，於是停滯期明顯拉長，重新啟動幾乎完全依賴外部介入。這種組合需要管理者更頻繁地主動同步、提供節點確認，而不能預期他自己帶著問題找上門。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4387, 'CSR_20', 'B (中)', 'CSR_25', 'A', '與 CSR_25 (樂觀) A聯動：表現為「阻礙可恢復且重新出發快」。他的路徑規劃有時需要外部協助，但把挫折視為暫時且可改善的解釋習慣讓卡住期間的士氣損耗降到最低——不會因為一次方法不順就陷入自我懷疑。重新對齊後再啟動的速度也因此加快。這個組合在有引導資源的環境中表現良好；管理重點是確保當他卡住時，對齊的協助能及時到位，而不是等他自己找到新路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4388, 'CSR_20', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「需引導又自我懷疑卡點加倍」。他的路徑規劃本就有時需要外部協助，而對自己能否完成目標缺乏信心又讓重新啟動的門檻更高——引導給了方向，自我懷疑仍在追問「我做得到嗎」。在他身上，任何一次卡住的脫困成本都明顯偏高。建議把引導拆成可快速驗收的小步驟，讓他從成功完成小任務中積累信心，而非在路徑整體確認後才出發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4389, 'CSR_20', 'B (中)', 'CSR_26', 'A', '與 CSR_26 (條理性) A聯動：表現為「流程結構補充路徑引導」。他的路徑規劃有時需要外部對齊，但清楚的流程偏好和例行節奏讓方法卡住時不至於完全失去方向——他會回到程序節點上等候，而不是空白等待。條理性提供的結構成為希望引導間隙的緩衝。這個組合在流程清晰的工作環境中特別穩定；管理上應確保任務有明確的程序框架，讓他在路徑不確定時有結構可依靠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4390, 'CSR_20', 'B (中)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「動機能續航但容易被誘惑打岔的推進者」。他對目標有一定的動機，方法順利時能穩定往前，重新對齊方向後也能再推進。不過在延遲滿足與抗拒短期誘惑這一塊，他明知長期目標重要，仍容易在當下選擇立即回報的事情，計畫推進中途容易出現鬆動或偏軌。具體情境裡，他在結構清楚、目標可見、外部支持足夠時表現最穩，一旦進入長期且缺乏即時回饋的任務，推進節奏就容易受干擾，管理上宜把長期目標拆成短期可見的里程碑，讓動機有地方落腳。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4391, 'CSR_20', 'B (中)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「目標感有但收尾支撐不足的推進者」。他有清楚的目標動機，在方向明確時能開始推進，方法卡住後重新對齊也能再上路。不過在自我監控與維持節奏這一段，他相對吃力，容易受情境或情緒影響而出現拖延或尾段收尾不足。具體情境裡，他啟動時通常沒問題，但在複雜任務的中後段若缺少外部節點提醒，品質與進度容易悄悄下滑；管理上宜設定明確的中間交付點，並清楚界定各段責任範圍，幫助他把目標動機持續轉換成可驗收的實際輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4392, 'CSR_20', 'C (低)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「不知如何走又不信自己能走」。他在遇到阻礙時難以找到替代策略，同時對自己能否完成目標極度缺乏信心；找不到路時他更確認「自己做不到」，而因為不信自己，他也往往提前放棄找路的努力。這個組合中連主動求助的門檻都被升高——他可能擔心接受幫助後仍然失敗。介入需從最小成功單位入手，讓他先體驗「這一步我做得到」來打破封閉迴路。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4393, 'CSR_20', 'C (低)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「卡住又復原慢雙重耗損」。他在遇到阻礙時難以啟動替代路徑，而在高壓或連續失敗後補救和恢復的能力也偏弱。在他身上，這呈現為雙重耗損：路徑不足讓挫折更頻繁發生，韌性不足讓每次挫折的代價更難被消化。長期任務中這是動能最快速流失的高風險配置，建議主動將任務切短、增加支持節點，並在早期就介入路徑協助而不是等待他自行突破。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4394, 'CSR_20', 'C (低)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「路徑不足加被動因應完全停擺」。他較難把目標與策略路徑連結，同時傾向被動等待結果而非主動採取行動。在他身上，這呈現為一種封閉的停滯：沒有路徑可以主動走，被動傾向讓他也不會去找；沒有主動啟動，路徑也沒有機會被嘗試和修正。這種狀態中停滯幾乎沒有自我解除的機制，管理上需要外部主動提供具體的第一步行動指示，而不是給出方向後等待他自行出發。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4395, 'CSR_20', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「停滯又外移歸因難以改善」。他在遇到阻礙時難以連結替代路徑，而遇到失誤或延誤又傾向歸因外部，使每次卡住都被解讀成環境問題而非自身策略需要調整的訊號。這兩者共同切斷了學習迴路：路徑不足製造失敗，外移歸因阻止從失敗中提取教訓，改進速度因此極慢。管理介入需兼顧路徑輔助（給工具）和責任框定（明確哪些是可控變因），讓他有機會體驗「調整策略有用」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4396, 'CSR_20', 'C (低)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「路徑缺位加資源耗盡」。他在遇到阻礙時難以找到替代路徑，而能夠緩衝逆境的內在資源——對投入事物的歸屬感、相信自己可影響結果的信念、以及把變化視為常態的心態——這三種構成堅毅的要素也同時薄弱。在他身上，這意味著在逆境中既沒有策略出口，也沒有撐住的底層資源，自行恢復幾乎不可能。這是需要最直接外部支撐的狀態，工作設計應優先降低逆境衝擊頻率，並在每次打擊後主動提供支持，而非期待自行反彈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4397, 'CSR_20', 'C (低)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「路徑有限又排斥改變的雙重固著」。他在遇到阻礙時難以產生替代策略，而傾向把穩定與可預測視為理想狀態、對變化感到不適，讓嘗試新路徑的心理代價進一步提高。路徑策略的工具箱本就有限，對改道本身的抗拒讓這個有限的工具箱更少被打開。在需要頻繁適應調整的環境中，這個組合最容易出現顯著的停滯和推進困難，建議在任務設計時盡量提供穩定的框架，在框架內提供具體可選的小改動選項，讓改變的代價感最小化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4398, 'CSR_21', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「冷靜但先做再說」。他在壓力情境中能管住情緒反應、不做失態言行，但決策前的停頓與評估習慣薄弱，傾向先啟動行動、事後再補上判斷——冷靜的外表讓這種行動模式難以被辨識為風險。在高後果場景中，其冷靜態度可能使旁邊的人以為他已經過深思，但實際上隱性風險評估步驟常被省略。建議在重要決策前明確要求寫出預期後果與假設，作為彌補審慎不足的結構補位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4399, 'CSR_21', 'A (高)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「情緒穩但誘惑易讓步」。他能管住情緒與衝動的社會表達——不在壓力下失態、不做出高代價的衝動言行——但在延遲滿足這個維度卻明顯不同，面對短期誘惑或立即舒適時計畫紀律容易鬆動。這兩種能力涉及不同的自我調節機制，前者強後者弱的組合使他在人際互動中顯得穩重，卻在執行節奏與計畫守持上較難維持。建議把長期目標拆為短期里程碑並配合外部結構提醒，減少誘惑決策點的頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4400, 'CSR_21', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「穩重的頻繁轉換者」。他在各類活動中都容易迅速失去投入感，但有足夠的情緒管理能力不把這種無聊顯露在外——不打哈欠、不公開抱怨、不做突兀脫離行為。真實的問題在於注意力已提前撤退，只是外表仍維持坐姿。在他身上，這容易讓觀察者產生誤讀，需要更主動地以工作節奏切換、任務多樣化來因應其厭倦傾向，而非靠其自制力無限撐持投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4401, 'CSR_21', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮持續但行為受控」。他對模糊與未知非常敏感，各類不確定情境都容易誘發強烈焦慮，但情緒與衝動管理的能力讓這些焦慮不以失態或衝動決定顯現——而是轉化為頻繁確認、反覆查核或過度溝通的行為。外表看來穩健、可信賴，但高不確定情境下的隱性耗損累積得很快。管理上應主動降低不確定性（明確里程碑、定期更新狀態），不要誤以為他「看起來沒事」就代表內在負擔輕。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4402, 'CSR_21', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「鎮定的強硬立場者」。他面對衝突時傾向直接表達立場、較少選擇退讓，同時情緒與衝動管理讓這種對抗以冷靜而非失控的形式展現——不會因為對方情緒升高就跟著爆發，也不會因壓力而撤退。這種組合在談判與立場維持上有其優勢，但也使衝突解決更為艱難：旁觀者無法用「讓他先冷靜」來降溫，需要真實回應其立場才能推進。建議在高對抗情境中主動結構化溝通流程，確保雙方有聽見對方論點的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4403, 'CSR_21', 'A (高)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「自律主動的持續超越者」。他在各類情境中都能自發開啟行動，超越既定要求；他同時管理情緒與衝動，讓主動行為不是一時熱情，而是穩定可持續的輸出。具體情境裡，他能長期在缺乏外部催促的情況下維持高投入，且不因壓力或挑戰而出現爆衝或失控。實務上他是可靠的自驅動員工，在自主性高的環境特別有表現；管理上最需要的是讓他有清楚的目標框架，避免過度承諾拖垮節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4404, 'CSR_21', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「壓力撐得住但資源不足」。他能在高壓下管住情緒反應、不做出失態言行或衝動決定，但堅毅性所指的內在承壓資源——包括對自身使命的連結、對局勢的掌控信念與對變化的接受——整體偏弱。這意味著他能短期撐住，但長時間逆境會加速消耗，且因外表冷靜，旁人不易察覺他已接近承壓上限。建議主動追蹤其工作負荷與恢復節奏，不要用「他看起來沒問題」作為無需支援的依據。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4405, 'CSR_21', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「冷靜地走捷徑」。他傾向在強烈競爭或目標壓力下把領先放第一、可能合理化不公平手段或利用他人換取優勢，但這些選擇不以衝動或情緒失控的形式表現——而是以冷靜計算的態度做出。正因如此，邊界行為更難被即時察覺，不會因為言行失態而被提早打斷。建議在競爭情境中建立行為留存軌跡與第三方核查，不要因其穩定的外表就降低對流程公正性的審查力度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4406, 'CSR_21', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「高壓下焦慮升高、護欄變薄的人」。他對不確定情境在各類處境中都極為敏感，且他的衝動管理本就在連續高壓、衝突或情緒消耗時出現波動；這兩個弱點的觸發條件高度重疊——當高不確定與高壓場景同時到來，他的焦慮最強、自制護欄最薄，此時他反應加快、語氣變硬的機率大幅升高。管理上應盡量在高壓期提供清晰資訊和決策結構，降低模糊狀態的持續時間。B 段狀態受情境驅動，非穩定特徵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4407, 'CSR_21', 'B (中)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「平時謹慎高壓時短路」。他常態下習慣在行動前評估風險與假設，且在一般壓力下也能穩住衝動，於是他既謹慎又自制；但他的衝動管理在連續高壓或衝突情境中會出現波動——反應加快、語氣變硬——此時原本精心維護的審慎程序也隨之被壓縮或跳過。常態下的審慎形象容易讓旁人以為他在任何情況都會停下來想，但高壓期的決策短路往往在事後才能察覺。建議在緊急高壓決策前加入強制確認步驟，不依賴個人狀態穩定性。B 段狀態受情境驅動，非穩定特徵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4408, 'CSR_21', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「平時可靠但高壓雙重耗損的工作者」。他一般狀態自制力良好，能穩定輸出；但在長期高壓或連續變動中，情緒管控與能量恢復都同時受到壓力。在他身上，這讓消耗更快累積。具體情境裡，他在短期衝刺中表現穩定，但若高壓持續延伸，反應加快與回彈變慢會同時出現。實務上他的穩定有時效性；管理上宜主動監控他的承壓狀態，在連續高壓任務後給予恢復空間，避免雙重耗損累積至無法挽回的程度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4409, 'CSR_21', 'B (中)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「高壓下雙重鬆動」。他的衝動管理在連續高壓或衝突情境中會出現波動，而延遲滿足與抗拒短期誘惑的自律能力本就偏弱；兩個維度在平穩期各自撐住，但一旦進入壓力高點或誘惑機會出現，往往同步鬆動——既可能做出衝動言行，也可能提前消費資源或放棄計畫。常態表現往往遮蓋了這個高壓脆弱窗口，建議在高壓期同時管理情境設計（減少誘惑決策點）和支持節奏（防止疲勞累積）。B 段狀態受情境驅動，非穩定特徵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4410, 'CSR_21', 'B (中)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「高壓時衝突升級」。他面對紛爭時本就傾向直接表達立場、較少選擇退讓，同時他的衝動管理在連續高壓、衝突或疲勞時會出現波動。兩者在衝突場景同時觸發：對抗傾向拉高的時刻，恰好也是自制護欄最薄的時刻——語氣變硬、退讓意願更低，衝突快速升級。平時的管控能力讓觀察者低估其高壓時的風險。建議在預期高衝突情境前，安排緩衝時間與情緒復原機制，並設計讓各方有台階下的溝通結構。B 段狀態受情境驅動，非穩定特徵。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4411, 'CSR_21', 'B (中)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「情緒有波動但韌性充沛的承壓者」。他一般自制力良好，但在連續高壓或衝突時，情緒節奏會出現可察覺的波動；他同時具備充沛的內在韌性資源，能在波動後相對快速回穩。具體情境裡，他在高壓節點的情緒管控不是滴水不漏，但他不容易被逆境真正打倒，能在波動後繼續前進。實務上他是耐得住長期消耗的工作者，短暫的情緒波動不代表能力下降；管理上宜理解他在高壓期的語氣變化是短暫訊號，協助他有意識地在波動後補充緩衝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4412, 'CSR_21', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「情境波動且容易消沉的承壓者」。他在一般狀態下自制力不差，但在高壓或連續挫折中，他傾向把不順解讀為長期且難以改變，這份悲觀解釋讓情緒管控變得更吃力。具體情境裡，遇到接連的不如意時，他可能一邊情緒升溫，一邊萌生放棄的念頭，兩者同時拉低行動品質。實務上他在順境中表現穩定，但在逆境中的復原速度會慢下來；管理上宜給予及時的進展回饋，讓他看見可改善的訊號，打斷悲觀解釋的循環。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4413, 'CSR_21', 'C (低)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「審慎習慣被情緒覆蓋」。他在行動前評估風險、假設與後果的習慣真實存在，在平靜環境中能有效展現；但衝動管理偏弱使他在情緒被觸發時這套程序就被直接跳過——不是沒有審慎能力，而是情緒啟動後這個能力的通道被關閉了。旁觀者在平時觀察到他謹慎的一面，往往低估其在壓力或衝突情境中失準的機率。建議針對高情緒觸發場景預先建立程序性護欄（如強制冷靜期），使審慎習慣不完全依賴情緒狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4414, 'CSR_21', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「情緒與誘惑雙面失守」。較容易被情緒推著走出現衝動回應，同時在延遲滿足和抗拒短期誘惑方面也持續吃力，兩個維度的失效方向高度一致——都朝向當下、遠離長期目標。這種組合使行為可靠性在高壓或誘惑情境下雙向崩落：衝動言行和計畫中斷往往同時出現，事後修補的頻率和成本都更高。建議透過環境設計減少誘惑決策點的密度，同時為情緒高漲時提供強制緩衝機制，從兩個入口同時降低失控頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4415, 'CSR_21', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「衝動且對抗性強的紛爭者」。他較容易被情緒推著走，在高壓或衝突中出現衝動回應；他面對紛爭時同時傾向直接表達立場，較少選擇退讓或迎合。具體情境裡，遇到意見不合或對方施壓時，他可能快速爭辯，讓衝突升級後才意識到需要修補。實務上他在需要維持關係穩定的場合容易製造張力；管理上宜在他進入高壓前主動溝通期望，讓他有機會在衝動出現前找到出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4416, 'CSR_21', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「不確定激發衝動爆發」。他對模糊與未知在各類情境中都極度敏感，同時衝動管理偏弱，使焦慮難以在內部承擔，往往以衝動行為的方式減輕不確定帶來的壓力——倉促要求答案、強行推進決策或情緒性地要求明確承諾。這種組合讓不確定情境成為衝動行為的系統性觸發源，與其等問題爆發再處理，不如在工作設計上主動降低模糊時間（及時更新狀態、明確下一步），從源頭減少觸發頻率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4417, 'CSR_21', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「善意基礎下的衝動傷害」。他在各類人際情境中能自然展現信任與熱情，連對陌生人也不例外——但衝動管理偏弱使情緒在壓力或摩擦時容易過頭，失態言行或倉促承諾就在這份善意的背景下出現了。親近的關係往往讓旁人更傾向接受事後解釋而非即時指正，反而讓問題重複發生而不被修正。建議在親近關係中也建立明確的行為回饋管道，讓衝動行為不因善意光環而被持續包容。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4418, 'CSR_21', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「衝動失誤後傾向歸因外部的行動者」。他較容易被情緒推著走，出現衝動回應或倉促承諾；遇到失誤後，他又傾向把原因歸給情境或他人，較少主動承擔與補救。具體情境裡，他在當下行動快但欠缺自我監控，事後補救節奏又偏被動，讓問題累積的速度比修補的速度快。實務上他在自主責任制環境的表現可靠度偏低；管理上宜在關鍵任務設置明確的確認點，協助他在衝動行動前有一個停頓機制，同時讓責任歸屬在出問題時有清楚的定義。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4419, 'CSR_21', 'C (低)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「衝動加利益取向的高風險組合」。他較重視利益、地位或外在象徵，可能合理化先拿到再說的做法；同時衝動管理偏弱使情緒與機會出現時的克制能力不足——兩者的動機方向一致，讓邊界行為的發生門檻大幅降低，且事後因對公平與誠懇的自我要求較弱，合理化框架容易讓行為自我持續。這種組合需要更密集的流程透明度與第三方確認機制，以行為軌跡而非意圖宣告作為信任基礎。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4420, 'CSR_21', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「衝動配上彈性底線」。他傾向把規範視為可調整的工具，在目標壓力下較容易優先選擇結果導向做法；衝動管理偏弱使情緒或當下壓力更容易在規則前省略停頓——他既把底線看得有彈性、又在當下難以踩煞車，於是他的越界不是偶然個案，而是較可預測的頻率行為。建議針對關鍵規則設置強制程序點（不可繞過的確認步驟），使底線合規不依賴個人意識與衝動控制的狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4421, 'CSR_22', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「焦慮驅動快速行動者」。他對任何未知或模糊情境都有極強的不安感，這種焦慮讓他難以靜待資訊齊備再出手；他傾向透過立即行動來緩解內心的不確定感，評估往往在事情啟動後才補上。實務情境中，他一邊承受強烈的焦慮壓力，一邊已經先把事情推著跑，周遭人常看到他在執行到一半時才回頭確認前提條件。這個節奏容易讓他在快速環境中帶出速度，但在需要事前風險評估的決策上容易留下缺口；管理上宜在行動前建立簡短的確認清單，幫助他把焦慮轉化為結構化的準備動作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4422, 'CSR_22', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「焦慮觸發衝動反應者」。他對任何不確定情境都有極低的容忍度，焦慮感在模糊局面中幾乎立即升至高點；情緒積累到一定程度後，他容易被內在張力推著走，出現倉促表態或行為過頭的反應。具體情境裡，他一邊被強烈的不安感籠罩，一邊很難等待局面自行明朗，往往在結果還不清楚時就採取了高代價的行動。這種組合在需要快速回應的場景可能帶出即時性，但在需要等待的情境容易造成張力；管理上宜在他出現明顯焦慮信號時提供一個可操作的短期確認步驟，協助他用結構性行動取代衝動反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4423, 'CSR_22', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「災難化的預期者」。對他而言，『不知道結果』和『大概會是壞結果』幾乎是同一個念頭——他對未知本就高度敏感，而他解讀事情的習慣又總把不如意看成長期且難以扭轉，於是每一個懸而未決的情境，在他心裡都不是中性的空白，而是壞結局的前兆。未知對他從來不只是未知，而是預設的災難。結果是情勢還沒明朗，他就已經預期失敗、提前退縮，或反覆向人求保證來壓低那份壞預感。建議用具體、近期、可改善的事實去校正他的預期，把『想像中的災難』和『實際的風險』之間的落差一點點縮小。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4424, 'CSR_22', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「耗竭的焦慮者」。在他身上，不確定帶來的不只是當下的焦慮，還是一筆還不掉的消耗——他對未知持續緊繃，偏偏在長期高壓下又特別難回血，於是懸而未決對他既是不斷扣血的來源，又遲遲補不回來。這讓他越拖越虛：變動只要延續，他的情緒和表現會一起往下走，因為他始終處在『持續被消耗、卻來不及恢復』的狀態裡。建議盡早給他明確的時間框架和階段性的收斂點，讓不確定有看得見的盡頭，他才不會一路緊繃到耗盡。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4425, 'CSR_22', 'A (高)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「無止盡的求證者」。對他來說，『結果還沒定』和『東西還不夠好』帶來的是同一種坐立難安——他既無法忍受懸而未決，又無法接受任何瑕疵，於是『再查一次、再確認一次、再修一遍』成了他同時對付這兩種不安的唯一動作。問題在於這個動作沒有自然的終點：查得越多，他越能找到新的不確定和新的不完美，於是檢查本身變成了停不下來的迴圈，遲遲不肯定案。建議替他外加一條明確的『夠好了就停』準則和截止點，給這個本來會無限延伸的求證過程一個必須收手的邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4426, 'CSR_22', 'A (高)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「強烈迴避變動的確定性追求者」。他天然傾向把穩定與可預測當作常態，對變化與未知抱持不適；同時，他對任何程度的不確定性都有強烈且持續的焦慮反應，這讓他在模糊情境中很難找到安全感。在需要頻繁調適方向的環境裡，他一邊努力把局面拉回熟悉節奏，一邊內心持續承受壓力；周遭人會看到他不斷反覆確認計畫細節，並對任何計畫外的變動表現出明顯抗拒。這個特性在穩定且可預測的環境中能維持高度可靠，但在動態環境中需要刻意支持；管理上宜提前告知可能的變動、給予清楚的方向說明，避免在訊息不足的狀態下要求他接受轉向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4427, 'CSR_22', 'A (高)', 'CSR_30', 'A', '與 CSR_30 (心理資本) A聯動：表現為「有資源撐住的緊張者」。他面對未知一樣會升起明顯的焦慮，這份敏感並沒有消失；但他同時是個對自己懷著希望、相信事情可以被處理的人，所以同一個不確定情境，他既感到緊張、又同時覺得『這是能解的問題』。這讓他的焦慮不會空轉成『會不會完蛋』，而是順勢變成『那接下來該怎麼推』——他會承認自己不安，卻仍維持得住動能、主動去拆解。這是無法忍受不確定性裡相對可控的一種樣子。建議善用他這份正向底氣，在高不確定的任務中讓他把緊張轉成往前推進的能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4428, 'CSR_22', 'A (高)', 'CSR_32', 'A', '與 CSR_32 (自我勝任感) A聯動：表現為「自信卻高度焦慮的風險感知者」。他對自身能力有穩定且明確的信心，面對具挑戰性的任務會主動承擔並拆解推進，較少因為能不能做到而退縮；然而外部情境一旦出現模糊訊號，他的焦慮就會快速啟動，對未知的部分反應強烈。具體情境裡，他一邊有足夠的勝任感讓他敢接、敢推進，一邊在執行中持續追問、反覆確認還有哪裡不明確，周遭人會察覺到他同時帶著信心與緊繃。在有明確目標與即時回饋的環境中，他能充分展現能力；但在資訊持續不完整的環境裡，他的焦慮會消耗注意力資源；管理上宜提供明確的里程碑與狀態更新機制，讓他的掌控需求有結構性出口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4429, 'CSR_22', 'A (高)', 'CSR_20', 'A', '與 CSR_20 (希望) A聯動：表現為「以備案安撫的焦慮者」。他對未知強烈不安，同時又很擅長把目標講清楚、替自己預想好幾條路——對他而言，這不是焦慮之外另一項本事，而正是他安撫焦慮的方式：當不確定逼近，他會自然地開始『那我先想好幾條路』，把模糊的未知重新翻譯成一個需要布局的問題。於是他的不安比較少空轉，多半會落地成預想阻礙、設想改道的準備動作。要注意的是，當情境模糊到連備案都排不出來時，他失去的不只是計畫，還有安撫自己的辦法，焦慮便會回升。建議鼓勵他發揮這份路徑規劃的長處，同時練習：當路無法窮盡時，學著接住剩下那段無法消除的不確定，而不是無限地再加一條備案。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4430, 'CSR_22', 'B (中)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「框架內的安心者」。他在不確定有限、時間框架看得見時本來就能從容，只有當事情長期懸著才會明顯焦慮；而他面對事情，又習慣在出手前把風險和假設想一遍。這兩件事在他身上是相輔的同一種傾向：他應付不確定的方式，正是先動手把它結構化——釐清哪些已知、列出假設與時程，把模糊收斂進自己能承受的範圍，再決定怎麼走。於是他『能從容』的情境比一般人更寬，因為他懂得替不確定搭出可預見的骨架。提醒：碰到完全沒有時程、無從結構化的開放情境時，他那份有限的容忍仍會被觸發，這時需要額外給他方向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4431, 'CSR_22', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「久懸即崩的悲觀者」。短期、看得見盡頭的不確定，他還能從容；但他同時是個習慣把不如意看成長期又普遍的人，於是一旦事情拖長、方向不明，他心裡那句『這大概不會好轉』就會很快接管。對他來說，時間是關鍵——情境可預見時他撐得住，可一旦進入未知的延長賽，他的容忍會比一般人更早崩解，呈現出前期還願意配合、後期轉為消極甚至預期失敗的落差。建議特別替他控管不確定的『持續時間』，及早給出進展的訊號，別讓那股悲觀預期提前上場。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4432, 'CSR_22', 'B (中)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「久撐不潰的調節者」。短期可預見的不確定他能從容，懸久了焦慮確實會升上來——但他也是個遇壓後能很快回到可工作狀態的人，於是緊張對他『會來，也走得快』。正因為他骨子裡相信『就算難受也撐得回來』，延長的不確定在他眼中就只是需要管理的一波壓力，而不是無法承受的威脅。即使越過了那個『看得見時程』的舒適區，他也不太容易崩盤，恢復速度成了他最關鍵的本錢。建議在長期不確定的任務中借重他的復原力，並用階段性的回饋去強化『我撐得過』的正向經驗。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4433, 'CSR_22', 'B (中)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「把無常當常態者」。有限、可預見的不確定他本就能從容，懸久了才會焦慮；但他天生把變化看成生活的常態、還能從中取得動能，於是面對『持續的不確定』，他的第一反應不是抵抗，而是重新框定：這就是環境本來的樣子。正因為他能這樣看，原本會讓他焦慮的開放情境，多半被他當成可以運用而非需要消除的東西，在頻繁變動中他仍投得進去，也較少要求事事底定。這讓他能從容的邊界明顯往外推。提醒：當變動完全失去脈絡與方向、連『這是常態』都套不上時，他那個焦慮觸發點仍可能浮現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4434, 'CSR_22', 'B (中)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「久拖即耗的乏力者」。短期、可預見的不確定他還能從容，懸久了負面反應就上來；偏偏他內在的希望、效能與韌性都偏薄，於是當不確定延長、最需要後備動能去撐的時候，他恰恰沒什麼可調用的。對他而言，情境可控時尚能平穩，一旦拖長就既看不到出路、又提不起勁——他『能從容』的條件本就比別人脆弱，久懸時便更快滑向無力。表現上常是前期還行、長期退縮停滯。建議盡量縮短他面對的不確定週期，並主動補上支持與進展訊號，趕在那股乏力真正壓垮他之前。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4435, 'CSR_22', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「久懸自疑的遲疑者」。有限、可預見的不確定他能從容，懸久了焦慮會升高；而他本來就容易懷疑自己做不做得好、需要更多安全感才敢往前。對他來說，這兩者在久懸時會接成同一條思路：拖久了他不只覺得『搞不清楚狀況』，還會進一步讀成『這恐怕是我應付不來』，把外在的不確定內化成對自己的不信任。於是在延長的不確定下，他容易遲疑、過度求證，或乾脆把決定交給別人。建議透過明確的分工和一連串小步成功的經驗替他補足安全感，別讓『不安』和『不信任自己』在他心裡互相壯大。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4436, 'CSR_22', 'B (中)', 'CSR_20', 'A', '與 CSR_20 (希望) A聯動：表現為「靠路徑延長耐受者」。短期、可預見的不確定他能從容，懸久了本會焦慮；但他擅長把目標講清楚、替自己想好幾條替代路徑，於是他撐住延長不確定的辦法，就是把開放的局面重新轉成一個『有方向可走』的問題。只要他還能排出路徑，原本該焦慮的時點就被往後推——規劃對他不只是工具，更是延後焦慮臨界點的方式。這讓他比一般人更能在久懸的情境裡保持耐受。提醒：當情境模糊到連一條路都想不出來時，他用來撐場的辦法也跟著失效，焦慮便會回升。建議鼓勵他發揮路徑規劃的長處，同時練習在『無路可排』時承受那段剩餘的不確定。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4437, 'CSR_22', 'C (低)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「從容的快速試行者」。他面對不確定能維持穩定，也偏好先做再調整、邊做邊學——對他而言這是同一種放鬆的探索心態：未知不是得先消除的風險，而是『先試試看』的空間，所以他在資訊還不足時也願意快速行動、迭代修正。因為他本來就不焦慮，這份快速試行少了那種被不安推著走的倉促，更像是從容地探路。要留意的是，他既不焦慮又傾向行動先行，也可能因此低估藏在底下的風險，因為他既不急也不特別在出手前掂量後果。建議替他的速度搭配一層外部審視，讓快不至於犧牲掉必要的風險把關。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4438, 'CSR_22', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「穩定順應變動的開放行動者」。他對不確定情境有較高的容忍度，面對模糊也能維持內在平穩；同時他把變化視為生活的常態，不需要外部環境達到某個穩定門檻才能投入。在需要不斷調適方向的環境裡，他一邊對模糊的現況感到從容，一邊持續從變動中獲取動能，不容易因為計畫改動而停頓。周遭人在他身上感受到一種穩定的適應力，在高度不確定的情境中，他能帶出較少因模糊而產生的內耗。這個特性在快速迭代或方向頻繁校準的環境中尤為有效；管理上不需要刻意為他提供過度的穩定結構，給予適度的自主空間讓他自行在不確定中找到前進方式即可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4439, 'CSR_22', 'C (低)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「沉穩耐受的定錨者」。他面對不確定能維持穩定，遇到壓力或失敗後又能很快回到可工作狀態——這兩件事在他身上是同一種沉穩的底色：不論是眼前的未知，還是事後的打擊，他都把它當成可承受、可恢復的過程，於是既不被未知擾動，也不被挫折擊倒。動盪當中他多半能保持冷靜，把注意力放在『下一步能做什麼』。正因如此，他常成了團隊在不確定期的情緒定錨，而且動盪拖得越久，這份穩定越顯得可貴。建議在長期高壓或變動的情境中借重他的穩定，把他當成團隊的參照點與緩衝。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4440, 'CSR_22', 'C (低)', 'CSR_25', 'A', '與 CSR_25 (樂觀) A聯動：表現為「穩定向前的樂觀者」。他面對不確定能維持穩定，又習慣把挫折看成暫時、可改善——在他身上，這是同一份平穩期待的兩種說法：既不把未知當威脅，又相信眼前的不順只是過渡。於是模糊情境對他不是停下觀望的理由，他多半能維持行動力，也不因單次受挫就停步，心裡那句『現在看不清，但會逐漸明朗、也會變好』讓他持續往前。建議讓他在前景不明的開拓性任務裡帶動節奏；他的穩定與希望感，正好能緩衝團隊的觀望與遲疑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4441, 'CSR_22', 'C (低)', 'CSR_27', 'A', '與 CSR_27 (完美主義) A聯動：表現為「容得下未知的苛求者」。他面對不確定能維持穩定，同時對細節與品質又極為苛求——關鍵在於他把這兩件事分得很清：結果未定，他可以容忍、耐心等它釐清；但東西做得粗糙，他一步都不讓。正因為他不焦慮，他的完美主義不會滑向那種『因為不安所以反覆查證』的空轉，而是穩穩對準真正該把關的品質。於是他能在情勢還未明朗時冷靜推進，卻對交付的成果寸步不讓，兩者構成一種相對健康的張力。建議把這個組合用在既要求高品質、情勢又多變的工作上；他的品質把關對準的是實質，而不是源於心慌。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4442, 'CSR_22', 'C (低)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「從容的審度者」。他面對不確定能維持穩定，行動前又會把風險、假設和後果評估一遍——在他身上，這是同一種沉著：他把未明的情勢當成需要冷靜權衡、而不是急著消除的對象，所以即使資訊不足，他仍能維持判斷的品質，蒐證、掂量之後再決定。正因為他不焦慮，他既不會被不安逼著倉促拍板，也不會被不安凍在原地動彈不得，而是能在不確定中穩穩地做出高品質的判斷。建議把他安排在需要於不確定中做關鍵決策的位置；這份穩定與審慎的結合，是相當可靠的資產。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4443, 'CSR_22', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「未明即啟動者」。他面對不確定能維持穩定，又能在方向模糊、缺乏支持時自發開始行動、甚至超出被交辦的範圍——對他而言，這是同一種不等指令的傾向：因為未知不會讓他卻步，『方向還沒明朗』在他眼中就成了『可以自己先動起來界定』的空間，而不是按兵不動的理由，於是他常在沒人補位的真空地帶率先頂上。建議把那種開拓性、規範還沒成形的任務交給他；他這份穩定加主動的組合，最適合替未定的局面開頭——只要事後記得確認他自己界定出來的方向，和整體目標對得上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4444, 'CSR_23', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「意義與成長優先的高效投入者」。他有明確的企圖心，遇到困難時習慣把方法和目標往上推；驅動他的是任務本身的份量與成長機會，不是物質激勵的多寡。在有挑戰性的環境裡，他願意長時間投入也不覺得付出需要立即兌現成金錢或地位。具體上他挑任務看深度，不看頭銜；做到一半遇到瓶頸，他傾向升級方法而不是去談薪酬。管理上他在意義清楚、難度足夠的任務中表現最佳，若把物質誘因當成主要管理工具，反而可能引起他的距離感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4445, 'CSR_23', 'A (高)', 'CSR_03', 'A', '與 CSR_03 (利他行為) A聯動：表現為「付出不算代價的行動者」。他願意在高度個人犧牲下仍持續付出，無私與體貼是他面對人的自然反應；而他對財富地位的淡然，使得「付出值不值得」這個念頭在他心裡天生就少了物質得失這一項。對他而言，幫助別人不需要先換算成報酬或地位加分才有動力——這不是「先計算、再扣掉物質項」，而是他衡量付出時，物質本來就不在天平上。於是他成了很少因為「幫了沒好處」而停下來的人。要留意的是，他也可能在設定個人邊界、保留自身資源上投入太少，長期需要有人提醒他補充與休整。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4446, 'CSR_23', 'A (高)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「有原則的意義導向行動者」。他不把財富與地位當成主要追求，也不願為了領先而欺騙或利用他人，在競爭中保持一條清楚的邊界。面對高誘惑的機會，他問的是「這值不值得做」，而不是「有沒有人看見」或「能拿多少」。他選擇任務看意義，遇到不公平競爭不參與，即使因此少了一些物質回報也不後悔。管理上他在透明、公正的環境最能發揮；若環境允許擦邊球甚至鼓勵，他容易感到與文化不合而逐漸退縮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4447, 'CSR_23', 'A (高)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「不顯富但需被看見」。他對財富與地位的象徵相當淡漠，卻同時很在意自己的貢獻有沒有被看見、被歸屬——表面上這兩件事像有張力，其實在他身上是一致的：他要的認可從來不是物質形式的，而是「我做的事被知道、被認可」。所以他既不會為薪酬斤斤計較、也不炫耀物質，但對於「誰做了什麼、功勞算在誰頭上」會相當敏感。對管理者來說，這個人不需要加薪來安撫，他需要的是被看見的舞台與清楚的貢獻歸屬；給對了渠道，比給錢更能滿足他的核心需求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4448, 'CSR_23', 'A (高)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「意義明確但執行易偏軌的行動者」。他選擇任務時看意義不看物質，但一旦進入執行階段，抗拒短期誘惑的能力卻相對不足，讓長期目標在推進上容易打折扣。他知道自己在乎什麼，卻常常在「等下再做」與「這樣也無所謂」之間消耗時間。具體上他在選任務時展現出清楚的價值判斷，但在日常執行中容易被立即回報的活動拉走，交付品質因此受節奏影響。管理上宜給他明確的里程碑和短週期回饋，光靠意義感不足以讓他維持穩定節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4449, 'CSR_23', 'A (高)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「意義導向但易鬆動承諾的工作者」。他投入工作靠的是任務本身有沒有份量，物質待遇不是主要的留任理由；但他對所處環境的心理依戀也相對薄弱，一旦任務失去吸引力或環境條件出現逆風，他不太有理由撐過去。遇到組織變動或任務重組，他在評估要不要繼續時，考量的是「現在還有沒有值得做的事」，而不是「對這個地方有多少義務」。管理上對他而言，讓任務保持足夠的意義感比加薪更能留住他，但若意義感一旦消失，物質補償也難以彌補。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4450, 'CSR_23', 'A (高)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「意義優先、規範彈性的行動者」。他不被物質誘因驅動，把任務的意義與成長放在第一位；但他對規範的態度相對鬆動，在目標壓力下容易把規則視為可調整的背景條件。這讓他在推進有深度的工作時動能強，但在需要遵守程序或承諾的節點上可能出現模糊地帶。具體情境下，他在有意義的任務中全力衝刺，遇到程序卡點時傾向先繞過再補文件；他的出發點不是貪圖好處，而是覺得結果比過程更重要。管理上宜明確哪些底線不可動，否則他的彈性邏輯可能在灰色地帶製造風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4451, 'CSR_23', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「意義敏感但難持久的興趣追求者」。他評估要不要投入時靠的是意義和成長而不是物質，但他對厭倦的抵抗力有限，新鮮感一旦退去，原本說服自己投入的理由也跟著鬆動。這讓他在任務初期的推進力和想法密度都相當高，但到了執行中後段，他的活躍度容易快速下降。具體上他傾向在意義清楚、難度夠高的開始階段全力投入，卻在任務進入收尾或重複作業時顯現明顯的退縮。管理上宜把長任務切成有獨立意義的小段，讓他持續在「有新事物可探索」的狀態下工作，否則他的意義驅動容易因厭倦而中途熄滅。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4452, 'CSR_23', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「不追高報酬也不求突破」。他在物質與地位上採取務實平衡的態度，而成就動機本就傾向完成合理範圍而非追求更高難度——兩者都偏向「夠用就好」，從不同的角度指向同一種低驅動水位。當缺乏外部意義框架時，這個組合容易讓他長期停留在穩定但不突破的狀態。若環境需要更高投入，給出清楚的意義與成長誘因比薪酬調整更有作用；B 段的務實平衡態度意味著他仍能識別合理取捨，不是完全動不了，只是推力需要從正確的方向施加。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4453, 'CSR_23', 'B (中)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「務實取捨、話術包裝的靈活行動者」。他對物質的態度務實平衡，不過度執著，但也不天真地忽視回報；在需要保護自身利益或爭取資源時，他傾向透過策略性的表達來影響對方，而不是完全透明地展示自己的底牌。他的判斷是情境性的，平時合作真誠，到了資源競爭的節點會切換成更靈活的溝通策略。具體上他在一般任務中不搶物質回報，卻在分配談判時善用資訊不對等；他不認為這是欺騙，而是必要的靈活。管理上在透明文化中這個組合容易製造信任落差，建議讓他在談判前先和管理者對齊核心底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4454, 'CSR_23', 'B (中)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「不爭物質但爭立場」。他不把財富與地位視為主要追求，在薪酬、資源分配的競爭中較為被動；但在遇到立場衝突或原則不合時，傾向直接表達甚至對抗。這個組合使他的衝突模式很特定：薪酬談判上幾乎不成問題，但在工作方式、決策方向或價值觀衝突的場合，他反而是主動的辯論者。管理上要預期他在薪酬上好說話，但在理念分歧上需要更多說明與溝通投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4455, 'CSR_23', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「淡然物質卻困於未知」。他對財富與地位的得失相當平靜，薪酬談判或物質變化不太會引發他的強烈反應；但只要情境涉及未知或模糊，負面反應就會出現且相當強烈。這個組合使他的焦慮觸發點非常特定：不是「得不到夠多」，而是「不知道接下來怎樣」。管理上給予充足的資訊透明度與方向確認，比給予薪酬保障或獎勵更能安定他的狀態；混淆兩者來源的管理者可能投入錯誤的安撫資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4456, 'CSR_23', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「自發行動不求物質回報」。他在各類情境中都能自發開啟行動、超越被交代的範圍，而推著他動起來的，是對任務本身的投入，不是薪酬期待或晉升算計。他啟動行動之前，根本不需要先盤算「做了能拿到多少」。他因此很難用物質誘因操控：加薪不會讓他突然更主動，減薪也不一定讓他縮手。管理上的著力點，是維持任務的意義感與方向清晰，把這些當成他主動性的燃料，而不是把薪酬結構當成驅動他的主要槓桿。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4457, 'CSR_23', 'C (低)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「財富地位雙向追逐者」。他把財富與地位視為重要追求，也傾向強調自身貢獻、把被看見當成核心需求；對他而言，薪酬數字、頭銜、貢獻歸屬都是敏感點，任何被認為「沒有被正當對待」的情境（無論是薪酬還是認可）都可能引發強烈反應。在資源或認可有限的環境中，他容易成為競爭最激烈的行動者；管理上需要在公平透明的分配機制上投入較多心力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4458, 'CSR_23', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「回報敏感、策略包裝的利益推進者」。他高度重視財富與地位的象徵，對回報落差有強烈反應；在與他人互動時，他也傾向用策略性的方式呈現自己的立場，選擇性揭露有利的資訊、隱藏或調整不利的部分。他在需要爭取資源的場合特別靈活也特別積極。在利益談判中他是主動推進者，不一定說謊，但習慣把對話朝對自己最有利的方向引導；對方若察覺到這個模式，信任就會快速受損。管理上需要明確的合規框架和透明的分配機制，否則他在競爭情境中容易觸發內部摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4459, 'CSR_23', 'C (低)', 'CSR_36', 'A', '與 CSR_36 (職場忠誠度) A聯動：表現為「高度物質導向的堅定留任者」。他對所在環境有深度的心理依戀，共度順逆的意願強，但他的忠誠前提之一是物質回報和地位感受符合預期。在環境穩定、回報足夠的條件下，他是非常可靠的長期成員；但若物質條件持續不如預期，他雖然不會立刻離開，內心的計算卻已經啟動。具體上他在承諾好的任務中表現穩定，遇到逆境也願意撐，但同時他也會持續追蹤自己的回報是否相稱，出現長期落差時情緒和投入都會改變。管理上給他的承諾要說到做到，尤其是物質和地位方面，一旦出現說好沒兌現，忠誠度的消耗會比預期快。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4460, 'CSR_23', 'C (低)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「回報導向的高自律推進者」。他有一貫的自我要求，做事不需外部催促也能維持節奏；但他也對物質回報和地位訊號高度敏感，把足夠的回報當成全力投入的前提。在兩個條件都滿足時，他是高效、可靠的推進者；一旦感覺物質上沒有被合理對待，他的盡責傾向並不會讓他繼續維持同樣的輸出品質。具體上他接任務前先確認回報結構，確認後進入高效執行；遇到功勞分配不清或薪酬落後市場，他的推進力和細節品質都會出現下滑。管理上宜定期確認他對回報結構的感受，主動溝通比等他表達不滿更有效。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4461, 'CSR_23', 'C (低)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「物質敏感、壓力易損的脆弱進取者」。他在物質和地位的回報上有明確的期待，同時在逆境和高壓中緩衝能力相對有限，困難時期特別難以維持穩定。順境下他能清楚表達自己的需求並積極推進，但遇到持續的壓力或逆境時，他的抗壓資源快速消耗，而此時對物質落差的不滿也最容易轉化成不合作或退出的訊號。他在穩定、回報清楚的環境表現最佳；一旦環境惡化且物質面同步失落，他的離心力會非常強。管理上在高壓時期要特別主動確認他的狀態，必要時給予支持資源，並確保物質承諾在壓力情境中仍然兌現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4462, 'CSR_23', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「物質在意但人際溫暖的合作者」。他天生對人友善，合作和信任是他在各類互動中的自然反應；他也很清楚財富和地位對他的意義，並不認為對物質有期待和對人好是矛盾的。這讓他在工作中既是好的合作夥伴，又是清楚知道自己想要什麼的談判者。遇到功勞分配或薪酬協商，他不會因為大家關係好就悶聲，而是直接表達自己的期待，但語氣通常不強硬。管理上他適合需要團隊合作、但也需要個人績效清楚可見的環境；若薪酬和地位結構模糊，他友善的表面下的不滿可能需要一段時間才顯現，一旦表露就相對直接。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4463, 'CSR_24', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「用力做事不爭名」。他對表現與成果有明顯企圖心，面對挑戰傾向主動升級方法與目標，不輕易停在夠用就好的位置。在追求卓越的過程中，他對自身與他人的相對位置看法較平衡，不需透過搶功或壓過他人來確認價值。具體情境裡，他願意把任務推到更高標準，也能接受他人在共同成果中占有一席之地。管理上他在有清楚目標與回饋的環境最有動能，也適合扮演帶頭拉高標準的角色，不易因功勞分配引發磨擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4464, 'CSR_24', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「直接表態但不貶低他人」。面對紛爭或對立，他傾向直接表達立場，較少選擇退讓或順從，衝突中容易出現爭辯性反應。在這種直接性的表達之外，他對自身與他人的相對位置看法較平衡，不需要透過壓低對方來凸顯自己。具體情境裡，他亮立場的方式偏事件導向，較少上升到對對方資格或能力的評判。管理上宜引導他把爭辯能量集中在問題本身，減少無謂的對立摩擦；同時他不易因維護「誰更重要」而升級衝突，是可以利用的特質。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4465, 'CSR_24', 'A (高)', 'CSR_13', 'A', '與 CSR_13 (同理關懷) A聯動：表現為「無聲的同行支持者」。他對他人困境的同情不因消耗而退縮，同時不需要透過被看見來確認自身價值，使關懷行為少了一層自我展示的雜訊。結果是他的情感投入更穩定、更一致，在長期支持情境中不易因「付出沒被認可」而中斷。建議在需要他對外倡議他人處境時給予明確授權，否則謙虛感可能使他的支持停留在幕後而缺乏必要的可見度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4466, 'CSR_24', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「主動認錯、扛責到底」。他對把事情做好有強烈決心，遇到問題主動承擔，而謙虛感使他不需要透過甩鍋來保護自我形象，大幅降低了責任迴避的動機。在他身上，面對失誤時的行動特別快、特別乾淨——不拖、不卸責、不抬高自己而貶低他人。這是高信賴角色的高價值表現，在事後覆盤機制中宜給予充分安全感，鞏固其開放溝通的動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4467, 'CSR_24', 'A (高)', 'CSR_34', 'A', '與 CSR_34 (誠懇) A聯動：表現為「坦誠且不需要展示的合作者」。他溝通偏直接透明、傾向用真實資訊建立合作，同時不需要透過炫耀或壓過他人來確認價值，使真實表達得以不帶任何形象管理的雜訊。這是團隊中罕見的高透明度組合：在自我揭露、承認局限、接受他人意見等行為上，成本極低。在需要誠正文化的高責任環境中，他是自然的錨點；要注意的是，過度透明在高政治性環境中可能使他的資訊被他人不對等使用。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4468, 'CSR_24', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「開放給予、戒備接受」。他不需要透過炫耀來證明自身價值，對他人貢獻的接受度較高；但同時對他人意圖高度警戒、傾向預設對方可能不利，使合作的信任建立過程明顯延長。結果是他在「分享自己的資源或想法」上相對大方，卻在「相信對方真心」這件事上設有較高門檻——關係需要對方持續展現一致性才能加速。建議在新合作啟動時提供透明的角色脈絡，降低他需要自行評估意圖的認知負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4469, 'CSR_24', 'A (高)', 'CSR_23', 'C', '與 CSR_23 (低物質傾向) C聯動：表現為「重物質回報但不計排名」。他重視財富、地位或外在象徵，對回報的合理性十分敏感，把物質激勵視為衡量投入是否值得的重要依據。在對物質回報的明確計算之外，他對自身與他人的相對地位看法較平衡，不需要藉由比較排名來確認自我價值。實務上他在薪酬或獎勵相關議題上意見直接，但不易因嫉妒或競爭心態影響協作氣氛。管理上宜確保報酬結構透明合理，讓他對物質回報有明確預期，他便能在協作中保持穩定而不執著於誰更受重視。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4470, 'CSR_24', 'A (高)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「謙遜形象包覆手段傾向」。他在人際互動中低調、不炫耀，但較容易把領先視為第一順位，可能合理化不公平手段或利用他人換取優勢。謙虛的外顯姿態與手段傾向同時存在時，後者的能見度反而更低——因為不搶鋒頭使人降低防備，不公平行為更不容易被早期識別。建議在高利益情境中以具體決策行為與資訊對稱度作為評估依據，而非依賴人際風格印象。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4471, 'CSR_24', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「含蓄等待、缺乏推力」。在需要展現影響力或爭取資源時，他本就猶豫如何拿捏分寸，加上成就動機受環境支持牽動而非自發，他「站出來主張」的行動門檻更高——他傾向等待環境給予明確信號才投入。若信號不足，他既不願張揚、動能又低，於是他的貢獻在重要時機不夠可見。建議定期提供具體的進展回饋並明確邀請他表達觀點，降低他自行判斷「現在適合站出來嗎」的認知負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4472, 'CSR_24', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「有把握但不願高調佔位」。他在各類處境都持續相信自身能影響結果並主動採取行動，但在需要展現影響力的場合猶豫如何拿捏分寸，使兩者產生落差——行動力強，但可見度刻意壓低。這讓他在幕後推動上可靠，但在需要他對外主張方向或爭取資源的場合反應較慢。當情境要求他公開扮演主導角色時，建議給予明確的社交授權與框架，協助他越過「分寸」猶豫的門檻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4473, 'CSR_24', 'B (中)', 'CSR_17', 'C', '與 CSR_17 (溫和有禮) C聯動：表現為「保留表達、批評不軟化」。他在需要展現影響力或自我推銷時保留、猶豫分寸，但評價他人時傾向直接嚴厲，較少展現寬容或緩和。這形成不對稱：自我呈現謹慎、批評他人不手軟——他人可能感覺到他在評斷標準上雙軌運行。在反饋或績效討論場合，建議配對具體的改善建議，以平衡批評的直接性；也需留意他的自我保留是否讓批評行為在群體中顯得突兀。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4474, 'CSR_24', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「自發行動、低調不張揚」。他在各類情境都能自發開啟行動並超越既定要求，但在需要展現影響力或爭取資源時猶豫分寸，使高度的主動精神在可見度上打了折扣。他做得多，說得少，長期可能形成貢獻與獎勵不對等的結構。管理上應主動設計貢獻可見機制（如進度分享、跨組匯報），而非等待他自發展示——否則他的主動精神會持續服務任務，但難以轉化為職涯資本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4475, 'CSR_24', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「含蓄加自我懷疑的雙重收縮」。在需要展現影響力或爭取資源的場合，他本就猶豫如何拿捏分寸，加上對能否完成任務缺乏把握——含蓄讓他不站出來，自我懷疑讓他不確定自己能不能，於是他更傾向收縮。結果是在需要他主動表態的時機，行動特別慢，甚至讓決策空間落到他人手裡。建議在新情境中預先拆解任務並提供明確的小步驟確認，協助他越過這雙重門檻。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4476, 'CSR_24', 'B (中)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「保留投入、低度扎根」。在需要爭取資源或表達需求的場合他本就猶豫分寸，他對環境的依戀感又低，因此他不太可能主動提出問題或協商留下的條件——他既不願把話講開、又對這裡不太眷戀，於是他從「不滿」到「離開」的路徑被縮短。外部觀察者往往難以事先察覺，因為他不會高調傳遞不滿訊號。建議以主動的一對一對話代替等待他開口，定期確認他的核心需求是否獲得滿足。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4477, 'CSR_24', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱情外交但中心仍是自我」。他在各類人際情境都能自然展現信任與熱情，合作成為穩定反應模式，同時傾向強調自身貢獻與地位、把被看見視為重要需求。親和性為自我凸顯提供了社交緩衝——他的自我展示更容易被理解為「自信」而非「自大」，使影響力建立更順暢。需留意的是，熱情的外顯不等於真正接受他人貢獻；在歸因分配上仍可能偏向自己，值得在協作覆盤時明確追蹤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4478, 'CSR_24', 'C (低)', 'CSR_03', 'C', '與 CSR_03 (利他行為) C聯動：表現為「先顧自己、以自我為中心」。面對他人需求他以自身利益為優先、較少主動體貼或犧牲，同時把被看見與認可視為重要需求，傾向強調自身貢獻。在他身上，這呈現為一種不對稱的協作姿態：他對他人的付出少，對自己被認可的要求多，使長期協作關係中容易累積失衡感。在高互賴任務中，建議設計明確的互助規範與成果共享框架，讓貢獻計算更透明，降低協作摩擦。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4479, 'CSR_24', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動出擊也主動搶鋒頭」。他無論情境可控程度如何，都持續相信自身能影響結果，並主動採取行動，掌控感穩定且不依賴外部催促。在這股主動性之中，他也把被看見視為重要需求，傾向在行動時確立自己是那個推動事情的人。具體情境裡，他不等待指示便能開始，也會確保自己的主導角色不被稀釋。管理上他在有自主空間的任務中表現突出，但在需要平等協作的場合，宜引導他把帶頭的能量聚焦在推動成果，而非爭取鎂光燈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4480, 'CSR_24', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「目標達成優先、合規彈性大」。他較容易把規範視為可調整的工具、在目標壓力下優先選擇結果導向做法，同時把被看見與認可視為重要需求。在他身上，對「成果歸屬自己」的執著伴隨著對合規程序的輕看，使他更可能採取擦邊球做法並強化自身貢獻的敘事。在高合規要求的環境中，建議設立明確且不可協商的底線，並讓他清楚意識到，合規瑕疵會是最直接傷害其聲譽的風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4481, 'CSR_24', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「自我凸顯遇不確定性強烈焦慮」。他把被看見視為重要需求，對自身地位與貢獻認可有明確期待，同時在不確定情境中容易產生強烈負面反應。在他身上，認可訊號的模糊會直接觸發高度焦慮：他不只不知道下一步，還不知道自己在別人眼中的位置，兩種不確定同時衝擊。建議在績效評估週期或組織變動期間，主動提供清晰且明確的貢獻認可，避免模糊訊號觸發不必要的過度反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4482, 'CSR_24', 'C (低)', 'CSR_16', 'C', '與 CSR_16 (寬恕) C聯動：表現為「功勞敏感且難以釋懷者」。他把被看見視為重要需求，對貢獻是否清楚歸屬到自己高度敏感；當這份需求未被滿足，他對冒犯者較難釋懷，不滿會持續積累而非隨時間自然消退。具體情境裡，一旦他認定某人搶了自己的功勞或刻意忽視他的付出，後續與對方的互動品質會明顯惡化，且難以快速恢復。管理上宜在事前就明確界定成果歸屬，定期讓他得到可見的認可；若已有積怨，需要較長時間的正向回饋才能修復關係，不能期待他自行釋懷。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4483, 'CSR_25', 'A (高)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「積極推進卻自我懷疑」。他把挫折自然解讀為可改善、可轉機，不容易被單次失敗打垮，但同時對自己能否完成目標缺乏把握——樂觀讓他不放棄，效能感不足卻讓每次再出發前都要先解決「我是那個能做到的人嗎」這個內部質疑。外觀上持續嘗試、態度正向，實際行動卻拖延或過度依賴他人確認。管理上應給予任務初期的明確分工與進度里程碑，讓他能用可見的小成功建立信心，而非只靠正向態度撐過整個歷程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4484, 'CSR_25', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「越挫越彈但復元費力」。他真心把每次挫折都讀成暫時、可扭轉，所以外表上總是繼續往前、令人印象深刻；但他從打擊中真正恢復的能量其實有限，連續高壓下消耗累積得很快。問題不在於樂觀替他『遮住』了什麼，而在於他自己也真的這樣相信——他用『沒事、會過去』去理解自己的疲態，因此既不向外求援、也不替自己踩煞車，旁人聽他說得正向也跟著低估了損耗。結果往往是看起來都好、直到突然撐不住。長期任務中應主動設恢復觀察點，用實際狀態而非他的正向自述來判斷該不該讓他喘口氣。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4485, 'CSR_25', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「積極解讀卻放棄掌控」。他把任何不如意都視為暫時可逆，情緒穩定、不容易崩潰，但同時極少相信自己的行動能改變結果——這讓他的樂觀更像是一種耐性而非驅動力，等待局勢自行扭轉而非主動出擊。在需要主動介入才能改善的情境中，這種組合可能讓機會窗口錯過。管理上應明確指出哪些行動是「他能掌握的槓桿點」，幫助他把正向詮釋連結到具體可行動項目。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4486, 'CSR_25', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「正向詮釋下的慢性焦慮」。他在認知上把挫折解讀為暫時且可逆轉，但對任何未知情境都有強烈的焦慮反應，兩種狀態同時存在而不相消——他說情況沒問題、說得出轉機，但只要有一點未解的模糊，就難以讓自己真的安定。外觀正向但行為上頻繁要求確認，或提前執行以消除模糊。管理上須特別留意他情緒訊號與言語表達的落差，不要只聽「沒問題」就略過他的實際焦慮狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4487, 'CSR_25', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「驅動力高漲的正向引擎」。他把挫折解讀為暫時可改善，同時對卓越表現有強烈企圖心——逆境不只不打垮他，反而成為他升級方法和提高標準的契機。他傾向在失敗後立刻找更好的做法，而非只是「撐過去」。這種高驅動在高挑戰任務中表現突出，但也需留意他在連續高壓下是否有足夠的恢復空間，避免以樂觀和企圖心掩蓋真實的疲勞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4489, 'CSR_25', 'A (高)', 'CSR_20', 'A', '與 CSR_20 (希望) A聯動：表現為「挫而不垮、能找到下一條路的持續推進者」。他對不如意的解釋偏向可改善、可轉機，不把單次失敗讀成全面否定；他也能把目標具體化並同步想好替代路徑，遇到阻礙時改道而非放棄。情緒復位和行動路徑調整在他身上幾乎同步發生：剛挫折完，他已經在想下一步怎麼走。他適合承接需要在不確定中長期推進、方法可能需要反覆調整的複雜任務；在他身上，受挫不是停頓訊號，而是換路的啟動點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4490, 'CSR_25', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「外表堅韌、底氣單薄」。他能很自然地把不如意說成暫時、可逆轉，這讓他顯得很有韌性；但支撐堅毅的三股內在資源——對所做之事的投入感、對局面的掌控感、把變動當成挑戰的開放度——其實都偏薄。關鍵不是正向語言『騙過了』誰，而是他自己也是這樣理解處境的：他真心相信會過去，只是這份相信底下沒有足夠的心理本錢撐很久。短期看他穩穩往前，連續或高強度逆境下卻可能突然退縮或崩掉，讓旁人措手不及。管理上不能只憑他的情緒自述判斷承受度，要在高壓任務中定期確認他實際的投入與餘力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4491, 'CSR_25', 'B (中)', 'CSR_12', 'A', '與 CSR_12 (目標效能感) A聯動：表現為「信心補位讓期待落地」。他的樂觀在多數時候能保持正向，但連續不順或高壓時會短暫消沉，而高度效能感在此時發揮了補位作用——即使情緒上的樂觀退潮，「我付出努力就能達到目標」的信念仍驅動著行動，使整體表現波動顯著縮小。這是兩者最佳化的情境依賴互補，但若逆境夠強、夠久，效能感也可能被侵蝕，管理上需在恢復視窗之前提供適時的正向回饋節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4492, 'CSR_25', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「恢復後主動再出擊」。他的樂觀在逆境時會短暫受壓，但當看見進展或獲得支持後能回穩——而他同時深信自己能影響結果，這讓情緒回升後幾乎立刻轉化為行動：他不會只是感覺好一點，而是馬上找到可出手的槓桿點。恢復期較短，重新投入節奏快；管理上應在情緒低谷期主動製造一個可以「感受到影響力」的小任務，加速觸發這個恢復迴圈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4493, 'CSR_25', 'B (中)', 'CSR_31', 'A', '與 CSR_31 (韌性) A聯動：表現為「雙重保護的穩定緩衝」。他的樂觀在高壓時會短暫消沉，但韌性高讓他即使情緒詮釋暫時失守，仍能快速從逆境中回到可工作狀態。他在恢復速度上表現強韌，在詮釋框架上則屬情境敏感型。他比單純依賴樂觀的人更能在高強度、高失敗率的環境中維持穩定輸出，是適合長期高壓任務的韌性型態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4494, 'CSR_25', 'B (中)', 'CSR_22', 'C', '與 CSR_22 (無法忍受不確定性) C聯動：表現為「短暫消沉後仍能從容等待」。他在連續不順時會有情緒低谷，但同時對模糊和未知有高度耐受，讓他的低谷品質顯著優於一般人——他只是暫時悲觀，不會同步陷入對不確定性的焦慮，兩種壓力源被清晰解耦。等待回升信號的過程比較從容，不會因前方不明確就急著做倉促決定。適合在方向仍待釐清的緩衝期擔任穩定的觀察者角色。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4495, 'CSR_25', 'B (中)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「沉入低谷時連結感也跟著斷」。他的樂觀在逆境時需要進展或支持才能恢復，而承諾感偏低意味著他對自身興趣和價值觀的認同不穩、融入感薄弱。他在低谷期缺少能把自己「拉回來」的意義燃料，恢復節點難以被一般的進展信號觸發，需要更強的外部支持或更直接的意義連結。管理上應在任務設計初期就確認他是否對目標有足夠的個人認同，而非等到他消沉時才處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4496, 'CSR_25', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「平穩期待的順勢行動者」。他多數時候能保持正向，在連續不順或高壓後會短暫消沉，看見進展才能恢復；成就動機上他傾向把工作完成在合理範圍，不主動追求突破。具體情境裡，他在有清楚回饋的環境最有動能，既不過度焦慮也不往上拚搏，走一步看一步。一旦環境支持減弱，正向感與投入度會一起下滑。管理上宜搭配定期進展可見的節點，讓他的期待感有所依靠，避免在目標模糊時陷入消極等待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4497, 'CSR_25', 'C (低)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「雙重退縮的行動空白」。傾向把不如意視為長期普遍，同時對自己能否完成目標缺乏把握。他既把不如意視為長期普遍而預期嘗試無效，又因低效能感而預期自己無法勝任，於是行動意願從兩個方向同時被抽空，陷入最難被外部推動打破的行動癱瘓。管理上需先切割任務到最小單位、消除第一步的不確定性，並主動提供成功的可查證小案例，才能讓這個組合有機會鬆動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4498, 'CSR_25', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「悲觀預期的主控行動者」。他傾向把不如意解讀為長期且普遍的困境，同時又持續相信自己能影響結果，必須主動採取行動。具體情境裡，他一邊悲觀預測情況只會更難，一邊仍在各類處境中主動介入、積極規劃，行為上看起來充滿能動性。這種模式讓他在高壓情境維持住動能，但也可能過度投入在難以控制的事情上，消耗自己。管理上宜幫他把可控範圍畫清楚，減少在預期失敗的區域過度用力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4499, 'CSR_25', 'C (低)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「韌性兜底的低谷爬升」。他傾向把挫折解讀為長期普遍，情緒上很難快速回到正向；但充沛的堅毅性——在承諾感、掌控感與面對挑戰的開放性三個面向都有穩固底氣——讓他即使持續悲觀也不容易真正崩潰。他不是因為想通了而繼續前進，而是靠著內在韌性資源維持運作。這種組合在長期高壓環境中比單純樂觀更可靠，但需留意他的悲觀詮釋可能讓外界難以評估他的真實狀態，定期主動確認。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4500, 'CSR_25', 'C (低)', 'CSR_20', 'C', '與 CSR_20 (希望) C聯動：表現為「出口封閉的雙重悲觀」。樂觀負責詮釋框架（挫折是暫時還是永久），希望負責行動路徑（知不知道怎麼走下一步），兩者都在低位意味著他既無法正向解讀挫折，也無法自行規劃下一步——認知和路徑雙線封閉。遇阻礙時快速停滯，不主動繞道，等待他人告訴他該怎麼辦。管理上應同時提供情緒重框架（協助辨別哪些挫折真的可以改善）與具體行動地圖（清楚的下一步），缺一不可。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4501, 'CSR_25', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動行動卻預設失敗」。他傾向把挫折解讀為長期普遍，但強烈的主動精神讓他仍然不斷自發發起行動、超越既定要求——主動精神推著他走，悲觀詮釋卻在情緒底層持續消耗意義感。外觀上是個極有行動力的人，內在卻在不斷問「這樣做有什麼意義」。長期下來行動的情緒報酬不斷打折，可能讓原本穩固的主動精神開始出現侵蝕。管理上應定期幫他建立「行動帶來改變」的可見連結，讓結果的可見性補充他所缺乏的正向詮釋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4502, 'CSR_25', 'C (低)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「悲觀易耗的低韌性者」。他傾向把不如意視為長期且普遍的困境，在長期高壓或連續變動下也容易出現能量耗竭，補救與恢復較吃力。壓力累積到一定程度時，他的行動力與正向預期會同步下滑，難以在短時間內自行回穩。管理上宜盡量縮短不確定期、拆細目標讓他有可見的小進展，同時在明顯耗損前主動介入支持，避免等他已經低谷再處理。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4503, 'CSR_25', 'C (低)', 'CSR_06', 'A', '與 CSR_06 (承諾) A聯動：表現為「意義感撐住悲觀底色」。他把挫折解讀為長期普遍，但對自身興趣與價值觀有穩固的認同感，不受逆境動搖——這份承諾感成為悲觀底色中讓他繼續在場的關鍵內在錨點。他不一定期待成功，但因為深度認同這件事而仍然留守。外觀上穩定、不輕言放棄，但行動的積極度和全力投入度受悲觀詮釋壓低，呈現「持續參與但力道偏保留」的模式。管理上可善用他的承諾感作為切入點，引導他在意義感穩固的基礎上逐步重建對挫折的彈性詮釋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4504, 'CSR_25', 'C (低)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「悲觀遇戒備的雙重收縮」。他傾向把挫折解讀為長期普遍，同時對他人高度警戒、預設意圖可能不利——悲觀封閉了他對未來的正向預期，低信任封閉了他從他人支持中獲得恢復能量的可能，兩條逆境中最常見的出路同時被切斷。需要幫助時既難以主動求助，即使有人主動提供協助，也可能因戒備而無法充分接受。管理上需先在安全、低風險的情境中建立真實可信的信任關係，再嘗試介入其悲觀詮釋；強迫給予正向鼓勵反而可能觸發更強的戒備反應。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4505, 'CSR_26', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「系統推進高標執行者」。他對工作有明確的企圖心，願意多投入以達到更高標準；同時他偏好把工作納入清楚的流程，靠分類和排程降低遺漏。在有清楚目標且資訊可追蹤的環境，他動能足且輸出可靠，推進力強。在分工模糊或結構混亂的情境，他一邊試圖整頓秩序、一邊還要自我要求成果品質，可能在兩個方向上各花力氣，讓整體節奏比預期重。管理上給他清楚的目標範疇和基本資訊架構，能讓他的高標追求最有效地轉化為可交付的成果。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4506, 'CSR_26', 'A (高)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「流程清楚但底線模糊」。他能把任務排得整齊、維持一致的工作節奏，但在規範與結果目標衝突時，傾向把規則視為可調整的工具而非硬性底線。外觀有序反而讓這種彈性更難被看見：稽核文件齊整，但灰色地帶的例外處理缺乏一致標準。管理上建議在程序設計階段明確鎖定哪些規則不可繞行，並定期核查例外記錄，而非只驗收交付物是否整齊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4507, 'CSR_26', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「條理外殼下的衝動決策」。在穩定狀態下，他的工作節奏有序、交付可預期；但在連續高壓或衝突情境下，衝動管理失守使程序直接被跳過，出現倉促決定或不當承諾。這種對比製造了一致性的假象：合作方基於平時的有序樣貌建立信任，卻在危機時刻遭遇與預期落差極大的行為。建議在高壓場景前確立不可跳過的關鍵查核點，並設置他人提醒機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4508, 'CSR_26', 'A (高)', 'CSR_33', 'A', '與 CSR_33 (自律性) A聯動：表現為「節奏穩定的長線執行者」。在他身上，喜歡把事情排成清楚流程、和能為了長遠目標忍住眼前的捷徑，其實是同一種傾向往兩個方向的延伸——他之所以受得了延遲滿足，部分正是因為流程讓他清楚看見每一步累積往哪裡去；而他之所以願意守著流程，也是因為他打從心裡認定偏離一次就破壞了長期的成果。對他來說，按計畫走不是一種克制，而是順理成章。實務上他在需要長時間、多環節持續推進的計畫型任務中特別突出；要留意的是這種人一旦鎖定路徑，偏離成本很高，因此更該在啟動前確認方向本身是對的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4509, 'CSR_26', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「以秩序對抗模糊的焦慮者」。他偏好清楚流程，又對不確定性高度敏感，於是程序對他而言從工作工具變成情緒穩定器——有流程時表現穩定可靠，缺乏流程或面對高度模糊任務時，焦慮會顯著壓制判斷力。管理上需留意：將他安置在流程成熟的場景最能發揮；若需要他應對新型任務或快速變化，建議提前協助他建立臨時框架，而非讓他在「無結構」中硬撐。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4510, 'CSR_26', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「守序但等待指令」。他能把被交辦的事做得整齊、紀錄清楚、交接不漏；但較少自發地去發現改善機會或超越任務邊界。這個組合在穩定且定義清晰的角色中表現可靠，但在需要人員自主優化流程的環境中，程序可能隨時間固化而失去適應彈性。建議定期提出改善邀請，並讓他知道流程更新本身也是他職責的一部分，而非額外要求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4511, 'CSR_26', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「按程序行事卻易起衝突」。他有清楚的流程偏好並願意維護，但面對不遵守程序的他人，傾向直接表達立場甚至對抗，而非用協商方式引導。這使得他在推行標準化流程時容易與風格不同的同事產生摩擦，程序本身正確，但推進方式激起阻力。建議在需要跨部門流程對齊的場景，額外配備具溝通協調功能的角色作為橋接，或引導他以詢問替代要求。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4512, 'CSR_26', 'B (中)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「整理重點但難耐反覆」。他在條件適合時能整理出清楚的工作框架，但這種條理本身有情境前提；他又對各類活動都容易迅速失去投入感，於是固定格式的例行紀錄、重複性核查最容易出現缺漏。他的條理品質跟任務的新鮮度呈正比：越單調的維護工作，紀錄越不一致。建議把例行紀錄自動化或由他人執行，讓他專注於需要框架設計的非例行任務。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4513, 'CSR_26', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「整理框架卻猶豫推進」。他能在多工環境中把重點整理清楚、建立基本的工作順序；但對自身能否完成目標缺乏把握，使整理好的框架停在計畫階段，執行時過度求證或等待他人確認才敢動。計畫的完整性遮蔽了推進的猶豫，合作方可能誤以為進度正常。建議在任務啟動時明確標示哪些決定他有自主權，並縮短確認環節，讓框架盡早轉為行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4514, 'CSR_26', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「有序分工卻責任外移」。他能把工作的重點和分工整理得相對清楚，在責任範圍明確時也有一定的執行條理；但一旦出現失誤或延誤，傾向把原因指向情境或他人，補救行動相對被動。條理性讓分工邊界看起來清晰，卻也成了責任切分的擋箭牌——邊界外的問題容易被歸類為「不是我的事」。管理上需明確要求跨界問題的通報與接手標準，避免縫隙問題被有序分工所遮蔽。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4515, 'CSR_26', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「條理撐不住的高壓崩序」。在壓力可控的日常裡，他能整理重點、維持基本工作框架；但堅毅性偏弱意味著面對困難或逆境時，內在緩衝資源有限，而他的條理性本身又有情境前提。他在壓力升高時整理能力最先瓦解，出現紀錄缺漏和任務掉球。管理上建議在預期高壓期提前協助他建立更精簡的核查清單，並增加支援資源，避免讓他獨立承受多重壓力源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4516, 'CSR_26', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「整理有方但動能不足」。他在任務開展時能整理出相對清楚的框架和基本秩序；但動機更受環境支持與要求牽動，較少主動追求突破，使整理好的計畫在推進中段容易失速，收尾完整度下降。條理性讓工作看起來有開始，但未必有終點。建議為他設計明確的收尾里程碑與外部追蹤機制，確保框架轉化為完整交付。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4517, 'CSR_26', 'B (中)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「條理自足卻難以協作」。他有能力把重點整理清楚，個人工作框架尚能維持；但對他人的高度警戒使他在需要共享流程、透明交接的協作場景中，傾向保留而非流通。這讓他的條理停留在個人邊界內，無法轉化為團隊共享的工作秩序。建議在協作流程中設置結構化交接模板，讓資訊共享從個人判斷轉為例行程序，降低他對共享的主觀顧慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4518, 'CSR_26', 'C (低)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「即興行事後患疊生」。他本就不靠固定流程工作，彈性隨性是主要操作模式；他又傾向先做再調整、評估在行動後才補，於是他啟動雖快，對隱性風險的防護卻極為薄弱。這不是偶發的失誤，而是模式性的遺漏積累：紀錄不足、假設未驗證、後果未評估，補救成本持續滾入。管理上建議在任務分配時明確要求最低查核程序，並設置強制的前置確認節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4519, 'CSR_26', 'C (低)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「守規卻少留憑據」。他高度重視承諾與規則邊界，傾向選擇可被交代的做法；但不靠固定流程工作、紀錄較少的習慣，使這種守規行為缺乏可追溯的文件痕跡。在需要稽核、合規驗證或交接的場景，他可能確實沒做錯，但難以舉證。管理上建議為他設置最小化的合規記錄模板，讓守規行為自動轉化為可查核的紀錄，而非依賴他自主系統化。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4520, 'CSR_26', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「遺漏加責任外移的管理風險」。他臨場作業、紀錄不足，細節容易遺漏；遇到失誤時又傾向歸因外部、補救被動，使問題不只出現，而且不被修正。條理性低讓問題難被提前看見，責任感低讓問題被發現後也難被妥善處理。管理上這是需要高度結構性干預的人：強制交接清單、明確失誤通報責任，以及定期查核而非事後追責。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4521, 'CSR_26', 'C (低)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「擁抱變化卻難以系統化」。他自然將變化視為常態，在環境快速調整時能開放應對、不需額外時間適應；但不靠固定流程工作的習慣，使他在高速變化中產生的解法和應對方式很少被系統化記錄下來。個人靈活性高，組織知識累積卻慢——他能輕鬆轉向，但留下的交接文件讓後繼者難以重現他的路徑。建議在高速迭代場景設置最小化的決策記錄機制，讓彈性應變也能沉澱為可重用的知識。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4522, 'CSR_26', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「計畫虛設、節奏散漫」。他不靠固定流程工作，又容易被短期誘惑牽動、難以為長期目標延遲滿足；沒有程序提供節奏錨點，短期拉扯就直接主導他的行為。長期計畫的落地率低，推進節奏對他人而言難以預測。他在需要持續自主執行的任務中風險最高，建議採取高頻度的外部節奏管理——週計畫、每日核查、里程碑確認——替代他缺位的內部自律機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4523, 'CSR_26', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱絡易接卻交接混亂」。他在各類人際情境都能自然展現信任與熱情，快速建立合作關係；但工作過程中的分工紀錄、溝通共識和交接文件往往依賴口頭約定而非系統整理。廣泛的人脈和良好的人際氣氛讓合作啟動輕鬆，但在團隊成員更換或長期追蹤時，口頭共識的缺口就會浮現。管理上建議在合作啟動時要求最低限度的書面確認，並設置固定的進度同步格式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4524, 'CSR_27', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「全力拼高標的卓越進取者」。他對品質的苛求與對更高成就的渴望同時在場——不只要完成，還要做到無瑕疵，還要超越既有標準。面對挑戰時，他會主動把目標和方法往上推，執行過程中反覆修整，很難在「夠好」停下來。在看得見成果且回饋清楚的環境，他的投入與輸出品質都能達到高峰；若任務缺乏清楚的完成邊界，可能陷入無止境的優化迴圈，管理上宜事先定義「達標即可推進」的標準，讓他的進取心在明確框架內高效運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4525, 'CSR_27', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「對瑕疵與模糊雙重敏感的執行者」。他對細節品質有高度要求，同時對任何不確定或模糊的情境也容易產生強烈的不安反應；當這兩種敏感同時觸發，他可能在確認細節與消除不確定性上花費大量精力，才敢往下推進。在環境穩定、資訊完整的場景，他的輸出品質往往高且可靠；一旦任務本身有固有的模糊性，可能出現決策卡頓或過度求證的情況。管理上宜預先提供盡量完整的資訊與清楚的範圍，並設定可接受的不確定範圍，幫助他在必要的不完整中也能推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4526, 'CSR_27', 'A (高)', 'CSR_26', 'A', '與 CSR_26 (條理性) A聯動：表現為「系統性精細執行者」。對細節的高要求和對流程秩序的偏好，在他身上是同一種傾向的兩種樣子：他在意每個細節對不對，也自然會把『怎麼確保每個細節都對』變成一套可以照著走的步驟，所以核查清單、分層確認、紀錄留痕對他不是額外負擔，而是他把高標準落實下來最舒服的方式。結果是他的品質把關帶有系統性的穩定，而不是隨情緒起伏的時好時壞——這是這組特質最理想的場景。代價是他的程序可能偏細，遇到需要臨場快速切換的情境，這套精密的流程本身會變成負擔。建議在高精度任務充分授權他建立流程，同時為高變動情境事先約定哪些步驟可以略過，避免流程在該快的時候反而卡住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4549, 'CSR_28', 'A (高)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「承擔不放棄但耗損累積快」。他對結果有強烈決心，不願推諉或放棄，但在長期高壓或連續逆境下，內在的恢復資源並不充裕；強烈的責任感讓他不肯停下，韌性薄弱卻讓他在持續負重後加速耗竭。他的風險在於最需要補救的時刻反而狀態最差。應主動監控其累積負荷，在高壓專案中安排明確的恢復節點，而非等他主動求援。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4527, 'CSR_27', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「等待觸發的品質精修者」。他有充分把細節做到位的能力與意願，但這份意願是『被指向了才會啟動』的——在沒有人交辦、沒有明確需求的情況下，他不太會自己去找事情做；而一旦被放進某項任務，他又會深陷在細節優化裡，難以在『夠好』時停下。對他而言，起點和終點都需要外部給：要有人推他才開始，要有人畫線他才結束。在分工明確、有截止壓力的環境，他的品質價值能穩定發揮；但若期待他主動發掘問題、自發超越範疇，這個動力組合就會顯得吃力。建議搭配定期的任務指派與清楚的交付時點，既用上他的品質強項，也補住主動性的缺口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4528, 'CSR_27', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「品質原則上的直接對峙者」。他對『東西要做到該有的水準』的在意，和他遇到分歧傾向直接表態、不愛迎合的性子，在品質議題上是合一的：當他認為某件事的品質不該被妥協，他既不會沉默也不會順著別人走，而是直接把不滿說出來、把決策擋下來，因為在他心裡，讓步品質就等於放棄一條不該退的原則，即使對方是上級也一樣。這在重視品質的環境能起到守門作用，但若他的表達一再升高為硬碰硬，會折損協作關係與信任。建議給他一條正式、可被接受的品質申訴管道，讓那股『不肯讓』的能量走向結構化的回饋，而不是反覆的對峙。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4529, 'CSR_27', 'A (高)', 'CSR_33', 'A', '與 CSR_33 (自律性) A聯動：表現為「長線精雕的自律完成者」。對他來說，『把結果做到無瑕』本身就定義了什麼叫值得完成的事，而為此放掉眼前『趕快交差』的舒服，他並不覺得是犧牲——『不到位就不放手』與『能熬住不抄捷徑』在他身上是同一種對長期正確的偏好。這讓他的高品質不是偶發，而是能撐過漫長優化週期的穩定模式，在需要長線、高精度的工作中是難得的優勢。代價是他對外部節奏的容忍度偏低：一旦時程要求他快速交付，那份『不達標不鬆手』會讓時程協商變得困難。建議事先談清楚品質下限與交付時間框，明確界定什麼情況允許做取捨。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4530, 'CSR_27', 'A (高)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「苛己不苛責的品質鑽研者」。他對自己手上的產出有很高的要求，會反覆優化把它做到漂亮；但這份高標準是朝向『我的東西要做好』，而不是朝向『這件事整體的結果由我扛』。所以當事情出了錯，他第一時間更傾向去找情境或他人的原因，而不是主動認領、補救、追到底——他會想著『下次要做得更好』，卻較少停在『這次是我沒做到、我來負責修』。結果是他能把細節精雕到位，卻在公開的失誤面前不容易第一時間站出來認責，品質追求與問責補救成了兩個分開的方向。在協作情境，建議明確區分『誰負責提升品質』與『誰是這個問題的擁有者』，避免他在打磨個人產出的同時，整體問題缺了承擔的人。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4531, 'CSR_27', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「品質彈性的穩定達標者」。在任務重要性清楚或有截止壓力時，他能提高品質標準做出取捨；但成就動機偏向「合理完成而非追求突破」，使品質投入多半停留在可用水準，而非主動升高。他整體表現穩定、不易出現重大失誤，但也缺乏主動追求更高品質或目標的內生驅力，需要外部明確的高標準期待才能啟動較高的品質投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4532, 'CSR_27', 'B (中)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「壓力下穩住品質的克制者」。他的品質投入具情境彈性，但他同時有穩定的情緒自制力，因此在任務壓力下也不輕易被情緒推著做出倉促的品質妥協——他的取捨是有意識的，而非慌亂之下的退讓。在快節奏、多變的工作環境中，這種穩定的品質判斷是難得的資產；一旦環境穩定，可進一步引導他識別哪些場景值得提高標準，培養主動升質的動機。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4533, 'CSR_27', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「逆境中品質先妥協者」。品質的投入原本就受情境驅動，在順暢環境下能做合理取捨；但堅毅資源薄弱，使逆境中的緩衝能力有限——壓力升高時，品質往往是最先被縮減的維度。在長期高壓或連續困難的情境，需要提供更多的外部支持與清楚的品質底線，防止細節失控在壓力期間累積成系統性問題。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4534, 'CSR_27', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動掌舵的品質取捨者」。在時間或資源受限時，他不被動等待別人定義品質底線，而是主動判斷哪些細節對結果影響最大並有意識地做取捨——掌控感賦予品質平衡更積極的形式。這使他在快節奏環境中能穩定推進而不失控，但也需留意過於自信的掌控傾向可能低估細節累積的長期風險；建議定期設立品質回顧節點，讓自我判斷與外部標準保持對齊。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4535, 'CSR_27', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「猶豫中的品質合格者」。他的品質投入本就視情境調節、彈性取捨；他又懷疑自己是否能達成目標，於是品質判斷難以果斷——「這樣夠好嗎」與「我能做到更好嗎」在他心裡反覆出現，消耗決策資源。輸出通常落在可用水準，但過程偏向過度求證或依賴他人確認，推進節奏受阻。建議提供清晰的品質驗收標準，讓他不需內部反覆拉鋸，也幫助他建立「品質判斷已足夠」的能力信心。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4536, 'CSR_27', 'B (中)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「穩態中的品質維持者」。品質投入在重要任務時能靈活取捨，他同時偏好穩定，於是他的品質判斷更依賴既有的基準框架——環境穩定時表現一致可靠，一旦外部要求快速調整品質期待或重新定義驗收標準，則較難適應。在可預測的重複性工作中是穩定的品質維持者，但若任務性質頻繁變化，需主動給予新的品質基準說明，而非假設他能自行校準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4537, 'CSR_27', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「彈性取捨規範的完成優先者」。他重視推進與交付，傾向把任務做到可用就先交出；面對規範與程序，他把這些視為工具而非界線，在目標壓力下可能選擇結果導向的做法而跳過部分要求。他在快速執行的場景效率突出，但在需要合規精準的環境容易留下小錯積累或規範疏漏。管理上宜預先明確哪些底線不能動，並在關鍵節點設置確認步驟，避免靈活態度在不該彈性的地方造成風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4550, 'CSR_28', 'A (高)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「認責但訊息不透明」。他對結果的承擔意願是真實的——出了問題不推諉、主動補救；但在溝通上傾向選擇性揭露、用話術包裝，使他的「負責」在外部感知上有透明度缺口。合作者可能感受到他「有在處理，但不清楚他在做什麼」，形成信任落差。對這類組合，要求定期公開進度更新與原因說明，能讓他的責任感轉化為可被驗證的信任資產。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4538, 'CSR_27', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮快交的矛盾推進者」。他身上有一個自相矛盾卻是同一根源的張力：對『還沒做完』的懸著狀態極度難受，逼著他想趕快把東西交出去把這件事關掉；可是他本來就不太在意細節品質，所以交出去之後，『這東西到底夠不夠好』又變成一個新的、無法確認的未知，再次把他拉回不安。於是他常陷入『慌忙做完、交出去、又後悔』的循環——交付不是因為他覺得做好了，而是因為他受不了沒做完的感覺。最有效的介入是在交付前替他立一個明確的品質最低門檻，把『達到這條線就可以交』取代『趕快交了再擔心』，讓那股不確定的焦慮有一個可以落地的標準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4539, 'CSR_27', 'C (低)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「衝刺優先的行動型推進者」。他傾向先做再調整，與完成優先的取向契合；他啟動快、推進快，事前評估和細節打磨都被視為可省略的步驟。在節奏快速且容錯空間較大的工作中這是效率優勢，但在複雜任務中，他事前規劃與事後品質確認雙重薄弱，容易留下結構性缺口或遺漏隱性風險。建議在重要任務前引入最低限度的評估檢查節點，以及交付後的固定品質回顧，補足他缺失的反思環節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4540, 'CSR_27', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「追求快速完成卻易感厭倦的執行者」。他對品質的自我要求停在「可用即可」，不會主動在細節層反覆打磨；同時對重複性的確認與修整工作極易感到厭倦，難以透過意志力長時間維持在同一任務的收尾環節。在需要創意啟動或初步產出的場景，他的動能往往充沛；但在要求精細品控或系統性確認的任務中，容易交出不夠完整的成果後就難以再回頭。管理上宜把細節收尾切成短時間的小段進行，或設計外部回饋機制，減少他在確認環節的厭倦累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4541, 'CSR_27', 'C (低)', 'CSR_14', 'B', '與 CSR_14 (公正性) B聯動：表現為「目標壓力下的品質邊界模糊者」。平時他把細節品質做到可用就停，對公平規則也大致守得住；但這兩條線在他身上都不是寫死的底線，而是會隨情境鬆動的判斷。一旦競爭變強或目標壓力上來，『先做到夠用就好』和『這次稍微擦個邊應該還好』會在同一個壓力下一起浮現——對他來說，高壓時把品質和規矩都調鬆，是同一種『以結果為先』的反應，而非兩件各自獨立的事。在低壓的日常裡這還算可控，但壓力一升高，品質門檻和行為邊界的可靠性會同時下滑。對這樣的人，需要在外部設好明確且會被執行的品質與行為底線，而不是寄望他在壓力下靠自律守住。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4542, 'CSR_27', 'C (低)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「低能量的被動完成者」。他做到可用就停，但這不是出於『務實地選擇速度』的從容——在希望、效能感、韌性、樂觀都偏薄弱的狀態下，『把這個做完』更像是他撐住自己、不被壓垮的最低限度，而不是積極推進後的滿足。對他而言，更高的品質意味著要再掏出他已經不太有的力氣，所以品質期待自然被壓低；遇到挫折或被要求提高時，他容易先預期失敗、然後縮回去。品質改進在他這裡是第一個被放掉的優先序，長期下來輸出水準還可能進一步下滑。對這樣的人，補充心理資源比直接要求他提高品質更有效；用一連串小幅而可見的進步，幫他重新把動能積回來。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4543, 'CSR_27', 'C (低)', 'CSR_34', 'C', '與 CSR_34 (誠懇) C聯動：表現為「包裝完成的目的執行者」。對他來說，一件事算不算完成，標準是『對方有沒有接受』而不是『實際上夠不夠好』——他既不太在意細節品質，又傾向把選擇性呈現、話術包裝當成達標的正當手段，這兩者其實是同一種『達到目的就行』的處事方式。所以當品質確實不足，他的第一選擇往往是調整呈現方式讓對方買單，而不是回頭把東西補強，因為『讓對方覺得夠好』在他眼中比『確保它真的夠好』更省力也更直接。短期看交付很順，但客觀的品質缺口在後期仍會浮現，並連帶折損信任。在需要透明驗收的協作裡，必須建立客觀的品質核查機制，不能只憑他自己的說法判斷輸出水準。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4544, 'CSR_28', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「守責不越界的完成者」。他對自己的工作結果有強烈的責任感，出了問題會主動承擔並找到原因補救，而不是推給情境或他人；同時他的動能受環境要求的牽引較深，在沒有明確指標或挑戰信號的情況下，傾向把事情做完在合理範圍，而非自發追求更高標準。具體情境裡，他常一邊把手邊任務踏實收尾，一邊等待外部的目標刺激才決定是否要多走一步。實務上他在交辦任務上可靠度高，是穩定的執行錨點；在需要自驅突破的場景，則需要清楚的挑戰框架來激發更高投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4545, 'CSR_28', 'A (高)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「承擔意願強但收尾吃力」。他遇到問題不會逃避、主動追根究柢，但把一件事從開始做到可靠收尾的自我監控與節奏維持，對他而言較為吃力——不是不做，而是容易出現拖延或細節遺漏。高責任感意味著他不會放棄，卻也意味著他可能反覆回頭補救。合作時宜設定明確里程碑與收尾查核點，讓他的承擔意願能有結構支撐而非僅靠意志力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4546, 'CSR_28', 'A (高)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動掌控到收尾者」。他對事情出了差錯不逃避、不歸因外部，同時相信自己有能力影響局面，這讓他在問題發生時能迅速切入承擔，並持續追蹤到問題真正收尾為止。具體情境裡，他常一邊扛下責任，一邊持續主動介入、監控進展，確認每個環節都在他可掌控的範圍內推進。實務上他在高難度任務或緊急情況中能成為強力的收尾者，但也可能因為掌控感強烈而較難放手給他人；管理上宜引導他在適當節點做責任分攤。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4547, 'CSR_28', 'A (高)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「守規又守責的可信任者」。他對自己的工作結果有強烈的問責意識，出了問題會主動承擔並追根究柢；同時他高度重視承諾與規則，在壓力下也傾向選擇可被信任、可被對外交代的做法，即使面對灰色地帶也不例外。具體情境裡，他常一邊積極補救問題，一邊確保補救方式都在規範邊界內，不會為了效率走捷徑。實務上他是組織中可靠性極高的錨點，適合負責高透明度要求的工作；需要快速靈活的場景中可能節奏較慢，宜搭配清楚授權範圍協助他加速。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4548, 'CSR_28', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「負責到底但等人提出才動」。他一旦知道問題在自己範圍內，絕對不逃避、主動補救；但主動發現問題、自發超越要求的傾向較低，傾向在被要求時才回應。他的責任感需要外部觸發點才能充分發揮——問題被指出後執行力強，但潛在問題若未被他人點出，可能停留在盲點較久。適合與有主動問題偵測機制的環境或夥伴搭配，以彌補早期預警的缺口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4551, 'CSR_28', 'A (高)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「事事承擔卻留不住」。他對手上的工作有強烈決心，出了問題不逃避、主動補救；但對所在環境的心理依戀較低，遇到逆境或核心需求未被滿足時，更傾向考慮離開而非繼續堅守。對組織而言，他在職期間是可靠的承擔者，但留任意願是獨立變數。若要讓責任感轉化為長期貢獻，需要同步關注他的核心需求是否被環境滿足。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4552, 'CSR_28', 'B (中)', 'CSR_07', 'A', '與 CSR_07 (法規遵從) A聯動：表現為「責任邊界清時順從配合」。當責任範圍明確時，他能穩定承擔並完成，且高度順從、不製造對抗，是環境中的配合型執行者；然而當分工模糊或權責不對等時，兩個特質都沒有提供主動釐清的驅力——責任感本已隨界線模糊而收縮，順從傾向更讓他不易挑戰現有安排。這類組合需要清晰的職責架構配套，讓可靠性有機會發揮，而非被結構缺失抵消。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4553, 'CSR_28', 'B (中)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「責任感隨界線調節加上手段取向」。他的責任承擔在分工清楚時是穩定的，但在目標壓力升高且責任邊界模糊時值得警惕：他的責任感一收縮，便留出「我不確定這是我的事」的緩衝空間，而他本就傾向看重手段，於是他在這個空間裡合理化結果導向的做法，同時迴避後續的歸責。在高壓績效情境中應保持明確責任歸屬記錄，並強化行為可追溯機制。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4554, 'CSR_28', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「邊界清才扛加上不確定放大焦慮」。他在責任清楚時能穩定承擔，但責任邊界模糊時本已受影響；他對模糊與未知又有強烈負面反應，使他在分工不清的狀態下同時面臨焦慮上升與責任感收縮。他在模糊情境下有雙重退縮的風險。環境需提供明確的責任框架與足夠快的資訊更新，才能讓他的承擔意願穩定展現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4555, 'CSR_28', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「邊界模糊時責任縮且看壞後果」。他的責任承擔在分工清楚時尚能穩定，但責任邊界不清時本已縮減；他同時把不如意視為持久且難以改變，於是在問題發生後他更難喚起「我能補救」的動能。他用悲觀的解釋去看待責任邊界模糊留下的緩衝空間，於是那空間在他眼中進一步擴大，形成情境不利時雙向退縮。管理上需提供清楚的責任框架和明確的可行步驟，讓他不需要自己評估「補得好嗎」就能開始行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4556, 'CSR_28', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「責任界線模糊加信心不足雙退」。他的責任承擔需要清楚的邊界支撐，而他的自我勝任感不足，意味著他在高風險或新任務面前常先懷疑自己能否做好。情境不確定時最為明顯：責任邊界一模糊，他便難以認定「這是我的事」，他又對自己的能力沒信心，難以啟動「我能做到」，於是在最需要主動承擔的時刻他卻最難行動。建議提供明確的責任範圍界定，並在任務初期給予能力確認，才能有效喚起他的承擔動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4557, 'CSR_28', 'B (中)', 'CSR_03', 'A', '與 CSR_03 (利他行為) A聯動：表現為「邊界內負責邊界外仍願意出手」。他的責任承擔在責任邊界清楚時穩定，邊界模糊時有所收縮；然而深度的利他傾向使他在邊界外仍傾向出手，不因個人成本而退縮。他在實際行為上比純粹的責任感剖面更主動，但這份主動來自利他而非責任認定——若日後被追究「為什麼做這件事」，可能出現歸因混淆。建議在合作中明確區分「責任內必做」與「利他額外出手」，以維持清楚的職責邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4558, 'CSR_28', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「衝勁強但迴避失誤責任」。他對成果有明確企圖心，願意主動升級目標和方法，遇到挑戰傾向衝在前面；同時遇到失誤或延誤，他較容易把成因歸向外部情境，補救動作相對被動，這讓問題的收尾速度往往落後於他衝刺時的節奏。具體情境裡，他常一邊積極推高目標、全力衝刺，一邊在事情出差錯時等待環境先給出解方，而非主動承擔並追根究柢。實務上他在激進衝刺型任務中能爆發強勁動能，但在問責文化要求高的場景易生張力；管理上宜明確定義每個衝刺段的個人問責邊界，協助他把衝勁和收尾責任連結在一起。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4559, 'CSR_28', 'C (低)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「外移歸因且缺少融入動能」。他遇到問題較容易歸因外部，補救動作相對被動；同時對自身在環境中的歸屬感與投入程度偏低，面對需要深度參與的情境傾向旁觀。他對問題既不主動承擔，也缺乏讓自己願意投入的內在連結——不是能力不足，而是責任意識與投入動能同時薄弱。管理上需從建立個人意義感切入，先讓他感受到在乎，責任感才有機會被喚起。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4560, 'CSR_28', 'C (低)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「歸因外部且缺乏掌控意願」。在他身上，「這不是我的問題」和「反正我也改變不了什麼」其實是同一種心境的兩種說法——對一個本來就不覺得自己能影響事態的人而言，把問題推到外面不是策略，而是順理成章：既然使不上力，那當然也輪不到他來扛。所以失誤或延誤發生後，他既不會從自己這邊找補救的起手式，也不會生出「我來試試看」的念頭，而是安靜地等事情自己有個結果。這類人在高度問責的情境中風險明顯，但問題的核心不是不負責，而是「我做了也沒用」的無力底色。要鬆動它，得先用小範圍、效果看得見的任務讓他親身體驗「我的動作真的改變了什麼」，等這份掌控感長出來，再逐步把責任期待往上加。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4561, 'CSR_28', 'C (低)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「衝動行動加卸責後補」。他傾向先做再調整，行動前的評估較薄弱；而遇到失誤後卻較容易把原因歸給情境或他人，補救動作相對被動。他常先行動製造缺口，又把缺口的原因外移，使這些缺口難以變成個人的學習信號。在快速迭代環境中，他若缺乏外部結構化的問責回饋，成長速度容易停滯。建議建立事後反思機制，並要求他明確寫出「我的哪個決定造成了這個結果」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4562, 'CSR_28', 'C (低)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「歸責外移加壓力資源耗盡」。他遇到失誤或延誤較容易歸因外部，補救動作相對被動；堅毅性薄弱意味著面對困難的內在緩衝資源有限，韌性在逆境升高後明顯下降。堅毅性由承諾、控制、挑戰三種內在資源組成，而他三個面向同樣薄弱，等於在最艱難的時刻連結構性支柱都缺位。他在高壓情境下風險最高：既難自主啟動補救，又難撐住持續推進。應安排明確的支持系統與問責夥伴，避免讓他獨自面對高風險逆境。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4563, 'CSR_28', 'C (低)', 'CSR_19', 'C', '與 CSR_19 (誠實謙遜) C聯動：表現為「外移歸因且原則自我要求弱」。他遇到失誤較容易把責任歸給外部，補救動作相對被動；同時對公平對待他人、誠懇與不佔便宜的自我要求較弱，在利益壓力下可能合理化對自己有利的詮釋。在問題發生後他的表現最為明顯：他不主動承擔，且在說明時傾向呈現對自身有利的版本。這類組合在高問責情境中對團隊信任的侵蝕風險較高，需要明確的事實記錄機制與獨立驗證管道。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4564, 'CSR_28', 'C (低)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「歸責外部且需要被看見」。他遇到失誤較容易歸因情境或他人，補救動作被動；同時把被看見與被正面認可視為重要需求，強調自身貢獻、對他人表現的接受度較敏感。在問題發生時他的反應最為明顯：他用外部歸因保護形象，又因看重被看見而更難公開承認缺失——他在「說是自己的錯」與「維持被正面看見」之間感到張力，於是傾向規避公開問責。建議建立私下反思與問責機制，降低在人際場合公開承認錯誤的心理成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4565, 'CSR_28', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「即時回報優先加責任外移」。他明知長期目標重要，仍容易在當下選擇立即回報；遇到失誤後又傾向歸因外部，補救動作相對被動。他既難維持長期目標的執行節奏，也難從失誤中提取個人學習——出了問題覺得「是環境的事」，而不是自己行動的後果。長期而言，他的成長速度容易停滯，需要外部設計清晰的短期里程碑連結長期目標，同時建立行為追溯機制讓他感受到個人行動與結果之間的連結。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4566, 'CSR_28', 'C (低)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「不承擔也不信任」。他遇到失誤較容易歸因外部，補救動作相對被動；同時對他人的信任度偏低，互動中多保留與警戒，傾向預設對方意圖可能不利。問題發生後，他既不主動從自身啟動補救，也難借助他人的資源和合作；責任外移關閉了自啟動入口，高度警戒關閉了外力借用管道，形成在問題後最孤立且被動的狀態。管理上需要降低問責情境的威脅感（避免讓他感到被指控），才能打開補救對話的空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4567, 'CSR_29', 'A (高)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「自我驅動的高標追求者」。他自己動手開始，也想把結果做得更好——他不會先「啟動」再「拔高標準」，而是在看一件事的當下就已經把「值得做」和「能做到更好」一起讀進去。沒有人交代，他也會自問還能推進到哪裡，並把那個更高的版本當成自己理所當然要達到的目標。他在開放、缺乏既定要求的場景特別有產出，但也容易把目標訂在超過時程或資源能承受的位置；管理上重點是定期和他一起對齊優先序與邊界，而非催他投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4568, 'CSR_29', 'A (高)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「自發衝刺、節奏易散的推進者」。他在各類情境下都能自發開啟行動、超越既定要求，旁人還在等指示時他已自行推進；遇到挑戰不需外部催促，主動精神不依賴環境支持。做事過程中，他不太靠固定節奏維持可靠輸出，自我監控與收尾管理相對吃力，容易在衝刺後出現細節遺漏或延遲收口。具體情境裡，他常是第一個舉手接任務、也是最容易在最後一哩路掉速的人；管理上宜在任務中段設確認點，幫助他把主動的衝勁轉成完整交付。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4569, 'CSR_29', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「快速出手、事後補評的行動者」。他在各類情境下都能自發開啟行動，缺乏明確指示或支持也不影響投入，主動精神穩定且充沛。面對決策，他傾向先做再調整，評估常在行動後補上，行動前對風險的審視較薄，容易在快速節奏下忽略隱性問題。具體情境裡，他常常是第一個推進的人，衝刺力強，但也較常需要在事後修正方向或處理返工；管理上宜在他自發啟動後加入短暫的檢核點，確保主動性能轉換成有品質的輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4570, 'CSR_29', 'A (高)', 'CSR_12', 'A', '與 CSR_12 (目標效能感) A聯動：表現為「充滿信心的全力推進者」。這個人身上幾乎找不到「不能開始」的理由——他既有自己先動的傾向，又深信只要投入就能把目標達成，在他內在這是同一種底氣，而不是先有信心才行動或先行動才生信心。面對模糊或全新的任務，別人還在等指令、等確認方向，他已經自己拆解並往前推了。因此他在需要開拓、無前例可循的場景格外突出；相對的風險是，當資源其實不足或方向其實錯了，他那股「一定做得成」的篤定會讓他遲遲不肯踩煞車。管理上要替他保留check point來檢視方向與資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4571, 'CSR_29', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「積極出發、逆境易損的行動者」。他在各類情境下都能自發開啟行動、超越既定要求，不依賴外部驅動或明確支持；起頭的主動性十分穩定。面對持續逆境或高強度壓力，他緩衝負面影響的內在資源有限，動能會在拉鋸中明顯消耗，且恢復比發起慢很多。具體情境裡，他在任務初期表現積極，但長期高壓任務可能出現後繼力不足的情形；管理上宜在壓力累積前主動介入，確保他的主動精神不因資源耗竭而提早熄火。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4572, 'CSR_29', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「持續出擊、高度焦慮的主動者」。他在各類情境都能自發開啟行動並超越要求，主動精神不依賴外部指示或確定環境，投入意願十分穩定。面對模糊或資訊不足的情境，他同時對不確定性產生強烈負面反應，對未知的容忍度極低，焦慮感在多數模糊處境中持續出現。具體情境裡，他常主動衝進不明確的任務，一邊推進一邊產生大量焦慮，可能用高密度的行動填補不安感；管理上宜盡早提供方向與里程碑，幫助他把主動性導向可驗證的成果而非焦慮驅動的過度投入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4573, 'CSR_29', 'A (高)', 'CSR_28', 'A', '與 CSR_28 (個人責任感) A聯動：表現為「超範圍行動且主動扛責者」。對這個人來說，「主動做更多」和「我來扛後果」本就是一回事——他自發開啟的每件事，他都當成自己全程要負責到底的事，所以不存在「先衝再說、出事再推」的縫隙。他不必別人授權就會去識別範圍外的機會，也不必別人施壓就會在出問題時主動補救、追到底。這讓他在無人監督或權責邊界模糊的崗位特別可靠，是高自主位置的強組合。要留意的是，他這份「自己開的事自己全攬」的傾向，也會延伸到本不該由他扛的範圍，需要定期和他談清楚授權邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4597, 'CSR_30', 'B (中)', 'CSR_08', 'C', '與 CSR_08 (盡責) C聯動：表現為「可激發卻收尾失守」。他的心理資本在支持與進展下能被激發，整體態度正向；但盡責薄弱讓他自我監控與維持節奏較吃力，容易出現拖延和收尾不足。他有「想做」的意願基礎，卻在「做完」的可靠性上不穩，在長週期任務中容易高開低走。建議把大任務拆成有明確截點的小段，借助外部節奏補足盡責的內部調節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4574, 'CSR_29', 'A (高)', 'CSR_06', 'C', '與 CSR_06 (承諾) C聯動：表現為「主動出手、融入感低的行動者」。他在各類情境都能自發開啟行動、超越既定要求，方向模糊或缺乏支持也不阻礙他啟動，主動精神穩定且持續。同時，他對自身興趣與價值觀的認同感較弱，面對需要深度融入的情境傾向保持旁觀，歸屬感與投入程度偏低。具體情境裡，他會主動推進任務，卻可能只停留在行動層面，對團隊或組織的深度參與感有限；管理上宜協助他找到任務與自身價值的連結點，讓主動性能累積成真正的投入而非單純的行動輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4575, 'CSR_29', 'A (高)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「主動出擊、對人保持警戒的行動者」。他在各類情境下都能自發開啟行動並超越要求，不依賴外部驅動也能維持穩定的主動精神。在人際互動層面，他對他人的信任度偏低，傾向預設對方意圖可能不利，互動中保留與警戒明顯。具體情境裡，他在個人執行上積極主動、貢獻超出基本範圍，但在需要開放協作或依賴他人的情境中容易拉出距離，合作推進速度受警戒感影響；管理上宜讓他先在可驗證的合作中累積信任，再擴大協作範圍。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4576, 'CSR_29', 'B (中)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「選擇性主動、不追求超標的投入者」。他在察覺機會或需求時傾向自發投入，但若方向不明確或回饋不足，會先評估實際效益再決定是否超越既有範圍。做事時他傾向把工作完成在合理範圍，不主動追求更高難度或額外突破，動機更受環境支持與要求的力道牽動。具體情境裡，他在有明確需求時會啟動主動性，但不會為了超越本身而拉高標準；管理上宜提供清楚的目標與回饋，幫助他把選擇性主動的動能落在最有效益的地方。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4577, 'CSR_29', 'B (中)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「評估後主動、持續相信能影響的行動者」。他在各類情境都持續相信自身能影響結果，掌控感穩定，主動採取行動的傾向不因環境可控程度降低而消失。察覺到機會或需求時傾向自發投入，但若方向不明或回饋不足，會先評估投入的實際效益再決定是否超越既有範圍，行動強度因評估結果而調整。具體情境裡，他在感受到能施力的地方會積極推進，評估清楚後執行力強；管理上宜確保他能看見行動與結果的連結，讓他的掌控信念轉化成持續且聚焦的主動輸出。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4578, 'CSR_29', 'B (中)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「選擇性主動、遇阻容易停下的行動者」。他察覺機會或需求時傾向自發投入，但在方向不明或回饋不足時會先評估效益，不會無條件超越既有範圍。面對不如意，他傾向把挫折解讀為長期且普遍的問題，抗挫力相對薄弱，遇到阻礙容易降低嘗試意願。具體情境裡，順境時的主動性表現穩定，但在遭遇困難後動能容易快速下滑，難以靠自身把不順視為暫時；管理上宜在他遇阻時提供具體的進展訊號，幫助他重拾評估後主動的能力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4579, 'CSR_29', 'B (中)', 'CSR_32', 'C', '與 CSR_32 (自我勝任感) C聯動：表現為「條件性主動、信心不足的評估者」。他察覺機會或需求時傾向自發投入，會先評估投入的實際效益再決定是否超越既有範圍；這個評估機制在他信心不足時更容易給出保守結論。他對自身能否做好缺乏穩定的把握，遇到不確定任務容易遲疑或轉向尋求他人決定。具體情境裡，在任務明確且安全感足夠時能主動推進，一旦環境模糊或任務要求升高，信心與主動性會同步下降；管理上宜先讓他在可控的範圍內建立成功經驗，再逐步擴大他願意主動介入的邊界。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4580, 'CSR_29', 'B (中)', 'CSR_05', 'A', '與 CSR_05 (挑戰) A聯動：表現為「選擇性主動、視變化為常態的推進者」。他在察覺機會或需求時傾向自發投入，若方向不明確或回饋不足，會先評估投入效益再決定是否超越範圍。在高度不確定與頻繁變動的環境中，他能自然將變化視為常態，不需要額外調適就能保持開放，環境的不穩定本身不是他考量是否主動的阻力。具體情境裡，他在變動頻繁的環境中仍維持選擇性主動的節奏，能從變化中找到啟動點；管理上宜幫助他在高變動情境中設定評估節點，讓他的主動評估邏輯能在快速流動的環境中持續運作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4581, 'CSR_29', 'B (中)', 'CSR_20', 'C', '與 CSR_20 (希望) C聯動：表現為「有限主動、路徑規劃不足的行動者」。他察覺到機會或需求時傾向自發投入，但若方向不明確或回饋不足，會先評估實際效益再決定是否超越既有範圍。他可能有想達成的目標，但較難把動機與策略化路徑連結，遇到阻礙容易停滯或轉向，重新對齊後才能再推進。具體情境裡，他的主動性在初期能啟動，但遭遇卡點時難以自行開出新路，持續主動的能力因路徑思考不足而受限；管理上宜在他遭遇阻礙時提供路徑引導，幫助他把啟動的主動性轉化成可持續的行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4582, 'CSR_29', 'C (低)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「被動等待、達標即止的低動能者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。他做事傾向完成在合理範圍，不主動追求更高難度或額外突破，動機更受外在環境支持與明確要求的力道牽動。具體情境裡，他在清楚指示下能穩定交付，但鮮少在沒人推動的情況下自發超越；管理上宜設定清楚的期望邊界與具體回饋，並適時給予任務挑戰，讓動能有機會往上移動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4583, 'CSR_29', 'C (低)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「被動因應、掌控信念低的靜待者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。面對事態變化，他也較少相信自己能產生影響，傾向被動等待結果而非主動採取行動，改變局面的意願和信念都偏低。具體情境裡，他在有清楚指示時能配合完成，但在局面需要主動介入時容易觀望；管理上宜提供明確的行動範圍與可見的影響回饋，幫助他建立行動與結果連結的信念。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4584, 'CSR_29', 'C (低)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「謹守規範、被動回應的盡責者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。他高度重視承諾、規則與責任邊界，遇到灰色地帶也傾向選擇可被交代、可被信任的做法，對規範的遵守十分穩定。具體情境裡，在被明確交付的任務範圍內他表現可靠且值得信任，但在沒有明確指示的地帶很少自發延伸；管理上宜把期待明確化，讓他的規範堅守和需要主動投入的情境能夠對接。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4585, 'CSR_29', 'C (低)', 'CSR_15', 'C', '與 CSR_15 (遵循指示) C聯動：表現為「被動執行、質疑指示的觀望者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。面對既有指示與規定，他配合度偏低，傾向質疑或挑戰而非直接遵從，觀望與評估期在行動前占據較長時間。具體情境裡，他在被推動前較少動，被推動後又可能先質疑指示的合理性，啟動行動需要更多溝通成本；管理上宜說明指示背後的理由，減少質疑期並幫助他找到願意配合且能行動的切入點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4586, 'CSR_29', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「被動回應、責任外移的靜默者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。遇到失誤或延誤，他較容易歸因外部，補救動作相對被動，主動承擔與追根究柢的意願偏低。具體情境裡，在沒有推力的情況下他很少自發延伸；出現問題後也傾向等待別人介入而非主動補救，學習與改進速度因此受限；管理上宜建立清楚的責任歸屬機制，並在問題出現時主動引導他進入解決流程。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4587, 'CSR_29', 'C (低)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「被動靜待、正向資源匱乏的低動能者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。他所能調用的希望、效能感、韌性與樂觀傾向相對有限，遇到挑戰時動能明顯下降，對未來期待感薄弱，難以靠內在資源重新激發行動意願。具體情境裡，他在穩定、有清楚指示的環境中能基本配合，但一旦遇到阻礙或壓力，動能與主動性都快速消退；管理上宜提供持續的支持與小型成功經驗，協助他逐步累積內在正向資源。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4588, 'CSR_29', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「被動靜候、易感厭倦的低啟動者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。他在各類情境下容易迅速失去投入感，厭倦與無聊的體驗頻繁出現，難以透過外部刺激長時間維持興趣，即便有外在推動也難以持續深投。具體情境裡，他在沒有新刺激時動能衰退快，被要求才動、動了又快膩，是持續執行力最難維持的組合；管理上宜設計短週期的任務切換與明確的進展節點，減少他在單一重複任務上的厭倦累積。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4589, 'CSR_29', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「被動回應、短期拉扯的低自啟動者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。他對短期誘惑的抵抗力有限，明知長期目標重要仍可能在當下選擇立即回報，自律維持相對吃力。具體情境裡，在沒有外部推力的情況下，他既不容易自發啟動，也不容易在啟動後維持節奏；管理上宜增加外部結構與短期確認機制，減少他在誘惑與延宕中消耗的行動能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4590, 'CSR_29', 'C (低)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「被動等待、低度依附的邊緣行動者」。他較少主動發起行動或超越既定要求，傾向在被要求時才回應，行動範圍多半停留在基本需求之內。他對所在環境的心理依戀與承諾感偏低，面對逆境或不利條件時傾向考慮離開而非堅守，共進退的意願薄弱。具體情境裡，他在環境穩定時能基本配合，但在組織遇到壓力或不利階段，他既不主動貢獻也不容易堅持留下；管理上宜盡早建立他與工作或團隊的具體連結點，降低他在逆境時的流失風險。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4591, 'CSR_30', 'A (高)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「有資本卻無企圖心」。他具備充沛的心理資源——遇到阻礙能維持信心與動能、不輕易被挫折擊垮——但成就動機偏低，傾向在合理範圍完成工作而不追求額外突破。心理資本是能力工具，但沒有企圖心的驅動，這份工具很少被主動調用到更高標準。在需要主動突破的角色中，他的潛力容易低於實際資源水位。建議搭配明確的高期待信號與回饋，激活他的心理資本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4592, 'CSR_30', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「充沛信念卻覺得無從影響」。他的希望感、韌性與樂觀傾向讓他面對挑戰時不崩潰，但自控力偏低——較少相信自己能影響結果，面對變化傾向被動等待。這組合下，心理資本成為「情緒緩衝器」而非「行動啟動器」：他能撐住，但不去影響。在需要主動介入的任務情境中，需要搭配明確的行動框架幫助他把正向心態轉化為有效行動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4593, 'CSR_30', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「資本充沛卻持續焦慮」。心理資本讓他在理性層面保有效能感與樂觀，相信挑戰可以克服；但對不確定性的極度敏感與持續焦慮同時存在，面對模糊情境時情緒反應強烈且不因正向態度消退。兩種機制並行：效能感說「做得到」，焦慮說「但還不知道會怎樣」。他不容易崩潰，但在不確定環境中仍有明顯的過度確認行為，管理建議應聚焦在減少環境模糊度，而非只依賴他的心理資本自我調節。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4594, 'CSR_30', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「順境飽滿逆境見底」。心理資本與堅毅性其實是同一片正向心理資源的兩種說法——都在講一個人面對逆境時可動用的內在緩衝。當這個人在心理資本上顯得充沛、在堅毅性（承諾、掌控信念、把變化視為機會）上卻偏低，最忠實的讀法不是『一層撐另一層』，而是：他的正向與信心在日常挑戰裡是真實可見的，但一旦壓力拉到夠久夠重、需要靠深層的承諾感與掌控信念硬扛時，這份底氣就見了底。換句話說，他的充沛多半是在順境與一般難度下成立的，沒有經過嚴峻逆境真正壓測過。在安排長期高壓或反覆受挫的任務前，應留意他的表面信心可能比實際的耐受深度厚。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4595, 'CSR_30', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「有資本不主動出擊」。他面對挑戰有信心、面對挫折不輕易放棄——心理資本充沛；但主動精神薄弱，傾向等待指示才行動，不主動超越既有範圍。充沛的心理資源是潛力工具，卻缺乏自發啟動的動力，結果是潛力只在被明確要求時才被調用，平時處於待機狀態。在需要自驅力的崗位，他的優勢難以自然展現，建議搭配清晰期望與主動行動的具體邀請，才能釋放其真實能量。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4596, 'CSR_30', 'B (中)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「激發時投入卻快速失去新鮮感」。他的心理資本在有支持與進展時能被激發、動能回升；但極高的厭倦傾向讓投入感難以持續，各類活動形式都容易迅速失去吸引力。激發-消退的循環週期短，對管理者而言意味著需要持續提供新鮮刺激才能維持他的狀態，而非一次性介入就能穩定。這是情境敏感狀態，任務設計應盡量保持高變化性與可見的短期回饋節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4598, 'CSR_30', 'C (低)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「動能耗盡無從驅動」。心理資本薄弱讓他整體較易感到無力，面對挫折動能明顯下降；成就動機同樣低落，不主動追求更高難度或超越基本範圍。他既因心理資本薄弱而情緒資源不足，又因成就動機低落而即使資源短暫回升也不把它導向更高標準，於是「剛好達標」成為他高度穩定的終點。在需要主動突破的任務中，這個組合產生的阻力比任一單獨更大，建議先聚焦在建立基本動能與短期可見成功，再逐步討論更高期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4599, 'CSR_30', 'C (低)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「無力感加上掌控缺失」。心理資本薄弱讓他較易感到無力與悲觀；自控力薄弱讓他較少相信自己能影響事態，傾向被動等待結果。他在情緒上感到無力，又抱著「我影響不了」的信念，於是被動等待成為他最穩定的應對模式。在這個組合下，環境的正向轉機也難以自發把握，管理介入需要同時提供情緒支持與明確、小範圍的可掌控行動機會，才能開始鬆動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4600, 'CSR_30', 'C (低)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「無力與卸責互相鞏固」。心理資本薄弱讓他較易感到無力，挫折後動能明顯下降；個人責任感薄弱讓他遇到失誤時傾向歸因外部，補救動作被動。前者削弱了主動承擔的情緒資源，後者把這份削弱合理化成「本來就不是我的事」——兩者閉合讓問題改進的動能接近最低。在持續出現失誤的情境中，這個組合可能阻礙學習與調整，需要外部建立清晰的責任邊界與可見的補救機制，才能創造改進條件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4601, 'CSR_30', 'C (低)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「悲觀又戒備的封閉狀態」。心理資本薄弱讓他整體較易感到無力與悲觀，需要外部支持來回穩；但信任同樣薄弱，互動中較多保留與警戒，預設他人意圖可能不利。這個組合製造了一個困境：內部資源不足，外部支持的通道也被信任壁壘阻擋。支持介入的效果比預期差，因為他難以開放地接受協助。建議先在低風險情境中積累信任基礎，再逐步推進更深入的支持介入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4602, 'CSR_30', 'C (低)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「兩層正向資源同時塌陷」。心理資本薄弱讓他整體較易感到無力與悲觀；堅毅性薄弱讓他面對困難的內在緩衝資源有限，承諾感、掌控信念、接受挑戰的意願都偏低。心理資本提供情緒動能，堅毅性提供逆境中的結構性緩衝，兩者相鄰但不互補——同時薄弱代表在高壓情境中可動用的資源接近清零。這是需要優先關注的高風險組合，不應依賴其自行恢復，建議主動介入並考慮降低環境壓力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4603, 'CSR_31', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「快速恢復但長期悲觀的矛盾者」。他在挫折後能迅速回穩、把打擊轉成補救行動；但他對整體走向的解讀仍偏悲觀，傾向把不如意理解為長期持續而非暫時，短期恢復力與長期信心之間存在落差。具體情境裡，他在事情出錯後行動力往往比預期快，但同時對後續期待較低，平靜期可能反而保守。管理上宜把他的回彈動作轉化為可見的進展記錄，讓他有具體依據修正對長期走向的悲觀預設。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4604, 'CSR_31', 'A (高)', 'CSR_12', 'A', '與 CSR_12 (目標效能感) A聯動：表現為「高信心快速反彈者」。對他而言，從打擊中站起來和相信自己能把問題解決，根本是同一回事——他不會先平復情緒、再去想辦法，而是因為深信『努力換得到結果』，所以打擊對他更像一道待拆的題目而非一場需要消化的傷。逆境因此不太能讓他停住，反而會把他啟動。他在高壓、快節奏的任務裡特別頂用：遇到障礙幾乎不卡，能自己找到方向往前推，不太需要外部反覆打氣。適合放在需要邊承壓邊突圍的主力位置。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4605, 'CSR_31', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「表面快復原、內部資源薄」。他在單次壓力事件後確實能快速回穩並展開補救，但堅毅性的三個核心資源——對價值觀的全心融入、相信自己能影響結果的掌控感、以及把變化視為常態的開放性——都相對薄弱，意味著每次快速復原都消耗了更少的內部儲備。連續逆境或壓力堆疊時，短期表現穩健、中長期卻可能更快透支。建議在高壓任務間提供恢復空間，並留意他「持續看起來沒事」背後可能積累的耗損。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4606, 'CSR_31', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「快速反彈但帶著衝動尾巴」。這個人遇到失敗或衝突會很快重新出發，這份行動力是真的；但他本來就容易被當下情緒推著走，於是他的『快』和他的『急』其實是同一股勁——那個讓他迅速重啟的衝勁，也讓他的第一個補救動作常常在情緒還沒退潮時就出手。結果是倉促的承諾、過頭的反應或粗糙的決定，事後得再回頭收拾。他的復原優勢因此被自己製造的二次問題抵掉一部分，整體節奏是『起步很快、來回很多』。高壓情境後建議替他預留一小段緩衝，讓他在動手前先確認自己是不是還在氣頭上。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4607, 'CSR_31', 'A (高)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主動掌控的逆境翻轉者」。對他來說，從壓力中回穩這件事和『我能影響事情怎麼發展』的信念是綁在一起的——正因為他不認為自己只能被動承受，逆境對他而言一開始就是一個『我可以介入的局面』，而不是一個需要先熬過去的狀態。所以他的復原從來不只是心情平復，而是直接表現為去找可以下手的槓桿點並採取行動。這種人在需要快速修正航道的任務裡特別有價值：遇到阻礙幾乎不會停下來等待，而是立刻鎖定下一個自己能掌控的動作。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4608, 'CSR_31', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「快速反彈但易失去耐力者」。他在遭受打擊後能很快回穩並展開補救行動；但他對各類活動都容易迅速失去投入感，在補救告一段落、任務進入平穩執行期後，興趣與動能往往難以維持。具體情境裡，他的逆境恢復期往往是能量最高的時候，但後段的持續執行需要刻意驅動才不鬆散。管理上宜在他恢復後的能量高峰設計有挑戰性的下一步，而非讓他進入重複維持模式，以免投入感快速下滑。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4609, 'CSR_31', 'A (高)', 'CSR_36', 'C', '與 CSR_36 (職場忠誠度) C聯動：表現為「逆境能回彈但依附感薄弱者」。他在壓力或失敗後有快速恢復的能力，能把打擊轉成補救行動繼續往前；但他對所處環境的心理依附本就偏低，逆境過後留下來繼續投入的動力並非理所當然。具體情境裡，他在恢復期表現穩定，但若環境持續不利且沒有改善訊號，他評估離開的時間點會比預期早。管理上宜在他回彈後給予明確正向回饋，讓他感受到繼續投入有意義，而非只看他是否還在做事。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4610, 'CSR_31', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「快速行動卻焦慮不止」。他在逆境後能迅速行動補救，展現出高復原速度；但對不確定性的強烈敏感使他在行動的同時，對尚未澄清的部分持續焦慮——行為層面看起來沒問題，內在層面卻處於高警戒狀態。長期下來這種「邊動邊焦慮」的組合本身就是一種持續耗損。建議在快速行動後優先釐清還有哪些未知是可以確定的，給他足夠的資訊閉合，讓焦慮有收斂的出口而非無限循環。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4611, 'CSR_31', 'B (中)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「壓力後搖擺、信心也不夠」。受到壓力時他本就會有明顯影響、需要支持與方向才能回穩，而同時對自身能否達成目標缺乏把握，復原過程多了一層「我真的做得到嗎？」的自我懷疑。他的修復週期較長，且對外部引導的依賴更高——沒有明確支持時可能同時停在情緒未穩與方向未明兩個困境。當情境較順時能逐步回穩，但高壓連發時需要主管提供具體的步驟確認與肯定，才能打破這個雙重搖擺。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4612, 'CSR_31', 'B (中)', 'CSR_25', 'A', '與 CSR_25 (樂觀) A聯動：表現為「挫折後轉彎、看得到出路」。壓力或失敗後他確實會有明顯影響並需要時間才能回穩，但他把不如意視為暫時且可改善，恢復期的等待不至於滑入無望感——他知道需要時間，同時相信事情可以改變。他的情境敏感型韌性有較好的復原底色，只要外部條件稍有轉機就能接上。適合搭配定期的進展確認，讓樂觀解釋有具體事實落點，加快他從「影響中」回到「行動中」的節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4613, 'CSR_31', 'B (中)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「壓力後靠不住、掌控感也低」。他的韌性本就需要支持與方向才能逐步發揮，而他同時對自身能影響事態缺乏信念、傾向被動等待結果。逆境期間他的修復格外被動——既沒有自發的干預行動，也沒有能加速復原的掌控感。在環境條件不明朗時，他可能卡在一個等待他人解決的狀態相當長一段時間。需要主動拆解成具體可行的下一步，幫他找到可以掌控的小範圍行動點，打破被動等待的迴圈。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4614, 'CSR_31', 'B (中)', 'CSR_20', 'C', '與 CSR_20 (希望) C聯動：表現為「恢復卡關又找不到下一步」。他受壓力後的韌性恢復仰賴外部支持與方向的釐清，而希望感薄弱、難以把動機與策略路徑連結的特質，使得「找到下一步」這件事本身就是他最難做到的事——恰好是他復原所需要的，卻正是他最缺乏的。逆境後的停滯因此可能相當明顯：他知道要往前，但不知道怎麼走，也很難自行找到替代路徑。需要他人主動提供方向與具體下一步，而不只是給予情感支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4615, 'CSR_31', 'B (中)', 'CSR_06', 'A', '與 CSR_06 (承諾) A聯動：表現為「壓力後靠承諾感撐住」。他的韌性需要時間和支持才能充分發揮，而他同時有著強烈且不受環境條件影響的承諾感，這是他逆境中最穩定的內在錨——即使狀態受損，他仍然知道「為什麼要繼續」，恢復不至於中途放棄。他在逆境中有明顯影響、但較少完全脫軌，只要條件改善便能較快接回。建議在他陷入壓力時幫助他重新連結到核心目標與意義，讓承諾感成為加速韌性恢復的觸媒。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4616, 'CSR_31', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「情境下傾向等待他人解決」。韌性受壓後需要方向與支持才能逐步回穩，而面對問題較易歸因外部、補救行動相對被動的特質，使得恢復過程的主動性大打折扣——他等待環境好轉，而不是去推動它好轉。結果是逆境後停滯時間拉長，且需要他人先採取行動，他才會跟進。管理上需要明確拆分責任範圍，並在逆境後主動指定他能做的第一個補救步驟，幫助他從「等待」切換到「行動」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4617, 'CSR_31', 'C (低)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「逆境中內外資源俱耗者」。他面對困難時用來緩衝的內在韌性資源偏少；在長期高壓或連續變動下，能量耗竭又更加削弱可動用的儲備，形成恢復所需資源與消耗速度之間的嚴重落差。具體情境裡，他在逆境持續一段時間後補救能力明顯減弱，表現波動難以自主控制。管理上宜提前識別壓力累積訊號，在他完全耗竭前主動介入減壓，而非等待他自己恢復。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4618, 'CSR_31', 'C (低)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「消耗下動能逐步退守者」。他的成就動機本就傾向維持在合理完成的水位，追求額外突破的意願不強；在長期高壓下能量耗竭讓他更難維持投入，行動範圍縮窄到把眼前任務交出去就好。具體情境裡，他在逆境後仍能完成基本工作，但若環境持續加壓而沒有明確支持，他的輸出會逐步收縮至最低可交付狀態。管理上宜在逆境期提供具體的環境支持與回饋，而非依賴他的內在動機自行撐過去。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4619, 'CSR_31', 'C (低)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「耗竭中焦慮感持續升高者」。他對不確定或模糊局勢反應強烈，無論程度輕重都容易產生持續焦慮；在長期高壓中能量耗竭讓他更難吸收不確定帶來的衝擊，焦慮反應反而在資源最薄弱的時候最為明顯。具體情境裡，他在逆境期對任何尚未明確的環節都會過度確認，消耗額外精力，實際恢復的速度比預期慢。管理上宜在逆境期主動降低不確定訊息量，先穩住已知再逐步釐清待定事項，給他恢復所需的確定感。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4620, 'CSR_31', 'C (低)', 'CSR_33', 'C', '與 CSR_33 (自律性) C聯動：表現為「消耗後更易被立即誘因牽走者」。他較容易被短期誘惑牽動，為長期目標延遲滿足本就需要努力；在長期高壓中耗竭讓自律的維持更加吃力，逆境後恢復期的計畫性推進往往會被立即有回報的事物分散。具體情境裡，他在壓力後的恢復過程中補救動作容易不連貫，需要外部提醒才能維持方向。管理上宜在他的恢復期提供具體且短周期的里程碑，而非只交付一個長期目標讓他自行規劃節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4621, 'CSR_31', 'C (低)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「耗竭後衝突閾值下降者」。他面對紛爭傾向直接表達立場，較少選擇退讓；在長期高壓下能量耗竭讓他的忍受度更薄，遇到衝突時爭辯或對抗性反應的閾值明顯降低。具體情境裡，他在逆境期的恢復本就吃力，此時若再碰到人際摩擦，對立行為容易出現，讓他在最需要他人協助的時候反而製造距離。管理上宜在逆境期減少強迫衝突的情境，讓他有空間先恢復，而非在消耗期強求配合或退讓。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4622, 'CSR_31', 'C (低)', 'CSR_36', 'B', '與 CSR_36 (職場忠誠度) B聯動：表現為「消耗中依附意願提前評估者」。他在環境正向且契合期望時能展現投入與承諾；但在長期高壓下能量耗竭讓他更難維持原有的恢復節奏，而此時環境若未能提供足夠正向回饋，他重新評估留守意願的時間點會比多數人早。具體情境裡，他在逆境期的表現可能仍維持基本輸出，但心理上已在進行得失計算。管理上宜在逆境期主動確認他的核心需求是否被看見，而非等他明顯撤退才介入。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4623, 'CSR_31', 'C (低)', 'CSR_05', 'C', '與 CSR_05 (挑戰) C聯動：表現為「高壓加上不適應變化的雙重負荷」。他在長期高壓或連續變動下能量快速耗竭，而描述中明確指出「連續變動」是最容易觸發其耗損的情境；他同時對變化與未知感到不適、較少把變動視為成長機會，於是變動頻繁的環境成為對他傷害最大的工作型態。每一次環境要求適應對他都是額外的能量支出，而不是被正常吸收的常態。建議盡量為他提供結構穩定的任務環境，若必須面對頻繁調整，需要搭配明確的過渡說明與支持資源，降低每次變化的衝擊成本。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4624, 'CSR_31', 'C (低)', 'CSR_08', 'B', '與 CSR_08 (盡責) B聯動：表現為「壓力下節奏崩散的執行者」。他在目標與節奏清楚時能穩定輸出，但遇到優先序頻繁變動或責任邊界不清時效率容易波動；在長期高壓下能量耗竭讓他更難在模糊情境中自主整頓節奏，恢復所需的條件比平時更嚴苛。具體情境裡，他在逆境期若環境條件又不清晰，表現波動會比單純疲憊時更明顯。管理上宜在逆境期主動提供清晰的優先序與責任範圍，降低他需要自行判斷的不確定量，給恢復創造基礎條件。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4625, 'CSR_32', 'A (高)', 'CSR_12', 'C', '與 CSR_12 (目標效能感) C聯動：表現為「感覺有把握卻缺少動力」。他對自身能力的感受是正向的——面對任務不會在起點懷疑自己——但對「努力是否能換來想要的結果」缺乏把握，使他在推進過程中容易猶豫或依賴他人確認；兩種信心的方向不同，前者朝向「我能做到」，後者朝向「做了會有用」。建議在分派任務時不只說明「你可以做」，更要清楚描述成功的具體樣貌與進展指標，才能持續撐起推進動能。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4626, 'CSR_32', 'A (高)', 'CSR_09', 'C', '與 CSR_09 (自控力) C聯動：表現為「自信但感到無力掌控」。他對自己能做好的事有信心，願意承擔個人執行責任，但他較少相信自己的行動能影響更廣的環境或推動他人。他在個人執行端表現可靠，但在需要影響系統、倡議改變或推動跨部門協作的場景顯著變弱。適合指派明確個人責任邊界的任務，協作型或推動型角色則需要主動為他建立「行動有影響力」的具體回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4627, 'CSR_32', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「強信心但低度容忍模糊」。他對自身能力自信、面對挑戰不逃跑，但同時對模糊與未知有強烈負面反應；這兩者疊合的典型表現是「積極要求釐清」——不是因為不敢，而是因為不確定本身讓他不舒服，所以他用快速定義問題來消除焦慮。在高度結構化或需快速落地的任務中這是優勢；在需要長期探索或容忍開放性的場景，他的釐清節奏可能過快，使問題空間過早關閉。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4628, 'CSR_32', 'A (高)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「信心在逆境中快速消蝕」。他在順境時表現自信、敢於承擔，但堅毅性由承諾、控制與挑戰三種內在資源組成，他在三面都相對薄弱，等於缺少在逆境下撐住信心的緩衝層；當壓力持續或失敗密集出現時，自信瓦解的速度比外人預期的更快。管理上應避免對他投入大量連續高壓任務而不給喘息，初期信心充沛不代表抗耗竭能力同等強健。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4629, 'CSR_32', 'A (高)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「敢做不敢負責」。他對自身能力有信心、起步不退縮，但面對失誤或未達成結果時較容易往外部歸因，補救動作相對被動；信心讓他承擔了責任，但內在「把事情做好是我的事」的決心相對薄弱，使得出錯後的修正學習不紮實。建議在任務結束後明確設計回顧環節，讓他練習主動追根究柢而非停在「外部條件不利」的解釋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4630, 'CSR_32', 'A (高)', 'CSR_25', 'C', '與 CSR_25 (樂觀) C聯動：表現為「信心充足但解讀悲觀」。他對自身能力的評估是正向的——覺得自己有能力、有效率——但他對情境結果的解讀傾向悲觀，把不如意視為長期且普遍。他能開始，卻容易在途中阻礙出現時，預期又一次失敗而提早收力。管理上建議在遇阻時主動提供「暫時性」解讀框架，幫助他區分「這次條件特殊」與「事情普遍不會好轉」，延長他的堅持窗口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4631, 'CSR_32', 'B (中)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「企圖心強但需要確認的進取者」。他對表現和成果有明確的企圖心，遇到挑戰傾向想把方法和目標往上推；不過在新領域或責任較重的情境，他對自己是否有能力做到這個更高標準仍有不確定，會在全力投入前希望先確認方向或獲得支持。在熟悉或有回饋的環境，他的動能和承擔意願很清楚；進入高風險任務或責任邊界模糊時，他的行動幅度容易收窄。管理上宜在任務初期給予清楚的確認，讓他把進取的意願轉化成實際的推進力。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4632, 'CSR_32', 'B (中)', 'CSR_22', 'C', '與 CSR_22 (無法忍受不確定性) C聯動：表現為「確認需求低，推進順暢」。他的自我勝任感在情境敏感時雖需要外部確認，但他同時對模糊與未知有高容忍，較少因為「還不確定」就停下——面對模糊能維持穩定，不易因缺乏明確資訊而焦慮，確認需求的觸發閾值實際偏高。他在不確定環境中推進節奏比預期流暢，但要注意的是，從容不一定等於方向正確；建議在重要決策節點仍安排確認機制，避免他在錯誤方向上走太遠才被發現。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4633, 'CSR_32', 'B (中)', 'CSR_31', 'C', '與 CSR_31 (韌性) C聯動：表現為「受挫後信心難以回穩」。自我勝任感在情境中等程度下能穩定輸出，但韌性偏弱讓他在壓力或失敗後能量耗損快、恢復費時；而恢復緩慢又進一步壓低原本就需要外部支撐的勝任信心，形成「受挫→難以回穩→更需要確認→等待時間拉長」的循環。管理上，對此類型的人在高壓任務後應主動提供情感確認與方向確認，而非等他自己說需要支持。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4634, 'CSR_32', 'B (中)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「信任他人讓確認需求易被滿足」。他在新領域或高風險任務需要外部確認才能穩定推進，而對他人的高度信任讓這個求確認的動作自然流暢——他不擔心被評判，也預設對方的反饋是善意的。兩者疊合讓確認循環容易完成，但高信任同時也讓他對反饋品質缺少辨別，可能在接受了不夠精準的確認後就全速投入；建議引導他建立簡單的確認品質評估習慣，不只問「可以嗎」，也問「怎麼知道可以」。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4635, 'CSR_32', 'B (中)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「多重支撐皆不足，推進明顯困難」。自我勝任感在新領域或高風險任務已需要外部確認才能穩定，而心理資本由希望、效能感、韌性、樂觀四種資源組成，四面同步偏弱等於裡裡外外的推進支撐都不到位；確認需求的觸發頻率更高、等待確認的時間更長，且單次確認的撐持時間也相對短。管理上這是需要持續主動支持而非一次性指導的類型，建議安排短週期的進度確認節奏，而非讓他在長時間缺乏回饋下自行推進。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4636, 'CSR_32', 'B (中)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「確認需求遇強硬衝突容易僵局」。在新領域或高風險任務，他需要外部確認才能穩定推進；而他面對意見分歧時，又傾向直接表達立場、較少選擇退讓。他既需要他人的認可，又不傾向為取得認可而讓步，在分歧情境下容易陷入僵局。建議在有重大分歧的任務啟動前先獨立完成框架對齊，降低確認需求與對抗性互動同時觸發的機率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4637, 'CSR_32', 'C (低)', 'CSR_01', 'C', '與 CSR_01 (成就動機) C聯動：表現為「信心與動力雙雙薄弱」。他對能否做好缺乏把握，遇到挑戰容易遲疑；他同時成就動機偏弱，傾向把工作完成在合理範圍而不追求更高難度。他傾向待在「夠用」的安全地帶，不確定自己做得到的同時也不特別想嘗試——在需要主動超越、自發升級的環境中難以成長。建議給他設計清楚的小步驟成功路徑，透過累積具體的「做到了」來逐步抬升信心基準，而非期待他自發突破。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4638, 'CSR_32', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「行動意志撐過信心不足」。他對自身能力有所懷疑，容易在不確定任務前遲疑，但相信行動能影響結果的信念讓他即使不確定也傾向主動採取行動；「先動」的傾向補貼了「能做嗎」的懷疑，讓他的行動啟動障礙比純低信心者低。這個組合的潛力在於，透過行動累積的具體成果可以逐步修復信心，建議管理上不只給安全感、也給他「你的行動確實產生了這些影響」的具體可見回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4639, 'CSR_32', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動精神抵銷信心不足」。他對自身能力有所懷疑，遇到不確定任務容易遲疑，但自發超越既定要求的主動精神穩定且不依賴外部驅動，讓他在察覺需求時仍會動身發起行動；主動精神在前半段抵銷了信心不足的阻力，但進入任務後的懷疑往往在途中浮現。這是比「低信心＋被動」好得多的組合，管理上重點是在他主動發起後的推進中段，安排一次適時的確認與肯定，幫助他跨越自我懷疑的高峰區。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4640, 'CSR_32', 'C (低)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「逆境中仍能撐住的低信心者」。他容易懷疑自己是否能做好，需要更多安全感才敢推進，但堅毅性由承諾、控制、挑戰三種內在資源充分組成，讓他在逆境中不至於崩潰放棄——即使信心不足，在壓力與失敗下的韌性反而比外人預期的強。這是「信心薄弱但耐力強」的組合，管理上不用特別擔心他在逆境中棄場，真正需要關注的是在一般任務的起點給他足夠的安全感，讓他願意啟動。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4641, 'CSR_32', 'C (低)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「懷疑自己又不信任他人」。他容易懷疑自己是否能做好，需要安全感才敢推進；但同時對他人高度警戒、預設意圖可能不利，讓求助或求確認的動作充滿心理障礙；他需要外部支撐，卻很難真的開口或接受支援。這是孤立風險最高的組合之一——低信心與低信任同時存在，使他在困難中趨於沉默而非求援。管理上不宜等他主動說出需求，應主動、定期且低評判地建立接觸機會，讓他逐步累積「這個人是安全的」的感受。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4642, 'CSR_32', 'C (低)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「需要被看見卻不敢展現」。他容易懷疑自己是否夠好，需要更多安全感才敢推進；他同時渴望被看見並強調自身貢獻，把被認可視為重要需求。他的低信心讓他在未確定成果前退縮，凸顯需求又讓他在他人受到認可時倍感焦慮。管理上建議主動提供肯定——不等他展現才給，而是主動點出他的具體貢獻；這能同時滿足他的被見需求與降低他的信心焦慮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4643, 'CSR_33', 'A (高)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「克制誘惑卻難以持續投入」。他能維持計畫紀律、不輕易因舒適誘惑轉向，但同時對活動快速失去投入感、厭倦在各類情境中頻繁出現——自律讓他堅持在任務上，厭倦卻讓能量持續外漏。這種組合的外部表現是「有交付」，但深度參與與創意投入卻悄悄減損。建議設計節點式刺激或任務輪換，讓紀律有值得守護的新鮮目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4644, 'CSR_33', 'A (高)', 'CSR_26', 'A', '與 CSR_26 (條理性) A聯動：表現為「系統化的自律執行者」。他偏好用清楚的流程與例行節奏來組織工作，把資訊分類、把任務排進時程，在結構中維持一致做法；他同時能延遲即時滿足、不輕易讓短期誘惑打亂計畫，在有程序支撐的環境裡執行節奏格外穩定。具體情境裡，他常一邊把新任務快速歸進既有的流程框架，一邊在執行中段遇到分心誘惑時回頭確認時程、把自己拉回計畫節奏。實務上他在有明確程序規範的工作中最可靠，若環境需要大量臨場彈性或缺乏結構支撐，自律節奏仍能維持，但速度可能放慢；管理上宜給他清楚的流程框架與進度回饋，讓他的結構偏好得到發揮空間。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4645, 'CSR_33', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮驅動的嚴格自律者」。他面對模糊與未知容易產生強烈負面反應，同時具備高度的自我約束能力——自律在此不只是價值觀，也是對抗不確定感的策略。計畫執行上非常穩定，但在目標模糊或環境快速變動時，紀律可能轉為僵化而非適應性調整。管理上應確保任務框架清晰，並為不可避免的變動提前溝通，減少焦慮對決策品質的影響。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4646, 'CSR_33', 'A (高)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「自律強但規範感低」。他能為長期目標抗拒誘惑、維持個人節奏，但對承諾、規則與責任邊界的重視程度較低——容易把規範視為可調整的工具，在目標壓力下可能選擇結果導向做法。自律管的是個人計畫的執行，義務感管的是對他人與系統的承諾；兩者分離，前者強不補後者缺。在合規要求高的環境中，需額外設計問責機制而非依賴他的自律性。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4647, 'CSR_33', 'A (高)', 'CSR_29', 'C', '與 CSR_29 (主動精神) C聯動：表現為「紀律守成卻被動等待」。他能為長期目標延遲滿足、維持任務節奏，但在未被明確要求時很少主動發起行動或超越既有範圍——自律的能量集中在守住現有框架，而非主動開創。這種組合在需要穩定執行的崗位是資產，但在需要自驅成長或創新的角色中容易停滯。管理建議：明確指出期待的主動範圍，並設計觸發機制讓主動行動有明確回饋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4648, 'CSR_33', 'A (高)', 'CSR_10', 'C', '與 CSR_10 (審慎) C聯動：表現為「守紀律卻快速行動」。他能抗拒短期誘惑、維持計畫節奏，同時傾向先做再調整、評估常在行動後補上——自律提供了執行穩定性，但審慎不足讓這份穩定性中混入未被評估的隱性風險。在快速節奏下的衝刺能力強，但積累的小錯與返工風險相對較高。建議在關鍵節點設計強制暫停的評估時間，讓紀律與思考品質同步。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4649, 'CSR_33', 'B (中)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「環境一鬆就失守的節奏者」。其自律在目標清楚或環境有回饋時能維持，但當環境干擾或缺乏回饋時容易鬆動；而厭倦傾向高使他在任何情境中都難以長時間維持投入感——兩個條件缺失的方向不同，卻常在同一情境中同時觸發。拖延與注意力轉移是主要風險信號，建議維持短週期可見的進展回饋與任務新鮮度。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4650, 'CSR_33', 'B (中)', 'CSR_21', 'A', '與 CSR_21 (衝動管理) A聯動：表現為「壓力下的穩定自控者」。其自律在目標清楚時穩定、在干擾大時容易鬆動，但穩定的衝動管理能力確保他不因情緒衝動而在壓力節點大幅失守——兩者組合讓自律鬆動的方式是「漸緩」而非「爆炸」。建議善用這個穩定底線，在目標變模糊的階段提供清楚方向，避免情境依賴性自律長期處於低回饋狀態。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4651, 'CSR_33', 'B (中)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「焦慮中的條件式自律」。其自律在目標清楚時穩定，但在干擾或缺乏回饋時容易鬆動；面對模糊或未知情境又容易產生強烈焦慮——不確定性同時觸發焦慮與削弱自律支撐，兩者同步浮現。建議在目標不確定的過渡期主動提供中繼訊息，降低焦慮消耗，保留更多資源維持自律節奏。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4652, 'CSR_33', 'B (中)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動開創但節奏不穩」。他能自發開啟行動、超越既有要求，但自律在目標模糊或環境干擾時容易出現鬆動——主動性確保了起跑強勢，但執行中的節奏持續性仍受情境影響。對需要長期推進的自發計畫，建議設計明確的里程碑回饋，讓主動精神有錨點、讓自律有依附的清楚目標。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4653, 'CSR_33', 'B (中)', 'CSR_18', 'C', '與 CSR_18 (堅毅性) C聯動：表現為「韌性薄弱下的節奏崩塌」。其自律在環境支持良好時能維持，在壓力或逆境中容易鬆動；而堅毅性薄弱讓他面對逆境時內在資源本就有限——逆境同時衝擊堅毅韌性與自律節奏，形成雙向惡化。堅毅性由承諾、控制、挑戰三種內在資源組成，在此三者都薄弱的情況下，自律鬆動既無韌性緩衝、也無控制感支撐。高壓期間需要主動的外部支持與資源補充。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4654, 'CSR_33', 'C (低)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「雙向衝動的決策風險者」。他容易在當下選擇立即回報，同時在情緒高漲或衝突時被情緒推著走——自律薄弱和衝動管理薄弱雖然機制不同，但同時出現使幾乎所有自我調控路徑都缺位。倉促承諾、計畫崩解、衝動回應是主要風險信號，對人際信任與任務可靠度都形成持續的負面壓力。需要同時設計享樂誘惑的移除機制與情緒觸發的緩衝節點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4655, 'CSR_33', 'C (低)', 'CSR_01', 'A', '與 CSR_01 (成就動機) A聯動：表現為「高企圖卻難以持守計畫」。他對表現與成果有明顯企圖心、願意追求更高標準，但同時容易被短期誘惑牽動、自律維持吃力——明知長期目標重要，仍在當下選擇立即回報。這種組合的外部表現是起跑積極、中途失速：啟動新目標時高能量，長期堅持上容易出現空窗。建議設計短週期的目標達成節點，把長期企圖心切割成能被立即回報滿足的小段，減少自律的消耗負擔。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4656, 'CSR_33', 'C (低)', 'CSR_26', 'C', '與 CSR_26 (條理性) C聯動：表現為「結構鬆散加速失控」。他較容易被短期誘惑牽動、自律維持吃力，同時不靠固定流程工作、容易臨場處理、出現紀錄不足與遺漏細節——條理性的薄弱讓外部結構缺席，自律薄弱讓意志力也無法補位。兩者同時缺席在複雜或長期任務中會明顯放大失控風險。建議優先建立外部工具支撐（清單、提醒、流程模板），降低對意志力的依賴。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4657, 'CSR_33', 'C (低)', 'CSR_10', 'A', '與 CSR_10 (審慎) A聯動：表現為「審慎評估後仍屈服誘惑」。他行動前會評估風險與後果、在不確定情境也能維持判斷品質，但同時容易被短期誘惑牽動、明知長期重要仍在當下選擇立即回報——認知上清楚長期選擇，行動上卻持續妥協。這是「知行落差」最清楚的組合之一：評估能力不是短板，意志力才是。建議減少即時誘惑出現的環境設計，而非依賴加強自我評估。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4658, 'CSR_33', 'C (低)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「守規範卻守不住計畫」。他高度重視承諾、規則與責任邊界，在灰色地帶也傾向選擇可被信任的做法；但同時容易被短期誘惑牽動、個人計畫維持吃力。義務感確保了對他人承諾與系統規範的遵守，自律薄弱卻讓個人長期目標的執行持續漏失——是對外可靠但對自身成長計畫執行不穩的輪廓。建議把個人目標以正式承諾或問責框架表達，借助義務感的強度驅動自我計畫的持守。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4659, 'CSR_33', 'C (低)', 'CSR_04', 'A', '與 CSR_04 (厭倦傾向) A聯動：表現為「誘惑加厭倦的雙重失守」。他容易被短期誘惑牽動，同時在各類情境中快速失去投入感——即時誘惑從外部拉走注意力，厭倦感從內部瓦解持續投入的意願。兩者雖機制不同，但結果都是縮短對長期計畫的堅持時間。這是需要最積極環境設計的組合之一：減少可見誘惑、增加任務新鮮感與短週期成就回饋，才能延長有效執行窗口。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4660, 'CSR_33', 'C (低)', 'CSR_18', 'A', '與 CSR_18 (堅毅性) A聯動：表現為「韌性充沛卻難守計畫」。他在逆境與壓力中具備充沛的內在資源——由承諾、控制、挑戰三種資源組成的韌性讓他不易被困難打垮；但同時容易被短期誘惑牽動、日常計畫節奏維持吃力。堅毅性在逆境中發光，自律薄弱在輕鬆環境中洩漏——弱點恰好藏在最不需要韌性的「日常執行」裡。建議把長期目標轉化為有適度挑戰感的任務框架，讓韌性資源能持續被啟動、同時為自律提供結構錨點。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4661, 'CSR_34', 'A (高)', 'CSR_02', 'C', '與 CSR_02 (親和性) C聯動：表現為「坦白卻帶著距離的人」。他不會為了目的去操縱或欺騙，講話直接、用真實資訊跟人往來；但他在人際上本來就傾向保持距離、對合作需求容易先起戒心。於是他給人的感覺很特別——說出口的每句話都可信，卻不熱絡、不主動靠近，誠意藏在冷淡的外殼裡。別人常因為他的疏離而錯估他的善意，以為他在防備或不感興趣，其實他只是不擅長也不傾向用熱情包裝自己。管理上可借重他話語的可靠度，但別期待他用親和力去黏合關係。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4662, 'CSR_34', 'A (高)', 'CSR_14', 'A', '與 CSR_14 (公正性) A聯動：表現為「不操弄也不取巧的正直者」。對他來說，『不為達標而操縱別人』和『不為領先而欺騙或佔人便宜』其實是同一種底線的兩個面：他既不會在溝通上耍話術，也不會在競爭裡走偷吃步。這讓他的可信度有一種少見的完整——不只說話算數，連手段的乾淨度也守得住，在需要高度信任的場合（敏感資訊、利益分配）特別站得住腳。要留意的是，這樣的人通常不擅長『必要的策略性包裝』，在講究手腕的環境裡可能顯得過於剛直，需要旁人補位。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4663, 'CSR_34', 'A (高)', 'CSR_07', 'C', '與 CSR_07 (法規遵從) C聯動：表現為「有話直說、寸步不讓的直言者」。他不用話術包裝意見，想到什麼就講什麼；而面對紛爭時他又傾向直接表態、爭辯而非退讓。兩者合起來，是一個近乎沒有緩衝層的人——既不繞彎也不迎合，意見差異會被他用最原始的方式攤在桌上。這種人坦率、立場清楚，效率高，但張力也高：他很少替對方留台階，衝突容易迅速升溫。在需要協商或共識的場合，最好替他預設一個結構化的討論框架，把他的直接導向議題本身，而不是演變成情緒對撞。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4664, 'CSR_34', 'A (高)', 'CSR_11', 'A', '與 CSR_11 (義務感) A聯動：表現為「誠信守規的可靠者」。他較少為了達成目標去操縱或欺騙他人，溝通偏直接透明；對承諾、規則與責任邊界也高度重視，遇到灰色地帶傾向選擇可被交代、可被信任的做法。在實際工作裡，他給出的資訊和承諾都有相當的一致性，不容易出現說一套做一套的落差。周遭需要靠他協調資訊或確認事項時，他的回應有基準可依；若環境對透明度與義務感的要求降低，他反而容易感到不自在。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4665, 'CSR_34', 'A (高)', 'CSR_21', 'C', '與 CSR_21 (衝動管理) C聯動：表現為「透明說話卻難防衝動失控」。他傾向直接透明表達而不操弄，但較弱的衝動管理使得這種直率在高壓或衝突情境中容易以過激方式呈現——說的是真話，但語氣、時機或強度超標，事後常需修補。透明度本身不是問題，問題在於真實反應未經過濾就輸出；建議給予高壓情境前的冷卻機制或事前框架，幫助他維持直接而不失控的溝通方式。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4666, 'CSR_34', 'A (高)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「真誠善信的互動者」。他以善意預設對方意圖，互動中習慣把真實資訊與立場直接說清楚，不刻意保留或包裝；即使面對陌生人或不確定情境，這份開放態度也不太縮手。在合作場合，他給出的資訊和他相信對方給出的資訊都不帶太多策略性過濾，讓溝通的往返相當直接。潛在風險在於他雙向開放的態度有時讓他在資訊不對稱的情境容易吃虧；管理上宜協助他保持識別風險的判斷，而不過度削弱他的開放傾向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4667, 'CSR_34', 'A (高)', 'CSR_22', 'A', '與 CSR_22 (無法忍受不確定性) A聯動：表現為「透明焦慮的確認者」。他對不確定情境有強烈的負面反應，模糊的局面很快轉化為持續焦慮，讓他需要頻繁確認與追問才能安心；在溝通上，他傾向把自己知道的直接說出來，較少包裝或保留，但這份透明度有時是焦慮驅動的，急著釐清勝過策略考量。在資訊明確的環境他最穩定，一旦進入灰色地帶，他的頻繁確認行為可能讓周遭感到壓力。管理上宜主動提供清楚的資訊與時間框架，讓他的透明溝通傾向在穩定的底色下更有效率。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4668, 'CSR_34', 'A (高)', 'CSR_08', 'A', '與 CSR_08 (盡責) A聯動：表現為「誠懇高效的可靠執行者」。他以真實資訊建立合作、不走話術捷徑，同時具備一致的自我要求與主動收尾能力；這使他的「承諾」有著少見的完整性——說了就做、做了就交代，而非為目標調整說詞。對需要高度授權或長期委任的任務，此組合可以快速建立可信賴基礎；他的盡責涵蓋盡職、審慎、自律等多重面向，加上誠懇，於是他在多個維度同時展現可靠。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4669, 'CSR_34', 'B (中)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「策略拿捏的手段者」。他平時溝通保持一定的誠懇底線，但在競爭或壓力情境下，對說話方式和達成方式的底線都會鬆動：可能用較策略性的表達保護立場，也可能合理化不公平手段或利用他人換取優勢。遇到利益衝突，他對「怎麼有利就怎麼做」的容忍度比平時高，而這兩個方向的鬆動往往同時出現。管理上需要清楚設定誠信與公平的底線，並在競爭壓力升高時主動確認他的做法是否仍在界內。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4670, 'CSR_34', 'B (中)', 'CSR_24', 'C', '與 CSR_24 (謙虛) C聯動：表現為「自我凸顯的策略者」。他較傾向強調自身貢獻與地位，對被看見有較高的需求；在溝通上，他不總是把完整資訊攤開，而是會評估哪種呈現方式最能彰顯自己的角色，用較策略性的表達保護立場。具體情境裡，他一邊在意誰拿到功勞，一邊用話術或選擇性揭露讓自己的貢獻最大化。管理上宜讓成果歸屬透明，並要求資訊完整度，避免他的自我凸顯需求推動資訊管控行為。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4671, 'CSR_34', 'B (中)', 'CSR_35', 'C', '與 CSR_35 (信任) C聯動：表現為「警戒試水的策略者」。他對他人意圖保持高度警戒，互動中傾向多保留少給出；在溝通策略上，他多數時候能保持一定的誠懇，但在競爭或政治情境中，對話術與選擇性揭露的抗拒感下降。兩個方向的保留疊在一起——對外界不太信任，對自己說出去的話也習慣過一道策略篩選——讓旁人感受到他是一個在資訊上很難讀透的人。管理上宜建立可預期的信任環境，降低他的防護本能，讓他有更多空間選擇直接表達。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4672, 'CSR_34', 'B (中)', 'CSR_03', 'A', '與 CSR_03 (利他行為) A聯動：表現為「真誠付出的協作者」。他對他人需求有真實的回應意願，無私與體貼是他穩定的互動底色，面對高度個人犧牲的需求也較少退縮；在溝通上，他多數時候傾向直接說清楚而非用話術鋪陳。在一般合作情境，他的付出與說話方式都帶著清楚的誠意，讓周遭容易建立信任；只有在競爭或壓力升高時，他才可能用較策略性的表達方式調整立場。管理上他在開放協作的環境最有動能，需要防範高壓情境引發他少見的包裝溝通傾向。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4673, 'CSR_34', 'B (中)', 'CSR_28', 'C', '與 CSR_28 (個人責任感) C聯動：表現為「歸因外移的策略者」。他遇到失誤或延誤，較容易把責任歸因外部，補救動作相對被動，學習與改進的速度因此受限；在溝通上，他在競爭或壓力情境中傾向用策略性的表達方式保護立場，對完整揭露的執著也偏低。兩個方向疊在一起，讓他在出了問題時，不只慢於承擔，也可能主動管控旁人看到的資訊版本。管理上需要建立清楚的責任歸屬機制，並要求資訊完整度，避免問題在策略性表達與責任外移的組合下被稀釋。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4674, 'CSR_34', 'B (中)', 'CSR_30', 'C', '與 CSR_30 (心理資本) C聯動：表現為「動能不足的策略者」。他內在的希望、效能、韌性與樂觀資源偏弱，遇到挫折時動能下降較明顯，對未來期待感也相對薄弱；在溝通上，他不總是完全透明，在壓力下會用較策略性的表達方式因應，但整體狀態的動能不足，讓這種操作也難以持久或積極。旁人感受到的是一個在困難面前容易失去推進力，同時溝通上又不完全開放的人。管理上需要主動補給他的心理資源，讓他先恢復基本動能，再建立溝通透明度的期待。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4675, 'CSR_34', 'C (低)', 'CSR_02', 'A', '與 CSR_02 (親和性) A聯動：表現為「熱情開放的目的者」。他在各類人際情境中能自然展現信任與合作意願，面對陌生或不確定的互動也不縮手，熱情是他真實的底色；然而在推進目標時，他對包裝資訊或用話術影響他人判斷的抗拒感較低，把這些操作視為正常工具。他的熱情讓旁人容易對他建立信任，但他給出的資訊未必完整。管理上需要主動測試他的資訊透明度，不能只靠他表現出來的親和感就推斷他的溝通是完全開放的。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4676, 'CSR_34', 'C (低)', 'CSR_14', 'C', '與 CSR_14 (公正性) C聯動：表現為「目標至上、毫無手段顧忌的人」。對他來說，包裝、操弄是達成目標的工具，而把『領先』放在公平之上、合理化不公平手段也是同一種思路——兩者其實是同一個價值排序的不同出口：目標最大，手段視情況挑。問題在於這個人內在缺乏任何一道會互相制衡的煞車：誠懇這側不踩剎車，公平那側也不踩，於是在目標壓力下他的道德邊界會整片快速模糊，而不是被任何一個面向拉住。對外部觀察者而言，他的實際行為與表面說法之間的落差最難察覺。管理上不能仰賴他的自我報告，而要引入獨立的行為審計，用客觀記錄去補上他自己不會設的那道界線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4677, 'CSR_34', 'C (低)', 'CSR_11', 'C', '與 CSR_11 (義務感) C聯動：表現為「為結果連規則一起放掉的人」。他把包裝、操弄當成達標的工具，也把規範看成可以隨情況調整的東西——這兩者其實是同一種『結果優先』的人格在不同層面的表現:對人，他選擇性地說;對規則,他彈性地用。關鍵是他內在對『誠信』和『規矩』都缺乏強烈的約束力,所以一旦外部壓力升高,他這兩條線會一起往下掉,而不會其中一條把另一條拉住。這種人在需要清廉與合規的場景風險極高,因為他沒有可依賴的內在自律。管理上只能靠外部:把規則紅線設死、把行為定期攤在陽光下,用制度去做他自己不會做的那份約束。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4678, 'CSR_34', 'C (低)', 'CSR_35', 'A', '與 CSR_35 (信任) A聯動：表現為「輕信易被操控的對象」。他對他人的信任度高，以善意預設對方意圖已成為穩定傾向，面對資訊不對稱也不太收手；在自己的溝通與行事上，他則較容易把包裝或操弄當作達成目標的工具。這個組合在互動中形成明顯的不對稱：他開放地相信對方，對方卻未必得到他完整真實的資訊。管理上需要協助他建立識別風險的判斷，避免他的高信任傾向被他人利用；同時也需要為他設定溝通誠信的明確底線。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4679, 'CSR_34', 'C (低)', 'CSR_09', 'A', '與 CSR_09 (自控力) A聯動：表現為「主控包裝的局面者」。他相信自己能影響結果，無論情境可控程度如何，都持續採取主動行動，掌控感是他穩定的底層傾向；在這份主控意識延伸到溝通上，他傾向管控對外釋出的資訊版本，把選擇性揭露或話術視為主動掌握局面的工具。旁人感受到他是一個行動力強、有效率，但很難確定他說出來的是否為完整圖像的人。管理上需要主動建立資訊透明度的要求，讓他的高主控能量在誠信框架內發揮，而非轉向資訊管控。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4680, 'CSR_34', 'C (低)', 'CSR_29', 'A', '與 CSR_29 (主動精神) A聯動：表現為「主動出擊的話術者」。他在各類情境都能自發開啟行動並超越既定要求，缺乏支持或方向模糊也擋不住他的主動性；在這份驅動力之下，他對達成路徑的底線相對有彈性，可能把選擇性揭露或話術視為推進工具，主動用來影響他人判斷。旁人感受到的是一個行動力強、但很難確定他說出來的是不是全貌的人。管理上需要主動表彰他的真實貢獻，並對溝通完整度設定明確期待，讓他的主動精神在誠信框架內發揮。');
INSERT INTO trait_interactions (id, primary_trait_id, primary_band, trigger_trait_id, trigger_band, narrative) VALUES (4681, 'CSR_34', 'C (低)', 'CSR_17', 'C', '與 CSR_17 (溫和有禮) C聯動：表現為「直接嚴厲的操弄者」。他評價他人時傾向直接且嚴厲，批評性判斷較少加緩衝，面對對方反覆出錯也較難展現寬容；在自己的目標推進上，他則對包裝與選擇性揭露保持開放，願意用話術影響他人判斷。這兩個方向的組合讓他的互動感受相當複雜：他對別人的要求清楚直白，對自己的溝通卻帶著策略性管控。管理上需要同時處理他的嚴厲批評對團隊氣候的影響，以及他在資訊透明度上的彈性，兩者都需要明確的框架。');
